// STATE
// ============================================================
let DATA = null;
let watchlist = (() => { try { return JSON.parse(localStorage.getItem("set_wl") || "[]"); } catch { return []; } })();

// บันทึก watchlist ทั้ง localStorage (ทันที) และไฟล์ data/watchlist.json ฝั่งเซิร์ฟเวอร์
// (ให้ git push/pull พาไปเครื่องอื่นได้ — ดู /api/watchlist ใน app.py) merge แบบ union
// เท่านั้น ไม่มีการลบข้ามเครื่องอัตโนมัติ กันข้อมูลหายถ้าอีกเครื่องยังไม่ pull ล่าสุด
//
// ก่อน POST จะ GET ไฟล์ล่าสุดจากเซิร์ฟเวอร์มา union เข้ากับ list ปัจจุบันก่อนเสมอ (ไม่ใช่ POST
// ทับตรงๆ) กันเคสเปิด 2 เครื่องพร้อมกัน: เครื่อง A เพิ่มหุ้นแล้ว sync ขึ้นไฟล์ ก่อนที่เครื่อง B
// (ที่เปิดค้างไว้นานกว่า ยังไม่เห็นของ A) จะเพิ่มหุ้นอื่นแล้ว save ทับไฟล์ด้วย list เก่าที่ไม่มี
// ของ A อยู่ — พบจากรีวิวโค้ด 2026-08-24
function _wlSave() {
  localStorage.setItem("set_wl", JSON.stringify(watchlist));
  fetch('/api/watchlist').then(r => r.ok ? r.json() : Promise.reject())
    .then(serverList => {
      if (Array.isArray(serverList) && _wlMergeFromServer(watchlist, serverList)) {
        localStorage.setItem("set_wl", JSON.stringify(watchlist));
      }
    })
    .catch(() => {})
    .then(_wlPostSave);
}

function _wlPostSave() {
  fetch('/api/watchlist', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ symbols: watchlist }),
  }).then(r => {
    const note = document.getElementById('wl-sync-note');
    if (!note) return;
    if (r.ok) { note.textContent = ''; return; }
    // เกิน 500 ตัว (limit ฝั่ง backend — ดู save_watchlist ใน app.py) หรือ payload ผิดรูป —
    // localStorage เครื่องนี้ยังบันทึกได้ปกติ แต่ sync ข้ามเครื่องผ่าน data/watchlist.json
    // หยุดทำงานเงียบๆ ถ้าไม่แจ้ง (เดิม catch ทิ้งทั้งหมด ไม่มีใครรู้ — พบจากรีวิวโค้ด 2026-08-02)
    note.textContent = watchlist.length > 500
      ? `⚠ Watchlist เกิน 500 ตัว (มี ${watchlist.length}) — เกินลิมิต sync ข้ามเครื่อง บันทึกได้แค่ในเครื่องนี้`
      : '⚠ บันทึก Watchlist ไปเซิร์ฟเวอร์ไม่สำเร็จ — sync ข้ามเครื่องอาจไม่ทำงาน';
  }).catch(() => {
    const note = document.getElementById('wl-sync-note');
    if (note) note.textContent = '⚠ ติดต่อเซิร์ฟเวอร์ไม่ได้ — บันทึก Watchlist ได้แค่ในเครื่องนี้ (localStorage)';
  });
}

function _wlHasPrefix(s) {
  return s.startsWith("DR:") || s.startsWith("US:") || s.startsWith("HK:");
}
function _wlBaseSym(s) {
  return _wlHasPrefix(s) ? s.slice(3) : s;
}

// เช็คว่า list มี sym นี้ "อยู่แล้ว" ไม่ว่าจะอยู่ในรูป bare (ยังไม่ migrate) หรือ prefixed
// (migrate แล้ว) ก็ตาม — ใช้ตอน merge จาก server กัน entry ซ้ำเวลา migrate ในเครื่องนี้ (เช่น
// renderWatchlist เจอ "OKTA" ตรงกับ US Index/mirror เลยเปลี่ยนเป็น "US:OKTA") วิ่งชนกับจังหวะที่
// _wlSyncFromServer ยังถือ list เก่าที่มีแต่ "OKTA" bare อยู่ — merge ตรงตัวเดิมจะเห็นว่า "OKTA"
// ไม่อยู่ใน watchlist (มีแต่ "US:OKTA") แล้ว push "OKTA" กลับเข้ามาซ้ำ กลายเป็น 2 รายการ
// ไม่เทียบข้าม prefix ต่างชนิด (DR:META กับ US:META ยังนับเป็นคนละตัวเสมอ — คนละสินทรัพย์จริง)
function _wlListHas(list, sym) {
  if (list.includes(sym)) return true;
  if (!_wlHasPrefix(sym)) return list.some(w => _wlHasPrefix(w) && _wlBaseSym(w) === sym);
  return list.includes(_wlBaseSym(sym));
}

// union merge จาก serverList เข้า `local` (แก้ในที่) — ใช้ร่วมกันทั้ง _wlSave (ก่อน POST) และ
// _wlSyncFromServer (ตอนโหลดหน้า) กันโค้ดซ้ำ (เดิม copy-paste บรรทัดเดียวกัน 2 จุด — เหมือน
// _mergeAlertRatchet ที่ฝั่ง price alert แยกออกมาเป็น helper อยู่แล้ว รีวิวโค้ด 2026-09-02)
function _wlMergeFromServer(local, serverList) {
  let changed = false;
  serverList.forEach(s => { if (typeof s === 'string' && !_wlListHas(local, s)) { local.push(s); changed = true; } });
  return changed;
}

(function _wlSyncFromServer() {
  fetch('/api/watchlist').then(r => r.ok ? r.json() : Promise.reject()).then(serverList => {
    if (!Array.isArray(serverList)) return;
    const changed = _wlMergeFromServer(watchlist, serverList);
    if (changed) {
      localStorage.setItem("set_wl", JSON.stringify(watchlist));
      if (document.getElementById('page-watchlist')?.classList.contains('active')) renderWatchlist();
    }
    // เผื่อเครื่องนี้มีตัวใหม่ที่อีกเครื่องยังไม่มี ก็ sync กลับขึ้นไฟล์ด้วย
    if (watchlist.length && (changed || watchlist.length !== serverList.length)) _wlSave();
  }).catch(() => {});
})();
// dir: 1 = มาก→น้อย (descending, ค่าเริ่มต้น) · -1 = น้อย→มาก (ascending) — เหมือน _boSortDir/
// _momSortDir ของตาราง Breakout/Momentum (ดู renderBreakout/renderMomentum) เดิม dir เริ่มที่ -1
// ทำให้ตารางเรียงจากน้อยไปมากตั้งแต่เปิดหน้า (RS ต่ำสุดขึ้นก่อน) สวนทางกับลูกศร ↓ ที่โชว์อยู่
let stockSort = { key: "rs_score", dir: 1 };
let sectorSort = { key: "ret_1m", dir: 1 };
let rotView = "sector";
let rotTimeframe = 'short';  // 'long'=3M/1M, 'short'=1M/1W — default Short
let sectorView = "sector";
let industryFilter = "ALL";
let sectorFilter = "ALL";
let stageFilter = "ALL";
let stockSearch = "";
let dqOnlyFilter = false;
let stockRsMin = 0;
let stockEma200Only = false;
let _stocksView = 'all';
let _stocksMode = 'stocks';

// ============================================================
// STATIC MODE — รันบน GitHub Pages (ไม่มี Flask server)
// ข้อมูลทั้งหมดถูก precompute เป็นไฟล์ใน data/ โดย GitHub Actions
