const IS_STATIC = location.hostname.endsWith('github.io')
  || location.protocol === 'file:'
  || new URLSearchParams(location.search).has('static');

if (IS_STATIC) {
  document.addEventListener('DOMContentLoaded', () => {
    document.body.classList.add('static-mode');
    _patchPosStreakForStatic();
  });

  // เว็บมือถือ/ไอแพดไม่มี Finnomena รายไตรมาส (financials.db เต็มเป็น local-only) —
  // ช่อง "เป็นบวกติดกัน" ทั้ง 4 + checkbox OCF>กำไรสุทธิ จึงคำนวณจากงบ Yahoo "รายปี"
  // แทน (เหมือนกับที่ backend สลับไปใช้ payload รายปีตอน yahoo_only=True ใน
  // _compute_fin_analytics_for) — ต้องแก้ label/placeholder/tooltip ให้ตรงหน่วยจริง
  // ไม่งั้นผู้ใช้จะเข้าใจผิดว่ายังนับเป็นไตรมาสอยู่
  function _patchPosStreakForStatic() {
    const FIELDS = {
      'scr-rev-posstreak-min': {
        label: 'รายได้เป็นบวกติดกัน ≥ (ปี) *', placeholder: 'เช่น 3',
        tip: `<strong>รายได้เป็นบวกต่อเนื่อง</strong><br>
          จำนวนปีติดกัน (จากปีล่าสุดย้อนหลัง) ที่รายได้ &gt; 0 — ต่างจาก "รายได้โตติดกัน" ที่ต้องมากกว่าปีก่อนทุกครั้ง ตัวนี้แค่เช็คว่าเป็นบวก ไม่สนว่าโตหรือหด<br><br>
          เช่น ใส่ 3 = มีรายได้จริงต่อเนื่อง 3 ปีเต็ม<br><br>
          📡 จาก Yahoo Finance งบรายปี ย้อนหลัง ~4-5 ปี (ไม่มี Finnomena บนเว็บมือถือ/ไอแพด — เวอร์ชันรันบนเครื่องนับเป็นไตรมาสแทน)`,
      },
      'scr-profit-posstreak-min': {
        label: 'กำไรเป็นบวกติดกัน ≥ (ปี) *', placeholder: 'เช่น 2',
        tip: `<strong>กำไรสุทธิเป็นบวกต่อเนื่อง</strong><br>
          จำนวนปีติดกันที่กำไรสุทธิ &gt; 0 (ไม่ขาดทุนเลย) — กรองหุ้นที่เพิ่งพลิกมาขาดทุน หรือขาดทุนแฝงบางปี<br><br>
          เช่น ใส่ 2 = ไม่ขาดทุนเลยใน 2 ปีหลัง<br><br>
          📡 จาก Yahoo Finance งบรายปี ย้อนหลัง ~4-5 ปี (ไม่มี Finnomena บนเว็บมือถือ/ไอแพด — เวอร์ชันรันบนเครื่องนับเป็นไตรมาสแทน)`,
      },
      'scr-ebitda-posstreak-min': {
        label: 'EBITDA เป็นบวกติดกัน ≥ (ปี) *', placeholder: 'เช่น 2',
        tip: `<strong>EBITDA เป็นบวกต่อเนื่อง (ประมาณ)</strong><br>
          จำนวนปีติดกันที่ EBITDA &gt; 0<br><br>
          เช่น ใส่ 2 = EBITDA เป็นบวกทุกปีใน 2 ปีหลัง<br><br>
          ⚠ ประมาณจาก "กำไรสุทธิ + ค่าเสื่อม/ตัดจำหน่าย" รายปี (Yahoo ไม่มี EBITDA ตรงๆ) เครื่องหมายบวก/ลบแม่นยำสูง แต่ตัวเลขจะต่ำกว่า EBITDA จริงเล็กน้อย<br><br>
          📡 จาก Yahoo Finance งบรายปี ย้อนหลัง ~4-5 ปี (ไม่มี Finnomena บนเว็บมือถือ/ไอแพด — เวอร์ชันรันบนเครื่องนับเป็นไตรมาสแทน)`,
      },
      'scr-ocf-posstreak-min': {
        label: 'OCF เป็นบวกติดกัน ≥ (ปี) *', placeholder: 'เช่น 3',
        tip: `<strong>กระแสเงินสดดำเนินงาน (OCF) เป็นบวกต่อเนื่อง</strong><br>
          จำนวนปีติดกันที่ OCF &gt; 0 — เงินสดเข้าจริงจากการดำเนินธุรกิจ ไม่ใช่แค่กำไรทางบัญชี<br><br>
          เช่น ใส่ 3 = เงินสดเข้าจริงต่อเนื่อง 3 ปีเต็ม<br><br>
          📡 จาก Yahoo Finance งบรายปี ย้อนหลัง ~4-5 ปี (ไม่มี Finnomena บนเว็บมือถือ/ไอแพด — เวอร์ชันรันบนเครื่องนับเป็นไตรมาสแทน)`,
      },
    };
    Object.entries(FIELDS).forEach(([id, cfg]) => {
      const input = document.getElementById(id);
      if (!input) return;
      input.placeholder = cfg.placeholder;
      const group = input.closest('.scr-group');
      const label = group?.querySelector('.scr-label');
      if (label) label.childNodes[0].textContent = cfg.label + ' ';
      const box = group?.querySelector('.scr-tip-box');
      if (box) box.innerHTML = cfg.tip;
    });
    const ocfGtNiBox = document.getElementById('scr-ocf-gt-ni')?.closest('label')?.querySelector('.scr-tip-box');
    if (ocfGtNiBox) {
      ocfGtNiBox.innerHTML = `<strong>คุณภาพกำไร ณ ปีล่าสุด</strong><br>
        ปีล่าสุดที่มีข้อมูลครบ: กระแสเงินสดดำเนินงาน (OCF) มากกว่ากำไรสุทธิไหม — ถ้าใช่ = กำไรมีเงินสดหนุนจริง ไม่ใช่แค่ตัวเลขทางบัญชี<br><br>
        <span style="color:var(--text2)">📡 จาก Yahoo Finance งบรายปี (ไม่มี Finnomena บนเว็บมือถือ/ไอแพด — เวอร์ชันรันบนเครื่องเช็คงวดไตรมาสแทน)</span>`;
    }
  }

  // PWA: ลงทะเบียน service worker เฉพาะเวอร์ชันเว็บ (ติดตั้งเป็นแอป + cache + ออฟไลน์)
  // ไม่ลงทะเบียนบน local Flask — กัน cache บังโค้ดใหม่ระหว่างพัฒนา (file: ก็ลงไม่ได้อยู่แล้ว)
  if ('serviceWorker' in navigator && location.protocol !== 'file:') {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('sw.js').catch(() => {});
    });
  }

  const STATIC_MAP = {
    '/api/data':                  'data/set_data.json',
    '/api/indices':               'data/indices_data.json',
    '/api/dr':                    'data/dr_data.json',
    '/api/etf':                   'data/etf_data.json',
    '/api/nvdr':                  'data/nvdr_data.json',
    '/api/short-sales':           'data/short_sales.json',
    '/api/market-stats':          'data/market_stats.json',
    '/api/market-stats-meta':     'data/market_stats_meta.json',
    '/api/market-flow':           'data/market_flow.json',
    '/api/market-flow-s50':       'data/market_flow_s50.json',
    '/api/market-flow-bond':      'data/market_flow_bond.json',
    '/api/market-internals':      'data/market_internals.json',
    '/api/rotation-alerts':       'data/rotation_alerts.json',
    '/api/stock-valuation-stats': 'data/stock_valuation_stats.json',
    '/api/prices':                'data/prices.json',
    // เวอร์ชันย่อของ /api/financials-analytics ที่ bake ล่วงหน้าจาก Yahoo ล้วน (ไม่มี
    // Finnomena — financials.db เต็มเป็น local-only) ปลุกช่องกรองบางส่วนใน Stock
    // Screener ที่ไม่ได้ต้องพึ่งประวัติไตรมาสยาว (ดู loadFinAnalytics + _FIN_STATIC_UNAVAILABLE_IDS)
    '/api/financials-analytics':  'data/financials_analytics_yahoo.json',
    // คำอธิบายบริษัท DR (EN + แปลไทย) จาก Yahoo Finance — bake ล่วงหน้า ไม่ fetch สด
    '/api/dr-descriptions':       'data/dr_descriptions.json',
    // รายชื่อหุ้น US ที่อยู่ใน S&P 500 / Dow Jones / Nasdaq 100 — bake ล่วงหน้าจาก Wikipedia
    '/api/us-index-membership':   'data/us_index_membership.json',
    // P/E-P/BV รายวันตลาด SET/mai (scrape จาก SET.or.th) — bake ล่วงหน้า
    '/api/set-daily-valuation':   'data/set_daily_valuation.json',
    // สัญญาณเงินทุนรวม (insider+short+NVDR) — ข้อมูลสาธารณะ bake ได้ ใช้บนมือถือได้จริง
    '/api/flow-signals':          'data/flow_signals.json',
  };

  function _staticURL(url) {
    const [path, query] = url.split('?');
    if (path === '/api/breadth') {
      const m = /range=(\w+)/.exec(query || '');
      return `data/breadth_${m ? m[1] : '1y'}.json`;
    }
    // SEC จำกัดผลลัพธ์ ~100 แถว/query — bake แยกไฟล์ต่อช่วงวัน (7/30/90/180)
    // เพื่อไม่ให้ query ช่วงกว้างกินโควตาจนช่วงแคบเหลือข้อมูลไม่ครบ
    if (path === '/api/insider-trades' || path === '/api/major-changes') {
      const m = /days=(\d+)/.exec(query || '');
      const base = path === '/api/insider-trades' ? 'insider_trades' : 'major_changes';
      const allowed = ['7', '30', '90', '180'];
      const d = m && allowed.includes(m[1]) ? m[1] : '180';
      return `data/${base}_${d}.json`;
    }
    return STATIC_MAP[path] || null;
  }

  const _origFetch = window.fetch.bind(window);
  window.fetch = function (url, opts) {
    if (typeof url !== 'string' || !url.startsWith('/api/')) return _origFetch(url, opts);
    const mapped = _staticURL(url);
    // ต้องส่ง signal ต่อด้วย ไม่งั้น AbortController ของ _fetchTimeout() ผูกกับ
    // request นี้ไม่ติด — ครบเวลาแล้ว abort() ยิงเปล่า ไม่มีอะไรฟัง fetch ค้างได้
    // นานเท่าที่เน็ตมือถือจะค้าง เหมือนไม่มี timeout เลย (บั๊กที่ทำให้ _fetchTimeout
    // ทั้งระบบไม่มีผลจริงบนเว็บ static แม้จะตั้ง timeout ไว้ที่ caller ก็ตาม)
    if (mapped) return _origFetch(mapped, { signal: opts && opts.signal });
    if (url.startsWith('/api/status')) {
      return Promise.resolve(new Response('{"running":false}', { headers: { 'Content-Type': 'application/json' } }));
    }
    // endpoint ที่ต้องมี server จริง (quick-update, history ยาว, งบการเงินสด ฯลฯ)
    return Promise.resolve(new Response(
      '{"error":"ฟีเจอร์นี้ใช้ได้เฉพาะเวอร์ชันรันบนเครื่อง (Flask) — เวอร์ชันเว็บอัปเดตข้อมูลอัตโนมัติวันละ 2 รอบ"}',
      { status: 404, headers: { 'Content-Type': 'application/json' } }));
  };
}

// ============================================================
// LOAD DATA — ดึงจาก Flask /api/data
// ============================================================
async function loadData() {
  try {
    // ไม่ใส่ cache-buster — server มี ETag แล้ว ถ้าข้อมูลไม่เปลี่ยนจะได้ 304 (โหลดเร็วมาก)
    // ต้องมี timeout — นี่คือ fetch แรกสุดตอนเปิดเว็บ ถ้าค้าง (เน็ตมือถือไม่นิ่ง) ผู้ใช้ไม่ผ่าน
    // หน้า loading เลย (ดู fetchInsiderData/loadShortData ฯลฯ ที่เจอปัญหาเดียวกันมาก่อน)
    const r = await _fetchTimeout("/api/data", IS_STATIC ? 25000 : 60000,
      'หมดเวลารอข้อมูล (เกิน ' + (IS_STATIC ? 25 : 60) + ' วิ) — ลองใหม่อีกครั้ง');
    if (!r.ok) {
      document.getElementById("updated-at").textContent = "ยังไม่มีข้อมูล — กด Refresh";
      return;
    }
    DATA = await r.json();
    DATA.stocks.forEach(s => {
      if (!s.sector || s.sector === '-') s.sector = s.market === 'mai' ? 'MAI' : 'Unknown';
      // คำนวณ ret_1y จาก price_history ถ้า null (ใช้แท่ง -260 = ~1 ปี ไม่ใช่ bar แรกสุด)
      if (s.ret_1y == null && s.price_history && s.price_history.length >= 260) {
        const idx1y = Math.max(0, s.price_history.length - 260);
        const first = s.price_history[idx1y][1];
        if (first > 0) s.ret_1y = +((s.price - first) / first * 100).toFixed(2);
      }
    });
    _enrichTechSignals(DATA.stocks);
    DATA.sectors.forEach(s => {
      if (!s.name || s.name === '-') s.name = 'MAI';
    });
    // คำนวณ ret_1y เฉลี่ยของแต่ละ group ใหม่
    ['sectors','industries'].forEach(key => {
      const groupKey = key === 'sectors' ? 'sector' : 'industry';
      DATA[key].forEach(g => {
        if (g.ret_1y == null) {
          const vals = DATA.stocks.filter(s => s[groupKey] === g.name && s.ret_1y != null).map(s => s.ret_1y);
          // เคารพกฎเดียวกับ backend (G3): กลุ่มต้องมีข้อมูล >= 3 ตัวถึงจะเฉลี่ย
          g.ret_1y = vals.length >= 3 ? +(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(2) : null;
        }
      });
    });
    const _upType  = DATA.update_type || '—';
    const _upTime  = DATA.updated_at  || '—';
    const _asOf    = DATA.data_as_of  || '—';
    const _typeIcon = _upType === 'Full Refresh' ? '🔄' : '⚡';
    // เวอร์ชันเว็บ (static): บอกความสดของข้อมูลให้ชัด — ข้อมูลอัพเดตตามรอบ GitHub
    // Actions (~06:00 / 13:10 / 18:30 ICT) ไม่ใช่ราคาสด กันตีความผิดตอนเปิดระหว่างวัน
    const _staticNote = IS_STATIC
      ? ` <span style="color:var(--text2);font-size:10px">· 🌐 เว็บเวอร์ชันอ่านอย่างเดียว — อัพเดตอัตโนมัติ ~06:00/13:10/18:30 น.</span>`
      : '';
    document.getElementById("updated-at").innerHTML =
      `<span title="ประเภท: ${_upType}\nดึงข้อมูลเมื่อ: ${_upTime}\nข้อมูลราคาถึงวัน: ${_asOf}" style="cursor:default">` +
      `${_typeIcon} <b>${_asOf}</b> <span style="color:var(--text2);font-size:10px">${_upTime.slice(11,16)}</span>` +
      `</span>` + _staticNote;
    _populateScrIndustry();
    _scrMigrateRvolOnce();
    loadScreenerSettings();
    initScreenerAutosave();
    renderSavedPresets();
    renderDqBanner();
    _rotAlertsData = null;   // ข้อมูลใหม่ -> ดึง rotation alerts ใหม่
    _breadthData   = null;   // ข้อมูลใหม่ -> ดึง breadth ใหม่
    _breadthCacheByRange = {};
    loadRegimeLight();       // ไฟ regime บน nav (async ไม่ block การ render)
    renderAll();
    initAlertSystem();
    checkPeReminder();
    checkFinReminder();      // เตือนอัพเดทงบการเงินฉบับเต็มทุก 2 เดือน (local-only)
    checkFlowFreshness();    // ซ่อนเมนู Capital Flow บนเวอร์ชันเว็บถ้าข้อมูลค้าง
    loadFinAnalytics();      // ผสาน growth_score/peg/fcf_yield เข้า DATA.stocks (local-only)
    checkDataHealthBadge();  // badge แดงบนปุ่ม nav ถ้ามีแหล่งข้อมูลไหนค้าง (local-only)
    checkEtfNewListingsBadge();  // badge ฟ้าบนปุ่ม nav ถ้ามี ETF จดทะเบียนใหม่ (local-only)
    checkRunFailures();      // banner แดงถ้า Quick Update/Full Refresh/สคริปต์งบ ล่าสุดล้มเหลว
  } catch(e) {
    console.error("loadData error:", e);
    document.getElementById("updated-at").textContent = "ไม่สามารถโหลดข้อมูลได้: " + e.message;
  }
}

// ============================================================
// REFRESH — ดึงข้อมูลใหม่พร้อม progress bar
// ============================================================
let _refreshStart = 0;

async function _startJob(apiEndpoint, btnId, btnLabel, body = null, onDone = null) {
  const btn = document.getElementById(btnId);
  btn.disabled = true;
  btn.textContent = btnLabel + "...";

  try {
    const opts = { method: "POST" };
    if (body) { opts.headers = { "Content-Type": "application/json" }; opts.body = JSON.stringify(body); }
    const r = await fetch(apiEndpoint, opts);
    if (!r.ok) {
      // response อาจไม่ใช่ JSON (เช่น 500 ที่ตอบ HTML error page ของ server) —
      // อย่าให้ .json() ที่ parse ไม่ได้ throw เข้า catch ด้านล่างจนฟ้องข้อความผิด
      // ("เชื่อมต่อไม่ได้" ทั้งที่จริงเชื่อมต่อได้ แค่ server error)
      let msg = "เกิดข้อผิดพลาด";
      try { msg = (await r.json()).error || msg; } catch(e) { msg = `เกิดข้อผิดพลาด (HTTP ${r.status})`; }
      alert("⚠️ " + msg);
      btn.disabled = false; btn.textContent = btnLabel; return;
    }
  } catch(e) {
    alert("❌ ไม่สามารถเชื่อมต่อ server ได้");
    btn.disabled = false; btn.textContent = btnLabel; return;
  }

  _refreshStart = Date.now();
  const overlay = document.getElementById("progress-overlay");
  overlay.style.display = "flex";
  document.getElementById("progress-bar-fill").style.width = "0%";
  document.getElementById("progress-pct").textContent = "0%";
  document.getElementById("progress-msg").textContent = "กำลังเริ่ม...";
  document.getElementById("progress-eta").textContent = "";

  let es = null;
  let sseRetries = 0;
  const MAX_SSE_RETRIES = 20; // ~จับสะดุด connection ได้ยาวหลายนาที ก่อนจะยอมแพ้จริงๆ

  function finish(s) {
    document.getElementById("progress-bar-fill").style.width = "100%";
    document.getElementById("progress-pct").textContent = "100%";
    setTimeout(function() {
      overlay.style.display = "none";
      btn.disabled = false; btn.textContent = btnLabel;
      if (s.error) {
        const usedFallback = (s.message || "").includes("ข้อมูลล่าสุด");
        if (usedFallback) {
          alert("⚠️ ดึงข้อมูลใหม่ไม่สำเร็จ\nกำลังใช้ข้อมูลล่าสุดแทน");
          loadData();
        } else {
          alert("❌ เกิดข้อผิดพลาด:\n" + s.error);
        }
      } else {
        // ไม่ error แต่มีบางส่วนล้มเหลวไม่ critical (เช่น Indices/Capital Flow
        // ตอน Full Refresh) — เห็นข้อความเตือนแทนที่จะเงียบหายไปทั้งที่หัวข้อหลักสำเร็จ
        if ((s.message || "").includes("ล้มเหลว")) {
          alert("⚠️ " + s.message);
        }
        resetNhCache();
        // clear all page caches so next visit fetches fresh data
        _idxData = null; _idxDataDone = false; _idxDataFails = 0; _valData = null; _nvdrData = null;
        _shortData = null; _insData = null;
        // สัญญาณรวมคำนวณจาก short+NVDR+insider ที่เพิ่งล้างไป — ถ้าไม่ล้างด้วย หน้า
        // "🎯 สัญญาณรวม" (และ alert watchlist ที่เช็คทุก 5 นาที) จะค้างชุดเก่าทั้ง session
        _flowSigData = null;
        Object.keys(_flowDataByMarket).forEach(k => delete _flowDataByMarket[k]); _valStockData = null;
        _drLoaded = false; _drData = null;
        // ล้าง cache หุ้น US/HK ด้วย — job ที่วิ่งผ่าน _startJob (Quick Update, US/HK
        // Index Max) อัพเดทราคา/metrics ฝั่ง server เสร็จแล้วเสมอ ถ้าไม่ล้างตรงนี้
        // หน้า "หุ้น US/HK", Heatmap, Rotation จะยังโชว์ข้อมูลเก่าจนกว่าจะ F5 เอง
        _usData = null; _usSectorRanks = {}; _usBreadthCacheByRange = {};
        _hkData = null; _hkSectorRanks = {}; _hkBreadthCacheByRange = {};
        _jpData = null; _jpSectorRanks = null; _jpBreadthCacheByRange = {}; _jpBreadthEpoch++;
        _hmData = {}; _hkHmData = {}; _jpHmData = null;
        loadData();
        // if already on a data page, reload it immediately
        const _activePage = document.querySelector('.page.active')?.id;
        if (_activePage === 'page-indices')   loadIndicesPage();
        if (_activePage === 'page-dr')        loadDRPage();
        if (_activePage === 'page-valuation') loadValuationPage();
        if (_activePage === 'page-short')     loadShortPage();
        if (_activePage === 'page-confluence') loadConfluencePage();
        if (_activePage === 'page-insider')   loadInsiderPage();
        if (_activePage === 'page-flow')      loadFlowPage();
        if (_activePage === 'page-us-stocks')   loadUsStocksPage();
        if (_activePage === 'page-hk-stocks')   loadHkStocksPage();
        if (_activePage === 'page-jp-stocks')   loadJpStocksPage();
        // page-heatmap/page-stock-rotation รวม TH/US/HK/JP ไว้หน้าเดียวแล้ว — reload เฉพาะ
        // แท็บตลาดที่กำลังดูอยู่ (_hmMarket/_srMarket) ไม่ใช่ทุกตลาดพร้อมกัน
        if (_activePage === 'page-heatmap') {
          if (_hmMarket === 'US') loadHeatmapPage();
          if (_hmMarket === 'HK') loadHkHeatmapPage();
          if (_hmMarket === 'JP') loadJpHeatmapPage();
        }
        if (_activePage === 'page-stock-rotation') {
          if (_srMarket === 'TH') loadDRRotation();
          if (_srMarket === 'US') loadUsRotation();
          if (_srMarket === 'HK') loadHkRotation();
          if (_srMarket === 'JP') loadJpRotation();
        }
        if (onDone) onDone(s);   // ส่ง state สุดท้าย (มี message ที่มี ok/fail count) ให้ caller ใช้ต่อได้
      }
    }, 800);
  }

  function connectSSE() {
    es = new EventSource("/api/progress");
    es.onmessage = function(e) {
      sseRetries = 0; // ข้อความเข้าปกติ -> รีเซ็ตตัวนับ retry
      const s = JSON.parse(e.data);
      const pct = s.total > 0 ? Math.min(Math.round(s.current / s.total * 100), 99) : 0;
      document.getElementById("progress-bar-fill").style.width = pct + "%";
      document.getElementById("progress-pct").textContent = pct + "%";
      document.getElementById("progress-msg").textContent = s.message || "";
      if (pct > 5 && pct < 99) {
        const elapsed = (Date.now() - _refreshStart) / 1000;
        const eta = Math.round(elapsed / pct * (100 - pct));
        const mm = Math.floor(eta / 60), ss = eta % 60;
        document.getElementById("progress-eta").textContent =
          "เหลืออีกประมาณ " + (mm > 0 ? mm + " นาที " : "") + ss + " วินาที";
      }
      if (s.done) {
        es.close();
        finish(s);
      }
    };
    es.onerror = function() {
      es.close();
      // job (Full Refresh ~1 ชม.) ยังรันอยู่ฝั่ง server ต่อเนื่องแม้ SSE connection
      // สะดุด — reconnect แทนการปิด overlay ทิ้งเฉยๆ ไม่งั้นผู้ใช้เข้าใจผิดว่าจบแล้ว
      // ทั้งที่ยังรันอยู่ (กดปุ่มซ้ำจะเจอ 409 งงต่อ)
      sseRetries++;
      if (sseRetries > MAX_SSE_RETRIES) {
        overlay.style.display = "none";
        btn.disabled = false; btn.textContent = btnLabel;
        alert("⚠️ ขาดการเชื่อมต่อกับ server — งานอาจยังรันอยู่เบื้องหลัง\nลองรีเฟรชหน้าเว็บอีกครั้งภายหลัง");
        loadData();
        return;
      }
      document.getElementById("progress-msg").textContent = "การเชื่อมต่อขาดหาย กำลังลองใหม่...";
      setTimeout(connectSSE, Math.min(1000 * sseRetries, 5000));
    };
  }
  connectSSE();
}

function startRefresh() {
  const dlg = document.getElementById('refresh-dialog');
  dlg.style.display = 'flex';
}
function confirmRefresh(period) {
  document.getElementById('refresh-dialog').style.display = 'none';
  _startJob("/api/refresh", "refresh-btn", "⟳ Full Refresh", { period }, () => {
    // callback หลัง SET เสร็จ: ล้าง DR cache แล้วเริ่ม DR refresh ใน background —
    // ต้องรอ /api/refresh ยืนยันว่างานเริ่มได้จริงและรันจนจบก่อน ไม่งั้นถ้า
    // /api/refresh ตอบ 409 (มีงานรันอยู่แล้ว) DR cache จะถูกล้างฟรีโดยไม่มีอะไร
    // มาสร้างใหม่ให้ ทำให้เปิดหน้า DR ครั้งถัดไปต้องดึงใหม่ทั้ง 266 ตัวโดยไม่จำเป็น
    _drLoaded = false;
    _drData   = null;
    const statusEl = document.getElementById('dr-status');
    if (statusEl) statusEl.textContent = 'กำลังอัปเดตข้อมูลหุ้นต่างประเทศ...';
    // ต้องรอ POST ตั้ง ts=0 ให้เสร็จก่อนยิง GET /api/dr — ไม่งั้น GET อาจถึง get_dr_data
    // ก่อน (คนละ worker thread) เห็น cache ยังไม่หมดอายุ แล้วตอบของเก่าโดยไม่ rebuild
    fetch('/api/dr-full-refresh', { method: 'POST' })
      .catch(() => {})
      .then(() => _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000))
      .then(r => r.json())
      .then(d => {
        if (d.stocks) {
          _drData   = d.stocks;
          _drLoaded = true;
          const ts = d.ts ? d.ts.replace('T',' ').slice(0,16) : '—';
          if (statusEl) statusEl.innerHTML =
            `อัปเดต: ${ts} &nbsp;|&nbsp; ${_drData.length} stocks`;
          if (document.getElementById('page-dr')?.classList.contains('active'))
            renderDRTable();
        }
      }).catch(() => {});
    checkDataHealthBadge();
  });
}
function startQuickUpdate() {
  _fetchTimeout('/api/dr-quick-update', 30000, null, { method: 'POST' }).catch(() => {});
  // ETF universe เล็ก (~13 ตัว) full-refresh เร็วพอจะยิงตรงๆ แทน incremental job แบบ DR —
  // แค่ล้าง cache เบื้องหลัง รอบถัดไปที่ /api/etf ถูกเรียก (เปิดหน้า ETF หรือ Rotation
  // แท็บ ETF) จะได้ข้อมูลสดแทนของเก่าอัตโนมัติ
  fetch('/api/etf-full-refresh', { method: 'POST' }).catch(() => {});
  _startJob("/api/quick-update", "quick-update-btn", "⚡ Quick Update", null, checkDataHealthBadge);
}

