// ── Stage helpers ──────────────────────────────────────────────
function getStage(s) {
  if (s.stage != null) return s.stage;
  // client-side fallback: approximate ด้วย ema200_slope_pct หรือ returns
  const above = s.above_ema200;
  if (above == null) return null;
  // ถ้ายังไม่มี ema200_slope_pct (ก่อน Quick Update) คืน null — ไม่ guess สูตร
  const slope = s.ema200_slope_pct ?? null;
  if (slope == null) return null;
  if (above  && slope >= 0) return 2;
  if (above  && slope <  0) return 3;
  if (!above && slope >= -1.5) return 1;
  return 4;
}

function stageBadge(stage) {
  if (stage == null) return '<span class="text2">—</span>';
  const cfg = {
    1: { label: 'S1 Basing',    color: '#58a6ff' },
    2: { label: 'S2 ✅',        color: '#3fb950' },
    3: { label: 'S3 Topping',   color: '#e3b341' },
    4: { label: 'S4 Declining', color: '#f85149' },
  };
  const c = cfg[stage] || { label: '—', color: 'var(--text2)' };
  return `<span style="font-size:10px;font-weight:700;color:${c.color}">${c.label}</span>`;
}

// ── Market Regime ──────────────────────────────────────────────
// หมายเหตุ: เดิมใช้ % หุ้น RS≥80 เป็น component (น้ำหนัก 25%) แต่ rs_score เป็น percentile
// rank ภายใน universe (rank_rs ปัดเป็น 0-99 ตามอันดับ) ทำให้ตาม "นิยาม" แล้วประมาณ 20% ของ
// หุ้นที่มี RS ถูกต้องเสมอจะมี RS≥80 ไม่ว่าตลาดจะ bull/bear แค่ไหน — แทบไม่แปรผันจริง
// เปลี่ยนเป็น % หุ้นที่ ret_3m เป็นบวก (magnitude-based เหมือน pctPos1m) ซึ่งแปรตามสภาพตลาดจริง
function calcMarketRegime(stocks) {
  // เศษ/ส่วนนับเฉพาะหุ้นที่ค่านั้นไม่ใช่ null — หุ้น IPO ใหม่ (< period แท่ง → above_emaXXX = null,
  // < 63 แท่ง → ret_3m = null) เดิมถูกนับเข้า "ส่วน" แต่ไม่เคยเข้า "เศษ" ทำให้ score เอนไป Bear
  // ~1-4 แต้มถาวร (หนักช่วงหุ้นเข้าใหม่เป็นชุด) — สอดคล้องกับ core/metrics.pct_above_ema50
  const frac = (key, test) => {
    const w = stocks.filter(s => s[key] != null);
    return w.length ? w.filter(test).length / w.length * 100 : 0;
  };
  const pct200 = frac('above_ema200', s => s.above_ema200);
  const pct50  = frac('above_ema50',  s => s.above_ema50);
  const pctPos3m = frac('ret_3m', s => s.ret_3m > 0);
  const pctPos1m = frac('ret_1m', s => s.ret_1m > 0);
  const score = Math.round(pct200 * 0.35 + pct50 * 0.25 + pctPos3m * 0.25 + pctPos1m * 0.15);
  const capped = Math.min(100, score);
  let desc = '';
  if (pct200 >= 60 && pctPos3m >= 60)   desc = `EMA200: ${pct200.toFixed(0)}% · 3M เป็นบวก: ${pctPos3m.toFixed(0)}%`;
  else if (pct200 < 40) desc = `ระวัง: เพียง ${pct200.toFixed(0)}% อยู่เหนือ EMA200`;
  else desc = `EMA200: ${pct200.toFixed(0)}% · EMA50: ${pct50.toFixed(0)}%`;
  return { score: capped, desc };
}

