// stockMap/drMap/usMap/hkMap เดิม rebuild ทุกครั้งที่ renderWatchlist() ถูกเรียก (ถี่มาก — ทุก
// mirror fetch ที่ resolve) ทั้งที่ DATA/_drData/_usData/_hkData reassign ทั้งก้อนเสมอ ไม่เคย
// mutate in place (เหมือน DATA ที่ _secRankCache ใช้ identity-check อยู่แล้วที่ computeSectorRanks)
// → memoize ด้วย reference-identity เดียวกัน กันสร้าง map ~900 หุ้นซ้ำโดยไม่จำเป็น
let _wlMapCache = { data: null, dr: null, us: null, hk: null, stockMap: null, drMap: null, usMap: null, hkMap: null };
function _wlBuildMaps() {
  if (_wlMapCache.data === DATA && _wlMapCache.dr === _drData && _wlMapCache.us === _usData && _wlMapCache.hk === _hkData) {
    return _wlMapCache;
  }
  _wlMapCache = {
    data: DATA, dr: _drData, us: _usData, hk: _hkData,
    stockMap: Object.fromEntries(DATA.stocks.map(s => [s.symbol, s])),
    drMap:    Object.fromEntries((_drData || []).map(s => [s.sym, s])),
    usMap:    Object.fromEntries((_usData?.stocks || []).map(s => [s.symbol, s])),
    hkMap:    Object.fromEntries((_hkData?.stocks || []).map(s => [s.symbol, s])),
  };
  return _wlMapCache;
}

function renderWatchlist() {
  _wlPopulateSymList();
  if (!DATA) {
    document.getElementById("wl-tbody").innerHTML =
      `<tr><td colspan="17"><div class="empty">กำลังโหลดข้อมูล...</div></td></tr>`;
    return;
  }
  const { stockMap, drMap, usMap, hkMap } = _wlBuildMaps();

  // ถ้ามี symbol ใน watchlist ที่ไม่เจอใน SET/DR/US Index/HK Index และยังไม่โหลดชุดข้อมูลนั้น
  // → fetch เฉพาะชุดที่ขาดจริง (ดู prefix DR:/US:/HK: บอกตลาดอยู่แล้ว) แล้ว re-render
  // เดิม fetch ทั้ง 3 endpoint (รวม ~9MB) ทุกครั้งที่มี symbol ค้างแม้จะรู้ตลาดจาก prefix แล้ว
  if (!_drData || (!IS_STATIC && (!_usData || !_hkData))) {
    const need = new Set();
    let hasUnknown = false;
    watchlist.forEach(sym => {
      const hasPfx = sym.startsWith("DR:") || sym.startsWith("US:") || sym.startsWith("HK:");
      const clean = hasPfx ? sym.slice(3) : sym;
      // ต้องเช็คเทียบกับตลาดที่ prefix ของ entry บอกไว้เท่านั้น ไม่ใช่ทุก map — ไม่งั้น ticker
      // ที่ซ้ำชื่อข้ามตลาด (เช่น TSLA เป็นทั้งสมาชิก US Index และ DR underlying) จะเข้าใจผิดว่า
      // "พร้อมแล้ว" จาก map ของอีกตลาดที่บังเอิญโหลดมาก่อน ทำให้ตลาดจริงของ entry นั้นไม่เคยถูก
      // fetch เลย (แถวค้าง "ยังไม่โหลดข้อมูล" ถาวร) — entry ไม่มี prefix (legacy) ยังไม่รู้ตลาด
      // จริง เช็คทุกแหล่งเหมือนเดิม
      if (sym.startsWith("DR:")) { if (drMap[clean]) return; }
      else if (sym.startsWith("US:")) { if (usMap[clean]) return; }
      else if (sym.startsWith("HK:")) { if (hkMap[clean]) return; }
      else if (stockMap[sym] || stockMap[clean] || drMap[clean] || usMap[clean] || hkMap[clean]) return;
      // เว็บมือถือ/iPad (IS_STATIC): /api/us-index-metrics, /api/hk-index-metrics ไม่มีบน GitHub
      // Pages เลย (us/hk_prices.db local-only ไม่ได้ bake) ดึงยังไงก็ไม่สำเร็จ — ถ้ายังนับเป็น
      // "unknown" ต่อไปจะค้างจอ "กำลังโหลดข้อมูล..." ทั้งตารางตลอดกาลทุกครั้งที่มีหุ้น US/HK ดัชนี
      // หลัก (เช่น AAPL/NVDA) อยู่ใน Watchlist — ปล่อยผ่านให้ตกไปที่ per-row fallback
      // (_wlFetchMirror ผ่าน /api/tearsheet) แทน อย่างน้อยได้ error แจ้งชัดเจนต่อแถวเดียว
      // ไม่ค้างทั้งตาราง (ดูจุดเรียก _wlFetchMirror ด้านล่างใน renderWatchlist)
      if (hasPfx && IS_STATIC && (sym.startsWith("US:") || sym.startsWith("HK:"))) return;
      hasUnknown = true;
      if (hasPfx) need.add(sym.slice(0, 2));
      else { need.add("DR"); need.add("US"); need.add("HK"); }   // ไม่รู้ตลาด — เช็คทุกแหล่งเหมือนเดิม
    });
    if (hasUnknown) {
      document.getElementById("wl-tbody").innerHTML =
        `<tr><td colspan="17"><div class="empty" style="font-size:12px">กำลังโหลดข้อมูล DR/DRx, US Index และ HK Index...</div></td></tr>`;
      Promise.all([
        (_drData || !need.has("DR")) ? Promise.resolve() : _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000).then(r => r.json()).then(d => {
          if (d.stocks) { _drData = d.stocks; _drLoaded = true; }
          if (d.refreshing) _drPollRefresh(0);   // cache stale — poll เบื้องหลังจนได้ชุดใหม่ (pattern เดียวกับหน้า DR)
        }).catch(() => {}),
        (IS_STATIC || _usData || !need.has("US")) ? Promise.resolve() : _fetchTimeout('/api/us-index-metrics', 25000).then(r => r.json()).then(d => {
          if (d && !d.error && d.stocks && d.stocks.length) _usData = d;   // route คืน {error:...} ตอน exception — ห้าม cache เป็นข้อมูลจริง/ก้อนว่าง ไม่งั้นไม่ retry อีกเลยทั้ง session + renderUsTable crash
        }).catch(() => {}),
        (IS_STATIC || _hkData || !need.has("HK")) ? Promise.resolve() : _fetchTimeout('/api/hk-index-metrics', 25000).then(r => r.json()).then(d => {
          if (d && !d.error && d.stocks && d.stocks.length) _hkData = d;
        }).catch(() => {}),
      ]).then(renderWatchlist);
      return;
    }
  }

  if (watchlist.length === 0) {
    document.getElementById("wl-tbody").innerHTML =
      `<tr><td colspan="17"><div class="empty">ยังไม่มีหุ้นใน Watchlist<br>พิมพ์ Symbol (เช่น PTT, AAPL, NVDA) แล้วกด + เพิ่ม</div></td></tr>`;
    return;
  }

  // จัดเรียงตามตลาด: หุ้นไทย(ไม่มี prefix) → DR → US → HK (sort เสถียร คงลำดับเดิม
  // ภายในกลุ่มเดียวกัน) เรียงแค่ตอน render ไม่แตะ watchlist จริง กัน indexOf/migrate ด้านล่างพัง
  // (ไม่มี "JP:" เพราะ Tearsheet ซ่อนปุ่มเพิ่ม Watchlist ของตลาด JP ไว้แล้ว — renderWatchlist
  // ไม่มี render branch รองรับ entry แบบนี้จริง ดู guard ที่ปุ่ม "เพิ่มเข้า Watchlist" ของ JP)
  const _wlMarketRank = sym =>
    sym.startsWith("DR:") ? 1 : sym.startsWith("US:") ? 2 : sym.startsWith("HK:") ? 3 : 0;
  const sortedWatchlist = [...watchlist].sort((a, b) => _wlMarketRank(a) - _wlMarketRank(b));

  const rows = sortedWatchlist.map(sym => {
    // ── DR row ──
    if (sym.startsWith("DR:")) {
      const under = sym.slice(3);
      const d = drMap[under];
      if (!d) return `
        <tr>
          <td class="text2">—</td>
          <td><strong style="color:var(--blue)">${_escHtml(under)}</strong>
            <span style="font-size:9px;background:rgba(88,166,255,.15);color:var(--blue);border-radius:3px;padding:1px 4px;margin-left:4px">DR</span>
          </td>
          <td colspan="14" class="text2">ยังไม่โหลดข้อมูล DR — ไปหน้า DR ก่อน</td>
          <td><button class="wl-del-btn" onclick="confirmRemoveFromWatchlist('${_escJsAttr(sym)}')">✕</button></td>
        </tr>`;

      return _wlRenderDrRow(sym, under, d);
    }

    // ── US Index row (S&P500/Dow/NDX จาก us_index_metrics.json) — ถ้าไม่เจอในดัชนีหลัก
    // ลอง on-demand mirror data (_wlMirrorData, เติมโดย _wlFetchMirror) เหมือนหน้า Tearsheet ──
    if (sym.startsWith("US:")) {
      const under = sym.slice(3);
      let u = usMap[under];
      let isMirror = false;
      if (!u) {
        const m = _wlMirrorData[sym];
        if (m && !m.error) { u = m; isMirror = true; }
        else if (m && m.error && (Date.now() - (m.t || 0)) < _WL_MIRROR_ERR_RETRY_MS) return _wlMirrorErrorRow(sym, under, 'US', m.error);
        else { if (m) delete _wlMirrorData[sym]; _wlQueueMirrorFetch({sym, mkt:'US', under, guess:false}); return _wlMirrorLoadingRow(sym, under, 'US'); }
      }
      return _wlRenderUsRow(sym, u, isMirror);
    }

    // ── HK Index row (HSI/HSTECH/HSCEI จาก hk_index_metrics.json) — ถ้าไม่เจอในดัชนีหลัก
    // ลอง on-demand mirror data (_wlMirrorData, เติมโดย _wlFetchMirror) เหมือนหน้า Tearsheet ──
    if (sym.startsWith("HK:")) {
      const under = sym.slice(3);
      let h = hkMap[under];
      let isMirror = false;
      if (!h) {
        const m = _wlMirrorData[sym];
        if (m && !m.error) { h = m; isMirror = true; }
        else if (m && m.error && (Date.now() - (m.t || 0)) < _WL_MIRROR_ERR_RETRY_MS) return _wlMirrorErrorRow(sym, under, 'HK', m.error);
        else { if (m) delete _wlMirrorData[sym]; _wlQueueMirrorFetch({sym, mkt:'HK', under, guess:false}); return _wlMirrorLoadingRow(sym, under, 'HK'); }
      }
      return _wlRenderHkRow(sym, h, isMirror);
    }

    // ── SET row (หรือ DR/US/HK ที่เก็บโดยไม่มี prefix — migrate อัตโนมัติ) ──
    const s = stockMap[sym];
    if (!s) {
      // ตรวจว่าเป็น DR underlying ที่ไม่มี prefix (เช็คก่อน US — ถ้าเคยมีทั้งคู่ให้ยึด DR
      // ตามพฤติกรรมเดิมก่อนเพิ่ม US Index)
      const drMatch = drMap[sym];
      if (drMatch) {
        // migrate: เปลี่ยน sym → DR:sym ใน localStorage แล้ว re-render
        const idx = watchlist.indexOf(sym);
        if (idx !== -1) {
          watchlist[idx] = "DR:" + sym;
          _wlSave();
          _alertsRenameSymbol(sym, "DR:" + sym);
        }
        // render ในรอบนี้เป็น DR row โดยใช้ key ใหม่
        return _wlRenderDrRow("DR:" + sym, sym, drMatch);
      }
      // ตรวจว่าเป็น US Index ticker ที่ไม่มี prefix (เฉพาะตัวที่ไม่ใช่ DR ด้วย)
      const usMatch = usMap[sym];
      if (usMatch) {
        // migrate: เปลี่ยน sym → US:sym ใน localStorage แล้ว re-render
        const idx = watchlist.indexOf(sym);
        if (idx !== -1) {
          watchlist[idx] = "US:" + sym;
          _wlSave();
          _alertsRenameSymbol(sym, "US:" + sym);
        }
        return _wlRenderUsRow("US:" + sym, usMatch, false);
      }
      // ตรวจว่าเป็น HK Index ticker ที่ไม่มี prefix (เฉพาะตัวที่ไม่ใช่ DR/US ด้วย)
      const hkMatch = hkMap[sym];
      if (hkMatch) {
        // migrate: เปลี่ยน sym → HK:sym ใน localStorage แล้ว re-render
        const idx = watchlist.indexOf(sym);
        if (idx !== -1) {
          watchlist[idx] = "HK:" + sym;
          _wlSave();
          _alertsRenameSymbol(sym, "HK:" + sym);
        }
        return _wlRenderHkRow("HK:" + sym, hkMatch, false);
      }
      // ไม่เจอในทุกแหล่งที่รู้ตลาดแน่ชัด (SET/DR/US-idx/HK-idx) — อาจเป็นหุ้น mirror นอกดัชนี
      // หลักที่เก็บไว้แบบไม่มี prefix ตั้งแต่ก่อนมี prefix บังคับ (เช่น OKTA/ZS) ลอง on-demand
      // เดาตลาด (_wlFetchMirrorGuessMarket) — สำเร็จแล้วจะ migrate เป็น "US:"/"HK:" ให้เอง
      // แล้ว re-render ผ่าน branch ด้านบนตรงๆ ไม่ผ่าน path นี้อีก
      const guess = _wlMirrorData[sym];
      if (!guess || (guess.error && (Date.now() - (guess.t || 0)) >= _WL_MIRROR_ERR_RETRY_MS)) {
        if (guess) delete _wlMirrorData[sym];
        _wlQueueMirrorFetch({sym, guess:true});
        return _wlMirrorLoadingRow(sym, sym, null);
      }
      return `
        <tr>
          <td class="text2">—</td><td><strong>${_escHtml(sym)}</strong></td>
          <td colspan="14" class="text2">ไม่พบข้อมูล${guess.error ? ` — ${_escHtml(guess.error)}` : ''}</td>
          <td><button class="wl-del-btn" onclick="confirmRemoveFromWatchlist('${_escJsAttr(sym)}')">✕</button></td>
        </tr>`;
    }
    return `
      <tr data-sym="${s.symbol}">
        <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score??"-"}</span></td>
        <td><strong class="sym-link" onclick="openChartModal('${s.symbol}')">${s.symbol}</strong>${tvLink(s.symbol)}${dqBadge(s)}</td>
        <td style="font-size:11px;color:var(--text2);max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(s.name)}</td>
        <td style="font-size:11px">${s.sector||"—"}</td>
        <td class="r">${s.price?.toFixed(2)??"—"}${_wlLiveCell(s.symbol, s.price)}</td>
        <td class="r">${pct(s.ret_1d)}</td>
        <td class="r">${pct(s.ret_1w)}</td>
        <td class="r">${pct(s.ret_1m)}</td>
        <td class="r">${pct(s.ret_3m)}</td>
        <td class="r">${pct(s.ret_ytd)}</td>
        <td class="r">${pct(s.ret_1y)}</td>
        <td class="r"><canvas class="spark-canvas" width="60" height="24" style="display:block;width:100%;height:24px"></canvas></td>
        <td class="r" style="font-size:11px">${fmtCap(s.mkt_cap, s.is_reit)}</td>
        <td class="r">${emaBadge(s.above_ema50)}</td>
        <td class="r">${emaBadge(s.above_ema200)}</td>
        <td class="r" style="white-space:nowrap">${_wlAlertCell(s.symbol)}</td>
        <td><button class="wl-del-btn" onclick="confirmRemoveFromWatchlist('${_escJsAttr(sym)}')">✕</button></td>
      </tr>`;
  }).join("");

  document.getElementById("wl-tbody").innerHTML = rows;

  // สร้างหลัง .map() ข้างบนจบแล้วเท่านั้น (ไม่ใช่ต้นฟังก์ชัน) — legacy-migrate block ระหว่าง
  // .map() มี mutate watchlist[idx] กลางทาง ถ้าสร้าง Set ไว้ก่อนจะ stale ไม่เห็นรายการที่เพิ่ง
  // migrate เสร็จ ใช้ Set แทน watchlist.includes() ในลูป filter ด้านล่างกัน O(n×m) ทุก render
  const wlSet = new Set(watchlist);

  // sparklines: SET
  renderSparklinesInTable("wl-tbody", DATA.stocks.filter(s => wlSet.has(s.symbol)));

  // sparklines: US Index — reuse ตัววาดเดียวกับ SET (มี price_history ในฟอร์แมตเดียวกัน
  // เพราะ process_stock() ตัวเดียวกัน) แค่ clone symbol ใส่ prefix ให้ตรงกับ data-sym
  if (_usData?.stocks?.length) {
    const usRows = _usData.stocks
      .filter(u => wlSet.has("US:" + u.symbol))
      .map(u => ({ ...u, symbol: "US:" + u.symbol }));
    renderSparklinesInTable("wl-tbody", usRows);
  }

  // sparklines: HK Index — เหมือน US ทุกประการ (process_stock() ตัวเดียวกัน)
  if (_hkData?.stocks?.length) {
    const hkRows = _hkData.stocks
      .filter(h => wlSet.has("HK:" + h.symbol))
      .map(h => ({ ...h, symbol: "HK:" + h.symbol }));
    renderSparklinesInTable("wl-tbody", hkRows);
  }

  // sparklines: US/HK mirror นอกดัชนีหลัก — ดึง on-demand เหมือน Tearsheet แล้ว cache ไว้ใน
  // _wlMirrorData (key = watchlist entry เต็มอยู่แล้ว เช่น "US:ZS" ตรงกับ data-sym พอดี)
  const mirrorRows = Object.entries(_wlMirrorData)
    .filter(([k, d]) => wlSet.has(k) && d && !d.error && d.price_history?.length)
    .map(([k, d]) => ({ ...d, symbol: k }));
  if (mirrorRows.length) renderSparklinesInTable("wl-tbody", mirrorRows);

  // sparklines: DR — วาดจาก close100 ที่ฝังใน data-dr-close
  requestAnimationFrame(() => {
    document.querySelectorAll("#wl-tbody tr[data-dr-close]").forEach(row => {
      const canvas = row.querySelector(".wl-dr-spark");
      if (!canvas) return;
      try {
        const closes = JSON.parse(row.dataset.drClose || "[]");
        if (closes.length >= 2) {
          // สร้าง price_history format ที่ drawSparkline รองรับ ([date, price])
          const history = closes.map((p, i) => [i, p]);
          // ต้องมีอย่างน้อย 22 วันถึงคำนวณ return ~1 เดือนได้ — น้อยกว่านั้น closes[negative
          // index] จะได้ undefined แล้ว undefined-number = NaN ซึ่ง drawSparkline's (retVal||0)
          // ปัดเป็น 0 (>=0) ทำให้หุ้นที่เพิ่งมีประวัติราคาไม่ถึง 22 วัน (เช่น IPO ใหม่) ได้สี
          // sparkline เขียว(ขึ้น)เสมอไม่ว่าราคาจริงจะร่วงแรงแค่ไหนก็ตาม
          const ret = closes.length >= 22 ? (closes[closes.length-1] - closes[closes.length-22]) / closes[closes.length-22] * 100 : null;
          drawSparkline(canvas, history, ret);
        }
      } catch(e) {}
    });
  });
}

// ============================================================
// NAV OPEN MODE — "กดเมนู/กดดูหุ้น แล้วเปิดในหน้าเดิม หรือเปิดแท็บใหม่"
// ------------------------------------------------------------
// ปุ่มสลับอยู่ข้างปุ่มซ่อนเมนู (#nav-openmode-btn) จำค่าไว้ใน localStorage
//   'new' (ค่าเริ่มต้น) = กดเมนู/ปุ่มดูหุ้น แล้วเปิดแท็บใหม่ผ่าน deep-link hash
//   'same'              = พฤติกรรมเดิมทุกอย่าง — กดเมนูแล้วสลับหน้าในแท็บเดียว
// ไม่ว่าโหมดไหน Ctrl/Cmd+click หรือคลิกล้อกลาง = เปิดแท็บใหม่เสมอ (มาตรฐานเบราว์เซอร์)
//
// วิธี intercept เมนู: ดัก click แบบ capture ที่ <nav> แล้ว stopPropagation ก่อน event
// ถึงตัวปุ่ม → inline onclick="showPage(...)" จะไม่ทำงาน จึงไม่ต้องแก้ showPage เลย
// (สำคัญ: showPage ถูกเรียกจากโค้ดภายในอีกสิบกว่าที่ ถ้าไปดักในนั้นจะเด้งแท็บใหม่มั่ว)
// ============================================================
const NAV_OPEN_MODE_KEY = 'nav-open-mode';

function navOpenMode() {
  return localStorage.getItem(NAV_OPEN_MODE_KEY) === 'same' ? 'same' : 'new';
}

function _navOpenModeSync() {
  const b = document.getElementById('nav-openmode-btn');
  if (!b) return;
  const isNew = navOpenMode() === 'new';
  b.textContent = isNew ? '🗗 แท็บใหม่' : '🔗 หน้าเดิม';
  b.classList.toggle('mode-new', isNew);
  b.title = isNew
    ? 'ตอนนี้: กดเมนู/ปุ่มดูหุ้น = เปิดแท็บใหม่ (หน้าเดิมยังคาไว้ ไม่ต้องกดย้อนกลับ)\nกดเพื่อสลับเป็น "เปิดในหน้าเดิม"'
    : 'ตอนนี้: กดเมนู/ปุ่มดูหุ้น = เปลี่ยนหน้าในแท็บเดิม\nกดเพื่อสลับเป็น "เปิดแท็บใหม่"\n(เคล็ดลับ: Ctrl+คลิก เปิดแท็บใหม่ได้เสมอ)';
  if (typeof syncNavHeight === 'function') syncNavHeight();
}

function toggleNavOpenMode() {
  localStorage.setItem(NAV_OPEN_MODE_KEY, navOpenMode() === 'new' ? 'same' : 'new');
  _navOpenModeSync();
}

// เปิด deep-link ภายใน dashboard (เช่น '#fin/dr/NVDA', '#ts/us/AAPL', '#page/screener')
// ตามโหมดที่ผู้ใช้เลือกไว้ — forceNew=true เพื่อบังคับแท็บใหม่ (เช่นกด Ctrl ค้าง)
function openInternalHash(hash, forceNew) {
  if (forceNew || navOpenMode() === 'new') {
    // หมายเหตุ: window.open(...,'noopener') คืนค่า null เสมอตามสเปก ไม่ว่าจะเปิดสำเร็จหรือไม่
    // (noopener ตัดการอ้างอิงกลับมาที่ opener โดยเจตนา) ห้ามใช้ return value เช็คว่าสำเร็จหรือ
    // เปล่าแล้ว fallback ไปหน้าเดิม — เคยลองแล้วทำให้แท็บเดิมโดนลากตามไปหน้าปลายทางด้วยทุกครั้ง
    // ทั้งที่แท็บใหม่เปิดถูกต้องอยู่แล้ว (แท็บเดิมควรอยู่ที่เดิมตามที่โหมด "แท็บใหม่" ออกแบบไว้)
    window.open(location.pathname + location.search + hash, '_blank', 'noopener');
    return;
  }
  // กดหุ้นตัวเดิมซ้ำ: hash ไม่เปลี่ยน → hashchange ไม่ยิง ต้องกระตุ้นเอง
  if (location.hash === hash) window.dispatchEvent(new HashChangeEvent('hashchange'));
  else location.hash = hash;
}

// URL hash deep-link ของ "หน้า" ธรรมดา: #page/screener — ใช้ตอนเปิดเมนูเป็นแท็บใหม่
// (deep-link รายหุ้นมี #fin/ #ts/ #stock/ อยู่แล้ว ดูท้ายไฟล์)
// id เก่าของ 6 เมนูที่รวมเข้า "หุ้นทั้งหมด" แล้ว (ดู setStocksView/setStocksMode) —
// hash แบบนี้ยังถูกสร้างจริงทุกครั้งที่คลิก nav ตอน nav-open-mode = "เปิดแท็บใหม่" (ดีฟอลต์)
// ต้อง alias ไม่งั้น tab/bookmark เก่าจะเงียบไปเฉยๆ (page-<id> เดิมไม่มีแล้ว)
const _STOCKS_PAGE_ALIAS = {
  'rs-leaders': 'rs80', stage: 'stage2', breakout: 'breakout', momentum: 'momentum', sectors: null,
};
// id เก่าของหน้าที่ถูกยุบรวมเข้าหน้าอื่นแบบ 1:1 (ไม่มี view/mode ย่อยให้ตั้งเหมือน stocks) —
// ต้อง alias เหมือนกัน ไม่งั้น tab/bookmark เก่าจะเงียบไปเฉยๆ (page-<id> เดิมไม่มีแล้ว)
const _PAGE_ID_ALIAS = { fcfyield: 'screener', fundamentals: 'screener' };
// id เก่าของ 3 หน้า Heatmap ตลาดต่างประเทศ ที่รวมเข้า page-heatmap (แท็บเลือกตลาด) แล้ว
const _HM_PAGE_ALIAS = { 'us-heatmap': 'US', 'hk-heatmap': 'HK', 'jp-heatmap': 'JP' };
// id เก่าของ 4 หน้า Rotation รายหุ้น ที่รวมเข้า page-stock-rotation (แท็บเลือกตลาด) แล้ว
const _SR_PAGE_ALIAS = { 'dr-rotation': 'TH', 'us-rotation': 'US', 'hk-rotation': 'HK', 'jp-rotation': 'JP' };

function _pageApplyHash() {
  const m = location.hash.match(/^#page\/([\w-]+)$/);
  if (!m) return;
  let id = m[1];
  let stocksView = null, stocksMode = null;
  if (id === 'ema-breadth') { id = 'stocks'; stocksMode = 'sectors'; }
  else if (id in _PAGE_ID_ALIAS) { id = _PAGE_ID_ALIAS[id]; }
  else if (id in _STOCKS_PAGE_ALIAS) {
    id = 'stocks';
    if (_STOCKS_PAGE_ALIAS[m[1]] === null) stocksMode = 'sectors'; else stocksView = _STOCKS_PAGE_ALIAS[m[1]];
  }
  else if (id in _HM_PAGE_ALIAS) {
    _hmMarket = _HM_PAGE_ALIAS[id]; id = 'heatmap';
    // แท็บตลาด US/HK/JP ในหน้ารวมถูกซ่อนด้วย CSS .static-mode (ดู dashboard.css) — ถ้า hash
    // เก่าชี้มาที่ตลาดที่ถูกซ่อนอยู่ ให้เงียบเหมือนตอนก่อนรวมที่ nav-btn ทั้งปุ่มถูกซ่อน
    const tabBtn = document.getElementById('hm-tab-' + _hmMarket.toLowerCase());
    if (tabBtn && getComputedStyle(tabBtn).display === 'none') return;
  }
  else if (id in _SR_PAGE_ALIAS) {
    _srMarket = _SR_PAGE_ALIAS[id]; id = 'stock-rotation';
    const tabBtn = document.getElementById('sr-tab-' + _srMarket.toLowerCase());
    if (tabBtn && getComputedStyle(tabBtn).display === 'none') return;
  }
  if (!document.getElementById('page-' + id)) return;
  const btn = document.querySelector(`.nav-btn[onclick*="'${id}'"]`);
  // เว็บ static (GitHub Pages) ซ่อนปุ่ม nav ของหน้า local-only ไว้ด้วย CSS (.static-mode)
  // แต่ hash นี้เรียก showPage() ตรงๆ ข้าม CSS guard ได้ — ถ้า hash ค้าง/แชร์ลิงก์มาเปิดหน้า
  // ที่ควรถูกซ่อนแล้วเจอ error แทน กันด้วยการเช็คว่าปุ่มนี้ถูกซ่อนอยู่หรือไม่ก่อนเปิด
  if (btn && getComputedStyle(btn).display === 'none') return;
  showPage(id, btn);
  if (stocksMode) setStocksMode(stocksMode);
  if (stocksView) {
    const viewBtn = document.querySelector(`#stocks-view-btns .filter-btn[data-view="${stocksView}"]`);
    setStocksView(stocksView, viewBtn);
  }
}

(function _navOpenModeInit() {
  const boot = () => {
    _navOpenModeSync();
    const nav = document.querySelector('nav');
    if (nav) {
      nav.addEventListener('click', e => {
        const btn = e.target.closest('.nav-btn');
        if (!btn || !nav.contains(btn)) return;
        const forceNew = e.ctrlKey || e.metaKey || e.button === 1;
        if (!forceNew && navOpenMode() !== 'new') return;   // โหมดหน้าเดิม = ปล่อยผ่านตามปกติ
        const m = (btn.getAttribute('onclick') || '').match(/showPage\(\s*['"]([\w-]+)['"]/);
        if (!m) return;
        e.preventDefault();
        e.stopPropagation();      // กัน inline onclick ของปุ่มไม่ให้ทำงาน (capture phase)
        window.open(location.pathname + location.search + '#page/' + m[1], '_blank', 'noopener');
      }, true);
    }
    if (location.hash.startsWith('#page/')) _pageApplyHash();
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  window.addEventListener('hashchange', _pageApplyHash);
})();

// ============================================================
// NAV
// ============================================================
function showPage(id, btn) {
  document.querySelectorAll(".page").forEach(p => p.classList.remove("active"));
  document.querySelectorAll(".nav-btn").forEach(b => b.classList.remove("active"));
  document.getElementById("page-"+id).classList.add("active");
  if (btn) btn.classList.add("active");
  // Re-draw canvas charts once the page is visible and has real dimensions
  if (id === "stocks")         { loadBreadthCharts(); if (_stocksMode === 'sectors') { renderSectors(); renderEMABreadth(); } }
  if (id === "rotation")       renderRotation();
  if (id === "heatmap")        setHmMarket(_hmMarket);
  if (id === "stock-rotation") setSrMarket(_srMarket);
  if (id === "dr")             loadDRPage();
  if (id === "etf")            loadETFPage();
  if (id === "financials")     initFinPage();
  if (id === "market-trend")   loadMarketTrendPage();
  if (id === "us-stocks")      loadUsStocksPage();
  if (id === "hk-stocks")      loadHkStocksPage();
  if (id === "jp-stocks")      loadJpStocksPage();
  if (id === "stock-news")     initNewsPage();
  if (id === "filings")        initFilingsPage();
  if (id === "fscreener")      loadFscreener();
  if (id === "peer")           initPeerPage();
  if (id === "tearsheet")      initTearsheetPage();
  if (id === "calendar")       loadCalendarPage();
  if (id === "band")           loadBandPage();
  if (id === "valuation")      loadValuationPage();
  if (id === "insider")        loadInsiderPage();
  if (id === "short")          loadShortPage();
  if (id === "confluence")     loadConfluencePage();
  if (id === "flow")           loadFlowPage();
  if (id === "indices")        loadIndicesPage();
  if (id === "data-health")    loadDataHealth();
  if (id === "hedge")          loadHedgePage();
  if (id === "dcf-screener")   loadDcfScreenerPage();
  if (id === "pbv-pe-screener") loadPbvPeScreenerPage();
  if (id === "growth-screener") loadGrowthScreenerPage();
  if (id === "overview")       { setTimeout(() => { if (!_nhLoaded) loadNewHighChart(); else _nhDraw(); }, 100); }
}


// ============================================================
// MARKET TREND — 📈 แนวโน้มตลาดย้อนหลัง (ดู /api/market-trend +
// financials_store.get_market_trend ใน backend) สไตล์กราฟ reuse จาก _drawCmFinChart
// (หน้างบการเงิน) ตรงๆ ให้เข้าธีมเดียวกันทั้งแอป
// ============================================================
let _marketTrendData = null;
let _marketTrendLoading = false;
const _mtCharts = {};   // canvasId -> Chart instance (ทำลายทิ้งก่อนวาดใหม่กันซ้อน)

// ข้อมูล sector/หุ้นรายตัว (revenue_yoy/qoq, profit_yoy/qoq) สำหรับตาราง Top 10 เติบโตโดดเด่น
// ด้านล่างกราฟ — reuse /api/sector-compare ตรงๆ (cache 24h เดียวกัน invalidate พร้อมกันตอน sync
// อยู่แล้ว ดู _run_financials_sync ใน app.py) ไม่ต้องเพิ่ม endpoint ใหม่
let _mtSectorData = null;
const _mtGrowthMode = { sectorRevenue: 'yoy', sectorProfit: 'yoy', stockRevenue: 'yoy', stockProfit: 'yoy', stockTurnaround: 'yoy' };

// เส้นบน 2 การ์ดแรก (รายได้รวม / กำไรสุทธิรวม) สลับได้ — การ์ดรายได้: 'yoy'|'qoq' ·
// การ์ดกำไร: 'npm'|'yoy'|'qoq' (default คงพฤติกรรมเดิม) ข้อมูล revenue_qoq/profit_qoq
// มาใน payload /api/market-trend อยู่แล้ว (ดู financials_store.get_market_trend)
let _mtRevLineMode = 'yoy';
let _mtProfitLineMode = 'npm';
let _mtSectorLoading = false;
// คำบรรยายใต้หัวข้อ (#mt-updated) ฉบับตั้งต้นจาก HTML — เก็บครั้งเดียวตอนเรียกครั้งแรก ก่อนถูก
// เขียนทับเป็น "กำลังรวม..."/"โหลดไม่ได้..." ไม่งั้นรอบที่โหลดล้มเหลวจะทำให้รอบถัดไปที่สำเร็จ
// "คืนค่า" ข้อความ error ค้างไว้แทนคำบรรยายจริง
let _mtOrigSub = null;
const _MT_THB_FMT = v => v == null ? '' : (Math.round(v / 1e6)).toLocaleString('en-US') + ' ลบ.';
const _MT_PCT_FMT = v => v == null ? '' : (v > 0 ? '+' : '') + v.toFixed(1) + '%';
const _MT_NPM_FMT = v => v == null ? '' : v.toFixed(1) + '%';
const _MT_RATIO_FMT = v => v == null ? '' : v.toFixed(2) + 'x';

async function loadMarketTrendPage() {
  const sub = document.getElementById('mt-updated');
  if (_mtOrigSub == null && sub) _mtOrigSub = sub.textContent;
  if (_marketTrendData) { _renderMarketTrend(); _mtLoadSectorData(); return; }
  if (_marketTrendLoading) return;
  _marketTrendLoading = true;
  if (sub) sub.textContent = 'กำลังรวมข้อมูลย้อนหลังทั้งตลาด... (ครั้งแรกอาจช้า ~20-30 วิ)';
  try {
    const res = await _fetchTimeout('/api/market-trend?t=' + Date.now(), 45000,
      'หมดเวลารอข้อมูล (เกิน 45 วิ) — เซิร์ฟเวอร์กำลังรวมข้อมูลทั้งตลาด (ครั้งแรกหลัง restart/sync อาจช้า) ลองใหม่อีกครั้ง');
    const d = await res.json();
    if (d.error) throw new Error(d.error);
    _marketTrendData = d;
    if (sub) sub.textContent = _mtOrigSub;
    _renderMarketTrend();
  } catch (e) {
    if (sub) sub.textContent = `โหลดไม่ได้: ${e.message}`;
    _marketTrendLoading = false;
    return;
  }
  _marketTrendLoading = false;
  _mtLoadSectorData();
}

// ตาราง Top 10 แยก fetch เป็นอิสระจากกราฟหลัก — timeout/พังที่นี่ไม่ควรทำให้กราฟหลักที่โหลด
// สำเร็จแล้วหายไปด้วย · เรียกได้ทุกครั้งที่เข้าหน้า (รวม cache-hit path) เพื่อ retry ถ้ารอบก่อน
// โหลด sector ไม่สำเร็จ — วาดเฉพาะตาราง ไม่ rebuild กราฟทั้ง 6 ใบซ้ำ
async function _mtLoadSectorData() {
  if (_mtSectorData || _mtSectorLoading) return;
  _mtSectorLoading = true;
  try {
    const secRes = await _fetchTimeout('/api/sector-compare?t=' + Date.now(), 45000,
      'หมดเวลารอข้อมูล Top 10 เติบโต (เกิน 45 วิ)');
    const sd = await secRes.json();
    if (!sd.error) { _mtSectorData = sd; _mtRenderGrowthTables(); }
  } catch (e2) { /* ตาราง Top 10 พังไม่ควรทำให้กราฟหลักพังตาม */ }
  _mtSectorLoading = false;
}

function _mtQuarterLabel(q) {
  const [y, qn] = (q || '').split('-');
  return y ? `${qn}Q${y.slice(-2)}` : '—';
}

function _mtDestroy(id) {
  if (_mtCharts[id]) { _mtCharts[id].destroy(); delete _mtCharts[id]; }
}

const _MT_TICK_COLOR = '#8b949e', _MT_GRID_COLOR = '#1e2736';
const _MT_TOOLTIP_BASE = {
  backgroundColor: '#1c2128', borderColor: '#30363d', borderWidth: 1,
  titleColor: '#e6edf3', bodyColor: '#8b949e',
  footerColor: '#6e7681', footerFont: { size: 10, weight: 'normal' }, footerMarginTop: 6,
};

// footer callback ร่วม — โชว์ "บริษัทที่มีข้อมูล: N" ต่อจุด (จาก *_coverage ใน payload
// /api/market-trend) ตามที่ tooltip help บนหน้าสัญญาไว้ · cov = array ยาวเท่า labels หรือ undefined
function _mtCoverageFooter(cov) {
  if (!cov) return undefined;
  return items => {
    const i = items && items.length ? items[0].dataIndex : null;
    return (i != null && cov[i] != null) ? `บริษัทที่มีข้อมูล: ${cov[i]}` : '';
  };
}

// กราฟแท่ง+เส้น 2 แกน (รายได้/กำไร) — โครงเดียวกับ _drawCmFinChart (dashboard.js ~11912)
function _mtDrawBarLine(canvasId, labels, barVals, lineVals, barLabel, lineLabel, barColor, lineFmt, barFmt, coverage) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  _mtDestroy(canvasId);
  _mtCharts[canvasId] = new Chart(canvas, {
    data: {
      labels,
      datasets: [
        { type: 'bar', label: barLabel, data: barVals, backgroundColor: barColor + 'd9',
          borderColor: barColor, borderWidth: 1, borderRadius: 4, yAxisID: 'yBar', order: 2 },
        { type: 'line', label: lineLabel, data: lineVals, borderColor: '#e8b84b',
          backgroundColor: 'rgba(232,184,75,0.15)', borderWidth: 2.5, pointRadius: 3,
          pointHoverRadius: 6, tension: 0.25, yAxisID: 'yLine', order: 1, spanGaps: true },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { labels: { color: _MT_TICK_COLOR, font: { size: 11 }, boxWidth: 14, padding: 16 } },
        tooltip: { ...(_MT_TOOLTIP_BASE), callbacks: {
          label: ctx => ctx.raw == null ? null
            : ctx.dataset.yAxisID === 'yBar' ? ` ${barLabel}: ${barFmt(ctx.raw)}`
            : ` ${lineLabel}: ${lineFmt(ctx.raw)}`,
          footer: _mtCoverageFooter(coverage),
        } }
      },
      scales: {
        x: { ticks: { color: _MT_TICK_COLOR, font: { size: 11 } }, grid: { color: _MT_GRID_COLOR } },
        yBar:  { position: 'left',  ticks: { color: _MT_TICK_COLOR, font: { size: 11 }, callback: barFmt }, grid: { color: _MT_GRID_COLOR } },
        yLine: { position: 'right', ticks: { color: _MT_TICK_COLOR, font: { size: 11 }, callback: lineFmt }, grid: { display: false } },
      }
    }
  });
}

// กราฟเส้นคู่แกนเดียว (Aggregate vs Median) — ROE / Margin Trend / Cash Quality
function _mtDrawDualLine(canvasId, labels, seriesA, seriesB, labelA, labelB, colorA, colorB, fmt, coverage) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  _mtDestroy(canvasId);
  _mtCharts[canvasId] = new Chart(canvas, {
    type: 'line',
    data: {
      labels,
      datasets: [
        { label: labelA, data: seriesA, borderColor: colorA, backgroundColor: colorA + '26',
          borderWidth: 2.5, pointRadius: 3, pointHoverRadius: 6, tension: 0.25, spanGaps: true },
        { label: labelB, data: seriesB, borderColor: colorB, backgroundColor: colorB + '26',
          borderWidth: 2.5, pointRadius: 3, pointHoverRadius: 6, tension: 0.25, spanGaps: true },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { labels: { color: _MT_TICK_COLOR, font: { size: 11 }, boxWidth: 14, padding: 16 } },
        tooltip: { ...(_MT_TOOLTIP_BASE), callbacks: {
          label: ctx => ctx.raw == null ? null : ` ${ctx.dataset.label}: ${fmt(ctx.raw)}`,
          footer: _mtCoverageFooter(coverage),
        } }
      },
      scales: {
        x: { ticks: { color: _MT_TICK_COLOR, font: { size: 11 } }, grid: { color: _MT_GRID_COLOR } },
        y: { ticks: { color: _MT_TICK_COLOR, font: { size: 11 }, callback: fmt }, grid: { color: _MT_GRID_COLOR } },
      }
    }
  });
}

// กราฟ Market Breadth — 3 เส้น % (แกนซ้าย 0-100) + 2 เส้นจำนวนหุ้น (แกนขวา)
function _mtDrawBreadth(canvasId, labels, q) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  _mtDestroy(canvasId);
  const pctFmt = v => v == null ? '' : v.toFixed(0) + '%';
  const cntFmt = v => v == null ? '' : String(Math.round(v));
  const mk = (label, data, color, axis) => ({
    label, data, borderColor: color, backgroundColor: color + '00', borderWidth: 2,
    pointRadius: 2, pointHoverRadius: 5, tension: 0.25, spanGaps: true, yAxisID: axis
  });
  _mtCharts[canvasId] = new Chart(canvas, {
    type: 'line',
    data: {
      labels,
      datasets: [
        mk('รายได้โต %',   q.map(x => x.pct_revenue_growing), '#58a6ff', 'yPct'),
        mk('กำไรโต %',     q.map(x => x.pct_profit_growing),  '#3fb950', 'yPct'),
        mk('CFO บวก %',    q.map(x => x.pct_cfo_positive),    '#e8b84b', 'yPct'),
        mk('พลิกกำไร (ตัว)', q.map(x => x.flipped_profit), '#a371f7', 'yCnt'),
        mk('พลิกขาดทุน (ตัว)', q.map(x => x.flipped_loss), '#f85149', 'yCnt'),
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { labels: { color: _MT_TICK_COLOR, font: { size: 11 }, boxWidth: 14, padding: 16 } },
        tooltip: { ...(_MT_TOOLTIP_BASE), callbacks: {
          label: ctx => ctx.raw == null ? null
            : ` ${ctx.dataset.label}: ${ctx.dataset.yAxisID === 'yPct' ? pctFmt(ctx.raw) : cntFmt(ctx.raw)}`
        } }
      },
      scales: {
        x: { ticks: { color: _MT_TICK_COLOR, font: { size: 11 } }, grid: { color: _MT_GRID_COLOR } },
        yPct: { position: 'left',  min: 0, max: 100, ticks: { color: _MT_TICK_COLOR, font: { size: 11 }, callback: pctFmt }, grid: { color: _MT_GRID_COLOR } },
        yCnt: { position: 'right', min: 0, ticks: { color: _MT_TICK_COLOR, font: { size: 11 }, callback: cntFmt }, grid: { display: false } },
      }
    }
  });
}

// การ์ด "รายได้รวม" — แท่ง = รายได้ระดับ · เส้น = อัตราเติบโต YoY หรือ QoQ (สลับด้วยปุ่ม)
function _mtDrawRevenueChart() {
  const q = _marketTrendData?.quarters || [];
  if (!q.length) return;
  const labels = q.map(x => _mtQuarterLabel(x.quarter));
  const qoq = _mtRevLineMode === 'qoq';
  _mtDrawBarLine('mt-chart-revenue', labels, q.map(x => x.revenue),
    q.map(x => qoq ? x.revenue_qoq : x.revenue_yoy),
    'รายได้', qoq ? 'QoQ' : 'YoY', '#1f6feb', _MT_PCT_FMT, _MT_THB_FMT,
    q.map(x => x.revenue_coverage));
}

// การ์ด "กำไรสุทธิรวม + NPM" — แท่ง = กำไรระดับ · เส้น = NPM (default) หรืออัตราเติบโต YoY/QoQ
function _mtDrawProfitChart() {
  const q = _marketTrendData?.quarters || [];
  if (!q.length) return;
  const labels = q.map(x => _mtQuarterLabel(x.quarter));
  const m = _mtProfitLineMode;
  const lineVals = m === 'npm' ? q.map(x => x.npm)
                 : m === 'qoq' ? q.map(x => x.profit_qoq)
                 : q.map(x => x.profit_yoy);
  const lineLabel = m === 'npm' ? 'Aggregate NPM' : m === 'qoq' ? 'กำไร QoQ' : 'กำไร YoY';
  const lineFmt = m === 'npm' ? _MT_NPM_FMT : _MT_PCT_FMT;
  _mtDrawBarLine('mt-chart-profit', labels, q.map(x => x.profit), lineVals,
    'กำไรสุทธิ', lineLabel, '#3fb950', lineFmt, _MT_THB_FMT,
    q.map(x => x.profit_coverage));
}

// สลับโหมดเส้นของการ์ดรายได้/กำไร แล้ววาดเฉพาะการ์ดนั้นใหม่ (pattern เดียวกับ _mtSetGrowthMode)
function _mtSetLineMode(which, mode, btn) {
  if (which === 'rev') _mtRevLineMode = mode; else _mtProfitLineMode = mode;
  if (btn && btn.parentElement) {
    btn.parentElement.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
  }
  if (which === 'rev') _mtDrawRevenueChart(); else _mtDrawProfitChart();
}

function _renderMarketTrend() {
  if (!_marketTrendData) return;
  const q = _marketTrendData.quarters || [];
  if (!q.length) return;
  const labels = q.map(x => _mtQuarterLabel(x.quarter));

  _mtDrawRevenueChart();
  _mtDrawProfitChart();
  _mtDrawDualLine('mt-chart-roe', labels, q.map(x => x.roe_aggregate), q.map(x => x.roe_median),
    'Aggregate ROE', 'Median ROE', '#58a6ff', '#e8b84b', _MT_NPM_FMT, q.map(x => x.roe_coverage));
  _mtDrawDualLine('mt-chart-margin', labels, q.map(x => x.npm), q.map(x => x.npm_median),
    'Aggregate NPM', 'Median NPM', '#3fb950', '#f85149', _MT_NPM_FMT, q.map(x => x.revenue_coverage));
  _mtDrawDualLine('mt-chart-cashquality', labels, q.map(x => x.cfo_np_aggregate), q.map(x => x.cfo_np_median),
    'Aggregate CFO/NP', 'Median CFO/NP', '#58a6ff', '#e8b84b', _MT_RATIO_FMT, q.map(x => x.cfo_np_coverage));
  _mtDrawBreadth('mt-chart-breadth', labels, q);
  _mtRenderGrowthTables();
}

// TOP 10 เติบโตโดดเด่น — ไตรมาสล่าสุด (Sector + หุ้นรายตัว, รายได้/กำไร, QoQ/YoY แยกการ์ด
// สลับได้ด้วยปุ่ม) ข้อมูลมาจาก /api/sector-compare (financials_store.get_sector_qpl_compare)
// ตัวเดียวกับหน้า "⚖ เปรียบเทียบ Sector" — sectors[].revenue_yoy/qoq/profit_yoy/qoq คือ aggregate
// ต่อ sector, sectors[].stocks[] คือรายตัวที่มีงวดล่าสุดแล้ว (มี field เดียวกันต่อหุ้น)
const _mtMedal = i => (i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i + 1}.`);

function _mtSetGrowthMode(key, mode, btn) {
  _mtGrowthMode[key] = mode;
  if (btn && btn.parentElement) {
    btn.parentElement.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
  }
  _mtRenderGrowthTables();
}

function _mtSectorGrowthRows(field) {
  return (_mtSectorData?.sectors || [])
    .filter(s => s[field] != null && s.count > 0)
    .sort((a, b) => b[field] - a[field])
    .slice(0, 10);
}

// ฐานกำไรงวดก่อนขั้นต่ำ (บาท) สำหรับตาราง "หุ้นกำไรโตเด่น" เท่านั้น — กันหุ้นที่กำไรงวดก่อนจิ๋ว
// (เช่น 1 ล้านบาท) โต% หลอกจนแซง Top 10 ทั้งที่ตัวเงินจริงเล็กมาก ไม่ใช้กับรายได้ (ฐานรายได้ไม่ค่อย
// จิ๋วขนาดนั้น) และไม่ใช้กับตาราง Sector (ฐานเป็นผลรวมทั้งกลุ่ม ใหญ่พอเป็นทุนเดิมอยู่แล้ว)
const _MT_PROFIT_GROWTH_MIN_BASE = 50_000_000;

function _mtStockGrowthRows(field) {
  const isProfitGrowth = field.startsWith('profit_');
  const priorKey = field.endsWith('_qoq') ? 'profit_prior_qoq' : 'profit_prior';
  const rows = [];
  for (const s of (_mtSectorData?.sectors || [])) {
    for (const st of (s.stocks || [])) {
      if (st[field] == null) continue;
      if (isProfitGrowth && !(st[priorKey] > _MT_PROFIT_GROWTH_MIN_BASE)) continue;
      rows.push({ ...st, sector: s.sector });
    }
  }
  rows.sort((a, b) => b[field] - a[field]);
  return rows.slice(0, 20);   // โชว์ 20 ตัว — 10 แรกเห็นเลย อีก 10 เลื่อนดูใน .mini-tbl-scroll
}

function _mtRenderSectorGrowthTable(containerId, field) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const rows = _mtSectorGrowthRows(field);
  if (!rows.length) { el.innerHTML = '<div class="text2" style="padding:8px 0;font-size:12px">ไม่มีข้อมูล</div>'; return; }
  el.innerHTML = `<table class="tbl" style="min-width:280px">
    <thead><tr><th></th><th>Sector</th><th class="r">โต</th><th class="r">งบครบ</th></tr></thead>
    <tbody>${rows.map((s, i) => `<tr>
      <td>${_mtMedal(i)}</td>
      <td>${s.sector}</td>
      <td class="r">${pct(s[field], 1)}</td>
      <td class="r text2">${s.reported}/${s.total}</td>
    </tr>`).join('')}</tbody></table>`;
}

function _mtRenderStockGrowthTable(containerId, field) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const rows = _mtStockGrowthRows(field);
  if (!rows.length) { el.innerHTML = '<div class="text2" style="padding:8px 0;font-size:12px">ไม่มีข้อมูล</div>'; return; }
  el.innerHTML = `<table class="tbl" style="min-width:280px">
    <thead><tr><th></th><th>หุ้น</th><th>Sector</th><th class="r">โต</th></tr></thead>
    <tbody>${rows.map((s, i) => `<tr>
      <td>${_mtMedal(i)}</td>
      <td><b class="sym-link" onclick="openChartModal('${s.symbol}')">${s.symbol}</b>${tvLink(s.symbol)}</td>
      <td class="text2">${s.sector}</td>
      <td class="r">${pct(s[field], 1)}</td>
    </tr>`).join('')}</tbody></table>`;
}

// หุ้นพลิกกำไร (งวดก่อนขาดทุน/เท่ากับศูนย์ -> งวดนี้กำไร) — แยกจากตาราง "หุ้นกำไรโตเด่น" เพราะ
// profit_yoy/qoq เป็น None เสมอตอนฐานเทียบติดลบ (ดู _stock_yoy ใน financials_store.py — หารด้วย
// ฐานติดลบพลิกเครื่องหมาย % กลายเป็นค่าหลอก) เรียงด้วยขนาดการพลิกเป็นบาทแทน % ที่ไม่มีความหมาย
function _mtStockTurnaroundRows(mode) {
  const priorKey = mode === 'qoq' ? 'profit_prior_qoq' : 'profit_prior';
  const rows = [];
  for (const s of (_mtSectorData?.sectors || [])) {
    for (const st of (s.stocks || [])) {
      const prior = st[priorKey];
      if (prior != null && prior <= 0 && st.net_profit != null && st.net_profit > 0) {
        rows.push({ ...st, sector: s.sector, prior, swing: st.net_profit - prior });
      }
    }
  }
  rows.sort((a, b) => b.swing - a.swing);
  return rows.slice(0, 20);   // โชว์ 20 ตัว — 10 แรกเห็นเลย อีก 10 เลื่อนดูใน .mini-tbl-scroll
}

function _mtRenderTurnaroundTable(containerId, mode) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const rows = _mtStockTurnaroundRows(mode);
  if (!rows.length) { el.innerHTML = '<div class="text2" style="padding:8px 0;font-size:12px">ไม่มีข้อมูล</div>'; return; }
  const thbFmt = v => v == null ? '—' : (Math.round(v / 1e6)).toLocaleString('en-US') + ' ลบ.';
  el.innerHTML = `<table class="tbl" style="min-width:420px">
    <thead><tr><th></th><th>หุ้น</th><th>Sector</th><th class="r">ไตรมาสก่อน</th><th class="r">ไตรมาสนี้</th></tr></thead>
    <tbody>${rows.map((s, i) => `<tr>
      <td>${_mtMedal(i)}</td>
      <td><b class="sym-link" onclick="openChartModal('${s.symbol}')">${s.symbol}</b>${tvLink(s.symbol)}</td>
      <td class="text2">${s.sector}</td>
      <td class="r red">${thbFmt(s.prior)}</td>
      <td class="r green">${thbFmt(s.net_profit)}</td>
    </tr>`).join('')}</tbody></table>`;
}

function _mtRenderGrowthTables() {
  if (!_mtSectorData) return;
  const title = document.getElementById('mt-growth-title');
  if (title) {
    const q = _mtQuarterLabel(_mtSectorData.quarter);
    title.textContent = `🏆 Top 10 เติบโตโดดเด่น ไตรมาส ${q}`;
  }
  _mtRenderSectorGrowthTable('mt-tbl-sectorRevenue', 'revenue_' + _mtGrowthMode.sectorRevenue);
  _mtRenderSectorGrowthTable('mt-tbl-sectorProfit', 'profit_' + _mtGrowthMode.sectorProfit);
  _mtRenderStockGrowthTable('mt-tbl-stockRevenue', 'revenue_' + _mtGrowthMode.stockRevenue);
  _mtRenderStockGrowthTable('mt-tbl-stockProfit', 'profit_' + _mtGrowthMode.stockProfit);
  _mtRenderTurnaroundTable('mt-tbl-stockTurnaround', _mtGrowthMode.stockTurnaround);
}


// ============================================================
// DCF SCREENER — DCF Model (พยากรณ์เต็มรูปแบบ) รันวนทุกหุ้นไทยที่คำนวณได้
// ดู sources/dcf_screener.py + routes /api/dcf-screener* ใน app.py — สูตรเดียวกับ
// _tsDcfModelRecalc ด้านบน (WACC โหมด 'คำนวณให้' เป็นค่าเริ่มต้น, Beta=1.00 คงที่ทุกตัว — แต่
// กรอกช่อง "WACC override" (DCF_SCR_OPTIONAL_FIELDS) ได้เพื่อบังคับ WACC ตรงๆ ทั้งตลาด ข้าม
// CAPM/capital structure ทั้งหมด ดู compute_dcf_for_symbol) พอร์ตไป Python
// แล้วรันเป็น batch คนละชุดโค้ดกัน ไม่ได้ derive จากตารางหน้า Tearsheet ตรงๆ — คำนวณฝั่ง server
// ล้วนๆ หน้านี้แค่ fetch ผลลัพธ์ที่ cache ไว้แล้วมาแสดง/กรอง/เรียงเท่านั้น
// ============================================================
let _dcfScreenerData = null;
// เรียงตาม upside% มาก->น้อยเป็นค่าเริ่มต้น — กดหัวตารางเปลี่ยนได้ (asc/desc สลับกันทุกครั้งที่กด
// คอลัมน์เดิมซ้ำ, กดคอลัมน์ใหม่เริ่มที่ desc เสมอยกเว้นชื่อ/ticker ที่เริ่ม asc เพราะเรียง A-Z อ่านง่ายกว่า)
let _dcfScrSort = { key: 'upside_pct', dir: 'desc' };
// |upside%| เกินนี้ = เตือน ⚠️ ในตาราง (ดู renderDcfScreener) — ค่าเดียวกับข้อความอธิบายท้ายตาราง
const DCF_SCR_EXTREME_UPSIDE_PCT = 300;
const DCF_SCR_COLS = [
  { key: 'symbol', label: 'หุ้น', align: 'left' },
  { key: 'name', label: 'ชื่อ', align: 'left' },
  { key: 'price', label: 'ราคา', align: 'right' },
  { key: 'intrinsic', label: 'มูลค่าเหมาะสม', align: 'right' },
  { key: 'upside_pct', label: 'Upside', align: 'right' },
  { key: 'wacc_pct', label: 'WACC', align: 'right' },
  { key: 'g13_pct', label: 'Growth ปี1-3', align: 'right' },
];

function loadDcfScreenerPage() {
  if (_dcfScreenerData) { renderDcfScreener(); return; }
  fetchDcfScreener();
}

// field ที่ override ทั้งตลาดได้ (เว้นว่าง = ใช้ค่าจริงของหุ้นนั้น) — id ช่อง input คู่กับ key ที่
// ส่งให้ /api/dcf-screener/rebuild (ต้องตรงกับ resolve_assumptions() ใน sources/dcf_screener.py)
const DCF_SCR_OPTIONAL_FIELDS = [
  ['dcf-screener-g13', 'g13_pct'], ['dcf-screener-g45', 'g45_pct'],
  ['dcf-screener-ebitm', 'ebit_margin_pct'], ['dcf-screener-tax', 'tax_rate_pct'],
  ['dcf-screener-da', 'da_pct'], ['dcf-screener-capex', 'capex_pct'],
  ['dcf-screener-nwc', 'nwc_pct'], ['dcf-screener-wacc-override', 'wacc_pct'],
];

function fetchDcfScreener() {
  const box = document.getElementById('dcf-screener-table');
  if (box) box.innerHTML = '<div class="empty">กำลังโหลด...</div>';
  return fetch('/api/dcf-screener').then(r => r.json()).then(d => {
    _dcfScreenerData = d;
    // แสดงสมมติฐานที่ใช้จริงในรอบล่าสุดในช่องกรอก (ไม่ทับช่องที่ผู้ใช้กำลังพิมพ์อยู่)
    const a = d.meta && d.meta.assumptions;
    if (a) {
      const setv = (id, v) => {
        const el = document.getElementById(id);
        if (el && document.activeElement !== el && v != null) el.value = v;
      };
      // ช่อง override: null แปลว่ารอบล่าสุดไม่ได้กรอก (ใช้ค่าจริงของหุ้น) -> เคลียร์ให้ว่างเหมือนกัน
      const setvOpt = (id, v) => {
        const el = document.getElementById(id);
        if (el && document.activeElement !== el) el.value = (v == null ? '' : v);
      };
      setv('dcf-screener-rf', a.rf_pct);
      setv('dcf-screener-beta', a.beta);
      setv('dcf-screener-erp', a.erp_pct);
      setv('dcf-screener-tg', a.terminal_growth_pct);
      setv('dcf-screener-years', a.years);
      DCF_SCR_OPTIONAL_FIELDS.forEach(([id, key]) => setvOpt(id, a[key]));
      const uaEl = document.getElementById('dcf-screener-use-analyst');
      if (uaEl && document.activeElement !== uaEl) uaEl.checked = !!a.use_analyst_growth;
    }
    renderDcfScreener();
  }).catch(() => {
    // เคลียร์ cache เดิมทิ้งด้วย (ไม่ใช่แค่โชว์ error) กันรอบถัดไปที่กลับมาหน้านี้เจอ cache-hit
    // branch ใน loadDcfScreenerPage() แล้วโชว์ข้อมูลเก่าเงียบๆ โดยไม่รู้ว่ารอบล่าสุด fetch ไม่สำเร็จ
    _dcfScreenerData = null;
    if (box) box.innerHTML = '<div class="empty">โหลดข้อมูลไม่สำเร็จ</div>';
  });
}

// ค่าเริ่มต้นเดียวกับ RISK_FREE_PCT/BETA/ERP_PCT/TERMINAL_GROWTH_PCT/FORECAST_YEARS ใน
// sources/dcf_screener.py — ยังต้องแก้คู่กัน 3 ที่ถ้าเปลี่ยนค่าเริ่มต้นฝั่งใดฝั่งหนึ่ง: ค่าคงที่ฝั่ง
// Python นี้, ก้อนนี้ (startDcfScreenerRebuild/resetDcfScreenerAssumptions อ้างจากตรงนี้จุดเดียว
// แล้ว ไม่มี literal ซ้ำอีก), และ value="..."/selected ในฟอร์ม HTML (set_dashboard.html)
const DCF_SCR_DEFAULTS = { rf_pct: 2.5, beta: 1.00, erp_pct: 5.5, terminal_growth_pct: 2.5, years: 5 };

function resetDcfScreenerAssumptions() {
  const el = id => document.getElementById(id);
  el('dcf-screener-rf').value = DCF_SCR_DEFAULTS.rf_pct;
  el('dcf-screener-beta').value = DCF_SCR_DEFAULTS.beta.toFixed(2);
  el('dcf-screener-erp').value = DCF_SCR_DEFAULTS.erp_pct;
  el('dcf-screener-tg').value = DCF_SCR_DEFAULTS.terminal_growth_pct;
  el('dcf-screener-years').value = String(DCF_SCR_DEFAULTS.years);
  // ช่อง override ทั้ง 8 กลับเป็นว่าง = ใช้ค่าจริงของหุ้นนั้น (ไม่มี "ค่าเริ่มต้น" กลางที่ใช้ได้ทุกหุ้น)
  DCF_SCR_OPTIONAL_FIELDS.forEach(([id]) => { const e = el(id); if (e) e.value = ''; });
  const uaEl = el('dcf-screener-use-analyst'); if (uaEl) uaEl.checked = false;
  // แค่รีเซ็ตช่องกรอก ยังไม่คำนวณใหม่ — ให้ผู้ใช้ตรวจค่าก่อนกด ⟳ เอง (เหมือนปุ่ม "คืนค่าเริ่มต้น"
  // ในหน้า Tearsheet ที่ก็ไม่ auto-submit ให้)
}

function startDcfScreenerRebuild() {
  const btn = document.getElementById('dcf-screener-rebuild-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ กำลังคำนวณ...'; }
  const numVal = (id, dflt) => {
    const v = parseFloat(document.getElementById(id)?.value);
    return Number.isFinite(v) ? v : dflt;
  };
  // ว่าง/พิมพ์ไม่ถูก -> null (ไม่ override ทั้งตลาด ใช้ค่าจริงของหุ้นนั้นแทน — ดู resolve_assumptions
  // ฝั่ง server) ต่างจาก numVal ด้านบนที่มี default กลางเสมอ (Rf/Beta/ERP/Terminal Growth)
  const optVal = id => {
    const raw = document.getElementById(id)?.value;
    if (raw == null || String(raw).trim() === '') return null;
    const v = parseFloat(raw);
    return Number.isFinite(v) ? v : null;
  };
  const body = {
    rf_pct: numVal('dcf-screener-rf', DCF_SCR_DEFAULTS.rf_pct),
    beta: numVal('dcf-screener-beta', DCF_SCR_DEFAULTS.beta),
    erp_pct: numVal('dcf-screener-erp', DCF_SCR_DEFAULTS.erp_pct),
    terminal_growth_pct: numVal('dcf-screener-tg', DCF_SCR_DEFAULTS.terminal_growth_pct),
    years: parseInt(document.getElementById('dcf-screener-years')?.value || String(DCF_SCR_DEFAULTS.years), 10),
  };
  DCF_SCR_OPTIONAL_FIELDS.forEach(([id, key]) => { body[key] = optVal(id); });
  body.use_analyst_growth = !!document.getElementById('dcf-screener-use-analyst')?.checked;
  fetch('/api/dcf-screener/rebuild', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  }).then(r => r.json())
    .then(result => {
      // skipped_empty = server เจอ set_data.json ว่าง/อ่านไม่ได้ ข้ามการเขียนทับ ตารางยังเป็นผลรอบก่อน
      // ต้องแจ้งผู้ใช้ตรงๆ ไม่งั้นดูเหมือนคำนวณสำเร็จทั้งที่ยังเป็นข้อมูลเก่า
      if (result && result.skipped_empty) {
        const meta = document.getElementById('dcf-screener-meta');
        if (meta) meta.textContent = 'คำนวณใหม่ไม่สำเร็จ (อ่านรายชื่อหุ้นไม่ได้) — ยังแสดงผลรอบก่อนหน้าอยู่';
        return;
      }
      return fetchDcfScreener();
    })
    .catch(() => {
      const meta = document.getElementById('dcf-screener-meta');
      if (meta) meta.textContent = 'คำนวณไม่สำเร็จ ลองใหม่อีกครั้ง';
    })
    .finally(() => {
      if (btn) { btn.disabled = false; btn.textContent = '⟳ คำนวณ DCF ใหม่ทั้งตลาด'; }
    });
}

function _dcfScrSetSort(key) {
  if (_dcfScrSort.key === key) {
    _dcfScrSort.dir = _dcfScrSort.dir === 'desc' ? 'asc' : 'desc';
  } else {
    _dcfScrSort.key = key;
    _dcfScrSort.dir = (key === 'symbol' || key === 'name') ? 'asc' : 'desc';
  }
  renderDcfScreener();
}

// ใช้ร่วมกันทั้งตอน render ตารางและตอน export CSV — export เอาแถวที่กรอง/เรียงตามที่เห็นบนจอ
function _dcfScrFilteredSorted() {
  const d = _dcfScreenerData;
  if (!d || !d.rows) return [];
  const q = (document.getElementById('dcf-screener-search')?.value || '').toUpperCase().trim();
  const hideErr = document.getElementById('dcf-screener-hide-na')?.checked;
  let rows = d.rows.filter(r => !q || r.symbol.includes(q) || (r.name || '').toUpperCase().includes(q));
  if (hideErr) rows = rows.filter(r => !r.error);
  const key = _dcfScrSort.key, dir = _dcfScrSort.dir === 'asc' ? 1 : -1;
  rows = rows.slice().sort((a, b) => {
    const av = a[key], bv = b[key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === 'string') return dir * av.localeCompare(bv);
    return dir * (av - bv);
  });
  return rows;
}

function renderDcfScreener() {
  const d = _dcfScreenerData;
  const box = document.getElementById('dcf-screener-table');
  const metaBox = document.getElementById('dcf-screener-meta');
  const countBox = document.getElementById('dcf-screener-count');
  if (!box) return;
  if (!d || !d.rows || !d.rows.length) {
    if (metaBox) metaBox.textContent = 'ยังไม่เคยคำนวณ';
    box.innerHTML = '<div class="empty">ยังไม่มีข้อมูล กดปุ่ม "⟳ คำนวณ DCF ใหม่ทั้งตลาด" ด้านบนก่อน</div>';
    return;
  }
  if (metaBox) {
    const a = d.meta.assumptions || {};
    const overrideCount = DCF_SCR_OPTIONAL_FIELDS.filter(([, key]) => a[key] != null).length;
    metaBox.innerHTML = `คำนวณล่าสุด ${d.meta.computed_at || '—'} · คำนวณได้ ${d.meta.ok_count}/${d.meta.count} ตัว`
      + (a.rf_pct != null ? ` · Rf ${a.rf_pct}% · β ${a.beta} · ERP ${a.erp_pct}% · TG ${a.terminal_growth_pct}% · ${a.years} ปี` : '')
      + (a.use_analyst_growth ? ' · 🎯 Growth ปี1-3 = ประมาณการนักวิเคราะห์ (Yahoo)' : '')
      + (overrideCount > 0 ? ` · กำหนดเองทั้งตลาด ${overrideCount} ช่อง` : '')
      + _finStaleBadge(d.meta.stale, 'กด ⟳ คำนวณใหม่');
  }
  const rows = _dcfScrFilteredSorted();
  if (countBox) countBox.textContent = `${rows.length} ตัว`;
  if (!rows.length) { box.innerHTML = '<div class="empty">ไม่พบหุ้นตรงเงื่อนไข</div>'; return; }

  const rowsHtml = rows.map(r => {
    const symHtml = _escHtml(r.symbol);
    if (r.error) {
      return `<tr style="opacity:.55">
        <td><a href="#" onclick="openInternalHash('#ts/th/${encodeURIComponent(r.symbol)}');return false">${symHtml}</a>${tvLink(r.symbol)}</td>
        <td>${_escHtml(r.name || '')}</td>
        <td colspan="5" style="color:var(--text2)">— ${_escHtml(r.error)}</td>
      </tr>`;
    }
    const up = r.upside_pct;
    // upside เท่ากับ 0 พอดี (มูลค่าเหมาะสม = ราคาตลาดเป๊ะ) ควรเป็นสีกลาง ไม่ใช่แดง (bearish)
    // เหมือน pattern สีอื่นในไฟล์นี้ เช่น d1>0?green:d1<0?red:text2
    const color = up > 0 ? 'var(--green)' : (up < 0 ? 'var(--red)' : 'var(--text2)');
    // ผลลัพธ์เกิน ±300% ส่วนใหญ่มาจาก denominator ราคาเล็ก/หนี้-เงินสดผิดปกติ ไม่ใช่ signal จริง —
    // เตือนแทนการซ่อน (ยังอยากให้เห็นแถวไว้เผื่ออยากตรวจสอบเอง)
    const extreme = Math.abs(up) > DCF_SCR_EXTREME_UPSIDE_PCT;
    return `<tr>
      <td><a href="#" onclick="openInternalHash('#ts/th/${encodeURIComponent(r.symbol)}');return false">${symHtml}</a>${tvLink(r.symbol)}</td>
      <td>${_escHtml(r.name || '')}</td>
      <td style="text-align:right">${r.price != null ? r.price.toFixed(2) : '—'}</td>
      <td style="text-align:right">${r.intrinsic != null ? r.intrinsic.toFixed(2) : '—'}</td>
      <td style="text-align:right;font-weight:700;color:${color}">${up != null ? (up > 0 ? '+' : '') + up.toFixed(1) + '%' : '—'}${extreme ? ' ⚠️' : ''}</td>
      <td style="text-align:right">${r.wacc_pct != null ? r.wacc_pct.toFixed(2) + '%' : '—'}</td>
      <td style="text-align:right">${r.g13_pct != null ? r.g13_pct.toFixed(1) + '%' : '—'}${r.g_source === 'analyst' ? ' <span title="ใช้ประมาณการโตของนักวิเคราะห์ (Yahoo)" style="color:var(--blue)">🎯</span>' : ''}</td>
    </tr>`;
  }).join('');
  const headHtml = DCF_SCR_COLS.map(c => {
    const arrow = _dcfScrSort.key === c.key ? (_dcfScrSort.dir === 'desc' ? ' ▼' : ' ▲') : '';
    return `<th style="text-align:${c.align};cursor:pointer;user-select:none;white-space:nowrap" onclick="_dcfScrSetSort('${c.key}')" title="กดเรียงลำดับ">${c.label}${arrow}</th>`;
  }).join('');
  box.innerHTML = `<div style="overflow-x:auto"><table class="tbl" style="width:100%">
    <thead><tr>${headHtml}</tr></thead>
    <tbody>${rowsHtml}</tbody></table></div>
    <div style="font-size:10.5px;color:var(--text2);margin-top:6px">⚠️ = |upside| เกิน ${DCF_SCR_EXTREME_UPSIDE_PCT}% — ส่วนใหญ่เกิดจากราคาต่อหุ้นเล็กมาก/โครงสร้างหนี้-เงินสดผิดปกติ ไม่ใช่ signal ที่เชื่อถือได้ตรงๆ ควรเปิด Tearsheet ตรวจดูก่อนเสมอ · กดหัวตารางเพื่อเรียงลำดับ</div>`;
}

function exportDcfScreenerCsv() {
  const rows = _dcfScrFilteredSorted();
  if (!rows.length) { alert('ไม่มีข้อมูลให้ export'); return; }
  const csvEsc = v => {
    if (v == null) return '';
    const s = String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const headers = ['Symbol', 'Name', 'Sector', 'Price', 'Intrinsic', 'Upside %', 'WACC %', 'Growth ปี1-3 %', 'Growth source', 'As of', 'Error'];
  const lines = [headers.map(csvEsc).join(',')];
  rows.forEach(r => {
    lines.push([
      r.symbol, r.name || '', r.sector || '',
      r.price ?? '', r.intrinsic ?? '', r.upside_pct ?? '', r.wacc_pct ?? '', r.g13_pct ?? '',
      r.g_source || '', r.as_of || '', r.error || '',
    ].map(csvEsc).join(','));
  });
  const csv = '﻿' + lines.join('\r\n');   // BOM กัน Excel เปิดภาษาไทยเพี้ยน
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const ts = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
  a.href = url;
  a.download = `dcf_screener_${ts}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// ============================================================
// FAIR VALUE P/B·P/E SCREENER — Justified P/B (ROE-based) + Justified P/E รันวนทุกหุ้นไทย
// ดู sources/pbv_pe_screener.py + routes /api/pbv-pe-screener* ใน app.py — สูตร Justified P/B
// mirror ของ _altJustifiedPb() ด้านบน (Tearsheet) พอร์ตไป Python คนละชุดโค้ดกัน · หน้านี้แค่
// fetch ผลลัพธ์ที่ cache ไว้แล้วมาแสดง/กรอง/เรียงเท่านั้น (ไม่คำนวณฝั่ง client)
// ============================================================
let _pbvPeScreenerData = null;
// เรียงตาม Upside P/B มาก->น้อยเป็นค่าเริ่มต้น (Justified P/B = เป้าหมายหลักของหน้านี้ ตาม memory
// pbv-pe-screener-plan) — กดหัวตารางเปลี่ยนได้ (asc/desc สลับทุกครั้งที่กดคอลัมน์เดิมซ้ำ)
let _pbvPeScrSort = { key: 'jpb_upside_pct', dir: 'desc' };
// |upside%| เกินนี้ = เตือน ⚠️ ในตาราง (ดู _pbvPeScrUpCell) — ค่าเดียวกับข้อความอธิบายท้ายตาราง
// (เหมือน DCF_SCR_EXTREME_UPSIDE_PCT ด้านบน — คนละหน้า คนละค่าคงที่ แต่ตัวเลขบังเอิญเท่ากัน)
const PBV_PE_SCR_EXTREME_UPSIDE_PCT = 300;
const PBV_PE_SCR_COLS = [
  { key: 'symbol', label: 'หุ้น', align: 'left' },
  { key: 'name', label: 'ชื่อ', align: 'left' },
  { key: 'price', label: 'ราคา', align: 'right' },
  { key: 'jpb_fair', label: 'Fair (P/B)', align: 'right' },
  { key: 'jpb_upside_pct', label: 'Upside P/B', align: 'right' },
  { key: 'jpe_fair', label: 'Fair (P/E)', align: 'right' },
  { key: 'jpe_upside_pct', label: 'Upside P/E', align: 'right' },
  { key: 'roe_pct', label: 'ROE', align: 'right' },
  { key: 'coe_pct', label: 'r (CoE)', align: 'right' },
  { key: 'cur_ps', label: 'P/S', align: 'right',
    tip: 'Price-to-Sales ปัจจุบัน (มูลค่าตลาด ÷ รายได้ TTM) — ข้อมูลอ้างอิงเสริมเท่านั้น ไม่มี "Justified P/S"/Fair Value คำนวณคู่ให้ (สูตร Justified ของหน้านี้อิง ROE ซึ่งผูกกับ P/B และ P/E เท่านั้น)' },
];

function loadPbvPeScreenerPage() {
  if (_pbvPeScreenerData) { renderPbvPeScreener(); return; }
  fetchPbvPeScreener();
}

// field ที่ override ทั้งตลาดได้ (เว้นว่าง = ใช้ค่าจริงของหุ้นนั้น) — id ช่อง input คู่กับ key ที่
// ส่งให้ /api/pbv-pe-screener/rebuild (ต้องตรงกับ resolve_assumptions() ใน sources/pbv_pe_screener.py)
const PBV_PE_SCR_OPTIONAL_FIELDS = [
  ['pbvpe-screener-coe', 'coe_pct'], ['pbvpe-screener-roe', 'roe_pct'],
];

function fetchPbvPeScreener() {
  const box = document.getElementById('pbvpe-screener-table');
  if (box) box.innerHTML = '<div class="empty">กำลังโหลด...</div>';
  return fetch('/api/pbv-pe-screener').then(r => r.json()).then(d => {
    _pbvPeScreenerData = d;
    const a = d.meta && d.meta.assumptions;
    if (a) {
      const setv = (id, v) => {
        const el = document.getElementById(id);
        if (el && document.activeElement !== el && v != null) el.value = v;
      };
      const setvOpt = (id, v) => {
        const el = document.getElementById(id);
        if (el && document.activeElement !== el) el.value = (v == null ? '' : v);
      };
      setv('pbvpe-screener-g', a.g_pct);
      setv('pbvpe-screener-rf', a.rf_pct);
      setv('pbvpe-screener-beta', a.beta);
      setv('pbvpe-screener-erp', a.erp_pct);
      PBV_PE_SCR_OPTIONAL_FIELDS.forEach(([id, key]) => setvOpt(id, a[key]));
    }
    renderPbvPeScreener();
  }).catch(() => {
    // เคลียร์ cache เดิมทิ้งด้วย (ไม่ใช่แค่โชว์ error) กันรอบถัดไปที่กลับมาหน้านี้เจอ cache-hit
    // branch ใน loadPbvPeScreenerPage() แล้วโชว์ข้อมูลเก่าเงียบๆ โดยไม่รู้ว่ารอบล่าสุด fetch ไม่สำเร็จ
    _pbvPeScreenerData = null;
    if (box) box.innerHTML = '<div class="empty">โหลดข้อมูลไม่สำเร็จ</div>';
  });
}

// ค่าเริ่มต้นเดียวกับ LONG_TERM_GROWTH_PCT/RISK_FREE_PCT/BETA/ERP_PCT ใน sources/pbv_pe_screener.py
// — ต้องแก้คู่กันถ้าเปลี่ยนค่าเริ่มต้นฝั่งใดฝั่งหนึ่ง
const PBV_PE_SCR_DEFAULTS = { g_pct: 3.0, rf_pct: 2.5, beta: 1.00, erp_pct: 5.5 };

function resetPbvPeScreenerAssumptions() {
  const el = id => document.getElementById(id);
  el('pbvpe-screener-g').value = PBV_PE_SCR_DEFAULTS.g_pct;
  el('pbvpe-screener-rf').value = PBV_PE_SCR_DEFAULTS.rf_pct;
  el('pbvpe-screener-beta').value = PBV_PE_SCR_DEFAULTS.beta.toFixed(2);
  el('pbvpe-screener-erp').value = PBV_PE_SCR_DEFAULTS.erp_pct;
  PBV_PE_SCR_OPTIONAL_FIELDS.forEach(([id]) => { const e = el(id); if (e) e.value = ''; });
  // แค่รีเซ็ตช่องกรอก ยังไม่คำนวณใหม่ — ให้ผู้ใช้ตรวจค่าก่อนกด ⟳ เอง
}

function startPbvPeScreenerRebuild() {
  const btn = document.getElementById('pbvpe-screener-rebuild-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ กำลังคำนวณ...'; }
  const numVal = (id, dflt) => {
    const v = parseFloat(document.getElementById(id)?.value);
    return Number.isFinite(v) ? v : dflt;
  };
  const optVal = id => {
    const raw = document.getElementById(id)?.value;
    if (raw == null || String(raw).trim() === '') return null;
    const v = parseFloat(raw);
    return Number.isFinite(v) ? v : null;
  };
  const body = {
    g_pct: numVal('pbvpe-screener-g', 3.0),
    rf_pct: numVal('pbvpe-screener-rf', 2.5),
    beta: numVal('pbvpe-screener-beta', 1.0),
    erp_pct: numVal('pbvpe-screener-erp', 5.5),
  };
  PBV_PE_SCR_OPTIONAL_FIELDS.forEach(([id, key]) => { body[key] = optVal(id); });
  fetch('/api/pbv-pe-screener/rebuild', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  }).then(r => r.json())
    .then(result => {
      // skipped_empty = server เจอ set_data.json ว่าง/อ่านไม่ได้ ข้ามการเขียนทับ ตารางยังเป็นผลรอบก่อน
      // ต้องแจ้งผู้ใช้ตรงๆ ไม่งั้นดูเหมือนคำนวณสำเร็จทั้งที่ยังเป็นข้อมูลเก่า
      if (result && result.skipped_empty) {
        const meta = document.getElementById('pbvpe-screener-meta');
        if (meta) meta.textContent = 'คำนวณใหม่ไม่สำเร็จ (อ่านรายชื่อหุ้นไม่ได้) — ยังแสดงผลรอบก่อนหน้าอยู่';
        return;
      }
      return fetchPbvPeScreener();
    })
    .catch(() => {
      const meta = document.getElementById('pbvpe-screener-meta');
      if (meta) meta.textContent = 'คำนวณไม่สำเร็จ ลองใหม่อีกครั้ง';
    })
    .finally(() => {
      if (btn) { btn.disabled = false; btn.textContent = '⟳ คำนวณใหม่ทั้งตลาด'; }
    });
}

function _pbvPeScrSetSort(key) {
  if (_pbvPeScrSort.key === key) {
    _pbvPeScrSort.dir = _pbvPeScrSort.dir === 'desc' ? 'asc' : 'desc';
  } else {
    _pbvPeScrSort.key = key;
    _pbvPeScrSort.dir = (key === 'symbol' || key === 'name') ? 'asc' : 'desc';
  }
  renderPbvPeScreener();
}

// ใช้ร่วมกันทั้งตอน render ตารางและตอน export CSV — export เอาแถวที่กรอง/เรียงตามที่เห็นบนจอ
function _pbvPeScrFilteredSorted() {
  const d = _pbvPeScreenerData;
  if (!d || !d.rows) return [];
  const q = (document.getElementById('pbvpe-screener-search')?.value || '').toUpperCase().trim();
  const hideErr = document.getElementById('pbvpe-screener-hide-na')?.checked;
  const finOnly = document.getElementById('pbvpe-screener-fin-only')?.checked;
  let rows = d.rows.filter(r => !q || r.symbol.includes(q) || (r.name || '').toUpperCase().includes(q));
  if (hideErr) rows = rows.filter(r => !r.error);
  if (finOnly) rows = rows.filter(r => r.is_financial);
  const key = _pbvPeScrSort.key, dir = _pbvPeScrSort.dir === 'asc' ? 1 : -1;
  rows = rows.slice().sort((a, b) => {
    const av = a[key], bv = b[key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === 'string') return dir * av.localeCompare(bv);
    return dir * (av - bv);
  });
  return rows;
}

function _pbvPeScrFinBadge(r) {
  return r.is_financial ? ' <span title="กลุ่มการเงิน — Justified P/B เหมาะกับกลุ่มนี้เป็นพิเศษ">🏦</span>' : '';
}

function _pbvPeScrUpCell(up) {
  if (up == null) return '<td style="text-align:right">—</td>';
  // upside เท่ากับ 0 พอดี (มูลค่าเหมาะสม = ราคาตลาดเป๊ะ) ควรเป็นสีกลาง ไม่ใช่แดง (bearish)
  const color = up > 0 ? 'var(--green)' : (up < 0 ? 'var(--red)' : 'var(--text2)');
  const extreme = Math.abs(up) > PBV_PE_SCR_EXTREME_UPSIDE_PCT;
  return `<td style="text-align:right;font-weight:700;color:${color}">${(up > 0 ? '+' : '') + up.toFixed(1)}%${extreme ? ' ⚠️' : ''}</td>`;
}

function renderPbvPeScreener() {
  const d = _pbvPeScreenerData;
  const box = document.getElementById('pbvpe-screener-table');
  const metaBox = document.getElementById('pbvpe-screener-meta');
  const countBox = document.getElementById('pbvpe-screener-count');
  if (!box) return;
  if (!d || !d.rows || !d.rows.length) {
    if (metaBox) metaBox.textContent = 'ยังไม่เคยคำนวณ';
    box.innerHTML = '<div class="empty">ยังไม่มีข้อมูล กดปุ่ม "⟳ คำนวณใหม่ทั้งตลาด" ด้านบนก่อน</div>';
    return;
  }
  if (metaBox) {
    const a = d.meta.assumptions || {};
    const ov = [];
    if (a.coe_pct != null) ov.push('r');
    if (a.roe_pct != null) ov.push('ROE');
    metaBox.innerHTML = `คำนวณล่าสุด ${d.meta.computed_at || '—'} · คำนวณได้ ${d.meta.ok_count}/${d.meta.count} ตัว`
      + (a.g_pct != null ? ` · g ${a.g_pct}%` : '')
      + (a.coe_pct != null ? ` · r ${a.coe_pct}% (กรอกตรง)` : ` · r = Rf ${a.rf_pct}% + β ${a.beta}·ERP ${a.erp_pct}%`)
      + (ov.length ? ` · กำหนดเองทั้งตลาด: ${ov.join(', ')}` : '')
      + _finStaleBadge(d.meta.stale, 'กด ⟳ คำนวณใหม่');
  }
  const rows = _pbvPeScrFilteredSorted();
  if (countBox) countBox.textContent = `${rows.length} ตัว`;
  if (!rows.length) { box.innerHTML = '<div class="empty">ไม่พบหุ้นตรงเงื่อนไข</div>'; return; }

  const rowsHtml = rows.map(r => {
    const symHtml = _escHtml(r.symbol);
    const symCell = `<td><a href="#" onclick="openInternalHash('#ts/th/${encodeURIComponent(r.symbol)}');return false">${symHtml}</a>${tvLink(r.symbol)}${_pbvPeScrFinBadge(r)}</td>`;
    if (r.error) {
      return `<tr style="opacity:.55">${symCell}
        <td>${_escHtml(r.name || '')}</td>
        <td colspan="8" style="color:var(--text2)">— ${_escHtml(r.error)}</td></tr>`;
    }
    return `<tr>${symCell}
      <td>${_escHtml(r.name || '')}</td>
      <td style="text-align:right">${r.price != null ? r.price.toFixed(2) : '—'}</td>
      <td style="text-align:right">${r.jpb_fair != null ? r.jpb_fair.toFixed(2) : '—'}</td>
      ${_pbvPeScrUpCell(r.jpb_upside_pct)}
      <td style="text-align:right">${r.jpe_fair != null ? r.jpe_fair.toFixed(2) : '—'}</td>
      ${_pbvPeScrUpCell(r.jpe_upside_pct)}
      <td style="text-align:right">${r.roe_pct != null ? r.roe_pct.toFixed(1) + '%' : '—'}</td>
      <td style="text-align:right">${r.coe_pct != null ? r.coe_pct.toFixed(2) + '%' : '—'}</td>
      <td style="text-align:right">${_scrFmtX(r.cur_ps)}</td>
    </tr>`;
  }).join('');
  const headHtml = PBV_PE_SCR_COLS.map(c => {
    const arrow = _pbvPeScrSort.key === c.key ? (_pbvPeScrSort.dir === 'desc' ? ' ▼' : ' ▲') : '';
    const title = c.tip ? `${c.tip} (กดเรียงลำดับ)` : 'กดเรียงลำดับ';
    return `<th style="text-align:${c.align};cursor:pointer;user-select:none;white-space:nowrap" onclick="_pbvPeScrSetSort('${c.key}')" title="${_escHtml(title)}">${c.label}${arrow}</th>`;
  }).join('');
  box.innerHTML = `<div style="overflow-x:auto"><table class="tbl" style="width:100%">
    <thead><tr>${headHtml}</tr></thead>
    <tbody>${rowsHtml}</tbody></table></div>
    <div style="font-size:10.5px;color:var(--text2);margin-top:6px">🏦 = กลุ่มการเงิน · ⚠️ = |upside| เกิน ${PBV_PE_SCR_EXTREME_UPSIDE_PCT}% (มักเกิดจากราคาต่อหุ้นเล็กมาก/BVPS เพี้ยน ไม่ใช่ signal ที่เชื่อถือได้ตรงๆ — เปิด Tearsheet ตรวจก่อน) · Justified P/E เป็นแบบ leading (ROE-based) คูณ EPS รายปีล่าสุด · กดหัวตารางเพื่อเรียงลำดับ</div>`;
}

function exportPbvPeScreenerCsv() {
  const rows = _pbvPeScrFilteredSorted();
  if (!rows.length) { alert('ไม่มีข้อมูลให้ export'); return; }
  const csvEsc = v => {
    if (v == null) return '';
    const s = String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const headers = ['Symbol', 'Name', 'Sector', 'Is financial', 'Price', 'BVPS', 'EPS',
    'Justified P/B x', 'Fair (P/B)', 'Upside P/B %', 'Justified P/E x', 'Fair (P/E)', 'Upside P/E %',
    'ROE %', 'r (CoE) %', 'g %', 'Current P/BV', 'Current P/E', 'Current P/S', 'Error'];
  const lines = [headers.map(csvEsc).join(',')];
  rows.forEach(r => {
    lines.push([
      r.symbol, r.name || '', r.sector || '', r.is_financial ? 'Y' : '',
      r.price ?? '', r.bvps ?? '', r.eps ?? '',
      r.jpb_x ?? '', r.jpb_fair ?? '', r.jpb_upside_pct ?? '',
      r.jpe_x ?? '', r.jpe_fair ?? '', r.jpe_upside_pct ?? '',
      r.roe_pct ?? '', r.coe_pct ?? '', r.g_pct ?? '', r.cur_pbv ?? '', r.cur_pe ?? '', r.cur_ps ?? '',
      r.error || '',
    ].map(csvEsc).join(','));
  });
  const csv = '﻿' + lines.join('\r\n');   // BOM กัน Excel เปิดภาษาไทยเพี้ยน
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const ts = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
  a.href = url;
  a.download = `pbv_pe_screener_${ts}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// ============================================================
// QUARTERLY GROWTH SCREENER — 🚀 หุ้นโตแรงรายไตรมาส — ดู /api/quarterly-growth-screener +
// financials_store.get_qpl_growth_screener ใน backend (source 'set_qpl', SET.or.th official)
