function _scrActiveExtraCols() {
  return _SCR_EXTRA_COL_DEFS.filter(def => {
    const el = document.getElementById(def.id);
    return el && !isNaN(parseFloat(el.value));
  });
}

function setScrSort(col) {
  if (_scrSortCol === col) _scrSortDir *= -1;
  else { _scrSortCol = col; _scrSortDir = _SCR_ASC_FIRST.has(col) ? -1 : 1; }
  renderScrTable();
}

// คำนวณคอลัมน์เสริม (fromHigh/fromLow/rvol/sec_rank) + เรียงตาม _scrSortCol/_scrSortDir
// ปัจจุบัน — ใช้ร่วมกันระหว่าง renderScrTable() และ exportScreenerCSV() เพื่อให้ไฟล์ที่
// export ออกมาเรียงลำดับตรงกับที่เห็นบนตารางเป๊ะๆ เสมอ (เดิม export ใช้ _scrStocks ดิบๆ
// ไม่ผ่านการ sort เลย)
function _scrComputeSorted() {
  const secRanks = computeSectorRanks();
  // ใช้ snapshot จากตอนกด "ค้นหา" ล่าสุด (_scrActiveRvolDays/_scrActiveYearsBack) ไม่ใช่ค่าสด
  // จาก DOM — ต้องตรงกับเกณฑ์ที่ใช้กรอง _scrStocks จริงเป๊ะๆ เสมอ ไม่ว่าผู้ใช้จะแก้ช่อง
  // rvol-days/years-back แล้วยังไม่กด "ค้นหา" ซ้ำก็ตาม (เดิม hardcode vol_avg20 (20 วัน)
  // เสมอ ก่อนจะเปลี่ยนมาอ่านค่าสดจาก DOM ซึ่งกลับไปมีปัญหาเดิมในอีกรูปแบบ — เจอตอน
  // code review 2026-08-27)
  const rvolDaysNow  = _scrActiveRvolDays;
  const yearsBackNow = _scrActiveYearsBack;
  const withRange = _scrStocks.map(s => {
    const fromHigh = s.high_52w > 0 ? (s.price - s.high_52w) / s.high_52w * 100 : null;
    const fromLow  = s.low_52w  > 0 ? (s.price - s.low_52w)  / s.low_52w  * 100 : null;
    const rvCalc   = _rvolCalc(s, rvolDaysNow);
    const rvol     = rvCalc ? rvCalc.rv * 100 : null;
    // secRanks มาจาก DATA.stocks (หุ้นไทยเท่านั้น) — key ด้วย symbol ดิบ ถ้าไม่กัน universe
    // หุ้น DR ที่ symbol ชนกับหุ้นไทยจริงโดยบังเอิญ (เช่น META = Meta Platforms ฝั่ง DR
    // และหุ้น mai ไทยชื่อ META พร้อมกัน) จะได้ sec_rank ของหุ้นไทยตัวนั้นไปแปะผิดๆ
    const sr = s._isDR ? null : secRanks[s.symbol];
    const extra = {};
    _scrExtraCols.forEach(def => {
      if (def.trend) extra[def.field] = s[def.trend] ? s[def.trend][yearsBackNow] : null;
    });
    return { ...s, fromHigh, fromLow, rvol, sec_rank: sr?.rank ?? null, sec_total: sr?.total ?? null, ...extra };
  });
  // withRange เป็น array ใหม่จาก .map() อยู่แล้ว — sort ในตัวได้เลย ไม่ต้อง spread ซ้ำ
  return withRange.sort((a, b) => {
    const col = _scrSortCol;
    if (_SCR_BOOL.has(col)) return ((b[col]?1:0) - (a[col]?1:0)) * _scrSortDir;
    if (_SCR_STR.has(col))  return ((a[col]??'').localeCompare(b[col]??'')) * _scrSortDir;
    // ดัน null ไปท้ายตารางเสมอไม่ว่าจะเรียงมากไปน้อยหรือน้อยไปมาก — เดิมแทน null ด้วย
    // -Infinity แล้วคูณทิศทาง ทำให้ตอนเรียงน้อยไปมาก (_scrSortDir = -1) ค่า null ลอยขึ้น
    // บนสุดแทน (เพราะ -Infinity เป็นค่าที่ "น้อยที่สุด" เสมอ)
    const av = a[col], bv = b[col];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    return (bv - av) * _scrSortDir;
  });
}

function renderScrTable() {
  // snapshot จากตอนกด "ค้นหา" ล่าสุด — เหตุผลเดียวกับใน _scrComputeSorted() ด้านบน
  const rvolDaysNow = _scrActiveRvolDays;
  const sorted = _scrComputeSorted();

  // มือถือจอแคบ (≤480px) ย่อ Sector สุด ๆ เอาพื้นที่คืนให้คอลัมน์ตัวเลข
  // ไอแพด/เดสก์ท็อป มีพื้นที่พอ โชว์ชื่อ sector เต็มได้เลยไม่ต้องย่อ
  const _tier = _screenTier();
  const secColWidth = _tier === 'phone' ? 56 : 110;
  const sectorCellHtml = s => _tier === 'phone'
    ? `<td style="font-size:11px" title="${s.sector || ''}">${_scrSectorAbbr(s.sector)}</td>`
    : `<td style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${s.sector || ''}">${s.sector || '—'}</td>`;
  // คอลัมน์ "ชื่อ" (ชื่อเต็มบริษัท) ซ้ำกับ Symbol อยู่แล้ว — ซ่อนเสมอบน
  // เวอร์ชันเว็บ GitHub Pages (ไม่ว่าจอขนาดไหน) เก็บไว้เฉพาะเวอร์ชัน local
  const _showName = !IS_STATIC;
  const nameColHtml = _showName ? `<col style="width:130px"><!-- ชื่อ -->` : '';
  const nameThHtml  = _showName ? th('name','ชื่อ') : '';
  const nameCellHtml = s => _showName
    ? `<td style="font-size:11px;color:var(--text2);max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${s.name}</td>`
    : '';

  function th(col, label, cls='') {
    const active = _scrSortCol === col;
    const arrow  = active ? (_scrSortDir === 1 ? '↓' : '↑') : '↕';
    const c = (cls ? cls+' ' : '') + 'sortable';
    return `<th class="${c}" onclick="setScrSort('${col}')">${label}${colTipIcon(col)}<span class="sort-ind${active?' on':''}">${arrow}</span></th>`;
  }

  document.getElementById('screener-results').innerHTML = `
    <div class="card" style="overflow-x:auto"><table class="tbl" style="table-layout:fixed;width:auto">
      <colgroup>
        <col style="width:36px"><!-- RS -->
        <col style="width:60px"><!-- SEC.RANK -->
        <col style="width:72px"><!-- SYMBOL -->
        ${nameColHtml}
        <col style="width:${secColWidth}px"><!-- SECTOR -->
        <col style="width:46px"><!-- ราคา -->
        <col style="width:48px"><!-- 1D% -->
        <col style="width:48px"><!-- 1W% -->
        <col style="width:48px"><!-- 1M% -->
        <col style="width:48px"><!-- 3M% -->
        <col style="width:48px"><!-- 6M% -->
        <col style="width:48px"><!-- 1Y% -->
        <col style="width:48px"><!-- YTD% -->
        <col style="width:56px"><!-- %HIGH -->
        <col style="width:48px"><!-- %LOW -->
        <col style="width:38px"><!-- P/E -->
        <col style="width:38px"><!-- P/BV -->
        <col style="width:42px"><!-- DIV% -->
        <col style="width:52px"><!-- RVOL -->
        <col style="width:60px"><!-- MKT CAP -->
        <col style="width:44px"><!-- EMA50 -->
        <col style="width:44px"><!-- EMA200 -->
        <col style="width:50px"><!-- Growth -->
        <col style="width:44px"><!-- PEG -->
        <col style="width:54px"><!-- FCF Yield% -->
        <col style="width:56px"><!-- Div Cover -->
        ${_scrExtraCols.map(() => '<col style="width:74px">').join('')}<!-- คอลัมน์เสริมจากตัวกรองที่ตั้งไว้ -->
      </colgroup>
      <thead><tr>
        ${th('rs_score','RS')}${th('sec_rank','SEC.RANK','r')}${th('symbol','SYMBOL')}${nameThHtml}${th('sector','SECTOR')}
        ${th('price','ราคา','r')}${th('ret_1d','1D%','r')}${th('ret_1w','1W%','r')}${th('ret_1m','1M%','r')}
        ${th('ret_3m','3M%','r')}${th('ret_6m','6M%','r')}${th('ret_1y','1Y%','r')}${th('ret_ytd','YTD%','r')}
        ${th('fromHigh','%HIGH','r')}${th('fromLow','%LOW','r')}
        ${th('pe','P/E','r')}${th('pbv','P/BV','r')}${th('div_yield','DIV%','r')}
        ${th('rvol','RVOL','r')}${th('mkt_cap','MKT CAP','r')}${th('above_ema50','EMA50','r')}${th('above_ema200','EMA200','r')}
        ${th('growth_score','Growth','r')}${th('peg','PEG','r')}${th('fcf_yield','FCF Yield%','r')}${th('dividend_coverage','Div Cover','r')}
        ${_scrExtraCols.map(def => th(def.field, def.label, 'r')).join('')}
      </tr></thead>
      <tbody>${sorted.map(s => `
        <tr>
          <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '—'}</span></td>
          <td class="r">${secRankHtml(s.sec_rank ? {rank:s.sec_rank,total:s.sec_total} : null)}</td>
          <td><strong class="sym-link" onclick="${s._isDR ? `openDRChartModal('${s.symbol}')` : `openChartModal('${s.symbol}')`}">${s.symbol}</strong>${s._isDR ? ' 🌏' : tvLink(s.symbol)}${dqBadge(s)}</td>
          ${nameCellHtml(s)}
          ${sectorCellHtml(s)}
          <td class="r">${s.price?.toFixed(2) ?? '—'}</td>
          <td class="r">${pct(s.ret_1d)}</td>
          <td class="r">${pct(s.ret_1w)}</td>
          <td class="r">${pct(s.ret_1m)}</td>
          <td class="r">${pct(s.ret_3m)}</td>
          <td class="r">${pct(s.ret_6m)}</td>
          <td class="r">${pct(s.ret_1y)}</td>
          <td class="r">${pct(s.ret_ytd)}</td>
          <td class="r">${s.fromHigh == null ? '—' : `<span class="${s.fromHigh >= -2 ? 'green' : s.fromHigh >= -5 ? 'yellow' : 'text2'}">${s.fromHigh >= 0 ? 'NEW HIGH' : s.fromHigh.toFixed(2)+'%'}</span>`}</td>
          <td class="r">${s.fromLow  == null ? '—' : `<span class="${s.fromLow  <= 2  ? 'red'   : s.fromLow  <= 5  ? 'yellow' : 'text2'}">${s.fromLow  <= 0.5  ? 'NEW LOW'  : s.fromLow.toFixed(2)+'%'}</span>`}</td>
          <td class="r text2">${s.pe        != null ? s.pe.toFixed(2)        : '—'}</td>
          <td class="r text2">${s.pbv       != null ? s.pbv.toFixed(2)       : '—'}</td>
          <td class="r">${s.div_yield != null ? `<span class="${s.div_yield >= 5 ? 'green' : s.div_yield >= 3 ? 'yellow' : 'text2'}">${s.div_yield.toFixed(2)}%</span>` : '—'}</td>
          <td class="r">${rvolHtml(s, rvolDaysNow)}</td>
          <td class="r" style="font-size:11px">${fmtCap(s.mkt_cap, s.is_reit)}</td>
          <td class="r">${emaBadge(s.above_ema50)}</td>
          <td class="r">${emaBadge(s.above_ema200)}</td>
          <td class="r">${s.growth_score != null ? `<span class="${s.growth_score >= 0 ? 'green' : 'red'}">${s.growth_score.toFixed(1)}</span>` : '<span class="text2">—</span>'}</td>
          <td class="r text2">${s.peg != null ? s.peg.toFixed(2) : '—'}</td>
          <td class="r text2">${s.fcf_yield != null ? s.fcf_yield.toFixed(2) + '%' : '—'}</td>
          <td class="r">${s.dividend_coverage != null ? `<span class="${s.dividend_coverage < 1 ? 'red' : 'green'}">${s.dividend_coverage.toFixed(2)}x</span>` : '<span class="text2">—</span>'}</td>
          ${_scrExtraCols.map(def => `<td class="r">${def.fmt(s[def.field])}</td>`).join('')}
        </tr>`).join('')}
      </tbody>
    </table></div>`;
}

