// ~150-230 ตัวจาก 1,000 แถวแรกมีค่าให้กรองครบทุก field กลุ่มนี้ (ไม่ใช่ศูนย์อย่างที่ comment
// เดิมอ้างไว้ ตอนนั้นยังไม่มีงาน sync งบ Yahoo ดัชนีหลัก) — เลิกปิดช่องทิ้ง เปิดให้กรองได้
// พร้อมเตือนสีเหลืองใต้ตาราง (เหมือน FS_PRICE_ONLY ด้านล่าง) แทน กันเข้าใจผิดว่าหุ้นหาย/บั๊ก
const FS_YAHOO_ONLY = new Set(['rev_cagr', 'profit_cagr', 'revenue_streak', 'profit_streak', 'rule_of_40',
  'interest_coverage', 'cash_cycle', 'goodwill_ratio', 'ocf_neg_years', 'shares_chg_yoy',
  'net_cash_positive', 'buyback', 'dividend_coverage', 'fcf_yield', 'f_score', 'z_zone']);

// filter สายราคา (rs/ema200/52w high/rvol) — มีข้อมูลจริงเฉพาะหุ้น US ที่อยู่ใน
// S&P500+Dow+NDX (~518 ตัว, overlay จาก us_index_metrics.json ใน app.py) ตัวอื่น
// นอกดัชนีหลัก + หุ้น HK ทั้งหมด ยังไม่มีราคารายวันเก็บไว้ (ปิดเฉพาะ HK)
const FS_PRICE_ONLY = new Set(['rs', 'pct_vs_ema200', 'pct_off_high52', 'rvol']);

function _fsApplyUniverseUI() {
  const uni = document.getElementById('fs-universe')?.value;
  const offNever = (uni === 'us' || uni === 'hk' || uni === 'jp');
  const offPrice = (uni === 'hk');   // US/JP มี overlay ราคาแล้ว (JP ครบทุกตัวเพราะทั้ง universe
                                      // คือสมาชิกดัชนีหลัก 225 ตัวอยู่แล้ว) — เปิดไว้ ปิดเฉพาะ HK
  FS_FILTERS.forEach(f => {
    if (f.g) return;
    const isNever = FS_MIRROR_NEVER.has(f.k), isPrice = FS_PRICE_ONLY.has(f.k);
    if (!isNever && !isPrice) return;
    const off = isNever ? offNever : offPrice;
    // filter แบบช่วง (range:true) มี 2 ช่อง (min id หลัก + max fsin-{k}-alt) ต้องปิด/เคลียร์ทั้งคู่
    // เหมือนกัน — เดิมเช็คแค่ id เดียว (fsin-{k}/fsen-{k}) ช่องคู่ -alt เลยค้างเปิด/มีค่าเก่าตอนสลับ
    // universe (เจอกับ free_float/foreign_room_used_pct — code review 2026-09-02)
    const ids = f.range ? Object.values(_fsRangeIds(f)) : ['fsin-' + f.k, 'fsen-' + f.k];
    let grpEl = null;
    ids.forEach(id => {
      const el = document.getElementById(id);
      if (!el) return;
      grpEl = grpEl || el;
      el.disabled = off;
      if (off) { if (el.value) el.value = ''; if (el.checked) el.checked = false; }
    });
    if (!grpEl) return;
    // เปิดกลับ (us/hk -> th/dr/ทั้งหมด): ปล่อยว่างไว้เหมือนเดิม — placeholder จางแสดง
    // ตัวเลขแนะนำอยู่แล้ว ไม่ต้องเติมค่าจริงให้
    const grp = grpEl.closest('.scr-group');
    // ทำให้ตัวหนังสือ 'จาง' แทน opacity — เพราะ opacity บน group จะส่งผลถึง tip box
    // ที่เป็นลูกด้วย (ทำให้ tip box โปร่งใส พื้นหลังทะลุขึ้นมา อ่านไม่ออก)
    // tip box มีสี/พื้นหลังของตัวเองใน CSS จึงไม่โดนสี label ที่ตั้งจาง
    if (grp) {
      grp.style.opacity = '';   // ล้าง opacity เดิม
      const lbl = grp.querySelector('.scr-label') || grp.querySelector('.scr-check');
      if (lbl) lbl.style.color = off ? 'var(--text2)' : '';
    }
  });
}

function _fsOnUniverseChange() {
  _fsApplyUniverseUI();
  runFscreener();
}

