function toggleBtNote(boxId) {
  const el = document.getElementById(boxId);
  if (!el) return;
  if (!el.innerHTML) el.innerHTML = _BT_NOTE_HTML_BY_ID[boxId] || _BT_NOTE_HTML;
  el.style.display = el.style.display === 'none' ? 'block' : 'none';
}

