// สีตามความหมายต่อคอลัมน์ — คืน CSS color ('' = สีปกติ)
const _fsPosNeg = v => v > 0 ? 'var(--green)' : (v < 0 ? 'var(--red)' : '');
const FS_COL_CLR = {
  rs:                  v => v >= 80 ? 'var(--green)' : (v < 40 ? 'var(--red)' : ''),
  pct_off_high52:      v => v >= -5 ? 'var(--green)' : (v <= -30 ? 'var(--red)' : ''),
  roe:                 v => v >= 15 ? 'var(--green)' : (v < 0 ? 'var(--red)' : ''),
  roe15_streak_q:      v => v >= 8 ? 'var(--green)' : '',
  roa:                 v => v < 0 ? 'var(--red)' : '',
  net_margin:          v => v < 0 ? 'var(--red)' : '',
  ocf_ni_ratio:        v => v >= 1 ? 'var(--green)' : (v < 0 ? 'var(--red)' : (v < 0.8 ? '#e8a33d' : '')),
  f_score:             v => v >= 8 ? 'var(--green)' : (v >= 6 ? '#7ee787' : (v >= 4 ? '#d29922' : 'var(--red)')),
  de_ratio:            v => v > 2 ? 'var(--red)' : '',
  rev_yoy_q:           _fsPosNeg,
  profit_yoy_q:        _fsPosNeg,
  rev_qoq:             _fsPosNeg,
  profit_qoq:          _fsPosNeg,
  rev_ttm_yoy:         _fsPosNeg,
  profit_ttm_yoy:      _fsPosNeg,
  rev_accel_streak:    v => v >= 2 ? 'var(--green)' : '',
  profit_accel_streak: v => v >= 2 ? 'var(--green)' : '',
  pe_percentile:       v => v <= 25 ? 'var(--green)' : (v >= 75 ? 'var(--red)' : ''),
  ps_percentile:       v => v <= 25 ? 'var(--green)' : (v >= 75 ? 'var(--red)' : ''),
  peg:                 v => v <= 1 ? 'var(--green)' : (v > 2 ? 'var(--red)' : ''),
  div_yield:           v => v >= 3 ? 'var(--green)' : '',
  div_cagr_5y:         v => v >= 5 ? 'var(--green)' : (v < 0 ? 'var(--red)' : ''),
  fcf_yield:           v => v >= 5 ? 'var(--green)' : (v < 0 ? 'var(--red)' : ''),
  dividend_coverage:   v => v >= 1 ? 'var(--green)' : (v < 1 ? 'var(--red)' : ''),
  esg_rating:          v => (v === 'AAA' || v === 'AA') ? 'var(--green)' : (v === 'BBB' ? '#e8a33d' : ''),
  cg_score:            v => v <= 3 ? 'var(--red)' : (v === 5 ? 'var(--green)' : ''),
  free_float:          v => v >= 40 ? 'var(--green)' : (v < 15 ? 'var(--red)' : ''),
  foreign_room_used_pct: v => v >= 95 ? 'var(--red)' : (v >= 80 ? '#e8a33d' : ''),
  analyst_target_upside: v => v >= 15 ? 'var(--green)' : (v < 0 ? 'var(--red)' : ''),
  analyst_rec_mean:      v => v <= 2 ? 'var(--green)' : (v >= 3.5 ? 'var(--red)' : ''),
  analyst_buy_pct:       v => v >= 70 ? 'var(--green)' : (v < 30 ? 'var(--red)' : ''),
};
const FS_MKT_BADGE = { TH: '#58a6ff', US: '#3fb950', HK: '#e3b341', JP: '#f778ba', DR: '#3fb950' };

// คอลัมน์เสริมที่โผล่อัตโนมัติในตาราง Screener+ เมื่อผู้ใช้ตั้งตัวกรองที่ "field ยังไม่มี
// คอลัมน์ตายตัว" ใน FS_COLS อยู่แล้ว (เช่น QoQ, streak รายไตรมาส, margin trend, D/E เทรนด์
// ฯลฯ) — คำนวณจาก conds ที่ _fsReadConds() อ่านได้ตอนกด "ค้นหา" ครั้งนั้นๆ เก็บไว้ที่
// _fsExtraCols แล้ว renderFsTable()/exportFscreenerCSV() ต่อท้าย FS_COLS ด้วยรายการนี้
let _fsExtraCols = [];
const FS_COLS_KEYS = new Set(FS_COLS.map(c => c.k));
// esg_rank เป็น threshold เลือกจาก dropdown (1-4) ใช้กรองเท่านั้น — ค่า esg_rating
// (ตัวอักษร AAA/AA/A/BBB) ที่มีคอลัมน์ตายตัวอยู่แล้วสื่อความหมายตรงกว่า ไม่ต้องมีคอลัมน์ซ้ำ
const FS_EXTRA_COL_SKIP = new Set(['esg_rank']);
function _fsActiveExtraCols(conds) {
  const seen = new Set();
  const cols = [];
  conds.forEach(c => {
    if (c.cmp === 'bool' || FS_COLS_KEYS.has(c.k) || FS_EXTRA_COL_SKIP.has(c.k) || seen.has(c.k)) return;
    seen.add(c.k);
    const f = FS_FILTERS.find(x => x.k === c.k);
    if (!f) return;
    const label = f.label.replace(/\s*[≥≤]\s*$/, '') + (f.unit ? ` (${f.unit})` : '');
    // ไม่เอา f.tip มาใส่ตรงๆ — เป็น HTML เต็ม (มี " ในตัว เช่น style="...") ออกแบบมาสำหรับ
    // กล่อง tip ในฟอร์ม filter ไม่ใช่ attribute title="..." ตรงๆ ที่ renderFsTable ใช้
    // (เดิมใส่ตรงๆ แล้ว " ตัดค่า title กลางคัน ทำ header ทั้งแถวเพี้ยน — เจอตอนทดสอบจริง)
    cols.push({ k: c.k, label, sep: cols.length === 0 });
  });
  return cols;
}
// FS_COLS ต่อท้ายด้วย _fsExtraCols ของรอบนี้ — ใช้ร่วมกันทั้ง renderFsTable/exportFscreenerCSV
// กันสองจุดเพี้ยนไม่ตรงกันถ้าแก้ logic รวมคอลัมน์แค่จุดเดียวแล้วลืมอีกจุด (code review 2026-08-26)
function _fsAllCols() {
  return _fsExtraCols.length ? FS_COLS.concat(_fsExtraCols) : FS_COLS;
}

// คลิก symbol ในตาราง Screener+ -> เปิด "chart-modal" ป็อปอัพเดียวกับที่ใช้ทั่วทั้งแอป
// (กราฟราคา + เมตริก + ปุ่มงบการเงิน/Tearsheet/เทียบเพื่อนอยู่ในนั้นแล้ว) แทนที่จะเด้ง
// ไปหน้างบการเงินตรงๆ เหมือนเดิม — เลือก modal ให้ตรงตามชนิดแถว (TH/DR/US/HK mirror)
// lazy-load ชุดข้อมูลที่โมดัลนั้นต้องใช้ก่อน ถ้ายังไม่เคยโหลด (ผู้ใช้อาจเข้า Screener+
// เป็นหน้าแรกโดยไม่เคยเปิดหน้า DR/US/HK มาก่อนเลย)
//
// universe=us/hk (mirror table) เซ็ต is_dr=true ให้ทุกแถวเสมอ (backend เขียนไว้แบบนั้นตั้งแต่ต้น
// ไม่เกี่ยวกับ DR จริง) ต้องเช็ค dropdown universe ก่อน ไม่ใช่ isDr param ตรงๆ ไม่งั้นหุ้น mirror
// US/HK จะหลุดไปเปิด openDRChartModal ผิด (หา symbol ใน _drData ~279 ตัวไม่เจอ -> เงียบไม่มีอะไรเกิดขึ้น)
// map universe -> {dataVar getter/setter, endpoint, suffix ที่ต้องต่อก่อน lookup, ฟังก์ชันเปิด
// chart modal} — JP เหมือน HK ทุกอย่าง (225/225 อยู่ในดัชนีหลักหมด ต่างจาก US/HK มิเรอร์ที่ส่วน
// ใหญ่อยู่นอกดัชนี) เลย found แทบจะเป็น true เสมอสำหรับ JP
const _FS_MIRROR_IDX = {
  us: { get: () => _usData, set: v => { _usData = v; }, endpoint: '/api/us-index-metrics', suffix: '', open: openUsChartModal, rebuild: () => _rebuildUsSectorFilter() },
  hk: { get: () => _hkData, set: v => { _hkData = v; }, endpoint: '/api/hk-index-metrics', suffix: '.HK', open: openHkChartModal, rebuild: () => _rebuildHkSectorFilter() },
  jp: { get: () => _jpData, set: v => { _jpData = v; }, endpoint: '/api/jp-index-metrics', suffix: '.T', open: openJpChartModal, rebuild: () => _rebuildJpSectorFilter() },
};

// fetch ที่กำลังทำอยู่ต่อตลาด — กันสองคลิกซ้อนกันก่อน fetch แรกจะเสร็จยิงซ้ำ/แข่งกันเขียนทับ
// _usData/_hkData/_jpData (code review 2026-09-02)
const _fsMirrorInflight = {};

// เปิดหน้ารายละเอียดหุ้น mirror US/HK/JP — ใช้ร่วมกัน (Growth Screener / Screener+ / Peer Compare):
//  โหมด "🗗 แท็บใหม่" → deep-link หน้างบการเงินในแท็บใหม่
//  โหมด "🔗 หน้าเดิม" → อยู่ในดัชนีหลัก (lazy-fetch index metrics) เปิด chart modal, ไม่งั้น deep-link หน้างบ
// mkt = 'us' | 'hk' | 'jp' (ตัวเล็ก)
function _openMirrorStock(sym, mkt) {
  const idx = _FS_MIRROR_IDX[mkt];
  // deep-link ใช้รหัสดิบไม่มี suffix (#fin/ route regex จับ 'HK:'/'JP:' prefix แล้ว symbol ตามหลัง)
  const deep = `#fin/dr/${mkt.toUpperCase()}:` + encodeURIComponent(sym.replace(/\.(HK|T)$/i, ''));
  if (!idx || navOpenMode() === 'new') { openInternalHash(deep); return; }
  const go = () => {
    const lookup = idx.suffix && !sym.endsWith(idx.suffix) ? sym + idx.suffix : sym;
    if ((idx.get()?.stocks || []).some(s => s.symbol === lookup)) idx.open(lookup);
    else openInternalHash(deep);
  };
  if (idx.get()) { go(); return; }
  if (!_fsMirrorInflight[mkt]) {
    // เช็ค d.error/d.stocks ก่อน cache เสมอ — เหมือน loadUsStocksPage/loadHkStocksPage/loadJpStocksPage
    // (เดิมจุดนี้ set(d) ดิบไม่เช็คอะไรเลย ถ้า index metrics ยังไม่เคย sync response จะเป็น
    // {error:...} ไม่มี .stocks พอ cache เข้า _usData แล้วไปเปิดหน้า US/HK/JP จริงทีหลัง หน้านั้น
    // เห็น _usData truthy ข้าม fetch/เช็คของตัวเอง แล้ว throw TypeError ตอน .filter(.stocks))
    // แล้ว rebuild sector filter dropdown ให้ด้วย — ไม่งั้น dropdown ค้างว่างจนกว่าจะสลับ index เอง
    _fsMirrorInflight[mkt] = _fetchTimeout(idx.endpoint, 30000).then(r => r.json())
      .then(d => { if (d && !d.error && d.stocks) { idx.set(d); idx.rebuild(); } })
      .catch(() => {})
      .finally(() => { delete _fsMirrorInflight[mkt]; });
  }
  _fsMirrorInflight[mkt].then(go);
}

// deep-link หน้ารายละเอียดหุ้นของแถว Screener+ (ตาม fs-universe) — ใช้เป็น href ให้ Ctrl/กลางคลิก
// เปิดแท็บใหม่ได้เอง + ตอนโหมด "🗗 แท็บใหม่" · us/hk/jp → หน้างบการเงิน DR tab + market prefix
// (Tearsheet #ts/ ไม่รับ 'dr' และ 404 กับหุ้น mirror ตัวเล็กที่ Yahoo resolve ไม่ได้)
function _fsDeepLink(sym, isDr) {
  const uni = document.getElementById('fs-universe')?.value;
  const s = encodeURIComponent(sym);
  if (uni === 'us' || uni === 'hk' || uni === 'jp') return `#fin/dr/${uni.toUpperCase()}:` + s;
  if (isDr) return '#fin/dr/' + s;
  return '#ts/th/' + s;
}

async function fsOpenDetail(sym, isDr) {
  // โหมด "🗗 แท็บใหม่" — เปิด deep-link ในแท็บใหม่ ไม่เปิด modal/นำทางทับหน้าเดิม
  if (navOpenMode() === 'new') { openInternalHash(_fsDeepLink(sym, isDr)); return; }
  const uni = document.getElementById('fs-universe')?.value;
  // mirror US/HK/JP — ในดัชนีหลัก chart modal, นอกดัชนี → หน้างบการเงิน market ถูกต้อง
  // (เดิม fsOpenFin ค้าง _finMirMarket='US' ทำให้ HK/JP หาไม่เจอ)
  if (_FS_MIRROR_IDX[uni]) { _openMirrorStock(sym, uni); return; }
  if (isDr) {
    if (!_drData) {
      try {
        const d = await (await _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000)).json();
        if (d.stocks) { _drData = d.stocks; _drLoaded = true; }
      } catch (e) { fsOpenFin(sym, true); return; }
    }
    openDRChartModal(sym);
    return;
  }
  openChartModal(sym);   // หุ้นไทย (market='TH')
}

// สำรอง — เปิดหน้างบการเงินตรงๆ (ใช้ตอน chart modal ของ DR เปิดไม่ได้จริงๆ เช่น
// /api/dr ล่ม) ปุ่ม "งบการเงิน" ปกติอยู่ในตัว chart-modal เองแล้ว ไม่ต้องผ่านฟังก์ชันนี้
function fsOpenFin(sym, isDr) {
  showPage('financials');
  const btn = document.getElementById(isDr ? 'fin-tab-dr-btn' : 'fin-tab-set-btn');
  if (btn) setFinTab(isDr ? 'dr' : 'set', btn);
  const inp = document.getElementById(isDr ? 'fin-sym-dr' : 'fin-sym-set');
  if (inp) inp.value = sym;
  searchFinancials();
}

// id หลัก fsin-{k} คงเป็นฝั่ง 'ทิศทางเดิม' ของ filter (gte -> ช่องซ้าย/ขั้นต่ำ, lte -> ช่องขวา/
// ไม่เกิน) เพื่อให้ preset เก่า/โค้ดเดิมที่อ้าง fsin-{k} ทำงานเหมือนเดิมทุกอย่าง — อีกฝั่งคือ
// fsin-{k}-alt · เดิม ternary นี้ก็อปแยกกัน 3 จุด (buildFsFilterUI/applyFsPreset/_fsRangeWarnings)
// รวมเป็น helper เดียว (code review 2026-09-02)
function _fsRangeIds(f) {
  const minId = f.cmp === 'gte' ? `fsin-${f.k}` : `fsin-${f.k}-alt`;
  const maxId = f.cmp === 'gte' ? `fsin-${f.k}-alt` : `fsin-${f.k}`;
  return { minId, maxId };
}

function buildFsFilterUI() {
  if (_fsBuilt) return;
  const box = document.getElementById('fs-filters');
  const preBox = document.getElementById('fs-presets');
  if (!box || !preBox) return;
  box.innerHTML = FS_FILTERS.map(f => {
    if (f.g) return `<div style="grid-column:1/-1;font-size:10px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin:10px 0 0;border-top:1px solid var(--border);padding-top:8px">${f.g}</div>`;
    const tip = f.tip ? ` <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:250px">${f.tip}</div></span>` : '';
    if (f.cmp === 'bool') {
      return `<div class="scr-group"><label class="scr-check" style="margin-top:16px"><input type="checkbox" id="fsen-${f.k}" onchange="runFscreener()"> <span>${f.label}</span>${tip}</label></div>`;
    }
    if (f.cmp === 'eq' && f.options) {
      const opts = f.options.map(o => `<option value="${o.v}">${o.label}</option>`).join('');
      return `<div class="scr-group"><label class="scr-label" for="fsin-${f.k}">${f.label}${tip}</label>
        <select class="scr-input" id="fsin-${f.k}" onchange="runFscreener()">
          <option value="">— ทั้งหมด —</option>${opts}
        </select></div>`;
    }
    if (f.cmp === 'gte' && f.selectOptions) {
      // ตัวเลือกอันดับ (เช่น SETESG rating) แต่เปรียบเทียบแบบตัวเลข "ขั้นต่ำ" (gte)
      // ไม่ใช่ตรงตัวแบบ eq — <select>.value เป็น string แต่ parseFloat ใน
      // _fsReadConds() แปลงเป็นตัวเลขให้เองเหมือน input ปกติ
      const opts = f.selectOptions.map(o => `<option value="${o.v}">${o.label}</option>`).join('');
      return `<div class="scr-group"><label class="scr-label" for="fsin-${f.k}">${f.label}${tip}</label>
        <select class="scr-input" id="fsin-${f.k}" onchange="runFscreener()">
          <option value="">— ทั้งหมด —</option>${opts}
        </select></div>`;
    }
    if (f.range) {
      // filter แบบช่วง (min-max): ช่องซ้าย = ขั้นต่ำ (≥), ช่องขวา = ไม่เกิน (≤) เสมอ
      const lbl = f.label.replace(/\s*[≥≤]\s*$/, '');
      const { minId, maxId } = _fsRangeIds(f);
      return `<div class="scr-group"><label class="scr-label" for="fsin-${f.k}">${lbl} (ช่วง)${tip}</label>
      <div style="display:flex;gap:6px;align-items:center">
        <input class="scr-input" type="number" step="any" id="${minId}" placeholder="ขั้นต่ำ" onkeydown="if(event.key==='Enter')runFscreener()">
        <span style="font-size:11px;color:var(--text2)">–</span>
        <input class="scr-input" type="number" step="any" id="${maxId}" placeholder="ไม่เกิน" onkeydown="if(event.key==='Enter')runFscreener()">
        <span style="font-size:11px;color:var(--text2);min-width:28px">${f.unit || ''}</span>
      </div></div>`;
    }
    // ช่องที่มี def (risk filter แนะนำ) โชว์ตัวเลขแนะนำเป็น placeholder (จาง) แทนการเติมค่าจริง
    // ให้ไว้ล่วงหน้า — ช่องว่างเปล่าจริงจนกว่าผู้ใช้จะพิมพ์เอง (ไม่กรองอะไรถ้าไม่พิมพ์)
    return `<div class="scr-group"><label class="scr-label" for="fsin-${f.k}">${f.label}${tip}</label>
      <div style="display:flex;gap:6px;align-items:center">
        <input class="scr-input" type="number" step="any" id="fsin-${f.k}" placeholder="${f.def != null ? f.def : (f.unit || 'ค่า')}" onkeydown="if(event.key==='Enter')runFscreener()">
        <span style="font-size:11px;color:var(--text2);min-width:28px">${f.unit || ''}</span>
      </div></div>`;
  }).join('');
  preBox.innerHTML = FS_PRESETS.map((p, i) =>
    `<button onclick="applyFsPreset(${i})" title="${p.desc}" style="background:${p.color}22;border:1px solid ${p.color};color:${p.color};border-radius:6px;padding:5px 12px;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap">${p.name}</button>`
  ).join('');
  // ช่องที่มี def (risk filter แนะนำ) เริ่มต้นเป็นค่าว่างเสมอ — ตัวเลขแนะนำโชว์เป็น
  // placeholder จางๆ ในช่อง input เท่านั้น (ดู render ด้านบน) ไม่กรอกค่าจริงให้ล่วงหน้า
  _fsBuilt = true;
  _fsApplyUniverseUI();   // ตั้งสถานะ enable/disable ตาม universe เริ่มต้น
  initFsAutosave();       // ผูก listener autosave หลัง DOM สร้างเสร็จ (ต้องรอ element มีอยู่จริงก่อน)
}

// ============================================================
// PERSISTENT SCREENER+ SETTINGS — เหมือน _SCR_LS ของเมนู Stock Screener ปกติ (ดูด้านล่างของ
// ไฟล์) ต่างกันที่ field ของ Screener+ สร้างจาก FS_FILTERS แบบ data-driven จึงวน list เอง
// แทนการ hardcode รายชื่อ id เหมือน _SCR_FIELDS — กันลืมเพิ่ม id ใหม่ทุกครั้งที่เพิ่ม filter
// ============================================================
const _FS_LS = 'set_fs_v1';

function saveFsSettings() {
  const s = {};
  FS_FILTERS.forEach(f => {
    if (f.g) return;
    if (f.cmp === 'bool') {
      const en = document.getElementById('fsen-' + f.k);
      if (en) s['fsen-' + f.k] = en.checked;
      return;
    }
    const inp = document.getElementById('fsin-' + f.k);
    if (inp) s['fsin-' + f.k] = inp.value;
    if (f.range) {
      const alt = document.getElementById('fsin-' + f.k + '-alt');
      if (alt) s['fsin-' + f.k + '-alt'] = alt.value;
    }
  });
  const uni = document.getElementById('fs-universe');
  if (uni) s['fs-universe'] = uni.value;
  localStorage.setItem(_FS_LS, JSON.stringify(s));
}

function loadFsSettings() {
  try {
    const raw = localStorage.getItem(_FS_LS);
    if (!raw) return;
    const s = JSON.parse(raw);
    FS_FILTERS.forEach(f => {
      if (f.g) return;
      if (f.cmp === 'bool') {
        if (s['fsen-' + f.k] != null) { const en = document.getElementById('fsen-' + f.k); if (en) en.checked = s['fsen-' + f.k]; }
        return;
      }
      if (s['fsin-' + f.k] != null) { const inp = document.getElementById('fsin-' + f.k); if (inp) inp.value = s['fsin-' + f.k]; }
      if (f.range && s['fsin-' + f.k + '-alt'] != null) { const alt = document.getElementById('fsin-' + f.k + '-alt'); if (alt) alt.value = s['fsin-' + f.k + '-alt']; }
    });
    if (s['fs-universe']) { const uni = document.getElementById('fs-universe'); if (uni) uni.value = s['fs-universe']; }
    _fsApplyUniverseUI();   // universe ที่โหลดกลับมาอาจไม่ตรงกับ default 'th' ตอน build UI — sync enable/disable ใหม่
  } catch (e) {}
}

// autosave ทุกครั้งที่แก้ค่า filter — เหมือน initScreenerAutosave() ของเมนู Screener ปกติ
let _fsAutosaveWired = false;
function initFsAutosave() {
  if (_fsAutosaveWired) return;
  _fsAutosaveWired = true;
  FS_FILTERS.forEach(f => {
    if (f.g) return;
    if (f.cmp === 'bool') {
      const en = document.getElementById('fsen-' + f.k);
      if (en) en.addEventListener('change', saveFsSettings);
      return;
    }
    const inp = document.getElementById('fsin-' + f.k);
    if (inp) inp.addEventListener('input', saveFsSettings);
    if (f.range) {
      const alt = document.getElementById('fsin-' + f.k + '-alt');
      if (alt) alt.addEventListener('input', saveFsSettings);
    }
  });
  const uni = document.getElementById('fs-universe');
  if (uni) uni.addEventListener('change', saveFsSettings);
}

function applyFsPreset(i) {
  const p = FS_PRESETS[i];
  if (!p) return;
  // preset ที่ผูกกับตลาด (เช่น 🇺🇸/🇭🇰 หุ้นดีราคาถูก) สลับ universe ให้อัตโนมัติ —
  // กดปุ่มเดียวได้ทั้งเปลี่ยนตลาด+กรอง (preset ที่ไม่มี universe ทำงานเหมือนเดิม)
  if (p.universe) {
    const u = document.getElementById('fs-universe');
    if (u) u.value = p.universe;
  }
  resetFscreener(true);   // เคลียร์ก่อน แล้วเติมค่าของ preset (ช่องว่าง = ไม่กรอง)
  Object.entries(p.set || {}).forEach(([k, v]) => {
    if (v !== null && typeof v === 'object') {
      // ค่าแบบช่วง {min, max} — ใช้กับ filter ที่มี range: true
      const f = FS_FILTERS.find(x => x.k === k);
      const { minId, maxId } = f ? _fsRangeIds(f) : { minId: `fsin-${k}`, maxId: `fsin-${k}-alt` };
      if (v.min != null) { const el = document.getElementById(minId); if (el) el.value = v.min; }
      if (v.max != null) { const el = document.getElementById(maxId); if (el) el.value = v.max; }
      return;
    }
    const inp = document.getElementById('fsin-' + k); if (inp) inp.value = v;
  });
  (p.bool || []).forEach(k => { const en = document.getElementById('fsen-' + k); if (en) en.checked = true; });
  _fsApplyUniverseUI();   // ถ้าอยู่ universe US/HK เคลียร์ค่า FS_MIRROR_NEVER ที่ preset เผลอตั้ง (server ไม่คำนวณให้ mirror เลย)
  saveFsSettings();       // จำ preset ที่เพิ่งกดไว้ด้วย (setter ด้านบนตั้งค่าผ่าน .value ตรงๆ ไม่ผ่าน
                          // 'input'/'change' event เลยไม่ trigger autosave เอง — ต้องเรียกเอง)
  runFscreener();
}

function resetFscreener(skipRun) {
  _fsExtraCols = [];
  FS_FILTERS.forEach(f => {
    if (f.g) return;
    // ทุกช่องกลับเป็นค่าว่างเสมอ (รวมช่องที่มี def) — ตัวเลขแนะนำโชว์เป็น placeholder
    // จางๆ เท่านั้น ไม่กรอกค่าจริงให้ ผู้ใช้ต้องพิมพ์เองถึงจะเปิดใช้ filter นั้น
    const inp = document.getElementById('fsin-' + f.k); if (inp) inp.value = '';
    const alt = document.getElementById('fsin-' + f.k + '-alt'); if (alt) alt.value = '';
    const en = document.getElementById('fsen-' + f.k); if (en) en.checked = false;
  });
  // เช็คสถานะ enable/disable ตาม universe ปัจจุบันซ้ำ — ไม่งั้นถ้าอยู่โหมด US/HK ตอนกดรีเซ็ต
  // ช่อง Yahoo-only (Interest coverage/OCF ติดลบ/หุ้นเพิ่ม) จะยังค้างเป็นสถานะเก่า
  _fsApplyUniverseUI();
  if (!skipRun) {
    document.getElementById('fs-count').textContent = '';
    document.getElementById('fs-results').innerHTML = '<div class="empty">เลือก preset ด้านบน หรือกรอกเงื่อนไขเอง แล้วกด ค้นหา</div>';
    document.getElementById('fs-export').style.display = 'none';
    const moreBtn = document.getElementById('fs-more'); if (moreBtn) moreBtn.style.display = 'none';
    // ปุ่ม "รีเซ็ตทั้งหมด" กดจริง (ไม่ใช่แค่เคลียร์ฟอร์มก่อนโหลด/ก่อน apply preset ที่ผ่าน
    // skipRun=true) — ล้างค่าที่จำไว้ด้วย เหมือน resetScreener() ของเมนู Screener ปกติ
    localStorage.removeItem(_FS_LS);
  }
}

async function loadFscreener() {
  buildFsFilterUI();
  const gate = document.getElementById('fs-gate'), body = document.getElementById('fs-body');
  if (IS_STATIC) {
    gate.style.display = ''; body.style.display = 'none';
    gate.innerHTML = '🔬 Fundamental Screener ใช้ได้เฉพาะเวอร์ชันรันบนเครื่อง (local) — ต้องอ่านงบการเงินจาก financials.db ที่ไม่ได้อยู่บน GitHub';
    return;
  }
  if (_fsLoaded) return;
  gate.style.display = ''; gate.innerHTML = 'กำลังโหลดข้อมูลงบการเงิน...'; body.style.display = 'none';
  // ชื่อบริษัท US/HK สำหรับโชว์ใต้ symbol — โหลดคู่ขนาน ไม่ block ตาราง (พังก็แค่ไม่มีชื่อ)
  if (!Object.keys(_fsMirNames).length) {
    fetch('/api/mirror-names').then(r => r.json()).then(d => { _fsMirNames = d || {}; }).catch(() => {});
  }
  try {
    const r = await fetch('/api/factor-screener');
    const d = await r.json();
    _fsRows = d.rows || [];
    if (!_fsRows.length) {
      gate.innerHTML = (d.meta && d.meta.note) || 'ยังไม่มีข้อมูล — รัน build_snapshot.py ก่อน (local)';
      return;
    }
    _fsLoaded = true;
    gate.style.display = 'none'; body.style.display = '';
    const m = d.meta || {};
    _fsMainMetaText = `${m.count || _fsRows.length} หุ้น · คำนวณเมื่อ ${m.computed_at || '-'}`
      + (m.esg_count ? ` · CG/ESG ${m.esg_count} บริษัท (${m.esg_updated_at || '-'})` : '')
      + (m.shareholder_count ? ` · ผู้ถือหุ้นใหญ่ ${m.shareholder_count} ตัว (${m.shareholder_updated_at || '-'})` : '')
      + (m.foreign_count ? ` · ห้องต่างชาติ ${m.foreign_count} ตัว (${m.foreign_updated_at || '-'})` : '')
      + (m.analyst_count ? ` · นักวิเคราะห์ ${m.analyst_with_target || 0}/${m.analyst_count} ตัว (${(m.analyst_updated_at || '-').slice(0, 10)})` : '')
      + _finStaleBadge(m.stale, 'กด "🔄 อัพเดทงบการเงินทั้งหมด" หน้า 🩺 Data Health เพื่อ rebuild');
    document.getElementById('fs-meta').innerHTML = _fsMainMetaText;
    resetFscreener(true);   // เคลียร์ค่าฟอร์มก่อน (skipRun=true: ไม่แตะผลลัพธ์/localStorage)
    loadFsSettings();       // ดึงค่าที่เคยตั้งไว้ล่าสุดกลับมา (persist เหมือนเมนู Screener ปกติ)
    document.getElementById('fs-count').textContent = '';
    document.getElementById('fs-results').innerHTML = '<div class="empty">เลือก preset ด้านบน หรือกรอกเงื่อนไขเอง แล้วกด ค้นหา</div>';
    document.getElementById('fs-export').style.display = 'none';
    const moreBtn = document.getElementById('fs-more'); if (moreBtn) moreBtn.style.display = 'none';
  } catch (e) {
    gate.innerHTML = 'โหลดข้อมูลไม่สำเร็จ: ' + e.message;
  }
}

// ดึง CG/ESG rating ทั้งตลาดใหม่จาก SET.or.th (1 call — ดู /api/sync-esg) แล้วโหลด
// factor-screener ใหม่ทั้งชุดเพื่อให้คอลัมน์/filter ESG/CG ได้ค่าล่าสุด (ดู
// PLAN_set_api_expansion.txt งาน #3)
async function syncEsgData(btn) {
  const note = document.getElementById('fs-esg-sync-note');
  const orig = btn.textContent;
  btn.disabled = true;
  btn.textContent = '⏳ กำลังดึง...';
  if (note) note.textContent = '';
  try {
    const r = await _fetchTimeout('/api/sync-esg', 30000, undefined, { method: 'POST' });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error || 'ไม่ทราบสาเหตุ');
    if (note) note.textContent = `✓ อัพเดทแล้ว ${d.count} บริษัท (${d.updated_at || ''})`;
    _fsLoaded = false;   // บังคับ loadFscreener() ดึง /api/factor-screener ใหม่
    await loadFscreener();
  } catch (e) {
    if (note) note.textContent = `⚠ ไม่สำเร็จ: ${e.message}`;
  } finally {
    btn.disabled = false;
    btn.textContent = orig;
  }
}

// ดึงผู้ถือหุ้นใหญ่/free float (kind='shareholders') หรือโควตาต่างชาติ
// (kind='foreign') ทั้งกระดานใหม่จาก SET.or.th แล้วโหลด factor-screener ใหม่ —
// ดู PLAN_set_api_expansion.txt งาน #1/#2 (endpoint พารัลเลลทั้งกระดาน ~7-15 วิ)
async function syncOwnershipData(kind, btn) {
  const url = kind === 'foreign' ? '/api/sync-foreign-room' : '/api/sync-shareholders';
  const label = kind === 'foreign' ? 'ห้องต่างชาติ' : 'ผู้ถือหุ้นใหญ่';
  const note = document.getElementById('fs-esg-sync-note');
  const orig = btn.textContent;
  btn.disabled = true;
  btn.textContent = '⏳ กำลังดึง (~10 วิ)...';
  if (note) note.textContent = '';
  try {
    const r = await _fetchTimeout(url, 30000, undefined, { method: 'POST' });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error || 'ไม่ทราบสาเหตุ');
    if (note) note.textContent = `✓ ${label}: ${d.fetched}/${d.total} ตัว (${d.updated_at || ''})`;
    _fsLoaded = false;
    await loadFscreener();
  } catch (e) {
    if (note) note.textContent = `⚠ ไม่สำเร็จ: ${e.message}`;
  } finally {
    btn.disabled = false;
    btn.textContent = orig;
  }
}

function _fsReadConds() {
  const conds = [];
  const uni = document.getElementById('fs-universe')?.value;
  const skipNever = (uni === 'us' || uni === 'hk' || uni === 'jp');
  FS_FILTERS.forEach(f => {
    if (f.g) return;
    if (skipNever && FS_MIRROR_NEVER.has(f.k)) return;   // server ไม่คำนวณให้ mirror เลย — ข้าม
    if (f.cmp === 'bool') {
      const en = document.getElementById('fsen-' + f.k);
      if (en && en.checked) conds.push({ k: f.k, cmp: 'bool' });
      return;
    }
    if (f.cmp === 'eq') {
      const sel = document.getElementById('fsin-' + f.k);
      if (sel && sel.value !== '') conds.push({ k: f.k, cmp: 'eq', v: sel.value });
      return;
    }
    const el = document.getElementById('fsin-' + f.k);
    if (el && el.value !== '') {   // ช่องว่าง = ไม่กรอง
      const v = parseFloat(el.value);
      if (!isNaN(v)) conds.push({ k: f.k, cmp: f.cmp, v, nullOk: !!f.nullOk });
    }
    // filter แบบช่วง: ช่องฝั่งตรงข้าม (fsin-{k}-alt) เป็นเงื่อนไขอีกข้อบน key เดียวกัน
    // (ทั้ง filter client-side และ _keep ฝั่ง server วนทุกเงื่อนไขอยู่แล้ว — AND กันเอง)
    if (f.range) {
      const alt = document.getElementById('fsin-' + f.k + '-alt');
      if (alt && alt.value !== '') {
        const v2 = parseFloat(alt.value);
        if (!isNaN(v2)) conds.push({ k: f.k, cmp: f.cmp === 'gte' ? 'lte' : 'gte', v: v2, nullOk: !!f.nullOk });
      }
    }
  });
  return conds;
}

// mirror US/HK: ชุดใหญ่มาก (US ~17k) — กรองฝั่ง server ส่งกลับเฉพาะผลลัพธ์ ≤500
async function _runFscreenerMirror(uni, conds) {
  const myReqId = ++_fsMirrorReqId;
  const box = document.getElementById('fs-results');
  box.innerHTML = '<div class="empty" style="padding:24px">กำลังค้นหุ้น ' + uni.toUpperCase()
    + (uni === 'jp' ? ' (Nikkei 225)' : ' (Finnomena)') + '...</div>';
  const dir = _fsSort.dir < 0 ? 'desc' : 'asc';
  const url = `/api/factor-screener?universe=${uni}&filters=${encodeURIComponent(JSON.stringify(conds))}&sort=${_fsSort.key}&dir=${dir}&limit=500`;
  try {
    const r = await fetch(url);
    const d = await r.json();
    // มี request ใหม่กว่ายิงออกไปแล้ว (ผู้ใช้สลับตลาด/แก้ filter ระหว่างรอ) — ทิ้ง response
    // นี้ ไม่เขียนทับผลลัพธ์ที่ถูกต้องของ request ล่าสุด (response ไม่รับประกันลำดับกลับ)
    if (myReqId !== _fsMirrorReqId) return;
    const rows = d.rows || [];
    _fsResultCache = rows;
    const total = d.total || rows.length;
    // meta ของ mirror แยกจาก snapshot หลัก (คนละตารางคนละเวลาคำนวณ) — เดิมช่อง
    // fs-meta ค้างโชว์ "คำนวณเมื่อ" ของ snapshot ไทย+DR แม้กำลังดูข้อมูล US/HK อยู่
    const mm = d.meta || {};
    const mCount = (mm.counts && mm.counts[uni.toUpperCase()]) ?? total;
    document.getElementById('fs-meta').innerHTML =
      `${mCount.toLocaleString()} หุ้น (mirror) · คำนวณเมื่อ ${mm.computed_at || '-'}`
      + _finStaleBadge(mm.stale, 'กด "🔄 อัพเดทงบการเงินทั้งหมด" หน้า 🩺 Data Health เพื่อ rebuild');
    document.getElementById('fs-count').textContent =
      `พบ ${total.toLocaleString()} หุ้น` + (total > rows.length ? ` (แสดง ${rows.length} อันดับแรก — เพิ่มเงื่อนไขเพื่อแคบผล)` : '');
    document.getElementById('fs-export').style.display = rows.length ? '' : 'none';
    const moreBtn = document.getElementById('fs-more');
    if (moreBtn) moreBtn.style.display = 'none';   // mirror US/HK แบ่งหน้าฝั่ง server (limit param) ไม่ใช่ที่นี่
    renderFsTable(rows);
    const note = document.createElement('div');
    note.style.cssText = 'font-size:11px;color:var(--text2);margin:4px 0 8px';
    // JP: คนละสถานการณ์กับ US/HK ทั้งหมด — ไม่มี Finnomena เลย (225 ตัวคือทั้ง universe ไม่ใช่
    // "สมาชิกดัชนีหลักส่วนหนึ่งของก้อนใหญ่"), coverage PE/PBV/ROE/F-Score/Z-Score/CAGR สูง
    // (>90%) เพราะ sync Yahoo annual ครบทุกตัวไปแล้ว แต่ field ที่ต้องใช้งบรายไตรมาส (P/S/PEG/
    // %YoY-QoQ/div_yield) เป็น None ถาวรเสมอ (ไม่ใช่ "ยังไม่เคย sync" แบบ US/HK)
    if (uni === 'jp') {
      note.innerHTML = 'ℹ หุ้น JP ชุดนี้คือสมาชิก <b>Nikkei 225 ทั้งหมด</b> (225 ตัว ไม่ใช่มิเรอร์ทั้งตลาดแบบ US/HK เพราะ Finnomena ไม่มีข้อมูลตลาดนี้เลย) — ตัวเลขจาก <b>Yahoo annual</b> ล้วน: PE/PBV/ROE/margin/F-Score/Z-Score/CAGR รายปีมีครบเกิน 90% ของตัว, ราคาสด (RS/EMA200/high 52wk/RVOL) มีครบทุกตัวเพราะทั้ง universe อยู่ในดัชนีหลักอยู่แล้ว'
        + ' · <b>P/S, PEG, รายได้/กำไร %YoY-QoQ รายไตรมาส, ปันผล%</b> เป็นค่าว่างถาวร (ต้องใช้งบรายไตรมาสที่ Finnomena ไม่มีให้ตลาดนี้ — ไม่ใช่บั๊ก)';
    } else {
      note.innerHTML = 'ℹ หุ้น US/HK ชุดนี้ใช้งบ <b>Finnomena ล้วน</b> เป็นหลัก — เฉพาะหุ้นที่เคย sync งบ <b>Yahoo annual</b> แล้ว (สมาชิกดัชนีหลักส่วนใหญ่ + ตัวที่เคยเปิดดู/on-demand fetch) จะมีค่ากลุ่ม net cash / cash cycle / goodwill / buyback / CAGR รายปี / interest coverage / dilution / F-Score / Z-Score / FCF Yield / FCF คุ้มปันผล ครบ — ตัวที่ยังไม่เคย sync จะไม่มีค่ากลุ่มนี้ (ไม่ใช่บั๊ก)'
        + ' · FCF Yield% ต้องมี market cap สดด้วย เลยมีเฉพาะหุ้นในดัชนีหลักที่ sync Yahoo แล้ว, FCF คุ้มปันผลต้องเคยจ่ายปันผลด้วย'
        + (uni === 'us'
          ? ' · ค่าสดจากราคา (RS, EMA200, high 52wk, RVOL) มีเฉพาะหุ้นใน S&P500/Dow/Nasdaq 100'
          : ' · ค่าสดจากราคา (RS, EMA200, high 52wk, RVOL) มีเฉพาะหุ้นใน HSI/HSCEI/HSTECH');
    }
    // เตือนสีเหลืองถ้าเปิด filter ที่ "มีค่าเฉพาะบางตัว" (ราคา หรืองบ Yahoo) — หุ้นที่ไม่เข้า
    // เงื่อนไข (นอกดัชนีหลัก / ยังไม่เคย sync Yahoo) จะถูกตัดออกจากผลทั้งหมดโดยปริยาย เตือนชัดๆ
    // กันเข้าใจผิดว่าหุ้นหาย/บั๊ก (รวม 2 คำเตือนเข้าด้วยกันถ้าเปิดทั้งคู่พร้อมกัน) — ข้าม filter
    // ราคาสำหรับ JP เพราะครบทุกตัวอยู่แล้ว ไม่มี "นอกดัชนี" ให้เตือน
    const warnParts = [];
    if (uni !== 'jp' && conds.some(c => FS_PRICE_ONLY.has(c.k))) {
      const idxLabel = uni === 'us' ? 'S&P500 / Dow / Nasdaq 100' : 'HSI / HSCEI / HSTECH';
      warnParts.push(`ฟิลเตอร์ราคา (RS / EMA200 / high 52wk / RVOL) มีค่าเฉพาะหุ้นใน ${idxLabel} — หุ้น ${uni.toUpperCase()} นอกดัชนีถูกตัดออกจากผลทั้งหมด`);
    }
    if (conds.some(c => FS_YAHOO_ONLY.has(c.k))) {
      warnParts.push(uni === 'jp'
        ? 'ฟิลเตอร์งบ Yahoo (CAGR/F-Score/Z-Score/FCF ฯลฯ) — ~10% ของหุ้น JP ไม่มีค่า (เช่น ขาดทุน/EPS ติดลบ) ถูกตัดออกจากผลทั้งหมด'
        : 'ฟิลเตอร์งบ Yahoo (CAGR/F-Score/Z-Score/FCF ฯลฯ) มีค่าเฉพาะหุ้นที่เคย sync งบ Yahoo annual แล้ว — ตัวที่ยังไม่เคย sync ถูกตัดออกจากผลทั้งหมด');
    }
    if (warnParts.length) {
      note.innerHTML = `<span style="color:#e3b341">⚠ ${warnParts.join(' · ')}</span><br>` + note.innerHTML;
    }
    box.insertBefore(note, box.firstChild);
  } catch (e) {
    if (myReqId !== _fsMirrorReqId) return;   // request เก่าที่ถูกแทนที่แล้ว — เงียบไว้ ไม่ทับ error ของอันใหม่
    box.innerHTML = '<div class="empty" style="color:var(--red)">ค้นไม่สำเร็จ: ' + e.message + '</div>';
  }
}

// เช็คช่วงกลับด้าน (ขั้นต่ำ > ไม่เกิน) ก่อนค้นหา — เดิมกดค้นหาแล้วได้ "พบ 0 หุ้น" เงียบๆ
// โดยไม่รู้สาเหตุ (เช่น พิมพ์ ROE ขั้นต่ำ 80 ไม่เกิน 15 เผลอสลับช่อง) เตือนชัดๆ แทนปล่อยให้งง
function _fsRangeWarnings() {
  const warns = [];
  FS_FILTERS.forEach(f => {
    if (!f.range) return;
    const { minId, maxId } = _fsRangeIds(f);
    const minEl = document.getElementById(minId), maxEl = document.getElementById(maxId);
    const minV = (minEl && minEl.value !== '') ? parseFloat(minEl.value) : null;
    const maxV = (maxEl && maxEl.value !== '') ? parseFloat(maxEl.value) : null;
    if (minV != null && maxV != null && !isNaN(minV) && !isNaN(maxV) && minV > maxV) {
      const lbl = f.label.replace(/\s*[≥≤]\s*$/, '');
      warns.push(`${lbl}: ขั้นต่ำ (${minV}) มากกว่าไม่เกิน (${maxV}) — สลับช่องหรือแก้ค่าก่อนค้นหา`);
    }
  });
  return warns;
}

function runFscreener() {
  if (!_fsLoaded) return;
  const rangeWarnings = _fsRangeWarnings();
  if (rangeWarnings.length) {
    document.getElementById('fs-count').textContent = '';
    document.getElementById('fs-export').style.display = 'none';
    const moreBtn = document.getElementById('fs-more'); if (moreBtn) moreBtn.style.display = 'none';
    document.getElementById('fs-results').innerHTML =
      '<div class="empty" style="color:var(--red)">⚠ ค่าช่วงกลับด้าน — ช่วงนี้ไม่มีหุ้นไหนผ่านได้แน่นอน:<br>'
      + rangeWarnings.map(w => `• ${w}`).join('<br>') + '</div>';
    return;
  }
  const uni = document.getElementById('fs-universe').value;
  const conds = _fsReadConds();
  // สแนปช็อตคอลัมน์เสริมตอนกด "ค้นหา" ครั้งนี้ — ใช้ทั้ง universe หลักและ mirror US/HK
  _fsExtraCols = _fsActiveExtraCols(conds);
  // คอลัมน์ที่กำลังใช้เรียงอยู่ (_fsSort.key) อาจหายไปจาก _fsExtraCols รอบนี้ (สลับ universe/
  // ล้าง filter ที่เคยสร้างคอลัมน์นั้นทิ้ง) — ถ้าไม่รีเซ็ต mirror US/HK จะส่ง sort= เป็น field ที่
  // server ไม่มีจริง กลายเป็น no-op เงียบๆ ไม่มี indicator เตือน (code review 2026-08-26)
  if (!FS_COLS_KEYS.has(_fsSort.key) && !_fsExtraCols.some(c => c.k === _fsSort.key)) {
    _fsSort = { key: 'roe', dir: -1 };
  }
  if (uni === 'us' || uni === 'hk' || uni === 'jp') { _runFscreenerMirror(uni, conds); return; }
  // กลับมา universe หลัก (ทั้งหมด/ไทย/DR) — คืนข้อความ fs-meta ของ snapshot หลัก
  // เผื่อรอบก่อนหน้าอยู่ที่ US/HK แล้วค้างโชว์ meta ของ mirror อยู่
  const metaEl = document.getElementById('fs-meta');
  if (metaEl && _fsMainMetaText) metaEl.innerHTML = _fsMainMetaText;
  if (!_fsRows) return;

  let rows = _fsRows.filter(r => {
    if (uni === 'th' && r.is_dr) return false;
    if (uni === 'dr' && !r.is_dr) return false;
    for (const c of conds) {
      const val = r[c.k];
      if (c.cmp === 'bool') { if (!val) return false; continue; }
      if (c.cmp === 'eq') { if (val !== c.v) return false; continue; }
      if (val == null || isNaN(val)) {
        if (c.nullOk) continue;   // risk filter: ไม่มีข้อมูล = ไม่ตัด (ตัดเฉพาะตัวที่รู้ว่าแย่)
        return false;             // filter ปกติ: ไม่มีข้อมูล = ตัดออกเมื่อกรองด้วยเงื่อนไขนั้น
      }
      if (c.cmp === 'gte' && val < c.v) return false;
      if (c.cmp === 'lte' && val > c.v) return false;
    }
    return true;
  });

  const sc = _fsSort;
  rows.sort((a, b) => {
    const x = a[sc.key], y = b[sc.key];
    if (x == null) return 1; if (y == null) return -1;
    if (typeof x === 'string') return sc.dir * x.localeCompare(y);
    return sc.dir * (x - y);
  });

  _fsResultCache = rows;
  _fsShowLimit = 300;
  _fsRenderPage();
}

let _fsResultCache = [];
let _fsShowLimit = 300;

// เพจผลลัพธ์ฝั่ง client (universe หลัก ทั้งหมด/ไทย/DR) — ใช้ทั้งตอนค้นหาใหม่และกด "แสดงเพิ่ม"
// (mirror US/HK แบ่งหน้าฝั่ง server อยู่แล้วผ่าน limit=500 ไม่ผ่านฟังก์ชันนี้)
function _fsRenderPage() {
  const rows = _fsResultCache;
  document.getElementById('fs-count').textContent = `พบ ${rows.length} หุ้น`
    + (rows.length > _fsShowLimit ? ` (แสดง ${_fsShowLimit.toLocaleString()} ตัวแรก)` : '');
  document.getElementById('fs-export').style.display = rows.length ? '' : 'none';
  const moreBtn = document.getElementById('fs-more');
  if (moreBtn) moreBtn.style.display = rows.length > _fsShowLimit ? '' : 'none';
  renderFsTable(rows.slice(0, _fsShowLimit));
}

function fsShowMore() {
  _fsShowLimit += 300;
  _fsRenderPage();
}

function fsSort(key) {
  if (_fsSort.key === key) _fsSort.dir *= -1;
  else { _fsSort.key = key; _fsSort.dir = (key === 'symbol' || key === 'market') ? 1 : -1; }
  runFscreener();
}

function _fsFmt(v, key) {
  if (v == null || (typeof v === 'number' && isNaN(v))) return '<span style="color:var(--text2)">–</span>';
  if (typeof v === 'string') return v;
  if (key === 'high_season_q') return 'Q' + v;   // ไตรมาสไฮซีซั่น
  if (key === 'f_score') return Math.round(v) + '/9';
  if (key === 'profit_accel_streak' || key === 'rev_accel_streak' || key === 'quarters_available' ||
      key === 'roe15_streak_q' || key === 'rs') return Math.round(v);
  if (key === 'pct_off_high52' || key === 'profit_yoy_q' || key === 'profit_ttm_yoy' ||
      key === 'rev_yoy_q' || key === 'rev_ttm_yoy' || key === 'rev_qoq' || key === 'profit_qoq' ||
      key === 'analyst_target_upside') {
    const x = Math.round(v * 10) / 10;           // 1 ทศนิยมพอ + ใส่เครื่องหมาย + ให้ค่าบวก
    return (x > 0 ? '+' : '') + x;
  }
  return Math.round(v * 100) / 100;
}

function _fsDisplayName(r) {
  // ชื่อบริษัทโชว์ใต้ symbol: main snapshot มี r.name (DR) ส่วน mirror US/HK ชื่อ = ticker
  // ให้เปิดจาก mirror_names.json ที่โหลดไว้ (_fsMirNames) — หุ้นไทย name = symbol ไม่ต้องโชว์ซ้ำ
  if (r.name && r.name !== r.symbol) return r.name;
  const m = (_fsMirNames[r.market] || {})[r.symbol];
  return m || '';
}

const _SEP_CSS = 'border-left:1px solid var(--border);padding-left:10px';

// ค่า + สีต่อคอลัมน์ (ไม่รวม symbol — ใช้ทั้งตารางหลักและ popup รายละเอียด กันโค้ดสีตรง
// z_zone/market เพี้ยนกันระหว่างสองที่)
function _fsColHtml(r, c) {
  const v = _fsFmt(r[c.k], c.k);
  if (c.k === 'market') {
    const cc = FS_MKT_BADGE[r.market] || 'var(--text2)';
    return `<span style="background:${cc}22;color:${cc};padding:1px 7px;border-radius:4px;font-size:10.5px;font-weight:600">${r.market || '—'}</span>`;
  }
  if (c.k === 'z_zone') {
    const zoneColor = { safe: 'var(--green,#2ea043)', grey: '#d29922', distress: 'var(--red,#da3633)' }[r.z_zone] || '';
    const zoneLabel = { safe: 'ปลอดภัย', grey: 'เทา', distress: 'เสี่ยง' }[r.z_zone];
    return zoneLabel
      ? `<span title="${_zScoreTooltip(r.z_variant, r.z_zone, zoneLabel)}" style="color:${zoneColor};font-weight:600;cursor:help">${zoneLabel}</span>`
      : (r.z_excluded_reason
          ? `<span title="${r.z_excluded_reason}" style="color:var(--text2);cursor:help">–</span>`
          : '<span style="color:var(--text2)">–</span>');
  }
  const raw = r[c.k];
  const clr = FS_COL_CLR[c.k];
  if (clr && raw != null && (typeof raw === 'number' || c.k === 'esg_rating')) {
    const col = clr(raw);
    if (col) return `<span style="color:${col};font-weight:600">${v}</span>`;
  }
  return v;
}

// TradingView arrow ต่อแถว Screener+ — ขึ้นกับ universe ที่เลือก: us/hk/jp (mirror) ใช้ raw
// ticker ตรงๆ ผ่าน helper ตลาดนั้น, DR จริง (uni='dr' หรือ 'all'+is_dr) ต้อง map ผ่าน _drData
// (r.symbol ที่นี่คือ 'sym' ของ DR universe ซึ่งเป็นคนละค่ากับ 'yf' เสมอสำหรับหุ้น HK/EU เช่น
// sym='GIGA' แต่ yf='3986.HK' — ต้อง lookup หา yf ก่อนค่อยแปลงเป็น TradingView symbol) ถ้ายังไม่
// เคยโหลด _drData (ยังไม่เคยเปิดหน้า DR ในเซสชันนี้) โหลด background แล้ว re-render ทับให้เอง
// drSymToYf: Map sym->yf ที่ renderFsTable สร้างครั้งเดียวก่อน render (เดิม .find() เชิงเส้นบน
// _drData ต่อแถว DR ทุกแถว — O(rows×|_drData|) พอ _drData มี ~290 ตัวกับผลลัพธ์เต็มหน้า ~300
// แถวก็หลักหมื่นครั้งเทียบต่อ render — code review 2026-09-02)
function _fsSymTvLink(r, uni, drSymToYf) {
  if (uni === 'us') return _usTvLink(r.symbol);
  if (uni === 'hk') return _hkTvLink(r.symbol);
  if (uni === 'jp') return _jpTvLink(r.symbol);
  if (r.is_dr) {
    const yf = drSymToYf ? drSymToYf.get(r.symbol) : null;
    return yf ? `<a class="tv-link" href="https://www.tradingview.com/chart/?symbol=${yfToTVSym(yf)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView">↗</a>` : '';
  }
  return tvLink(r.symbol);   // หุ้นไทย (uni='th' หรือ 'all' ไม่ใช่ DR)
}

function renderFsTable(rows) {
  if (!rows.length) {
    document.getElementById('fs-results').innerHTML = '<div class="empty">ไม่พบหุ้นที่ตรงเงื่อนไข ลองผ่อนเกณฑ์</div>';
    return;
  }
  const uni = document.getElementById('fs-universe')?.value;
  if (!_drData && (uni === 'dr' || uni === 'all') && rows.some(r => r.is_dr)) {
    _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000).then(r => r.json())
      .then(d => { if (d.stocks) { _drData = d.stocks; _drLoaded = true; renderFsTable(rows); } })
      .catch(() => {});
  }
  const drSymToYf = _drData ? new Map(_drData.map(x => [x.sym, x.yf])) : null;
  // ต่อท้ายด้วยคอลัมน์เสริมจากตัวกรองที่ตั้งไว้รอบนี้ (_fsExtraCols) — field ที่ยังไม่มี
  // คอลัมน์ตายตัวใน FS_COLS จะโผล่ให้เห็น/เรียงลำดับได้โดยไม่ต้องเปิด popup รายละเอียดทีละตัว
  const cols = _fsAllCols();
  const head = cols.map(c => {
    const arrow = _fsSort.key === c.k ? (_fsSort.dir < 0 ? ' ▼' : ' ▲') : '';
    const tip = c.tip ? ` title="${c.tip}"` : '';
    return `<th onclick="fsSort('${c.k}')"${tip} style="cursor:pointer;white-space:nowrap;position:sticky;top:0;background:var(--bg2);z-index:2;${c.sep ? _SEP_CSS : ''}">${c.label}${arrow}</th>`;
  }).join('');
  const body = rows.map(r => {
    const name = _fsDisplayName(r).replace(/</g, '&lt;');
    const tds = cols.map(c => {
      const style = `text-align:${c.txt ? 'left' : 'right'};white-space:nowrap;${c.sep ? _SEP_CSS : ''}`;
      let v;
      if (c.k === 'symbol') {
        const sub = name ? `<div style="font-size:10px;color:var(--text2);font-weight:400;max-width:150px;overflow:hidden;text-overflow:ellipsis">${name}</div>` : '';
        v = `<a href="${_fsDeepLink(r.symbol, r.is_dr)}" onclick="fsOpenDetail('${r.symbol}', ${r.is_dr ? 'true' : 'false'}); return false"
               style="color:var(--blue);font-weight:700;text-decoration:none" title="ดูรายละเอียด ${r.symbol}">${r.symbol}</a>${_fsSymTvLink(r, uni, drSymToYf)}${sub}`;
      } else {
        v = _fsColHtml(r, c);
      }
      return `<td style="${style}">${v}</td>`;
    }).join('');
    return `<tr>${tds}</tr>`;
  }).join('');
  // กล่องสูงคงที่ + header ติดขอบบนตอน scroll — ดูผลหลายร้อยแถวได้โดยไม่หลุดหัวตาราง
  document.getElementById('fs-results').innerHTML =
    `<div style="overflow:auto;max-height:74vh;border:1px solid var(--border);border-radius:8px">
       <table class="data-table" style="font-size:12px;min-width:1280px">
       <thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
}

function exportFscreenerCSV() {
  if (!_fsResultCache.length) return;
  const allCols = _fsAllCols();
  const cols = allCols.map(c => c.k);
  const header = allCols.map(c => c.label).join(',');
  const lines = _fsResultCache.map(r => cols.map(k => {
    const v = r[k]; return (v == null) ? '' : (typeof v === 'string' ? `"${v.replace(/"/g, '""')}"` : v);
  }).join(','));
  const csv = '﻿' + [header, ...lines].join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  // universe US/HK กรองฝั่ง server แล้วส่งกลับสูงสุด 500 แถวแรกเสมอ (ดู _runFscreenerMirror) —
  // ใส่ไว้ในชื่อไฟล์กันเข้าใจผิดว่า export ได้ทุกตัวที่ตรงเงื่อนไข
  const uni = document.getElementById('fs-universe')?.value || 'all';
  const suffix = (uni === 'us' || uni === 'hk') ? `_${uni}_top500` : `_${uni}`;   // jp ไม่ต้อง
  // เติม "_top500" เหมือน us/hk เพราะฝั่ง server ไม่ตัดที่ limit=500 จริง (225 < 500 อยู่แล้ว)
  a.download = `fundamental_screener${suffix}_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
}

// ============================================================
// PEER COMPARE — 🆚 เทียบเพื่อนร่วม sector/industry (งาน #3 PLAN_stock_study_suite.txt)
// เฉพาะหุ้นไทยตอนนี้ (ดู /api/peer-compare ใน app.py) — ไม่คำนวณอะไรฝั่ง client
// นอกจาก percentile สีต่อคอลัมน์ (ข้อมูลตัวเลขมาจาก factor_snapshot อยู่แล้ว)
// ============================================================
let _peerRows = [], _peerMedian = null, _peerMeta = null;
let _peerPreset = 'valuation';
let _peerViewMode = 'table';

const PEER_COLS = {
  valuation: [
    { k: 'pe',        label: 'PE',     lowerBetter: true,  tip: 'ราคาต่อกำไร — ต่ำกว่าเพื่อนอาจถูกกว่า' },
    { k: 'pbv',       label: 'PBV',    lowerBetter: true,  tip: 'ราคาต่อมูลค่าทางบัญชี' },
    { k: 'ps_value',  label: 'P/S',    lowerBetter: true,  tip: 'ราคาต่อยอดขาย — ใช้ได้แม้หุ้นขาดทุน' },
    { k: 'div_yield', label: 'ปันผล%', lowerBetter: false, tip: 'อัตราปันผลต่อปี' },
    { k: 'peg',       label: 'PEG',    lowerBetter: true,  tip: 'PE ÷ กำไรโต TTM — ≤1 เข้าเกณฑ์ GARP' },
  ],
  quality: [
    { k: 'roe',               label: 'ROE%',    lowerBetter: false, tip: 'ผลตอบแทนต่อส่วนผู้ถือหุ้น' },
    { k: 'roa',                label: 'ROA%',    lowerBetter: false, tip: 'ผลตอบแทนต่อสินทรัพย์รวม' },
    { k: 'gross_margin',       label: 'GM%',     lowerBetter: false, tip: 'อัตรากำไรขั้นต้น' },
    { k: 'net_margin',         label: 'NM%',     lowerBetter: false, tip: 'อัตรากำไรสุทธิ' },
    { k: 'de_ratio',           label: 'D/E',     lowerBetter: true,  tip: 'หนี้สินต่อทุน' },
    { k: 'interest_coverage',  label: 'IntCov',  lowerBetter: false, tip: 'ความสามารถจ่ายดอกเบี้ย' },
    { k: 'ocf_ni_ratio',       label: 'OCF/NI',  lowerBetter: false, tip: 'คุณภาพกำไร — เงินสดเข้าจริง ÷ กำไร (TTM)' },
    { k: 'f_score',            label: 'F-Score', lowerBetter: false, tip: 'Piotroski F-Score 0-9' },
    { k: 'z_score',            label: 'Z-Score', lowerBetter: false, tip: "Altman Z''-Score — สีตามโซนปลอดภัย/เทา/เสี่ยง (hover ตัวเลขแต่ละแถวดูคำเตือนธุรกิจ WC ติดลบ)" },
  ],
  growth: [
    { k: 'rev_cagr',        label: 'RevCAGR%',     lowerBetter: false, tip: 'รายได้โตเฉลี่ยต่อปี' },
    { k: 'profit_cagr',     label: 'ProfitCAGR%',  lowerBetter: false, tip: 'กำไรโตเฉลี่ยต่อปี' },
    { k: 'rev_ttm_yoy',     label: 'RevTTM%',      lowerBetter: false, tip: 'รายได้ TTM เทียบปีก่อน' },
    { k: 'profit_ttm_yoy',  label: 'ProfitTTM%',   lowerBetter: false, tip: 'กำไร TTM เทียบปีก่อน' },
    { k: 'revenue_streak',  label: 'RevStreak(ปี)', lowerBetter: false, tip: 'รายได้โตต่อเนื่องกี่ปี' },
    { k: 'growth_score',    label: 'GrowthScore',  lowerBetter: false, tip: 'สกอร์รวมความแข็งแรงของการเติบโต (รวมหลายปัจจัยข้างต้น)' },
    { k: 'rule_of_40',      label: 'Rule of 40',   lowerBetter: false, tip: 'รายได้โต% + Net Margin% — ≥40 ดี' },
  ],
  // ธรรมาภิบาล & ความยั่งยืน (SET.or.th ทางการ) — หุ้นไทยเท่านั้น · มีข้อมูลแค่ ~38% ของตลาด
  // ค่าในตารางเป็นตัวเลข (esg_rank 1-4 / cg_score 1-5) ให้เรียง+ลงสี percentile ได้ แต่แสดงผล
  // เป็นข้อความ (เรตติ้ง AAA.. / ดาว) ผ่าน render() ดู PLAN_set_api_expansion.txt งาน #3C
  governance: [
    { k: 'esg_rank', label: 'SETESG', lowerBetter: false,
      tip: 'SETESG Rating ทางการของตลาดหลักทรัพย์ฯ (AAA ดีสุด → BBB) — เรียง/สีตามอันดับ · มีข้อมูล ~38% ของตลาด',
      render: r => r.esg_rating || '<span style="color:var(--text2)">–</span>' },
    { k: 'cg_score', label: 'CG', lowerBetter: false,
      tip: 'คะแนนกำกับดูแลกิจการ 1-5 จาก IOD — ~85% ของบริษัทที่ประเมินได้ 5 เต็ม ใช้ตัดตัวต่ำได้ ไม่เหมาะจัดอันดับ',
      render: r => r.cg_score != null ? '★'.repeat(Math.max(0, Math.min(5, r.cg_score)))
                                      : '<span style="color:var(--text2)">–</span>' },
  ],
};

let _peerMarket = 'TH';
let _peerFetchToken = 0;   // กัน response เก่าที่มาถึงทีหลัง (สลับหุ้น/กลุ่มเร็วๆ ติดกัน) เขียนทับผลของ request ใหม่กว่า

function initPeerPage() {
  initFinPage();        // ให้ fin-set-datalist populate ก่อน แล้วโคลนมาใช้
  _peerBuildDatalist();
  _peerBuildSectorSelect();
}

function setPeerMarket(mkt, btn) {
  _peerMarket = mkt;
  document.querySelectorAll('#peer-tab-th,#peer-tab-us,#peer-tab-hk,#peer-tab-jp').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  // พรีเซ็ต ESG/CG มีเฉพาะหุ้นไทย (SET.or.th) — ซ่อนปุ่มในตลาดอื่น + ถ้ากำลังเลือกอยู่ให้กลับ
  // ไปพรีเซ็ต Valuation ไม่งั้นตารางตลาด US/HK/JP จะโชว์คอลัมน์ว่างทั้งแถบ
  const govBtn = document.getElementById('peer-preset-governance');
  if (govBtn) {
    govBtn.style.display = mkt === 'TH' ? '' : 'none';
    if (mkt !== 'TH' && _peerPreset === 'governance') {
      setPeerPreset('valuation', document.getElementById('peer-preset-valuation'));
    }
  }
  const inp = document.getElementById('peer-sym');
  if (inp) { inp.value = ''; inp.placeholder = mkt === 'TH' ? 'เช่น CPALL, PTT, KBANK' : mkt === 'US' ? 'เช่น AAPL, MSFT, NVDA' : mkt === 'JP' ? 'เช่น 7203.T, 6758.T' : 'เช่น 0700.HK, 9988.HK'; }
  const sel = document.getElementById('peer-sector-select');
  if (sel) { sel.innerHTML = '<option value="">— เลือก Sector ตรง ๆ —</option>'; sel.dataset.built = ''; }
  document.getElementById('peer-meta').textContent = '';
  // สลับตลาดต้องล้างผลลัพธ์ค้างของตลาดก่อนหน้าด้วย ไม่งั้นกด preset/view mode ก่อนค้นหุ้นใหม่
  // จะ render ตารางตลาดเก่ากลับมาแสดงทั้งที่แท็บสลับไปแล้ว (renderPeerResults ยึด _peerRows เดิม)
  // ++token ทั้งคู่กันด้วย — request ของตลาดเก่าที่ยังค้างอยู่ (fetch ช้า/mirror on-demand)
  // resolve ทีหลังจะโดนทิ้งแทนที่จะมาเขียนทับข้อมูลตลาดใหม่ที่เพิ่งสลับมา
  _peerFetchToken++; _peerGroupFetchToken++;
  _peerRows = []; _peerMedian = null; _peerMeta = null; _peerSort = null;
  _peerGroupSyms = null; _peerGroupRows = null; _peerGroupSort = {};
  _peerDestroyScatterChart();
  document.getElementById('peer-results').innerHTML = '<div class="empty">พิมพ์ชื่อหุ้นหรือเลือก Sector เพื่อเริ่มเทียบ</div>';
  _peerBuildDatalist();
  _peerBuildSectorSelect();
}

async function _peerBuildDatalist() {
  const dl = document.getElementById('peer-datalist');
  if (!dl) return;
  if (_peerMarket === 'TH') {
    const src = document.getElementById('fin-set-datalist');
    if (!src || !src.childElementCount) return;
    const key = 'TH:' + src.childElementCount;
    if (dl.dataset.key === key) return;
    dl.innerHTML = '';
    const frag = document.createDocumentFragment();
    [...src.children].forEach(o => frag.appendChild(o.cloneNode(true)));
    dl.appendChild(frag);
    dl.dataset.key = key;
    return;
  }
  // _usData/_hkData/_jpData เป็น top-level `let` ไม่ใช่ property ของ window — window['_usData']
  // undefined เสมอ (เดิม sector dropdown/autocomplete US/HK/JP ตายสนิท + ยิง index-metrics ซ้ำ
  // ทุกครั้งที่สลับแท็บ) ใช้ getter/setter ผ่าน _FS_MIRROR_IDX เหมือน Tearsheet/Screener+ + เช็ค
  // d.error ก่อน cache (route คืน {error} 500 ตอนไฟล์ metrics หาย)
  const idx = _FS_MIRROR_IDX[_peerMarket.toLowerCase()];
  let justLoaded = false;
  if (!idx.get()) {
    try {
      const d = await (await fetch(idx.endpoint)).json();
      if (d && !d.error && d.stocks) { idx.set(d); justLoaded = true; }
    } catch { return; }
  }
  // sector select ถูกเรียกคู่กันตอนเปิดหน้า/สลับแท็บ แต่ตอนนั้นข้อมูลตลาดยังไม่มา (async
  // ด้านบน) เลยออกจากฟังก์ชันไปเปล่าๆ — ถ้าเพิ่งโหลดเสร็จรอบนี้ต้อง rebuild sector select เอง
  // ไม่งั้น dropdown ค้างว่างจนกว่าจะสลับแท็บไปมา
  if (justLoaded) _peerBuildSectorSelect();
  const stocks = idx.get()?.stocks || [];
  const mirror = (await _loadMirrorSymbols())[_peerMarket] || [];
  const key = _peerMarket + ':' + stocks.length + ':' + mirror.length;
  if (dl.dataset.key === key) return;
  dl.innerHTML = '';
  const frag = document.createDocumentFragment();
  const seen = new Set();
  stocks.forEach(s => {
    seen.add(s.symbol);
    const o = document.createElement('option');
    o.value = s.symbol; o.label = s.name || s.symbol;
    frag.appendChild(o);
  });
  // หุ้น mirror นอกดัชนีหลัก — sector ดึงแบบ on-demand ตอนเลือกจริง (ดู /api/peer-compare)
  // JP ไม่มี mirror นอกดัชนีหลัก (ไม่มี raw universe แบบ US/HK) — mirror ที่ได้คือสมาชิก
  // Nikkei225 เองทั้งหมด ซึ่งอยู่ใน stocks (seen) แล้ว ไม่ต้องเติม suffix
  mirror.forEach(rawSym => {
    const sym = _peerMarket === 'HK' ? rawSym + '.HK' : _peerMarket === 'JP' ? rawSym + '.T' : rawSym;
    if (seen.has(sym)) return;
    const o = document.createElement('option');
    o.value = sym;
    frag.appendChild(o);
  });
  dl.appendChild(frag);
  dl.dataset.key = key;
}

function _peerBuildSectorSelect() {
  const sel = document.getElementById('peer-sector-select');
  if (!sel || sel.dataset.built) return;
  let sectors = [];
  if (_peerMarket === 'TH') {
    if (!DATA || !DATA.stocks) return;
    sectors = [...new Set(DATA.stocks.map(s => s.sector).filter(Boolean))].sort();
  } else {
    // ผ่าน _FS_MIRROR_IDX getter — _usData/_hkData/_jpData ไม่ใช่ property ของ window
    const stocks = _FS_MIRROR_IDX[_peerMarket.toLowerCase()].get()?.stocks;
    if (!stocks) return;   // ยังไม่โหลด — _peerBuildDatalist ที่เรียกคู่กันจะโหลดให้แล้ว rerun เอง
    sectors = [...new Set(stocks.map(s => s.sector).filter(Boolean))].sort();
  }
  sectors.forEach(s => {
    const opt = document.createElement('option');
    opt.value = s; opt.textContent = s;
    sel.appendChild(opt);
  });
  sel.dataset.built = '1';
}

function setPeerPreset(preset, btn) {
  _peerPreset = preset;
  document.querySelectorAll('#page-peer .filter-btn[id^="peer-preset-"]').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  // พรีเซ็ตคอลัมน์มีผลแค่มุมมอง "ตาราง" — ในมุมมอง scatter/group/workspace การกดพรีเซ็ตไม่เปลี่ยน
  // อะไร แต่ renderPeerResults จะไปยิง /api/peer-group-detail ใหม่โดยเปล่าประโยชน์
  if (_peerRows.length && _peerViewMode === 'table') renderPeerResults();
}

function setPeerViewMode(mode, btn) {
  _peerViewMode = mode;
  document.querySelectorAll('#page-peer .filter-btn[id^="peer-view-"]').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  // แถบพรีเซ็ตคอลัมน์ (Valuation/คุณภาพ/Growth) มีผลแค่มุมมอง "ตาราง" เท่านั้น — scatter เป็นกราฟ
  // ตายตัว, การ์ดเทียบกลุ่มโชว์ทุกหมวดพร้อมกันในตารางแยกอยู่แล้วไม่ได้กรองตามพรีเซ็ต — ซ่อนทิ้งกัน
  // สับสนว่ากดพรีเซ็ตแล้ว "เหมือนเดิมทุกปุ่ม" (พรีเซ็ตไม่มีผลจริงๆ ในสองมุมมองนี้)
  const presetRow = document.getElementById('peer-preset-row');
  if (presetRow) presetRow.style.display = mode === 'table' ? '' : 'none';
  if (_peerRows.length) renderPeerResults();
}

function renderPeerResults() {
  _peerRenderMeta();
  if (_peerViewMode === 'scatter') renderPeerScatter();
  else if (_peerViewMode === 'group') renderPeerGroupCards();
  else if (_peerViewMode === 'workspace') renderPeerSectorWorkspace();
  else renderPeerTable();
}

// meta บนสุด (จำนวนหุ้น/กลุ่ม/ลิงก์ขยาย industry/หมายเหตุ on-demand) ใช้ร่วมกันทั้งมุมมองตาราง
// และ scatter — เดิมอยู่ใน renderPeerTable อย่างเดียว ทำให้ถ้าเปิดมุมมอง scatter ค้างไว้ตอน
// ค้นหุ้นใหม่ (renderPeerResults ข้าม renderPeerTable ไปเลย) แถบ meta จะว่างเปล่าตลอด
function _peerRenderMeta() {
  const meta = document.getElementById('peer-meta');
  if (!meta || !_peerMeta) return;
  const rows = _peerRows;
  // widen ทำได้เฉพาะตลาด TH เท่านั้น — US/HK/JP มีแค่ sector ชั้นเดียว (ดู comment ใน
  // /api/peer-compare) ก่อนหน้านี้ลิงก์นี้โผล่ในตลาดอื่นด้วยทั้งที่กดแล้วไม่มีผลอะไรเลย
  const canWiden = _peerMeta.market === 'TH' && !_peerMeta.widened && _peerMeta.level === 'sector' && rows.length < 8;
  // ondemand_note/dr_symbol/base_symbol/group มาจาก backend ที่ echo symbol/sector ที่ผู้ใช้พิมพ์
  // (จาก hash หรือช่อง input) กลับมาดิบ — escape ทุกจุดก่อนยัดเข้า innerHTML กัน XSS
  const ondemandNote = _peerMeta.ondemand_note
    ? `<div style="font-size:11px;color:#d29922;margin-bottom:6px">⚠ ${_escHtml(_peerMeta.ondemand_note)}</div>` : '';
  const drNote = _peerMeta.dr_symbol
    ? `<div style="font-size:11px;color:var(--text2);margin-bottom:6px">ℹ DR "${_escHtml(_peerMeta.dr_symbol)}" อ้างอิงหุ้น underlying "${_escHtml(_peerMeta.base_symbol)}" (ตลาด ${_escHtml(_peerMeta.market)}) — กลุ่มเพื่อนด้านล่างคือเพื่อนของ underlying</div>` : '';
  meta.innerHTML = ondemandNote + drNote +
    `พบ ${rows.length} หุ้น ใน ${_peerMeta.level === 'industry' ? 'Industry' : 'Sector'} "<b>${_escHtml(_peerMeta.group)}</b>"` +
    (_peerMeta.computed_at ? ` · คำนวณเมื่อ ${_escHtml(_peerMeta.computed_at)}` : '') +
    (canWiden ? ` &nbsp;<a href="#" onclick="_peerWiden();return false" style="color:var(--blue)">ขยับไปดูระดับ Industry (กลุ่มใหญ่ขึ้น)</a>` : '');
}

function loadPeerCompare(symArg, marketOverride) {
  const sym = (symArg || document.getElementById('peer-sym').value || '').toUpperCase().trim();
  if (!sym) return;
  document.getElementById('peer-sym').value = sym;
  document.getElementById('peer-sector-select').value = '';
  // marketOverride: ใช้ตอนเปิดจาก modal หุ้น DR (ดู openPeerFromModal) — fetch แรกต้องส่ง
  // market='DR' ให้ backend resolve DR sym เป็น underlying เอง ต่างจาก _peerMarket ที่เป็นแค่
  // แท็บ UI (US/HK) ปกติ ครั้งถัดไป (ขยายกลุ่ม/ค้นใหม่) กลับไปใช้ _peerMarket ตามเดิม
  _peerFetch(`/api/peer-compare?market=${marketOverride || _peerMarket}&symbol=${encodeURIComponent(sym)}`);
}

function loadPeerCompareBySector() {
  const sec = document.getElementById('peer-sector-select').value;
  if (!sec) return;
  document.getElementById('peer-sym').value = '';
  _peerFetch(`/api/peer-compare?market=${_peerMarket}&sector=${encodeURIComponent(sec)}&level=sector`);
}

function _peerWiden() {
  if (!_peerMeta) return;
  // สลับชั้นเดียวกับที่ backend รองรับ — เรียกด้วย group ปัจจุบันตรง ๆ ที่ level=industry เสมอ
  const url = _peerMeta.base_symbol
    ? `/api/peer-compare?market=${_peerMarket}&symbol=${encodeURIComponent(_peerMeta.base_symbol)}&level=industry`
    : `/api/peer-compare?market=${_peerMarket}&sector=${encodeURIComponent(_peerMeta.group)}&level=industry`;
  _peerFetch(url);
}

async function _peerFetch(url) {
  const box = document.getElementById('peer-results');
  const meta = document.getElementById('peer-meta');
  _peerDestroyScatterChart();
  box.innerHTML = '<div class="empty">กำลังโหลด...</div>';
  meta.textContent = '';
  // กัน response เก่าเขียนทับใหม่กว่า — สลับหุ้น/กลุ่มเร็วๆ ก่อน request เดิม (เช่น mirror
  // หุ้นนอกดัชนีที่ fetch sector สดจาก Yahoo ช้ากว่าปกติ) resolve เสร็จ
  const token = ++_peerFetchToken;
  try {
    // หุ้น mirror นอกดัชนีหลัก (US/HK) ต้อง fetch sector สดจาก Yahoo ก่อนตอบ (ดู
    // fetch_header ใน app.py) — ใช้ timeout เดียวกับ tearsheet กันหน้าค้าง "กำลังโหลด..." ไม่รู้จบ
    const r = await _fetchTimeout(url, 35000, 'โหลดข้อมูลกลุ่มนี้ช้าเกินไป (เกิน 35 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (token !== _peerFetchToken) return;   // มี request ใหม่กว่าแซงไปแล้ว ทิ้งผลลัพธ์นี้
    if (!d.rows || !d.rows.length) {
      // ล้าง state กลุ่มเดิมทิ้งก่อน return — ไม่งั้นกด preset/view-mode/widen ต่อจะ resurrect
      // กลุ่มเก่าจาก _peerRows/_peerMeta ที่ยังค้าง (guard `if (_peerRows.length)` ยังจริงอยู่)
      _peerRows = []; _peerMedian = null; _peerMeta = null; _peerSort = null;
      _peerGroupSyms = null; _peerGroupRows = null; _peerGroupSort = {};
      // note มาจาก backend ที่ echo symbol/sector ที่ผู้ใช้พิมพ์ (จาก hash) กลับมาดิบ — escape กัน XSS
      box.innerHTML = `<div class="empty">${_escHtml((d.meta && d.meta.note) || 'ไม่พบข้อมูลกลุ่มนี้')}</div>`;
      return;
    }
    _peerRows = d.rows;
    _peerMedian = d.median;
    _peerMeta = d.meta;
    // กลุ่มเปลี่ยน (ค้นหุ้นใหม่/เลือก sector ใหม่/ขยาย industry) — ล้างการเลือกหุ้นของมุมมอง
    // "การ์ดเทียบกลุ่ม" เดิมทิ้ง ให้ auto-pick top mkt_cap ใหม่ตามกลุ่มล่าสุดเสมอ (null สั่ง
    // ให้ renderPeerGroupCards/renderPeerSectorWorkspace auto-pick ใหม่ ต่างจาก [] ที่แปลว่า
    // ผู้ใช้ติ๊กออกจนหมดเองโดยตั้งใจ — ดู comment ที่จุดประกาศ _peerGroupSyms)
    _peerGroupSyms = null; _peerGroupRows = null; _peerGroupSort = {};
    renderPeerResults();
  } catch (e) {
    if (token !== _peerFetchToken) return;
    box.innerHTML = '<div class="empty" style="color:var(--red)">โหลดไม่สำเร็จ: ' + e.message + '</div>';
  }
}

// คอลัมน์ "ยิ่งน้อยยิ่งดี" ที่ค่า <= 0 คือผิดปกติ (ขาดทุน → P/E,PEG ติดลบ · ส่วนผู้ถือหุ้นติดลบ →
// PBV,D/E,IBD/E ติดลบ) ไม่ใช่ "ถูก/ปลอดภัยที่สุด" — ต้องถือเป็นแย่สุดของกลุ่ม ไม่ใช่ดีสุด
const _PEER_NEG_INVALID = new Set(['pe', 'pbv', 'peg', 'de_ratio', 'ibd_equity']);

// percentile ของ val ภายในกลุ่ม arr (0 = แย่สุด, 1 = ดีสุด — ปรับทิศตาม lowerBetter)
// negInvalid: คอลัมน์ที่ค่า <= 0 = พยาธิสภาพ (ดู _PEER_NEG_INVALID) → คืน 0 (แย่สุด) และตัดค่า
// <= 0 ออกจากฐานเปรียบเทียบ ไม่งั้นหุ้นขาดทุน (P/E ติดลบ) จะได้ percentile ~1.0 ดูเหมือนถูกสุด
function _peerPercentile(val, arr, lowerBetter, negInvalid) {
  if (val == null || arr.length < 2) return null;
  if (negInvalid && lowerBetter) {
    if (val <= 0) return 0;
    const pool = arr.filter(v => v > 0);
    if (pool.length < 2) return null;
    return 1 - pool.filter(v => v < val).length / (pool.length - 1);
  }
  const cntBetter = lowerBetter ? arr.filter(v => v < val).length : arr.filter(v => v > val).length;
  return 1 - cntBetter / (arr.length - 1);
}
function _peerCellColor(pct) {
  if (pct == null) return '';
  const t = Math.abs(pct - 0.5) * 2;
  return pct >= 0.5 ? `rgba(63,185,80,${0.1 + t * 0.55})` : `rgba(248,81,73,${0.1 + t * 0.55})`;
}
function _peerFmt(v) {
  if (v == null || (typeof v === 'number' && isNaN(v))) return '<span style="color:var(--text2)">–</span>';
  return Math.round(v * 100) / 100;
}

// ผู้ใช้คลิกหัวคอลัมน์เพื่อจัดเรียงเอง — ไม่กระทบแถว base (หุ้นที่กำลังดู) และแถว MEDIAN ซึ่งปักหมุดไว้เสมอ
let _peerSort = null;   // { key, dir: 1=มาก→น้อย, -1=น้อย→มาก } — key เป็น 'symbol' | 'mktcap' | c.k
function peerSortBy(key) {
  if (_peerSort && _peerSort.key === key) _peerSort.dir *= -1;
  else _peerSort = { key, dir: key === 'symbol' ? -1 : 1 };
  renderPeerTable();
}
function _peerSortArrow(key) {
  if (!_peerSort || _peerSort.key !== key) return '';
  return _peerSort.dir === 1 ? ' ▼' : ' ▲';
}

function renderPeerTable() {
  _peerDestroyScatterChart();
  _peerGroupDestroyCharts();
  const cols = PEER_COLS[_peerPreset];
  const rows = _peerRows;
  const baseSym = _peerMeta && _peerMeta.base_symbol;

  // ready-made arrays ต่อคอลัมน์สำหรับคำนวณ percentile (เฉพาะหุ้นที่มีข้อมูล ไม่รวม median)
  const arrays = {};
  cols.forEach(c => { arrays[c.k] = rows.map(r => r[c.k]).filter(v => typeof v === 'number'); });

  const widenNote = (_peerMeta && _peerMeta.widened)
    ? `<div style="font-size:11px;color:#d29922;margin-bottom:6px">⚠ sector เดิมมีสมาชิกน้อยกว่า 4 ตัว — ขยับไปเทียบระดับ industry "${_escHtml(_peerMeta.group)}" แทนอัตโนมัติ</div>` : '';

  const finNote = rows.some(r => r.is_financial_sector)
    ? '<div style="font-size:11px;color:var(--text2);margin-bottom:6px">ℹ กลุ่มนี้มีหุ้นสถาบันการเงิน — Z-Score/margin บางตัวตีความต่างจากกลุ่มอื่น เทียบตรง ๆ ระวัง</div>' : '';

  // พรีเซ็ต "ธรรมาภิบาล & ความยั่งยืน" — ต้องบอก coverage ตรง ๆ (SET ประเมินแค่ ~38% ของตลาด)
  // ไม่งั้นผู้ใช้เดาว่าทำไมช่องว่างเยอะ (ดู PLAN_set_api_expansion.txt งาน #3C)
  const esgHave = _peerMeta && _peerMeta.esg_have;
  const govNote = _peerPreset === 'governance' ? `<div style="font-size:11px;color:var(--text2);margin-bottom:6px">
    ธรรมาภิบาล &amp; ความยั่งยืน — ข้อมูลทางการจาก SET.or.th
    <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:280px">
      <strong>SETESG Rating</strong> — เรตติ้งความยั่งยืนทางการของตลาดหลักทรัพย์ฯ (AAA ดีสุด → BBB ต่ำสุดที่แจก) เรียง/ไล่สีตามอันดับ<hr>
      <strong>CG</strong> — คะแนนกำกับดูแลกิจการ (บริษัทจดทะเบียน) 1-5 จาก IOD<br>
      <span style="color:var(--text2)">~85% ของบริษัทที่ประเมินได้ 5 เต็ม — ใช้ "ตัดตัวที่ได้ต่ำ" ได้ แต่จัดอันดับไม่ได้ (แยกไม่ออก)</span><hr>
      <span style="color:var(--text2)">⚠ SET ประเมินแค่ ~38% ของหุ้นไทย — ช่องว่างในคอลัมน์ = บริษัทไม่ได้เข้าร่วมประเมิน ไม่ได้แปลว่าคะแนนแย่</span>
    </div></span>
    ${esgHave != null ? ` · ในกลุ่มนี้มีเรตติ้ง <b>${esgHave}/${rows.length}</b> ตัว` : ''}
    ${_peerMeta && _peerMeta.esg_as_of ? ` · ณ ${_peerMeta.esg_as_of}` : ''}
  </div>` : '';

  const head = `<th style="text-align:left;position:sticky;top:0;background:var(--bg2);z-index:2;cursor:pointer" onclick="peerSortBy('symbol')">หุ้น<span class="sort-ind${_peerSort&&_peerSort.key==='symbol'?' on':''}">${_peerSortArrow('symbol')}</span></th>` +
    `<th style="position:sticky;top:0;background:var(--bg2);z-index:2;cursor:pointer" onclick="peerSortBy('mktcap')">MktCap<span class="sort-ind${_peerSort&&_peerSort.key==='mktcap'?' on':''}">${_peerSortArrow('mktcap')}</span></th>` +
    cols.map(c => `<th title="${c.tip || ''}" style="position:sticky;top:0;background:var(--bg2);z-index:2;white-space:nowrap;cursor:pointer" onclick="peerSortBy('${c.k}')">${c.label}<span class="sort-ind${_peerSort&&_peerSort.key===c.k?' on':''}">${_peerSortArrow(c.k)}</span></th>`).join('');

  const rowHtml = (r, isMedian) => {
    const highlight = !isMedian && r.symbol === baseSym;
    const dim = !isMedian && r.quarters_available != null && r.quarters_available < 4;
    const rowStyle = isMedian
      ? 'font-weight:700;background:var(--card2);border-top:2px solid var(--border)'
      : (highlight ? 'background:rgba(88,166,255,0.12);font-weight:700' : (dim ? 'opacity:0.55' : ''));
    const symCell = isMedian
      ? '<td style="text-align:left">MEDIAN</td>'
      : `<td style="text-align:left"><strong class="sym-link" onclick="closePeerAndOpenChart('${r.symbol}')">${r.symbol}</strong>${_peerTvLink(r.symbol)}${dim ? ' <span title="ข้อมูลงบยังไม่ครบพอ (น้อยกว่า 4 ไตรมาส) — ตัวเลขอาจไม่นิ่ง" style="cursor:help">⚠</span>' : ''}</td>`;
    const mcCell = `<td>${isMedian ? '—' : fmtCap(r.mkt_cap)}</td>`;
    const tds = cols.map(c => {
      const v = r[c.k];
      let bg = '';
      if (!isMedian) {
        const pct = _peerPercentile(v, arrays[c.k], c.lowerBetter, _PEER_NEG_INVALID.has(c.k));
        bg = _peerCellColor(pct);
      }
      let display = _peerFmt(v);
      if (c.render) {
        // คอลัมน์ที่แสดงผลเป็นข้อความ (เรตติ้ง/ดาว) แต่ค่าจริงเป็นตัวเลขไว้เรียง+ลงสี — MEDIAN
        // ไม่มีความหมายในเชิงข้อความ โชว์ "–"
        display = isMedian ? '<span style="color:var(--text2)">–</span>' : c.render(r);
      } else if (c.k === 'f_score' && !isMedian && v != null) {
        display = `${display}${_fzExternalLinkIcon(r.symbol)}`;
      } else if (c.k === 'z_score' && !isMedian && v != null) {
        const zoneColor = { safe: 'var(--green,#2ea043)', grey: '#d29922', distress: 'var(--red,#da3633)' }[r.z_zone] || '';
        const zoneLabel = { safe: 'ปลอดภัย', grey: 'เทา', distress: 'เสี่ยง' }[r.z_zone] || '';
        display = `<span title="${_zScoreTooltip(r.z_variant, r.z_zone, zoneLabel)}" style="color:${zoneColor};font-weight:600;cursor:help">${display}</span>`;
      } else if (c.k === 'z_score' && !isMedian && v == null && r.z_excluded_reason) {
        display = `<span title="${r.z_excluded_reason}" style="color:var(--text2);cursor:help">–</span>`;
      }
      return `<td style="background:${bg}">${display}</td>`;
    }).join('');
    return `<tr style="${rowStyle}">${symCell}${mcCell}${tds}</tr>`;
  };

  let sortedRows = rows.slice();
  if (_peerSort) {
    const key = _peerSort.key, dir = _peerSort.dir;
    const isStr = key === 'symbol';
    sortedRows.sort((a, b) => {
      const va = key === 'mktcap' ? a.mkt_cap : a[key];
      const vb = key === 'mktcap' ? b.mkt_cap : b[key];
      if (isStr) {
        const sa = (va || '').toLowerCase(), sb = (vb || '').toLowerCase();
        return dir === 1 ? sb.localeCompare(sa) : sa.localeCompare(sb);
      }
      const na = typeof va === 'number' ? va : -Infinity;
      const nb = typeof vb === 'number' ? vb : -Infinity;
      return dir === 1 ? nb - na : na - nb;
    });
  }
  let bodyRows = sortedRows.map(r => rowHtml(r, false));
  // ปักหมุดหุ้นตั้งต้นไว้บนสุด — เฉพาะตอนที่มันอยู่ในกลุ่มจริง (base อาจหลุดกลุ่มได้หลัง widen
  // industry) ไม่งั้น MEDIAN จะถูกแทรกที่ index 1 ทั้งที่ไม่มีแถว base ปักหมุดอยู่ข้างบน
  let basePinned = false;
  if (baseSym) {
    const idx = sortedRows.findIndex(r => r.symbol === baseSym);
    if (idx > 0) { const [x] = bodyRows.splice(idx, 1); bodyRows.unshift(x); basePinned = true; }
    else if (idx === 0) basePinned = true;
  }
  if (_peerMedian) bodyRows.splice(basePinned ? 1 : 0, 0, rowHtml(_peerMedian, true));

  document.getElementById('peer-results').innerHTML = widenNote + finNote + govNote +
    `<div style="overflow:auto;max-height:70vh;border:1px solid var(--border);border-radius:8px">
       <table class="data-table" style="font-size:12px;min-width:900px">
       <thead><tr>${head}</tr></thead><tbody>${bodyRows.join('')}</tbody></table></div>`;
}

// Scatter PE (แกน X) × ROE (แกน Y) — จตุภาคอิงเส้นค่ากลาง (median) ของกลุ่มเพื่อน
// บนซ้าย (PE ต่ำ, ROE สูง) = ถูกและมีคุณภาพสูง → เขียว
// ล่างขวา (PE สูง, ROE ต่ำ) = แพงและคุณภาพต่ำ → แดง · อีกสองจตุภาคเป็นกลาง (เทา)
let _peerScatterChartInst = null;

function _peerDestroyScatterChart() {
  if (_peerScatterChartInst) { _peerScatterChartInst.destroy(); _peerScatterChartInst = null; }
}

function renderPeerScatter() {
  _peerDestroyScatterChart();
  _peerGroupDestroyCharts();
  const rows = _peerRows;
  const baseSym = _peerMeta && _peerMeta.base_symbol;

  const pts = rows
    .filter(r => typeof r.pe === 'number' && typeof r.roe === 'number')
    .map(r => ({ x: r.pe, y: r.roe, symbol: r.symbol, isBase: r.symbol === baseSym }));

  if (pts.length < 2) {
    document.getElementById('peer-results').innerHTML =
      '<div class="empty">หุ้นในกลุ่มนี้มีข้อมูล PE และ ROE ไม่พอสำหรับวาด Scatter (ต้องมีอย่างน้อย 2 ตัว)</div>';
    return;
  }

  const peVals = pts.map(p => p.x), roeVals = pts.map(p => p.y);
  const medianOf = arr => {
    const s = [...arr].sort((a, b) => a - b);
    const n = s.length;
    return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
  };
  const medPe = (_peerMedian && typeof _peerMedian.pe === 'number') ? _peerMedian.pe : medianOf(peVals);
  const medRoe = (_peerMedian && typeof _peerMedian.roe === 'number') ? _peerMedian.roe : medianOf(roeVals);

  const zoneColor = p => {
    if (p.x <= medPe && p.y >= medRoe) return '#3fb950';   // ถูก+คุณภาพสูง
    if (p.x >= medPe && p.y <= medRoe) return '#f85149';   // แพง+คุณภาพต่ำ
    return '#8b949e';                                       // จตุภาคกลาง
  };

  document.getElementById('peer-results').innerHTML =
    `<div style="font-size:11px;color:var(--text2);margin-bottom:8px">
       เส้นประ = ค่ากลาง (median) PE และ ROE ของกลุ่มเพื่อน ·
       <span style="color:#3fb950">●</span> ถูกกว่าเพื่อน+ROE สูงกว่า &nbsp;
       <span style="color:#f85149">●</span> แพงกว่าเพื่อน+ROE ต่ำกว่า &nbsp;
       <span style="color:#8b949e">●</span> จตุภาคกลาง
     </div>
     <div style="position:relative;height:420px;border:1px solid var(--border);border-radius:8px;padding:8px">
       <canvas id="peer-scatter-chart"></canvas>
     </div>`;

  const canvas = document.getElementById('peer-scatter-chart');
  const medianLinesPlugin = {
    id: 'peerMedianLines',
    afterDraw(chart) {
      const { ctx, chartArea, scales } = chart;
      if (!chartArea) return;
      const xPix = scales.x.getPixelForValue(medPe);
      const yPix = scales.y.getPixelForValue(medRoe);
      ctx.save();
      ctx.strokeStyle = 'rgba(139,148,158,0.5)';
      ctx.setLineDash([4, 4]);
      ctx.lineWidth = 1;
      if (xPix >= chartArea.left && xPix <= chartArea.right) {
        ctx.beginPath(); ctx.moveTo(xPix, chartArea.top); ctx.lineTo(xPix, chartArea.bottom); ctx.stroke();
      }
      if (yPix >= chartArea.top && yPix <= chartArea.bottom) {
        ctx.beginPath(); ctx.moveTo(chartArea.left, yPix); ctx.lineTo(chartArea.right, yPix); ctx.stroke();
      }
      ctx.restore();
    }
  };

  _peerScatterChartInst = new Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [{
        label: 'หุ้นในกลุ่ม',
        data: pts,
        backgroundColor: pts.map(p => zoneColor(p)),
        borderColor: pts.map(p => p.isBase ? '#58a6ff' : zoneColor(p)),
        borderWidth: pts.map(p => p.isBase ? 3 : 1),
        pointRadius: pts.map(p => p.isBase ? 9 : 6),
        pointHoverRadius: pts.map(p => p.isBase ? 11 : 8),
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      onClick: (evt, elements) => {
        // คลิกจุดใน scatter เปิดกราฟหุ้นตัวนั้นได้เหมือนคลิกชื่อหุ้นในมุมมองตาราง
        if (!elements.length) return;
        const p = pts[elements[0].index];
        if (p) closePeerAndOpenChart(p.symbol);
      },
      onHover: (evt, elements) => {
        evt.native.target.style.cursor = elements.length ? 'pointer' : 'default';
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: (ctx) => {
              const p = ctx.raw;
              return `${p.symbol}: PE ${p.x.toFixed(2)} · ROE ${p.y.toFixed(2)}%`;
            }
          }
        }
      },
      scales: {
        x: { title: { display: true, text: 'PE (เท่า)' }, grid: { color: 'rgba(139,148,158,0.15)' } },
        y: { title: { display: true, text: 'ROE (%)' }, grid: { color: 'rgba(139,148,158,0.15)' } },
      }
    },
    plugins: [medianLinesPlugin]
  });
}

// ลิงก์ TradingView ต่อแถว peer ตามตลาดของกลุ่มที่กำลังดู (เดิมใช้ tvLink แบบ SET เสมอ → US/HK/JP ผิด)
function _peerTvLink(sym) {
  return _peerMarket === 'US' ? _usTvLink(sym)
    : _peerMarket === 'HK' ? _hkTvLink(sym)
    : _peerMarket === 'JP' ? _jpTvLink(sym)
    : tvLink(sym);
}

function closePeerAndOpenChart(sym) {
  if (_peerMarket === 'US' || _peerMarket === 'HK' || _peerMarket === 'JP') {
    _openMirrorStock(sym, _peerMarket.toLowerCase());   // เคารพโหมด 🗗 + lazy-load + fallback หน้างบ
    return;
  }
  if (navOpenMode() === 'new') { openInternalHash('#ts/th/' + encodeURIComponent(sym)); return; }
  openChartModal(sym);
}

function openPeerFromModal() {
  if (!_cmStock) return;
  // หุ้น DR (_isDR) fetch แรกต้องส่ง market='DR' ตรงๆ ให้ backend resolve เป็น underlying
  // US/HK เอง (DR sym อาจไม่ตรงกับ yf ticker จริง เช่น DR "APPL" -> underlying "APP" — เดา
  // ผิดตัวได้ถ้าส่ง market=US ตรงๆ) ส่วนแท็บ UI/datalist ยังตั้งเป็น US/HK ตามปกติ (field
  // 'region' จาก dr_universe บอกตลาด underlying คร่าวๆ) เพราะหลังจากนี้ resolved market/symbol
  // จาก response (meta.market/base_symbol) จะเป็น US/HK ตรงแล้ว ปุ่ม "ขยายกลุ่ม" ครั้งถัดไปเลย
  // ใช้ _peerMarket ปกติได้
  const isDr = !!_cmStock._isDR;
  // DR: region จาก dr_universe บอกตลาด underlying — JP ต้องแยกออกมา ไม่งั้นตกไปแท็บ US
  // (_peerMarket='US' ทำให้ _peerTvLink/closePeerAndOpenChart สร้างลิงก์/เปิดกราฟผิดตลาดสำหรับ
  //  ticker แบบ 7203.T) · backend รองรับ region JP อยู่แล้ว
  const tabMkt = isDr
    ? (_cmStock.region === 'HK' ? 'HK' : _cmStock.region === 'JP' ? 'JP' : 'US')
    : (_cmStock._isUSIdx ? 'US' : _cmStock._isHKIdx ? 'HK' : _cmStock._isJPIdx ? 'JP' : 'TH');
  // โหมด "🗗 แท็บใหม่" — ส่ง deep-link #peer/ ไปแท็บใหม่ คากราฟที่ดูอยู่ไว้ในแท็บนี้ (DR ไปทางเดิม)
  if (!isDr && navOpenMode() === 'new') {
    openInternalHash(`#peer/${tabMkt.toLowerCase()}/${encodeURIComponent(_cmStock.symbol)}`, true);
    return;
  }
  closeChartModal();
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes("'peer'"));
  showPage('peer', btn);
  setPeerMarket(tabMkt, document.getElementById('peer-tab-' + tabMkt.toLowerCase()));
  loadPeerCompare(_cmStock.symbol, isDr ? 'DR' : null);
}

// ============================================================
// PEER GROUP CARDS — มุมมอง "🗂 หุ้นเทียบกับกลุ่ม" ของหน้า Peer Compare (เฉพาะหุ้นไทย)
// ต่างจากตาราง percentile/scatter ด้านบนที่ใช้ตัวเลขรายปีจาก factor_snapshot — มุมมองนี้ยิง
// /api/peer-group-detail คำนวณ TTM (ผลรวม 4 ไตรมาสล่าสุด) สดจากงบไตรมาสผสาน ค่าเริ่มต้น = หุ้น
// ทุกตัวในกลุ่ม sector/industry เดียวกัน (ตัดออกทีละตัวได้ผ่าน checkbox) ให้เห็นการ์ด Margins/
// Cash Cycle/รายการการเงินรายไตรมาส/อันดับกำไรโต แบบเดียวกับตารางเทียบหุ้น 2 ตัว แต่ขยายเป็นกลุ่ม
// ============================================================
// null = ยังไม่เคยตั้งค่า (จะ auto-pick ทั้งกลุ่มตอน render) ต่างจาก [] ที่แปลว่าผู้ใช้ติ๊กออก
// จนหมดกลุ่มเองโดยตั้งใจ (เดิมใช้ [] ทั้งสองความหมายปนกัน ทำให้ติ๊กออกตัวสุดท้ายแล้ว auto-pick
// ดันกลับมาเลือกทั้งกลุ่มใหม่ทันที ไม่มีทางดูหุ้นตัวเดียวโดดๆ จากมุมมองนี้ได้เลย)
let _peerGroupSyms = null;    // symbol ที่เลือกอยู่ตอนนี้ (ค่าเริ่มต้น = ทั้งกลุ่ม, ตัดออกได้เอง)
let _peerGroupRows = null;    // แถวล่าสุดจาก /api/peer-group-detail
let _peerGroupCharts = [];    // Chart.js instances — ทำลายก่อน render ใหม่ทุกครั้งกัน canvas ค้าง

// รายการ "ยิ่งน้อยยิ่งดี" — ที่เหลือ (revenue/margin/CFO/DPO ฯลฯ) ถือว่ายิ่งมากยิ่งดี ตาม
// convention เดียวกับ FIN_INVERT_KEYS ที่ใช้ในตารางเทียบหุ้น 2 ตัว
const _PEER_GROUP_LOWER_BETTER = new Set(['de_ratio', 'pe', 'pbv', 'peg', 'cash_cycle', 'dio', 'dso', 'ibd', 'q_cogs', 'q_sga', 'ibd_equity', 'capex_rev']);
// mkt_cap ใหญ่กว่า/เล็กกว่าไม่ใช่ "ดีกว่า/แย่กว่า" ในเชิงลงทุน — โชว์เฉยๆ ไม่ไล่สีเทียบ base
const _PEER_GROUP_NEUTRAL = new Set(['mkt_cap']);

function _peerGroupCellColor(key, val, baseVal) {
  if (_PEER_GROUP_NEUTRAL.has(key)) return '';
  if (val == null || baseVal == null || val === baseVal) return '';
  const lowerBetter = _PEER_GROUP_LOWER_BETTER.has(key);
  // P/E,PBV,PEG,D/E,IBD/E ติดลบ = ขาดทุน/ส่วนผู้ถือหุ้นติดลบ ไม่ใช่ "ถูก/ปลอดภัยที่สุด" — ถือเป็นแย่กว่า
  if (lowerBetter && _PEER_NEG_INVALID.has(key)) {
    const valBad = val <= 0, baseBad = baseVal <= 0;
    if (valBad && baseBad) return '';
    if (valBad) return 'var(--red,#f85149)';
    if (baseBad) return 'var(--green,#3fb950)';
  }
  const better = lowerBetter ? val < baseVal : val > baseVal;
  return better ? 'var(--green,#3fb950)' : 'var(--red,#f85149)';
}

// จัดกลุ่มคอลัมน์แบบหัวข้อ 2 ชั้น (ขนาด/GROWTH/PROFITABILITY/CASH FLOW/FINANCIAL HEALTH/
// EFFICIENCY/VALUATION/QUALITY) ตามรูปแบบที่ผู้ใช้ขอ — รวมรายการที่เคยแยกเป็น 3 ตาราง
