function _peerGroupDestroyCharts() {
  _peerGroupCharts.forEach(c => c.destroy());
  _peerGroupCharts = [];
}

function _peerGroupSignedPct(v) {
  return v == null ? '–' : (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
}

// ค่าเริ่มต้น = หุ้นทุกตัวในกลุ่มที่โหลดไว้แล้ว (_peerRows) — ผู้ใช้ตัดออกทีละตัวได้เองผ่าน
// checkbox ทีหลัง (เดิมจำกัด top-5 ตาม mkt_cap เปลี่ยนเป็นเทียบได้ทั้ง sector ตามที่ผู้ใช้ขอ)
function _peerGroupAutoPick() {
  return _peerRows.slice().sort((a, b) => (b.mkt_cap || 0) - (a.mkt_cap || 0)).map(r => r.symbol);
}

function renderPeerGroupCards() {
  _peerGroupDestroyCharts();
  _peerDestroyScatterChart();
  const box = document.getElementById('peer-results');
  if (_peerMarket !== 'TH') {
    box.innerHTML = '<div class="empty">มุมมอง "หุ้นเทียบกับกลุ่ม" รองรับเฉพาะหุ้นไทยตอนนี้ — สลับไปแท็บ 🇹🇭 ไทย ก่อน</div>';
    return;
  }
  if (!_peerRows.length) return;
  if (_peerGroupSyms === null) _peerGroupSyms = _peerGroupAutoPick();
  box.innerHTML = _peerGroupChipsHtml() + '<div id="peer-group-body"><div class="empty">กำลังโหลด...</div></div>';
  _peerGroupFetch();
}

function _peerGroupChipsHtml() {
  const baseSym = _peerMeta && _peerMeta.base_symbol;
  const all = _peerRows.slice().sort((a, b) => (b.mkt_cap || 0) - (a.mkt_cap || 0));
  const chips = all.map(r => {
    const checked = _peerGroupSyms.includes(r.symbol);
    const isBase = r.symbol === baseSym;
    return `<label style="display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:12px;font-size:12px;cursor:${isBase ? 'default' : 'pointer'};background:${checked ? 'rgba(88,166,255,0.15)' : 'transparent'};border:1px solid var(--border)">
      <input type="checkbox" ${checked ? 'checked' : ''} ${isBase ? 'disabled' : ''} onchange="_peerGroupToggle('${r.symbol}',this.checked)" style="margin:0">
      ${isBase ? '⭐ ' : ''}${r.symbol}
    </label>`;
  }).join('');
  return `<div class="card" style="padding:10px 12px;margin-bottom:10px">
    <div style="font-size:11px;color:var(--text2);margin-bottom:6px">เทียบกับหุ้นทุกตัวในกลุ่มนี้ (${all.length} ตัว) — ติ๊กออกได้ถ้าอยากตัดบางตัวทิ้ง (หุ้นตั้งต้น ⭐ ตัดไม่ได้)</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px">${chips}</div>
  </div>`;
}

function _peerGroupToggle(sym, on) {
  if (on) {
    if (!_peerGroupSyms.includes(sym)) _peerGroupSyms.push(sym);
  } else {
    _peerGroupSyms = _peerGroupSyms.filter(s => s !== sym);
  }
  if (_peerViewMode === 'workspace') renderPeerSectorWorkspace();
  else renderPeerGroupCards();
}

// ใช้ร่วมกันทั้งมุมมอง "🗂 หุ้นเทียบกับกลุ่ม" และ "🏭 Sector Workspace" — สอง view นี้ยิง
// /api/peer-group-detail ชุดเดียวกัน (แค่ render body คนละแบบ) แยกตาม _peerViewMode ตอนจบ fetch
let _peerGroupFetchToken = 0;   // กัน response เก่าที่มาถึงทีหลัง (ติ๊กหุ้นออกเร็วๆ ติดกัน) เขียนทับผลของ request ใหม่กว่า
async function _peerGroupFetch() {
  const bodyId = _peerViewMode === 'workspace' ? 'peer-workspace-body' : 'peer-group-body';
  const baseSym = (_peerMeta && _peerMeta.base_symbol) || '';
  // หุ้นที่เลือกตอนนี้เป็น subset ของชุดที่ fetch มาแล้วครบ (เพิ่งติ๊กออกบางตัว / สลับ view mode
  // ไปมา) — กรอง cache เดิมฝั่ง client ไม่ต้องยิง /api/peer-group-detail ใหม่ (แต่ละ request
  // คำนวณ TTM สดต่อหุ้น ~60 วิ ไม่มี server cache) · การเพิ่มหุ้นใหม่ที่ยังไม่เคย fetch จะไม่ผ่าน
  // เงื่อนไขนี้ → ตกไปยิงจริงตามเดิม
  if (_peerGroupRows && _peerGroupSyms.length &&
      _peerGroupSyms.every(s => _peerGroupRows.some(r => r.symbol === s))) {
    ++_peerGroupFetchToken;   // ทิ้ง response ของ fetch เดิมที่อาจยังค้างอยู่ (จะได้ไม่เขียน rows เต็มทับ)
    _peerGroupRows = _peerGroupRows.filter(r => _peerGroupSyms.includes(r.symbol));
    if (_peerViewMode === 'workspace') _peerWorkspaceRenderBody();
    else _peerGroupRenderBody();
    return;
  }
  const token = ++_peerGroupFetchToken;
  try {
    const url = `/api/peer-group-detail?market=TH&symbols=${encodeURIComponent(_peerGroupSyms.join(','))}&base=${encodeURIComponent(baseSym)}`;
    // sector ใหญ่สุด ~64 ตัว (Services -mai) — คำนวณ TTM สดต่อหุ้นเยอะขึ้นตามจำนวนที่เลือก ให้
    // เวลามากกว่า timeout ปกติของหน้านี้ (35 วิ)
    const r = await _fetchTimeout(url, 60000, 'โหลดข้อมูลกลุ่มนี้ช้าเกินไป (เกิน 60 วิ) — ลองใหม่อีกครั้ง หรือติ๊กหุ้นออกให้เหลือน้อยลง');
    const d = await r.json();
    if (token !== _peerGroupFetchToken) return;   // มี request ใหม่กว่าแซงไปแล้ว ทิ้งผลลัพธ์นี้
    _peerGroupRows = d.rows || [];
    if (_peerViewMode === 'workspace') _peerWorkspaceRenderBody();
    else _peerGroupRenderBody();
  } catch (e) {
    if (token !== _peerGroupFetchToken) return;
    // หา node สดตอนนี้แทนการใช้ reference ที่จับไว้ก่อน await — ถ้าผู้ใช้สลับ view mode ระหว่างรอ
    // (โดยไม่มี request ใหม่มาบัมพ์ token) node เดิมอาจหลุดจาก DOM ไปแล้ว เขียน error เข้า node
    // ที่ไม่มีใครเห็นแบบเงียบๆ — เช็คสดกันพลาดจุดนี้ (ถ้า mode สลับไปจริง node ใหม่จะไม่มี id นี้
    // อยู่แล้ว ก็แค่ไม่เขียน ไม่ error)
    const body = document.getElementById(bodyId);
    if (body) body.innerHTML = '<div class="empty" style="color:var(--red)">โหลดไม่สำเร็จ: ' + e.message + '</div>';
  }
}

function _peerGroupHeaderHtml(rows, baseSym) {
  const level = _peerMeta.level === 'industry' ? 'Industry' : 'Sector';
  const group = _escHtml(_peerMeta.group || '');
  const tip = `<span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:270px">
    ตัวเลขคำนวณสด (TTM) จากงบการเงินรายไตรมาสของแต่ละบริษัท ผสาน ณ ตอนเปิดหน้านี้ — ไม่ใช่ค่าที่เก็บไว้ล่วงหน้า จึงรองรับเฉพาะหุ้นไทย<br><br>
    คลิกหัวคอลัมน์เพื่อเรียงลำดับ (หุ้นตั้งต้น ⭐ ปักหมุดบนสุดเสมอ)<br>
    ติ๊กออกที่ชิปด้านบนได้ถ้าอยากตัดบางตัวออกจากการเทียบ
  </div></span>`;
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;font-size:14px;display:flex;align-items:center;gap:2px">${level}: ${group}${tip}</div>
    <div style="font-size:12px;color:var(--text2);margin-top:4px">เทียบ ${rows.length} ตัวในกลุ่ม | ⭐ = หุ้นที่ดูอยู่ | <span style="color:var(--green,#3fb950)">เขียว</span>=ดีกว่า <span style="color:var(--red,#f85149)">แดง</span>=แย่กว่า เทียบกับ ${_escHtml(baseSym || '-')}</div>
  </div>`;
}

// sort state ต่อตาราง (ตาราง 1/2/3 คนละ metric set แยกกัน) — { tableIndex: { key, dir } }
// dir 1 = มาก->น้อย, -1 = น้อย->มาก · re-render จาก _peerGroupRows ที่ cache ไว้แล้ว ไม่ fetch ซ้ำ
let _peerGroupSort = {};

function _peerGroupSortBy(tableIndex, key) {
  const cur = _peerGroupSort[tableIndex];
  if (cur && cur.key === key) cur.dir *= -1;
  else _peerGroupSort[tableIndex] = { key, dir: key === 'symbol' ? -1 : 1 };
  _peerGroupRenderBody();
}

// หุ้นเป็นแถว (รายการ = คอลัมน์) — อ่านง่ายเมื่อกลุ่มมีหุ้นเยอะ (ทั้ง sector ได้ถึง ~64 ตัว)
// ต่างจากตารางเทียบหุ้น 2 ตัวที่หุ้นเป็นคอลัมน์ (มีแค่ 2 ตัวไม่ต้อง scroll แนวตั้งเยอะ) หัวคอลัมน์
// กดเรียงลำดับได้ (ปักหมุดหุ้นตั้งต้น ⭐ ไว้บนสุดเสมอไม่ว่าจะเรียงยังไง เหมือนตาราง percentile หลัก)
// รายการ 2 ชั้นสี ประจำแต่ละหัวข้อกลุ่ม (ขนาด/GROWTH/PROFITABILITY/...) — วนซ้ำถ้ากลุ่มเยอะกว่านี้
const _PEER_GROUP_COLORS = ['#8b949e', '#3fb950', '#58a6ff', '#56d4dd', '#e8b84b', '#d2a8ff', '#f778ba'];

function _peerGroupTableHtml(tableIndex, title, icon, metricsOrGroups, rows, baseSym) {
  const baseRow = rows.find(r => r.symbol === baseSym);
  const sortState = _peerGroupSort[tableIndex];
  // ตารางแบบมีหัวข้อกลุ่ม (colspan 2 ชั้น) ถ้า item แรกมี .metrics — ไม่งั้นเป็น array metric แบนแบบเดิม
  const isGrouped = Array.isArray(metricsOrGroups) && metricsOrGroups.length > 0 && Array.isArray(metricsOrGroups[0].metrics);
  const groups = isGrouped ? metricsOrGroups : null;
  const metrics = isGrouped ? metricsOrGroups.flatMap(g => g.metrics) : metricsOrGroups;

  let sortedRows = rows.slice();
  if (sortState) {
    const { key, dir } = sortState;
    if (key === 'symbol') {
      sortedRows.sort((a, b) => dir === 1 ? b.symbol.localeCompare(a.symbol) : a.symbol.localeCompare(b.symbol));
    } else {
      sortedRows.sort((a, b) => {
        const va = a[key], vb = b[key];
        const na = typeof va === 'number' ? va : -Infinity;
        const nb = typeof vb === 'number' ? vb : -Infinity;
        return dir === 1 ? nb - na : na - nb;
      });
    }
  }
  if (baseSym) {
    const idx = sortedRows.findIndex(r => r.symbol === baseSym);
    if (idx > 0) { const [x] = sortedRows.splice(idx, 1); sortedRows.unshift(x); }
  }

  const arrow = key => {
    if (!sortState || sortState.key !== key) return '';
    return sortState.dir === 1 ? ' ▼' : ' ▲';
  };

  let head;
  if (groups) {
    // แถวบน = หัวข้อกลุ่ม (colspan ตามจำนวน metric ในกลุ่ม, สีไล่ตามกลุ่ม) แถวล่าง = ชื่อคอลัมน์
    // จริงที่กดเรียงได้ — ความสูงแถวบน fix ไว้ (padding+font ด้านล่าง) ให้คำนวณ top ของแถวล่างตรงกัน
    const symTh = `<th rowspan="2" style="text-align:left;position:sticky;left:0;top:0;z-index:4;background:var(--bg2);vertical-align:bottom" onclick="_peerGroupSortBy(${tableIndex},'symbol')">หุ้น${arrow('symbol')}</th>`;
    const groupRow = groups.map((g, gi) => {
      const color = _PEER_GROUP_COLORS[gi % _PEER_GROUP_COLORS.length];
      return `<th colspan="${g.metrics.length}" style="text-align:center;position:sticky;top:0;z-index:2;background:var(--bg2);padding:4px 9px;font-size:10.5px;line-height:14px;white-space:nowrap;border-bottom:2px solid ${color};color:${color};font-weight:700;letter-spacing:.03em">${g.title}</th>`;
    }).join('');
    const labelRow = groups.map(g => g.metrics.map(m =>
      `<th style="text-align:right;position:sticky;top:23px;background:var(--bg2);z-index:2;white-space:nowrap;cursor:pointer" title="${m.tip || m.label}" onclick="_peerGroupSortBy(${tableIndex},'${m.k}')">${m.label}${arrow(m.k)}</th>`
    ).join('')).join('');
    head = `<tr>${symTh}${groupRow}</tr><tr>${labelRow}</tr>`;
  } else {
    const thStyle = 'position:sticky;top:0;background:var(--bg2);z-index:2;white-space:nowrap;cursor:pointer';
    head = `<tr><th style="text-align:left;${thStyle};position:sticky;left:0;z-index:3" onclick="_peerGroupSortBy(${tableIndex},'symbol')">หุ้น${arrow('symbol')}</th>` +
      metrics.map(m => `<th style="text-align:right;${thStyle}" title="${m.tip || m.label}" onclick="_peerGroupSortBy(${tableIndex},'${m.k}')">${m.label}${arrow(m.k)}</th>`).join('') + `</tr>`;
  }

  const body = sortedRows.map(r => {
    const isBase = r.symbol === baseSym;
    const rowBg = isBase ? 'background:rgba(88,166,255,0.12);font-weight:700' : '';
    const symCell = `<td style="text-align:left;white-space:nowrap;position:sticky;left:0;background:var(--card2,#161b22);${isBase ? 'color:var(--accent,#58a6ff);font-weight:700' : ''}">${isBase ? '⭐ ' : ''}${r.symbol}</td>`;
    const cells = metrics.map(m => {
      const v = r[m.k];
      const baseVal = baseRow ? baseRow[m.k] : null;
      const color = isBase ? '' : _peerGroupCellColor(m.k, v, baseVal);
      return `<td style="text-align:right;${color ? `color:${color};font-weight:600` : ''}">${m.fmt(v, r)}</td>`;
    }).join('');
    return `<tr style="${rowBg}">${symCell}${cells}</tr>`;
  }).join('');

  const minWidth = 140 + metrics.length * 82;
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px;font-size:13px">${icon} ${title}</div>
    <div style="overflow:auto;max-height:60vh">
      <table class="data-table" style="font-size:12px;min-width:${minWidth}px">
        <thead>${head}</thead><tbody>${body}</tbody>
      </table>
    </div>
  </div>`;
}

function _peerGroupChartsHtml() {
  return `<div style="display:flex;flex-direction:column;gap:12px;margin-bottom:12px">
    <div class="card" style="padding:12px 14px">
      <div style="font-weight:700;margin-bottom:8px;font-size:13px">📊 Margins เทียบ Peer</div>
      <div style="overflow-x:auto"><div id="peer-group-margins-wrap" style="position:relative;height:320px;min-width:100%"><canvas id="peer-group-margins-chart"></canvas></div></div>
      <div id="peer-group-margins-clip-note" style="font-size:10px;color:#8b949e;margin-top:4px;display:none">* แกน Y ตัดขอบอัตโนมัติเพื่อไม่ให้ค่าผิดปกติบดบังตัวอื่น — เลื่อนเมาส์ชี้แท่งเพื่อดูค่าจริง</div>
    </div>
    <div class="card" style="padding:12px 14px">
      <div style="font-weight:700;margin-bottom:8px;font-size:13px">🎯 P/E เทียบ Peer</div>
      <div style="overflow-x:auto"><div id="peer-group-pe-wrap" style="position:relative;height:320px;min-width:100%"><canvas id="peer-group-pe-chart"></canvas></div></div>
    </div>
  </div>`;
}

// บังคับความกว้าง canvas ตามจำนวนหุ้น กันชื่อหุ้นล้น/ถูกข้ามเวลามีหุ้นในกลุ่มเยอะ
function _peerGroupChartMinWidth(count) {
  return Math.max(count * 46, 0) + 'px';
}

// หา min/max แกน Y แบบตัด outlier (Tukey IQR fence) กันค่าผิดปกติตัวเดียวดึงสเกลจนตัวอื่นแบนหมด
function _peerGroupAxisBounds(values) {
  const vals = values.filter(v => typeof v === 'number' && isFinite(v)).sort((a, b) => a - b);
  if (!vals.length) return { min: undefined, max: undefined, clipped: false };
  const q = p => vals[Math.min(vals.length - 1, Math.floor(p * (vals.length - 1)))];
  const q1 = q(0.25), q3 = q(0.75);
  const iqr = q3 - q1 || Math.abs(q3) || 10;
  const dataMin = vals[0], dataMax = vals[vals.length - 1];
  let lo = Math.max(q1 - 1.5 * iqr, dataMin);
  let hi = Math.min(q3 + 1.5 * iqr, dataMax);
  const pad = Math.max((hi - lo) * 0.15, 5);
  lo = Math.min(lo - pad, 0);
  hi = Math.max(hi + pad, 0);
  const clipped = dataMin < lo || dataMax > hi;
  return { min: Math.round(lo), max: Math.round(hi), clipped };
}

function _peerGroupRenderCharts(rows, baseSym) {
  const labels = rows.map(r => r.symbol);
  const gridColor = 'rgba(139,148,158,0.15)';
  const chartWidth = _peerGroupChartMinWidth(labels.length);
  const xAxisTicks = { autoSkip: false, maxRotation: 60, minRotation: labels.length > 10 ? 60 : 0, font: { size: 10 } };

  const marginsWrap = document.getElementById('peer-group-margins-wrap');
  if (marginsWrap) marginsWrap.style.width = chartWidth;
  const marginsCanvas = document.getElementById('peer-group-margins-chart');
  if (marginsCanvas) {
    const marginVals = [];
    rows.forEach(r => { [r.gpm, r.npm, r.roe].forEach(v => marginVals.push(v)); });
    const bounds = _peerGroupAxisBounds(marginVals);
    const clipNote = document.getElementById('peer-group-margins-clip-note');
    if (clipNote) clipNote.style.display = bounds.clipped ? '' : 'none';
    _peerGroupCharts.push(new Chart(marginsCanvas, {
      type: 'bar',
      data: {
        labels,
        datasets: [
          { label: 'GPM %', data: rows.map(r => r.gpm), backgroundColor: '#58a6ff' },
          { label: 'NPM %', data: rows.map(r => r.npm), backgroundColor: '#3fb950' },
          { label: 'ROE %', data: rows.map(r => r.roe), backgroundColor: '#d2a8ff' },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { position: 'top', labels: { boxWidth: 10, font: { size: 10 } } } },
        scales: {
          y: { min: bounds.min, max: bounds.max, ticks: { callback: v => v + '%' }, grid: { color: gridColor } },
          x: { grid: { display: false }, ticks: xAxisTicks },
        }
      }
    }));
  }

  const peWrap = document.getElementById('peer-group-pe-wrap');
  if (peWrap) peWrap.style.width = chartWidth;
  const peCanvas = document.getElementById('peer-group-pe-chart');
  if (peCanvas) {
    _peerGroupCharts.push(new Chart(peCanvas, {
      type: 'bar',
      data: {
        labels,
        datasets: [{
          label: 'P/E (เท่า)', data: rows.map(r => r.pe),
          backgroundColor: rows.map(r => r.symbol === baseSym ? '#58a6ff' : '#8b949e'),
        }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          y: { ticks: { callback: v => v + 'x' }, grid: { color: gridColor } },
          x: { grid: { display: false }, ticks: xAxisTicks },
        }
      }
    }));
  }
}

function _peerGroupRankingHtml(rows, baseSym) {
  const ranked = rows.filter(r => r.q_net_profit_yoy != null).slice().sort((a, b) => b.q_net_profit_yoy - a.q_net_profit_yoy);
  if (!ranked.length) return '';
  const baseRank = ranked.findIndex(r => r.symbol === baseSym) + 1;
  const medal = _mtMedal;
  const growthColor = v => v == null ? '' : v >= 0 ? 'color:var(--green,#3fb950)' : 'color:var(--red,#f85149)';
  const rowsHtml = ranked.map((r, i) => {
    const isBase = r.symbol === baseSym;
    return `<tr style="${isBase ? 'background:rgba(88,166,255,0.12);font-weight:700' : ''}">
      <td>${medal(i)}</td>
      <td style="text-align:left">${isBase ? '⭐ ' : ''}${r.symbol}</td>
      <td style="text-align:right">${_finFmt(r.q_net_profit)}</td>
      <td style="text-align:right;${growthColor(r.q_net_profit_yoy)}">${_peerGroupSignedPct(r.q_net_profit_yoy)}</td>
      <td style="text-align:right;${growthColor(r.q_net_profit_qoq)}">${_peerGroupSignedPct(r.q_net_profit_qoq)}</td>
      <td style="text-align:right">${_finFmt(r.net_profit_ttm)}</td>
      <td style="text-align:right;${growthColor(r.ttm_net_profit_yoy)}">${_peerGroupSignedPct(r.ttm_net_profit_yoy)}</td>
    </tr>`;
  }).join('');
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px;font-size:13px">🚀 กำไรปกติโตแรงสุด — เรียงตาม YoY% ไตรมาสล่าสุด${baseRank ? ` | ${baseSym} อยู่อันดับ ${baseRank} จาก ${ranked.length}` : ''}</div>
    <div style="overflow-x:auto">
      <table class="data-table" style="font-size:12px;min-width:640px">
        <thead><tr><th>#</th><th style="text-align:left">หุ้น</th><th style="text-align:right">กำไรปกติ Q (บาท)</th><th style="text-align:right">YoY% (Q)</th><th style="text-align:right">QoQ% (Q)</th><th style="text-align:right">กำไรปกติ TTM (บาท)</th><th style="text-align:right">YoY% (TTM)</th></tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>
  </div>`;
}

function _peerGroupRenderBody() {
  const body = document.getElementById('peer-group-body');
  if (!body) return;
  const rows = (_peerGroupRows || []).filter(r => !r.no_data);
  const missing = (_peerGroupRows || []).filter(r => r.no_data).map(r => r.symbol);
  const baseSym = (_peerMeta && _peerMeta.base_symbol) || (rows[0] && rows[0].symbol);
  if (!rows.length) {
    body.innerHTML = '<div class="empty">ไม่พบข้อมูลงบการเงินของหุ้นที่เลือก</div>';
    return;
  }
  rows.sort((a, b) => (b.mkt_cap || 0) - (a.mkt_cap || 0));
  const missingNote = missing.length
    ? `<div style="font-size:11px;color:#d29922;margin-bottom:8px">⚠ ไม่มีข้อมูลงบการเงินเพียงพอสำหรับ: ${_escHtml(missing.join(', '))}</div>` : '';

  body.innerHTML = missingNote +
    _peerGroupHeaderHtml(rows, baseSym) +
    _peerGroupTableHtml(0, 'Margins / ROE / Valuation (TTM 4Q)', '💹', _PEER_GROUP_TABLE1_GROUPS, rows, baseSym) +
    _peerGroupChartsHtml() +
    _peerGroupTableHtml(1, 'รายการการเงิน — ไตรมาสล่าสุด', '🧾', _PEER_GROUP_TABLE3, rows, baseSym) +
    _peerGroupRankingHtml(rows, baseSym);

  _peerGroupRenderCharts(rows, baseSym);
}

// ============================================================
// SECTOR WORKSPACE — มุมมอง "🏭 Sector Workspace" ของหน้า Peer Compare (เฉพาะหุ้นไทย)
// สรุปคุณภาพงบการเงินทั้งกลุ่มเป็นการ์ด KPI (median + top zone + coverage) + กราฟจัดอันดับ
// สภาพคล่อง/กระแสเงินสดทั้งกลุ่ม — ใช้ข้อมูลเดียวกับมุมมอง "🗂 หุ้นเทียบกับกลุ่ม" (_peerGroupRows
// จาก /api/peer-group-detail) แค่สรุปเป็นภาพรวมกลุ่มแทนตารางเทียบรายตัว v1 นี้ตั้งใจไม่ทำ Quality
// Zone Map / Composite Score เพราะเป็นสูตรที่ต้องออกแบบเกณฑ์เอง (ยังไม่มี field รองรับ) — ทำเฉพาะ
// ส่วนที่คำนวณได้ตรงไปตรงมาจาก field ที่มีอยู่แล้วก่อน
// ============================================================

function renderPeerSectorWorkspace() {
  _peerGroupDestroyCharts();
  _peerDestroyScatterChart();
  const box = document.getElementById('peer-results');
  if (_peerMarket !== 'TH') {
    box.innerHTML = '<div class="empty">มุมมอง "Sector Workspace" รองรับเฉพาะหุ้นไทยตอนนี้ — สลับไปแท็บ 🇹🇭 ไทย ก่อน</div>';
    return;
  }
  if (!_peerRows.length) return;
  if (_peerGroupSyms === null) _peerGroupSyms = _peerGroupAutoPick();
  box.innerHTML = _peerGroupChipsHtml() + '<div id="peer-workspace-body"><div class="empty">กำลังโหลด...</div></div>';
  _peerGroupFetch();
}

// ตัวชี้วัดคุณภาพสรุประดับกลุ่ม — median (ตัวกลางกลุ่ม) + top zone (ค่าเฉลี่ยของ 25% ที่ดีที่สุด)
const _WORKSPACE_KPI_METRICS = [
  { k: 'rev_cagr_3y',    label: 'Rev CAGR 3Y %',    unit: 'pct', lowerBetter: false, tip: 'รายได้โตเฉลี่ยทบต้นต่อปี — TTM ปัจจุบันเทียบ TTM เมื่อ 12 ไตรมาสก่อน' },
  { k: 'profit_cagr_3y', label: 'Profit CAGR 3Y %', unit: 'pct', lowerBetter: false, tip: 'กำไรโตเฉลี่ยทบต้นต่อปี — TTM ปัจจุบันเทียบ TTM เมื่อ 12 ไตรมาสก่อน' },
  { k: 'fcf_margin',     label: 'FCF Margin %',     unit: 'pct', lowerBetter: false, tip: 'กระแสเงินสดอิสระ (FCF) TTM ÷ รายได้ TTM' },
  { k: 'cfo_ni_ratio',   label: 'CFO/NP',           unit: 'x',   lowerBetter: false, tip: 'กระแสเงินสดจากดำเนินงาน ÷ กำไรสุทธิ — ยิ่งสูงยิ่งแปลงกำไรเป็นเงินสดได้จริง' },
  { k: 'roe',            label: 'ROE %',            unit: 'pct', lowerBetter: false, tip: 'ผลตอบแทนต่อส่วนผู้ถือหุ้น' },
  { k: 'gpm',            label: 'GPM %',            unit: 'pct', lowerBetter: false, tip: 'อัตรากำไรขั้นต้น' },
  { k: 'de_ratio',       label: 'D/E',              unit: 'x',   lowerBetter: true,  tip: 'หนี้สินรวม ÷ ส่วนผู้ถือหุ้น — ยิ่งต่ำยิ่งปลอดภัย' },
];

function _workspaceMetricStats(rows, key, lowerBetter) {
  const vals = rows.map(r => r[key]).filter(v => v != null && !isNaN(v));
  if (!vals.length) return null;
  const sorted = vals.slice().sort((a, b) => a - b);
  const n = sorted.length;
  const median = n % 2 ? sorted[(n - 1) / 2] : (sorted[n / 2 - 1] + sorted[n / 2]) / 2;
  const zoneCount = Math.max(1, Math.round(n * 0.25));
  const zoneVals = lowerBetter ? sorted.slice(0, zoneCount) : sorted.slice(n - zoneCount);
  const topZone = zoneVals.reduce((s, v) => s + v, 0) / zoneVals.length;
  return { median, topZone, coverage: n, total: rows.length };
}

function _workspaceFmtVal(v, unit) {
  if (v == null) return '–';
  return unit === 'x' ? v.toFixed(2) + 'x' : (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
}

function _workspaceKpiCardsHtml(rows) {
  const cards = _WORKSPACE_KPI_METRICS.map(m => {
    const stats = _workspaceMetricStats(rows, m.k, m.lowerBetter);
    if (!stats) {
      return `<div class="card" style="padding:12px 14px">
        <div style="font-weight:700;font-size:13px;margin-bottom:6px">${m.label}${_tipIconHtml(m.tip)}</div>
        <div style="color:var(--text2);font-size:12px">ไม่มีข้อมูล</div>
      </div>`;
    }
    return `<div class="card" style="padding:12px 14px">
      <div style="font-weight:700;font-size:13px;margin-bottom:6px">${m.label}${_tipIconHtml(m.tip)}</div>
      <div style="font-size:12px;color:var(--text2)">median: <b style="color:var(--text,#e6edf3)">${_workspaceFmtVal(stats.median, m.unit)}</b></div>
      <div style="font-size:12px;color:var(--text2)">top zone: <b style="color:var(--green,#3fb950)">${_workspaceFmtVal(stats.topZone, m.unit)}</b></div>
      <div style="font-size:11px;color:var(--text2);margin-top:4px">${stats.coverage}/${stats.total} หุ้นมีข้อมูล</div>
    </div>`;
  }).join('');
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;font-size:13px;margin-bottom:2px">✏️ ตัวชี้วัดที่ใช้คัดคุณภาพกลุ่ม</div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:10px">median = ค่ากลางของกลุ่ม (ตัดผลกระทบตัวสุดโต่ง) · top zone = ค่าเฉลี่ยของ 25% หุ้นที่ดีที่สุดในตัวชี้วัดนั้น · แตะไอคอน ℹ ที่แต่ละการ์ดเพื่อดูคำอธิบายตัวชี้วัด</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px">${cards}</div>
  </div>`;
}

// ส่วนแบ่งรายได้/กำไรในกลุ่ม + HHI (ดัชนีกระจุกตัว มาตรฐาน 0-10000 จาก Σ(share%)²) — คำนวณสด
// ฝั่ง client ล้วนๆ จาก revenue_ttm/net_profit_ttm ที่มีอยู่แล้วใน rows ไม่ต้องแตะ backend เลย
// กำไร: ฐานคิด % ใช้เฉพาะหุ้นที่กำไรเป็นบวก (หุ้นขาดทุนหาร % ส่วนแบ่ง "กำไร" ไม่ได้ความหมายอะไร —
// แสดงแยกเป็นลิสต์ "ขาดทุน" ต่างหากแทน) — ผลข้างเคียง: เขียน _rev_share/_profit_share ลงใน rows
// ตรงๆ (pseudo-field คำนวณสด ไม่ใช่จาก API) ให้ _WORKSPACE_RANK_METRICS ด้านล่างอ่านต่อได้เลย
function _hhiLabel(hhi) {
  if (hhi == null) return '';
  if (hhi < 1500) return 'กระจายตัวดี';
  if (hhi < 2500) return 'กระจุกตัวปานกลาง';
  return 'กระจุกตัวสูง';
}

function _workspaceComputeShares(rows) {
  const revRows = rows.filter(r => r.revenue_ttm != null && r.revenue_ttm > 0);
  const revTotal = revRows.reduce((s, r) => s + r.revenue_ttm, 0);
  revRows.forEach(r => { r._rev_share = revTotal ? r.revenue_ttm / revTotal * 100 : null; });

  const profitRows = rows.filter(r => r.net_profit_ttm != null && r.net_profit_ttm > 0);
  const profitTotal = profitRows.reduce((s, r) => s + r.net_profit_ttm, 0);
  profitRows.forEach(r => { r._profit_share = profitTotal ? r.net_profit_ttm / profitTotal * 100 : null; });

  const lossRows = rows.filter(r => r.net_profit_ttm != null && r.net_profit_ttm < 0)
    .slice().sort((a, b) => a.net_profit_ttm - b.net_profit_ttm);

  const sumSq = arr => arr.reduce((s, v) => s + v * v, 0);
  const top5Sum = (arr, key) => arr.slice().sort((a, b) => b[key] - a[key]).slice(0, 5).reduce((s, r) => s + r[key], 0);

  return {
    revTotal, profitTotal, lossRows,
    revCount: revRows.length, profitCount: profitRows.length,
    hhiRev: revRows.length ? sumSq(revRows.map(r => r._rev_share)) : null,
    hhiProfit: profitRows.length ? sumSq(profitRows.map(r => r._profit_share)) : null,
    top5Rev: revRows.length ? top5Sum(revRows, '_rev_share') : null,
    top5Profit: profitRows.length ? top5Sum(profitRows, '_profit_share') : null,
  };
}

function _workspaceShareSummaryHtml(stats) {
  const lossHtml = stats.lossRows.length
    ? `<div style="margin-top:8px;font-size:12px;color:var(--red,#f85149)">⚠ ขาดทุน ${stats.lossRows.length} ตัว: ${stats.lossRows.map(r => `${r.symbol} (${_finFmt(r.net_profit_ttm)})`).join(', ')}</div>`
    : '';
  const fmtPct = v => v != null ? v.toFixed(1) + '%' : '–';
  const fmtHhi = v => v != null ? `${Math.round(v)} (${_hhiLabel(v)})` : '–';
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;font-size:13px;margin-bottom:4px">🎯 ส่วนแบ่งในกลุ่ม — Share / Concentration${_tipIconHtml('Top 5 = สัดส่วนรายได้/กำไรของ 5 หุ้นที่ใหญ่สุดในกลุ่มเทียบทั้งกลุ่ม (ยิ่งสูงยิ่งกระจุกอยู่ไม่กี่ตัว)<br><br>HHI (Herfindahl-Hirschman Index) = Σ(ส่วนแบ่ง%)² วัดการกระจุกตัวทั้งกลุ่ม:<br>&lt;1500 กระจายตัวดี · 1500-2500 กระจุกตัวปานกลาง · &gt;2500 กระจุกตัวสูง')}</div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:8px">รายได้/กำไรรวมคิดเฉพาะหุ้นที่มีค่าเป็นบวก — หุ้นขาดทุนแสดงแยกเป็นลิสต์ด้านล่างแทนเพราะหาร % ส่วนแบ่ง "กำไร" ไม่ได้ความหมาย</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px;font-size:12px;color:var(--text2)">
      <div>รายได้รวม (${stats.revCount} ตัว): <b style="color:var(--text,#e6edf3)">${_finFmt(stats.revTotal)}</b><br>Top 5 = <b style="color:var(--text,#e6edf3)">${fmtPct(stats.top5Rev)}</b> · HHI <b style="color:var(--text,#e6edf3)">${fmtHhi(stats.hhiRev)}</b></div>
      <div>กำไรรวม (เฉพาะตัวมีกำไร ${stats.profitCount} ตัว): <b style="color:var(--text,#e6edf3)">${_finFmt(stats.profitTotal)}</b><br>Top 5 = <b style="color:var(--text,#e6edf3)">${fmtPct(stats.top5Profit)}</b> · HHI <b style="color:var(--text,#e6edf3)">${fmtHhi(stats.hhiProfit)}</b></div>
    </div>
    ${lossHtml}
  </div>`;
}

// Multi-metric Heatmap + Composite Score — เทียบทุกตัวในกลุ่มพร้อมกันหลายมิติในตารางเดียว สีไล่
// ตาม percentile ต่อคอลัมน์ ใช้ _peerPercentile/_peerCellColor ตัวเดียวกับมุมมอง "ตาราง" หลักของ
// หน้านี้ตรงๆ (ไม่ปั้น logic ใหม่) — Composite = ค่าเฉลี่ย percentile (0-1) ของทุกคอลัมน์ที่มีข้อมูล
// ×100 เป็น "equal-weight percentile average" ไม่ใช่สูตรถ่วงน้ำหนักตามดุลยพินิจ (แบบเดียวกับที่
// _peerPercentile ใช้อยู่แล้วทั้งหน้า) — จงใจไม่ทำ weighting เองเพราะไม่มีเกณฑ์มาตรฐานให้ยึด
const _WORKSPACE_HEATMAP_METRICS = [
  { k: 'q_revenue_yoy',    label: 'Rev YoY',  unit: 'pct', lowerBetter: false, tip: 'รายได้ไตรมาสล่าสุดเทียบไตรมาสเดียวกันปีก่อน (YoY)' },
  { k: 'q_revenue_qoq',    label: 'Rev QoQ',  unit: 'pct', lowerBetter: false, tip: 'รายได้ไตรมาสล่าสุดเทียบไตรมาสก่อนหน้า (QoQ)' },
  { k: 'q_net_profit_yoy', label: 'NP YoY',   unit: 'pct', lowerBetter: false, tip: 'กำไรสุทธิไตรมาสล่าสุดเทียบไตรมาสเดียวกันปีก่อน (YoY)' },
  { k: 'q_net_profit_qoq', label: 'NP QoQ',   unit: 'pct', lowerBetter: false, tip: 'กำไรสุทธิไตรมาสล่าสุดเทียบไตรมาสก่อนหน้า (QoQ)' },
  { k: 'gpm',              label: 'GPM',      unit: 'pct', lowerBetter: false, tip: 'อัตรากำไรขั้นต้น (Gross Profit Margin) = กำไรขั้นต้น ÷ รายได้ ไตรมาสล่าสุด' },
  { k: 'npm',              label: 'NPM',      unit: 'pct', lowerBetter: false, tip: 'อัตรากำไรสุทธิ (Net Profit Margin) = กำไรสุทธิ ÷ รายได้ ไตรมาสล่าสุด' },
  { k: 'fcf_margin',       label: 'FCF Mg',   unit: 'pct', lowerBetter: false, tip: 'กระแสเงินสดอิสระ (FCF) TTM ÷ รายได้ TTM' },
  { k: 'roic',             label: 'ROIC',     unit: 'pct', lowerBetter: false, tip: 'NOPAT TTM (กำไรดำเนินงาน×(1-อัตราภาษี effective)) ÷ (หนี้สินรวม+ส่วนผู้ถือหุ้น-เงินสด งวดล่าสุด) — สูตรเดียวกับ ROIC (TTM) ในหน้างบรวมทุกแหล่ง' },
  { k: 'roe',              label: 'ROE',      unit: 'pct', lowerBetter: false, tip: 'ผลตอบแทนต่อส่วนผู้ถือหุ้น (Return on Equity) TTM' },
  { k: 'de_ratio',         label: 'D/E',      unit: 'x',   lowerBetter: true,  tip: 'หนี้สินรวม ÷ ส่วนผู้ถือหุ้น งวดล่าสุด — ยิ่งต่ำยิ่งปลอดภัย (สีเขียว)' },
];

// เขียน r._composite ลงทุกแถวใน rows (ผลข้างเคียง เหมือน _workspaceComputeShares) — ต้อง cover
// อย่างน้อย 1 metric ถึงจะมี composite ให้ (แถวที่ไม่มีข้อมูลเลยสักคอลัมน์ได้ null)
function _workspaceComputeComposite(rows) {
  const arrays = {};
  _WORKSPACE_HEATMAP_METRICS.forEach(m => { arrays[m.k] = rows.map(r => r[m.k]).filter(v => v != null); });
  rows.forEach(r => {
    const pcts = _WORKSPACE_HEATMAP_METRICS
      .map(m => _peerPercentile(r[m.k], arrays[m.k], m.lowerBetter, _PEER_NEG_INVALID.has(m.k)))
      .filter(p => p != null);
    r._composite = pcts.length ? Math.round(pcts.reduce((s, v) => s + v, 0) / pcts.length * 100) : null;
  });
}

let _workspaceHeatmapSort = { key: '_composite', dir: 1 };   // dir 1 = มาก->น้อย, -1 = น้อย->มาก (คอนเวนชันเดียวกับ _peerSort/_peerGroupSort)

function _workspaceHeatmapSortBy(key) {
  if (_workspaceHeatmapSort.key === key) _workspaceHeatmapSort.dir *= -1;
  else _workspaceHeatmapSort = { key, dir: key === 'symbol' ? -1 : 1 };
  _workspaceRenderHeatmapTable();
}

function _workspaceHeatmapSortArrow(key) {
  if (_workspaceHeatmapSort.key !== key) return '';
  return _workspaceHeatmapSort.dir === 1 ? ' ▼' : ' ▲';
}

function _workspaceRenderHeatmapTable() {
  const box = document.getElementById('ws-heatmap-body');
  if (!box) return;
  const rows = (_peerGroupRows || []).filter(r => !r.no_data);
  box.innerHTML = _workspaceHeatmapTableHtml(rows);
}

function _workspaceHeatmapTableHtml(rows) {
  const { key, dir } = _workspaceHeatmapSort;
  const sorted = rows.slice().sort((a, b) => {
    if (key === 'symbol') return dir * b.symbol.localeCompare(a.symbol);
    const av = a[key], bv = b[key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    return dir * (bv - av);
  });

  const headCells = [{ k: 'symbol', label: 'Ticker' }]
    .concat(_WORKSPACE_HEATMAP_METRICS)
    .concat([{ k: '_composite', label: 'Composite', tip: 'ค่าเฉลี่ย percentile (0-100) ของทุกคอลัมน์ที่หุ้นนี้มีข้อมูล — ยิ่งสูงยิ่งเด่นรอบด้านเทียบกลุ่มนี้ (equal-weight, ไม่ถ่วงน้ำหนักเป็นพิเศษคอลัมน์ไหน)' }])
    .map(c => `<th class="${c.k === 'symbol' ? '' : 'r'}" style="cursor:pointer" title="${c.tip || ''}" onclick="_workspaceHeatmapSortBy('${c.k}')">${c.label}${_workspaceHeatmapSortArrow(c.k)}</th>`)
    .join('');

  // เตรียม array ต่อ metric ครั้งเดียวนอก loop แถว (ไม่ใช่ recompute rows.map+filter ซ้ำทุกแถว ×
  // ทุกคอลัมน์ — เหมือนที่ _workspaceComputeComposite ทำไปแล้วรอบหนึ่งตอนคำนวณ _composite)
  const metricArrays = {};
  _WORKSPACE_HEATMAP_METRICS.forEach(m => { metricArrays[m.k] = rows.map(x => x[m.k]).filter(v => v != null); });

  const bodyRows = sorted.map(r => {
    const cells = _WORKSPACE_HEATMAP_METRICS.map(m => {
      const color = _peerCellColor(_peerPercentile(r[m.k], metricArrays[m.k], m.lowerBetter, _PEER_NEG_INVALID.has(m.k)));
      const v = r[m.k];
      const txt = v == null ? '–' : (m.unit === 'x' ? v.toFixed(2) + 'x' : (v >= 0 ? '+' : '') + v.toFixed(1) + '%');
      return `<td style="text-align:right;background:${color}">${txt}</td>`;
    }).join('');
    const compColor = r._composite != null ? `rgba(88,166,255,${(0.08 + r._composite / 100 * 0.5).toFixed(2)})` : '';
    return `<tr><td style="text-align:left;font-weight:600">${r.symbol}</td>${cells}<td style="text-align:right;font-weight:700;background:${compColor}">${r._composite != null ? r._composite : '–'}</td></tr>`;
  }).join('');

  return `<div style="overflow:auto;max-height:60vh">
    <table class="data-table" style="font-size:12px;min-width:900px">
      <thead><tr>${headCells}</tr></thead>
      <tbody>${bodyRows}</tbody>
    </table>
  </div>`;
}

function _workspaceHeatmapSectionHtml() {
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:4px;font-size:13px">🎯 Multi-metric Heatmap — เห็น "หุ้นเด่นทุกแกน"</div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:8px">สีไล่ตาม percentile ในกลุ่มนี้ต่อคอลัมน์ (เขียว=ดีกว่ากลุ่ม แดง=แย่กว่ากลุ่ม) · Composite = ค่าเฉลี่ย percentile ทุกคอลัมน์ (0-100, ยิ่งสูงยิ่งเด่นรอบด้าน) · คลิกหัวคอลัมน์เพื่อเรียง</div>
    <div id="ws-heatmap-body"></div>
  </div>`;
}

// Contribution — ใครลาก/ใครถ่วงกำไรกลุ่ม (ผลต่างกำไรสุทธิ TTM เทียบ TTM เมื่อ 4 ไตรมาสก่อน เป็น
// บาทจริง ต่างจากกราฟจัดอันดับด้านบนที่เป็น % ทั้งหมด) ใช้ net_profit_ttm_prior ที่ backend เพิ่ง
// expose เพิ่ม (เดิมคำนวณอยู่แล้วข้างในเพื่อหา ttm_net_profit_yoy % แต่ไม่เคย return ค่าดิบออกมา)
function _workspaceContributionHtml() {
  return `<div class="card" style="padding:12px 14px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:4px;font-size:13px">🔀 Contribution — ใครลาก/ใครถ่วงกำไรกลุ่ม</div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:8px">ผลต่างกำไรสุทธิ TTM เทียบ TTM เมื่อ 4 ไตรมาสก่อน (บาท) — เขียว=ดันกำไรกลุ่มขึ้น แดง=ฉุดกำไรกลุ่มลง (ต้องมีงบย้อนหลังอย่างน้อย 8 ไตรมาส)</div>
    <div style="position:relative" id="ws-contrib-box"><canvas id="ws-contrib"></canvas></div>
  </div>`;
}

function _workspaceRenderContributionChart(rows) {
  const canvas = document.getElementById('ws-contrib');
  const box = document.getElementById('ws-contrib-box');
  if (!canvas || !box) return;
  const contrib = rows
    .filter(r => r.net_profit_ttm != null && r.net_profit_ttm_prior != null)
    .map(r => ({ symbol: r.symbol, delta: r.net_profit_ttm - r.net_profit_ttm_prior }))
    .sort((a, b) => b.delta - a.delta);
  if (!contrib.length) { box.innerHTML = '<div class="empty">ไม่มีข้อมูลเพียงพอ (ต้องมีงบย้อนหลังอย่างน้อย 8 ไตรมาส)</div>'; return; }
  box.style.height = Math.max(180, contrib.length * 20) + 'px';
  _peerGroupCharts.push(new Chart(canvas, {
    type: 'bar',
    data: {
      labels: contrib.map(c => c.symbol),
      datasets: [{ data: contrib.map(c => c.delta), backgroundColor: contrib.map(c => c.delta >= 0 ? '#3fb950' : '#f85149') }]
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => _finFmt(ctx.parsed.x) } } },
      scales: {
        x: { ticks: { callback: v => _finFmt(v) }, grid: { color: 'rgba(139,148,158,0.15)' } },
        y: { grid: { display: false }, ticks: { font: { size: 10 }, autoSkip: false } },
      }
    }
  }));
}

// จัดอันดับสภาพคล่อง/กระแสเงินสดทั้งกลุ่มเป็นกราฟแท่งแนวนอน — เรียงดีสุด→แย่สุดเสมอ (lowerBetter
// ที่ต่างกันแต่ละ metric ตัดสินทิศทางการเรียง ไม่ใช่ทิศทางแกน) — _rev_share/_profit_share เป็น
// pseudo-field ที่ _workspaceComputeShares เขียนลง rows ไว้ก่อนแล้ว (ดูคอมเมนต์ด้านบน) ต้องเรียก
// ฟังก์ชันนั้นก่อนเสมอถึงจะมีค่าให้กราฟ 2 อันนี้อ่าน
const _WORKSPACE_RANK_METRICS = [
  { k: 'de_ratio',      canvasId: 'ws-rank-de',   title: 'D/E Ratio เปรียบเทียบ',        unit: 'x',   lowerBetter: true,
    tip: 'หนี้สินรวม ÷ ส่วนผู้ถือหุ้น — ยิ่งต่ำยิ่งปลอดภัย (เรียงจากต่ำสุด = ดีสุด อยู่บนสุด)' },
  { k: 'current_ratio', canvasId: 'ws-rank-cr',   title: 'Current Ratio เปรียบเทียบ',    unit: 'x',   lowerBetter: false,
    tip: 'สินทรัพย์หมุนเวียน ÷ หนี้สินหมุนเวียน — ยิ่งสูงยิ่งมีสภาพคล่องจ่ายหนี้ระยะสั้นได้ (เรียงจากสูงสุด = ดีสุด อยู่บนสุด)' },
  { k: 'cash_cycle',    canvasId: 'ws-rank-cc',   title: 'Cash Cycle เปรียบเทียบ (วัน)', unit: 'day', lowerBetter: true,
    tip: 'จำนวนวันตั้งแต่จ่ายเงินซื้อวัตถุดิบจนได้เงินสดคืนจากการขาย — ยิ่งสั้นยิ่งหมุนเงินเร็ว (เรียงจากสั้นสุด = ดีสุด อยู่บนสุด)' },
  { k: 'cfo_margin',    canvasId: 'ws-rank-cfom', title: 'CFO Margin % เปรียบเทียบ',     unit: 'pct', lowerBetter: false,
    tip: 'กระแสเงินสดจากดำเนินงาน (CFO) TTM ÷ รายได้ TTM (เรียงจากสูงสุด = ดีสุด อยู่บนสุด)' },
  { k: 'fcf_margin',    canvasId: 'ws-rank-fcfm', title: 'FCF Margin % เปรียบเทียบ',     unit: 'pct', lowerBetter: false,
    tip: 'กระแสเงินสดอิสระ (FCF) TTM ÷ รายได้ TTM (เรียงจากสูงสุด = ดีสุด อยู่บนสุด)' },
  { k: '_rev_share',    canvasId: 'ws-rank-revshare',    title: 'Revenue Share % เปรียบเทียบ',                    unit: 'pct', lowerBetter: false,
    tip: 'สัดส่วนรายได้ TTM ของหุ้นนี้เทียบรายได้รวมทั้งกลุ่ม (เฉพาะหุ้นที่มีรายได้เป็นบวก)' },
  { k: '_profit_share', canvasId: 'ws-rank-profitshare', title: 'Profit Share % เปรียบเทียบ (เฉพาะตัวมีกำไร)',   unit: 'pct', lowerBetter: false,
    tip: 'สัดส่วนกำไรสุทธิ TTM ของหุ้นนี้เทียบกำไรรวมทั้งกลุ่ม (เฉพาะหุ้นที่มีกำไรเป็นบวก — หุ้นขาดทุนไม่นับรวม)' },
];

function _workspaceRankChartsHtml() {
  const boxes = _WORKSPACE_RANK_METRICS.map(m => `
    <div class="card" style="padding:12px 14px">
      <div style="font-weight:700;margin-bottom:8px;font-size:13px" id="${m.canvasId}-title">${m.title}${_tipIconHtml(m.tip)}</div>
      <div style="position:relative" id="${m.canvasId}-box"><canvas id="${m.canvasId}"></canvas></div>
    </div>`).join('');
  return `<div style="font-size:11px;color:var(--text2);margin-bottom:8px">🎨 สี 3 โซนคือ อันดับภายในกลุ่มนี้เอง (เขียว = 1/3 แรกที่ดีสุด, เหลือง = 1/3 กลาง, แดง = 1/3 ท้ายที่แย่สุด) ไม่ใช่เกณฑ์ตายตัวข้ามกลุ่ม — แตะไอคอน ℹ ที่แต่ละกราฟเพื่อดูคำอธิบายตัวชี้วัด</div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px;margin-bottom:12px">${boxes}</div>`;
}

function _workspaceRankFmtVal(v, unit) {
  return unit === 'pct' ? v.toFixed(1) + '%' : unit === 'day' ? Math.round(v) + ' วัน' : v.toFixed(2) + 'x';
}

function _workspaceRenderRankCharts(rows) {
  _WORKSPACE_RANK_METRICS.forEach(m => {
    const canvas = document.getElementById(m.canvasId);
    const box = document.getElementById(m.canvasId + '-box');
    if (!canvas || !box) return;
    const ranked = rows.filter(r => r[m.k] != null).slice()
      .sort((a, b) => m.lowerBetter ? a[m.k] - b[m.k] : b[m.k] - a[m.k]);
    if (!ranked.length) { box.innerHTML = '<div class="empty">ไม่มีข้อมูล</div>'; return; }
    box.style.height = Math.max(180, ranked.length * 22) + 'px';
    // สี 3 โซนตามอันดับภายในกลุ่ม (เขียว=1/3 แรก ดีสุด, เหลือง=กลาง, แดง=1/3 ท้าย แย่สุด) — เทียบ
    // กันเองในกลุ่มนี้ ไม่ใช่ threshold ตายตัวข้ามกลุ่ม
    const n = ranked.length;
    const colorAt = i => {
      const t = i / Math.max(1, n - 1);
      return t < 1 / 3 ? '#3fb950' : t < 2 / 3 ? '#d29922' : '#f85149';
    };
    _peerGroupCharts.push(new Chart(canvas, {
      type: 'bar',
      data: {
        labels: ranked.map(r => r.symbol),
        datasets: [{ data: ranked.map(r => r[m.k]), backgroundColor: ranked.map((r, i) => colorAt(i)) }]
      },
      options: {
        indexAxis: 'y',
        responsive: true, maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: ctx => _workspaceRankFmtVal(ctx.parsed.x, m.unit) } },
        },
        scales: {
          x: { ticks: { callback: v => _workspaceRankFmtVal(v, m.unit) }, grid: { color: 'rgba(139,148,158,0.15)' } },
          y: { grid: { display: false }, ticks: { font: { size: 10 }, autoSkip: false } },
        }
      }
    }));
  });
}

function _peerWorkspaceRenderBody() {
  const body = document.getElementById('peer-workspace-body');
  if (!body) return;
  const rows = (_peerGroupRows || []).filter(r => !r.no_data);
  const missing = (_peerGroupRows || []).filter(r => r.no_data).map(r => r.symbol);
  if (!rows.length) {
    body.innerHTML = '<div class="empty">ไม่พบข้อมูลงบการเงินของหุ้นที่เลือก</div>';
    return;
  }
  const missingNote = missing.length
    ? `<div style="font-size:11px;color:#d29922;margin-bottom:8px">⚠ ไม่มีข้อมูลงบการเงินเพียงพอสำหรับ: ${_escHtml(missing.join(', '))}</div>` : '';
  const level = _peerMeta.level === 'industry' ? 'Industry' : 'Sector';
  const groupRaw = _peerMeta.group || '';       // ค่าดิบ — ใช้ยิง /api/sector-trend ตอนท้าย
  const group = _escHtml(groupRaw);             // escape สำหรับ innerHTML เท่านั้น
  const shareStats = _workspaceComputeShares(rows);   // เขียน _rev_share/_profit_share ลง rows ก่อน render กราฟ
  _workspaceComputeComposite(rows);                   // เขียน _composite ลง rows ก่อน render heatmap

  // Sector Margin Trend + Breadth ย้อนหลัง 20 ไตรมาส (ดึงจาก /api/sector-trend) — endpoint นี้
  // scope symbols ตามชื่อ "sector" ทางการของ SET เท่านั้น ไม่รองรับ level="industry" (กลุ่มย่อยกว่า
  // sector ไม่มี field ให้ query ตรงๆ) จึงโชว์ได้แค่ตอนดูระดับ Sector
  const trendSectionHtml = _peerMeta.level === 'sector'
    ? `<div id="ws-trend-box" style="margin-bottom:12px"><div class="empty">กำลังโหลดเทรนด์ย้อนหลัง 20 ไตรมาส...</div></div>`
    : `<div class="card" style="padding:12px 14px;margin-bottom:12px"><div style="font-size:12px;color:var(--text2)">📈 Sector Margin Trend / Breadth ย้อนหลัง 20 ไตรมาส ดูได้เฉพาะระดับ Sector เท่านั้น (ตอนนี้กำลังดูระดับ Industry Group "${group}")</div></div>`;

  body.innerHTML = missingNote +
    `<div class="card" style="padding:12px 14px;margin-bottom:12px">
       <div style="font-weight:700;font-size:14px">🏭 Sector Workspace: ${level} "${group}"</div>
       <div style="font-size:12px;color:var(--text2);margin-top:4px">สรุปคุณภาพงบการเงิน TTM ของ ${rows.length} หุ้นในกลุ่ม — median/top zone จากตัวชี้วัดสำคัญ + จัดอันดับสภาพคล่อง/กระแสเงินสดทั้งกลุ่ม (ติ๊กชิปด้านบนเพื่อตัดหุ้นออกได้)</div>
     </div>` +
    _workspaceKpiCardsHtml(rows) +
    _workspaceShareSummaryHtml(shareStats) +
    _workspaceHeatmapSectionHtml() +
    _workspaceRankChartsHtml() +
    _workspaceContributionHtml() +
    trendSectionHtml;
  _workspaceRenderHeatmapTable();
  _workspaceRenderRankCharts(rows);
  _workspaceRenderContributionChart(rows);
  if (_peerMeta.level === 'sector') _workspaceFetchAndRenderTrend(groupRaw);
}

// เทรนด์ย้อนหลัง 20 ไตรมาสของทั้ง sector ไม่ขึ้นกับหุ้นที่ติ๊กเลือก/ตัดออก (ต่างจากการ์ด KPI/กราฟ
// จัดอันดับด้านบนที่ผูกกับ _peerGroupSyms) — cache ฝั่ง client กันสลับ checkbox แล้ว fetch ซ้ำทุกครั้ง
// (backend มี cache 24h อยู่แล้วก็จริง แต่ยังกันการกระพริบ "กำลังโหลด" ที่ไม่จำเป็นได้)
let _workspaceTrendCache = {};

async function _workspaceFetchAndRenderTrend(sectorName) {
  const box = document.getElementById('ws-trend-box');
  if (!box) return;
  if (_workspaceTrendCache[sectorName]) {
    _workspaceRenderTrendSection(box, _workspaceTrendCache[sectorName]);
    return;
  }
  try {
    const r = await _fetchTimeout('/api/sector-trend?sector=' + encodeURIComponent(sectorName), 30000,
      'โหลดเทรนด์ของกลุ่มนี้ช้าเกินไป — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    _workspaceTrendCache[sectorName] = d.quarters || [];
    _workspaceRenderTrendSection(box, _workspaceTrendCache[sectorName]);
  } catch (e) {
    box.innerHTML = `<div class="empty" style="color:var(--red)">โหลดเทรนด์ไม่สำเร็จ: ${e.message}</div>`;
  }
}

function _workspaceTrendHtml() {
  const marginTip = 'NPM/ROE "aggregate" = คำนวณจากผลรวมกำไร/รายได้/ส่วนผู้ถือหุ้นของทั้ง sector ต่อไตรมาส (ไม่ใช่ค่าเฉลี่ยแบบถ่วงน้ำหนักเท่ากันทุกตัว) จึงถูกถ่วงน้ำหนักโดยหุ้นตัวใหญ่ในกลุ่มโดยธรรมชาติ — ดูทั้ง sector ไม่ผูกกับหุ้นที่ติ๊กเลือก/ตัดออกด้านบน';
  const breadthTip = '% ของหุ้นในกลุ่มที่ผ่านเกณฑ์แต่ละข้อ ณ ไตรมาสล่าสุด: รายได้/กำไรโต YoY หรือ CFO เป็นบวก (TTM) — <span style="color:#3fb950">เขียว</span> = ผ่าน ≥50% ของกลุ่ม, <span style="color:#f85149">แดง</span> = ต่ำกว่า 50%';
  return `<div style="display:grid;grid-template-columns:2fr 1fr;gap:12px">
    <div class="card" style="padding:12px 14px">
      <div style="font-weight:700;margin-bottom:8px;font-size:13px">📈 Sector Margin Trend — NPM/ROE เฉลี่ยกลุ่มย้อนหลัง 20 ไตรมาส${_tipIconHtml(marginTip)}</div>
      <div style="position:relative;height:260px"><canvas id="ws-margin-trend"></canvas></div>
    </div>
    <div class="card" style="padding:12px 14px">
      <div style="font-weight:700;margin-bottom:4px;font-size:13px">🌊 Breadth <span id="ws-breadth-quarter" style="color:var(--text2);font-weight:400"></span>${_tipIconHtml(breadthTip)}</div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:8px">การฟื้นตัวกระจายแค่ไหนในกลุ่ม (ไตรมาสล่าสุด)</div>
      <div style="position:relative;height:220px"><canvas id="ws-breadth"></canvas></div>
    </div>
  </div>`;
}

function _workspaceRenderTrendSection(box, quarters) {
  if (!quarters.length) { box.innerHTML = '<div class="empty">ไม่มีข้อมูลเทรนด์ย้อนหลังของกลุ่มนี้</div>'; return; }
  box.innerHTML = _workspaceTrendHtml();
  _workspaceRenderMarginTrendChart(quarters);
  _workspaceRenderBreadthBars(quarters);
}

function _workspaceRenderMarginTrendChart(quarters) {
  const canvas = document.getElementById('ws-margin-trend');
  if (!canvas) return;
  _peerGroupCharts.push(new Chart(canvas, {
    type: 'line',
    data: {
      labels: quarters.map(q => q.quarter),
      datasets: [
        { label: 'NPM % (aggregate)', data: quarters.map(q => q.npm), borderColor: '#58a6ff', backgroundColor: 'rgba(88,166,255,0.1)', tension: 0.3, spanGaps: true },
        { label: 'ROE % (aggregate)', data: quarters.map(q => q.roe_aggregate), borderColor: '#3fb950', backgroundColor: 'rgba(63,185,80,0.1)', tension: 0.3, spanGaps: true },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { position: 'top', labels: { boxWidth: 10, font: { size: 10 } } } },
      scales: {
        x: { ticks: { font: { size: 9 }, maxRotation: 60, minRotation: 60 }, grid: { display: false } },
        y: { ticks: { callback: v => v + '%' }, grid: { color: 'rgba(139,148,158,0.15)' } },
      }
    }
  }));
}

function _workspaceRenderBreadthBars(quarters) {
  const canvas = document.getElementById('ws-breadth');
  if (!canvas) return;
  const last = quarters[quarters.length - 1];
  const qLabel = document.getElementById('ws-breadth-quarter');
  if (qLabel) qLabel.textContent = last.quarter || '';
  const items = [
    { label: 'รายได้โต YoY', v: last.pct_revenue_growing },
    { label: 'กำไรโต YoY', v: last.pct_profit_growing },
    { label: 'CFO เป็นบวก (TTM)', v: last.pct_cfo_positive },
  ].filter(x => x.v != null);
  if (!items.length) { canvas.parentElement.innerHTML = '<div class="empty">ไม่มีข้อมูล</div>'; return; }
  _peerGroupCharts.push(new Chart(canvas, {
    type: 'bar',
    data: { labels: items.map(x => x.label), datasets: [{ data: items.map(x => x.v), backgroundColor: items.map(x => x.v >= 50 ? '#3fb950' : '#f85149') }] },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ctx.parsed.x.toFixed(1) + '%' } } },
      scales: {
        x: { min: 0, max: 100, ticks: { callback: v => v + '%' }, grid: { color: 'rgba(139,148,158,0.15)' } },
        y: { grid: { display: false }, ticks: { font: { size: 11 } } },
      }
    }
  }));
}

// ============================================================
// TEARSHEET — 📋 หุ้น 1 ตัว ครบในหน้าเดียว (งาน #1 ของ PLAN_stock_study_suite.txt — ครบทุกเฟส)
// รองรับ TH (ทุกหุ้น) + US/HK ทั้ง mirror universe — สมาชิกดัชนีหลัก (S&P500+Dow+NDX/
// HSI+HSCEI+HSTECH) ใช้ราคา/RS ที่คำนวณไว้ล่วงหน้า ส่วนหุ้นอื่นดึงแบบ on-demand ตอนเปิดดู
// (ดู sources/mirror_ondemand.py) — ช่อง input เป็น free-text อยู่แล้ว พิมพ์ตัวที่ไม่อยู่ใน
// datalist ก็ค้นได้ ตรงนี้แค่ขยาย autocomplete ให้ครอบคลุมด้วย (merge /api/mirror-symbols)
// ============================================================
let _tsData = null;
let _tsLoadSeq = 0;   // กัน response เก่า (หุ้นที่ดึงช้าจาก Yahoo) เขียนทับ _tsData/หน้าจอ ของหุ้นที่ผู้ใช้กดทีหลัง
let _tsMarket = 'TH';
// ค่าเริ่มต้นล่าสุดของ PE/PBV Valuation (ปุ่ม "↺ ค่าเริ่มต้น") — อัพเดทตอน render ครั้งแรก
// (naive: current PE/PBV ±25%) แล้วถูกเขียนทับด้วยสถิติย้อนหลังจริงตอน _tsApplyPeBandDefaults/
// _tsApplyPbvBandDefaults โหลดเสร็จ (ดู _tsLoadFinExtras) — ปุ่มรีเซ็ตอ่านค่าล่าสุดจากตรงนี้เสมอ
let _tsPeDefaults = null;
let _tsPbvDefaults = null;
let _mirrorSymbolsCache = null;

async function _loadMirrorSymbols() {
  if (_mirrorSymbolsCache) return _mirrorSymbolsCache;
  try {
    _mirrorSymbolsCache = await (await fetch('/api/mirror-symbols')).json();
    return _mirrorSymbolsCache;
  } catch { return {}; }   // ไม่ assign cache — ให้ครั้งถัดไป retry ใหม่แทนที่จะค้าง {} ตลอดไป
}

function initTearsheetPage() {
  initFinPage();
  _tsBuildDatalist();
}

function setTsMarket(mkt, btn) {
  _tsMarket = mkt;
  document.querySelectorAll('#ts-tab-th,#ts-tab-us,#ts-tab-hk,#ts-tab-jp').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const inp = document.getElementById('ts-sym');
  if (inp) inp.placeholder = mkt === 'TH' ? 'เช่น CPALL, PTT, KBANK' : mkt === 'US' ? 'เช่น AAPL, MSFT, NVDA' : mkt === 'JP' ? 'เช่น 7203.T, 6758.T' : 'เช่น 0700.HK, 9988.HK';
  _tsBuildDatalist();
}

// datalist ต่อตลาด — TH โคลนจาก fin-set-datalist (มีอยู่แล้ว), US/HK/JP โหลดจาก index metrics
// (โหลด lazy ครั้งแรกที่กดแท็บ — ไฟล์ค่อนข้างใหญ่ ไม่อยากโหลดตั้งแต่เข้าเมนูอื่น)
async function _tsBuildDatalist() {
  const dl = document.getElementById('ts-datalist');
  if (!dl) return;
  if (_tsMarket === 'TH') {
    const src = document.getElementById('fin-set-datalist');
    if (!src || !src.childElementCount) return;
    const key = 'TH:' + src.childElementCount;
    if (dl.dataset.key === key) return;
    dl.innerHTML = '';
    const frag = document.createDocumentFragment();
    [...src.children].forEach(o => frag.appendChild(o.cloneNode(true)));
    dl.appendChild(frag);
    dl.dataset.key = key;
    return;
  }
  // _usData/_hkData/_jpData เป็น top-level `let` ไม่ใช่ property ของ window — window['_usData']
  // undefined เสมอ ทำให้ก่อนหน้านี้ (ก) ยิง index-metrics ใหม่ทุกครั้งที่สลับแท็บ (ข) stocks เป็น []
  // ตลอด (autocomplete หุ้น US/HK/JP ไม่มีชื่อบริษัท) — ใช้ getter/setter ผ่าน _FS_MIRROR_IDX
  // เหมือน Screener+/_openMirrorStock + เช็ค d.error ก่อน cache (route คืน {error} 500 ตอนไฟล์หาย)
  const idx = _FS_MIRROR_IDX[_tsMarket.toLowerCase()];
  if (!idx.get()) {
    try {
      const d = await (await fetch(idx.endpoint)).json();
      if (d && !d.error && d.stocks) idx.set(d);
    } catch { return; }
  }
  const stocks = idx.get()?.stocks || [];
  const mirror = (await _loadMirrorSymbols())[_tsMarket] || [];
  const key = _tsMarket + ':' + stocks.length + ':' + mirror.length;
  if (dl.dataset.key === key) return;
  dl.innerHTML = '';
  const frag = document.createDocumentFragment();
  const seen = new Set();
  stocks.forEach(s => {
    seen.add(s.symbol);
    const o = document.createElement('option');
    o.value = s.symbol; o.label = s.name || s.symbol;
    frag.appendChild(o);
  });
  // หุ้น mirror นอกดัชนีหลัก — ไม่มีชื่อบริษัทเก็บไว้ (เบา ไม่คุ้มดึงชื่อสดแค่ autocomplete)
  // เติม ".HK"/".T" ให้ตรง convention เดียวกับสมาชิกดัชนีหลัก (backend ตัดออกเองก่อน lookup เสมอ)
  // JP ไม่มี mirror นอกดัชนีหลัก อยู่แล้วใน stocks (seen) ครบ — loop นี้จะไม่เพิ่มอะไรเพิ่ม
  mirror.forEach(rawSym => {
    const sym = _tsMarket === 'HK' ? rawSym + '.HK' : _tsMarket === 'JP' ? rawSym + '.T' : rawSym;
    if (seen.has(sym)) return;
    const o = document.createElement('option');
    o.value = sym;
    frag.appendChild(o);
  });
  dl.appendChild(frag);
  dl.dataset.key = key;
}

async function loadTearsheet(symArg, marketOverride) {
  const sym = (symArg || document.getElementById('ts-sym').value || '').toUpperCase().trim();
  if (!sym) return;
  document.getElementById('ts-sym').value = sym;
  const box = document.getElementById('ts-body');
  box.innerHTML = '<div class="empty">กำลังโหลด...</div>';
  // d.error มักสะท้อน sym ที่ผู้ใช้พิมพ์กลับมาตรงๆ (เช่น "ไม่พบหุ้น {sym}") และ sym มาจาก URL
  // path param — เข้าถึงได้ผ่าน deep-link ที่ปั้นเอง (#ts/us/<payload>) ไม่ใช่แค่ผ่านช่องค้นหา
  // ปกติ ต้อง escape ก่อนแทรกเป็น HTML content กัน reflected XSS (พบจากรีวิวโค้ด 2026-08-02)
  // ประกาศไว้นอก try/catch เพราะ catch block ก็ใช้ (block scope ของ const ใน try เข้าไม่ถึง)
  const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const seq = ++_tsLoadSeq;
  try {
    // marketOverride: ใช้ตอนเปิดจาก modal หุ้น DR (ดู openTearsheetFromModal) — ต้องส่ง
    // market='DR' ให้ backend resolve DR sym เป็น underlying US/HK เอง (DR sym อาจไม่ตรงกับ
    // yf ticker จริง) ต่างจาก _tsMarket ที่เป็นแค่แท็บ UI ปกติ
    const r = await _fetchTimeout(`/api/tearsheet/${marketOverride || _tsMarket}/${encodeURIComponent(sym)}`, 35000,
      'หมดเวลารอข้อมูล (เกิน 35 วิ) — หุ้นตัวนี้อาจอยู่นอกดัชนีหลักและต้องดึงราคาสดจาก Yahoo ครั้งแรก ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _tsLoadSeq) return;   // มีการโหลดหุ้นตัวใหม่แซงระหว่างรอ — ทิ้ง response นี้ ไม่แตะ _tsData/หน้าจอ
    if (d.error) { box.innerHTML = `<div class="empty">${esc(d.error)}</div>`; return; }
    _tsData = d;
    renderTearsheet(d);
  } catch (e) {
    if (seq !== _tsLoadSeq) return;
    box.innerHTML = '<div class="empty" style="color:var(--red)">โหลดไม่สำเร็จ: ' + esc(e.message) + '</div>';
  }
}

function _tsBadge(label, value, color) {
  return `<div style="text-align:center;min-width:64px">
    <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em">${label}</div>
    <div style="font-size:13px;font-weight:700;color:${color || 'var(--text)'}">${value}</div>
  </div>`;
}

// badge ธรรมาภิบาล/ความยั่งยืน (SET.or.th ทางการ) ในหัว Tearsheet — เฉพาะหุ้นไทยที่มีเรตติ้ง
// (ดู PLAN_set_api_expansion.txt งาน #3B) ไม่มีข้อมูล = ไม่แสดง badge เลย (SET ครอบแค่ ~38%
// ของกระดาน — ไม่มีค่า ≠ คะแนนแย่ · ถ้าโชว์ "—" จะดูเหมือนได้คะแนนต่ำ)
function _tsEsgPill(text, vtip, color) {
  return `<span data-vtip="${vtip.replace(/"/g, '&quot;')}" style="display:inline-flex;align-items:center;`
    + `padding:2px 9px;border-radius:11px;background:var(--card2);font-size:11px;font-weight:700;`
    + `cursor:help;white-space:nowrap;color:${color || 'var(--text)'}">${text}</span>`;
}
function _tsEsgBadges(esg) {
  if (!esg) return '';
  const asOf = esg.esg_as_of ? ` · ณ ${esg.esg_as_of}` : '';
  const covNote = '<br><span style="color:var(--text2)">SET ประเมินแค่ ~38% ของหุ้นไทย — '
    + 'บริษัทที่ไม่มี badge นี้คือไม่ได้เข้าร่วมประเมิน ไม่ได้แปลว่าแย่</span>';
  const rankColor = { 4: 'var(--green)', 3: 'var(--green)', 2: 'var(--text)', 1: 'var(--red)' };
  const out = [];
  if (esg.esg_rating) {
    out.push(_tsEsgPill(`ESG ${esg.esg_rating}`,
      `<b>SETESG Rating: ${esg.esg_rating}</b><br>เรตติ้งความยั่งยืนทางการของตลาดหลักทรัพย์ฯ `
      + `(AAA ดีสุด → BBB ต่ำสุดที่แจก)${asOf}${covNote}`,
      rankColor[esg.esg_rank] || 'var(--text)'));
  }
  if (esg.cg_score != null) {
    out.push(_tsEsgPill(`CG ${'★'.repeat(Math.max(0, Math.min(5, esg.cg_score)))}`,
      `<b>CG Score: ${esg.cg_score}/5</b><br>คะแนนการกำกับดูแลกิจการ (บริษัทจดทะเบียน) จาก IOD`
      + `<br><span style="color:var(--text2)">~85% ของบริษัทที่ประเมินได้ 5 เต็ม — บอกได้แค่ว่า `
      + `"ไม่ต่ำ" แยกคุณภาพจริงไม่ได้ ให้ดู SETESG rating แทน</span>`,
      esg.cg_score >= 4 ? 'var(--text)' : 'var(--red)'));
  }
  if (esg.setesg_index) {
    out.push(_tsEsgPill('🌱 SETESG',
      `<b>อยู่ในดัชนี SETESG</b><br>รายชื่อหุ้นยั่งยืนที่ตลาดหลักทรัพย์ฯ คัดเลือก — ผ่านเกณฑ์ ESG `
      + `ขั้นต่ำ + สภาพคล่อง + market cap${asOf}`, 'var(--green)'));
  }
  if (esg.djsi_index) {
    out.push(_tsEsgPill('🌍 DJSI',
      `<b>อยู่ในดัชนี DJSI</b><br>Dow Jones Sustainability Indices — เกณฑ์ความยั่งยืนระดับโลก `
      + `(S&amp;P Global) เข้มกว่า SETESG มาก${asOf}`, 'var(--green)'));
  }
  if (!out.length) return '';
  return `<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-left:auto">${out.join('')}</div>`;
}

function _tsValLabel(label) {
  return { cheap: ['ถูกกว่าปกติ', 'var(--green)'], normal: ['ปกติ', 'var(--text2)'],
           expensive: ['แพงกว่าปกติ', 'var(--red)'] }[label] || ['—', 'var(--text2)'];
}

function _tsValTile(name, v, key) {
  if (!v || v.value == null) {
    return `<div class="card" style="padding:10px 12px;flex:1;min-width:130px">
      <div style="font-size:10px;color:var(--text2)">${name}</div>
      <div style="font-size:18px;font-weight:700;color:var(--text2)">–</div></div>`;
  }
  // v.n = จำนวนไตรมาสที่มีข้อมูลจริง (ประวัติ Finnomena ลึกสุด ~16 ปี ไม่ได้ตัดแค่ 5 ปีตายตัว)
  // แสดงจำนวนปีจริงแทนคำว่า "5 ปี" เดิมที่ hardcode ไว้ผิด (พบจาก feedback ผู้ใช้)
  const yrsText = v.n != null ? `${(v.n / 4).toFixed(1)} ปี` : '5 ปี';
  const pctText = v.percentile != null ? `เทียบตัวเอง ${yrsText}: ${v.percentile}%ile` : '';
  const [lbl, lblColor] = v.percentile != null ? _tsValLabel(v.label) : ['', ''];
  const secMedText = v.sector_median != null ? `กลาง sector ${v.sector_median}` : '';
  // เฉลี่ย/มัธยฐานของตัวเอง (ทั้งประวัติที่มี ไม่ใช่แค่ 5 ปี) — เหมือนที่โชว์ในแถบ
  // "มูลค่าเทียบอดีตตัวเอง" หน้างบการเงิน
  const ownStatText = (v.mean != null || v.median != null)
    ? `เฉลี่ย ${v.mean != null ? v.mean : '—'} · มัธยฐาน ${v.median != null ? v.median : '—'}` : '';
  const valId = key ? ` id="ts-val-${key}"` : '';
  return `<div class="card" style="padding:10px 12px;flex:1;min-width:130px">
    <div style="font-size:10px;color:var(--text2)">${name}</div>
    <div${valId} style="font-size:18px;font-weight:700">${v.value}</div>
    ${lbl ? `<div style="font-size:10.5px;font-weight:600;color:${lblColor}">${lbl}</div>` : ''}
    <div style="font-size:10px;color:var(--text2);margin-top:2px">${pctText}</div>
    ${ownStatText ? `<div style="font-size:10px;color:var(--text2)">${ownStatText}</div>` : ''}
    <div style="font-size:10px;color:var(--text2)">${secMedText}</div>
  </div>`;
}

function renderTearsheet(d) {
  const h = d.header, v = d.valuation, mkt = d.market || 'TH';
  // lite = หุ้น DR ตลาดที่ยังไม่มี price cohort (JP/VN/SG/EU/TW/CN) — งบ/F-Z/DCF/ปันผล/valuation
  // ครบ แต่ RS/เทียบเพื่อน/ข่าว/เอกสาร (TH/US/HK เท่านั้น) ไม่พร้อม -> โชว์ลิงก์ภายนอกแทน
  const lite = !!d.lite, uyf = d.underlying_yf || '';
  const liteBanner = lite ? `
    <div class="card" style="padding:12px 16px;margin-bottom:12px;border-left:3px solid var(--yellow)">
      <div style="font-size:12px;color:var(--text);line-height:1.65">
        ℹ️ หุ้น DR ตลาด <b>${mkt}</b> — ตลาดนี้ยังไม่มีชุดราคาทั้งตลาดให้จัดอันดับ <b>RS</b> และ <b>เทียบเพื่อน</b> (แสดงเป็น “—”)
        แต่ <b>งบการเงิน · F-Score · Z-Score · DCF · ปันผล · Valuation</b> ใช้ได้ครบตามปกติ
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">
        <a class="filter-btn" href="https://finance.yahoo.com/quote/${encodeURIComponent(uyf)}" target="_blank" rel="noopener" style="text-decoration:none;font-size:12px;padding:6px 12px">📊 Yahoo Finance (${uyf}) ↗</a>
        <a class="filter-btn" href="https://www.tradingview.com/chart/?symbol=${yfToTVSym(uyf)}&interval=D" target="_blank" rel="noopener" style="text-decoration:none;font-size:12px;padding:6px 12px">📈 TradingView ↗</a>
      </div>
    </div>` : '';
  const emaBadge = h.above_ema200 == null ? '—'
    : (h.above_ema50 && h.above_ema200 ? '📈 เหนือ 50/200' : h.above_ema200 ? 'เหนือ 200' : h.above_ema50 ? 'เหนือ 50' : '❌ ใต้ทั้งคู่');
  const momColor = h.rs_momentum > 0 ? 'var(--green)' : h.rs_momentum < 0 ? 'var(--red)' : 'var(--text2)';

  const header = `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px">
        <div>
          <div style="font-size:20px;font-weight:800">${h.symbol}
            <span style="font-size:13px;font-weight:400;color:var(--text2)">${(h.name||'').replace(/</g,'&lt;')}</span>
          </div>
          <div style="font-size:12px;color:var(--text2)">${h.sector||'—'}${h.industry && h.industry!==h.sector ? ' · '+h.industry : ''}</div>
        </div>
        <button class="btn-secondary" onclick="closeTsOpenChart('${h.symbol}')">📈 กราฟเต็ม</button>
      </div>
      <div style="display:flex;align-items:baseline;gap:14px;margin:10px 0;flex-wrap:wrap">
        <div style="font-size:28px;font-weight:800">${h.price != null ? h.price.toFixed(2) : '—'}</div>
        <div style="display:flex;gap:12px;flex-wrap:wrap;font-size:12px">
          <span>1D ${pct(h.ret_1d)}</span><span>1W ${pct(h.ret_1w)}</span><span>1M ${pct(h.ret_1m)}</span>
          <span>3M ${pct(h.ret_3m)}</span><span>1Y ${pct(h.ret_1y)}</span><span>YTD ${pct(h.ret_ytd)}</span>
        </div>
      </div>
      <canvas id="ts-spark" width="600" height="60" style="width:100%;height:60px;display:block;margin-bottom:10px"></canvas>
      <div style="display:flex;gap:16px;flex-wrap:wrap;padding-top:8px;border-top:1px solid var(--border)">
        ${_tsBadge('RS', h.rs_score ?? '—', h.rs_score == null ? 'var(--text2)' : h.rs_score >= 80 ? 'var(--green)' : h.rs_score < 40 ? 'var(--red)' : 'var(--text)')}
        ${_tsBadge('Stage', stageBadge(h.stage), '')}
        ${_tsBadge('จาก High52', h.pct_off_high52 != null ? h.pct_off_high52.toFixed(1)+'%' : '—', h.pct_off_high52 == null ? 'var(--text2)' : h.pct_off_high52 >= -5 ? 'var(--green)' : h.pct_off_high52 <= -30 ? 'var(--red)' : 'var(--text)')}
        ${_tsBadge('Momentum', h.rs_momentum ?? '—', momColor)}
        ${_tsBadge('EMA', emaBadge, '')}
        ${_tsBadge('ATR%', h.atr14_pct ?? '—', '')}
        ${_tsEsgBadges(d.esg)}
      </div>
    </div>`;

  const valuation = `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:10px">💰 Valuation Snapshot
        <span id="ts-val-live-price" style="font-weight:400;font-size:11px;color:var(--text2)"></span>
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        ${_tsValTile('PE', v.pe, 'pe')}${_tsValTile('PBV', v.pbv, 'pbv')}${_tsValTile('P/S', v.ps, 'ps')}${_tsValTile('EV/EBITDA', v.ev_ebitda, 'ev_ebitda')}${_tsValTile('ปันผล%', v.div_yield)}
      </div>
    </div>`;

  const peScenarioHtml = _tsPeScenarioHtml(d);
  const pbvScenarioHtml = _tsPbvScenarioHtml(d);
  const finExtraHtml = `<div id="ts-fin-extra" style="margin-bottom:12px"></div>`;

  const dcfHtml = _tsDcfHtml(d.dcf, h.price);

  // การ์ด "🎯 ฉันทามตินักวิเคราะห์" (Yahoo: ราคาเป้าหมาย + Buy/Hold/Sell) — โหลด async
  // แยกผ่าน /api/analyst-consensus (DB, ไม่ยิง Yahoo สด) · หุ้นไทย + DR underlying US/HK
  // เท่านั้น (JP/lite ไม่มีข้อมูล sync) · ไม่มี coverage = ไม่โชว์การ์ด (เหมือน finHealthMini)
  const analystHtml = (lite || mkt === 'JP') ? '' : `<div id="ts-analyst-consensus" style="margin-bottom:12px"></div>`;

  const quality = _tsQualityHtml(d.quality, h.symbol);
  const dividend = _tsDividendHtml(d.dividend, h.symbol);

  // การ์ดย่อ SET Financial Health Check — หุ้นไทยเท่านั้น (ดู
  // PLAN_set_api_expansion.txt งาน #5B) โหลด async แยก ไม่บล็อค render หลัก
  const finHealthMini = mkt !== 'TH' ? '' : `<div id="ts-fin-health-mini" style="margin-bottom:12px"></div>`;

  // NVDR/insider (ร.59/246-2)/short sales เป็นข้อมูลเฉพาะตลาดหุ้นไทย — US/HK ไม่มีแนวคิดนี้
  const flow = mkt !== 'TH' ? '' : `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:10px">💸 เงินทุน & คนวงใน</div>
      <div id="ts-flow-summary" style="margin-bottom:10px"></div>
      <div style="display:flex;gap:16px;flex-wrap:wrap">
        <div style="flex:1;min-width:220px">
          <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:6px">ผู้บริหาร/ผู้ถือใหญ่ 180 วัน</div>
          <div id="ts-insider"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
        </div>
        <div style="flex:1;min-width:220px">
          <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:6px">Short Sales</div>
          <div id="ts-short"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
        </div>
        <div style="flex:1;min-width:220px">
          <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:6px">NVDR</div>
          <div id="ts-nvdr"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
        </div>
        <div style="flex:1;min-width:220px">
          <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:6px">ห้องต่างชาติ
            <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:270px">
              <strong>โควตาต่างชาติ (Foreign Room)</strong><br>
              กฎหมายไทยจำกัดสัดส่วนที่ต่างชาติถือได้ (ปกติ 49% บางกลุ่ม เช่น สื่อสาร/ธนาคาร ต่ำกว่านั้น)<hr>
              <b>ใกล้เต็ม = อ่านยังไง</b><br>
              ต่างชาติที่อยากซื้อเพิ่มต้องไปซื้อ NVDR แทน → NVDR มักซื้อขายแพงกว่าหุ้นปกติ (premium)<br>
              ตีความได้ 2 ทาง: ความต้องการต่างชาติสูง (บวก) หรือแรงซื้อต่างชาติชนเพดานแล้วหมดแรงหนุน (ลบ)<br>
              <span style="color:var(--text2)">ดูคู่กับ NVDR% ทางซ้าย — NVDR สูง + ห้องต่างชาติใกล้เต็ม = ต่างชาติอยากได้แต่ซื้อตรงไม่ได้แล้ว</span>
            </div></span>
          </div>
          <div id="ts-foreign-room"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
        </div>
      </div>
    </div>`;

  // ผู้ถือหุ้นใหญ่ + free float (SET.or.th ทางการ) — หุ้นไทยล้วน (ดู
  // PLAN_set_api_expansion.txt งาน #1) ต้องเคยกด sync ในหน้า Screener+ ก่อนถึงจะมีค่า
  const ownership = mkt !== 'TH' ? '' : `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:10px">🏛 โครงสร้างผู้ถือหุ้น
        <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:260px">
          ข้อมูลทางการจาก SET.or.th (ผู้ถือหุ้นใหญ่ 10 อันดับ + free float) ณ วันปิดสมุดทะเบียนล่าสุด — ไม่ใช่รายวัน อัพเดทเมื่อมี XM/XD ครั้งถัดไป
        </div></span>
      </div>
      <div id="ts-ownership"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
    </div>`;

  const seasonality = `<div id="ts-lts" style="margin-bottom:12px"></div>`;

  // ข่าว/เอกสารทางการ มีเฉพาะ TH/US/HK (endpoint/ลิงก์ผูกตลาดพวกนี้) — ตลาด lite ข้ามไป
  // (banner ด้านบนมีลิงก์ Yahoo/TradingView ให้เข้าไปอ่านต่อแล้ว)
  const news = lite ? '' : `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:13px;font-weight:700">📰 ข่าวล่าสุด</div>
        <a href="#" onclick="_tsGoNews('${h.symbol}');return false" style="font-size:11px;color:var(--blue)">ดูข่าวทั้งหมด →</a>
      </div>
      <div id="ts-news"><div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลด...</div></div>
    </div>`;

  // JP: หน้า Filings แบบเต็มยังไม่มีแท็บ JP (fil-tab-th/us/hk เท่านั้น) — ใช้ _filLinksJP
  // สำหรับลิงก์ในการ์ดนี้ได้ปกติ (ไม่ต้องพึ่งหน้า Filings) แต่ซ่อนลิงก์ "เปิดหน้ารายงานทางการ →"
  // ที่พาไปหน้านั้นไปก่อน (เดิม fallback เป็น _filLinksTH ผิดตลาด ขึ้นลิงก์ SET.or.th ของหุ้นญี่ปุ่น)
  const filLinksFn = mkt === 'US' ? _filLinksUS : mkt === 'HK' ? _filLinksHK : mkt === 'JP' ? _filLinksJP : _filLinksTH;
  const docs = lite ? '' : `
    <div class="card" style="padding:16px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:13px;font-weight:700">📑 เอกสารทางการ</div>
        ${mkt !== 'JP' ? `<a href="#" onclick="_tsGoFilings('${h.symbol}');return false" style="font-size:11px;color:var(--blue)">เปิดหน้ารายงานทางการ →</a>` : ''}
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">
        ${filLinksFn(h.symbol)[0].links.map(l => _filLinkAnchorHtml(l, '6px 12px', '12px')).join('')}
      </div>
      <button class="btn-secondary" style="font-size:11.5px" onclick="copyFilPrompt('${_escJsAttr(h.symbol)}','${_escJsAttr(mkt)}','ts-fil-copy-note')">📋 คัดลอก Prompt วิเคราะห์ 13 ข้อ</button>
      <span id="ts-fil-copy-note" style="font-size:11px;color:var(--green);margin-left:8px"></span>
    </div>`;

  const inWl = watchlist.includes(_tsWlKey(h.symbol));
  // Watchlist/ปฏิทิน ยังไม่รองรับ prefix "JP:" เลย (ดู renderWatchlist/_calResolveWatchlist —
  // ไม่มี branch JP) — ซ่อนปุ่มเพิ่ม Watchlist ของตลาด JP ไปก่อน กันสร้าง entry ที่หน้าอื่นแสดง
  // ผลไม่ได้ (จะกลายเป็นแถว "ไม่พบข้อมูล" ถาวร) จนกว่าจะเพิ่ม branch JP ให้ครบวงจร
  const wlSupported = mkt !== 'JP';
  // ปุ่ม _tsGoNews/_tsGoFilings/_tsGoPeer/_tsGoDividends พาไปหน้า TH/US/HK ที่ไม่รู้จักหุ้นตลาด
  // lite (peer ตอบ 501, ข่าว/เอกสาร/ปันผลผูกตลาดพวกนั้น) — ตัดออก เหลือแค่กราฟ DR + Watchlist
  const actionBar = lite ? `
    <div class="card" style="padding:12px 16px;margin-bottom:12px">
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn-secondary" style="font-size:12.5px" onclick="closeTsOpenChart('${h.symbol}')">📈 กราฟเต็ม</button>
      </div>
    </div>` : `
    <div class="card" style="padding:12px 16px;margin-bottom:12px">
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        ${wlSupported ? `<button class="btn-secondary" id="ts-wl-btn" style="font-size:12.5px" onclick="_tsToggleWl('${h.symbol}')">${inWl ? '⭐ อยู่ใน Watchlist แล้ว' : '☆ เพิ่มเข้า Watchlist'}</button>` : ''}
        <button class="btn-secondary" style="font-size:12.5px" onclick="closeTsOpenChart('${h.symbol}')">📈 กราฟเต็ม</button>
        <button class="btn-secondary" style="font-size:12.5px" onclick="_tsGoNews('${h.symbol}')">📰 ข่าว</button>
        ${mkt !== 'JP' ? `<button class="btn-secondary" style="font-size:12.5px" onclick="_tsGoFilings('${h.symbol}')">📑 เอกสาร</button>` : ''}
        <button class="btn-secondary" style="font-size:12.5px" onclick="_tsGoPeer('${h.symbol}')">🆚 เทียบเพื่อน</button>
        <button class="btn-secondary" style="font-size:12.5px" onclick="_tsGoDividends('${h.symbol}')">💵 ปันผล</button>
        <button class="btn-secondary" style="font-size:12.5px" onclick="_tsGoFin('${h.symbol}')">🧾 เมนูงบการเงิน</button>
      </div>
    </div>`;

  // ปฏิทิน/price analytics ผูกกับ pipeline ของ TH/US/HK — ตลาด lite ไม่มี ข้ามไป
  const calendarWeek = lite ? '' : `<div id="ts-calendar"></div>`;

  const altValHtml = _tsAltValHtml(d);

  document.getElementById('ts-body').innerHTML = header + liteBanner + calendarWeek + actionBar + valuation + peScenarioHtml + pbvScenarioHtml + finExtraHtml + dcfHtml + analystHtml + altValHtml + quality + dividend + finHealthMini + flow + ownership + seasonality + news + docs;
  requestAnimationFrame(() => {
    const canvas = document.getElementById('ts-spark');
    if (canvas && h.sparkline) drawSparkline(canvas, h.sparkline, h.ret_1y);
  });
  if (mkt === 'TH') {
    _tsLoadFlow(h.symbol); _tsLoadOwnership(h.symbol);
    // SET.or.th Financial Health Check ไม่ครอบกลุ่มธนาคาร/เงินทุน/ประกัน (404 เสมอ เหมือน Z-Score)
    // — ข้ามไม่ยิงเลยสำหรับหุ้นกลุ่มการเงิน กัน 404 รก console ทั้งที่การ์ดถูกซ่อนอยู่แล้ว
    if (!d.dcf?.is_financial_sector) _tsLoadFinHealthMini(h.symbol, d.quality?.cash_cycle);
  }
  if (!lite) {
    _tsLoadCalendarWeek(h.symbol, mkt);
    _loadPriceAnalytics(h.symbol, 'ts-lts', () => _tsData?.symbol === h.symbol, mkt !== 'TH' ? h.symbol : null);
    _tsLoadNews(h.symbol);
  }
  _tsPeScenarioRecalc();
  _tsPbvScenarioRecalc();
  _tsDcfRecalc();
  _tsDcfModelRecalc();
  _tsAltValRecalc();
  _tsLoadLiveValuation(d, h);
  _tsLoadFinExtras(d, h, mkt);
  // หลัง _tsDcfRecalc() — _tsDcfBaseFairValue พร้อมให้การ์ดเอาไปเทียบกับราคาเป้าหมาย
  if (!lite && mkt !== 'JP') _tsLoadAnalystConsensus(d, h, mkt);
}

// ---------- การ์ด 🎯 ฉันทามตินักวิเคราะห์ (Yahoo) ----------
// ราคาเป้าหมาย mean/high/low + upside% vs ราคาปัจจุบัน, แถบ Buy/Hold/Sell, จำนวนนักวิเคราะห์,
// ประมาณการโต EPS ปีหน้า + เทียบกับ Fair Value (DCF Base) ที่เราคำนวณเอง — ข้อมูลจาก DB
// (sync พร้อมงบการเงิน) ไม่ยิง Yahoo สด · coverage หุ้นไทย ~40% (เอียง cap ใหญ่), DR
// underlying US/HK เกือบ 100% · ไม่มีข้อมูล = ซ่อนการ์ด (ไม่ใช่ error)
async function _tsLoadAnalystConsensus(d, h, mkt) {
  const box = document.getElementById('ts-analyst-consensus');
  if (!box) return;
  // market + symbol ที่ตรงกับ key ใน DB: TH ตรงๆ · DR ที่ resolve เป็น US/HK แล้ว ใช้ h.symbol
  // (HK ตัด suffix .HK ให้ backend เพราะ DB เก็บ bare — เหมือน _tsLoadFinExtras)
  let acMkt = mkt, acSym = h.symbol;
  if (mkt === 'HK') acSym = h.symbol.replace(/\.HK$/i, '');
  else if (mkt !== 'TH' && mkt !== 'US') { box.innerHTML = ''; return; }
  try {
    const r = await _fetchTimeout(`/api/analyst-consensus/${encodeURIComponent(acSym)}?market=${acMkt}`, 8000);
    if (_tsData?.symbol !== d.symbol) return;   // เปลี่ยนหุ้นไปแล้วระหว่างรอโหลด
    if (!r.ok) { box.innerHTML = ''; return; }  // 404 = ไม่มีนักวิเคราะห์ตาม/ยังไม่ sync → ซ่อนเงียบๆ
    const a = await r.json();
    if (_tsData?.symbol !== d.symbol) return;
    box.innerHTML = _tsAnalystConsensusHtml(a, h.price);
  } catch (e) {
    if (_tsData?.symbol === d.symbol) box.innerHTML = '';
  }
}

function _tsAnalystConsensusHtml(a, price) {
  const cur = a.currency || '';
  const fmt = v => v == null ? '—' : v.toLocaleString(undefined, { maximumFractionDigits: 2 });
  // upside เทียบราคาปัจจุบันจริง (สดจากหน้า) ไม่ใช่ target_upside_pct ที่อิง price_at_fetch เก่า
  const up = (a.target_mean != null && price) ? (a.target_mean / price - 1) * 100 : null;
  const upClr = up == null ? 'var(--text2)' : up > 0 ? 'var(--green)' : up < 0 ? 'var(--red)' : 'var(--text)';
  const buy = (a.rec_strong_buy || 0) + (a.rec_buy || 0);
  const hold = a.rec_hold || 0;
  const sell = (a.rec_sell || 0) + (a.rec_strong_sell || 0);
  // ตัวหารแถบ = ผลรวม bucket จริง ไม่ใช่ a.rec_total (Yahoo numberOfAnalystOpinions มักไม่ตรงกับ
  // strong_buy+buy+hold+sell+strong_sell — ถ้าใช้ rec_total แถบจะไม่เต็มกรอบหรือล้นกรอบ)
  const recSum = buy + hold + sell;
  const seg = (n, clr) => recSum && n ? `<div style="width:${n / recSum * 100}%;background:${clr}"></div>` : '';
  const recBar = recSum ? `
    <div style="display:flex;height:10px;border-radius:5px;overflow:hidden;margin:6px 0 4px">
      ${seg(buy, 'var(--green)')}${seg(hold, '#e8a33d')}${seg(sell, 'var(--red)')}
    </div>
    <div style="font-size:10.5px;color:var(--text2)">
      <span style="color:var(--green)">ซื้อ ${buy}</span> ·
      <span style="color:#e8a33d">ถือ ${hold}</span> ·
      <span style="color:var(--red)">ขาย ${sell}</span>
      ${a.rec_mean != null ? ` · คะแนนเฉลี่ย ${a.rec_mean.toFixed(2)} <span style="color:var(--text2)">(1=ซื้อมาก…5=ขายมาก)</span>` : ''}
    </div>` : '<div style="font-size:10.5px;color:var(--text2)">ยังไม่มีคำแนะนำ Buy/Hold/Sell — มีเฉพาะราคาเป้าหมาย</div>';

  // เทียบกับ Fair Value (DCF Base) ของเราเอง — snapshot จาก _tsDcfRecalc() ตอน render
  let dcfCmp = '';
  if (_tsDcfBaseFairValue != null && _tsDcfBaseFairValue > 0 && a.target_mean != null) {
    const diff = (a.target_mean / _tsDcfBaseFairValue - 1) * 100;
    const [txt, clr] = Math.abs(diff) <= 10 ? ['ใกล้เคียงกัน', 'var(--text)']
      : diff > 0 ? ['นักวิเคราะห์มองสูงกว่า', 'var(--green)']
      : ['นักวิเคราะห์มองต่ำกว่า', 'var(--red)'];
    dcfCmp = `<div style="font-size:11px;margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">
      เทียบ Fair Value (DCF ฉาก Base) ของเรา ${_tsDcfBaseFairValue.toFixed(2)} :
      <span style="color:${clr};font-weight:600">${txt} ${diff > 0 ? '+' : ''}${diff.toFixed(0)}%</span></div>`;
  }

  const tgt = (lbl, v) => `<div style="text-align:center;min-width:70px">
    <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em">${lbl}</div>
    <div style="font-size:15px;font-weight:700">${fmt(v)}</div></div>`;

  const growthBits = [];
  if (a.eps_growth_this_y != null) growthBits.push(`โต EPS ปีนี้ ${a.eps_growth_this_y > 0 ? '+' : ''}${a.eps_growth_this_y.toFixed(1)}%`);
  if (a.eps_growth_next_y != null) growthBits.push(`ปีหน้า ${a.eps_growth_next_y > 0 ? '+' : ''}${a.eps_growth_next_y.toFixed(1)}%`);
  if (a.rev_growth_next_y != null) growthBits.push(`รายได้ปีหน้า ${a.rev_growth_next_y > 0 ? '+' : ''}${a.rev_growth_next_y.toFixed(1)}%`);
  if (a.ltg_pct != null) growthBits.push(`ระยะยาว ${a.ltg_pct.toFixed(1)}%`);

  const syncNote = a.synced_at ? ` · ข้อมูล ${a.synced_at.slice(0, 10)}` : '';

  // ── โครงสร้างผู้ถือหุ้น (Yahoo: major_holders / institutional_holders / insider_purchases) ──
  // เต็มเฉพาะ underlying US/HK ของ DR — หุ้นไทยแทบว่าง (sync_th ไม่ดึงกลุ่มนี้) · คนละแหล่งกับ
  // เมนู Insider ที่ใช้ แบบ 59/246-2 ของ ก.ล.ต. ไทย
  const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const grp = n => n == null ? '—' : Math.round(n).toLocaleString();
  // กรองรายที่ถือ ~0% ทิ้ง (Yahoo ยัด filer จิ๋วจาก US มาให้หุ้น HK เต็มไปหมด ไม่มีนัยยะ)
  const ti = (Array.isArray(a.top_institutions) ? a.top_institutions : [])
    .filter(x => x.pct != null && x.pct >= 0.05);
  const netI = a.insider_net_6m, buyI = a.insider_buy_6m, sellI = a.insider_sell_6m;
  const hasInsider = !!buyI || !!sellI || !!netI;
  const hasHolders = a.institutions_pct_held != null || ti.length || hasInsider;
  let holdersHtml = '';
  if (hasHolders) {
    const ownBits = [];
    if (a.institutions_pct_held != null) ownBits.push(`สถาบันถือ <b>${a.institutions_pct_held.toFixed(1)}%</b>`);
    if (a.insiders_pct_held != null) ownBits.push(`ผู้บริหาร/insider <b>${a.insiders_pct_held.toFixed(2)}%</b>`);
    if (a.institutions_count != null) ownBits.push(`${grp(a.institutions_count)} สถาบัน`);

    const shown = ti.slice(0, 5);
    const rows = shown.map(x => {
      const ch = x.pct_change;
      const chTxt = ch == null || ch === 0 ? '' :
        ` <span style="color:${ch > 0 ? 'var(--green)' : 'var(--red)'};font-size:9.5px">${ch > 0 ? '▲' : '▼'}${Math.abs(ch).toFixed(1)}%</span>`;
      return `<div style="display:flex;justify-content:space-between;gap:8px;font-size:10.5px;padding:2px 0">
        <span style="color:var(--text2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(x.holder)}</span>
        <span style="white-space:nowrap">${x.pct != null ? x.pct.toFixed(2) + '%' : '—'}${chTxt}</span></div>`;
    }).join('');

    const insiderLine = hasInsider ? `
      <div style="font-size:10.5px;color:var(--text2);margin-top:6px">Insider 6 เดือน:
        ซื้อ ${grp(buyI)} · ขาย ${grp(sellI)}
        ${netI != null ? `· สุทธิ <span style="color:${netI > 0 ? 'var(--green)' : netI < 0 ? 'var(--red)' : 'var(--text)'};font-weight:600">${netI > 0 ? '+' : ''}${grp(netI)}</span> หุ้น` : ''}</div>` : '';

    holdersHtml = `<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">
      <div style="font-size:11.5px;font-weight:700;margin-bottom:3px">🏛 โครงสร้างผู้ถือหุ้น
        <span style="font-weight:400;font-size:10px;color:var(--text2)">Yahoo${a.holders_synced_at ? ` · ${a.holders_synced_at.slice(0, 10)}` : ''}</span></div>
      ${ownBits.length ? `<div style="font-size:10.5px;color:var(--text2)">${ownBits.join(' · ')}</div>` : ''}
      ${rows ? `<div style="margin-top:4px">${rows}
        <div style="font-size:9px;color:var(--text2);margin-top:2px">สถาบันถือรายใหญ่สุด ${shown.length} อันดับ${ti.length > shown.length ? ` (จาก ${ti.length})` : ''} — รายงานถือครองล่าสุด</div></div>` : ''}
      ${insiderLine}
    </div>`;
  }

  return `<div class="card" style="padding:16px">
    <div style="font-size:13px;font-weight:700;margin-bottom:2px">🎯 ฉันทามตินักวิเคราะห์
      <span style="font-weight:400;font-size:11px;color:var(--text2)">Yahoo${a.analyst_count ? ` · ${a.analyst_count} ราย` : ''}${syncNote}</span></div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px">รวบรวมราคาเป้าหมาย + คำแนะนำจากนักวิเคราะห์ที่ติดตามหุ้นตัวนี้ — ไม่ใช่คำแนะนำซื้อ/ขายจากเรา</div>
    ${a.target_mean != null ? `
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;margin-bottom:6px">
      ${tgt('เป้าต่ำ', a.target_low)}${tgt('เป้าเฉลี่ย', a.target_mean)}${tgt('เป้าสูง', a.target_high)}
      <div style="min-width:90px">
        <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em">Upside vs ราคาปัจจุบัน</div>
        <div style="font-size:15px;font-weight:700;color:${upClr}">${up == null ? '—' : (up > 0 ? '+' : '') + up.toFixed(1) + '%'}</div>
        <div style="font-size:9.5px;color:var(--text2)">ราคา ${price != null ? price.toFixed(2) : '—'} ${cur}</div>
      </div>
    </div>` : '<div style="font-size:11.5px;color:var(--text2);margin-bottom:6px">ไม่มีราคาเป้าหมาย — มีเฉพาะคำแนะนำ Buy/Hold/Sell</div>'}
    ${recBar}
    ${growthBits.length ? `<div style="font-size:10.5px;color:var(--text2);margin-top:6px">ประมาณการนักวิเคราะห์: ${growthBits.join(' · ')}</div>` : ''}
    ${holdersHtml}
    ${dcfCmp}
  </div>`;
}

// ---------- Ratios รายไตรมาส + Earnings History รายปี + PE band (Finnomena) — reuse ฟังก์ชัน
// เดียวกับหน้างบการเงิน/popup กราฟหุ้น (_finTrendSection/_finFullTable/_loadLiveValuationBand)
// ไม่มี Finnomena coverage สำหรับ JP/lite (DR ตลาดที่ไม่มี cohort) — ข้ามไปเงียบๆ
function _tsLoadFinExtras(d, h, mkt) {
  const box = document.getElementById('ts-fin-extra');
  if (!box) return;
  box.innerHTML = '';
  if (d.lite || mkt === 'JP') return;
  const sym = h.symbol;
  let qs = '', fetchSym = sym;
  if (mkt === 'TH') { qs = ''; }
  else if (mkt === 'US') { qs = '&is_dr=1&market=US'; }
  else if (mkt === 'HK') { qs = '&is_dr=1&market=HK'; fetchSym = sym.replace(/\.HK$/i, ''); }
  else return;
  box.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px">กำลังโหลดงบการเงินเพิ่มเติม...</div>';
  _fetchTimeout(`/api/financials-full/${encodeURIComponent(fetchSym)}?source=finnomena_q${qs}`, 30000)
    .then(r => r.json())
    .then(fd => {
      if (_tsData?.symbol !== d.symbol) return;   // เปลี่ยนหุ้นไปแล้วระหว่างรอโหลด
      if (fd.error) { box.innerHTML = ''; return; }
      box.innerHTML = _finTrendSection(fd, 'finnomena_q', 'ts-') + '<div id="ts-ratios-annual"></div>' + _tsEarningsHistoryHtml(fd);
      requestAnimationFrame(() => _drawFinTrendCharts(fd, 'ts-'));
      const isDr = mkt !== 'TH';
      _loadLiveValuationBand(fd, isDr, mkt === 'TH' ? null : mkt, 'ts-', () => _tsData?.symbol === d.symbol);
      _tsApplyPeBandDefaults(fd);
      _tsApplyPbvBandDefaults(fd);
      _tsLoadAnnualRatios(fetchSym, qs, d.symbol);
    })
    .catch(() => { box.innerHTML = ''; });
}

// อัตราส่วนการเงิน (Ratios) — รายปี (finnomena_y, รวมจากไตรมาสฝั่ง backend) แทนรายไตรมาสเดิม
// margin/ROE/ROA คำนวณใหม่จากยอดรวมทั้งปี (แม่นกว่าเอา Q4 เดี่ยวๆ มาโชว์ — ดู
// build_annual_from_quarterly ฝั่ง backend) ส่วน D/E และ Cash Cycle ใช้ค่า ณ สิ้นปี (Q4)
// ยิงแยกจาก finnomena_q ด้านบน (คนละ endpoint) ไม่บล็อกกราฟ/band ที่ต้องใช้ข้อมูลรายไตรมาส
function _tsLoadAnnualRatios(fetchSym, qs, staleGuardSymbol) {
  const box = document.getElementById('ts-ratios-annual');
  if (!box) return;
  _fetchTimeout(`/api/financials-full/${encodeURIComponent(fetchSym)}?source=finnomena_y${qs}`, 30000)
    .then(r => r.json())
    .then(fdY => {
      if (_tsData?.symbol !== staleGuardSymbol) return;   // เปลี่ยนหุ้นไปแล้วระหว่างรอโหลด
      if (fdY.error) { box.innerHTML = ''; return; }
      const rat = fdY.ratios || {};
      const allDatesSet = new Set();
      Object.values(rat).forEach(row => Object.keys(row).forEach(k => allDatesSet.add(k)));
      const allColsFull = [...allDatesSet].sort();
      if (!allColsFull.length) { box.innerHTML = ''; return; }
      const cols = allColsFull.slice(-10);
      const colLabels = cols.map(c => c.slice(0, 4));
      box.innerHTML = _finFullTable('📐 อัตราส่วนการเงิน (Ratios รายปี)', cols, colLabels, FIN_FINN_RATIO_GROUP, null,
        (key, c) => (rat[key] || {})[c], () => false, true, null, false, 1, true, allColsFull);
    })
    .catch(() => { box.innerHTML = ''; });
}

// Base/Bear/Bull PE เริ่มต้นจากสถิติ PE ย้อนหลังจริง (มัธยฐาน/ต่ำสุด/สูงสุด หลัง winsorize
// ตัดขอบสุดโต่ง — เหมือนแถบ "มูลค่าเทียบอดีตตัวเอง" ด้านบน) แทนที่ current PE ±25% เดิม
// (ค่าเริ่มต้นหยาบตอนยังไม่มีข้อมูลย้อนหลัง) — เขียนทับเฉพาะตอนโหลดข้อมูล Finnomena สำเร็จ
// ครั้งแรกเท่านั้น (มาถึงหลัง initial render ไม่กี่ร้อย ms ปกติผู้ใช้ยังไม่ทันแก้ค่าเอง)
function _tsApplyPeBandDefaults(fd) {
  const baseEl = document.getElementById('ts-pe-base'), bearEl = document.getElementById('ts-pe-bear'),
        bullEl = document.getElementById('ts-pe-bull'), noteEl = document.getElementById('ts-pe-hist-note');
  if (!baseEl || !bearEl || !bullEl) return;
  const inc = fd.income || {}, val = fd.valuation || {};
  const pe = _annualPeSeries(inc['Basic EPS'], val['Close']);
  const vals = _winsorize(pe.map(o => o.v).filter(v => v > 0)).sort((a, b) => a - b);
  if (vals.length < 5) return;
  const lo = vals[0], hi = vals[vals.length - 1];
  const q = p => vals[Math.min(vals.length - 1, Math.floor(p * (vals.length - 1)))];
  const med = q(0.5);
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  baseEl.value = med.toFixed(1);
  bearEl.value = lo.toFixed(1);
  bullEl.value = hi.toFixed(1);
  if (noteEl) noteEl.textContent = `อิงสถิติ PE รายปีย้อนหลัง (ตัดขอบสุดโต่ง): เฉลี่ย ${mean.toFixed(1)} · มัธยฐาน ${med.toFixed(1)} · ต่ำสุด ${lo.toFixed(1)} · สูงสุด ${hi.toFixed(1)} — ใช้เป็นค่าเริ่มต้น Base/Bear/Bull ด้านบน (แก้เองได้)`;
  if (_tsPeDefaults) { _tsPeDefaults.base = med; _tsPeDefaults.bear = lo; _tsPeDefaults.bull = hi; }
  _tsPeScenarioRecalc();
}

// เหมือน _tsApplyPeBandDefaults ทุกประการ แต่ใช้ field PBV ดิบของ Finnomena ตรงๆ (ไม่ต้องคำนวณเอง
// เหมือน PE — ดู _finValuationSeries) เป็นรายไตรมาส ไม่ใช่รายปี เพราะ PBV ไม่มีปัญหา EPS ไตรมาสเดียว
// ทำให้ค่าเพี้ยนแบบ PE (ดูคอมเมนต์ที่ _finTrendSectionImpl)
function _tsApplyPbvBandDefaults(fd) {
  const baseEl = document.getElementById('ts-pbv-base'), bearEl = document.getElementById('ts-pbv-bear'),
        bullEl = document.getElementById('ts-pbv-bull'), noteEl = document.getElementById('ts-pbv-hist-note');
  if (!baseEl || !bearEl || !bullEl) return;
  const pbvSeries = _finSeries((fd.valuation || {})['PBV']);
  const vals = _winsorize(pbvSeries.map(o => o.v).filter(v => v > 0)).sort((a, b) => a - b);
  if (vals.length < 8) return;
  const lo = vals[0], hi = vals[vals.length - 1];
  const q = p => vals[Math.min(vals.length - 1, Math.floor(p * (vals.length - 1)))];
  const med = q(0.5);
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  baseEl.value = med.toFixed(2);
  bearEl.value = lo.toFixed(2);
  bullEl.value = hi.toFixed(2);
  if (noteEl) noteEl.textContent = `อิงสถิติ PBV รายไตรมาสย้อนหลัง (ตัดขอบสุดโต่ง): เฉลี่ย ${mean.toFixed(2)} · มัธยฐาน ${med.toFixed(2)} · ต่ำสุด ${lo.toFixed(2)} · สูงสุด ${hi.toFixed(2)} — ใช้เป็นค่าเริ่มต้น Base/Bear/Bull ด้านบน (แก้เองได้)`;
  if (_tsPbvDefaults) { _tsPbvDefaults.base = med; _tsPbvDefaults.bear = lo; _tsPbvDefaults.bull = hi; }
  _tsPbvScenarioRecalc();
}

// Earnings History รายปี (EPS/NP/ROE/NPM) — รวมจากไตรมาส Finnomena เฉพาะปีที่ครบ 4 ไตรมาสจริง
// (เหตุผลเดียวกับ _annualPeSeries ด้านบน) ROE ใช้ค่า ณ ไตรมาสสุดท้ายของปี (Finnomena เก็บเป็น
// TTM อยู่แล้ว ไม่ใช่ค่าต่อไตรมาสเดี่ยว) ส่วน NPM คำนวณจากผลรวมทั้งปีเอง (กำไรสุทธิ÷รายได้)
function _tsFinAnnualEarnings(fd) {
  const inc = fd.income || {}, rat = fd.ratios || {};
  const epsItems = _finSeries(inc['Basic EPS']);
  const niItems = _finSeries(inc['Net Income']);
  const revItems = _finSeries(inc['Total Revenue']);
  const roeItems = _finSeries(rat['ROE']);
  if (epsItems.length < 4 && niItems.length < 4) return [];
  const byYear = {};
  const group = (items, field) => items.forEach(o => {
    const y = o.d.slice(0, 4);
    byYear[y] = byYear[y] || {};
    (byYear[y][field] = byYear[y][field] || []).push(o);
  });
  group(epsItems, 'eps'); group(niItems, 'ni'); group(revItems, 'rev'); group(roeItems, 'roe');
  const years = Object.keys(byYear).sort().reverse().slice(0, 5);
  const sum = arr => arr.reduce((a, o) => a + o.v, 0);
  return years.map(y => {
    const g = byYear[y];
    const eps = (g.eps && g.eps.length === 4) ? sum(g.eps) : null;
    const np = (g.ni && g.ni.length === 4) ? sum(g.ni) : null;
    const rev = (g.rev && g.rev.length === 4) ? sum(g.rev) : null;
    const npm = (np != null && rev) ? np / rev * 100 : null;
    const roe = (g.roe && g.roe.length) ? g.roe[g.roe.length - 1].v : null;
    return { year: y, eps, np, roe, npm };
  }).filter(r => r.eps != null || r.np != null);
}

function _tsEarningsHistoryHtml(fd) {
  const rows = _tsFinAnnualEarnings(fd);
  if (!rows.length) return '';
  const fmtNp = v => v == null ? '—' : Math.round(v / 1e6).toLocaleString();
  const body = rows.map(r => `<tr><td style="font-size:12px;padding:5px 8px">${r.year}</td>
    <td class="r" style="font-size:12px">${r.eps != null ? r.eps.toFixed(2) : '—'}</td>
    <td class="r" style="font-size:12px">${fmtNp(r.np)}</td>
    <td class="r" style="font-size:12px">${r.roe != null ? (r.roe >= 0 ? '+' : '') + r.roe.toFixed(1) + '%' : '—'}</td>
    <td class="r" style="font-size:12px">${r.npm != null ? (r.npm >= 0 ? '+' : '') + r.npm.toFixed(1) + '%' : '—'}</td></tr>`).join('');
  return `<div style="margin-top:16px">
    <div style="font-size:13px;font-weight:600;color:var(--blue);margin-bottom:6px">📑 Earnings History (รายปี)</div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:4px">รวมจากงบไตรมาส Finnomena เฉพาะปีที่ครบ 4 ไตรมาสจริง (ปีปัจจุบัน/ปีไม่ครบข้าม) · NP หน่วยล้าน (สกุลเงินของหุ้น) · ROE = ค่า ณ ไตรมาสสุดท้ายของปี (TTM) · NPM = กำไรสุทธิรวมปี ÷ รายได้รวมปี</div>
    <div style="overflow-x:auto"><table class="tbl" style="min-width:320px">
      <thead><tr><th>ปี</th><th class="r">EPS</th><th class="r">NP (ล้าน)</th><th class="r">ROE</th><th class="r">NPM</th></tr></thead>
      <tbody>${body}</tbody></table></div>
  </div>`;
}

// ---------- PE Valuation (Bear/Base/Bull) — Forward EPS × PE band + sensitivity + verdict ----------
// คำนวณฝั่ง client ล้วนจาก d.valuation_models (มีอยู่แล้วในทุก response ของ /api/tearsheet — ดู
// _tsAltValHtml ด้านล่างที่ใช้วัตถุดิบชุดเดียวกัน) ค่าเริ่มต้น Forward EPS = TTM EPS × (1+growth%
// เริ่มต้นจาก profit_ttm_yoy/profit_cagr), Base PE = PE ปัจจุบัน, Bear/Bull = Base ∓25%
function _tsPeVerdict(basePct) {
  if (basePct == null) return ['—', 'var(--text2)'];
  if (basePct >= 15) return ['ถูก / มี Margin', 'var(--green)'];
  if (basePct <= -15) return ['แพง', 'var(--red)'];
  return ['ใกล้เคียงมูลค่า', 'var(--text)'];
}

function _tsPeScenarioHtml(d) {
  const v = d.valuation, vm = d.valuation_models, price = d.header?.price;
  const epsTtm = vm?.eps;
  if (epsTtm == null || epsTtm <= 0 || !price) {
    return `<div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:6px">📈 PE Valuation (Bear/Base/Bull)</div>
      <div class="empty" style="padding:4px 0;font-size:11.5px">ข้อมูลไม่พอสำหรับคำนวณ (ต้องมี EPS ล่าสุดเป็นบวก + ราคา)</div>
    </div>`;
  }
  const growthDefault = vm.growth_pct_default != null ? Math.max(-30, Math.min(vm.growth_pct_default, 60)) : 8;
  const fwdEpsDefault = epsTtm * (1 + growthDefault / 100);
  const curPe = v?.pe?.value;
  const baseDefault = (curPe != null && curPe > 0) ? curPe : 15;
  _tsPeDefaults = { fwdEps: fwdEpsDefault, growth: growthDefault, base: baseDefault,
                     bear: baseDefault * 0.75, bull: baseDefault * 1.25 };
  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
      <div style="font-size:13px;font-weight:700;margin-bottom:4px">📈 PE Valuation (Bear/Base/Bull)</div>
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px;white-space:nowrap" onclick="_tsPeResetDefaults()" title="คืนค่าทุกช่องกลับเป็นค่าเริ่มต้น (สถิติ PE ย้อนหลังจริงถ้าโหลดแล้ว)">↺ ค่าเริ่มต้น</button>
    </div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px">ประเมินมูลค่าจาก Forward EPS × PE — หุ้นวัฏจักรควรใช้ normalized earnings แทน EPS ปีล่าสุดเดี่ยวๆ ทุกช่องแก้ค่าเองได้ ไม่ใช่คำแนะนำซื้อ/ขาย</div>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:6px;align-items:flex-end">
      <label style="font-size:11px;color:var(--text2)">Forward EPS
        <input id="ts-pe-fwdeps" type="number" step="0.01" value="${fwdEpsDefault.toFixed(2)}"
          class="scr-input" style="display:block;width:100px;margin-top:3px" oninput="_tsPeScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">EPS Growth %/ปี
        <input id="ts-pe-growth" type="number" step="0.5" value="${growthDefault.toFixed(1)}"
          class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsPeScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Base PE
        <input id="ts-pe-base" type="number" step="0.5" value="${baseDefault.toFixed(1)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPeScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Bear PE
        <input id="ts-pe-bear" type="number" step="0.5" value="${(baseDefault * 0.75).toFixed(1)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPeScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Bull PE
        <input id="ts-pe-bull" type="number" step="0.5" value="${(baseDefault * 1.25).toFixed(1)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPeScenarioRecalc()"></label>
    </div>
    <div id="ts-pe-growth-note" style="font-size:10.5px;color:var(--text2);margin-bottom:4px"></div>
    <div id="ts-pe-hist-note" style="font-size:10.5px;color:var(--text2);margin-bottom:8px"></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px" onclick="_tsPeUseTtmEps()">ใช้ TTM EPS</button>
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px" onclick="_tsPeUseTtmGrowth()">ใช้ TTM × Growth</button>
    </div>
    <div id="ts-pe-verdict" style="margin-bottom:12px"></div>
    <div style="display:flex;gap:14px;flex-wrap:wrap;margin-bottom:6px">
      <div style="flex:2;min-width:280px">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Fair Value Band</div>
        <div id="ts-pe-band"></div>
      </div>
      <div style="flex:1;min-width:200px">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Sensitivity</div>
        <div id="ts-pe-chart" style="display:flex;align-items:flex-end;gap:10px;height:110px;padding-top:6px"></div>
      </div>
    </div>
    <div id="ts-pe-reason"></div>
  </div>`;
}

function _tsPeResetDefaults() {
  const def = _tsPeDefaults;
  if (!def) return;
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = v.toFixed(id === 'ts-pe-fwdeps' ? 2 : 1); };
  set('ts-pe-fwdeps', def.fwdEps);
  set('ts-pe-growth', def.growth);
  set('ts-pe-base', def.base);
  set('ts-pe-bear', def.bear);
  set('ts-pe-bull', def.bull);
  _tsPeScenarioRecalc();
}

function _tsPeUseTtmEps() {
  const vm = _tsData?.valuation_models;
  const el = document.getElementById('ts-pe-fwdeps');
  if (!vm?.eps || !el) return;
  el.value = vm.eps.toFixed(2);
  _tsPeScenarioRecalc();
}

function _tsPeUseTtmGrowth() {
  const vm = _tsData?.valuation_models;
  const epsTtm = vm?.eps;
  const growth = parseFloat(document.getElementById('ts-pe-growth')?.value);
  const el = document.getElementById('ts-pe-fwdeps');
  if (epsTtm == null || !Number.isFinite(growth) || !el) return;
  el.value = (epsTtm * (1 + growth / 100)).toFixed(2);
  _tsPeScenarioRecalc();
}

function _tsPeScenarioRecalc() {
  const d = _tsData;
  const vm = d?.valuation_models;
  const bandBox = document.getElementById('ts-pe-band');
  if (!vm || !bandBox) return;
  const price = d.header?.price;
  const epsTtm = vm.eps;

  const growthNote = document.getElementById('ts-pe-growth-note');
  const growth = parseFloat(document.getElementById('ts-pe-growth')?.value);
  if (growthNote && epsTtm != null) {
    const g = Number.isFinite(growth) ? growth : 0;
    growthNote.textContent = `TTM EPS: ${epsTtm.toFixed(3)} · ที่โต ${g}%/ปี: ${(epsTtm * (1 + g / 100)).toFixed(3)}`;
  }

  const fwdEps = parseFloat(document.getElementById('ts-pe-fwdeps')?.value);
  const basePe = parseFloat(document.getElementById('ts-pe-base')?.value);
  const bearPe = parseFloat(document.getElementById('ts-pe-bear')?.value);
  const bullPe = parseFloat(document.getElementById('ts-pe-bull')?.value);
  if (!Number.isFinite(fwdEps) || fwdEps <= 0 || !price) {
    bandBox.innerHTML = `<div class="empty" style="padding:4px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี Forward EPS เป็นบวก)</div>`;
    const chartBox0 = document.getElementById('ts-pe-chart'); if (chartBox0) chartBox0.innerHTML = '';
    const verdictBox0 = document.getElementById('ts-pe-verdict'); if (verdictBox0) verdictBox0.innerHTML = '';
    const reasonBox0 = document.getElementById('ts-pe-reason'); if (reasonBox0) reasonBox0.innerHTML = '';
    return;
  }

  const scenarios = [
    { key: 'bear', label: 'Bear', pe: bearPe },
    { key: 'base', label: 'Base', pe: basePe },
    { key: 'bull', label: 'Bull', pe: bullPe },
  ].map(sc => {
    const fv = (Number.isFinite(sc.pe) && sc.pe > 0) ? fwdEps * sc.pe : null;
    const upside = fv != null ? (fv / price - 1) * 100 : null;
    return { ...sc, fv, upside };
  });

  const tileColor = up => up > 0 ? 'var(--green)' : up < 0 ? 'var(--red)' : 'var(--text2)';
  const rows = scenarios.map(sc => `
    <tr><td style="font-weight:600">${sc.label}</td>
      <td style="text-align:right">${fwdEps.toFixed(3)}</td>
      <td style="text-align:right">${Number.isFinite(sc.pe) ? sc.pe.toFixed(1) + 'x' : '—'}</td>
      <td style="text-align:right;font-weight:700">${sc.fv != null ? sc.fv.toFixed(2) : '—'}</td>
      <td style="text-align:right;color:${tileColor(sc.upside)}">${sc.upside != null ? (sc.upside > 0 ? '+' : '') + sc.upside.toFixed(1) + '%' : '—'}</td></tr>`).join('');
  bandBox.innerHTML = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      ${scenarios.map(sc => `<div class="card" style="padding:8px 12px;flex:1;min-width:100px;text-align:center">
        <div style="font-size:9px;color:var(--text2);text-transform:uppercase">${sc.label} · ${Number.isFinite(sc.pe) ? sc.pe.toFixed(1) + 'x' : '—'}</div>
        <div style="font-size:17px;font-weight:800">${sc.fv != null ? sc.fv.toFixed(2) : '—'}</div>
        <div style="font-size:10.5px;font-weight:600;color:${tileColor(sc.upside)}">${sc.upside != null ? (sc.upside > 0 ? '+' : '') + sc.upside.toFixed(1) + '%' : '—'}</div>
      </div>`).join('')}
    </div>
    <div style="overflow-x:auto"><table class="tbl" style="width:100%;max-width:480px">
      <thead><tr><th>Case</th><th style="text-align:right">Forward EPS</th><th style="text-align:right">Target PE</th><th style="text-align:right">Fair Value</th><th style="text-align:right">Upside</th></tr></thead>
      <tbody>${rows}</tbody></table></div>`;

  const chartBox = document.getElementById('ts-pe-chart');
  if (chartBox) {
    const maxFv = Math.max(...scenarios.map(s => s.fv || 0), price, 1);
    const barColor = { bear: 'var(--red)', base: 'var(--blue)', bull: 'var(--green)' };
    chartBox.innerHTML = scenarios.map(sc => {
      const hpx = sc.fv != null ? Math.max(4, Math.round(sc.fv / maxFv * 90)) : 4;
      return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%">
        <div style="font-size:10px;font-weight:700;margin-bottom:2px">${sc.fv != null ? sc.fv.toFixed(1) : '—'}</div>
        <div style="width:100%;max-width:44px;height:${hpx}px;background:${barColor[sc.key]};border-radius:3px 3px 0 0"></div>
        <div style="font-size:9.5px;color:var(--text2);margin-top:4px;text-align:center">${sc.label}<br>${Number.isFinite(sc.pe) ? sc.pe.toFixed(1) + 'x' : ''}</div>
      </div>`;
    }).join('');
  }

  const verdictBox = document.getElementById('ts-pe-verdict');
  if (verdictBox) {
    const baseSc = scenarios.find(s => s.key === 'base');
    const [lbl, lblColor] = _tsPeVerdict(baseSc?.upside);
    let growthNeeded = null;
    if (Number.isFinite(basePe) && basePe > 0 && epsTtm > 0) {
      growthNeeded = (price / (epsTtm * basePe) - 1) * 100;
    }
    verdictBox.innerHTML = `<div class="card" style="padding:12px 14px">
      <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;align-items:baseline">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase">Investment Verdict</div>
        <div style="font-size:15px;font-weight:800;color:${lblColor}">${lbl}</div>
      </div>
      <div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:8px">
        <div><div style="font-size:16px;font-weight:700;color:${tileColor(baseSc?.upside)}">${baseSc?.upside != null ? (baseSc.upside > 0 ? '+' : '') + baseSc.upside.toFixed(1) + '%' : '—'}</div><div style="font-size:10px;color:var(--text2)">Base upside</div></div>
        <div><div style="font-size:16px;font-weight:700">${growthNeeded != null ? (growthNeeded > 0 ? '+' : '') + growthNeeded.toFixed(1) + '%' : '—'}</div><div style="font-size:10px;color:var(--text2)">EPS growth ที่ justify ราคาปัจจุบัน (ที่ Base PE)</div></div>
      </div>
    </div>`;
  }

  const reasonBox = document.getElementById('ts-pe-reason');
  if (reasonBox) {
    const curPe = d.valuation?.pe?.value;
    const fwdPe = (price && fwdEps > 0) ? price / fwdEps : null;
    reasonBox.innerHTML = `<details>
      <summary style="cursor:pointer;font-size:11px;color:var(--text2)">🔍 Reasonableness Check</summary>
      <div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:8px">
        <div><div style="font-size:14px;font-weight:700">${curPe != null ? curPe.toFixed(1) + 'x' : '—'}</div><div style="font-size:10px;color:var(--text2)">Current PE (TTM)</div></div>
        <div><div style="font-size:14px;font-weight:700">${fwdPe != null ? fwdPe.toFixed(1) + 'x' : '—'}</div><div style="font-size:10px;color:var(--text2)">Forward PE</div></div>
      </div>
      <div style="font-size:10.5px;color:var(--text2);margin-top:6px">Historical/Peer PE ยังเป็น manual reference — เทียบกับ percentile เทียบอดีตตัวเองใน Valuation Snapshot ด้านบน หรือหน้า "เทียบเพื่อน" ประกอบ</div>
    </details>`;
  }
}

// ---------- PBV Valuation (Bear/Base/Bull) — โครงสร้างเดียวกับ PE Valuation ด้านบนทุกอย่าง
// แค่เปลี่ยนตัวแปรอ้างอิงเป็น BVPS × PBV แทน EPS × PE — ค่าเริ่มต้น "BVPS Growth %" ใช้ sustainable
// growth rate = ROE × (1 − payout ratio) เพราะ book value โตจากกำไรสะสม (retained earnings) ไม่ใช่
// สมมติฐานโตกำไรแบบ EPS — Base/Bear/Bull PBV เริ่มจากปัจจุบัน±25% แล้วถูกแทนที่ด้วยสถิติ PBV
// ย้อนหลังจริง (มัธยฐาน/ต่ำสุด/สูงสุด) ตอน _tsLoadFinExtras โหลด Finnomena เสร็จ (ดู _tsApplyPbvBandDefaults)
function _tsPbvGrowthDefault(d) {
  const vm = d.valuation_models;
  const roe = vm?.roe;
  const payout = d.dividend?.payout_ratio_pct;
  let g;
  if (roe != null && payout != null) g = roe * (1 - payout / 100);
  else if (roe != null) g = roe * 0.5;   // ไม่รู้ payout — ประมาณ retention 50%
  else g = vm?.growth_pct_default ?? 5;
  return Math.max(-30, Math.min(g, 60));
}

function _tsPbvScenarioHtml(d) {
  const v = d.valuation, vm = d.valuation_models, price = d.header?.price;
  const bvps = vm?.bvps;
  if (bvps == null || bvps <= 0 || !price) {
    return `<div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:6px">📘 PBV Valuation (Bear/Base/Bull)</div>
      <div class="empty" style="padding:4px 0;font-size:11.5px">ข้อมูลไม่พอสำหรับคำนวณ (ต้องมี BVPS เป็นบวก + ราคา)</div>
    </div>`;
  }
  const growthDefault = _tsPbvGrowthDefault(d);
  const fwdBvpsDefault = bvps * (1 + growthDefault / 100);
  const curPbv = v?.pbv?.value;
  const baseDefault = (curPbv != null && curPbv > 0) ? curPbv : 1.5;
  _tsPbvDefaults = { fwdBvps: fwdBvpsDefault, growth: growthDefault, base: baseDefault,
                      bear: baseDefault * 0.75, bull: baseDefault * 1.25 };
  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
      <div style="font-size:13px;font-weight:700;margin-bottom:4px">📘 PBV Valuation (Bear/Base/Bull)</div>
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px;white-space:nowrap" onclick="_tsPbvResetDefaults()" title="คืนค่าทุกช่องกลับเป็นค่าเริ่มต้น (สถิติ PBV ย้อนหลังจริงถ้าโหลดแล้ว)">↺ ค่าเริ่มต้น</button>
    </div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px">ประเมินมูลค่าจาก Forward BVPS × PBV — เหมาะกับกลุ่มการเงิน/REIT ที่ DCF ใช้ไม่ได้ ทุกช่องแก้ค่าเองได้ ไม่ใช่คำแนะนำซื้อ/ขาย</div>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:6px;align-items:flex-end">
      <label style="font-size:11px;color:var(--text2)">Forward BVPS
        <input id="ts-pbv-fwdbvps" type="number" step="0.01" value="${fwdBvpsDefault.toFixed(2)}"
          class="scr-input" style="display:block;width:100px;margin-top:3px" oninput="_tsPbvScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">BVPS Growth %/ปี
        <input id="ts-pbv-growth" type="number" step="0.5" value="${growthDefault.toFixed(1)}"
          class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsPbvScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Base PBV
        <input id="ts-pbv-base" type="number" step="0.1" value="${baseDefault.toFixed(2)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPbvScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Bear PBV
        <input id="ts-pbv-bear" type="number" step="0.1" value="${(baseDefault * 0.75).toFixed(2)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPbvScenarioRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Bull PBV
        <input id="ts-pbv-bull" type="number" step="0.1" value="${(baseDefault * 1.25).toFixed(2)}"
          class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsPbvScenarioRecalc()"></label>
    </div>
    <div id="ts-pbv-growth-note" style="font-size:10.5px;color:var(--text2);margin-bottom:4px"></div>
    <div id="ts-pbv-hist-note" style="font-size:10.5px;color:var(--text2);margin-bottom:8px"></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px" onclick="_tsPbvUseCurrentBvps()">ใช้ BVPS ปัจจุบัน</button>
      <button class="btn-secondary" style="font-size:10.5px;padding:4px 8px" onclick="_tsPbvUseBvpsGrowth()">ใช้ BVPS × Growth</button>
    </div>
    <div id="ts-pbv-verdict" style="margin-bottom:12px"></div>
    <div style="display:flex;gap:14px;flex-wrap:wrap;margin-bottom:6px">
      <div style="flex:2;min-width:280px">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Fair Value Band</div>
        <div id="ts-pbv-band"></div>
      </div>
      <div style="flex:1;min-width:200px">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Sensitivity</div>
        <div id="ts-pbv-chart" style="display:flex;align-items:flex-end;gap:10px;height:110px;padding-top:6px"></div>
      </div>
    </div>
    <div id="ts-pbv-reason"></div>
  </div>`;
}

function _tsPbvResetDefaults() {
  const def = _tsPbvDefaults;
  if (!def) return;
  const set = (id, v, dp) => { const el = document.getElementById(id); if (el) el.value = v.toFixed(dp); };
  set('ts-pbv-fwdbvps', def.fwdBvps, 2);
  set('ts-pbv-growth', def.growth, 1);
  set('ts-pbv-base', def.base, 2);
  set('ts-pbv-bear', def.bear, 2);
  set('ts-pbv-bull', def.bull, 2);
  _tsPbvScenarioRecalc();
}

function _tsPbvUseCurrentBvps() {
  const vm = _tsData?.valuation_models;
  const el = document.getElementById('ts-pbv-fwdbvps');
  if (!vm?.bvps || !el) return;
  el.value = vm.bvps.toFixed(2);
  _tsPbvScenarioRecalc();
}

function _tsPbvUseBvpsGrowth() {
  const vm = _tsData?.valuation_models;
  const bvps = vm?.bvps;
  const growth = parseFloat(document.getElementById('ts-pbv-growth')?.value);
  const el = document.getElementById('ts-pbv-fwdbvps');
  if (bvps == null || !Number.isFinite(growth) || !el) return;
  el.value = (bvps * (1 + growth / 100)).toFixed(2);
  _tsPbvScenarioRecalc();
}

function _tsPbvScenarioRecalc() {
  const d = _tsData;
  const vm = d?.valuation_models;
  const bandBox = document.getElementById('ts-pbv-band');
  if (!vm || !bandBox) return;
  const price = d.header?.price;
  const bvps = vm.bvps;

  const growthNote = document.getElementById('ts-pbv-growth-note');
  const growth = parseFloat(document.getElementById('ts-pbv-growth')?.value);
  if (growthNote && bvps != null) {
    const g = Number.isFinite(growth) ? growth : 0;
    growthNote.textContent = `BVPS ปัจจุบัน: ${bvps.toFixed(3)} · ที่โต ${g}%/ปี: ${(bvps * (1 + g / 100)).toFixed(3)}`;
  }

  const fwdBvps = parseFloat(document.getElementById('ts-pbv-fwdbvps')?.value);
  const basePbv = parseFloat(document.getElementById('ts-pbv-base')?.value);
  const bearPbv = parseFloat(document.getElementById('ts-pbv-bear')?.value);
  const bullPbv = parseFloat(document.getElementById('ts-pbv-bull')?.value);
  if (!Number.isFinite(fwdBvps) || fwdBvps <= 0 || !price) {
    bandBox.innerHTML = `<div class="empty" style="padding:4px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี Forward BVPS เป็นบวก)</div>`;
    const chartBox0 = document.getElementById('ts-pbv-chart'); if (chartBox0) chartBox0.innerHTML = '';
    const verdictBox0 = document.getElementById('ts-pbv-verdict'); if (verdictBox0) verdictBox0.innerHTML = '';
    const reasonBox0 = document.getElementById('ts-pbv-reason'); if (reasonBox0) reasonBox0.innerHTML = '';
    return;
  }

  const scenarios = [
    { key: 'bear', label: 'Bear', pbv: bearPbv },
    { key: 'base', label: 'Base', pbv: basePbv },
    { key: 'bull', label: 'Bull', pbv: bullPbv },
  ].map(sc => {
    const fv = (Number.isFinite(sc.pbv) && sc.pbv > 0) ? fwdBvps * sc.pbv : null;
    const upside = fv != null ? (fv / price - 1) * 100 : null;
    return { ...sc, fv, upside };
  });

  const tileColor = up => up > 0 ? 'var(--green)' : up < 0 ? 'var(--red)' : 'var(--text2)';
  const rows = scenarios.map(sc => `
    <tr><td style="font-weight:600">${sc.label}</td>
      <td style="text-align:right">${fwdBvps.toFixed(3)}</td>
      <td style="text-align:right">${Number.isFinite(sc.pbv) ? sc.pbv.toFixed(2) + 'x' : '—'}</td>
      <td style="text-align:right;font-weight:700">${sc.fv != null ? sc.fv.toFixed(2) : '—'}</td>
      <td style="text-align:right;color:${tileColor(sc.upside)}">${sc.upside != null ? (sc.upside > 0 ? '+' : '') + sc.upside.toFixed(1) + '%' : '—'}</td></tr>`).join('');
  bandBox.innerHTML = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      ${scenarios.map(sc => `<div class="card" style="padding:8px 12px;flex:1;min-width:100px;text-align:center">
        <div style="font-size:9px;color:var(--text2);text-transform:uppercase">${sc.label} · ${Number.isFinite(sc.pbv) ? sc.pbv.toFixed(2) + 'x' : '—'}</div>
        <div style="font-size:17px;font-weight:800">${sc.fv != null ? sc.fv.toFixed(2) : '—'}</div>
        <div style="font-size:10.5px;font-weight:600;color:${tileColor(sc.upside)}">${sc.upside != null ? (sc.upside > 0 ? '+' : '') + sc.upside.toFixed(1) + '%' : '—'}</div>
      </div>`).join('')}
    </div>
    <div style="overflow-x:auto"><table class="tbl" style="width:100%;max-width:480px">
      <thead><tr><th>Case</th><th style="text-align:right">Forward BVPS</th><th style="text-align:right">Target PBV</th><th style="text-align:right">Fair Value</th><th style="text-align:right">Upside</th></tr></thead>
      <tbody>${rows}</tbody></table></div>`;

  const chartBox = document.getElementById('ts-pbv-chart');
  if (chartBox) {
    const maxFv = Math.max(...scenarios.map(s => s.fv || 0), price, 1);
    const barColor = { bear: 'var(--red)', base: 'var(--blue)', bull: 'var(--green)' };
    chartBox.innerHTML = scenarios.map(sc => {
      const hpx = sc.fv != null ? Math.max(4, Math.round(sc.fv / maxFv * 90)) : 4;
      return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%">
        <div style="font-size:10px;font-weight:700;margin-bottom:2px">${sc.fv != null ? sc.fv.toFixed(1) : '—'}</div>
        <div style="width:100%;max-width:44px;height:${hpx}px;background:${barColor[sc.key]};border-radius:3px 3px 0 0"></div>
        <div style="font-size:9.5px;color:var(--text2);margin-top:4px;text-align:center">${sc.label}<br>${Number.isFinite(sc.pbv) ? sc.pbv.toFixed(2) + 'x' : ''}</div>
      </div>`;
    }).join('');
  }

  const verdictBox = document.getElementById('ts-pbv-verdict');
  if (verdictBox) {
    const baseSc = scenarios.find(s => s.key === 'base');
    const [lbl, lblColor] = _tsPeVerdict(baseSc?.upside);
    let growthNeeded = null;
    if (Number.isFinite(basePbv) && basePbv > 0 && bvps > 0) {
      growthNeeded = (price / (bvps * basePbv) - 1) * 100;
    }
    verdictBox.innerHTML = `<div class="card" style="padding:12px 14px">
      <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;align-items:baseline">
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase">Investment Verdict</div>
        <div style="font-size:15px;font-weight:800;color:${lblColor}">${lbl}</div>
      </div>
      <div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:8px">
        <div><div style="font-size:16px;font-weight:700;color:${tileColor(baseSc?.upside)}">${baseSc?.upside != null ? (baseSc.upside > 0 ? '+' : '') + baseSc.upside.toFixed(1) + '%' : '—'}</div><div style="font-size:10px;color:var(--text2)">Base upside</div></div>
        <div><div style="font-size:16px;font-weight:700">${growthNeeded != null ? (growthNeeded > 0 ? '+' : '') + growthNeeded.toFixed(1) + '%' : '—'}</div><div style="font-size:10px;color:var(--text2)">BVPS growth ที่ justify ราคาปัจจุบัน (ที่ Base PBV)</div></div>
      </div>
    </div>`;
  }

  const reasonBox = document.getElementById('ts-pbv-reason');
  if (reasonBox) {
    const curPbv = d.valuation?.pbv?.value;
    const fwdPbv = (price && fwdBvps > 0) ? price / fwdBvps : null;
    reasonBox.innerHTML = `<details>
      <summary style="cursor:pointer;font-size:11px;color:var(--text2)">🔍 Reasonableness Check</summary>
      <div style="display:flex;gap:24px;flex-wrap:wrap;margin-top:8px">
        <div><div style="font-size:14px;font-weight:700">${curPbv != null ? curPbv.toFixed(2) + 'x' : '—'}</div><div style="font-size:10px;color:var(--text2)">Current PBV</div></div>
        <div><div style="font-size:14px;font-weight:700">${fwdPbv != null ? fwdPbv.toFixed(2) + 'x' : '—'}</div><div style="font-size:10px;color:var(--text2)">Forward PBV</div></div>
      </div>
      <div style="font-size:10.5px;color:var(--text2);margin-top:6px">Historical/Peer PBV ยังเป็น manual reference — เทียบกับ percentile เทียบอดีตตัวเองใน Valuation Snapshot ด้านบน หรือหน้า "เทียบเพื่อน" ประกอบ</div>
    </details>`;
  }
}

// อัพเดท PE/PBV/P/S ใน "Valuation Snapshot" ให้ใช้ราคาสดจาก Yahoo แทนราคาสิ้นงวด/สิ้นวัน
// ของ snapshot (เหมือนแนวคิดเดียวกับ _loadLiveValuationBand ในหน้างบการเงิน) — value ใหม่
// = value เดิม × (ราคาสด ÷ ราคาที่ใช้คำนวณ value เดิม) เพราะ PE/PBV/PS ล้วนแปรผันตรงกับราคา
// ที่ EPS/BVPS/revenue ต่อหุ้นคงที่ ไม่ต้องรู้ EPS/BVPS จริงก็คำนวณสัดส่วนได้ ส่วน percentile/
// เฉลี่ย/มัธยฐาน (คำนวณจากประวัติ ไม่ผูกกับราคาวันนี้) คงไว้ตามเดิม
function _tsLoadLiveValuation(d, h) {
  const yfSym = d.yf_symbol;
  const basePrice = h.price;
  if (!yfSym || !basePrice) return;
  // TH: ไม่ส่ง ?yf — ปล่อยให้ /api/live-price ใช้ SET API fast path (~1s) แทน yfinance fast_info
  // ที่ช้า 30-45s ตอนโดน rate limit (ดู docstring live_price) · non-TH ต้องส่ง yf เพราะ backend
  // เดา ticker mirror ที่ไม่มี suffix ผิด
  const mkt = d.market || 'TH';
  const url = mkt === 'TH'
    ? `/api/live-price/${encodeURIComponent(d.symbol)}`
    : `/api/live-price/${encodeURIComponent(d.symbol)}?yf=${encodeURIComponent(yfSym)}`;
  _fetchTimeout(url, 20000)
    .then(r => r.json()).then(res => {
      if (_tsData?.symbol !== d.symbol) return;   // เปลี่ยนหุ้นไปแล้วระหว่างรอโหลด
      if (res.error || !res.price) return;
      const live = res.price;
      const priceEl = document.getElementById('ts-val-live-price');
      if (priceEl) {
        priceEl.textContent = `· ราคาล่าสุด: ${live.toLocaleString(undefined, {maximumFractionDigits: 2})} ${res.currency || ''}`;
      }
      const ratio = live / basePrice;
      ['pe', 'pbv', 'ps'].forEach(key => {
        const v = (d.valuation || {})[key];
        const el = document.getElementById('ts-val-' + key);
        if (!el || !v || v.value == null) return;
        // rescale ได้เฉพาะค่าที่อิงราคาชุดเดียวกับ h.price (daily snapshot) — ถ้า value มาจาก
        // Finnomena สิ้นไตรมาส (live_scalable=false) ratio จะ ≈1 = โชว์ค่าไตรมาสเก่าติดป้ายว่าสด
        // ผิด · การ์ด band "มูลค่าเทียบอดีตตัวเอง" ด้านล่างคำนวณ PE/PBV สดจริงจาก EPS/BVPS ให้แล้ว
        if (!v.live_scalable) return;
        el.textContent = Math.round(v.value * ratio * 100) / 100;
      });
    }).catch(() => {});
}

// ---------- DCF (งาน #6): Reverse DCF เป็นหลัก + Forward DCF 3 ฉาก + sensitivity ----------
// คำนวณฝั่ง client ล้วน (input มากับ payload tearsheet อยู่แล้ว) — ใช้ FCF ปีล่าสุดจาก Yahoo annual
// (ไม่ใช่ TTM/ค่าเฉลี่ย) EV = mkt_cap - net_cash, Equity = PV(FCF stream)+net_cash, shares = mkt_cap/price
function _tsDcfHtml(dcf, price) {
  if (!dcf) return '';
  if (dcf.is_financial_sector) {
    return `<div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:6px">🎯 มูลค่าเหมาะสม (DCF)</div>
      <div class="empty" style="padding:4px 0;font-size:11.5px">สูตร DCF ใช้ไม่ได้กับกลุ่มการเงิน (ธนาคาร/เงินทุน/ประกัน) เพราะ FCF ไม่มีความหมายกับธุรกิจกลุ่มนี้</div>
    </div>`;
  }
  // dcf.forecast (DCF Model เต็มรูปแบบ) มาจากงบ Yahoo annual คนละแหล่งกับ fcf/mkt_cap
  // (factor_snapshot) — คำนวณสำเร็จได้แม้ Reverse/Forward DCF ด้านล่างขาดข้อมูล จึงต้องโชว์
  // เสมอถ้ามี ไม่ผูกกับเงื่อนไข fcf/mkt_cap/price ด้านล่าง (เดิม return ก่อนถึงบรรทัดนี้เลย
  // ทำให้ dcf.forecast ที่ backend คำนวณไว้ครบหายไปเงียบๆ)
  const modelHtml = dcf.forecast ? _tsDcfModelHtml(dcf.forecast, dcf) : '';
  if (dcf.fcf == null || !dcf.mkt_cap || !price) {
    return `<div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:13px;font-weight:700;margin-bottom:6px">🎯 มูลค่าเหมาะสม (DCF)</div>
      <div class="empty" style="padding:4px 0;font-size:11.5px">ข้อมูลไม่พอสำหรับคำนวณ Reverse/Forward DCF (ต้องมี Free Cash Flow + มูลค่าตลาด)</div>
    </div>${modelHtml}`;
  }
  const negNote = dcf.fcf <= 0
    ? `<div style="font-size:11px;color:var(--red);margin-bottom:8px">⚠ FCF ปีล่าสุดติดลบ — ผลลัพธ์ด้านล่างอาจไม่สมเหตุผล ควรดูแนวโน้มหลายปีประกอบก่อนเชื่อตัวเลขนี้</div>` : '';
  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:13px;font-weight:700;margin-bottom:4px">🎯 มูลค่าเหมาะสม (DCF)</div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px">ประมาณการคร่าวๆ จาก FCF ปีล่าสุด — ไม่ใช่คำแนะนำซื้อ/ขาย ใช้เป็นจุดตั้งต้นคิดต่อเอง</div>
    ${_dcfFormulaNoteHtml()}
    ${negNote}
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:12px;align-items:flex-end">
      <label style="font-size:11px;color:var(--text2)">Discount Rate %
        <input id="ts-dcf-discount" type="number" min="6" max="15" step="0.5" value="${dcf.discount_rate_default}"
          class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Terminal Growth %
        <input id="ts-dcf-terminal" type="number" min="0" max="4" step="0.25" value="${dcf.terminal_growth_default}"
          class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
    </div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:12px">
      ผลตอบแทนพันธบัตรรัฐบาล (อ้างอิงตั้ง Discount Rate):
      <a href="https://www.thaibma.or.th/EN/Market/YieldCurve/Government.aspx" target="_blank" rel="noopener">ไทย (ThaiBMA)</a> ·
      <a href="https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_yield_curve&field_tdr_date_value=2026" target="_blank" rel="noopener">สหรัฐฯ (US Treasury, 1M-30Y)</a> ·
      <a href="https://www.worldgovernmentbonds.com/country/united-states/" target="_blank" rel="noopener">US (worldgovernmentbonds, ล่าสุดอัตโนมัติ)</a>
    </div>
    <div id="ts-dcf-reverse"></div>

    <div style="margin-bottom:14px">
      <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Forward DCF — 3 ฉาก (ปี 1-5 โตตามอัตราที่กรอก ปี 6-10 ค่อยๆ ลดสู่ Terminal)</div>
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px;align-items:flex-end">
        <label style="font-size:11px;color:var(--text2)">Bear %
          <input id="ts-dcf-g-bear" type="number" step="0.5" value="${DCF_SCENARIO_DEFAULTS.bear}"
            class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
        <label style="font-size:11px;color:var(--text2)">Base %
          <input id="ts-dcf-g-base" type="number" step="0.5" value="${DCF_SCENARIO_DEFAULTS.base}"
            class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
        <label style="font-size:11px;color:var(--text2)">Bull %
          <input id="ts-dcf-g-bull" type="number" step="0.5" value="${DCF_SCENARIO_DEFAULTS.bull}"
            class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
        <button class="btn" style="font-size:10.5px;padding:4px 8px" onclick="_tsDcfUseHistGrowth()"
          title="ตั้ง Base = CAGR กำไร/รายได้ในอดีตของหุ้นตัวนี้ แล้วกระจาย Bear/Bull รอบๆ">ใช้ CAGR อดีต</button>
      </div>
      <div id="ts-dcf-forward"></div>
    </div>

    <div>
      <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Sensitivity — Fair Value ต่อหุ้น (แถว=โตปี1-5 · คอลัมน์=Discount Rate)</div>
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px;align-items:flex-end">
        <label style="font-size:11px;color:var(--text2)">แกนโต % (คั่นด้วยจุลภาค)
          <input id="ts-dcf-sens-growth" type="text" value="${DCF_SENS_GROWTH_DEFAULT}"
            class="scr-input" style="display:block;width:180px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
        <label style="font-size:11px;color:var(--text2)">แกน Discount % (คั่นด้วยจุลภาค)
          <input id="ts-dcf-sens-disc" type="text" value="${DCF_SENS_DISC_DEFAULT}"
            class="scr-input" style="display:block;width:180px;margin-top:3px" oninput="_tsDcfRecalc()"></label>
      </div>
      <div id="ts-dcf-sens"></div>
    </div>

    <div style="font-size:10px;color:var(--text2);margin-top:10px;padding-top:8px;border-top:1px solid var(--border)">⚠ เป็นกรอบคิดคร่าวๆ ไม่ใช่คำแนะนำซื้อ/ขาย — ผลลัพธ์ไวมากต่อสมมติฐาน growth/discount rate ที่ใส่ ใช้ FCF ปีล่าสุด (ไม่ใช่ TTM หรือค่าเฉลี่ยหลายปี) หุ้นที่ FCF ผันผวน/เป็นวัฏจักรควรดูย้อนหลังหลายปีประกอบก่อนเชื่อตัวเลขนี้</div>
    ${modelHtml}
  </div>`;
}

// ---------- DCF Model (พยากรณ์เต็มรูปแบบ): Revenue -> EBIT -> NOPLAT -> D&A -> CapEx -> NWC -> FCFF ----------
// ต่างจาก Reverse/Forward DCF ด้านบนตรงที่ไม่ใช้ FCF ก้อนเดียวโตอัตราเดียว แต่ build รายบรรทัด
// จากงบ Yahoo ปีล่าสุด (ทุก % แก้เองได้) — WACC build จาก 3 ขั้น (Cost of Equity/Cost of Debt/
// Capital Structure) เหมือนหน้า factsheet ทั่วไป ไม่ใช่ช่องเดียวกรอกเอง: ค่าที่มีในงบจริง
// (ดอกเบี้ยจ่าย÷หนี้รวม, Equity/Debt value, Tax Rate) ดึงจากข้อมูลจริงเป็นค่าเริ่มต้น ส่วนที่ไม่มี
// ในงบเลย (Risk-free rate/Beta/Equity Risk Premium) เป็นช่องกรอกเองล้วนๆ (Beta หุ้นไทยรายตัว
// ดูได้จากหน้า factsheet ของ SET.or.th)
//
// nwc_pct_revenue (จาก compute_dcf_forecast_inputs) = ระดับ Working Capital ÷ Revenue ปีล่าสุด
// (ไม่ใช่ 'การเปลี่ยนแปลง' — เปลี่ยนนิยาม 2026-08-21 หลังเทียบกับเครื่องมืออ้างอิงภายนอกแล้วนิยาม
// เดิม (ΔNWC จากงบกระแสเงินสด) ห่างจากค่าอ้างอิงมาก ~10pp ทุกตัวที่ทดสอบ ส่วนนิยามระดับตรงกับ
// PTT เป๊ะ 12.75% vs 12.7%) ผลกระทบต่อ FCFF แต่ละปีพยากรณ์จึงต้องคูณกับ 'ส่วนต่างรายได้ปีนั้นๆ
// เทียบปีก่อน' (nwcDefault = -(nwcPct × ΔRevenue)) ไม่ใช่คูณรายได้เต็มปีเหมือนเดิม — ดู nwcDefault
// ใน loop ด้านล่าง
//
// override รายปีของ D&A/CapEx/NWC ที่กดแก้เองในตาราง (key = t, value = บาทเต็ม) — รีเซ็ตทุกครั้ง
// ที่เปิด Tearsheet หุ้นตัวใหม่ (ดู _tsDcfModelHtml) แต่คงอยู่ข้าม recalc ของหุ้นตัวเดิม (เปลี่ยน
// growth/WACC/forecast period ไม่ล้าง override ที่กดไว้)
let _tsDcfModelOverrides = { revenue: {}, ebit: {}, noplat: {}, da: {}, capex: {}, nwc: {} };

// Fair Value ต่อหุ้นของฉาก Base (Forward DCF) จาก _tsDcfRecalc() ล่าสุด — ให้การ์ด
// "🎯 ฉันทามตินักวิเคราะห์" (โหลด async หลัง render) เอาไปเทียบกับราคาเป้าหมายนักวิเคราะห์
// โดยไม่ต้องคำนวณ DCF ซ้ำเอง · null = คำนวณไม่ได้/หุ้นกลุ่มการเงิน/ข้อมูลไม่พอ
let _tsDcfBaseFairValue = null;

function _tsDcfModelCellEdit(el) {
  const t = parseInt(el.dataset.t, 10);
  const field = el.dataset.field;
  const v = parseFloat(el.value);
  if (Number.isFinite(v)) {
    _tsDcfModelOverrides[field][t] = v * 1e6;
  } else {
    delete _tsDcfModelOverrides[field][t];
  }
  _tsDcfModelRecalc();
}

// พิมพ์ในช่อง WACC กรอกเอง -> สลับ radio ไปโหมด "กรอกเอง" ให้อัตโนมัติ (ไม่ต้องกดเลือกเอง)
function _tsDcfModelWaccManualInput() {
  const radio = document.getElementById('ts-dm-wacc-mode-manual');
  if (radio) radio.checked = true;
  _tsDcfModelRecalc();
}

// ปุ่ม "คืนค่าเริ่มต้น" — วาด section นี้ใหม่ทั้งก้อนจาก fc/dcf เดิม (ล้าง override รายเซลล์ +
// ค่าที่กรอกเองทุกช่องกลับไปเป็นค่าตั้งต้นจากงบ/ค่า default ทั้งหมด) แทนที่จะรีเซ็ตทีละช่อง
function _tsDcfModelReset() {
  const dcf = _tsData?.dcf;
  const fc = dcf?.forecast;
  const section = document.getElementById('ts-dm-section');
  if (!dcf || !fc || !section) return;
  section.outerHTML = _tsDcfModelHtml(fc, dcf);
  _tsDcfModelRecalc();
}

// คำเรียกสกุลเงินของงบ/ราคาใน Tearsheet ตามตลาด — งบ mirror US/HK/JP เป็น USD/HKD/JPY
// (backend ไม่แปลงค่าเงิน — mkt_cap/price/forecast.revenue อยู่สกุลเดียวกันหมด) · ตลาด lite อื่น
// (DR VN/SG/EU/…) ไม่รู้สกุลแน่ชัด คืน '' ให้ผู้เรียกใช้ label กลางๆ ("ล้าน" / "/หุ้น" เปล่าๆ)
function _tsCurWord() {
  return { TH: 'บาท', US: 'USD', HK: 'HKD', JP: 'JPY' }[_tsData?.market] || '';
}
// "ล้าน<หน่วย>" — ไทยเขียนติด ("ล้านบาท") · รหัสสกุลอังกฤษเว้นวรรค ("ล้าน USD") · lite → "ล้าน"
function _tsMilUnit(cw) { return cw === 'บาท' ? 'ล้านบาท' : cw ? 'ล้าน ' + cw : 'ล้าน'; }

function _tsDcfModelHtml(fc, dcf) {
  _tsDcfModelOverrides = { revenue: {}, ebit: {}, noplat: {}, da: {}, capex: {}, nwc: {} };
  const cw = _tsCurWord();   // 'บาท' (TH) · 'USD'/'HKD'/'JPY' · '' (lite อื่น)
  const munit = _tsMilUnit(cw);   // TH → "ล้านบาท", US/HK/JP → "ล้าน USD/…", lite → "ล้าน"
  const isTH = _tsData?.market === 'TH';
  const factsheetUrl = isTH
    ? `https://www.set.or.th/th/market/product/stock/quote/${(_tsData?.symbol || '').toLowerCase()}/factsheet` : null;
  const n = (v, d) => Number.isFinite(v) ? v : d;
  const equityDefault = (dcf.mkt_cap || 0) / 1e6;
  const debtDefault = (fc.total_debt || 0) / 1e6;
  return `<div id="ts-dm-section" style="margin-top:16px;padding-top:12px;border-top:1px solid var(--border)">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;flex-wrap:wrap">
      <div style="font-size:13px;font-weight:700">🧮 DCF Model — พยากรณ์เต็มรูปแบบ</div>
      <button class="btn" style="font-size:10.5px;padding:2px 8px" onclick="_tsDcfModelReset()">↺ คืนค่าเริ่มต้น</button>
    </div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:4px">
      ทุกช่องด้านล่างแก้ตัวเลขเองได้ทั้งหมด ค่าเริ่มต้นบางช่องดึงจากงบปีล่าสุด (${fc.as_of || '—'}) บางช่องเป็นค่าสมมติ ไม่ได้มาจากงบจริง — ดูหมายเหตุด้านล่าง
      ${factsheetUrl ? `(<a href="${factsheetUrl}" target="_blank" rel="noopener">หน้า factsheet ของ SET.or.th</a> มีค่า Beta หุ้นตัวนี้ให้ดูประกอบ)` : ''}
    </div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px;line-height:1.7">
      <div>📊 <b style="color:var(--text)">ดึงจากงบจริง</b> (ปีล่าสุด เป็นค่าเริ่มต้น แก้เองได้): EBIT Margin, Tax Rate, D&amp;A/CapEx %Revenue, NWC %Revenue (ระดับ Working Capital ปีล่าสุด), ดอกเบี้ยจ่ายเฉลี่ยต่อหนี้, มูลค่า Equity (E)/Debt (D)</div>
      <div>✏️ <b style="color:var(--text)">ค่าสมมติ ไม่มีในงบการเงิน</b> ต้องกะเอง/หาข้อมูลเพิ่ม: Risk-free Rate, Beta, Equity Risk Premium, Terminal Growth</div>
      <div>📈 <b style="color:var(--text)">กึ่งกลาง</b> — ตั้งต้นจาก CAGR รายได้ในอดีต (จากงบจริง) แต่เป็นการ<i>คาดการณ์อนาคต</i>ไม่ใช่ตัวเลขจริง: Rev Growth ปี1-3/ปี4-5</div>
    </div>
    <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:14px">
      <label style="font-size:11px;color:var(--text2)">Rev Growth ปี1-3 %
        <input id="ts-dm-g13" type="number" step="0.5" value="${n(dcf.rev_cagr, 5).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Rev Growth ปี4-5 %
        <input id="ts-dm-g45" type="number" step="0.5" value="${(n(dcf.rev_cagr, 5) * 0.6).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">EBIT Margin %
        <input id="ts-dm-ebitm" type="number" step="0.1" value="${n(fc.ebit_margin, 10).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Tax Rate %
        <input id="ts-dm-tax" type="number" step="0.5" value="${n(fc.tax_rate, 20).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">D&amp;A % Revenue
        <input id="ts-dm-da" type="number" step="0.1" value="${n(fc.da_pct_revenue, 3).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">CapEx % Revenue
        <input id="ts-dm-capex" type="number" step="0.1" value="${n(fc.capex_pct_revenue, 3).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">NWC % Revenue (ระดับ)
        <input id="ts-dm-nwc" type="number" step="0.1" value="${n(fc.nwc_pct_revenue, 0).toFixed(1)}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Terminal Growth %
        <input id="ts-dm-tg" type="number" step="0.25" value="${dcf.terminal_growth_default}"
          class="scr-input" style="display:block;width:88px;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
      <label style="font-size:11px;color:var(--text2)">Forecast Period
        <select id="ts-dm-years" class="scr-input" style="display:block;width:88px;margin-top:3px" onchange="_tsDcfModelRecalc()">
          <option value="3">3 ปี</option><option value="5" selected>5 ปี</option><option value="10">10 ปี</option>
        </select></label>
    </div>

    <div class="card" style="padding:12px;margin-bottom:14px;background:var(--card2)">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap">
        <div style="font-size:11.5px;font-weight:700">⚖ WACC — ต้นทุนเงินทุนถัวเฉลี่ยถ่วงน้ำหนัก</div>
        ${factsheetUrl ? `<a href="${factsheetUrl}" target="_blank" rel="noopener" class="btn" style="font-size:10.5px;padding:2px 8px;text-decoration:none">📄 ดู Beta ที่ factsheet SET.or.th</a>` : ''}
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px">
        <div>
          <div style="font-size:10.5px;color:var(--text2);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">ขั้น 1 — Cost of Equity (CAPM)</div>
          <label style="font-size:11px;color:var(--text2);display:block;margin-bottom:6px">Risk-free Rate (Rf) %
            <input id="ts-dm-rf" type="number" step="0.1" value="2.5"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <label style="font-size:11px;color:var(--text2);display:block;margin-bottom:6px">Beta (β)
            <input id="ts-dm-beta" type="number" step="0.05" value="1.00"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <label style="font-size:11px;color:var(--text2);display:block">Equity Risk Premium %
            <input id="ts-dm-erp" type="number" step="0.1" value="5.5"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <div id="ts-dm-coe-out" style="font-size:11px;color:var(--text2);margin-top:8px"></div>
        </div>
        <div>
          <div style="font-size:10.5px;color:var(--text2);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">ขั้น 2 — Cost of Debt</div>
          <label style="font-size:11px;color:var(--text2);display:block;margin-bottom:6px">ดอกเบี้ยจ่ายเฉลี่ยต่อหนี้ %
            <input id="ts-dm-kd" type="number" step="0.1" value="${n(fc.cost_of_debt_pretax, 4.5).toFixed(1)}"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <div style="font-size:10.5px;color:var(--text2)">Tax Rate ใช้ค่าจากช่อง Tax Rate ด้านบน</div>
          <div id="ts-dm-cod-out" style="font-size:11px;color:var(--text2);margin-top:8px"></div>
        </div>
        <div>
          <div style="font-size:10.5px;color:var(--text2);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px">ขั้น 3 — Capital Structure</div>
          <label style="font-size:11px;color:var(--text2);display:block;margin-bottom:6px">มูลค่าส่วนของผู้ถือหุ้น (E) ${munit}
            <input id="ts-dm-eq" type="number" step="1" value="${equityDefault.toFixed(0)}"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <label style="font-size:11px;color:var(--text2);display:block">มูลค่าหนี้สินที่มีดอกเบี้ย (D) ${munit}
            <input id="ts-dm-debt" type="number" step="1" value="${debtDefault.toFixed(0)}"
              class="scr-input" style="display:block;width:100%;margin-top:3px" oninput="_tsDcfModelRecalc()"></label>
          <div id="ts-dm-capstruct-out" style="font-size:11px;color:var(--text2);margin-top:8px"></div>
        </div>
      </div>
      <div id="ts-dm-wacc-out" style="margin-top:12px;padding-top:10px;border-top:1px solid var(--border)"></div>
      <div style="margin-top:10px;padding-top:10px;border-top:1px dashed var(--border);display:flex;gap:20px;flex-wrap:wrap;align-items:center">
        <label style="font-size:11.5px;color:var(--text2);display:flex;align-items:center;gap:5px;cursor:pointer">
          <input type="radio" name="ts-dm-wacc-mode" id="ts-dm-wacc-mode-calc" checked onchange="_tsDcfModelRecalc()">
          ใช้ WACC ที่คำนวณให้ (3 ขั้นด้านบน)</label>
        <label style="font-size:11.5px;color:var(--text2);display:flex;align-items:center;gap:5px;cursor:pointer">
          <input type="radio" name="ts-dm-wacc-mode" id="ts-dm-wacc-mode-manual" onchange="_tsDcfModelRecalc()">
          กรอก WACC เอง:
          <input id="ts-dm-wacc-manual" type="number" step="0.25" value="${dcf.discount_rate_default}"
            class="scr-input" style="width:80px" oninput="_tsDcfModelWaccManualInput()">%</label>
      </div>
    </div>

    <div id="ts-dm-table"></div>
    <div id="ts-dm-summary" style="margin-top:10px"></div>
    <div style="font-size:10px;color:var(--text2);margin-top:8px">⚠ D&amp;A / CapEx / Cost of Debt ตั้งต้นจาก % ต่อ Revenue หรือ % ต่อหนี้ของปีล่าสุดปีเดียว (ไม่ใช่ค่าเฉลี่ยหลายปี) — หุ้นที่เพิ่งลงทุนหนัก/มี one-off ควรปรับเองก่อนเชื่อผลลัพธ์ · NWC % Revenue คือระดับ Working Capital ปีล่าสุด ไม่ใช่การเปลี่ยนแปลง (ผลกระทบต่อ FCFF คำนวณจาก % นี้ × ส่วนต่างรายได้ปีนั้นเทียบปีก่อน) · Rf/Beta/ERP เป็นค่ากรอกเองล้วนๆ ไม่มีในงบการเงิน</div>
  </div>`;
}

function _tsDcfModelRecalc() {
  const dcf = _tsData?.dcf;
  const fc = dcf?.forecast;
  const tblBox = document.getElementById('ts-dm-table');
  const sumBox = document.getElementById('ts-dm-summary');
  const coeBox = document.getElementById('ts-dm-coe-out');
  const codBox = document.getElementById('ts-dm-cod-out');
  const capBox = document.getElementById('ts-dm-capstruct-out');
  const waccBox = document.getElementById('ts-dm-wacc-out');
  if (!fc || !tblBox || !sumBox || !waccBox) return;
  const cw = _tsCurWord();               // 'บาท' (TH) · 'USD'/'HKD'/'JPY' · '' (lite อื่น)
  const munit = _tsMilUnit(cw);          // label หน่วยตาราง — ตรงกับ _tsDcfModelHtml
  const perShare = cw ? cw + '/หุ้น' : '/หุ้น';
  const num = (id, dflt) => { const v = parseFloat(document.getElementById(id)?.value); return Number.isFinite(v) ? v : dflt; };
  const g13 = num('ts-dm-g13', 5) / 100, g45 = num('ts-dm-g45', 3) / 100;
  const ebitM = num('ts-dm-ebitm', 10) / 100, tax = num('ts-dm-tax', 20) / 100;
  const daPct = num('ts-dm-da', 3) / 100, capexPct = num('ts-dm-capex', 3) / 100, nwcPct = num('ts-dm-nwc', 0) / 100;
  const tg = num('ts-dm-tg', dcf.terminal_growth_default) / 100;
  const years = parseInt(document.getElementById('ts-dm-years')?.value || '5', 10);

  // ---- WACC: ขั้น 1 Cost of Equity (CAPM) ----
  const rf = num('ts-dm-rf', 2.5) / 100, beta = num('ts-dm-beta', 1) , erp = num('ts-dm-erp', 5.5) / 100;
  const costEquity = rf + beta * erp;
  coeBox.innerHTML = `Cost of Equity (Re) = ${(rf * 100).toFixed(2)}% + ${beta.toFixed(2)} × ${(erp * 100).toFixed(2)}% = <b style="color:var(--text)">${(costEquity * 100).toFixed(2)}%</b>`;

  // ---- ขั้น 2 Cost of Debt (หลังภาษี) ----
  const kdPretax = num('ts-dm-kd', 4.5) / 100;
  const costDebtAfterTax = kdPretax * (1 - tax);
  codBox.innerHTML = `Cost of Debt หลังภาษี = ${(kdPretax * 100).toFixed(2)}% × (1 − ${(tax * 100).toFixed(1)}%) = <b style="color:var(--text)">${(costDebtAfterTax * 100).toFixed(2)}%</b>`;

  // ---- ขั้น 3 Capital Structure ----
  const eqVal = Math.max(0, num('ts-dm-eq', 0)), debtVal = Math.max(0, num('ts-dm-debt', 0));
  const totalV = eqVal + debtVal;
  const eOverV = totalV > 0 ? eqVal / totalV : 1, dOverV = totalV > 0 ? debtVal / totalV : 0;
  capBox.innerHTML = totalV > 0
    ? `E/V = ${(eOverV * 100).toFixed(1)}% · D/V = ${(dOverV * 100).toFixed(1)}%`
    : `<span style="color:var(--red)">ต้องมี E หรือ D มากกว่า 0</span>`;

  const waccCalc = eOverV * costEquity + dOverV * costDebtAfterTax;
  // เลือกได้ว่าจะใช้ WACC ที่คำนวณจาก 3 ขั้นด้านบน หรือกรอกเองตรงๆ (radio ts-dm-wacc-mode)
  const waccManualMode = document.getElementById('ts-dm-wacc-mode-manual')?.checked;
  const waccManual = num('ts-dm-wacc-manual', dcf.discount_rate_default) / 100;
  const wacc = waccManualMode ? waccManual : waccCalc;
  waccBox.innerHTML = `<div style="font-size:11px;color:var(--text2)">WACC ที่คำนวณ = (E/V × Re) + (D/V × Rd หลังภาษี) = (${(eOverV * 100).toFixed(1)}% × ${(costEquity * 100).toFixed(2)}%) + (${(dOverV * 100).toFixed(1)}% × ${(costDebtAfterTax * 100).toFixed(2)}%) = ${(waccCalc * 100).toFixed(2)}%</div>
    <div style="font-size:22px;font-weight:800;margin-top:4px">WACC ที่ใช้จริง = ${(wacc * 100).toFixed(2)}% <span style="font-size:11px;font-weight:400;color:var(--text2)">(${waccManualMode ? 'กรอกเอง' : 'คำนวณให้'})</span></div>`;

  if (wacc <= tg) {
    tblBox.innerHTML = '';
    sumBox.innerHTML = `<div class="empty" style="padding:4px 0;font-size:11.5px;color:var(--red)">⚠ WACC ต้องมากกว่า Terminal Growth ถึงจะคำนวณ Terminal Value ได้</div>`;
    return;
  }

  const fmt = v => Number.isFinite(v) ? (v / 1e6).toLocaleString('en-US', { maximumFractionDigits: 0 }) : '—';

  // แถว TTM (ฐาน) — ข้อมูลจริงจากงบปีล่าสุด (ไม่ใช่พยากรณ์ ไม่รวมใน PV) แสดงไว้เทียบกับปีพยากรณ์
  // NWC ในแถวนี้โชว์ 'ระดับ' Working Capital ปัจจุบัน (บาท) เฉยๆ ไม่บวกเข้า ttmFcff เพราะไม่ใช่
  // กระแสเงินสด (ต่างจากปีพยากรณ์ที่คำนวณ 'ผลกระทบจาก ΔRevenue' — แถว TTM ไม่มีปีก่อนหน้าให้เทียบ)
  const ttmDa = fc.revenue * (fc.da_pct_revenue || 0) / 100;
  const ttmCapex = fc.revenue * (fc.capex_pct_revenue || 0) / 100;
  const ttmNwcLevel = fc.revenue * (fc.nwc_pct_revenue || 0) / 100;
  const ttmNoplat = fc.ebit * (1 - tax);
  const ttmFcff = ttmNoplat + ttmDa - ttmCapex;
  const ttmRowHtml = `<tr style="color:var(--blue)">
    <td style="font-weight:700">TTM (ฐาน)</td><td style="text-align:right">—</td>
    <td style="text-align:right">${fmt(fc.revenue)}</td><td style="text-align:right">${fmt(fc.ebit)}</td>
    <td style="text-align:right">${(fc.ebit_margin || 0).toFixed(1)}%</td><td style="text-align:right">${fmt(ttmNoplat)}</td>
    <td style="text-align:right">${fmt(ttmDa)}</td><td style="text-align:right">${fmt(ttmCapex)}</td>
    <td style="text-align:right;color:${ttmNwcLevel < 0 ? 'var(--red)' : 'var(--text)'}" title="ระดับ Working Capital ปัจจุบัน — ไม่ได้รวมในผลรวม FCFF แถวนี้ (ไม่ใช่กระแสเงินสด)">${fmt(ttmNwcLevel)}</td>
    <td style="text-align:right;font-weight:700">${fmt(ttmFcff)}</td></tr>`;

  // ทุกช่อง (Revenue/EBIT/NOPLAT/D&A/CapEx/NWC) ต่อปี: ตั้งต้นจากสูตร (โต% × Revenue ปีก่อน,
  // EBIT Margin, Tax Rate, % ต่อ Revenue ด้านบน) แต่กดแก้ตัวเลขตรงในตารางรายปีเองได้ทุกช่อง —
  // แก้ Revenue ปีไหน ปีถัดไปคำนวณสูตรต่อจากค่าที่แก้แล้ว (ไม่ใช่ค่าตามสูตรเดิม) เก็บ override ไว้
  // ใน _tsDcfModelOverrides คงอยู่ข้าม recalc จนกว่าจะโหลดหุ้นตัวใหม่ · EBIT% เป็นอัตราส่วน
  // (EBIT/Revenue) คำนวณจากค่าจริงเสมอ ไม่ใช่ช่องแก้ตรงๆ · NWC default ใช้ 'ผลต่างรายได้ปีนี้เทียบ
  // ปีก่อน' คูณ nwcPct (ระดับ) ไม่ใช่รายได้เต็มปี ดูคอมเมนต์ก่อนฟังก์ชันนี้
  let revenue = fc.revenue;
  const rows = [];
  let pvSum = 0, lastFcff = 0;
  for (let t = 1; t <= years; t++) {
    const g = t <= 3 ? g13 : g45;
    const revDefault = revenue * (1 + g);
    const rev = _tsDcfModelOverrides.revenue[t] ?? revDefault;
    const gDisplay = revenue ? (rev / revenue - 1) : g;

    const ebitDefault = rev * ebitM;
    const ebit = _tsDcfModelOverrides.ebit[t] ?? ebitDefault;

    const noplatDefault = ebit * (1 - tax);
    const noplat = _tsDcfModelOverrides.noplat[t] ?? noplatDefault;

    const daDefault = rev * daPct, capexDefault = rev * capexPct;
    // nwcPct = ระดับ NWC ÷ Revenue (ไม่ใช่การเปลี่ยนแปลง) — รายได้โตขึ้นเท่าไหร่ต้องใช้เงินทุน
    // หมุนเวียนเพิ่มตามอัตราส่วนนี้ ผลกระทบต่อกระแสเงินสด = −(nwcPct × ΔRevenue ปีนี้เทียบปีก่อน)
    const nwcDefault = -(nwcPct * (rev - revenue));
    const da = _tsDcfModelOverrides.da[t] ?? daDefault;
    const capex = _tsDcfModelOverrides.capex[t] ?? capexDefault;
    const nwc = _tsDcfModelOverrides.nwc[t] ?? nwcDefault;
    const fcff = noplat + da - capex + nwc;
    const pv = fcff / Math.pow(1 + wacc, t);
    pvSum += pv;
    lastFcff = fcff;
    rows.push({ t, g: gDisplay, revenue: rev, ebit, ebitPct: rev ? ebit / rev * 100 : 0, noplat, da, capex, nwc, fcff });
    revenue = rev;
  }
  const tv = lastFcff * (1 + tg) / (wacc - tg);
  const pvTv = tv / Math.pow(1 + wacc, years);

  const cellInput = (field, t, v, w) => `<input type="number" step="1" value="${(v / 1e6).toFixed(0)}"
    data-field="${field}" data-t="${t}" onchange="_tsDcfModelCellEdit(this)"
    class="scr-input" style="width:${w || 76}px;text-align:right;font-size:11px;padding:2px 4px">`;
  const rowsHtml = rows.map(r => `<tr>
    <td>ปี ${r.t}</td><td style="text-align:right;color:${r.g >= 0 ? 'var(--green)' : 'var(--red)'}">${r.g >= 0 ? '+' : ''}${(r.g * 100).toFixed(1)}%</td>
    <td style="text-align:right">${cellInput('revenue', r.t, r.revenue, 92)}</td>
    <td style="text-align:right">${cellInput('ebit', r.t, r.ebit, 88)}</td>
    <td style="text-align:right">${r.ebitPct.toFixed(1)}%</td>
    <td style="text-align:right">${cellInput('noplat', r.t, r.noplat, 88)}</td>
    <td style="text-align:right">${cellInput('da', r.t, r.da, 76)}</td>
    <td style="text-align:right">${cellInput('capex', r.t, r.capex, 76)}</td>
    <td style="text-align:right">${cellInput('nwc', r.t, r.nwc, 76)}</td>
    <td style="text-align:right;font-weight:700;color:${r.fcff >= 0 ? 'var(--green)' : 'var(--red)'}">${fmt(r.fcff)}</td>
  </tr>`).join('');
  tblBox.innerHTML = `<div style="overflow-x:auto"><table class="tbl" style="width:100%;font-size:11px">
    <thead><tr><th></th><th style="text-align:right">โต%</th><th style="text-align:right">Revenue ✏️</th>
    <th style="text-align:right">EBIT ✏️</th><th style="text-align:right">EBIT%</th><th style="text-align:right">NOPLAT ✏️</th>
    <th style="text-align:right">D&amp;A ✏️</th><th style="text-align:right">CapEx ✏️</th><th style="text-align:right">NWC ✏️</th>
    <th style="text-align:right">FCFF</th></tr></thead><tbody>${ttmRowHtml}${rowsHtml}</tbody></table></div>
    <div style="font-size:10px;color:var(--text2);margin-top:4px">หน่วย: ${munit} (หน่วยเดียวกับ Market Cap) · ✏️ = กดตัวเลขในช่องนั้นๆ เพื่อแก้เป็นค่าที่ตั้งเองรายปีได้ (เว้นว่างเพื่อกลับไปใช้สูตรจากช่อง % ด้านบน) — แก้ Revenue ปีไหน ปีถัดไปจะคำนวณต่อจากค่าที่แก้แล้ว, EBIT% เป็นอัตราส่วนคำนวณจาก EBIT/Revenue เสมอไม่มีช่องแก้ตรงๆ, TTM (ฐาน) เป็นข้อมูลจริงแก้ไม่ได้</div>`;

  const netCash = dcf.net_cash || 0, netDebt = -netCash;
  const ev = pvSum + pvTv;
  const equityValue = ev - netDebt;
  const price = dcf.price, shares = (dcf.mkt_cap && price) ? dcf.mkt_cap / price : null;
  const intrinsic = shares ? equityValue / shares : null;
  const upside = (intrinsic != null && price) ? (intrinsic / price - 1) * 100 : null;

  sumBox.innerHTML = `<div class="card" style="padding:12px;background:var(--card2)">
    <div style="display:flex;gap:20px;flex-wrap:wrap;font-size:11.5px;margin-bottom:8px">
      <div>PV of Forecast FCFF<br><b>${fmt(pvSum)}</b></div>
      <div>PV of Terminal Value<br><b>${fmt(pvTv)}</b></div>
      <div>Enterprise Value<br><b>${fmt(ev)}</b></div>
      <div>Net Debt<br><b>${fmt(netDebt)}</b></div>
      <div>Market Cap (Equity)<br><b>${fmt(equityValue)}</b></div>
    </div>
    <div style="font-size:20px;font-weight:800">${intrinsic != null ? intrinsic.toFixed(2) : '—'} ${perShare}
      ${upside != null ? `<span style="font-size:13px;font-weight:600;margin-left:6px;color:${upside > 0 ? 'var(--green)' : 'var(--red)'}">(${upside > 0 ? '+' : ''}${upside.toFixed(1)}%)</span>` : ''}</div>
    <div style="font-size:10.5px;color:var(--text2)">ราคาปัจจุบัน ${price != null ? price.toFixed(2) : '—'}${cw ? ' ' + cw : ''} · Intrinsic Price = Market Cap (Equity) ÷ จำนวนหุ้น (${shares != null ? (shares / 1e6).toLocaleString('en-US', { maximumFractionDigits: 0 }) : '—'} ล้านหุ้น)</div>
  </div>`;
}

// สรุปสูตรที่ใช้จริงในหน้านี้ ให้กดดูได้ (ไม่กางไว้ตลอดกันรก) — ต้องอัปเดตข้อความนี้เองถ้าแก้สูตรใน
// _dcfPvOfStream/_dcfImpliedGrowth/_dcfForwardFairValuePerShare ด้านล่าง เพราะเป็น string คงที่ไม่ได้ derive จาก code
function _dcfFormulaNoteHtml() {
  return `<details style="margin-bottom:10px">
    <summary style="cursor:pointer;font-size:11px;color:var(--text2)">📐 สูตรที่ใช้คำนวณ</summary>
    <div style="font-size:11px;color:var(--text2);margin-top:8px;line-height:1.6">
      <div style="margin-bottom:8px"><b style="color:var(--text)">ค่าตั้งต้น</b><br>
        FCF₀ = Free Cash Flow ปีล่าสุด (งบ annual ไม่ใช่ TTM/ค่าเฉลี่ย) ·
        EV = มูลค่าตลาด − เงินสดสุทธิ · shares = มูลค่าตลาด / ราคา</div>
      <div style="margin-bottom:8px"><b style="color:var(--text)">PV ของกระแสเงินสด (10 ปี + Terminal)</b><br>
        <code>CFₜ = CFₜ₋₁ × (1 + g(t))</code>, t = 1..10<br>
        <code>PV = Σ CFₜ/(1+r)ᵗ + [CF₁₀×(1+g_term)/(r−g_term)] / (1+r)¹⁰</code><br>
        Terminal Value ใช้สูตร Gordon Growth ธรรมดา</div>
      <div style="margin-bottom:8px"><b style="color:var(--text)">Reverse DCF</b><br>
        หา g คงที่ตลอด 10 ปีที่ทำให้ PV(g) = EV ด้วยวิธี bisection (ช่วงค้นหา −30% ถึง +60%)
        แล้วเทียบกับ CAGR กำไร/รายได้ในอดีต</div>
      <div style="margin-bottom:8px"><b style="color:var(--text)">Forward DCF (3 ฉาก)</b><br>
        โตตามอัตราที่กรอกในปี 1-5 แล้วลดเชิงเส้นเข้าหา Terminal Growth ในปี 6-10:<br>
        <code>g(t) = g₁₋₅</code> เมื่อ t ≤ 5, <code>g(t) = g₁₋₅ + (g_term − g₁₋₅)×(t−5)/5</code> เมื่อ t = 6..10<br>
        <code>Fair Value/หุ้น = (PV + เงินสดสุทธิ) / shares</code></div>
      <div>อัตราคิดลด (Discount Rate) และ Terminal Growth ปรับได้จากช่องด้านบน · Sensitivity ใช้สูตร Forward DCF เดิมคำนวณซ้ำในแต่ละช่องของตาราง</div>
    </div>
  </details>`;
}

// ค่าเริ่มต้นแบบคงที่ (ผู้ใช้กำหนดเอง) — เดิมคำนวณจาก CAGR อดีต ปุ่ม "ใช้ CAGR อดีต" ยังทำแบบเดิมได้
const DCF_SCENARIO_DEFAULTS = { bear: 10, base: 15, bull: 25 };
const DCF_SENS_GROWTH_DEFAULT = '5, 10, 15, 20, 25';
const DCF_SENS_DISC_DEFAULT = '6, 7.5, 9, 10.5, 12';

// แปลง "5, 10, 15" -> [5,10,15] (ทิ้งค่าที่ไม่ใช่ตัวเลข) ถ้าว่าง/พังหมดคืน fallback
function _dcfParseAxis(raw, fallback) {
  const vals = String(raw || '').split(',').map(s => parseFloat(s.trim())).filter(v => Number.isFinite(v));
  return vals.length ? vals.slice(0, 8) : fallback;
}

// ตั้ง Base = CAGR อดีต แล้ว Bear/Bull = Base ∓ spread (สูตร spread เดิมก่อนเปลี่ยนมาเป็นกรอกเอง)
function _tsDcfUseHistGrowth() {
  const dcf = _tsData?.dcf;
  const hist = dcf?.profit_cagr ?? dcf?.rev_cagr ?? null;
  if (hist == null) { alert('หุ้นตัวนี้ไม่มี CAGR กำไร/รายได้ในอดีตให้ใช้'); return; }
  const base = Math.max(-10, Math.min(hist, 25));
  const spread = Math.max(4, Math.min(Math.abs(base) * 0.4, 12));
  const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = v.toFixed(1); };
  set('ts-dcf-g-bear', Math.max(-10, base - spread));
  set('ts-dcf-g-base', base);
  set('ts-dcf-g-bull', Math.min(25, base + spread));
  _tsDcfRecalc();
}

function _dcfPvOfStream(fcf0, growthFn, r, years, terminalGrowth) {
  let pv = 0, cf = fcf0;
  for (let t = 1; t <= years; t++) {
    cf = cf * (1 + growthFn(t));
    pv += cf / Math.pow(1 + r, t);
  }
  const tv = cf * (1 + terminalGrowth) / (r - terminalGrowth);
  pv += tv / Math.pow(1 + r, years);
  return pv;
}

function _dcfImpliedGrowth(fcf0, ev, r, terminalGrowth, years = 10) {
  if (fcf0 <= 0 || r <= terminalGrowth) return null;
  const f = g => _dcfPvOfStream(fcf0, () => g, r, years, terminalGrowth) - ev;
  let lo = -0.3, hi = 0.6, flo = f(lo), fhi = f(hi);
  if ((flo > 0) === (fhi > 0)) return null;  // ไม่มี g ในช่วงที่ทำให้สมการเท่ากัน (extreme case)
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2, fm = f(mid);
    if (Math.abs(fm) < 1e-6 * Math.abs(ev || 1)) return mid;
    if ((fm > 0) === (flo > 0)) { lo = mid; flo = fm; } else { hi = mid; }
  }
  return (lo + hi) / 2;
}

function _dcfForwardFairValuePerShare(fcf0, r, g1_5, terminalGrowth, netCash, shares) {
  if (r <= terminalGrowth || !shares) return null;
  const growthFn = t => t <= 5 ? g1_5 : g1_5 + (terminalGrowth - g1_5) * ((t - 5) / 5);
  const pv = _dcfPvOfStream(fcf0, growthFn, r, 10, terminalGrowth);
  return (pv + netCash) / shares;
}

function _tsDcfRecalc() {
  const dcf = _tsData?.dcf;
  _tsDcfBaseFairValue = null;   // reset ก่อนทุกครั้ง — เติมกลับตอนคำนวณ scenarios สำเร็จ
  const revBox = document.getElementById('ts-dcf-reverse');
  const fwdBox = document.getElementById('ts-dcf-forward');
  const sensBox = document.getElementById('ts-dcf-sens');
  if (!dcf || !revBox || !fwdBox || !sensBox || dcf.is_financial_sector ||
      dcf.fcf == null || !dcf.mkt_cap || !dcf.price) return;
  const rInput = document.getElementById('ts-dcf-discount'), tgInput = document.getElementById('ts-dcf-terminal');
  // Number.isFinite แทน || — parseFloat('0') ให้ 0 ซึ่งเป็น falsy ทำให้ || ตกไปใช้ default
  // เงียบๆ ทั้งที่ผู้ใช้พิมพ์ 0% มาจริงๆ (Terminal Growth 0% เป็นค่าที่ใส่ได้ตามปกติ min="0")
  const rRaw = parseFloat(rInput?.value), tgRaw = parseFloat(tgInput?.value);
  const r = (Number.isFinite(rRaw) ? rRaw : dcf.discount_rate_default) / 100;
  const tg = (Number.isFinite(tgRaw) ? tgRaw : dcf.terminal_growth_default) / 100;
  const price = dcf.price, shares = dcf.mkt_cap / price, netCash = dcf.net_cash || 0, ev = dcf.mkt_cap - netCash;
  const histGrowth = dcf.profit_cagr ?? dcf.rev_cagr ?? null;

  const impliedG = _dcfImpliedGrowth(dcf.fcf, ev, r, tg);
  let reverseHtml;
  if (impliedG == null) {
    reverseHtml = `<div style="margin-bottom:14px"><div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Reverse DCF</div>
      <div class="empty" style="padding:4px 0;font-size:11.5px">คำนวณไม่ได้ด้วยพารามิเตอร์นี้ (ลอง Discount Rate ให้สูงกว่า Terminal Growth มากขึ้น)</div></div>`;
  } else {
    const impliedPct = impliedG * 100;
    let cmpHtml = '';
    if (histGrowth != null) {
      const diff = impliedPct - histGrowth;
      const [txt, color] = diff < -3 ? ['ตลาดคาดต่ำกว่าที่เคยทำได้ในอดีต (อาจถูก)', 'var(--green)']
        : diff > 3 ? ['ตลาดคาดสูงกว่าที่เคยทำได้ในอดีต (ต้องเชื่อว่าธุรกิจเร่งตัว)', 'var(--red)']
        : ['ใกล้เคียงผลงานในอดีต (สมเหตุผล)', 'var(--text)'];
      cmpHtml = `<div style="font-size:11.5px;margin-top:4px;color:${color}">${txt} — เทียบ CAGR กำไร/รายได้ในอดีต ${histGrowth.toFixed(1)}%/ปี</div>`;
    }
    reverseHtml = `<div style="margin-bottom:14px">
      <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">Reverse DCF</div>
      <div style="font-size:20px;font-weight:800">${impliedPct.toFixed(1)}%/ปี</div>
      <div style="font-size:11px;color:var(--text2)">อัตราการโตของ FCF ที่ราคาปัจจุบันกำลังคาดไว้ (โต 10 ปี + Terminal ${(tg * 100).toFixed(2)}%)</div>
      ${cmpHtml}
    </div>`;
  }

  // อัตราโตปี 1-5 ของแต่ละฉาก มาจากช่องกรอก (default 10/15/25) — ไม่ผูกกับ CAGR อดีตแล้ว
  // ปุ่ม "ใช้ CAGR อดีต" ใน _tsDcfUseHistGrowth() เป็นทางลัดให้เติมค่าจากอดีตกลับเข้ามาเอง
  const gOf = (id, dflt) => {
    const v = parseFloat(document.getElementById(id)?.value);
    return Number.isFinite(v) ? v : dflt;
  };
  const scenarios = [
    { key: 'bear', label: 'Bear', gPct: gOf('ts-dcf-g-bear', DCF_SCENARIO_DEFAULTS.bear) },
    { key: 'base', label: 'Base', gPct: gOf('ts-dcf-g-base', DCF_SCENARIO_DEFAULTS.base) },
    { key: 'bull', label: 'Bull', gPct: gOf('ts-dcf-g-bull', DCF_SCENARIO_DEFAULTS.bull) },
  ].map(sc => {
    const gPct = sc.gPct;
    const fv = _dcfForwardFairValuePerShare(dcf.fcf, r, gPct / 100, tg, netCash, shares);
    const upside = fv != null ? (fv / price - 1) * 100 : null;
    return { ...sc, gPct, fv, upside };
  });
  _tsDcfBaseFairValue = scenarios.find(s => s.key === 'base')?.fv ?? null;
  const scenRows = scenarios.map(sc => `
    <tr><td style="font-weight:600">${sc.label}</td><td style="text-align:right">${sc.gPct.toFixed(1)}%</td>
      <td style="text-align:right">${sc.fv != null ? sc.fv.toFixed(2) : '—'}</td>
      <td style="text-align:right;color:${sc.upside > 0 ? 'var(--green)' : sc.upside < 0 ? 'var(--red)' : 'var(--text)'}">${sc.upside != null ? (sc.upside > 0 ? '+' : '') + sc.upside.toFixed(1) + '%' : '—'}</td></tr>`).join('');
  const histNote = histGrowth != null ? ` · CAGR กำไร/รายได้ในอดีต ${histGrowth.toFixed(1)}%/ปี` : '';
  const forwardHtml = `
    <div style="overflow-x:auto"><table class="tbl" style="width:100%;max-width:440px">
      <thead><tr><th>ฉาก</th><th style="text-align:right">โต ปี1-5</th><th style="text-align:right">Fair Value</th><th style="text-align:right">Upside</th></tr></thead>
      <tbody>${scenRows}</tbody></table></div>
    <div style="font-size:10.5px;color:var(--text2);margin-top:4px">ราคาปัจจุบัน ${price.toFixed(2)}${histNote}</div>`;

  // แกน sensitivity มาจากช่องกรอก (default โต 5-25% / disc 6-12%) — ไม่ผูกกับ CAGR อดีตแล้ว
  const growthAxis = _dcfParseAxis(document.getElementById('ts-dcf-sens-growth')?.value, [5, 10, 15, 20, 25]);
  const rAxis = _dcfParseAxis(document.getElementById('ts-dcf-sens-disc')?.value, [6, 7.5, 9, 10.5, 12]);
  const baseG = scenarios.find(s => s.key === 'base')?.gPct;
  const sensHead = `<tr><th>โต% \\ Disc%</th>${rAxis.map(rr => `<th style="text-align:right">${rr.toFixed(1)}</th>`).join('')}</tr>`;
  const sensRows = growthAxis.map(g => {
    const cells = rAxis.map(rr => {
      const rDec = rr / 100;
      const fv = _dcfForwardFairValuePerShare(dcf.fcf, rDec, g / 100, tg, netCash, shares);
      // ไฮไลต์ช่องที่ตรงกับสมมติฐานหลักด้านบน (Base growth + Discount Rate ที่ตั้งไว้)
      const isBase = baseG != null && Math.abs(g - baseG) < 0.01 && Math.abs(rr - r * 100) < 0.01;
      return `<td style="text-align:right;${isBase ? 'font-weight:700;background:var(--card2)' : ''}">${fv != null ? fv.toFixed(1) : '—'}</td>`;
    }).join('');
    return `<tr><td style="font-weight:600">${g.toFixed(1)}%</td>${cells}</tr>`;
  }).join('');
  const sensHtml = `<div style="overflow-x:auto"><table class="tbl" style="font-size:11px">${sensHead}<tbody>${sensRows}</tbody></table></div>`;

  revBox.innerHTML = reverseHtml;
  fwdBox.innerHTML = forwardHtml;
  sensBox.innerHTML = sensHtml;
}

// ---------- มูลค่าเหมาะสมทางเลือก (นอกจาก DCF): PEG / Graham Number / DDM / Justified P-B ----------
// ทั้ง 4 แบบคำนวณฝั่ง client จากวัตถุดิบใน d.valuation_models (+ d.valuation/d.quality/d.dividend
// ที่มีอยู่แล้ว) — เหมือนแนวทาง DCF ด้านบน ทุกช่องแก้ค่าเองได้ (ค่าเริ่มต้นมาจาก snapshot ล่าสุด)
function _altVerdictFromUpside(upsidePct) {
  if (upsidePct == null) return null;
  if (upsidePct >= 10) return 'cheap';
  if (upsidePct <= -10) return 'expensive';
  return 'normal';
}

function _altUpsideHtml(fair, price) {
  if (fair == null || !price) return { fairText: '—', upsideHtml: '' };
  const upside = (fair / price - 1) * 100;
  const [lbl, lblColor] = _tsValLabel(_altVerdictFromUpside(upside));
  const upsideColor = upside > 0 ? 'var(--green)' : upside < 0 ? 'var(--red)' : 'var(--text)';
  return {
    fairText: fair.toFixed(2),
    upsideHtml: `<span style="color:${upsideColor}">${upside > 0 ? '+' : ''}${upside.toFixed(1)}%</span>
      <span style="color:${lblColor};font-weight:600;margin-left:6px">${lbl}</span>`,
  };
}

function _altPeg(pe, growthPct) {
  if (pe == null || pe <= 0 || growthPct == null || growthPct <= 0) return null;
  return pe / growthPct;
}

function _altGraham(eps, bvps) {
  if (eps == null || eps <= 0 || bvps == null || bvps <= 0) return null;
  return Math.sqrt(22.5 * eps * bvps);
}

function _altDdm(d0, rPct, gPct) {
  if (d0 == null || d0 <= 0 || rPct == null || gPct == null || rPct <= gPct) return null;
  const d1 = d0 * (1 + gPct / 100);
  return d1 / ((rPct - gPct) / 100);
}

function _altJustifiedPb(roePct, rPct, gPct, bvps) {
  if (roePct == null || rPct == null || gPct == null || bvps == null || bvps <= 0 || rPct <= gPct) return null;
  const jpb = (roePct - gPct) / (rPct - gPct);
  return jpb > 0 ? jpb * bvps : null;
}

function _altNav(bvps, targetPb) {
  if (bvps == null || bvps <= 0 || targetPb == null || targetPb <= 0) return null;
  return bvps * targetPb;
}

// EV/Sales ปัจจุบัน = EV ÷ ยอดขาย (EV = MktCap − เงินสดสุทธิ)
// ทางที่ถูก: ใช้ยอดขายจริง (salesActual = forecast.revenue งบ Yahoo ปีล่าสุด สกุลเดียวกับ MktCap)
// fallback (ไม่มี forecast เช่น กลุ่มการเงิน): PS ratio ปรับด้วยสัดส่วน EV/MktCap — แต่ PS จาก
// Finnomena เป็นค่า ณ "สิ้นไตรมาส" (live_scalable=false) ถ้าราคาขยับเยอะตั้งแต่ปิดงวด ค่าที่ได้จะ
// เพี้ยนตามส่วนต่างราคา (mktCap วันนี้ ÷ PS สิ้นงวด = ยอดขายจริง × ราคาวันนี้/ราคาสิ้นงวด)
function _altEvSalesCurrent(ps, mktCap, netCash, salesActual) {
  if (!mktCap) return null;
  const ev = mktCap - (netCash || 0);
  if (salesActual != null && salesActual > 0) return ev / salesActual;
  if (ps == null || ps <= 0) return null;
  return ps * (ev / mktCap);
}

function _altEvSalesFair(ps, mktCap, netCash, price, targetMultiple, salesActual) {
  const evSalesCur = _altEvSalesCurrent(ps, mktCap, netCash, salesActual);
  if (evSalesCur == null || evSalesCur <= 0 || targetMultiple == null || targetMultiple <= 0 || !price) return null;
  // ราคาแปรผันตรงกับ EV/Sales ที่ตั้งไว้ เทียบกับ EV/Sales ปัจจุบัน (Sales/shares คงที่)
  // แต่ net cash ไม่ได้แปรผันตามราคา — ปรับผ่าน EV แทนราคาตรงๆ ให้แม่นกว่า
  const shares = mktCap / price;
  const sales = (salesActual != null && salesActual > 0) ? salesActual : mktCap / ps;
  const impliedEv = targetMultiple * sales;
  return (impliedEv + (netCash || 0)) / shares;
}

function _altEpv(eps, costOfCapitalPct) {
  if (eps == null || eps <= 0 || costOfCapitalPct == null || costOfCapitalPct <= 0) return null;
  return eps / (costOfCapitalPct / 100);
}

// ไอคอน ⓘ แปะข้างชื่อวิธีแต่ละอัน hover ดูสูตร/วิธีอ่านค่าได้เลยไม่ต้องเลื่อนไปเปิด
// "สูตรที่ใช้คำนวณ" ด้านล่าง — ใช้ title attribute ของ browser ล้วน (ไม่ต้องมี JS/CSS เพิ่ม)
function _altTipIcon(text) {
  const esc = (text || '').replace(/"/g, '&quot;');
  return `<span title="${esc}" style="cursor:help;color:var(--text2);font-size:11px;margin-left:3px;border:1px solid var(--border);border-radius:50%;width:14px;height:14px;display:inline-flex;align-items:center;justify-content:center;line-height:1">ⓘ</span>`;
}

const ALT_VAL_TIPS = {
  peg: 'PEG = PE ÷ อัตราโตกำไร%/ปี\nต่ำกว่า 1 = ถูกเมื่อเทียบกับอัตราโต, สูงกว่า 2 = แพงเมื่อเทียบกับอัตราโต (กฎง่ายๆ ไม่ใช่กฎตายตัว)\nใช้ไม่ได้ถ้ากำไรติดลบ/หดตัว',
  graham: 'Graham Number = √(22.5 × EPS × BVPS)\nเพดานมูลค่าแบบอนุรักษ์นิยมของ Benjamin Graham เหมาะกับหุ้น value ที่กำไร+สินทรัพย์เป็นบวกสม่ำเสมอ\nใช้ไม่ได้ถ้า EPS หรือ BVPS ติดลบ',
  ddm: 'DDM (Gordon Growth) = D₀×(1+g) ÷ (r−g)\nD₀ = ปันผลปัจจุบัน (ราคา×Dividend Yield), r = Discount Rate, g = อัตราโตปันผลระยะยาว\nเหมาะกับหุ้นปันผลสม่ำเสมอ (แบงก์/REIT/สาธารณูปโภค) ต้องตั้ง r มากกว่า g เสมอ',
  jpb: 'Justified P/B = (ROE−g) ÷ (r−g) แล้วคูณ BVPS = Fair Value\nr = Cost of Equity, g = อัตราโตระยะยาว\nเหมาะกับกลุ่มการเงิน (แบงก์/ประกัน) ที่ DCF ใช้ไม่ได้เพราะ FCF ไม่มีความหมาย ต้องตั้ง r มากกว่า g เสมอ',
  nav: 'NAV = BVPS × Target P/BV\nปกติตั้ง Target ไว้ที่ 1.0× (ราคา = มูลค่าทางบัญชีพอดี)\nเหมาะกับ REIT/กองทุนอสังหาฯ/โฮลดิ้ง ที่สินทรัพย์ในงบตีมูลค่าตลาดได้ใกล้เคียงจริง ไม่เหมาะกับธุรกิจที่มูลค่าหลักอยู่ที่ intangible/แบรนด์',
  evs: 'EV/Sales = (มูลค่าตลาด − เงินสดสุทธิ) ÷ ยอดขาย\nเหมาะกับหุ้นเติบโตที่ยังขาดทุน/EBITDA ติดลบ (PEG/Graham/EPV ใช้คำนวณไม่ได้)\nระบบไม่มีค่าเฉลี่ยอุตสาหกรรมให้ — ค่าเริ่มต้น = อัตราส่วนปัจจุบันของหุ้นเอง ต้องไปเทียบเพื่อนร่วมกลุ่มเองจากหน้า "เทียบเพื่อน" แล้วกรอก Target',
  epv: 'Earnings Power Value (EPV) = Normalized EPS ÷ Cost of Capital\nสูตรของ Bruce Greenwald ไม่มีสมมติฐานการเติบโตเลย (conservative กว่า DCF/DDM/Graham)\nนี่เป็นเวอร์ชันต่อหุ้นแบบย่อ — ยังไม่ปรับเงินสดส่วนเกิน/หนี้ในงบ (EPV ตัวเต็ม = กำไร÷WACC + เงินสดส่วนเกิน − หนี้) จึงต่ำกว่ามูลค่ากิจการที่มีเงินสดมาก และสูงกว่าตัวที่หนี้เยอะ\nเหมาะใช้เป็น "เพดานล่าง" ของมูลค่า — ถ้าราคาต่ำกว่า EPV มาก มักปลอดภัยกว่าปกติ',
};

function _tsAltValHtml(d) {
  const vm = d.valuation_models;
  if (!vm) return '';
  const isFin = !!d.dcf?.is_financial_sector;
  const isReit = !!d.header?.is_reit;
  const finNote = isFin
    ? `<div style="font-size:11px;color:var(--text2);margin-bottom:6px">💡 กลุ่มการเงิน — DCF ใช้ไม่ได้ (ดูด้านบน) แต่ <b>Justified P/B</b> ด้านล่างเหมาะกับกลุ่มนี้เป็นพิเศษ เพราะอิงส่วนของผู้ถือหุ้น/ROE ไม่ใช่ FCF</div>`
    : '';
  const reitNote = isReit
    ? `<div style="font-size:11px;color:var(--text2);margin-bottom:10px">💡 REIT/กองทุนอสังหาฯ — ลอง <b>NAV</b> ด้านล่างประกอบ เพราะ BVPS ของกลุ่มนี้มักใกล้เคียงมูลค่าสินทรัพย์จริงมากกว่าธุรกิจทั่วไป</div>`
    : '';
  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:13px;font-weight:700;margin-bottom:4px">📐 มูลค่าเหมาะสมทางเลือก</div>
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:10px">อีก 7 วิธีนอกจาก DCF — ทุกช่องแก้ค่าเองได้ (ค่าเริ่มต้นจากงบล่าสุด) ใช้เป็นจุดตั้งต้นคิดต่อ ไม่ใช่คำแนะนำซื้อ/ขาย</div>
    ${finNote}${reitNote}
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px">
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">PEG Ratio${_altTipIcon(ALT_VAL_TIPS.peg)}</div>
        <label style="font-size:11px;color:var(--text2)">อัตราโตกำไร %/ปี
          <input id="ts-alt-peg-growth" type="number" step="0.5" value="${vm.growth_pct_default ?? ''}"
            class="scr-input" style="display:block;width:110px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        <div id="ts-alt-peg-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Graham Number${_altTipIcon(ALT_VAL_TIPS.graham)}</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <label style="font-size:11px;color:var(--text2)">EPS
            <input id="ts-alt-graham-eps" type="number" step="0.01" value="${vm.eps ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">BVPS
            <input id="ts-alt-graham-bvps" type="number" step="0.01" value="${vm.bvps ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        </div>
        <div id="ts-alt-graham-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">DDM (Gordon Growth)${_altTipIcon(ALT_VAL_TIPS.ddm)}</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <label style="font-size:11px;color:var(--text2)">Discount Rate %
            <input id="ts-alt-ddm-r" type="number" step="0.5" value="${vm.discount_rate_default ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">โตปันผล %/ปี
            <input id="ts-alt-ddm-g" type="number" step="0.5" value="${(() => {
              // ค่าเริ่มต้น = min(CAGR ปันผล 5 ปี, terminal growth) — Gordon Growth ต้องมี g < r
              // เสมอ ถ้าปล่อย CAGR อดีตดิบๆ (หุ้นปันผลไทยหลายตัว 8-40%) มันจะ ≥ r default (TH 9%)
              // ทำให้การ์ดขึ้น error ทันทีตั้งแต่เปิด หรือถ้าใกล้ r พอดีจะพ่น fair value พุ่งเวอร์
              const c = d.dividend?.cagr_5y, tg = vm.terminal_growth_default;
              if (c == null) return tg ?? '';
              return tg == null ? c : Math.min(c, tg);
            })()}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        </div>
        <div id="ts-alt-ddm-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Justified P/B${_altTipIcon(ALT_VAL_TIPS.jpb)}</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <label style="font-size:11px;color:var(--text2)">ROE %
            <input id="ts-alt-jpb-roe" type="number" step="0.5" value="${vm.roe ?? ''}"
              class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">Cost of Equity %
            <input id="ts-alt-jpb-r" type="number" step="0.5" value="${vm.discount_rate_default ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">โต %
            <input id="ts-alt-jpb-g" type="number" step="0.5" value="${vm.terminal_growth_default ?? ''}"
              class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">BVPS
            <input id="ts-alt-jpb-bvps" type="number" step="0.01" value="${vm.bvps ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        </div>
        <div id="ts-alt-jpb-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">NAV (Net Asset Value)${_altTipIcon(ALT_VAL_TIPS.nav)}</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <label style="font-size:11px;color:var(--text2)">BVPS
            <input id="ts-alt-nav-bvps" type="number" step="0.01" value="${vm.bvps ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">Target P/BV ×
            <input id="ts-alt-nav-pb" type="number" step="0.1" value="1.0"
              class="scr-input" style="display:block;width:80px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        </div>
        <div id="ts-alt-nav-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">EV/Sales${_altTipIcon(ALT_VAL_TIPS.evs)}</div>
        <label style="font-size:11px;color:var(--text2)">Target EV/Sales × <span style="font-weight:400">(ค่าเริ่มต้น = ปัจจุบัน — ปรับเทียบเพื่อนร่วมกลุ่มเองจากหน้า "เทียบเพื่อน")</span>
          <input id="ts-alt-evs-target" type="number" step="0.1"
            value="${(() => { const v = _altEvSalesCurrent(d.valuation?.ps?.value, d.dcf?.mkt_cap, d.dcf?.net_cash, d.dcf?.forecast?.revenue); return v != null ? v.toFixed(2) : ''; })()}"
            class="scr-input" style="display:block;width:100px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        <div id="ts-alt-evs-out" style="margin-top:8px"></div>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Earnings Power Value${_altTipIcon(ALT_VAL_TIPS.epv)}</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <label style="font-size:11px;color:var(--text2)">Normalized EPS
            <input id="ts-alt-epv-eps" type="number" step="0.01" value="${vm.eps ?? ''}"
              class="scr-input" style="display:block;width:100px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
          <label style="font-size:11px;color:var(--text2)">Cost of Capital %
            <input id="ts-alt-epv-r" type="number" step="0.5" value="${vm.discount_rate_default ?? ''}"
              class="scr-input" style="display:block;width:90px;margin-top:3px" oninput="_tsAltValRecalc()"></label>
        </div>
        <div id="ts-alt-epv-out" style="margin-top:8px"></div>
      </div>
    </div>
    <details style="margin-top:10px">
      <summary style="cursor:pointer;font-size:11px;color:var(--text2)">📐 สูตรที่ใช้คำนวณ</summary>
      <div style="font-size:11px;color:var(--text2);margin-top:8px;line-height:1.6">
        <div style="margin-bottom:6px"><b style="color:var(--text)">PEG</b> = PE ÷ อัตราโตกำไร% (&lt;1 ถูกกว่าที่โต, &gt;2 แพงกว่าที่โต — กฎง่ายๆ ไม่ใช่กฎตายตัว)</div>
        <div style="margin-bottom:6px"><b style="color:var(--text)">Graham Number</b> = √(22.5 × EPS × BVPS) — เพดานมูลค่าแบบอนุรักษ์นิยมของ Benjamin Graham เหมาะกับหุ้น value/กำไร-สินทรัพย์เป็นบวกสม่ำเสมอ</div>
        <div style="margin-bottom:6px"><b style="color:var(--text)">DDM (Gordon Growth)</b> = D₀×(1+g) ÷ (r−g) — D₀ = ปันผลปัจจุบัน (ราคา×Yield) เหมาะกับหุ้นปันผลสม่ำเสมอ (แบงก์/REIT/สาธารณูปโภค) ต้องมี r &gt; g</div>
        <div style="margin-bottom:6px">Justified P/B = (ROE−g) ÷ (r−g) แล้ว × BVPS = Fair Value — เหมาะกับกลุ่มการเงินที่ DCF ใช้ไม่ได้ ต้องมี r &gt; g</div>
        <div style="margin-bottom:6px"><b style="color:var(--text)">NAV</b> = BVPS × Target P/BV — ปกติตั้ง 1.0× (ราคา = มูลค่าทางบัญชีพอดี) เหมาะกับ REIT/กองทุนอสังหาฯ/โฮลดิ้งที่สินทรัพย์ตีมูลค่าตลาดได้ใกล้เคียงจริง</div>
        <div style="margin-bottom:6px"><b style="color:var(--text)">EV/Sales</b> = (มูลค่าตลาด−เงินสดสุทธิ) ÷ ยอดขาย — เหมาะกับหุ้นเติบโตที่ยังขาดทุน/EBITDA ติดลบ (PEG/Graham/EPV ใช้ไม่ได้) ระบบไม่มีค่าเฉลี่ยกลุ่มอุตสาหกรรมให้ ต้องไปเทียบเองจากหน้า "เทียบเพื่อน" แล้วกรอก Target</div>
        <div><b style="color:var(--text)">Earnings Power Value (EPV)</b> = Normalized EPS ÷ Cost of Capital — ของ Bruce Greenwald ไม่มีสมมติฐานการเติบโตเลย (conservative กว่า DCF/DDM) เหมาะเป็นเพดานล่างของมูลค่า · เป็นเวอร์ชันต่อหุ้นแบบย่อ ยังไม่ปรับเงินสดส่วนเกิน/หนี้ในงบ (ตัวเต็ม = กำไร÷WACC + เงินสดส่วนเกิน − หนี้)</div>
      </div>
    </details>
  </div>`;
}

function _tsAltValRecalc() {
  const d = _tsData;
  const vm = d?.valuation_models;
  if (!vm) return;
  const price = d.header?.price;
  const pe = d.valuation?.pe?.value;

  // PEG
  const pegOut = document.getElementById('ts-alt-peg-out');
  if (pegOut) {
    const growth = parseFloat(document.getElementById('ts-alt-peg-growth')?.value);
    const peg = _altPeg(pe, Number.isFinite(growth) ? growth : null);
    if (peg == null) {
      pegOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี PE และอัตราโตเป็นบวก)</div>`;
    } else {
      const [lbl, lblColor] = peg < 1 ? _tsValLabel('cheap') : peg > 2 ? _tsValLabel('expensive') : _tsValLabel('normal');
      pegOut.innerHTML = `<div style="font-size:20px;font-weight:800">${peg.toFixed(2)}</div>
        <div style="font-size:11px;color:${lblColor};font-weight:600">${lbl}</div>
        <div style="font-size:10.5px;color:var(--text2)">PE ${pe != null ? pe.toFixed(2) : '—'}</div>`;
    }
  }

  // Graham Number
  const grahamOut = document.getElementById('ts-alt-graham-out');
  if (grahamOut) {
    const eps = parseFloat(document.getElementById('ts-alt-graham-eps')?.value);
    const bvps = parseFloat(document.getElementById('ts-alt-graham-bvps')?.value);
    const fair = _altGraham(Number.isFinite(eps) ? eps : null, Number.isFinite(bvps) ? bvps : null);
    if (fair == null || !price) {
      grahamOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี EPS และ BVPS เป็นบวก)</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      grahamOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">ราคาปัจจุบัน ${price.toFixed(2)}</div>`;
    }
  }

  // DDM
  const ddmOut = document.getElementById('ts-alt-ddm-out');
  if (ddmOut) {
    const divYield = d.dividend?.yield;
    const d0 = (divYield != null && price) ? price * divYield / 100 : null;
    const r = parseFloat(document.getElementById('ts-alt-ddm-r')?.value);
    const g = parseFloat(document.getElementById('ts-alt-ddm-g')?.value);
    const fair = _altDdm(d0, Number.isFinite(r) ? r : null, Number.isFinite(g) ? g : null);
    if (fair == null || !price) {
      ddmOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">${!d0 ? 'หุ้นนี้ไม่จ่ายปันผล/ไม่มีข้อมูล Yield' : 'Discount Rate ต้องมากกว่าอัตราโตปันผล'}</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      ddmOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">D₀ = ${d0 != null ? d0.toFixed(2) : '—'}/หุ้น</div>`;
    }
  }

  // Justified P/B
  const jpbOut = document.getElementById('ts-alt-jpb-out');
  if (jpbOut) {
    const roe = parseFloat(document.getElementById('ts-alt-jpb-roe')?.value);
    const r = parseFloat(document.getElementById('ts-alt-jpb-r')?.value);
    const g = parseFloat(document.getElementById('ts-alt-jpb-g')?.value);
    const bvpsRaw = parseFloat(document.getElementById('ts-alt-jpb-bvps')?.value);
    const bvps = Number.isFinite(bvpsRaw) ? bvpsRaw : vm.bvps;
    const fair = _altJustifiedPb(Number.isFinite(roe) ? roe : null, Number.isFinite(r) ? r : null,
      Number.isFinite(g) ? g : null, bvps);
    if (fair == null || !price) {
      jpbOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี ROE, BVPS และ Cost of Equity &gt; อัตราโต)</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      const curPb = d.valuation?.pbv?.value;
      jpbOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">Justified P/B ${(fair / bvps).toFixed(2)}×${curPb != null ? ` (ปัจจุบัน ${curPb}×)` : ''}</div>`;
    }
  }

  // NAV
  const navOut = document.getElementById('ts-alt-nav-out');
  if (navOut) {
    const bvpsRaw = parseFloat(document.getElementById('ts-alt-nav-bvps')?.value);
    const bvps = Number.isFinite(bvpsRaw) ? bvpsRaw : null;
    const targetPb = parseFloat(document.getElementById('ts-alt-nav-pb')?.value);
    const fair = _altNav(bvps, Number.isFinite(targetPb) ? targetPb : null);
    if (fair == null || !price) {
      navOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี BVPS และ Target P/BV เป็นบวก)</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      navOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">BVPS × ${targetPb.toFixed(2)}×</div>`;
    }
  }

  // EV/Sales
  const evsOut = document.getElementById('ts-alt-evs-out');
  if (evsOut) {
    const ps = d.valuation?.ps?.value, mktCap = d.dcf?.mkt_cap, netCash = d.dcf?.net_cash;
    const salesActual = d.dcf?.forecast?.revenue;
    const evsCur = _altEvSalesCurrent(ps, mktCap, netCash, salesActual);
    const target = parseFloat(document.getElementById('ts-alt-evs-target')?.value);
    const fair = _altEvSalesFair(ps, mktCap, netCash, price, Number.isFinite(target) ? target : null, salesActual);
    if (fair == null || !price) {
      evsOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี P/S และมูลค่าตลาด)</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      evsOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">EV/Sales ปัจจุบัน ${evsCur != null ? evsCur.toFixed(2) : '—'}×</div>`;
    }
  }

  // Earnings Power Value
  const epvOut = document.getElementById('ts-alt-epv-out');
  if (epvOut) {
    const eps = parseFloat(document.getElementById('ts-alt-epv-eps')?.value);
    const r = parseFloat(document.getElementById('ts-alt-epv-r')?.value);
    const fair = _altEpv(Number.isFinite(eps) ? eps : null, Number.isFinite(r) ? r : null);
    if (fair == null || !price) {
      epvOut.innerHTML = `<div class="empty" style="padding:2px 0;font-size:11.5px">ข้อมูลไม่พอ (ต้องมี EPS เป็นบวก)</div>`;
    } else {
      const { fairText, upsideHtml } = _altUpsideHtml(fair, price);
      epvOut.innerHTML = `<div style="font-size:20px;font-weight:800">${fairText}</div>
        <div style="font-size:11px">${upsideHtml}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:2px">ไม่มีสมมติฐานการเติบโต</div>`;
    }
  }
}

// hk_index_metrics.json เก็บ symbol แบบ "0700.HK" / jp_index_metrics.json แบบ "7203.T"
// (ให้ chart/header ใช้ตรงๆ) แต่ endpoint อื่น (news/filings/financials) ที่ผูกกับ namespace
// mirror ('FINN:HK:0700' / 'FINN:JP:7203') ต้องการรหัสดิบไม่มี suffix เสมอ — ตัดออกก่อนทุกจุดที่
// ข้ามไปหน้าอื่น (TH/US ไม่มี suffix อยู่แล้ว ตัดแล้วเหมือนเดิม) · ต้องตัด .T ด้วย ไม่งั้น
// _news_resolve_yf ฝั่ง backend เติม ".T" ซ้ำได้ "7203.T.T" หาข่าวหุ้นญี่ปุ่นไม่เจอ และ deep-link
// #fin/dr/JP:7203.T ไม่ตรง convention (_openMirrorStock ใช้ /\.(HK|T)$/i)
function _tsRawSym(sym) { return (sym || '').replace(/\.(HK|T)$/i, ''); }

async function _tsLoadNews(sym) {
  const el = document.getElementById('ts-news');
  if (!el) return;
  const mkt = _tsData?.market || 'TH';
  const qs = mkt === 'TH' ? '' : `?is_dr=1&market=${mkt}`;
  try {
    const r = await _fetchTimeout(`/api/stock-news/${encodeURIComponent(_tsRawSym(sym))}${qs}`, 35000);
    const d = await r.json();
    if (_tsData?.symbol !== sym) return;
    const rows = (d.rows || []).slice(0, 5);
    if (!rows.length) { el.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px">ไม่พบข่าว</div>'; return; }
    const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
    el.innerHTML = rows.map(r => `
      <div style="padding:7px 0;border-bottom:1px solid var(--border)">
        <div style="display:flex;gap:8px;align-items:baseline;flex-wrap:wrap;font-size:10.5px;color:var(--text2);margin-bottom:2px">
          <span>${esc(r.publisher)}</span><span style="margin-left:auto">${_newsRelTime(r.ts)}</span>
        </div>
        <a href="${esc(_safeHref(r.url))}" target="_blank" rel="noopener" style="color:var(--text);font-size:12.5px;font-weight:600;text-decoration:none">${esc(r.title)}</a>
      </div>`).join('');
  } catch (e) {
    if (_tsData?.symbol !== sym) return;
    el.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px;color:var(--red)">โหลดข่าวไม่สำเร็จ</div>';
  }
}

// watchlist key: TH ใช้ symbol ตรงๆ, US/HK ใช้ prefix "US:"/"HK:" + h.symbol เต็ม (HK มี
// ".HK" ต่อท้ายอยู่แล้วเหมือน convention เดิมของทั้งแอป — ห้ามตัดออกด้วย _tsRawSym เหมือนเดิม
// เพราะ hkMap/renderWatchlist/_calResolveWatchlist ทุกจุดคาดหวังรหัสมี ".HK" ต่อท้าย ตัดออก
// แล้วจะหา entry ไม่เจอ กลายเป็นแถว "ไม่พบข้อมูล" ถาวร (พบจากรีวิวโค้ด 2026-08-02)
// หุ้น DR ที่ resolve เป็น underlying US/HK แล้ว (dr_symbol ไม่ว่าง) ใช้ "DR:"+dr_symbol แทน
// ให้ตรงกับ entry ที่หน้า DR สร้างไว้เดิม กันสร้าง entry ซ้ำซ้อนคนละ key กับหุ้นตัวเดียวกัน
function _tsWlKey(sym) {
  if (_tsData?.dr_symbol) return 'DR:' + _tsData.dr_symbol;
  const mkt = _tsData?.market || 'TH';
  return mkt === 'TH' ? sym : `${mkt}:${sym}`;
}

function _tsToggleWl(sym) {
  const key = _tsWlKey(sym);
  if (watchlist.includes(key)) removeFromWatchlist(key); else { watchlist.push(key); _wlSave(); renderWatchlist(); }
  const btn = document.getElementById('ts-wl-btn');
  if (btn) btn.textContent = watchlist.includes(key) ? '⭐ อยู่ใน Watchlist แล้ว' : '☆ เพิ่มเข้า Watchlist';
}

function _tsGoNews(sym) {
  const mkt = _tsData?.market || 'TH';
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes("'stock-news'"));
  showPage('stock-news', btn);
  const tab = mkt === 'TH' ? 'set' : 'dr';
  setNewsTab(tab, document.getElementById(tab === 'set' ? 'news-tab-set' : 'news-tab-dr'));
  document.getElementById('news-sym').value = _tsRawSym(sym);
  setTimeout(searchStockNews, 150);
}

function _tsGoFilings(sym) {
  const mkt = _tsData?.market || 'TH';
  // หน้า Filings เต็มมีแค่แท็บ TH/US/HK (fil-tab-th/us/hk) — ไม่มีแท็บ JP เลย เดิมเรียกตรงนี้
  // แบบไม่มี guard ทำให้ setFilTab('JP', null) ไม่มีแท็บติด active แล้ว searchFilings() ตกไปที่
  // _filLinksHK(sym) แบบเงียบๆ (เช็คแค่ TH/US แล้ว else เป็น HK) ได้ลิงก์ HKEX ผิดตัวของหุ้นญี่ปุ่น
  // — ปุ่มเรียกฟังก์ชันนี้ถูกซ่อนไปแล้วสำหรับ mkt==='JP' แต่กัน defensive ไว้เผื่อจุดเรียกอื่นในอนาคต
  if (mkt === 'JP') return;
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes("'filings'"));
  showPage('filings', btn);
  setFilTab(mkt, document.getElementById('fil-tab-' + mkt.toLowerCase()));
  document.getElementById('fil-sym').value = sym;   // _filLinksHK เองตัด .HK ให้อยู่แล้ว
  setTimeout(searchFilings, 150);
}

function _tsGoPeer(sym) {
  const mkt = _tsData?.market || 'TH';
  if (navOpenMode() === 'new') { openInternalHash(`#peer/${mkt.toLowerCase()}/${encodeURIComponent(sym)}`, true); return; }
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes("'peer'"));
  showPage('peer', btn);
  setPeerMarket(mkt, document.getElementById('peer-tab-' + mkt.toLowerCase()));
  loadPeerCompare(sym);
}

function _tsGoFin(sym) {
  const mkt = _tsData?.market || 'TH';
  openInternalHash(mkt === 'TH'
    ? '#fin/set/' + encodeURIComponent(sym)
    : `#fin/dr/${mkt}:${encodeURIComponent(_tsRawSym(sym))}`);
}

function _tsGoDividends(sym) {
  const mkt = _tsData?.market || 'TH';
  showPage('financials');
  if (mkt === 'TH') {
    setFinTab('set', document.getElementById('fin-tab-set-btn'));
    document.getElementById('fin-sym-set').value = sym;
  } else {
    setFinTab('dr', document.getElementById('fin-tab-dr-btn'));
    _finMirSelectMarket(mkt);
    document.getElementById('fin-sym-dr').value = _tsRawSym(sym);
  }
  setFinView('dividends', document.getElementById('fin-view-div-btn'));
  setTimeout(searchFinancials, 150);
}

function _tsQualityHtml(q, sym) {
  if (!q) return '';
  const tile = (label, val, color, tip) => `<div title="${tip || ''}" style="text-align:center;flex:1;min-width:88px${tip ? ';cursor:help' : ''}">
    <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em">${label}</div>
    <div style="font-size:15px;font-weight:700;color:${color || 'var(--text)'}">${val}</div></div>`;
  const roeC = q.roe == null ? '' : q.roe >= 15 ? 'var(--green)' : q.roe < 0 ? 'var(--red)' : '';
  const deC = q.de_ratio > 2 ? 'var(--red)' : '';
  const fcfC = q.fcf_yield == null ? '' : q.fcf_yield >= 5 ? 'var(--green)' : q.fcf_yield < 0 ? 'var(--red)' : '';
  const covC = q.dividend_coverage == null ? '' : q.dividend_coverage >= 1 ? 'var(--green)' : 'var(--red)';

  let fzHtml = '';
  if (q.f_score != null) {
    const fC = q.f_score >= 8 ? 'var(--green)' : q.f_score >= 6 ? '#7ee787' : q.f_score >= 4 ? '#d29922' : 'var(--red)';
    const note = q.f_score_max < 9 ? ` (เช็คได้ ${q.f_score_max}/9 ข้อ)` : '';
    const detail = (q.f_score_detail || []).map(x => `${x.pass === true ? '✓' : x.pass === false ? '✗' : '–'} ${x.label}`).join('\n');
    fzHtml += `<div title="Piotroski F-Score${note}\n${detail}" style="text-align:center;flex:1;min-width:110px;cursor:help">
      <div style="font-size:9px;color:var(--text2);text-transform:uppercase">F-Score</div>
      <div style="font-size:15px;font-weight:700;color:${fC}">${q.f_score}/9</div>
      <div style="margin-top:2px">${_fzExternalLinksHtml(sym)}</div></div>`;
  }
  if (q.z_variant === null && q.z_excluded_reason) {
    fzHtml += `<div title="${q.z_excluded_reason}" style="text-align:center;flex:1;min-width:88px;cursor:help">
      <div style="font-size:9px;color:var(--text2);text-transform:uppercase">Z-Score</div>
      <div style="font-size:15px;font-weight:700;color:var(--text2)">–</div></div>`;
  } else if (q.z_score != null) {
    const zoneColor = { safe: 'var(--green)', grey: '#d29922', distress: 'var(--red)' }[q.z_zone] || '';
    const zoneLabel = { safe: 'ปลอดภัย', grey: 'เทา', distress: 'เสี่ยง' }[q.z_zone] || '';
    fzHtml += `<div title="${_zScoreTooltip(q.z_variant, q.z_zone, zoneLabel)}" style="text-align:center;flex:1;min-width:88px;cursor:help">
      <div style="font-size:9px;color:var(--text2);text-transform:uppercase">Z${q.z_variant === 'Z2' ? "''" : ''}-Score</div>
      <div style="font-size:15px;font-weight:700;color:${zoneColor}">${q.z_score.toFixed(2)}</div></div>`;
  }

  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <div style="font-size:13px;font-weight:700">🧾 งบย่อ — คุณภาพ & สกอร์</div>
      <a href="#" onclick="_tsGoFin('${sym}');return false" style="font-size:11px;color:var(--blue)">ดูงบเต็ม 8 ไตรมาส →</a>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${tile('ROE%', q.roe ?? '—', roeC, 'ผลตอบแทนต่อส่วนผู้ถือหุ้น — เขียว ≥15% (ดี) · แดง <0% (ขาดทุน)')}
      ${tile('D/E', q.de_ratio ?? '—', deC, 'หนี้สินต่อทุน — แดง >2 เท่า (หนี้สูง เสี่ยงเรื่องสภาพคล่อง)')}
      ${tile('Gross Margin%', q.gross_margin ?? '—', '', 'อัตรากำไรขั้นต้น — ยิ่งสูงยิ่งมี pricing power')}
      ${tile('FCF Yield%', q.fcf_yield ?? '—', fcfC, 'กระแสเงินสดอิสระ ÷ มูลค่าตลาด — เขียว ≥5% (ดี) · แดง <0% (เผาเงินสด)')}
      ${tile('Div Coverage', q.dividend_coverage != null ? q.dividend_coverage.toFixed(2) : '—', covC, 'FCF ÷ เงินปันผลที่จ่ายทั้งปี — เขียว ≥1 เท่า (FCF พอจ่ายปันผล) · แดง <1 เท่า (จ่ายเกินตัว)')}
      ${fzHtml}
    </div>
  </div>`;
}

// การ์ดย่อประวัติปันผล (จุดผูกงาน #5 Dividend History — เลขเดียวกับที่หน้า "💵 ปันผล" คำนวณ
// ไม่คำนวณซ้ำเอง แค่แสดง 4 ตัวย่อ + ลิงก์ไปหน้าเต็ม) ไม่โชว์การ์ดถ้าไม่มีข้อมูลอะไรเลย (ยังไม่เคย
// sync ปันผลของหุ้นตัวนี้)
function _tsDividendHtml(d, sym) {
  if (!d) return '';
  if (d.yield == null && d.cagr_5y == null && d.growth_streak_y == null && d.coverage == null
      && d.payout_ratio_pct == null) return '';
  const tile = (label, val, color, tip) => `<div title="${tip || ''}" style="text-align:center;flex:1;min-width:88px${tip ? ';cursor:help' : ''}">
    <div style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:.05em">${label}</div>
    <div style="font-size:15px;font-weight:700;color:${color || 'var(--text)'}">${val}</div></div>`;
  const cagrC = d.cagr_5y == null ? '' : d.cagr_5y >= 5 ? 'var(--green)' : d.cagr_5y < 0 ? 'var(--red)' : '';
  const covC = d.coverage == null ? '' : d.coverage >= 1 ? 'var(--green)' : 'var(--red)';
  const payoutC = d.payout_ratio_pct == null ? '' : d.payout_ratio_pct > 100 ? 'var(--red)' : d.payout_ratio_pct <= 60 ? 'var(--green)' : '';
  return `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <div style="font-size:13px;font-weight:700">💵 ปันผลย่อ</div>
      <a href="#" onclick="_tsGoDividends('${sym}');return false" style="font-size:11px;color:var(--blue)">ดูประวัติเต็ม →</a>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${tile('Yield%', d.yield != null ? d.yield.toFixed(2) : '—', '', 'อัตราปันผลต่อปี ÷ ราคาปัจจุบัน')}
      ${tile('CAGR 5ปี%', d.cagr_5y != null ? d.cagr_5y.toFixed(2) : '—', cagrC, 'อัตราการเติบโตของเงินปันผลเฉลี่ยต่อปี ย้อนหลัง 5 ปี — เขียว ≥5% (โตดี) · แดง <0% (ลดลง)')}
      ${tile('โตติดกัน(ปี)', d.growth_streak_y ?? '—', '', 'จำนวนปีติดต่อกันที่เงินปันผลเพิ่มขึ้นหรือคงที่ (ไม่ลด)')}
      ${tile('FCF คุ้ม(เท่า)', d.coverage != null ? d.coverage.toFixed(2) : '—', covC, 'FCF ÷ เงินปันผลที่จ่ายทั้งปี — เขียว ≥1 เท่า (FCF พอจ่ายปันผล) · แดง <1 เท่า (จ่ายเกินตัว)')}
      ${tile('Payout Ratio', d.payout_ratio_pct != null ? d.payout_ratio_pct.toFixed(1) + '%' : '—', payoutC, 'DPS ÷ EPS งวดล่าสุด — เขียว ≤60% (ยังเหลือกำไรสะสม) · แดง >100% (จ่ายเกินกำไรที่หาได้)')}
    </div>
  </div>`;
}

// การ์ด "สัปดาห์นี้" (จุดผูกงาน #4 Calendar — reuse endpoint/badge เดียวกับหน้า "📅 ปฏิทิน" ตรงๆ
// ไม่ปั้น logic ใหม่) ดึงเฉพาะหุ้นตัวนี้ตัวเดียว (ต่างจากหน้าปฏิทินที่ดึงทั้ง Watchlist) กรอง
// เหตุการณ์ที่อยู่ในช่วง [วันนี้, วันนี้+7] แล้วโชว์เป็นแบนเนอร์เล็กใต้ header — ไม่โชว์อะไรเลยถ้า
// ไม่มี event ในสัปดาห์นี้ (เงียบๆ ไม่ใช่ error)
async function _tsLoadCalendarWeek(sym, mkt) {
  const el = document.getElementById('ts-calendar');
  if (!el) return;
  try {
    // /api/calendar-events อาจ fallback ดึงสดจาก SET.or.th + yfinance ถ้า cache stale เกิน 7 วัน
    // (ดู _CALENDAR_STALE_DAYS ฝั่ง app.py) — ต้องมี timeout กันหน้าค้าง "กำลังโหลด..." ไม่รู้จบ
    // เหมือน pattern อื่นทั้งหมดในไฟล์นี้ (ดู loadCalendarPage ที่ endpoint เดียวกันใช้ 15000ms)
    const r = await _fetchTimeout(`/api/calendar-events/${mkt}/${encodeURIComponent(sym)}`, 15000);
    const d = await r.json();
    if (_tsData?.symbol !== sym || !document.getElementById('ts-calendar')) return;
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const limit = new Date(today.getTime() + 7 * 86400000);
    const events = (d.events || [])
      .map(e => ({ ...e, _dt: new Date(e.date + 'T00:00:00') }))
      .filter(e => e._dt >= today && e._dt <= limit)
      .sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
    if (!events.length) { el.innerHTML = ''; return; }
    // e.detail มาจากข้อความสด (agenda ประชุมผู้ถือหุ้นจาก SET.or.th / EPS ประมาณการจาก yfinance)
    // ต้อง escape ก่อนแทรกเป็น HTML content เหมือน _calRenderList ในหน้า 📅 ปฏิทิน
    const esc = _escHtml;
    const rows = events.map(e => {
      const dLeft = Math.round((e._dt - today) / 86400000);
      const dayLabel = dLeft === 0 ? 'วันนี้' : `อีก ${dLeft} วัน`;
      return `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:3px 0;font-size:12px">
        <span>${_CAL_TYPE_BADGE[e.type] || e.type}</span>
        <span style="font-weight:600">${e.date}</span>
        <span style="color:var(--text2);font-size:11px">(${dayLabel})</span>
        ${e.detail ? `<span style="color:var(--text2);font-size:11px">${esc(e.detail)}</span>` : ''}
        <span style="color:${_CAL_CONF_COLOR[e.confidence] || 'var(--text2)'};font-size:11px;margin-left:auto">${_CAL_CONF_LABEL[e.confidence] || e.confidence}</span>
      </div>`;
    }).join('');
    el.innerHTML = `<div class="card" style="padding:12px 16px;margin-bottom:12px;border-left:3px solid var(--blue)">
      <div style="font-size:13px;font-weight:700;margin-bottom:6px">📅 สัปดาห์นี้</div>
      ${rows}
    </div>`;
  } catch (e) { /* เงียบไว้ — ไม่บล็อกหน้าหลักถ้าปฏิทินโหลดไม่สำเร็จ */ }
}

function _tsLoadFlow(sym) {
  loadFlowSignals().then(d => {
    if (_tsData?.symbol !== sym) return;
    const box = document.getElementById('ts-flow-summary');
    if (!box || !d || !d.stocks) return;
    const r = d.stocks.find(x => x.symbol === sym);
    if (!r) { box.innerHTML = ''; return; }
    const ins = r.insider || {}, sh = r.short || {}, nv = r.nvdr || {};
    const label = r.score >= 2 ? '<span style="color:#3ab464">เงินฉลาดไหลเข้า</span>'
                : r.score <= -2 ? '<span style="color:#e05252">เงินฉลาดไหลออก</span>'
                : r.score > 0 ? '<span style="color:#7fae7f">เอียงบวก</span>'
                : r.score < 0 ? '<span style="color:#c98787">เอียงลบ</span>' : 'ก้ำกึ่ง';
    box.innerHTML = `<div style="border:1px solid var(--border);background:var(--card2);border-radius:8px;padding:8px 12px;font-size:12px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      <span style="font-weight:600">🎯 สัญญาณรวม: ${label} <span style="color:var(--text2);font-weight:400">(${r.score>0?'+':''}${r.score})</span></span>
      <span style="color:var(--text2);font-size:11px">Insider ${_dirIcon(ins.dir)} · Short ${_dirIcon(sh.dir)} · NVDR ${_dirIcon(nv.dir)}</span>
    </div>`;
  }).catch(() => {});

  loadShortData().then(() => {
    if (_tsData?.symbol !== sym) return;
    const box = document.getElementById('ts-short');
    if (box) box.innerHTML = renderShortPopup(sym);
  });
  loadNvdrData().then(() => {
    if (_tsData?.symbol !== sym) return;
    const box = document.getElementById('ts-nvdr');
    if (box) box.innerHTML = renderNvdrPopup(sym);
  });
  _tsLoadInsider(sym);
}

// ผู้ถือหุ้นใหญ่/free float/ห้องต่างชาติ (SET.or.th ทางการ, ดู PLAN_set_api_expansion.txt
// งาน #1/#2) — เติมทั้งคอลัมน์ที่ 4 ของการ์ด "เงินทุน & คนวงใน" (#ts-foreign-room) และ
// การ์ด "🏛 โครงสร้างผู้ถือหุ้น" (#ts-ownership) ในคราวเดียว (endpoint เดียวกัน)
async function _tsLoadOwnership(sym) {
  const roomBox = document.getElementById('ts-foreign-room');
  const ownBox = document.getElementById('ts-ownership');
  try {
    const r = await _fetchTimeout(`/api/company-ownership/${encodeURIComponent(sym)}`, 8000);
    const d = await r.json();
    if (_tsData?.symbol !== sym) return;
    if (!r.ok) {
      const msg = `<div class="empty" style="padding:8px 0;font-size:11px">ยังไม่เคย sync — ไปหน้า <a href="#" onclick="showPage('fscreener');return false" style="color:var(--blue)">🔬 Screener+</a> กด "🌱 Sync CG/ESG" หรือปุ่ม sync ผู้ถือหุ้น/ห้องต่างชาติก่อน</div>`;
      if (roomBox) roomBox.innerHTML = msg;
      if (ownBox) ownBox.innerHTML = msg;
      return;
    }
    // คอลัมน์ห้องต่างชาติในการ์ด "เงินทุน & คนวงใน"
    if (roomBox) {
      const used = d.foreign_room_used_pct;
      if (used == null) {
        roomBox.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px">ไม่มีข้อมูล</div>';
      } else {
        const clr = used >= 95 ? 'var(--red)' : used >= 80 ? '#e8a33d' : 'var(--green)';
        roomBox.innerHTML = `
          <div style="font-size:18px;font-weight:700;color:${clr}">${used.toFixed(1)}%</div>
          <div style="font-size:10.5px;color:var(--text2)">ใช้ไปแล้ว (เพดาน ${d.foreign_limit ?? '—'}%)</div>
          <div style="height:5px;background:var(--card2);border-radius:3px;margin-top:4px;overflow:hidden">
            <div style="height:100%;width:${Math.min(used,100)}%;background:${clr}"></div>
          </div>
          <div style="font-size:10px;color:var(--text2);margin-top:3px">ณ ${d.foreign_as_of || '—'}</div>`;
      }
    }
    // การ์ด "🏛 โครงสร้างผู้ถือหุ้น" (renderer ใช้ร่วมกับหน้า Insider — ดู _ownershipCardHtml)
    if (ownBox) ownBox.innerHTML = _ownershipCardHtml(d);
  } catch (e) {
    if (_tsData?.symbol !== sym) return;
    const msg = '<div class="empty" style="padding:8px 0;font-size:11px;color:var(--red)">โหลดไม่สำเร็จ</div>';
    if (roomBox) roomBox.innerHTML = msg;
    if (ownBox) ownBox.innerHTML = msg;
  }
}

// สร้าง HTML การ์ดผู้ถือหุ้นใหญ่+free float+ห้องต่างชาติ จาก /api/company-ownership
// response ตัวเดียว — ใช้ร่วมกันทั้ง Tearsheet (#ts-ownership) และหน้า Insider
// (#ins-own-result, ดู loadInsOwnership) กันโค้ด tile/ตารางซ้ำกัน 2 ที่
function _ownershipCardHtml(d) {
  if (d.free_float == null && d.foreign_room == null && !d.major_shareholders?.length) {
    return '<div class="empty" style="padding:8px 0;font-size:11px">ไม่มีข้อมูล</div>';
  }
  const tile = (label, val, tip, clr) => `<div style="flex:1;min-width:120px">
    <div style="font-size:20px;font-weight:700${clr ? `;color:${clr}` : ''}">${val ?? '—'}</div>
    <div style="font-size:10.5px;color:var(--text2)">${label}${tip ? ` <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box">${tip}</div></span>` : ''}</div>
  </div>`;
  const used = d.foreign_room_used_pct;
  const usedClr = used == null ? '' : used >= 95 ? 'var(--red)' : used >= 80 ? '#e8a33d' : 'var(--green)';
  const rows = (d.major_shareholders || []).map(m => `
    <tr>
      <td style="text-align:center;color:var(--text2)">${m.seq}</td>
      <td style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap${m.is_nvdr ? ';color:#e8a33d;font-weight:600' : ''}" title="${(m.name||'').replace(/"/g,'&quot;')}${m.is_nvdr ? ' (บัญชี NVDR — ตัวแทนถือหุ้นแทนต่างชาติ ไม่ใช่เจ้าของจริง)' : ''}">${(m.name||'').replace(/</g,'&lt;')}${m.is_nvdr ? ' 🌐' : ''}</td>
      <td style="text-align:right;color:var(--text2)">${m.shares != null ? m.shares.toLocaleString() : '—'}</td>
      <td style="text-align:right;font-weight:600">${m.pct != null ? m.pct.toFixed(2)+'%' : '—'}</td>
      <td style="width:120px"><div style="height:6px;background:var(--card2);border-radius:3px;overflow:hidden"><div style="height:100%;width:${Math.min((m.pct||0)*4,100)}%;background:var(--blue)"></div></div></td>
    </tr>`).join('');
  return `
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:12px">
      ${tile('Free Float', d.free_float != null ? d.free_float.toFixed(1)+'%' : '—',
        'สัดส่วนหุ้นที่หมุนเวียนซื้อขายจริงในตลาด (ไม่นับหุ้นของผู้ถือหุ้นเชิงกลยุทธ์ที่ไม่ขาย)<hr>ยิ่งต่ำ = สภาพคล่องน้อย ราคาแกว่งแรง ปั่นง่าย · ต่ำกว่า 15% เสี่ยงถูกเตือนจาก SET')}
      ${tile('จำนวนผู้ถือหุ้น', d.total_shareholder != null ? d.total_shareholder.toLocaleString() : '—',
        'จำนวนบัญชีที่ถือหุ้นนี้ ณ วันปิดสมุด — น้อย = กระจุกตัว')}
      ${tile('NVDR ถือ', d.nvdr_pct_holding != null ? d.nvdr_pct_holding.toFixed(2)+'%' : '—',
        'บ.ไทยเอ็นวีดีอาร์ ถือแทนต่างชาติ — ไม่ใช่เจ้าของตัวจริง ตัวเลขนี้คือ proxy ของแรงซื้อต่างชาติสะสม<hr>ดูคู่กับ "ห้องต่างชาติ" ทางขวา: NVDR สูง + ห้องต่างชาติใกล้เต็ม = ต่างชาติอยากได้แต่ซื้อตรงไม่ได้แล้ว')}
      ${tile('ห้องต่างชาติใช้ไป', used != null ? used.toFixed(1)+'%' : '—',
        `<strong>โควตาต่างชาติ (Foreign Room)</strong><br>กฎหมายไทยจำกัดสัดส่วนที่ต่างชาติถือได้ (ปกติ 49% บางกลุ่มต่ำกว่านั้น) — ค่านี้คือสัดส่วนที่ใช้ไปแล้วเทียบเพดาน ${d.foreign_limit ?? '—'}%<hr><span style="color:var(--text2)">ใกล้เต็ม (≥95%) = ต่างชาติต้องซื้อผ่าน NVDR แทน มักดัน NVDR premium ขึ้น</span>`, usedClr)}
    </div>
    ${rows ? `<div style="overflow-x:auto"><table class="tbl" style="min-width:400px;font-size:12px">
      <thead><tr><th>#</th><th style="text-align:left">ผู้ถือหุ้น</th><th style="text-align:right">จำนวนหุ้น</th><th style="text-align:right">%</th><th></th></tr></thead>
      <tbody>${rows}</tbody></table></div>` : ''}
    <div style="font-size:10.5px;color:var(--text2);margin-top:8px">ผู้ถือหุ้น ณ วันปิดสมุด ${d.book_close_date || '—'} · ห้องต่างชาติ ณ ${d.foreign_as_of || '—'} — ไม่ใช่รายวัน อัพเดทเมื่อมีรอบ sync ถัดไป</div>`;
}

// ค้นหาผู้ถือหุ้นใหญ่+ห้องต่างชาติของหุ้น 1 ตัวในหน้า Insider (ปุ่ม "ค้นหา" /
// กด Enter ในช่อง ins-own-sym) ใช้ renderer เดียวกับ Tearsheet (_ownershipCardHtml)
async function loadInsOwnership() {
  initFinPage();   // เผื่อ fin-set-datalist (autocomplete) ยังไม่เคยถูกเติม (ไม่เคยเข้าหน้าอื่นมาก่อน) — เบามาก เรียกซ้ำได้
  const sym = (document.getElementById('ins-own-sym').value || '').trim().toUpperCase();
  const box = document.getElementById('ins-own-result');
  if (!sym || !box) return;
  box.innerHTML = '<div class="empty" style="padding:8px;font-size:12px">กำลังโหลด...</div>';
  try {
    const r = await _fetchTimeout(`/api/company-ownership/${encodeURIComponent(sym)}`, 8000);
    const d = await r.json();
    if (!r.ok) {
      box.innerHTML = `<div class="empty" style="padding:8px;font-size:12px">${(d.error || 'ไม่พบข้อมูล').replace(/</g,'&lt;')}</div>`;
      return;
    }
    box.innerHTML = _ownershipCardHtml(d);
  } catch (e) {
    box.innerHTML = '<div class="empty" style="padding:8px;font-size:12px;color:var(--red)">โหลดไม่สำเร็จ</div>';
  }
}

// ข้อมูล insider (แบบ 59) + major-changes (แบบ 246) 180 วันเต็ม "ทั้งกระดาน" — endpoint ทั้งคู่
// คืนทุกหุ้น (~4,400 แถว) แล้วกรองตามหุ้นฝั่ง client · Tearsheet (_tsLoadInsider) กับ popup หุ้น
// (loadInsiderForStock) เดิมต่างคนต่างยิงตารางเต็มซ้ำทุกครั้งที่เปิดหุ้น — รวมเป็น loader เดียว
// cache 10 นาที + กัน request ซ้อน (เปิดหลายหุ้นติดๆ กัน / Tearsheet+popup พร้อมกัน)
let _insStockCache = null;      // { ts, r59:[...], r246:[...] }
let _insStockInflight = null;
const _INS_STOCK_TTL = 600000;

async function _loadInsiderStockData() {
  if (_insStockCache && Date.now() - _insStockCache.ts < _INS_STOCK_TTL) return _insStockCache;
  if (_insStockInflight) return _insStockInflight;
  const timeoutMs = IS_STATIC ? 20000 : 200000;   // IS_STATIC ไม่มี live sync ให้รอ
  _insStockInflight = (async () => {
    try {
      const [r59res, r246res] = await Promise.all([
        _fetchTimeout('/api/insider-trades?days=180', timeoutMs).then(r => r.json()),
        _fetchTimeout('/api/major-changes?days=180', timeoutMs).then(r => r.json()),
      ]);
      _insStockCache = { ts: Date.now(), r59: r59res.records || [], r246: r246res.records || [] };
      return _insStockCache;
    } finally {
      _insStockInflight = null;
    }
  })();
  return _insStockInflight;
}

async function _tsLoadInsider(sym) {
  const el = document.getElementById('ts-insider');
  if (!el) return;
  try {
    const data = await _loadInsiderStockData();
    if (_tsData?.symbol !== sym) return;
    const r59 = data.r59.filter(x => x.symbol === sym);
    const r246 = data.r246.filter(x => x.symbol === sym);
    const all = [...r59.map(x => ({...x, src: 'r59'})), ...r246.map(x => ({...x, src: 'r246'}))]
                  .sort((a, b) => (b.trade_date || '').localeCompare(a.trade_date || ''));
    if (!all.length) { el.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px">ไม่มีรายการ 180 วัน</div>'; return; }
    const actColor = a => a === 'buy' ? 'var(--green)' : a === 'sell' ? 'var(--red)' : 'var(--text2)';
    el.innerHTML = all.slice(0, 8).map(row => {
      const isR59 = row.src === 'r59';
      const who = (isR59 ? (row.name || '') : (row.holder || '')).replace(/</g, '&lt;');
      return `<div style="display:flex;gap:6px;align-items:center;padding:3px 0;border-bottom:1px solid var(--border);font-size:11px">
        <span style="color:var(--text2);min-width:70px">${row.trade_date || '—'}</span>
        <span style="color:${actColor(row.action)};font-weight:600">${row.action === 'buy' ? 'ซื้อ' : row.action === 'sell' ? 'ขาย' : 'อื่น'}</span>
        <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${who}">${who}</span>
      </div>`;
    }).join('') + (all.length > 8 ? `<div style="font-size:10px;color:var(--text2);margin-top:4px">+ อีก ${all.length - 8} รายการ</div>` : '');
  } catch (e) {
    if (_tsData?.symbol !== sym) return;
    el.innerHTML = '<div class="empty" style="padding:8px 0;font-size:11px;color:var(--red)">โหลดไม่สำเร็จ</div>';
  }
}

function closeTsOpenChart(sym) {
  const mkt = _tsData?.market || 'TH';
  // lite (DR ตลาด JP/VN/ฯลฯ): sym เป็น DR sym ไม่ใช่ ticker ไทย/US — เปิด DR chart modal เดิม
  // (หุ้นอยู่ใน _drData อยู่แล้วเพราะผู้ใช้เข้ามาจากหน้า DR)
  if (_tsData?.lite && _tsData?.dr_symbol) { openDRChartModal(_tsData.dr_symbol); return; }
  if (mkt === 'US') openUsChartModal(sym);
  else if (mkt === 'HK') openHkChartModal(sym);
  else if (mkt === 'JP') openJpChartModal(sym);
  else openChartModal(sym);
}

function openTearsheetFromModal() {
  if (!_cmStock) return;
  // หุ้น DR (_isDR) fetch แรกส่ง market='DR' ให้ backend resolve underlying เอง (ดู
  // openPeerFromModal ด้านบนสำหรับเหตุผลเดียวกัน) แท็บ UI ยังตั้งเป็น US/HK ตามปกติ
  const isDr = !!_cmStock._isDR;
  const mkt = isDr ? (_cmStock.region === 'HK' ? 'HK' : 'US') : (_cmStock._isUSIdx ? 'US' : _cmStock._isHKIdx ? 'HK' : _cmStock._isJPIdx ? 'JP' : 'TH');
  // โหมด "🗗 แท็บใหม่" — ส่ง deep-link #ts/ ไปแท็บใหม่ แล้วคากราฟที่กำลังดูอยู่ไว้ในแท็บนี้
  // (ยกเว้นหุ้น DR: hash route ไม่มี market 'DR' ที่ backend ต้องใช้ resolve underlying)
  if (!isDr && navOpenMode() === 'new') {
    openInternalHash(`#ts/${mkt.toLowerCase()}/${encodeURIComponent(_cmStock.symbol)}`, true);
    return;
  }
  closeChartModal();
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes("'tearsheet'"));
  showPage('tearsheet', btn);
  setTsMarket(mkt, document.getElementById('ts-tab-' + mkt.toLowerCase()));
  loadTearsheet(_cmStock.symbol, isDr ? 'DR' : null);
}

// ============================================================
// HEATMAP
// ============================================================
// รวม page-heatmap/page-us-heatmap/page-hk-heatmap/page-jp-heatmap เป็นหน้าเดียว (page-heatmap)
// พร้อมแท็บเลือกตลาด — ฟังก์ชัน render/load เฉพาะตลาดของเดิมทั้งหมด (renderHeatmap,
// loadHeatmapPage, loadHkHeatmapPage, loadJpHeatmapPage ฯลฯ) ไม่ถูกแตะ แค่เปลี่ยนจุดเรียกจาก
// showPage(id) แยกๆ มาเป็น setHmMarket() ตัวเดียว
let _hmMarket = 'TH';
function setHmMarket(mkt, btn) {
  _hmMarket = mkt;
  document.querySelectorAll('#hm-tab-th,#hm-tab-us,#hm-tab-hk,#hm-tab-jp').forEach(b => b.classList.remove('active'));
  (btn || document.getElementById('hm-tab-' + mkt.toLowerCase()))?.classList.add('active');
  document.getElementById('hm-mkt-th').style.display = mkt === 'TH' ? '' : 'none';
  document.getElementById('hm-mkt-us').style.display = mkt === 'US' ? '' : 'none';
  document.getElementById('hm-mkt-hk').style.display = mkt === 'HK' ? '' : 'none';
  document.getElementById('hm-mkt-jp').style.display = mkt === 'JP' ? '' : 'none';
  if (mkt === 'TH') renderHeatmap();
  if (mkt === 'US') loadHeatmapPage();
  if (mkt === 'HK') loadHkHeatmapPage();
  if (mkt === 'JP') loadJpHeatmapPage();
}

let hmPeriod = 'ret_1d';
let hmSortDir = 1;   // 1 = มากไปน้อย (ค่าเริ่มต้น), -1 = น้อยไปมาก — คลิกปุ่ม metric เดิมซ้ำเพื่อสลับทิศ

// comparator ใช้ร่วมกันทั้ง 4 heatmap (ไทย/US/HK/JP) — ค่า null (ไม่มีข้อมูล) อยู่ท้ายสุดเสมอ
// ไม่ว่าจะเรียงทิศไหน (ไม่งั้นตอนสลับเป็นน้อยไปมาก ค่า null จะโดดขึ้นไปอยู่บนสุดแทน)
function _hmCmp(getV, dir) {
  return (a, b) => {
    const va = getV(a), vb = getV(b);
    if (va == null && vb == null) return 0;
    if (va == null) return 1;
    if (vb == null) return -1;
    return (vb - va) * dir;
  };
}

// ปุ่ม "⚡ อัพเดทราคา" ของ Heatmap US/HK/JP — POST /api/heatmap-live-update/<region> (background
// thread ฝั่ง Flask กด gap-update + คำนวณ live_price/live_chg แบบเดียวกับ dr_quick_update แล้ว
// rebuild <mkt>_index_metrics.json) แล้ว poll /api/heatmap-live-status/<region> ทุก 1.5 วิ
// จนเสร็จ (pattern เดียวกับ drQuickUpdate) ใช้ร่วมกันทั้ง 3 ตลาด ต่างแค่ region + callback
// โหลดข้อมูลใหม่ตอนจบ (loadHeatmapPage/loadHkHeatmapPage/loadJpHeatmapPage)
//
// indexKey (optional) — ดัชนีย่อยที่กำลังดูอยู่ (เช่น "DOW") ส่งไปให้ backend กรองแค่สมาชิก
// ของดัชนีนั้น แทนที่จะกด gap-update ทั้ง union ของ region (US ~518 ตัว, HK ~105 ตัว) —
// ไม่งั้นดูอยู่แค่แท็บ Dow (30 ตัว) แต่ต้องรอ Yahoo ทั้ง 518 ตัวเหมือนเดิมทุกครั้ง (JP ไม่มี
// ดัชนีย่อยให้เลือกอยู่แล้ว เลยไม่ส่ง)
// isActive (optional) — เช็คว่าแท็บดัชนีย่อยที่กดตอนเริ่ม (indexKey) ยังเป็นแท็บที่ผู้ใช้ดู
// อยู่หรือเปล่าตอนงาน poll เสร็จ (เดิมอ่าน _hmIndex/_hkHmIndex "ล่าสุด" ตรงๆ ตอน onDone/appendNote
// ทำงาน ไม่ใช่ค่าตอนกดปุ่ม — สลับแท็บระหว่างรอ (เช่น กด Dow แล้วสลับไป SP500 ก่อนงานเสร็จ)
// ทำให้ผลของ Dow ไปโผล่ที่แท็บ SP500 แทน) ไม่ส่งมา = ไม่มีแท็บย่อยให้เช็ค (JP)
function _hmLiveUpdate(region, btn, idleLabel, onDone, indexKey, noteId, isActive) {
  if (btn) { btn.disabled = true; btn.textContent = '⚡ กำลังดึงราคา Live...'; }
  const qs = indexKey ? `?index=${encodeURIComponent(indexKey)}` : '';
  _fetchTimeout(`/api/heatmap-live-update/${region}${qs}`, 20000, 'เริ่มอัพเดทราคา Live ไม่สำเร็จ (หมดเวลารอ)', { method: 'POST' })
    .then(r => r.json())
    .then(res => {
      // status "busy" = มีงานยาวอื่นที่ไม่เกี่ยวข้อง (Quick Update/Index Max ฯลฯ) ถือ _lock อยู่
      // เลยยังไม่ได้เริ่มงานอะไรเลย (ต่างจาก "running" ด้านล่าง) ไป poll ต่อจะเจอ running:false
      // ทันทีแล้วเข้าใจผิดว่าจบแล้ว ต้องแจ้งตรงๆ ว่าไม่ได้เริ่ม ไม่ใช่ไป poll
      if (res.status === 'busy') {
        if (btn) { btn.disabled = false; btn.textContent = idleLabel; }
        alert('ระบบกำลังทำงานอื่นอยู่ (เช่น Quick Update/Index Max) โปรดรอสักครู่แล้วลองใหม่');
        return;
      }
      // status "running" = มีงานของ region นี้ (แท็บย่อยอื่น/คลิกก่อนหน้า) ทำงานค้างอยู่แล้ว
      // ปุ่มนี้เลย "ไม่ได้" เริ่มงานใหม่ตามที่ผู้ใช้เพิ่งกด แค่ไปรอผลงานเก่าแทน — ต้องบอกผู้ใช้
      // ตรงๆ กันเข้าใจผิดว่าราคาที่ได้ท้ายสุดคือของรอบที่เพิ่งกด (อาจเป็นราคาจากรอบก่อนหน้า
      // ที่ scope ต่างกัน เช่นกดตอนแท็บ Dow ขณะแท็บ SP500 ยังดึงไม่เสร็จ)
      if (res.status === 'running' && btn) {
        btn.textContent = '⏳ มีงานอัพเดทค้างอยู่ กำลังรอผล...';
      }
      _hmLiveUpdatePoll(region, btn, idleLabel, onDone, noteId, isActive);
    })
    .catch(e => {
      if (btn) { btn.disabled = false; btn.textContent = idleLabel; }
      alert('อัพเดทราคา Live ไม่สำเร็จ: ' + e.message);
    });
}

function _hmLiveUpdatePoll(region, btn, idleLabel, onDone, noteId, isActive, tries) {
  tries = tries || 0;
  // cap จำนวนรอบ poll (เหมือน _drPollRefresh) — กัน backend thread ค้าง (เช่น yf.download
  // ไม่ตอบระหว่างดึงราคาสด) ทำให้ปุ่มนี้ disabled ค้างถาวรไม่มีทางกู้คืนได้เอง
  if (tries > 160) {   // ~4 นาที (1.5วิ x 160)
    if (btn) { btn.disabled = false; btn.textContent = idleLabel; }
    alert('อัพเดทราคา Live นานผิดปกติ (>4 นาที) — ลองกดใหม่ หรือรีเฟรชหน้า');
    return;
  }
  // ต้องมี timeout ต่อ request เอง (ไม่ใช่แค่ cap จำนวนรอบ) — ถ้า fetch เส้นนี้ค้างเฉยๆ (connection
  // ค้าง ไม่ resolve/reject เลย เช่น proxy สะดุด) ทั้ง .then ทั้ง .catch จะไม่ทำงานเลย รอบ poll ถัดไป
  // เลยไม่ถูก schedule ปุ่มจะ disabled ค้างถาวรแม้จะมี tries cap ก็ตาม (cap เช็คแค่ตอนเริ่มรอบใหม่)
  _fetchTimeout(`/api/heatmap-live-status/${region}`, 15000, 'เช็คสถานะอัพเดทราคา Live หมดเวลา')
    .then(r => r.json())
    .then(st => {
      if (st.running) { setTimeout(() => _hmLiveUpdatePoll(region, btn, idleLabel, onDone, noteId, isActive, tries + 1), 1500); return; }
      if (btn) { btn.disabled = false; btn.textContent = idleLabel; }
      // ต่อท้าย note เดิม (ที่ loadHeatmapPage/loadHkHeatmapPage/loadJpHeatmapPage เซ็ตตอน
      // โหลดข้อมูลใหม่เสร็จ) ด้วยสรุปผลรอบ live-update นี้ — แบบเดียวกับปุ่ม "⚡ ราคาล่าสุด"
      // ของ Watchlist (ดู wlRefreshLivePrices) ต้องรอ onDone() (โหลด/render ข้อมูลใหม่เสร็จ
      // ก่อน — มัน return promise ของ fetch เอง) ไม่งั้น note จะถูกเขียนทับด้วย "ข้อมูล ณ ..."
      // ของมันทีหลัง — เรียก onDone() ก่อนเช็ค error เสมอ เพราะ backend merge ราคาส่วนที่ได้
      // ลงไฟล์ไปแล้วแม้เคส error (ได้ live price บางส่วน <20%) หน้าจอต้องโชว์ของที่ได้มาจริง
      // ไม่ใช่ทิ้งไว้เป็นข้อมูลเก่า
      const p = onDone();
      if (st.error) {
        const showError = () => alert('อัพเดทราคา Live ไม่สำเร็จ: ' + st.error);
        if (p && typeof p.then === 'function') p.then(showError); else showError();
        return;
      }
      // isActive() = false แปลว่าผู้ใช้สลับแท็บดัชนีย่อยไปแล้วระหว่างรอ — ตัวเลข n_live/n_fetched
      // นี้เป็นของแท็บที่กดตอนเริ่ม ไม่ใช่แท็บที่กำลังดูอยู่ตอนนี้ ต่อท้าย note ผิดแท็บจะสับสน
      if (noteId && st.n_fetched != null && (!isActive || isActive())) {
        const appendNote = () => {
          const note = document.getElementById(noteId);
          if (note) {
            const time = new Date().toLocaleTimeString('th-TH');
            note.textContent += ` · ราคาสด ณ ${time} · สำเร็จ ${st.n_live}/${st.n_fetched} ตัว`;
          }
        };
        if (p && typeof p.then === 'function') p.then(appendNote); else appendNote();
      }
    })
    .catch(e => {
      // fetch ล้มเหลว/timeout (เซิร์ฟเวอร์รีสตาร์ท/เน็ตสะดุด) — เดิมไม่มี .catch ทำให้ปุ่มค้าง
      // disabled + textContent "กำลังดึงราคา Live..." ถาวรจนกว่าจะกด F5 เอง
      if (btn) { btn.disabled = false; btn.textContent = idleLabel; }
      alert('เช็คสถานะอัพเดทราคา Live ไม่สำเร็จ: ' + e.message);
    });
}

function setHmPeriod(key, btn) {
  hmSortDir = (key === hmPeriod) ? -hmSortDir : 1;
  hmPeriod = key;
  // scope แค่แถวปุ่ม metric ของแท็บไทย — เดิมกวาดทั้ง #page-heatmap ทำให้แท็บตลาด
  // (🇹🇭/🇺🇸/🇭🇰/🇯🇵) และปุ่มดัชนี/metric ของ US/HK/JP ที่เป็น .filter-btn เหมือนกัน
  // หายไฮไลต์ไปด้วยทุกครั้งที่คลิกปุ่ม metric ฝั่งไทย (ดู setEMABreadthView ด้านล่างที่แก้ไปแล้ว)
  document.querySelectorAll('#hm-th-period-btns .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderHeatmap();
}

function _heatColor(v, cap = 15) {
  if (v == null) return '#21262d';
  const t = Math.min(Math.abs(v) / cap, 1);
  if (v >= 0) return `rgba(63,185,80,${0.15 + t * 0.85})`;
  return `rgba(248,81,73,${0.15 + t * 0.85})`;
}
function _heatColorRS(v) {
  if (v == null) return '#21262d';
  const t = Math.abs(v - 50) / 50;
  if (v >= 50) return `rgba(63,185,80,${0.15 + t * 0.85})`;
  return `rgba(248,81,73,${0.15 + t * 0.85})`;
}
function _heatColorVol(v) {
  if (v == null) return '#21262d';
  const t = Math.min(Math.max(v - 80, 0) / 220, 1);
  return `rgba(88,166,255,${0.1 + t * 0.9})`;
}

const HM_CFG = {
  ret_1d:    { getV:s=>s.ret_1d,   clr:v=>_heatColor(v,15),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)',              hint:'เขียว = ขึ้น · แดง = ลง' },
  ret_1w:    { getV:s=>s.ret_1w,   clr:v=>_heatColor(v,15),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)',              hint:'เขียว = ขึ้น · แดง = ลง' },
  ret_1m:    { getV:s=>s.ret_1m,   clr:v=>_heatColor(v,20),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>8?'#fff':'var(--text)',              hint:'เขียว = ขึ้น · แดง = ลง' },
  ret_3m:    { getV:s=>s.ret_3m,   clr:v=>_heatColor(v,30),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>12?'#fff':'var(--text)',             hint:'เขียว = ขึ้น · แดง = ลง' },
  ret_6m:    { getV:s=>s.ret_6m,   clr:v=>_heatColor(v,40),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>16?'#fff':'var(--text)',             hint:'เขียว = ขึ้น · แดง = ลง (6 เดือน)' },
  ret_ytd:   { getV:s=>s.ret_ytd,  clr:v=>_heatColor(v,30),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>12?'#fff':'var(--text)',             hint:'เขียว = ขึ้น · แดง = ลง' },
  ret_1y:    { getV:s=>s.ret_1y,   clr:v=>_heatColor(v,50),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>20?'#fff':'var(--text)',             hint:'เขียว = ขึ้น · แดง = ลง (12 เดือน)' },
  rs_score:  { getV:s=>s.rs_score, clr:v=>_heatColorRS(v),   fmt:v=>'RS '+Math.round(v),            aFmt:v=>'avg RS '+Math.round(v),       aPos:v=>v>=50, txt:v=>(v??50)>70||(v??50)<30?'#fff':'var(--text)',        hint:'เขียว = RS สูง (แข็งแกร่ง) · แดง = RS ต่ำ (อ่อนแอ)' },
  vol_ratio: { getV:s=>(s.vol_today!=null&&s.vol_avg20>0)?s.vol_today/s.vol_avg20*100:null, clr:v=>_heatColorVol(v), fmt:v=>(v/100).toFixed(1)+'x', aFmt:v=>'avg '+(v/100).toFixed(1)+'x', aPos:v=>v>=100, txt:v=>(v??0)>175?'#fff':'var(--text)', hint:'น้ำเงินเข้ม = Volume สูงกว่าเฉลี่ย · น้ำเงินจาง = Volume ต่ำกว่าเฉลี่ย' },
  from_52wh: { getV:s=>s.high_52w>0?(s.price-s.high_52w)/s.high_52w*100:null, clr:v=>_heatColor(v,40), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>'avg '+(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>16?'#fff':'var(--text)', hint:'เขียว = ใกล้/ทำ 52W High · แดง = ห่างจาก 52W High มาก' },
  ath_dist:  { getV:s=>s.ath_pct??null, clr:v=>_heatColor(v,50), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>'avg '+(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>20?'#fff':'var(--text)', hint:'เขียว = ใกล้/ทำ ATH · แดง = ห่างจาก All-Time High มาก (คำนวณจากข้อมูลที่โหลด)' },
  // ราคาระหว่างวันที่ยังไม่ปิด (pre-market/กำลังเทรด) — มีเฉพาะ US/HK/JP heatmap หลังกด
  // "⚡ อัพเดทราคา" (ดู _run_heatmap_live_update ใน app.py) ถ้าตลาดปิดไปแล้ว/ยังไม่เคยกดปุ่ม
  // (live_chg เป็น null) fallback ไปใช้ ret_1d (% ปิดของวัน) แทน แทนที่จะโชว์ "—" ว่างเปล่า —
  // ทำ fallback ที่ getV เลย (ไม่ใช่แค่ตอน format) เพื่อให้ sort/สีพื้น/ค่าเฉลี่ยต่อ sector
  // (ดู _hmGridHtml) ใช้ค่าเดียวกับที่โชว์ในกล่องเสมอ ไม่ใช่ sort ด้วย live_chg (null สุดท้าย)
  // แต่โชว์ ret_1d — ส่วนไอคอน ⚡ ตัดออกตอน fallback (ดู _hmGridCellHtml) กันเข้าใจผิดว่าเป็น
  // ราคาสด ทั้งที่จริงคือราคาปิดของวัน
  live_chg:  { getV:s=>s.live_chg!=null?s.live_chg:s.ret_1d, clr:v=>_heatColor(v,15), fmt:v=>'⚡'+(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>'⚡ avg '+(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)', hint:'⚡ ราคา Live ระหว่างวัน (ยังไม่ปิดตลาด) เขียว = ขึ้น · แดง = ลง — ปุ่ม "👁 Live" นี้แค่เปลี่ยนมุมมอง ไม่ได้ดึงข้อมูลใหม่ ต้องกด "⚡ อัพเดทราคา"/"⚡ รีเฟรช" ด้านบนก่อนทุกครั้งที่ต้องการราคาล่าสุด · ตลาดปิดแล้วจะโชว์ % ปิดของวันแทน' },
};

function renderHeatmap() {
  if (!DATA) return;
  const cfg = HM_CFG[hmPeriod] || HM_CFG.ret_1d;
  const hintEl = document.getElementById('hm-hint');
  if (hintEl) hintEl.textContent = cfg.hint + (hmSortDir === 1 ? ' · เรียงมาก→น้อย' : ' · เรียงน้อย→มาก') + ' (คลิกปุ่มเดิมซ้ำเพื่อสลับ)';

  const groups = {};
  DATA.stocks.forEach(s => {
    const sec = s.sector || 'Unknown';
    if (!groups[sec]) groups[sec] = [];
    groups[sec].push(s);
  });

  const sectorAvg = arr => { const vs = arr.map(x => cfg.getV(x)).filter(v => v != null); return vs.length ? vs.reduce((s,v)=>s+v,0)/vs.length : null; };
  const sectorList = Object.entries(groups).sort((a, b) => _hmCmp(x => sectorAvg(x[1]), hmSortDir)(a, b));

  document.getElementById('heatmap-grid').innerHTML = sectorList.map(([sec, stocks]) => {
    const sorted = [...stocks].sort(_hmCmp(cfg.getV, hmSortDir));
    const withVal = sorted.filter(s => cfg.getV(s) != null);
    const avg = withVal.length ? withVal.reduce((s, x) => s + cfg.getV(x), 0) / withVal.length : null;
    const cells = sorted.map(s => {
      const v   = cfg.getV(s);
      const bg  = cfg.clr(v);
      const txt = cfg.txt(v);
      const lbl = v != null ? cfg.fmt(v) : '—';
      const priceV = s.live_price ?? s.price;
      const priceLbl = priceV != null ? priceV.toFixed(2) : '—';
      return `<div class="hm-cell" style="background:${bg};color:${txt}" title="${_escHtml(s.symbol)} ${_escHtml(lbl)}" onclick="openChartModal('${_escJsAttr(s.symbol)}')">
        <span style="font-size:11px;font-weight:700;line-height:1">${_escHtml(s.symbol.slice(0,5))}</span>
        <span style="font-size:9px;line-height:1;opacity:0.85">${priceLbl}</span>
        <span style="font-size:10px;line-height:1;opacity:0.92">${lbl}</span>
      </div>`;
    }).join('');
    const avgClass = avg != null ? (cfg.aPos(avg) ? 'green' : 'red') : 'text2';
    const avgDisp  = avg != null ? cfg.aFmt(avg) : '—';
    return `
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;display:flex;align-items:center;gap:8px">
          ${_escHtml(sec)}
          <span class="${avgClass}">${avgDisp}</span>
          <span class="text2" style="font-size:10px">${stocks.length} หุ้น</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:2px">${cells}</div>
      </div>`;
  }).join('');
}

// ============================================================
// EMA BREADTH BY SECTOR
// ============================================================
let emaBreadthView = 'sector';

function setEMABreadthView(v, btn) {
  emaBreadthView = v;
  // scope แค่แถวปุ่ม Sector/Industry — เดิมกวาดทั้งหน้า ทำให้ปุ่มช่วงเวลา
  // (1Y/3Y/5Y/All ใน #breadth-range-btns) ที่เลือกอยู่หายไฮไลต์ทุกครั้งที่สลับมุมมอง
  document.querySelectorAll('#ema-breadth-view-btns .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderEMABreadth();
}

// ============================================================
// MARKET BREADTH CHARTS — % above EMA / NH-NL / McClellan
// ช่วงเวลาเลือกได้: 1Y / 3Y / 5Y / All — cache แยกต่อ range ในฝั่ง client ด้วย
// ============================================================
let _breadthData = null;
let _breadthRange = '1y';
let _breadthCacheByRange = {};
// promise ที่กำลังยิงอยู่ต่อ range — ให้ loadBreadthCharts/loadRegimeLight ที่ขอ range
// เดียวกันพร้อมกัน (เช่นตอนโหลดหน้าแรก renderAll->renderEMABreadth กับ loadRegimeLight
// ยิงเกือบพร้อมกันก่อนใครจะ cache เสร็จ) รอ fetch เดียวกันแทนที่จะยิงซ้ำ
let _breadthFetchInflight = {};

function _fetchBreadthRange(rng) {
  if (_breadthCacheByRange[rng]) return Promise.resolve(_breadthCacheByRange[rng]);
  if (_breadthFetchInflight[rng]) return _breadthFetchInflight[rng];
  const p = _fetchTimeout('/api/breadth?range=' + encodeURIComponent(rng), 30000,
      'หมดเวลารอ Market Breadth หุ้นไทย (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      _breadthCacheByRange[rng] = d;
      return d;
    })
    .finally(() => { delete _breadthFetchInflight[rng]; });
  _breadthFetchInflight[rng] = p;
  return p;
}

function setBreadthRange(range, btn) {
  if (_breadthRange === range) return;
  _breadthRange = range;
  document.querySelectorAll('#breadth-range-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadBreadthCharts();
}

async function loadBreadthCharts() {
  // จับ range ณ ตอนเริ่ม fetch — กัน race: ถ้า user สลับปุ่มระหว่างโหลด
  // ข้อมูลเก่าต้องเก็บลง cache ใต้ key ที่ขอจริง ไม่ใช่ key ปัจจุบัน
  const rng = _breadthRange;
  const cached = _breadthCacheByRange[rng];
  if (cached) {
    _breadthData = cached;
    try {
      drawBreadthCharts();
    } catch (e) {
      ['bc-ema', 'bc-nhnl', 'bc-mcc'].forEach(id => {
        const el = document.getElementById(id + '-loading');
        if (el) { el.style.display = 'block'; el.textContent = 'โหลดไม่สำเร็จ: ' + e.message; }
      });
    }
    return;
  }
  if (!_breadthFetchInflight[rng]) {
    ['bc-ema', 'bc-nhnl', 'bc-mcc'].forEach(id => {
      const loading = document.getElementById(id + '-loading');
      const canvas  = document.getElementById(id);
      if (loading) { loading.style.display = 'block'; loading.textContent = 'กำลังโหลด...'; }
      if (canvas)  canvas.style.display = 'none';
    });
  }
  try {
    const d = await _fetchBreadthRange(rng);
    if (rng === _breadthRange) {   // user ยังอยู่ range เดิม — วาดได้
      _breadthData = d;
      drawBreadthCharts();
    }
  } catch (e) {
    ['bc-ema', 'bc-nhnl', 'bc-mcc'].forEach(id => {
      const el = document.getElementById(id + '-loading');
      if (el) el.textContent = 'โหลดไม่สำเร็จ: ' + e.message;
    });
  } finally {
    // ถ้าระหว่างโหลด user สลับไป range อื่นที่ยังไม่มี cache — โหลดต่อให้เลย
    if (_breadthRange !== rng && !_breadthCacheByRange[_breadthRange]) loadBreadthCharts();
  }
}

function _bcSetup(id) {
  const loading = document.getElementById(id + '-loading');
  const canvas  = document.getElementById(id);
  if (!canvas) return null;
  // reset เป็น 100% ก่อนวัดทุกครั้ง — กันค่า px เก่า (จากรอบที่วาดตอนแท็บซ่อน) ค้างทับ
  canvas.style.width = '100%';
  canvas.style.display = 'block';
  const W = canvas.offsetWidth, H = canvas.offsetHeight || 170;
  if (!W) {
    // แท็บยังซ่อนอยู่ วัดความกว้างจริงไม่ได้ — ข้ามไป ให้ showPage วาดตอนเปิดแท็บ
    canvas.style.display = 'none';
    return null;
  }
  if (loading) loading.style.display = 'none';
  const dpr = window.devicePixelRatio || 1;
  canvas.width = W * dpr; canvas.height = H * dpr;
  canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
  const ctx = canvas.getContext('2d');
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.scale(dpr, dpr);
  return { canvas, ctx, W, H,
           pad: { l: 34, r: 6, t: 6, b: 18 } };
}

function _bcAxes(c, yMin, yMax, dates, refs) {
  const { ctx, W, H, pad } = c;
  const cH = H - pad.t - pad.b;
  const toY = v => pad.t + (1 - (v - yMin) / (yMax - yMin)) * cH;
  ctx.font = '9px sans-serif'; ctx.fillStyle = '#8b949e';
  (refs || []).forEach(rv => {
    const y = toY(rv);
    ctx.strokeStyle = 'rgba(139,148,158,.25)'; ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(W - pad.r, y); ctx.stroke();
    ctx.setLineDash([]);
    ctx.textAlign = 'right'; ctx.fillText(String(rv), pad.l - 4, y + 3);
  });
  // label เดือนคร่าวๆ 4 จุด
  ctx.textAlign = 'center';
  if (dates && dates.length > 1) {
    for (let i = 0; i < 4; i++) {
      const idx = Math.floor(i * (dates.length - 1) / 3);
      const x = pad.l + idx / (dates.length - 1) * (W - pad.l - pad.r);
      ctx.fillText(dates[idx].slice(5, 7) + '/' + dates[idx].slice(2, 4), x, H - 5);
    }
  }
  return toY;
}

function _bcLine(c, data, toY, color) {
  const { ctx, W, pad } = c;
  const cW = W - pad.l - pad.r;
  ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.beginPath();
  let started = false;
  data.forEach((v, i) => {
    if (v == null) return;
    const x = pad.l + i / (data.length - 1) * cW, y = toY(v);
    started ? ctx.lineTo(x, y) : ctx.moveTo(x, y); started = true;
  });
  ctx.stroke();
}

function _bcBars(c, data, toY, zero) {
  const { ctx, W, pad } = c;
  const cW = W - pad.l - pad.r, y0 = toY(zero);
  const bw = Math.max(1, cW / data.length - 0.5);
  data.forEach((v, i) => {
    if (v == null) return;
    const x = pad.l + i / (data.length - 1) * cW;
    ctx.fillStyle = v >= zero ? 'rgba(63,185,80,.75)' : 'rgba(248,81,73,.75)';
    const y = toY(v);
    ctx.fillRect(x, Math.min(y, y0), bw, Math.max(1, Math.abs(y - y0)));
  });
}

function drawBreadthCharts() {
  const d = _breadthData;
  if (!d) return;
  const n = d.dates.length;
  const bcUnivEl = document.getElementById('bc-universe-n');
  if (bcUnivEl && DATA?.stocks?.length) bcUnivEl.textContent = DATA.stocks.length;

  // 1) % above EMA50/200
  let c = _bcSetup('bc-ema');
  if (c) {
    const toY = _bcAxes(c, 0, 100, d.dates, [20, 50, 80]);
    _bcLine(c, d.pct_above_ema50,  toY, '#e3b341');
    _bcLine(c, d.pct_above_ema200, toY, '#3fb950');
    document.getElementById('bc-ema-now').innerHTML =
      ` — <span style="color:#e3b341">EMA50: ${d.pct_above_ema50[n-1]}%</span> · ` +
      `<span style="color:#3fb950">EMA200: ${d.pct_above_ema200[n-1]}%</span>`;
  }

  // 2) NH - NL net bars
  c = _bcSetup('bc-nhnl');
  if (c) {
    const net = d.nh.map((h, i) => h - d.nl[i]);
    const m = Math.max(...net.map(Math.abs), 5);
    const toY = _bcAxes(c, -m, m, d.dates, [0]);
    _bcBars(c, net, toY, 0);
    const r = d.nhnl_ratio[n-1];
    document.getElementById('bc-nhnl-now').textContent =
      ` — NH ${d.nh[n-1]} / NL ${d.nl[n-1]}` + (r != null ? ` (ratio ${r})` : '');
  }

  // 3) McClellan Oscillator
  c = _bcSetup('bc-mcc');
  if (c) {
    const osc = d.mcclellan_osc;
    const m = Math.max(...osc.filter(v => v != null).map(Math.abs), 50);
    const toY = _bcAxes(c, -m, m, d.dates, [-70, 0, 70]);
    _bcBars(c, osc, toY, 0);
    const cur = osc[n-1], sum = d.mcclellan_sum[n-1];
    document.getElementById('bc-mcc-now').innerHTML = cur == null ? '' :
      ` — <span style="color:${cur >= 0 ? '#3fb950' : '#f85149'}">${cur}</span>` +
      (sum != null ? ` · summation ${sum >= 0 ? '+' : ''}${sum}` : '');
  }
}

// ============================================================
// MARKET REGIME LIGHT — ไฟ 3 โซนบน nav จาก % หุ้นเหนือ EMA200
// (เกณฑ์โซนมาจากผล backtest — ดูรายละเอียดที่ /backtest-report)
// ============================================================
async function loadRegimeLight() {
  const wrap  = document.getElementById('regime-wrap');
  const light = document.getElementById('regime-light');
  const tip   = document.getElementById('regime-tip');
  if (!wrap || !light) return;
  try {
    if (!_breadthData) {
      _breadthData = await _fetchBreadthRange('1y');   // coalesced กับ loadBreadthCharts — ไม่ fetch ซ้ำ
    }
    const arr = _breadthData.pct_above_ema200;
    const val = arr[arr.length - 1];
    if (val == null) return;

    let cls, icon, label, desc;
    if (val >= 50)      { cls = 'regime-on';  icon = '🟢'; label = 'Risk-On';
      desc = 'หุ้นเกินครึ่งตลาดอยู่เหนือ EMA200 — ช่วงที่สัญญาณ RS สูงทำงานได้ดีตามประวัติศาสตร์'; }
    else if (val >= 30) { cls = 'regime-mid'; icon = '🟡'; label = 'Caution';
      desc = 'โซน whipsaw (แบบปี 2024 ใน backtest) — ตลาดแกว่ง ระวังการเข้าออกถี่ พิจารณาลดขนาด position'; }
    else                { cls = 'regime-off'; icon = '🔴'; label = 'Risk-Off';
      desc = 'ทุก threshold ที่ backtest ทดสอบเห็นตรงกันว่าช่วงแบบนี้ (เช่น 2018–2019) การถือเงินสดคุ้มกว่า'; }

    light.className = cls;
    light.innerHTML = `${icon} ${label} <span style="opacity:.75">${val.toFixed(0)}%</span>`;
    tip.innerHTML =
      `<b>Market Regime: ${icon} ${label}</b><br>
       <span style="color:var(--text2)">% หุ้นเหนือ EMA200 ทั้งตลาด = <b>${val.toFixed(2)}%</b></span><br><br>
       ${desc}<br><br>
       <span style="color:#3fb950">🟢 ≥ 50</span> Risk-On ·
       <span style="color:#e3b341">🟡 30–50</span> Caution ·
       <span style="color:#f85149">🔴 &lt; 30</span> Risk-Off<br><br>
       <span style="color:var(--text2);font-size:11px">เกณฑ์มาจาก backtest RS+RRG 10.5 ปี (2016–2026) —
       regime filter เปลี่ยนปี 2018/2019 จาก −36.6%/−25.3% เป็น +4.5%/+7.1%
       แต่มีข้อจำกัดสำคัญ (survivorship bias ฯลฯ)</span><br>
       <a href="/backtest-report" target="_blank" rel="noopener">📄 อ่านรายงาน backtest ฉบับเต็ม + ข้อจำกัด →</a><br>
       <span style="color:var(--text2);font-size:10px">ข้อมูลบริบท ไม่ใช่คำแนะนำการลงทุน · คลิกที่ไฟเพื่อเปิดรายงาน</span>`;
    wrap.style.display = 'inline-block';
  } catch (e) { /* เงียบ — ไฟไม่ขึ้นแต่ dashboard ทำงานปกติ */ }
}

function renderEMABreadth() {
  if (!DATA) return;
  loadBreadthCharts();
  const key = emaBreadthView;
  const groups = {};
  DATA.stocks.forEach(s => {
    const g = s[key] || 'Unknown';
    if (!groups[g]) groups[g] = [];
    groups[g].push(s);
  });

  const rows = Object.entries(groups).map(([name, stocks]) => {
    const n    = stocks.length;
    const p20  = Math.round(stocks.filter(s => s.above_ema20  === true).length / n * 100);
    const p50  = Math.round(stocks.filter(s => s.above_ema50  === true).length / n * 100);
    const p200 = Math.round(stocks.filter(s => s.above_ema200 === true).length / n * 100);
    const score = Math.round((p20 + p50 + p200) / 3);
    return { name, n, p20, p50, p200, score };
  }).sort((a, b) => b.score - a.score);

  const bar = (v) => {
    const c = v >= 60 ? 'var(--green)' : v >= 40 ? 'var(--yellow)' : 'var(--red)';
    const tc = v >= 60 ? 'green' : v >= 40 ? 'yellow' : 'red';
    return `<div style="display:flex;align-items:center;gap:6px">
      <div style="flex:1;height:6px;background:var(--bg3);border-radius:3px;overflow:hidden">
        <div style="width:${v}%;height:100%;background:${c};border-radius:3px"></div>
      </div>
      <span class="${tc}" style="width:38px;text-align:right;font-size:12px;font-weight:600">${v}%</span>
    </div>`;
  };

  // สี Trend Score ตามเกณฑ์ที่ประกาศใน tooltip ของคอลัมน์: ≥70 แข็งแกร่ง (เขียว),
  // 40–70 ผสม (เหลือง), <40 อ่อนแอ (แดง) — เดิมใช้ rsColor() ซึ่งเป็นสเกลของ RS
  // (90/70/50) ทำให้ score 75 ขึ้นน้ำเงิน และ 45 ขึ้นแดง ขัดกับที่เอกสารบอก
  const trendScoreColor = (v) => v >= 70 ? 'green' : v >= 40 ? 'yellow' : 'red';

  document.getElementById('ema-breadth-tbody').innerHTML = rows.map((r, i) => `
    <tr style="cursor:pointer" onclick="openSectorModal('${r.name.replace(/'/g,"\\'")}')">
      <td class="text2">${i + 1}</td>
      <td><strong>${r.name}</strong>${sectorTvLink(r.name)}</td>
      <td class="r text2">${r.n}</td>
      <td style="min-width:140px;padding-right:12px">${bar(r.p20)}</td>
      <td style="min-width:140px;padding-right:12px">${bar(r.p50)}</td>
      <td style="min-width:140px;padding-right:12px">${bar(r.p200)}</td>
      <td class="r"><span class="${trendScoreColor(r.score)}" style="font-weight:700">${r.score}</span></td>
    </tr>`).join('');
}

// ============================================================
// ============================================================
// BREAKOUT RADAR
// ============================================================
// คอลัมน์ string/bool ที่ต้องเทียบต่างจากตัวเลขปกติ — ใช้ร่วมกันทั้ง Breakout Radar
// และ Momentum Alignment (โครงตาราง/คอลัมน์เหมือนกัน) ผ่าน _stockSortCompare/_stockSortTh
const _STOCK_SORT_STR  = new Set(['symbol','name','sector']);
const _STOCK_SORT_BOOL = new Set(['above_ema50','above_ema200']);

function _stockSortCompare(col, dir) {
  return (a, b) => {
    if (_STOCK_SORT_BOOL.has(col)) return ((b[col]?1:0) - (a[col]?1:0)) * dir;
    if (_STOCK_SORT_STR.has(col))  return ((a[col]??'').localeCompare(b[col]??'')) * dir;
    return ((b[col]??-Infinity) - (a[col]??-Infinity)) * dir;
  };
}
function _stockSortTh(col, label, sortCol, sortDir, setFn, cls='', tip=null) {
  const active = sortCol === col;
  const arrow  = active ? (sortDir === 1 ? '↓' : '↑') : '↕';
  const c = (cls ? cls+' ' : '') + 'sortable';
  const icon = tip !== undefined && tip !== null ? _tipIconHtml(tip) : colTipIcon(col);
  return `<th class="${c}" onclick="${setFn}('${col}')">${label}${icon}<span class="sort-ind${active?' on':''}">${arrow}</span></th>`;
}

let _boRS = 70, _boDist = 10, _boEMA = '50';
let _boSide = 'high';   // 'high' = Breakout/High watch, 'low' = Low watch
let _boSortCol = 'rs_score', _boSortDir = 1;

function setBoSort(col) {
  if (_boSortCol === col) _boSortDir *= -1;
  else { _boSortCol = col; _boSortDir = 1; }
  renderBreakout();
}

