const _BO_TIP_RANGE     = 'ตำแหน่งราคาในกรอบ 52 สัปดาห์: 0% = ที่ Low, 100% = ที่ High, เกิน 100% = ทะลุ High เดิม (วัดเป็นสัดส่วนของความกว้างกรอบ High−Low ไม่ใช่ % ของราคา)';
const _BO_TIP_FROM_HIGH = '% ห่างจาก 52W High — ติดลบ = ยังต่ำกว่า high, NEW HIGH = ราคาทะลุ high เดิมแล้ว';
const _BO_TIP_FROM_LOW  = '% เด้งขึ้นจาก 52W Low — ยิ่งน้อยยิ่งใกล้จุดต่ำสุด, NEW LOW = ทำจุดต่ำสุดใหม่';

// ไอคอน ℹ แตะ/ชี้เพื่อเปิดคำอธิบาย — ใช้งานได้ทั้ง desktop (hover, ผ่าน CSS :hover เดิม) และ
// มือถือ/แท็บเล็ต (แตะ) — ไอคอนอยู่ใน <th> ที่มักมี onclick sort ของตัวเอง จึงต้อง
// stopPropagation กันไม่ให้ทะลุไปโดน sort แต่ก็ทำให้ click ไปไม่ถึง document-level listener
// ที่ทำ tap-toggle ปกติ (บรรทัด ~6548) ด้วย เลยต้องทำ toggle เองตรงนี้แทน
function _tipIconToggle(el, ev) {
  ev.stopPropagation();
  document.querySelectorAll('.tt-open').forEach(o => { if (o !== el) o.classList.remove('tt-open'); });
  _tipIconPosition(el);
  el.classList.toggle('tt-open');
}

// คำนวณตำแหน่ง tipbox (.scr-tip-box เป็น position:fixed อ้างอิง viewport ไม่ใช่ตัวไอคอน
// อีกต่อไป — กันโดน clip เวลาไอคอนอยู่ในตารางที่ overflow-x:auto เช่นตารางงบการเงิน)
// เรียกตอน hover เริ่ม (mouseover ผ่าน document listener ด้านล่าง) และตอน tap เปิด
function _tipIconPosition(icon) {
  const box = icon.querySelector(':scope > .scr-tip-box');
  if (!box) return;
  const r = icon.getBoundingClientRect();
  const bw = box.offsetWidth || parseFloat(getComputedStyle(box).width) || 220;
  let left = r.left + r.width / 2 - bw / 2;
  left = Math.max(8, Math.min(left, window.innerWidth - bw - 8));
  let top = r.bottom + 6;
  const bh = box.offsetHeight || 0;
  if (bh && top + bh > window.innerHeight - 8) {
    top = Math.max(8, r.top - bh - 6);   // ไม่พอที่จะเปิดลงล่าง — เปิดขึ้นบนแทน
  }
  box.style.left = left + 'px';
  box.style.top  = top + 'px';
}
// hover บน desktop เปิดผ่าน CSS :hover ล้วนๆ (ไม่มี JS event) — ต้องดักตำแหน่งด้วย
// mouseover ที่ document เพราะ mouseenter ไม่ bubble ใช้ delegate ไม่ได้
document.addEventListener('mouseover', e => {
  const icon = e.target.closest('.scr-tip-icon');
  if (icon) _tipIconPosition(icon);
});
// หมายเหตุ: tap-toggle ของ .scr-tip-icon/.regime-wrap มี delegate กลางอยู่แล้ว
// (ดู document click listener ท้ายไฟล์) — ห้ามเพิ่ม listener ซ้ำ ไม่งั้น toggle ซ้อน
// (เปิดแล้วถูกปิดในคลิกเดียวกัน เพราะ stopPropagation ไม่กัน listener บน node เดียวกัน)
// กันตำแหน่งเพี้ยนถ้า scroll ตารางขณะ tipbox เปิดอยู่ (fixed ไม่ขยับตามไอคอนเอง)
window.addEventListener('scroll', () => {
  document.querySelectorAll('.scr-tip-icon:hover, .scr-tip-icon.tt-open').forEach(_tipIconPosition);
}, true);

// .btn-wrap/.btn-note (ปุ่ม Quick Update/Full Refresh/Restart, filter Stage ในหน้าหุ้นทั้งหมด)
// เดิม CSS ใช้ right:0 ตายตัว — ถ้าปุ่มอยู่ใกล้ขอบซ้ายจอ กล่อง note (กว้าง ~220px)
// จะยื่นเลยขอบซ้ายจอไปจนถูกตัดขาด อ่านไม่ครบ (เจอกับปุ่ม Stage ในหน้าหุ้นทั้งหมด)
// แก้โดยดัน right ติดลบชดเชยเมื่อจะล้น — ไม่กระทบปุ่มที่อยู่ใกล้ขอบขวาอยู่แล้ว (right:0 เดิม)
function _positionBtnNote(wrap) {
  const note = wrap.querySelector(':scope > .btn-note');
  if (!note) return;
  const r = wrap.getBoundingClientRect();
  const nw = note.offsetWidth || parseFloat(getComputedStyle(note).width) || 220;
  const nh = note.offsetHeight || 0;
  // ดีไซน์เดิมคือขอบขวากล่องตรงกับขอบขวาปุ่ม (right:0) — คงไว้ แล้วหนีบไม่ให้ล้นสองข้าง
  const left = Math.max(8, Math.min(r.right - nw, window.innerWidth - nw - 8));
  // ปกติเปิดลงล่าง ถ้าที่ไม่พอ (ปุ่มอยู่ครึ่งล่างจอ เช่น filter Stage กลางหน้า) เปิดขึ้นบนแทน
  let top = r.bottom + 6;
  if (nh && top + nh > window.innerHeight - 8) top = Math.max(8, r.top - nh - 6);
  note.style.left = left + 'px';
  note.style.top = top + 'px';
  note.style.right = 'auto';
  note.style.setProperty('--btn-note-arrow',
    Math.max(10, Math.min(r.left + r.width / 2 - left, nw - 10)) + 'px');
}
document.addEventListener('mouseover', e => {
  const wrap = e.target.closest('.btn-wrap');
  if (wrap) _positionBtnNote(wrap);
});
// fixed ไม่ขยับตามปุ่มเอง — ถ้า scroll ขณะกล่องเปิดอยู่ (nav เลื่อนแนวนอน หรือหน้าเลื่อน
// จนปุ่ม Stage ขยับ) ต้องคำนวณใหม่ ไม่งั้นกล่องค้างอยู่ที่เดิมแยกจากปุ่ม
window.addEventListener('scroll', () => {
  document.querySelectorAll('.btn-wrap:hover, .btn-wrap.tt-open').forEach(_positionBtnNote);
}, true);
// จอสัมผัส: ไม่มี hover จริง (iOS จำลอง hover ตอนแตะครั้งแรกแบบไม่เสถียร) — เพิ่ม
// tap-toggle ชัดเจนแทน ไม่ต้อง stopPropagation เพราะอยากให้ onclick เดิมของปุ่ม (กรอง/รีเฟรช) ทำงานควบคู่ไปด้วย
document.addEventListener('click', e => {
  const wrap = e.target.closest('.btn-wrap');
  document.querySelectorAll('.btn-wrap.tt-open').forEach(w => { if (w !== wrap) w.classList.remove('tt-open'); });
  if (wrap) { _positionBtnNote(wrap); wrap.classList.toggle('tt-open'); }
});
function _tipIconHtml(text) {
  if (!text) return '';
  return `<span class="scr-tip-icon" style="margin-left:4px" onclick="_tipIconToggle(this,event)">ℹ<div class="scr-tip-box">${text}</div></span>`;
}
function colTipIcon(col) {
  return _tipIconHtml(_COL_TIPS[col]);
}

function boTh(col, label, cls='', tip=null) {
  return _stockSortTh(col, label, _boSortCol, _boSortDir, 'setBoSort', cls, tip);
}

function setBO(type, val, btn) {
  if (type === 'rs')   _boRS   = val;
  if (type === 'dist') _boDist = val;
  if (type === 'ema')  _boEMA  = val;
  if (type === 'side') _boSide = val;
  // map type -> id prefix ของกลุ่มปุ่ม (dist ใช้ id "bo-d-*" ไม่ใช่ "bo-dist*"
  // — บั๊กเดิม: prefix ไม่ match ทำให้สี active ของกลุ่มระยะไม่เคยถูกล้าง)
  const prefix = { rs: 'bo-rs-', dist: 'bo-d-', ema: 'bo-ema-', side: 'bo-side-' }[type];
  document.querySelectorAll(`#stocks-view-breakout .filter-btn[id^="${prefix}"]`)
    .forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderBreakout();
}

function renderBreakout() {
  if (!DATA) return;
  const isHigh = _boSide === 'high';
  const aLbl   = isHigh ? 'High' : 'Low';
  const secRanks = computeSectorRanks();
  const stocks = DATA.stocks.map(s => {
    const anchor     = isHigh ? s.high_52w : s.low_52w;
    const fromAnchor = (anchor > 0 && s.price != null) ? (s.price - anchor) / anchor * 100 : null;
    const range      = (s.high_52w ?? 0) - (s.low_52w ?? 0);
    const rangePct   = range > 0 ? Math.round((s.price - s.low_52w) / range * 100) : null;
    const sr = secRanks[s.symbol];
    return { ...s, fromAnchor, rangePct, sec_rank: sr?.rank ?? null, sec_total: sr?.total ?? null };
  }).filter(s => {
    if (s.fromAnchor == null) return false;
    if ((s.rs_score ?? 0) < _boRS) return false;
    // high: ห่างลงจาก High ไม่เกิน X% | low: เด้งขึ้นจาก Low ไม่เกิน X%
    if (isHigh ? (s.fromAnchor < -_boDist) : (s.fromAnchor > _boDist)) return false;
    if (_boEMA === '50'  && !s.above_ema50)  return false;
    if (_boEMA === '200' && (!s.above_ema50 || !s.above_ema200)) return false;
    return true;
  }).sort(_stockSortCompare(_boSortCol, _boSortDir));

  const parts = [`${stocks.length} หุ้น`, isHigh ? 'ใกล้ 52W High' : 'ใกล้ 52W Low'];
  if (_boRS > 0)     parts.push(`RS ≥ ${_boRS}`);
  if (_boDist < 100) parts.push(`ห่าง ${aLbl} ≤ ${_boDist}%`);
  if (_boEMA !== 'any') parts.push(_boEMA === '50' ? '> EMA50' : '> EMA50+200');
  document.getElementById('bo-count').textContent = parts.join(' · ');

  const anchorCol = isHigh ? 'high_52w' : 'low_52w';
  document.getElementById('bo-thead').innerHTML = `<tr>
    ${boTh('rs_score','RS')}${boTh('sec_rank','Sec.Rank','r')}${boTh('symbol','Symbol')}${boTh('name','ชื่อ')}${boTh('sector','Sector')}
    ${boTh('price','ราคา','r')}${boTh(anchorCol,'52W '+aLbl,'r')}${boTh('fromAnchor','% จาก '+aLbl,'r', isHigh ? _BO_TIP_FROM_HIGH : _BO_TIP_FROM_LOW)}
    <th>Range${_tipIconHtml(_BO_TIP_RANGE)}</th>
    ${boTh('ret_1m','1M%','r')}${boTh('ret_3m','3M%','r')}${boTh('ret_ytd','YTD%','r')}
    ${boTh('vol_today','RVOL','r')}${boTh('mkt_cap','MKT CAP','r')}${boTh('above_ema50','EMA50','r')}${boTh('above_ema200','EMA200','r')}
  </tr>`;
  if (!stocks.length) {
    document.getElementById('bo-tbody').innerHTML =
      `<tr><td colspan="16" style="text-align:center;padding:20px;color:var(--text2)">ไม่พบหุ้นที่ตรงเงื่อนไข ลองผ่อนตัวกรอง (RS / ระยะห่าง / EMA)</td></tr>`;
    return;
  }
  document.getElementById('bo-tbody').innerHTML = stocks.map(s => {
    const fa = s.fromAnchor;
    const faHtml = isHigh
      ? `<span class="${fa >= -2 ? 'green' : fa >= -5 ? 'yellow' : 'text2'}">${fa >= 0 ? 'NEW HIGH' : fa.toFixed(2) + '%'}</span>`
      : `<span class="${fa <= 2 ? 'red' : fa <= 5 ? 'yellow' : 'text2'}">${fa <= 0.5 ? 'NEW LOW' : '+' + fa.toFixed(2) + '%'}</span>`;
    return `
    <tr>
      <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '—'}</span></td>
      <td class="r">${secRankHtml(s.sec_rank ? {rank:s.sec_rank,total:s.sec_total} : null)}</td>
      <td><strong class="sym-link" onclick="openChartModal('${s.symbol}')">${s.symbol}</strong>${tvLink(s.symbol)}${dqBadge(s)}</td>
      <td style="font-size:11px;color:var(--text2);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${s.name}</td>
      <td style="font-size:11px">${s.sector || '—'}</td>
      <td class="r">${s.price?.toFixed(2) ?? '—'}</td>
      <td class="r text2">${(isHigh ? s.high_52w : s.low_52w)?.toFixed(2) ?? '—'}</td>
      <td class="r">${faHtml}</td>
      <td>
        <div class="range-bar-wrap">
          <div class="range-bar-track"><div class="range-bar-fill" style="width:${s.rangePct ?? 0}%"></div></div>
          <div style="font-size:10px;color:var(--text2);text-align:right">${s.rangePct ?? '—'}%</div>
        </div>
      </td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_ytd)}</td>
      <td class="r">${rvolHtml(s)}</td>
      <td class="r" style="font-size:11px">${fmtCap(s.mkt_cap, s.is_reit)}</td>
      <td class="r">${emaBadge(s.above_ema50)}</td>
      <td class="r">${emaBadge(s.above_ema200)}</td>
    </tr>`;
  }).join('');
}

// ============================================================
// MOMENTUM ALIGNMENT
// ============================================================
let _momFilter = 'all4';
let _momSortCol = 'rs_score', _momSortDir = 1;

function setMomSort(col) {
  if (_momSortCol === col) _momSortDir *= -1;
  else { _momSortCol = col; _momSortDir = 1; }
  renderMomentum();
}

function momTh(col, label, cls='') {
  return _stockSortTh(col, label, _momSortCol, _momSortDir, 'setMomSort', cls);
}

function setMomFilter(val, btn) {
  _momFilter = val;
  document.querySelectorAll('#stocks-view-momentum .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderMomentum();
}

function renderMomentum() {
  if (!DATA) return;
  const secRanks = computeSectorRanks();
  const stocks = DATA.stocks.filter(s => {
    if (_momFilter === 'all4') return (s.ret_1d ?? -1) > 0 && (s.ret_1w ?? -1) > 0 && (s.ret_1m ?? -1) > 0 && (s.ret_3m ?? -1) > 0;
    if (_momFilter === '3tf')  return (s.ret_1w ?? -1) > 0 && (s.ret_1m ?? -1) > 0 && (s.ret_3m ?? -1) > 0;
    if (_momFilter === '2tf')  return (s.ret_1m ?? -1) > 0 && (s.ret_3m ?? -1) > 0;
    return true;
  }).map(s => {
    const sr = secRanks[s.symbol];
    return { ...s, sec_rank: sr?.rank ?? null, sec_total: sr?.total ?? null };
  }).sort(_stockSortCompare(_momSortCol, _momSortDir));

  const tfLabel = { all4: 'ทุก 4 Timeframe (1D·1W·1M·3M)', '3tf': '3 Timeframe (1W·1M·3M)', '2tf': '2 Timeframe (1M·3M)' };
  document.getElementById('mom-count').textContent = `${stocks.length} หุ้น — ${tfLabel[_momFilter]}`;
  document.getElementById('mom-thead').innerHTML = `<tr>
    ${momTh('rs_score','RS')}${momTh('sec_rank','Sec.Rank','r')}${momTh('symbol','Symbol')}${momTh('name','ชื่อ')}${momTh('sector','Sector')}
    ${momTh('price','ราคา','r')}
    ${momTh('ret_1d','1D%','r')}${momTh('ret_1w','1W%','r')}${momTh('ret_1m','1M%','r')}${momTh('ret_3m','3M%','r')}${momTh('ret_ytd','YTD%','r')}
    ${momTh('vol_today','RVOL','r')}${momTh('mkt_cap','MKT CAP','r')}${momTh('above_ema50','EMA50','r')}${momTh('above_ema200','EMA200','r')}
  </tr>`;
  if (!stocks.length) {
    document.getElementById('mom-tbody').innerHTML =
      `<tr><td colspan="15" style="text-align:center;padding:20px;color:var(--text2)">ไม่พบหุ้นที่ตรงเงื่อนไข ลองเลือกช่วงเวลาที่ผ่อนคลายกว่านี้</td></tr>`;
    return;
  }
  document.getElementById('mom-tbody').innerHTML = stocks.map(s => {
    return `
    <tr>
      <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '—'}</span></td>
      <td class="r">${secRankHtml(s.sec_rank ? {rank:s.sec_rank,total:s.sec_total} : null)}</td>
      <td><strong class="sym-link" onclick="openChartModal('${s.symbol}')">${s.symbol}</strong>${tvLink(s.symbol)}${dqBadge(s)}</td>
      <td style="font-size:11px;color:var(--text2);max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${s.name}</td>
      <td style="font-size:11px">${s.sector || '—'}</td>
      <td class="r">${s.price?.toFixed(2) ?? '—'}</td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_ytd)}</td>
      <td class="r">${rvolHtml(s)}</td>
      <td class="r" style="font-size:11px">${fmtCap(s.mkt_cap, s.is_reit)}</td>
      <td class="r">${emaBadge(s.above_ema50)}</td>
      <td class="r">${emaBadge(s.above_ema200)}</td>
    </tr>`}).join('');
}

// ============================================================
// PERSISTENT SCREENER SETTINGS
// ============================================================
const _SCR_LS = 'set_scr_v1';
const _SCR_FIELDS = ['scr-rs-min','scr-1m','scr-3m','scr-1d','scr-ytd','scr-cap',
                     'scr-price-min','scr-price-max','scr-from-high','scr-ath-dist','scr-from-low',
                     'scr-pe-min','scr-pe','scr-pbv-min','scr-pbv','scr-ps','scr-dy','scr-rvol','scr-atr-max','scr-seas-min','scr-1w','scr-6m','scr-1y',
                     'scr-growth-min','scr-peg-max','scr-fcf-yield-min','scr-div-cover-min','scr-rev-streak-min','scr-profit-streak-min',
                     'scr-rev-qoq-min','scr-profit-qoq-min','scr-rev-yoyq-min','scr-profit-yoyq-min',
                     'scr-rev-qstreak-min','scr-profit-qstreak-min','scr-margin-qstreak-min',
                     'scr-rev-posstreak-min','scr-profit-posstreak-min','scr-ebitda-posstreak-min','scr-ocf-posstreak-min',
                     'scr-rev-accel-min','scr-profit-accel-min','scr-margin-yoyq-min','scr-ttm-margin-min',
                     'scr-gross-margin-min','scr-roe-min','scr-net-margin-min',
                     'scr-gross-margin-trend-min','scr-roe-trend-min','scr-net-margin-trend-min',
                     'scr-de-ratio-max','scr-interest-coverage-min',
                     'scr-de-ratio-trend-min','scr-interest-coverage-trend-min',
                     'scr-ratio-years-back','scr-rvol-days'];
const _SCR_CHECKS = ['scr-ema20','scr-ema50','scr-ema200','scr-golden-cross',
                     'scr-new52h','scr-sma-cross50','scr-sma-cross200',
                     'scr-ema-cross50','scr-ema-cross200','scr-ema200-reclaim',
                     'scr-rsi-rebound','scr-bullish-vol',
                     'scr-backtest','scr-include-dr','scr-insider-buy','scr-ocf-gt-ni'];

function _populateScrIndustry() {
  if (!DATA) return;
  const sel = document.getElementById('scr-industry');
  if (!sel) return;
  const industries = [...new Set(DATA.stocks.map(s => s.industry).filter(Boolean))].sort();
  while (sel.options.length > 1) sel.remove(1);
  industries.forEach(ind => {
    const opt = document.createElement('option');
    opt.value = ind; opt.textContent = ind;
    sel.appendChild(opt);
  });
}

function saveScreenerSettings() {
  const s = {};
  _SCR_FIELDS.forEach(id => { const el = document.getElementById(id); if (el) s[id] = el.value; });
  _SCR_CHECKS.forEach(id => { const el = document.getElementById(id); if (el) s[id] = el.checked; });
  const mk = document.getElementById('scr-market'); if (mk) s['scr-market'] = mk.value;
  const ind = document.getElementById('scr-industry'); if (ind) s['scr-industry'] = ind.value;
  // localStorage.setItem อาจ throw (QuotaExceededError เต็ม/SecurityError โดน block) —
  // runScreener() เรียกฟังก์ชันนี้เป็นบรรทัดแรก ถ้าไม่กันไว้ throw ตรงนี้จะทำให้กด "ค้นหา"
  // ไม่ทำงานเลยทั้งฟังก์ชัน โดยไม่มีข้อความอะไรบอกผู้ใช้เลย
  try { localStorage.setItem(_SCR_LS, JSON.stringify(s)); } catch(e) {}
}

function loadScreenerSettings() {
  try {
    const raw = localStorage.getItem(_SCR_LS);
    if (!raw) return;
    const s = JSON.parse(raw);
    _SCR_FIELDS.forEach(id => { if (s[id] != null) { const el = document.getElementById(id); if (el) el.value = s[id]; } });
    _SCR_CHECKS.forEach(id => { if (s[id] != null) { const el = document.getElementById(id); if (el) el.checked = s[id]; } });
    if (s['scr-market']) { const el = document.getElementById('scr-market'); if (el) el.value = s['scr-market']; }
    if (s['scr-industry']) { const el = document.getElementById('scr-industry'); if (el) el.value = s['scr-industry']; }
  } catch(e) {}
}

// migrate ครั้งเดียวตลอดไป (ไม่ใช่ทุกครั้งที่โหลดหน้า) — RVOL เปลี่ยนหน่วยจาก % เป็น 'เท่า'
// ค่าเก่าที่บันทึกไว้แบบ % (เช่น 150) ตีความใหม่เป็นเท่า (1.5) ครั้งเดียว มี flag กันรันซ้ำ
// เดิม heuristic นี้รันทุกครั้งที่โหลดหน้า (>20 -> หาร100) ทำให้ถ้าผู้ใช้ตั้งใจพิมพ์
// RVOL>=21 เท่าจริงๆ (ล่าหุ้นปริมาณเบา) ค่าจะโดนบิดเหลือ 0.21 อัตโนมัติทุกครั้งที่ refresh
// ทำแบบรวมศูนย์ที่นี่ (แทนที่จะซ้ำใน loadScreenerSettings/loadSavedPreset แยกกัน) เพื่อให้
// ทั้ง autosave และ preset ที่บันทึกไว้ก่อนหน้านี้ได้ migrate เหมือนกันแน่นอน
const _SCR_RVOL_MIGRATED_LS = 'set_scr_rvol_migrated_v1';
function _scrMigrateRvolOnce() {
  try {
    if (localStorage.getItem(_SCR_RVOL_MIGRATED_LS)) return;
    const migrateOne = (s) => {
      if (s && s['scr-rvol'] != null && parseFloat(s['scr-rvol']) > 20) {
        s['scr-rvol'] = String(parseFloat(s['scr-rvol']) / 100);
      }
    };
    const raw = localStorage.getItem(_SCR_LS);
    if (raw) {
      const s = JSON.parse(raw);
      migrateOne(s);
      localStorage.setItem(_SCR_LS, JSON.stringify(s));
    }
    const presets = _loadPresets();
    Object.values(presets).forEach(migrateOne);
    localStorage.setItem(_PRESETS_LS, JSON.stringify(presets));
    localStorage.setItem(_SCR_RVOL_MIGRATED_LS, '1');
  } catch (e) {}
}

// autosave ทุกครั้งที่แก้ค่า filter — เดิมบันทึกเฉพาะตอนกด "ค้นหา"
// ทำให้ค่าที่พิมพ์ไว้แต่ยังไม่ได้กดค้นหาหายเมื่อ refresh หน้า
let _scrAutosaveWired = false;
function initScreenerAutosave() {
  if (_scrAutosaveWired) return;
  _scrAutosaveWired = true;
  _SCR_FIELDS.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', saveScreenerSettings);
  });
  _SCR_CHECKS.concat(['scr-market', 'scr-industry']).forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', saveScreenerSettings);
  });
}

// ============================================================
// SAVED PRESETS
// ============================================================
const _PRESETS_LS = 'set_scr_presets_v1';

function _loadPresets() {
  try { return JSON.parse(localStorage.getItem(_PRESETS_LS) || '{}'); } catch(e) { return {}; }
}

function saveCurrentPreset() {
  const name = document.getElementById('preset-name-input').value.trim();
  if (!name) return;
  const presets = _loadPresets();
  const s = {};
  _SCR_FIELDS.forEach(id => { const el = document.getElementById(id); if (el) s[id] = el.value; });
  _SCR_CHECKS.forEach(id => { const el = document.getElementById(id); if (el) s[id] = el.checked; });
  const mk = document.getElementById('scr-market'); if (mk) s['scr-market'] = mk.value;
  const ind = document.getElementById('scr-industry'); if (ind) s['scr-industry'] = ind.value;
  presets[name] = s;
  // setItem อาจ throw (เต็ม/ถูก block) — ไม่กันไว้จะเงียบๆ ไม่บันทึก preset โดยผู้ใช้ไม่รู้
  try { localStorage.setItem(_PRESETS_LS, JSON.stringify(presets)); } catch(e) {}
  document.getElementById('preset-name-input').value = '';
  renderSavedPresets();
}

function loadSavedPreset(name) {
  const presets = _loadPresets();
  const s = presets[name];
  if (!s) return;
  // ล้างทุกช่องก่อนเสมอ (เหมือน applyPreset) — กัน field ที่เพิ่มเข้ามาใหม่หลังบันทึก
  // preset นี้ไว้ค้างค่าจากการค้นหาครั้งก่อนหน้าปนเข้าไปในผลลัพธ์
  _SCR_FIELDS.forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  _SCR_CHECKS.forEach(id => { const el = document.getElementById(id); if (el) el.checked = false; });
  // ตั้ง default เหมือน applyPreset() ก่อนใส่ค่าจาก preset — preset เก่าที่บันทึกไว้ก่อน
  // field เหล่านี้จะมีถูกเว้นว่าง(select ไม่มี option ว่างเลย selectedIndex เป็น -1) หรือ
  // สืบทอดค่าที่เลือกค้างอยู่ในหน้าจอแทนการค้นทั้งตลาดตามที่ preset ตั้งใจ
  const mk = document.getElementById('scr-market'); if (mk) mk.value = 'ALL';
  const ind = document.getElementById('scr-industry'); if (ind) ind.value = 'ALL';
  const yb = document.getElementById('scr-ratio-years-back'); if (yb) yb.value = '1';
  const rvd = document.getElementById('scr-rvol-days'); if (rvd) rvd.value = '20';
  _SCR_FIELDS.forEach(id => { if (s[id] != null) { const el = document.getElementById(id); if (el) el.value = s[id]; } });
  _SCR_CHECKS.forEach(id => { if (s[id] != null) { const el = document.getElementById(id); if (el) el.checked = s[id]; } });
  if (s['scr-market']) { const el = document.getElementById('scr-market'); if (el) el.value = s['scr-market']; }
  if (s['scr-industry']) { const el = document.getElementById('scr-industry'); if (el) el.value = s['scr-industry']; }
  runScreener();
}

function deleteSavedPreset(name) {
  const presets = _loadPresets();
  delete presets[name];
  try { localStorage.setItem(_PRESETS_LS, JSON.stringify(presets)); } catch(e) {}
  renderSavedPresets();
}

function renderSavedPresets() {
  const presets = _loadPresets();
  const row = document.getElementById('saved-presets-row');
  if (!row) return;
  const names = Object.keys(presets);
  if (names.length === 0) {
    row.innerHTML = '<span style="font-size:11px;color:var(--text2);font-style:italic">ยังไม่มี preset</span>';
    return;
  }
  // ชื่อ preset ต้อง escape เป็น HTML entity — JSON.stringify ให้ double quote
  // ซึ่งชนกับ quote ของ attribute ทำให้ onclick พังเงียบ (บั๊กเดิม)
  const _attrArg = n => JSON.stringify(n)
    .replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  const _escHtml = n => String(n)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  row.innerHTML = names.map(n =>
    `<span class="preset-saved-btn" onclick="loadSavedPreset(${_attrArg(n)})">
      ${_escHtml(n)}<button class="preset-del" onclick="event.stopPropagation();deleteSavedPreset(${_attrArg(n)})" title="ลบ">✕</button>
    </span>`
  ).join('');
}

// ============================================================
// EXPORT CSV
// ============================================================
function exportScreenerCSV() {
  if (!_scrStocks || _scrStocks.length === 0) return;
  // ใช้ _scrComputeSorted() ตัวเดียวกับตาราง — ไฟล์ CSV จะเรียงลำดับตรงกับที่เห็นบนจอ
  // เสมอ (เดิม export จาก _scrStocks ดิบๆ ไม่ผ่านการ sort) และคอลัมน์ครบเท่าตาราง
  // (เดิมขาด 6M%, RVOL, Growth, PEG, FCF Yield%, Div Cover)
  const sorted = _scrComputeSorted();
  const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const header = ['Symbol','Name','Sector','RS','Sec.Rank','Price',
                  '1D%','1W%','1M%','3M%','6M%','1Y%','YTD%',
                  '% From High','% From Low','P/E','P/BV','Div Yield%','RVOL',
                  'Mkt Cap (MB)','EMA50','EMA200',
                  'Growth','PEG','FCF Yield%','Div Cover',
                  ..._scrExtraCols.map(def => def.label)].map(esc).join(',');
  const rows = sorted.map(s => {
    return [
      s.symbol, s.name, s.sector || '',
      s.rs_score ?? '', s.sec_rank ? `${s.sec_rank}/${s.sec_total}` : '',
      s.price?.toFixed(2) ?? '',
      s.ret_1d?.toFixed(2) ?? '', s.ret_1w?.toFixed(2) ?? '',
      s.ret_1m?.toFixed(2) ?? '', s.ret_3m?.toFixed(2) ?? '', s.ret_6m?.toFixed(2) ?? '',
      s.ret_1y?.toFixed(2) ?? '', s.ret_ytd?.toFixed(2) ?? '',
      s.fromHigh != null ? s.fromHigh.toFixed(2) : '',
      s.fromLow  != null ? s.fromLow.toFixed(2)  : '',
      s.pe?.toFixed(2) ?? '', s.pbv?.toFixed(2) ?? '',
      s.div_yield?.toFixed(2) ?? '',
      s.rvol != null ? (s.rvol / 100).toFixed(2) : '',
      s.mkt_cap ? Math.round(s.mkt_cap / 1e6) : '',
      s.above_ema50 === true ? 'Y' : s.above_ema50 === false ? 'N' : '',
      s.above_ema200 === true ? 'Y' : s.above_ema200 === false ? 'N' : '',
      s.growth_score?.toFixed(2) ?? '',
      s.peg?.toFixed(2) ?? '',
      s.fcf_yield?.toFixed(2) ?? '',
      s.dividend_coverage?.toFixed(2) ?? '',
      ..._scrExtraCols.map(def => { const v = s[def.field]; return v == null ? '' : (typeof v === 'number' ? v.toFixed(2) : v); }),
    ].map(esc).join(',');
  });
  const csv = '﻿' + header + '\n' + rows.join('\n');
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })),
    download: `SET_Screener_${new Date().toISOString().slice(0,10)}.csv`,
  });
  a.click(); URL.revokeObjectURL(a.href);
}

// ============================================================
// WATCHLIST SYNC ข้ามเครื่อง — localStorage แยกต่อเครื่อง จึงให้คัดลอก/วางเป็น
// ข้อความ (WL:PTT,KBANK,DR:AAPL,...) ส่งผ่าน LINE/โน้ตหาตัวเองได้ ไม่ต้องมี server
// ต่อท้ายด้วย |AL:SYM>cond>price>note;... เก็บ price alert (set_price_alerts) ที่ยัง
// ไม่ triggered ของหุ้นในลิสต์นี้ไปด้วย เพราะ alert เก็บใน localStorage ล้วนๆ ไม่เคย sync
// ขึ้น server เหมือน watchlist เอง (ดู memory ของบทสนทนาที่รายงานว่าย้ายเครื่องแล้วราคา
// แจ้งเตือนหาย) — ตัด ; > | ออกจาก note กันข้อความหลุด delimiter
// ============================================================
function wlExport() {
  if (!watchlist.length) { alert('Watchlist ยังว่างอยู่'); return; }
  const activeAlerts = _loadAlerts().filter(a => !a.triggered && watchlist.includes(a.symbol));
  const alertPart = activeAlerts.length
    ? '|AL:' + activeAlerts.map(a => {
        const note = (a.note || '').replace(/[;>|]/g, ' ').trim();
        return `${a.symbol}>${a.condition}>${a.targetPrice}>${note}`;
      }).join(';')
    : '';
  const code = 'WL:' + watchlist.join(',') + alertPart;
  const alertNote = activeAlerts.length ? ` + แจ้งเตือน ${activeAlerts.length} รายการ` : '';
  const done = () => alert(`คัดลอกแล้ว (${watchlist.length} ตัว${alertNote}) — เอาไปกด "📥 วางจากเครื่องอื่น" บนอีกเครื่องได้เลย

${code}`);
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(code).then(done).catch(() => prompt('คัดลอกข้อความนี้:', code));
  } else {
    prompt('คัดลอกข้อความนี้:', code);
  }
}

function wlImport() {
  const raw = prompt('วางข้อความ watchlist ที่คัดลอกมาจากอีกเครื่อง (ขึ้นต้นด้วย WL:)');
  if (!raw) return;
  const [wlPart, alertPart] = raw.trim().replace(/^WL:/i, '').split(/\|AL:/i);
  const syms = wlPart.split(/[,\s]+/).map(s => s.trim().toUpperCase()).filter(Boolean);
  if (!syms.length) { alert('ไม่พบรายชื่อหุ้นในข้อความ'); return; }
  const before = watchlist.length;
  // เพดานเดียวกับ backend (500 ตัว) — กันนำเข้าจนลิสต์บวมเกิน sync ข้ามเครื่องไม่ขึ้น
  // ใช้ _wlListHas (รู้จัก prefix) แทน .includes ตรงๆ — กันเข้าซ้ำเวลาอีกเครื่อง export ก่อน
  // migrate เป็น prefix (เช่น "OKTA" bare) แต่เครื่องนี้มี "US:OKTA" อยู่แล้ว ไม่งั้นได้ 2 แถว
  syms.forEach(s => { if (!_wlListHas(watchlist, s) && watchlist.length < 500) watchlist.push(s); });
  _wlSave();

  let newAlerts = 0;
  if (alertPart) {
    const alerts = _loadAlerts();
    alertPart.split(';').map(e => e.trim()).filter(Boolean).forEach(entry => {
      const [symbol, condition, priceStr, ...noteParts] = entry.split('>');
      const targetPrice = parseFloat(priceStr);
      if (!symbol || (condition !== 'above' && condition !== 'below') || !targetPrice) return;
      const note = noteParts.join('>').trim();
      const dup = alerts.some(a => a.symbol === symbol && a.condition === condition && a.targetPrice === targetPrice && !a.triggered);
      if (dup) return;
      alerts.unshift({
        id: Date.now().toString() + Math.random().toString(36).slice(2, 6),
        symbol, condition, targetPrice, note,
        createdAt: new Date().toISOString(),
        triggered: false, triggeredAt: null, triggeredPrice: null,
      });
      newAlerts++;
    });
    if (newAlerts) { _saveAlerts(alerts); _updateBellBadge(); if (_alertPanelOpen) renderAlertPanel(); }
  }

  const alertMsg = newAlerts ? ` + แจ้งเตือน ${newAlerts} รายการ` : '';
  alert(`นำเข้าแล้ว ${watchlist.length - before} ตัวใหม่${alertMsg} (รวมทั้งหมด ${watchlist.length} ตัว — ตัวที่มีอยู่แล้วไม่ซ้ำ)`);
  if (document.getElementById('page-watchlist')?.classList.contains('active')) renderWatchlist();
}

// ============================================================
// PRICE CHART MODAL
// ============================================================
let _cmStock       = null;
let _cmTf          = '1y';
let _cmHistoryData = null;  // full history from /api/history/<symbol>
let _cmVolumeData  = null;  // volume array aligned with _cmHistoryData
const _CM_TF_BARS  = { '1m': 21, '3m': 63, '6m': 126, '1y': 260, '5y': 1260, 'max': 99999 };
// ราคาสดจาก Yahoo — ตัวเดียวกับที่แทปงบการเงินใช้คำนวณ PE/PBV band สด (/api/live-price)
// price_history ล่าสุดเป็นราคาปิด EOD ของ Quick/Full Update รอบก่อน อาจเก่ากว่าราคาสด
// ระหว่างวัน — หุ้น DR ไม่ต้องดึงเพิ่ม เพราะ s.live_price ติดมากับข้อมูล DR อยู่แล้ว
// (ดู app.py _dr_do_rebuild) ตัวแปรนี้ใช้เฉพาะหุ้นไทยทั่วไปที่เปิดผ่าน openChartModal
let _cmLivePrice    = null;
let _cmLivePriceSym = null;   // symbol ที่ _cmLivePrice เป็นของ — กัน response เก่ามาทับตอนเปลี่ยนหุ้น

async function setCmTf(tf, btn) {
  _cmTf = tf;
  document.querySelectorAll('#chart-modal .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (!_cmStock) return;
  if ((tf === '5y' || tf === 'max') && !_cmHistoryData) {
    await _fetchLongHistory();
  }
  _drawChart(_cmStock, _cmHistoryData);
}

// เวอร์ชันเว็บ (static) ไม่มี endpoint ประวัติราคาเต็ม — ป้ายบอกข้อจำกัด (ครั้งเดียวต่อ modal)
function _cmStaticLimitNote() {
  const sub = document.getElementById('cm-sub');
  if (sub && !sub.textContent.includes('🌐')) {
    sub.textContent += ' · 🌐 เวอร์ชันเว็บ: กราฟย้อนได้ ~1 ปี (หุ้นไทย) / ~100 วัน (DR) / ~2 ปี (ETF)';
  }
}

async function _fetchLongHistory() {
  if (!_cmStock) return;
  if (IS_STATIC) {
    // ใช้ข้อมูลที่ฝังมากับไฟล์แทนการ fetch (เดิมทับกราฟด้วย "กำลังโหลด..." แล้วค้าง
    // เพราะ endpoint ไม่มีบนเว็บ static): หุ้นไทย = price_history ~260 วัน,
    // DR = close100 (วันที่ประมาณจากปฏิทินย้อนหลัง)
    if (!_cmHistoryData) {
      if (_cmStock._isDR) {
        const c100 = _cmStock.close100 || [];
        if (c100.length) {
          const today = new Date();
          _cmHistoryData = c100.map((p, i) => {
            const d = new Date(today);
            d.setDate(d.getDate() - (c100.length - 1 - i));
            return [d.toISOString().slice(0, 10), p];
          });
        }
      } else if (_cmStock.price_history?.length) {
        _cmHistoryData = _cmStock.price_history;
      }
    }
    _cmStaticLimitNote();
    return;
  }
  const canvas = document.getElementById('cm-canvas');
  if (canvas) {
    const dpr = window.devicePixelRatio || 1;
    const W   = canvas.parentElement.clientWidth - 40;
    const H   = 300;
    canvas.width  = W * dpr; canvas.height = H * dpr;
    canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.fillStyle = '#161b22';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#8b949e';
    ctx.font = '13px Segoe UI,sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('กำลังโหลด full history...', W / 2, H / 2);
  }
  try {
    const endpoint = _cmStock._isDR
      ? `/api/dr-history/${encodeURIComponent(_cmStock.symbol)}`
      : _cmStock._isETF
      ? `/api/etf-history/${encodeURIComponent(_cmStock.symbol)}`
      : _cmStock._isUSIdx
      ? `/api/us-history/${encodeURIComponent(_cmStock.symbol)}`
      : _cmStock._isHKIdx
      ? `/api/hk-history/${encodeURIComponent(_cmStock.symbol)}`
      : _cmStock._isJPIdx
      ? `/api/jp-history/${encodeURIComponent(_cmStock.symbol)}`
      : `/api/history/${encodeURIComponent(_cmStock.symbol)}`;
    const r = await fetch(endpoint);
    const d = await r.json();
    if (d.error || !d.dates) {
      console.warn('history fetch error:', d.error);
      return;
    }
    _cmHistoryData = d.dates.map((date, i) => [date, d.closes[i]]);
    _cmVolumeData  = d.volumes || null;
  } catch (e) {
    console.error('fetch history error:', e);
  }
}

// เปิด/ปิดปุ่ม "เทียบเพื่อน"/"ดูสรุปเต็ม" ตาม _cmStock ปัจจุบัน — หุ้น DR ที่ underlying
// ไม่ใช่ตลาด US/HK (JP/SG/TW/VN/EU/CN ~63 ตัว) ยังไม่มี cohort ให้จัดอันดับ RS/เทียบ sector
// -> ปุ่ม "เทียบเพื่อน" ยังปิด (backend /api/peer-compare ตอบ 501) แต่ Tearsheet เปิดได้แล้ว
// แบบ lite (งบ/F-Z/DCF/ปันผล/valuation ครบ ไม่มี RS/peer — ดู fetch_header_lite ใน backend)
// เรียกทุกครั้งที่เปิด modal (ทุกประเภทหุ้น) เพราะปุ่มใช้ element เดียวกันข้าม modal ทุกตัว
function _cmSyncPeerTearsheetButtons() {
  const peerBtn = document.getElementById('cm-peer-btn');
  const tsBtn = document.getElementById('cm-tearsheet-btn');
  if (!peerBtn || !tsBtn) return;
  // ETF: ไม่มี "underlying company" เดี่ยวให้ route ไป Tearsheet และไม่มี cohort sector
  // ให้เทียบเพื่อน — ปิดทั้งคู่เสมอ (popup นี้เองคือหน้ารายละเอียดเต็มของ ETF แล้ว)
  if (_cmStock?._isETF) {
    [peerBtn, tsBtn].forEach(btn => { btn.disabled = true; btn.style.opacity = '0.4'; btn.style.cursor = 'not-allowed'; });
    peerBtn.title = 'ETF ไม่มี sector cohort ให้เทียบเพื่อน';
    tsBtn.title = 'ETF ไม่มี "บริษัทเดี่ยว" ให้ดู Tearsheet — ดูรายละเอียดในหน้าต่างนี้แทน';
    return;
  }
  const isDr = !!_cmStock?._isDR;
  const nonCohort = isDr && _cmStock.region !== 'US' && _cmStock.region !== 'HK';
  // Peer ปิดเมื่อ nonCohort, Tearsheet เปิดเสมอ (lite รองรับทุกตลาด DR แล้ว) — หุ้น JP
  // (_isJPIdx) เป็นสมาชิกดัชนีหลัก Nikkei 225 มี cohort/mirror financials เต็มแล้วเหมือน
  // US/HK เลยไม่ต้อง disable พิเศษ (isDr=false อยู่แล้วสำหรับ path นี้)
  const cfg = [[peerBtn, nonCohort], [tsBtn, false]];
  cfg.forEach(([btn, off]) => {
    btn.disabled = off;
    btn.style.opacity = off ? '0.4' : '';
    btn.style.cursor = off ? 'not-allowed' : 'pointer';
  });
  peerBtn.title = nonCohort
    ? `หุ้น DR underlying ตลาด ${_cmStock.region || '?'} ยังไม่มี cohort ให้เทียบเพื่อน — เปิด "ดูสรุปเต็ม" ได้ (งบ/F-Z/DCF/ปันผล)`
    : 'เทียบกับเพื่อนร่วม sector';
  tsBtn.title = nonCohort
    ? `ดูสรุปเต็มแบบ lite (งบ/F-Score/Z-Score/DCF/ปันผล — ตลาด ${_cmStock.region} ยังไม่มี RS/เทียบเพื่อน)`
    : 'ดูสรุปเต็ม (Tearsheet)';
}

// เช็คซ้ำว่าปุ่ม "งบการเงิน" ควรโผล่ไหม — เรียกทั้งตอนเปิด modal ปกติ และตอน
// loadFinAnalytics() โหลดเสร็จช้าระหว่างที่ modal เปิดค้างอยู่แล้ว (กันเคสที่ปุ่มหาย)
function _refreshCmFinButton() {
  if (!_cmStock?._isDR) return;
  const drFinBtn = document.getElementById('cm-mode-fin');
  if (!drFinBtn) return;
  const drHasFin = !!(_finAnalyticsData?.dr && _finAnalyticsData.dr[_cmStock.symbol]);
  drFinBtn.style.display = drHasFin ? '' : 'none';
}

function openDRChartModal(sym) {
  const s = (_drData || []).find(x => x.sym === sym);
  if (!s) return;

  const _cmTitleEl1 = document.getElementById('cm-title');
  _cmTitleEl1.textContent = `${s.sym}  ${s.name}`;
  _cmTitleEl1.title = `${s.sym}  ${s.name}`;
  document.getElementById('cm-sub').textContent   = `${s.ind || '—'} · RS ${s.rs_score ?? '—'} · ${_drExchBadge(s.yf)}`;
  document.getElementById('cm-tv-link').href = `https://www.tradingview.com/chart/?symbol=${yfToTVSym(s.yf)}&interval=D`;
  const jittaLinkDR = document.getElementById('cm-jitta-link');
  jittaLinkDR.style.display = 'inline-flex';
  jittaLinkDR.onclick = ev => openJittaFromYf(s.yf, ev);

  const mk = (val, lbl, cls = '') =>
    `<div><div class="cm-metric-val ${cls}">${val}</div><div class="cm-metric-lbl">${lbl}</div></div>`;
  const cPct = v => v != null ? (v >= 0 ? '+' : '') + v.toFixed(2) + '%' : '—';
  const pCls = v => v == null ? '' : v >= 0 ? 'green' : 'red';

  const athPctCls = v => v == null ? '' : v >= -5 ? 'green' : v >= -20 ? 'yellow' : 'red';
  const fmtPx = v => v != null ? _drFmtPrice(v) : '—';
  document.getElementById('cm-metrics').innerHTML = [
    mk(_drFmtPrice(s.price) + _drLiveTag(s), 'ราคา'),
    mk(cPct(s.chg),    '1D%', pCls(s.chg)),
    mk(cPct(s.ret_1w), '1W%', pCls(s.ret_1w)),
    mk(cPct(s.ret_1m), '1M%', pCls(s.ret_1m)),
    mk(cPct(s.ret_3m), '3M%', pCls(s.ret_3m)),
    `<span id="cm-extra-metrics" style="display:contents">` +
      mk(cPct(s.ret_ytd), 'YTD%', pCls(s.ret_ytd)) +
      mk(fmtPx(s.high_52w), '52W High', 'text2') +
      mk(fmtPx(s.low_52w),  '52W Low',  'text2') +
      mk(fmtPx(s.ath),      'ATH',      'text2') +
      mk(s.ath_pct != null ? (s.ath_pct >= 0 ? '+' : '') + s.ath_pct.toFixed(2) + '%' : '—', '% จาก ATH', athPctCls(s.ath_pct)) +
    `</span>`,
    mk(_drFmtCap(s.mkt_cap), 'MKT CAP', 'text2'),
  ].join('');

  _cmStock = { ...s, symbol: s.sym, price_history: null, _isDR: true };
  _cmSyncPeerTearsheetButtons();
  _cmRenderHedgeInfo(s.yf || s.sym);   // ใช้ ticker US จริง (s.yf) เทียบกับ Dataroma ไม่ใช่รหัส DR ไทย
  _cmTf = '1y';
  _cmHistoryData = null;
  _cmVolumeData  = null;
  _cmLivePrice = null; _cmLivePriceSym = null;   // DR ใช้ s.live_price ที่ติดมากับข้อมูลแทน ไม่ fetch เพิ่ม
  _cmFinLoaded = null;
  const drStocksBtn = document.getElementById('cm-mode-stocks');
  // โชว์ปุ่ม "งบการเงิน" เฉพาะตัวที่มีข้อมูลจริง (เช็คจาก _finAnalyticsData ที่โหลดไว้แล้ว —
  // ครอบคลุมเฉพาะบริษัทจริง ไม่รวม ETF/กองทุนที่ไม่มีงบการเงินให้ดึงตั้งแต่ต้น) — ถ้า
  // _finAnalyticsData ยังโหลดไม่เสร็จตอนนี้ (เพิ่งเข้าเว็บ) ปุ่มจะโผล่เองตอน loadFinAnalytics()
  // เสร็จผ่าน _refreshCmFinButton() ไม่ต้องปิดเปิด modal ใหม่
  _refreshCmFinButton();
  if (drStocksBtn) drStocksBtn.style.display = 'none';
  const drFullFinBtn = document.getElementById('cm-fullfin-link');
  if (drFullFinBtn) drFullFinBtn.style.display = '';   // restore if hidden by index modal
  const drFsLink = document.getElementById('cm-factsheet-link');
  if (drFsLink) drFsLink.style.display = 'none';
  const drSetLink = document.getElementById('cm-set-link');
  if (drSetLink) drSetLink.style.display = 'none';
  const drBpLink = document.getElementById('cm-bullpedia-link');
  if (drBpLink) drBpLink.style.display = 'none';
  const drIaaLink = document.getElementById('cm-iaa-link');
  if (drIaaLink) drIaaLink.style.display = 'none';
  // สถิติระยะยาว (cm-lts) — หุ้น DR ไม่มีใน set_prices.db (หุ้นไทยเท่านั้น) ใช้ yfinance
  // สดแทน (s.yf = ticker จริงที่ DR universe แม็บไว้แล้ว เช่น 0700.HK, NVDA)
  _loadPriceAnalytics(sym, 'cm-lts', () => _cmStock?.symbol === sym, s.yf);
  _renderDRDescription(sym);
  setCmMode('chart');
  document.querySelectorAll('#chart-modal .filter-btn').forEach(b => b.classList.remove('active'));
  const tfBtn = document.getElementById('cm-tf-1y');
  if (tfBtn) tfBtn.classList.add('active');
  document.getElementById('chart-modal').classList.add('open');
  document.body.style.overflow = 'hidden';

  // ใช้ close100 เป็น initial preview แล้วโหลด full history ใน background
  const c100 = s.close100 || [];
  if (c100.length) {
    const today = new Date();
    const initHistory = c100.map((price, i) => {
      const d = new Date(today);
      d.setDate(d.getDate() - (c100.length - 1 - i));
      return [d.toISOString().slice(0, 10), price];
    });
    requestAnimationFrame(() => _drawChart(_cmStock, initHistory));
  }
  // โหลด full 5Y history จาก yfinance
  _fetchDRFullHistory(sym);
}

async function _fetchDRFullHistory(sym) {
  if (IS_STATIC) { _cmStaticLimitNote(); return; }   // เว็บ static ไม่มี endpoint นี้ — ใช้ preview close100 ที่วาดไว้แล้ว
  try {
    const r = await _fetchTimeout(`/api/dr-history/${encodeURIComponent(sym)}`, 25000);
    const d = await r.json();
    if (d.error || !d.dates) { _drHistoryFailNote(); return; }
    const hist = d.dates.map((date, i) => [date, d.closes[i]]);
    _cmHistoryData = hist;
    if (_cmStock?.symbol === sym) _drawChart(_cmStock, hist);
  } catch(e) { console.error('DR history fetch error:', e); _drHistoryFailNote(); }
}

// preview เดิมที่วาดจาก close100 ใน openDRChartModal ใช้วันที่ประดิษฐ์ขึ้น (นับถอยหลัง
// ทีละ 1 วันปฏิทินจากวันนี้ รวมวันหยุดสุดสัปดาห์ด้วย ไม่ใช่วันเทรดจริง) ตั้งใจให้เป็นแค่
// placeholder ชั่วคราวจนกว่า _fetchDRFullHistory จะโหลดวันที่จริงมาทับ — ถ้า fetch พลาด
// (error/timeout/response ไม่มี dates) preview ปลอมนี้จะค้างอยู่ถาวรโดยผู้ใช้ไม่รู้ตัวว่า
// วันที่ในกราฟ/tooltip คลาดเคลื่อน จึงต้องแจ้งเตือนให้เห็นชัดแทนการเงียบ
function _drHistoryFailNote() {
  const sub = document.getElementById('cm-sub');
  if (sub && !sub.textContent.includes('⚠')) {
    sub.textContent += ' · ⚠ โหลดวันที่จริงไม่สำเร็จ วันที่ในกราฟเป็นค่าประมาณ';
  }
}

// ============================================================
// US INDEX STOCKS — chart modal (S&P500/Dow/NDX, ข้อมูลจาก us_index_metrics.json)
// ใช้โมดัลเดียวกับหุ้นไทย/DR แค่ปิด tab/ลิงก์ที่เป็นของไทยล้วน (factsheet/งบ SET/
// insider-short-nvdr) — price_history/vol_history ติดมากับ metrics อยู่แล้ว (~2 ปี)
// วาดได้ทันทีไม่ต้องรอ fetch, ส่วน 5Y/Max ค่อยดึงเพิ่มจาก us_prices.db เบื้องหลัง
// ============================================================
function openUsChartModal(symbol, rowOverride) {
  // rowOverride: ใช้ตอนเรียกจากหน้า Heatmap US ที่มี row (พร้อม price_history) อยู่แล้ว
  // ใน _hmData — ไม่ต้องรอ _usData โหลด (หน้า "หุ้น US" อาจยังไม่เคยถูกเปิดเลย)
  const s = rowOverride || (_usData?.stocks || []).find(x => x.symbol === symbol);
  if (!s || !s.price_history || s.price_history.length < 5) {
    alert(`ไม่มีข้อมูลราคาสำหรับ ${symbol} — ลองกด US Index Max`);
    return;
  }

  const titleEl = document.getElementById('cm-title');
  titleEl.textContent = `${s.symbol}  ${s.name || ''}`;
  titleEl.title = titleEl.textContent;
  const idxTags = ['in_sp500', 'in_dow', 'in_ndx']
    .filter(k => s[k]).map(k => ({ in_sp500: 'S&P500', in_dow: 'Dow', in_ndx: 'NDX' }[k])).join(' · ');
  document.getElementById('cm-sub').textContent = `${s.sector || '—'} · RS ${s.rs_score ?? '—'} · ${idxTags}`;
  document.getElementById('cm-tv-link').href = `https://www.tradingview.com/chart/?symbol=${encodeURIComponent(_usTvSymbol(s.symbol))}&interval=D`;
  const jittaLinkUsIdx = document.getElementById('cm-jitta-link');
  jittaLinkUsIdx.style.display = 'inline-flex';
  jittaLinkUsIdx.onclick = ev => openJittaFromYf(s.symbol, ev);
  const fsLink = document.getElementById('cm-factsheet-link');
  if (fsLink) fsLink.style.display = 'none';
  const setLink = document.getElementById('cm-set-link');
  if (setLink) setLink.style.display = 'none';
  const bpLinkUsIdx = document.getElementById('cm-bullpedia-link');
  if (bpLinkUsIdx) bpLinkUsIdx.style.display = 'none';
  const iaaLinkUsIdx = document.getElementById('cm-iaa-link');
  if (iaaLinkUsIdx) iaaLinkUsIdx.style.display = 'none';

  const mk = (val, lbl, cls = '') =>
    `<div><div class="cm-metric-val ${cls}">${val}</div><div class="cm-metric-lbl">${lbl}</div></div>`;
  document.getElementById('cm-metrics').innerHTML = [
    `<div><div class="cm-metric-val">${s.price?.toFixed(2) ?? '—'}</div><div class="cm-metric-lbl">ราคา</div></div>`,
    mk(pct(s.ret_1d), '1D%'),
    mk(pct(s.ret_1w), '1W%'),
    mk(pct(s.ret_1m), '1M%'),
    mk(pct(s.ret_3m), '3M%'),
    `<span id="cm-extra-metrics" style="display:contents">` +
      mk(pct(s.ret_ytd), 'YTD%') +
      mk(s.high_52w?.toFixed(2) ?? '—', '52W High', 'text2') +
      mk(s.low_52w?.toFixed(2)  ?? '—', '52W Low',  'text2') +
      (s.ath != null ? mk(s.ath.toFixed(2), 'ATH', 'text2') : '') +
      (s.ath_pct != null ? mk((s.ath_pct > 0 ? '+' : '') + s.ath_pct.toFixed(2) + '%', '% จาก ATH', s.ath_pct >= -5 ? 'green' : s.ath_pct >= -20 ? 'yellow' : 'red') : '') +
    `</span>`,
    mk(stageBadge(s.stage), 'Stage'),
    // us/hk/jp_index_metrics.json ไม่เก็บ mkt_cap เลย (ดู comment เดียวกันใน /api/tearsheet,
    // /api/factor-screener) — ซ่อน tile นี้แทนโชว์ "—" ค้างทุกตัว (แบบเดียวกับ ATH ด้านบน)
    ...(s.mkt_cap != null ? [mk(_drFmtCap(s.mkt_cap), 'MKT CAP', 'text2')] : []),
  ].join('');

  _cmStock = { ...s, price_history: s.price_history, _isDR: false, _isUSIdx: true };
  _cmSyncPeerTearsheetButtons();
  _cmRenderHedgeInfo(s.symbol);
  _cmTf = '1y';
  // เว้น _cmHistoryData ไว้ null (ต่างจาก price_history ที่วาด preview ทันที) —
  // ให้แท็บ 5Y/Max ยังทำงาน (setCmTf เช็ค !_cmHistoryData ก่อนไปดึงประวัติเต็มจาก
  // us_prices.db) ถ้าตั้งไว้ล่วงหน้าจะเข้าใจผิดว่ามีข้อมูลครบแล้วไม่ไปดึงเพิ่ม
  _cmHistoryData = null;
  _cmVolumeData  = s.vol_history || null;
  _cmLivePrice = null; _cmLivePriceSym = null;
  _cmFinLoaded = null;
  const finBtn    = document.getElementById('cm-mode-fin');
  const stocksBtn = document.getElementById('cm-mode-stocks');
  // งบการเงินอ่านจาก namespace mirror US (is_dr=1&market=US — ดู _loadCmFin) ชุดเดียว
  // กับหน้างบการเงินเต็ม — financials.db เป็น local-only เลยเปิดเฉพาะเวอร์ชันบนเครื่อง
  if (finBtn)    finBtn.style.display    = IS_STATIC ? 'none' : '';
  if (stocksBtn) stocksBtn.style.display = 'none';
  const usFullFinBtn = document.getElementById('cm-fullfin-link');
  if (usFullFinBtn) usFullFinBtn.style.display = IS_STATIC ? 'none' : '';   // restore if hidden by index modal
  _renderDRDescription(symbol, 'US');
  setCmMode('chart');
  document.querySelectorAll('#chart-modal .filter-btn').forEach(b => b.classList.remove('active'));
  const tfBtn = document.getElementById('cm-tf-1y');
  if (tfBtn) tfBtn.classList.add('active');
  document.getElementById('chart-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
  requestAnimationFrame(() => _drawChart(_cmStock, _cmHistoryData));

  // สถิติระยะยาว จาก yfinance สด (ticker ตรงกับ symbol อยู่แล้ว ไม่ต้องแปลง)
  _loadPriceAnalytics(symbol, 'cm-lts', () => _cmStock?.symbol === symbol, symbol);
  const flowBox = document.getElementById('cm-flow-summary');
  if (flowBox) { flowBox.style.display = 'none'; flowBox.innerHTML = ''; }
  const insWrap = document.getElementById('popup-insider-section');
  if (insWrap) insWrap.style.display = 'none';
  const shortWrap = document.getElementById('popup-short-section');
  if (shortWrap) shortWrap.style.display = 'none';
  const nvdrWrap = document.getElementById('popup-nvdr-section');
  if (nvdrWrap) nvdrWrap.style.display = 'none';
}

// ============================================================
// HK INDEX STOCKS — chart modal (HSI/HSTECH/HSCEI, ข้อมูลจาก hk_index_metrics.json)
// ก็อปโครงจาก openUsChartModal ทั้งหมด ต่างแค่ flag _isHKIdx (ให้ setCmTf ไปดึง
