  const idxTags = ['in_hsi', 'in_hstech', 'in_hscei']
    .filter(k => s[k]).map(k => ({ in_hsi: 'HSI', in_hstech: 'HSTECH', in_hscei: 'HSCEI' }[k])).join(' · ');
  document.getElementById('cm-sub').textContent = `${s.sector || '—'} · RS ${s.rs_score ?? '—'} · ${idxTags}`;
