function startJPIndexSync(btnId = 'jp-idx-sync-btn') {
  _startJob('/api/jp-index-sync', btnId, '🔄 ดึงเฉพาะที่ขาด/เก่า (local)',
    null, () => {
      document.getElementById('jp-idx-diff-note').textContent = '';
      document.getElementById('jp-idx-diff-result').style.display = 'none';
      // jp_index_membership.json + financials.db เปลี่ยนแล้วบน server — โหลด mirror list
      // ใหม่ก่อน re-render (ตัวใหม่ที่เพิ่งดึงงบมาจะได้โผล่ในรายการ browse)
      fetch('/api/mirror-symbols').then(r => r.json()).then(d => { _finDrMirrorSyms = d || {}; _finMirRender(); }).catch(() => {});
      fetch('/api/mirror-names').then(r => r.json()).then(d => { _finMirNames = d || {}; _finMirRender(); }).catch(() => {});
    });
}

function startUSIndexSync(btnId = 'us-idx-sync-btn') {
  _startJob('/api/us-index-sync', btnId, '🔄 ดึงเฉพาะที่ขาด/เก่า (local)',
    { min_age_days: 7 }, () => {
      document.getElementById('us-idx-diff-note').textContent = '';
      document.getElementById('us-idx-diff-result').style.display = 'none';
      // ไฟล์ us_index_membership.json + financials.db เปลี่ยนแล้วบน server — โหลดใหม่ทั้งคู่
      // ก่อน re-render รายการ browse (เดิม _finDrMirrorSyms ไม่เปลี่ยน แต่โหลดซ้ำไว้กันพลาด
      // ถ้า mirror list ขยับจาก sync อื่นระหว่างนี้)
      _finIndexData = {};
      fetch('/api/us-index-membership').then(r => r.json()).then(d => { _finIndexData = d || {}; _finMirRender(); }).catch(() => { _finIndexData = null; });
      fetch('/api/mirror-symbols').then(r => r.json()).then(d => { _finDrMirrorSyms = d || {}; _finMirRender(); }).catch(() => {});
      fetch('/api/mirror-names').then(r => r.json()).then(d => { _finMirNames = d || {}; _finMirRender(); }).catch(() => {});
    });
}

// ============================================================
// US STOCKS — RS/Stage/52W/Momentum/EMA ของสมาชิกดัชนี S&P500/Dow/NDX
// อ่าน /api/us-index-metrics (คำนวณล่วงหน้าตอน Quick Update / US Index Max)
// ============================================================
let _usData = null;          // {updated_at,total,stocks:[...]}
let _usIndex = 'SP500';      // SP500 | DOW | NDX
let _usView = 'all';         // all | rs80 | stage2 | nearhigh | momentum | ema200
let _usSector = 'ALL';
let _usSort = { key: 'rs_score', dir: 1 };   // dir 1 = มาก→น้อย (ดู usSortBy)

const _US_IDX_FLAG = { SP500: 'in_sp500', DOW: 'in_dow', NDX: 'in_ndx' };

function _usPctOffHigh(s) {
  if (!s.price || !s.high_52w) return null;
  return (s.price - s.high_52w) / s.high_52w * 100;   // ≤ 0
}

function setUsIndex(idx, btn) {
  _usIndex = idx;
  document.querySelectorAll('#us-idx-sp500,#us-idx-dow,#us-idx-ndx').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _rebuildUsSectorFilter();
  if (_usMode === 'sectors') loadUsSectorRanks();
  else renderUsTable();
}

function setUsView(view, btn) {
  _usView = view;
  document.querySelectorAll('#us-view-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  // preset sort ให้เข้ากับมุมมอง
  if (view === 'nearhigh')      _usSort = { key: '_pct_off_high', dir: 1 };
  else if (view === 'momentum') _usSort = { key: 'rs_momentum', dir: 1 };
  else                          _usSort = { key: 'rs_score', dir: 1 };
  renderUsTable();
}

function usSortBy(key) {
  if (_usSort.key === key) {
    _usSort.dir *= -1;
  } else {
    // คอลัมน์ตัวเลข dir:1 = มาก→น้อยก่อน (ปกติ) แต่คอลัมน์ string (Symbol/Sector)
    // ใช้ localeCompare*(-1) เมื่อ dir=1 ทำให้กลายเป็น Z→A ตั้งแต่คลิกแรก — สลับ
    // dir เริ่มต้นเป็น -1 เฉพาะคอลัมน์ string ให้ได้ A→Z ตามที่คนคาดหวังตอนคลิกแรก
    const col = _US_COLS.find(c => c.key === key);
    _usSort = { key, dir: col && col.str ? -1 : 1 };
  }
  renderUsTable();
}

// ============================================================
// US % ABOVE EMA ย้อนหลัง — เหมือนกราฟ bc-ema ของหน้า EMA Breadth หุ้นไทย
// แต่ดึงจาก /api/us-breadth (us_prices.db) แทน — reuse _bcSetup/_bcAxes/_bcLine
// ============================================================
let _usBreadthData = null;
let _usBreadthRange = '1y';
let _usBreadthCacheByRange = {};
let _usBreadthLoading = false;

function setUsBreadthRange(range, btn) {
  if (_usBreadthRange === range) return;
  _usBreadthRange = range;
  document.querySelectorAll('#us-breadth-range-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadUsBreadthChart();
}

async function loadUsBreadthChart() {
  const rng = _usBreadthRange;
  const cached = _usBreadthCacheByRange[rng];
  if (cached) { _usBreadthData = cached; drawUsBreadthChart(); return; }
  if (_usBreadthLoading) return;
  _usBreadthLoading = true;
  ['us-bc-ema', 'us-bc-nhnl', 'us-bc-mcc'].forEach(id => {
    const loading = document.getElementById(id + '-loading');
    const canvas  = document.getElementById(id);
    if (loading) { loading.style.display = 'block'; loading.textContent = 'กำลังโหลด...'; }
    if (canvas)  canvas.style.display = 'none';
  });
  try {
    // range 'all'/'5y' ต้อง full-scan us_prices.db (breadth.py ~35s) — 30s ไม่พอตอน cache เย็น
    // ทำให้คลิกแรกขึ้น 'หมดเวลา' ทุกครั้ง (server คำนวณเสร็จ+cache ไว้ กดซ้ำถึงติด) — ให้เวลามากขึ้น
    const to = rng === 'all' ? 90000 : rng === '5y' ? 60000 : 30000;
    const r = await _fetchTimeout('/api/us-breadth?range=' + encodeURIComponent(rng), to,
      `หมดเวลารอ Market Breadth หุ้น US (เกิน ${to / 1000} วิ) — ลองใหม่อีกครั้ง`);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    _usBreadthCacheByRange[rng] = d;
    if (rng === _usBreadthRange) {
      _usBreadthData = d;
      drawUsBreadthChart();
    }
  } catch (e) {
    ['us-bc-ema', 'us-bc-nhnl', 'us-bc-mcc'].forEach(id => {
      const el = document.getElementById(id + '-loading');
      if (el) el.textContent = 'โหลดไม่สำเร็จ: ' + e.message;
    });
  } finally {
    _usBreadthLoading = false;
    if (_usBreadthRange !== rng && !_usBreadthCacheByRange[_usBreadthRange]) loadUsBreadthChart();
  }
}

// Breadth chart (EMA50/200 breadth, NH-NL, McClellan) — เดิม US/HK มีฟังก์ชันแยกกัน
// (drawUsBreadthChart/drawHkBreadthChart) เหมือนกันทุกบรรทัดยกเว้น id prefix รวมเป็น
// ฟังก์ชันเดียวรับ prefix ('us'/'hk') — ตัวเรียกเดิม (drawUsBreadthChart()) ยังใช้ได้
// เหมือนเดิมทุกจุด ไม่ต้องแก้ call site
function drawIndexBreadthChart(prefix, d) {
  if (!d) return;
  const n = d.dates.length;

  let c = _bcSetup(`${prefix}-bc-ema`);
  if (c) {
    const toY = _bcAxes(c, 0, 100, d.dates, [20, 50, 80]);
    _bcLine(c, d.pct_above_ema50,  toY, '#e3b341');
    _bcLine(c, d.pct_above_ema200, toY, '#3fb950');
    document.getElementById(`${prefix}-bc-ema-now`).innerHTML =
      ` — <span style="color:#e3b341">EMA50: ${d.pct_above_ema50[n-1]}%</span> · ` +
      `<span style="color:#3fb950">EMA200: ${d.pct_above_ema200[n-1]}%</span>`;
  }

  c = _bcSetup(`${prefix}-bc-nhnl`);
  if (c) {
    const net = d.nh.map((h, i) => h - d.nl[i]);
    const m = Math.max(...net.map(Math.abs), 5);
    const toY = _bcAxes(c, -m, m, d.dates, [0]);
    _bcBars(c, net, toY, 0);
    const r = d.nhnl_ratio[n-1];
    document.getElementById(`${prefix}-bc-nhnl-now`).textContent =
      ` — NH ${d.nh[n-1]} / NL ${d.nl[n-1]}` + (r != null ? ` (ratio ${r})` : '');
  }

  c = _bcSetup(`${prefix}-bc-mcc`);
  if (c) {
    const osc = d.mcclellan_osc;
    const m = Math.max(...osc.filter(v => v != null).map(Math.abs), 50);
    const toY = _bcAxes(c, -m, m, d.dates, [-70, 0, 70]);
    _bcBars(c, osc, toY, 0);
    const cur = osc[n-1], sum = d.mcclellan_sum[n-1];
    document.getElementById(`${prefix}-bc-mcc-now`).innerHTML =
      ` — <span style="color:${cur >= 0 ? '#3fb950' : '#f85149'}">${cur}</span>` +
      ` · summation ${sum >= 0 ? '+' : ''}${sum}`;
  }
}

function drawUsBreadthChart() {
  drawIndexBreadthChart('us', _usBreadthData);
}

// ============================================================
// US/HK/JP ROTATION — RRG ของหุ้นรายตัวเทียบค่าเฉลี่ยดัชนี/sector ที่เลือก
// เดิมเป็น 3 ชุดก็อปวางเหมือนกัน 100% (ต่างแค่ prefix/endpoint/index-flag) —
// รวมเป็นเอนจินเดียว (_rotXxx) พารามิเตอร์ด้วย _ROT_CFG ต่อตลาด ส่วนชื่อฟังก์ชันเดิม
// (setUsRotTf, renderHkRotation, ...) เก็บไว้เป็น wrapper บาง ๆ เพราะ HTML onclick เรียกตรง ๆ
// ============================================================
let _usRotIndex = 'SP500', _usRotTf = 'long', _usRotBenchmark = 'index';   // SP500|DOW|NDX|ALL, long|short, index|sector
let _hkRotIndex = 'HSI', _hkRotTf = 'long', _hkRotBenchmark = 'index';     // HSI|HSTECH|HSCEI|ALL
let _jpRotTf = 'long', _jpRotBenchmark = 'index';                          // ไม่มีสลับดัชนี (Nikkei 225 ทั้งหมด)

const _ROT_CFG = {
  us: {
    prefix: 'usrot', endpoint: '/api/us-index-metrics', marketName: 'US',
    canvasId: 'us-rotation-map', legendId: 'us-rot-legend', onOpen: (sym) => openUsChartModal(sym),
    idxFlag: () => _US_IDX_FLAG,
    getData: () => _usData, setData: v => { _usData = v; },
    getIndex: () => _usRotIndex, setIndex: v => { _usRotIndex = v; },
    getTf: () => _usRotTf, setTf: v => { _usRotTf = v; },
    getBenchmark: () => _usRotBenchmark, setBenchmark: v => { _usRotBenchmark = v; },
  },
  hk: {
    prefix: 'hkrot', endpoint: '/api/hk-index-metrics', marketName: 'HK',
    canvasId: 'hk-rotation-map', legendId: 'hk-rot-legend', onOpen: (sym) => openHkChartModal(sym),
    idxFlag: () => _HK_IDX_FLAG,
    getData: () => _hkData, setData: v => { _hkData = v; },
    getIndex: () => _hkRotIndex, setIndex: v => { _hkRotIndex = v; },
    getTf: () => _hkRotTf, setTf: v => { _hkRotTf = v; },
    getBenchmark: () => _hkRotBenchmark, setBenchmark: v => { _hkRotBenchmark = v; },
  },
  jp: {
    prefix: 'jprot', endpoint: '/api/jp-index-metrics', marketName: 'JP',
    canvasId: 'jp-rotation-map', legendId: 'jp-rot-legend', onOpen: (sym) => openJpChartModal(sym),
    idxFlag: null,   // JP ไม่มีสลับดัชนี
    getData: () => _jpData, setData: v => { _jpData = v; },
    getIndex: () => null, setIndex: () => {},
    getTf: () => _jpRotTf, setTf: v => { _jpRotTf = v; },
    getBenchmark: () => _jpRotBenchmark, setBenchmark: v => { _jpRotBenchmark = v; },
  },
};

function _rotSetBenchmark(mkt, mode, btn) {
  _ROT_CFG[mkt].setBenchmark(mode);
  btn?.closest('.filter-row')?.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _rotRender(mkt);
}

function _rotSetIndex(mkt, idx, btn) {
  _ROT_CFG[mkt].setIndex(idx);
  btn?.closest('.filter-row')?.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _rotRebuildSectorFilter(mkt);
  _rotRender(mkt);
}

function _rotSetTf(mkt, tf, btn) {
  const c = _ROT_CFG[mkt];
  c.setTf(tf);
  btn?.closest('.filter-row')?.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const sub = document.getElementById(`${c.prefix}-subtitle`);
  if (sub) sub.innerHTML = `RRG ของหุ้น ${c.marketName} แต่ละตัว — เทียบกับ <b>ค่าเฉลี่ยของกลุ่มที่เลือก</b> · ` +
    (tf === 'short' ? 'แกน X = 1M% Y = 1W% (เทียบกลุ่ม)' : 'แกน X = 3M% Y = 1M% (เทียบกลุ่ม)');
  _rotRender(mkt);
}

async function _rotLoad(mkt) {
  const c = _ROT_CFG[mkt];
  const gate = document.getElementById(`${c.prefix}-gate`), body = document.getElementById(`${c.prefix}-body`);
  if (!c.getData()) {
    _rotGateState(gate, body, 'loading', `กำลังดึงข้อมูลหุ้น ${c.marketName}...`);
    try {
      // endpoint อ่าน cache local จึงเร็ว แต่ถ้า server ค้าง fetch เปล่าจะแขวน gate
      // "กำลังดึงข้อมูล..." ตลอดกาล — ห่อ timeout ให้หลุดมาเห็น error เสมอ
      const d = await _rotFetchJson(c.endpoint, 30000,
        `หมดเวลารอข้อมูลหุ้น ${c.marketName} (เกิน 30 วิ) — ลองใหม่อีกครั้ง`);
      c.setData(d);
    } catch (e) {
      _rotGateState(gate, body, 'error', `โหลดข้อมูลหุ้น ${c.marketName} ไม่สำเร็จ: ` + e.message);
      return;
    }
  }
  const data = c.getData();
  if (!data || !data.stocks || !data.stocks.length) {
    _rotGateState(gate, body, 'error', `ยังไม่มีข้อมูล — กดปุ่ม 📈 ${c.marketName} Index Max หรือ ⚡ Quick Update ก่อน`);
    return;
  }
  _rotGateState(gate, body, 'ready');
  _rotRebuildSectorFilter(mkt);
  _rotRender(mkt);
}

function _rotRebuildSectorFilter(mkt) {
  const c = _ROT_CFG[mkt];
  const data = c.getData();
  if (!data || !data.stocks) return;
  const stocks = data.stocks.filter(s => s && typeof s === 'object');   // กัน entry null จาก JSON เพี้ยน
  const flag = c.idxFlag ? c.idxFlag()[c.getIndex()] : null;
  const inIdx = flag ? stocks.filter(s => s[flag]) : stocks;
  const sectors = ['ALL', ...[...new Set(inIdx.map(s => s.sector || 'Unknown'))].sort()];
  const sel = document.getElementById(`${c.prefix}-sector`);
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = sectors.map(s => `<option value="${s}">${s === 'ALL' ? 'ทุก Sector' : s}</option>`).join('');
  sel.value = sectors.includes(cur) ? cur : 'ALL';
}

function _rotRender(mkt) {
  const c = _ROT_CFG[mkt];
  const data = c.getData();
  if (!data || !data.stocks) return;
  const stocks = data.stocks.filter(s => s && typeof s === 'object');   // กัน entry null จาก JSON เพี้ยน
  const flag = c.idxFlag ? c.idxFlag()[c.getIndex()] : null;
  const universe = flag ? stocks.filter(s => s[flag]) : stocks;
  const isShort = c.getTf() === 'short';
  const valid = universe.filter(s => isShort
    ? (s.ret_1m != null && s.ret_1w != null)
    : (s.ret_3m != null && s.ret_1m != null));
  if (!valid.length) {
    _rotRenderEmpty(c.canvasId, c.legendId, `${c.prefix}-info`,
      'ไม่มีหุ้นที่มีผลตอบแทนครบตามกรอบเวลาที่เลือก');
    return;
  }
  const sector = document.getElementById(`${c.prefix}-sector`)?.value || 'ALL';
  const shown = sector === 'ALL' ? valid : valid.filter(s => (s.sector || 'Unknown') === sector);
  // ปุ่ม "เทียบ Sector" ไม่มีผลตอนยังเลือก "ทุก Sector" (bmSet ถอยไปใช้ทั้งดัชนีเงียบๆ)
  // — disable พร้อม hint กันปุ่มติด active แต่พฤติกรรมไม่เปลี่ยนแล้วคนงง
  const bmBtn = document.getElementById(`${c.prefix}-bm-sector`);
  if (bmBtn) {
    bmBtn.disabled = sector === 'ALL';
    bmBtn.title = sector === 'ALL' ? 'เลือก Sector เจาะจงก่อน จึงเทียบค่าเฉลี่ย sector ได้' : '';
  }
  // benchmark = ค่าเฉลี่ยทั้งดัชนี (ปกติ) หรือค่าเฉลี่ยเฉพาะ sector ที่เลือก (ถ้าสลับโหมด
  // และเลือก sector เจาะจงแล้ว) — ใช้ดูว่าใครแรง/อ่อนกว่า "เพื่อนร่วม sector" แทนทั้งตลาด
  const bmSector = c.getBenchmark() === 'sector' && sector !== 'ALL';
  const bmSet = bmSector ? shown : valid;
  const R = _rotRelative(bmSet);
  const items = shown.map(s => ({
    name: s.symbol, sector: s.sector,
    ...R.apply(s),
    avg_rs: s.rs_score,
  }));
  const info = document.getElementById(`${c.prefix}-info`);
  // เดิมเช็ค bmSet === shown (reference equality) แทนเช็ค bmSector ตรงๆ — ตอน sector==='ALL'
  // (ค่า default ทุกครั้งที่เปิดแท็บ) shown และ bmSet ต่างก็ชี้ไปที่ array เดียวกัน (valid)
  // ทำให้ bmSet === shown เป็น true โดยบังเอิญจาก object aliasing ไม่ใช่จาก logic จริง —
  // label เลยกลายเป็น 'เฉลี่ย sector "ALL"' ทั้งที่ยังไม่ได้เทียบ sector เลย
  const bmLabel = bmSector ? `เฉลี่ย sector "${sector}"` : 'เฉลี่ยทั้งดัชนี';
  if (info) info.textContent = `${shown.length} หุ้น · benchmark = ${bmLabel} (${bmSet.length} ตัว)` +
    _rotInfoSuffix(isShort, R);
  drawRotationScatter(items, { canvasId: c.canvasId, legendId: c.legendId, tf: c.getTf(), onOpen: c.onOpen, relative: true, relativeLabel: bmLabel });
}

function setUsRotBenchmark(mode, btn) { _rotSetBenchmark('us', mode, btn); }
function setHkRotBenchmark(mode, btn) { _rotSetBenchmark('hk', mode, btn); }
function setJpRotBenchmark(mode, btn) { _rotSetBenchmark('jp', mode, btn); }

function setUsRotIndex(idx, btn) { _rotSetIndex('us', idx, btn); }
function setHkRotIndex(idx, btn) { _rotSetIndex('hk', idx, btn); }

function setUsRotTf(tf, btn) { _rotSetTf('us', tf, btn); }
function setHkRotTf(tf, btn) { _rotSetTf('hk', tf, btn); }
function setJpRotTf(tf, btn) { _rotSetTf('jp', tf, btn); }

async function loadUsRotation() { return _rotLoad('us'); }
async function loadHkRotation() { return _rotLoad('hk'); }
async function loadJpRotation() { return _rotLoad('jp'); }

function _rebuildUsRotSectorFilter() { _rotRebuildSectorFilter('us'); }
function _rebuildHkRotSectorFilter() { _rotRebuildSectorFilter('hk'); }
function _rebuildJpRotSectorFilter() { _rotRebuildSectorFilter('jp'); }

function renderUsRotation() { _rotRender('us'); }
function renderHkRotation() { _rotRender('hk'); }
function renderJpRotation() { _rotRender('jp'); }

// รวม page-dr-rotation/page-us-rotation/page-hk-rotation/page-jp-rotation เป็นหน้าเดียว
// (page-stock-rotation) พร้อมแท็บเลือกตลาด — TH(DR) เป็น special-case เรียก loadDRRotation()
// เดิมตรงๆ (ไม่ผ่าน _rotLoad/_ROT_CFG เพราะโครงสร้าง data/UI ต่างจาก US/HK/JP มาก)
let _srMarket = 'TH';
function setSrMarket(mkt, btn) {
  _srMarket = mkt;
  document.querySelectorAll('#sr-tab-th,#sr-tab-us,#sr-tab-hk,#sr-tab-jp,#sr-tab-etf').forEach(b => b.classList.remove('active'));
  (btn || document.getElementById('sr-tab-' + mkt.toLowerCase()))?.classList.add('active');
  document.getElementById('sr-mkt-th').style.display = mkt === 'TH' ? '' : 'none';
  document.getElementById('sr-mkt-us').style.display = mkt === 'US' ? '' : 'none';
  document.getElementById('sr-mkt-hk').style.display = mkt === 'HK' ? '' : 'none';
  document.getElementById('sr-mkt-jp').style.display = mkt === 'JP' ? '' : 'none';
  document.getElementById('sr-mkt-etf').style.display = mkt === 'ETF' ? '' : 'none';
  if (mkt === 'TH') loadDRRotation();
  if (mkt === 'US') loadUsRotation();
  if (mkt === 'HK') loadHkRotation();
  if (mkt === 'JP') loadJpRotation();
  if (mkt === 'ETF') loadEtfRotation();
}

let _usStocksLoading = false;

function loadUsStocksPage() {
  if (_usData) {
    // _usData อาจถูกเซ็ตนอก path นี้ (preload ของ Watchlist / deep-link #stock/us/..) ซึ่งข้าม
    // _rebuildUsSectorFilter ทำให้ dropdown Sector ค้างเหลือแค่ "ALL" จนกว่าจะกดปุ่มสลับดัชนี
    if ((document.getElementById('us-sector-filter')?.options.length || 0) <= 1) _rebuildUsSectorFilter();
    renderUsTable(); loadUsBreadthChart(); return;
  }
  if (_usStocksLoading) return;   // กัน fetch ซ้ำตอนสลับเข้า-ออกหน้าระหว่างรอ (เหมือน loadHkStocksPage/loadJpStocksPage)
  const tbody = document.getElementById('us-stocks-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _usStocksLoading = true;
  _fetchTimeout('/api/us-index-metrics', 30000, 'หมดเวลารอข้อมูลหุ้น US (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      if (!d.stocks || !d.stocks.length) {
        // อย่า cache ก้อนว่าง — ไม่งั้น _usData ค้าง [] แล้วปุ่ม US Index Max/Quick Update
        // ที่บอกให้กดจะไม่มีทาง re-fetch จนกว่าจะ F5 (เหมือน loadHkStocksPage)
        if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">ยังไม่มีข้อมูล — กดปุ่ม <b>📈 US Index Max</b> หรือ <b>⚡ Quick Update</b> เพื่อดึงราคาและคำนวณ metrics</td></tr>`;
        return;
      }
      // กัน null entry ใน us_index_metrics.json (JSON เพี้ยน) ทำให้ s[flag]/s.symbol throw
      // ทั้งหน้า — hardening แบบเดียวกับ loadHkStocksPage
      if (Array.isArray(d.stocks)) d.stocks = d.stocks.filter(s => s && typeof s === 'object');
      _usData = d;
      _rebuildUsSectorFilter();
      renderUsTable();
      loadUsBreadthChart();
    })
    .catch(e => {
      if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    })
    .finally(() => { _usStocksLoading = false; });
}

function _rebuildUsSectorFilter() {
  if (!_usData) return;
  const flag = _US_IDX_FLAG[_usIndex];
  const inIdx = _usData.stocks.filter(s => s[flag]);
  const sectors = ['ALL', ...[...new Set(inIdx.map(s => s.sector || 'Unknown'))].sort()];
  const sel = document.getElementById('us-sector-filter');
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = sectors.map(s => `<option value="${_escHtml(s)}">${s === 'ALL' ? 'ทุก Sector' : _escHtml(s)}</option>`).join('');
  sel.value = sectors.includes(cur) ? cur : 'ALL';
  _usSector = sel.value;
}

function _usFilteredStocks() {
  if (!_usData) return [];
  const flag = _US_IDX_FLAG[_usIndex];
  let rows = _usData.stocks.filter(s => s[flag]);
  // precompute derived fields
  rows = rows.map(s => ({ ...s, _pct_off_high: _usPctOffHigh(s) }));
  const sel = document.getElementById('us-sector-filter');
  _usSector = sel ? sel.value : 'ALL';
  if (_usSector !== 'ALL') rows = rows.filter(s => (s.sector || 'Unknown') === _usSector);
  const q = (document.getElementById('us-search')?.value || '').trim().toLowerCase();
  if (q) rows = rows.filter(s => s.symbol.toLowerCase().includes(q) || (s.name || '').toLowerCase().includes(q));
  // view filter
  if (_usView === 'rs80')     rows = rows.filter(s => (s.rs_score ?? -1) >= 80);
  else if (_usView === 'stage2')   rows = rows.filter(s => s.stage === 2);
  else if (_usView === 'nearhigh') rows = rows.filter(s => s._pct_off_high != null && s._pct_off_high >= -5);
  else if (_usView === 'momentum') rows = rows.filter(s => (s.rs_momentum ?? 0) > 0);
  else if (_usView === 'ema200')   rows = rows.filter(s => s.above_ema200 === true);
  return rows;
}

const _US_COLS = [
  { key: 'rs_score',      label: 'RS',        w: 46 },
  { key: 'symbol',        label: 'Symbol',    w: 90, str: true },
  { key: 'sector',        label: 'Sector',    w: 150, str: true },
  { key: 'price',         label: 'ราคา',       w: 70 },
  { key: 'ret_1d',        label: '1D',        w: 62 },
  { key: 'ret_1w',        label: '1W',        w: 62 },
  { key: 'ret_1m',        label: '1M',        w: 62 },
  { key: 'ret_3m',        label: '3M',        w: 62 },
  { key: 'ret_1y',        label: '1Y',        w: 66 },
  { key: 'rs_momentum',   label: 'RS Δ4w',    w: 62 },
  { key: '_pct_off_high', label: '% จาก High', w: 76 },
  { key: 'above_ema50',   label: 'EMA50',     w: 56 },
  { key: 'above_ema200',  label: 'EMA200',    w: 58 },
  { key: 'stage',         label: 'Stage',     w: 80 },
];

// TradingView ใช้ "." คั่น class share (BRK.B) ส่วน ticker ในไฟล์ local/us_prices.db
// เป็นรูปแบบ yfinance ("BRK-B") — ไม่แปลงก่อนจะเปิดหน้า TradingView ค้นหาไม่เจอ
function _usTvSymbol(sym) {
  return sym.replace(/-/g, '.');
}

function _usTvUrl(sym, interval) {
  return `https://www.tradingview.com/chart/?symbol=${encodeURIComponent(_usTvSymbol(sym))}${interval ? '&interval=' + interval : ''}`;
}

function _usTvLink(sym) {
  return `<a class="tv-link" href="${_usTvUrl(sym)}" target="_blank" title="เปิด TradingView">↗</a>`;
}

function renderUsTable() {
  if (!_usData) return;
  let rows = _usFilteredStocks();
  rows.sort((a, b) => {
    const av = a[_usSort.key], bv = b[_usSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    if (typeof av === 'string') return av.localeCompare(bv) * (_usSort.dir === 1 ? -1 : 1);
    return (bv - av) * _usSort.dir;
  });

  // header
  const thead = document.getElementById('us-thead');
  if (thead) thead.innerHTML = _US_COLS.map(c => {
    const arrow = _usSort.key === c.key ? (_usSort.dir === 1 ? ' ▾' : ' ▴') : '';
    const align = c.str ? 'left' : 'right';
    return `<th style="width:${c.w}px;text-align:${align};cursor:pointer;white-space:nowrap" onclick="usSortBy('${c.key}')">${c.label}${arrow}</th>`;
  }).join('');

  const body = rows.map(s => {
    const offHigh = s._pct_off_high;
    const offCls = offHigh == null ? 'text2' : offHigh >= -3 ? 'green' : offHigh >= -10 ? 'yellow' : 'text2';
    return `<tr>
      <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '-'}</span></td>
      <td><strong class="sym-link" onclick="openUsChartModal('${s.symbol}')">${s.symbol}</strong>${_usTvLink(s.symbol)}</td>
      <td style="font-size:11px;color:var(--text2)">${s.sector ? _escHtml(s.sector) : '—'}</td>
      <td class="r">${s.price != null ? s.price.toFixed(2) : '—'}</td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.rs_momentum != null ? `<span class="${s.rs_momentum > 0 ? 'green' : s.rs_momentum < 0 ? 'red' : 'text2'}">${s.rs_momentum > 0 ? '+' : ''}${s.rs_momentum}</span>` : '<span class="text2">—</span>'}</td>
      <td class="r"><span class="${offCls}" style="font-size:11px">${offHigh != null ? offHigh.toFixed(1) + '%' : '—'}</span></td>
      <td class="r">${emaBadge(s.above_ema50)}</td>
      <td class="r">${emaBadge(s.above_ema200)}</td>
      <td class="r">${stageBadge(s.stage)}</td>
    </tr>`;
  }).join('');
  const tbody = document.getElementById('us-stocks-tbody');
  if (tbody) tbody.innerHTML = body || `<tr><td colspan="14" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีหุ้นตรงเงื่อนไข</td></tr>`;

  // count + updated
  const total = _usData.stocks.filter(s => s[_US_IDX_FLAG[_usIndex]]).length;
  const upd = _usData.updated_at ? ` · อัพเดท ${_usData.updated_at}` : '';
  const cnt = document.getElementById('us-count');
  if (cnt) cnt.textContent = `แสดง ${rows.length}/${total} ตัว${upd}`;

  _renderUsBreadth();
}

// ── US Sector Ranking (mode toggle บนหน้า "หุ้น US") ──────────────────────
// อ่าน /api/us-sector-ranks?index=... ซึ่ง reuse core.metrics.summarize_groups()
// ตัวเดียวกับหน้า Sectors ของหุ้นไทย (cache แยกตาม index เพราะ endpoint กรองฝั่ง server)
let _usMode = 'stocks';
let _usSectorRanks = {};      // { SP500: [...], DOW: [...], NDX: [...] }
let _usSectorSort = { key: 'avg_rs', dir: 1 };

function setUsMode(mode) {
  _usMode = mode;
  const btn = document.getElementById('us-mode-sectors');
  if (btn) btn.classList.toggle('active', mode === 'sectors');
  document.getElementById('us-stocks-wrap').style.display  = mode === 'sectors' ? 'none' : '';
  document.getElementById('us-sectors-wrap').style.display = mode === 'sectors' ? '' : 'none';
  // กลับมาโหมด stocks ต้อง render ใหม่เสมอ — ไม่งั้นถ้าสลับดัชนี (setUsIndex) ระหว่างอยู่
  // โหมด sectors ตารางหุ้นจะยังค้างข้อมูลของดัชนีเก่าจนกว่าจะมี trigger อื่นมา render ซ้ำ
  if (mode === 'sectors') loadUsSectorRanks();
  else renderUsTable();
}

function usSectorSortBy(key) {
  if (_usSectorSort.key === key) _usSectorSort.dir *= -1;
  else _usSectorSort = { key, dir: 1 };
  renderUsSectorTable();
}

function loadUsSectorRanks() {
  if (_usSectorRanks[_usIndex]) { renderUsSectorTable(); return; }
  const idx = _usIndex;   // capture ตอนยิง fetch — กัน response เขียนผิดช่องถ้าผู้ใช้สลับ
                           // ดัชนี (setUsIndex) ระหว่างรอ response กลับมา
  const tbody = document.getElementById('us-sectors-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _fetchTimeout(`/api/us-sector-ranks?index=${idx}`, 30000, 'หมดเวลารอ Sector Ranking หุ้น US (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      const sectors = d.sectors || [];
      // อย่า cache ก้อนว่าง — ดูเหตุผลใน loadHkSectorRanks
      if (sectors.length) _usSectorRanks[idx] = sectors;
      if (idx === _usIndex) renderUsSectorTable();
    })
    .catch(e => {
      if (idx === _usIndex && tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    });
}

function renderUsSectorTable() {
  const rows = [...(_usSectorRanks[_usIndex] || [])];
  rows.sort((a, b) => {
    const av = a[_usSectorSort.key], bv = b[_usSectorSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    return (bv - av) * _usSectorSort.dir;
  });
  const tbody = document.getElementById('us-sectors-tbody');
  if (!tbody) return;
  tbody.innerHTML = rows.map((s, i) => `
    <tr style="cursor:pointer" onclick="_openUsSector('${_escJsAttr(s.name)}')">
      <td class="text2">${i + 1}</td>
      <td><strong>${_escHtml(s.name)}</strong></td>
      <td class="r text2">${s.count}</td>
      <td class="r"><span class="${rsColor(s.avg_rs)}" style="font-weight:700">${s.avg_rs ?? '—'}</span></td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.pct_above_ema50 != null ? s.pct_above_ema50 + '%' : '—'}</td>
    </tr>`).join('') || `<tr><td colspan="10" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีข้อมูล</td></tr>`;
}

// คลิกแถว sector → กลับไปหน้าตารางหุ้น กรองเฉพาะ sector นั้น
function _openUsSector(name) {
  setUsMode('stocks');
  const sel = document.getElementById('us-sector-filter');
  if (sel) { sel.value = name; _usSector = name; }
  renderUsTable();
}

function _renderUsBreadth() {
  const flag = _US_IDX_FLAG[_usIndex];
  const all = _usData.stocks.filter(s => s[flag]);
  const n = all.length || 1;
  const p200 = all.filter(s => s.above_ema200).length / n * 100;
  const p50  = all.filter(s => s.above_ema50).length / n * 100;
  const rs80 = all.filter(s => (s.rs_score ?? 0) >= 80).length;
  const nearHigh = all.filter(s => { const o = _usPctOffHigh(s); return o != null && o >= -3; }).length;
  const s2 = all.filter(s => s.stage === 2).length;
  const tile = (label, val, sub, color) =>
    `<div class="card" style="padding:12px 14px">
      <div style="font-size:11px;color:var(--text2)">${label}</div>
      <div style="font-size:22px;font-weight:700;color:${color || 'var(--text)'}">${val}</div>
      <div style="font-size:10px;color:var(--text2)">${sub}</div>
    </div>`;
  const emaColor = p200 >= 60 ? '#3fb950' : p200 < 40 ? '#f85149' : '#e3b341';
  const strip = document.getElementById('us-breadth-strip');
  if (strip) strip.innerHTML =
    tile('% เหนือ EMA200', p200.toFixed(0) + '%', `EMA50: ${p50.toFixed(0)}%`, emaColor) +
    tile('RS ≥ 80', rs80, `${(rs80 / n * 100).toFixed(0)}% ของดัชนี`, '#3fb950') +
    tile('Stage 2', s2, `${(s2 / n * 100).toFixed(0)}% กำลังขาขึ้น`, '#3fb950') +
    tile('ใกล้ 52W High', nearHigh, 'ห่าง high ≤ 3%', '#58a6ff');
}

// ============================================================
// HK INDEX STOCKS — RS/Stage/52W/Momentum/EMA ของสมาชิก HSI/HSTECH/HSCEI
// ก็อปโครงจาก US INDEX STOCKS ด้านบนทั้งหมด (ต่างแค่ prefix us->hk, endpoint,
// รายชื่อดัชนี, และ TradingView link ที่ต้องใช้ HKEX:รหัส แทน symbol ตรงๆ)
// ============================================================
let _hkData = null;          // {updated_at,total,stocks:[...]}
let _hkIndex = 'HSI';        // HSI | HSTECH | HSCEI
let _hkView = 'all';         // all | rs80 | stage2 | nearhigh | momentum | ema200
let _hkSector = 'ALL';
let _hkSort = { key: 'rs_score', dir: 1 };

const _HK_IDX_FLAG = { HSI: 'in_hsi', HSTECH: 'in_hstech', HSCEI: 'in_hscei' };

function _hkPctOffHigh(s) {
  if (!s.price || !s.high_52w) return null;
  return (s.price - s.high_52w) / s.high_52w * 100;
}

function setHkIndex(idx, btn) {
  _hkIndex = idx;
  document.querySelectorAll('#hk-idx-hsi,#hk-idx-hstech,#hk-idx-hscei').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _rebuildHkSectorFilter();
  if (_hkMode === 'sectors') loadHkSectorRanks();
  else renderHkTable();
}

function setHkView(view, btn) {
  _hkView = view;
  document.querySelectorAll('#hk-view-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (view === 'nearhigh')      _hkSort = { key: '_pct_off_high', dir: 1 };
  else if (view === 'momentum') _hkSort = { key: 'rs_momentum', dir: 1 };
  else                          _hkSort = { key: 'rs_score', dir: 1 };
  renderHkTable();
}

function hkSortBy(key) {
  if (_hkSort.key === key) {
    _hkSort.dir *= -1;
  } else {
    // เหตุผลเดียวกับ usSortBy — คอลัมน์ string เริ่ม dir:-1 ให้ได้ A→Z ตั้งแต่คลิกแรก
    const col = _HK_COLS.find(c => c.key === key);
    _hkSort = { key, dir: col && col.str ? -1 : 1 };
  }
  renderHkTable();
}

// ============================================================
// HK % ABOVE EMA ย้อนหลัง — ดึงจาก /api/hk-breadth — reuse _bcSetup/_bcAxes/_bcLine
// ============================================================
let _hkBreadthData = null;
let _hkBreadthRange = '1y';
let _hkBreadthCacheByRange = {};
let _hkBreadthLoading = false;

function setHkBreadthRange(range, btn) {
  if (_hkBreadthRange === range) return;
  _hkBreadthRange = range;
  document.querySelectorAll('#hk-breadth-range-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadHkBreadthChart();
}

async function loadHkBreadthChart() {
  const rng = _hkBreadthRange;
  const cached = _hkBreadthCacheByRange[rng];
  if (cached) { _hkBreadthData = cached; drawHkBreadthChart(); return; }
  if (_hkBreadthLoading) return;
  _hkBreadthLoading = true;
  ['hk-bc-ema', 'hk-bc-nhnl', 'hk-bc-mcc'].forEach(id => {
    const loading = document.getElementById(id + '-loading');
    const canvas  = document.getElementById(id);
    if (loading) { loading.style.display = 'block'; loading.textContent = 'กำลังโหลด...'; }
    if (canvas)  canvas.style.display = 'none';
  });
  try {
    const r = await _fetchTimeout('/api/hk-breadth?range=' + encodeURIComponent(rng), 30000,
      'หมดเวลารอ Market Breadth หุ้น HK (เกิน 30 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    _hkBreadthCacheByRange[rng] = d;
    if (rng === _hkBreadthRange) {
      _hkBreadthData = d;
      drawHkBreadthChart();
    }
  } catch (e) {
    ['hk-bc-ema', 'hk-bc-nhnl', 'hk-bc-mcc'].forEach(id => {
      const el = document.getElementById(id + '-loading');
      if (el) el.textContent = 'โหลดไม่สำเร็จ: ' + e.message;
    });
  } finally {
    _hkBreadthLoading = false;
    if (_hkBreadthRange !== rng && !_hkBreadthCacheByRange[_hkBreadthRange]) loadHkBreadthChart();
  }
}

function drawHkBreadthChart() {
  drawIndexBreadthChart('hk', _hkBreadthData);
}

let _hkStocksLoading = false;

function loadHkStocksPage() {
  if (_hkData) { renderHkTable(); loadHkBreadthChart(); return; }
  if (_hkStocksLoading) return;   // กัน fetch ซ้ำตอนสลับเข้า-ออกหน้าระหว่างรอ (เหมือน loadJpStocksPage)
  const tbody = document.getElementById('hk-stocks-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _hkStocksLoading = true;
  _fetchTimeout('/api/hk-index-metrics', 30000, 'หมดเวลารอข้อมูลหุ้น HK (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      if (!d.stocks || !d.stocks.length) {
        // อย่า cache ก้อนว่าง — ไม่งั้น _hkData ค้าง [] แล้วปุ่ม Quick Update/HK Index Max
        // ที่บอกให้กดจะไม่มีทาง re-fetch จนกว่าจะ F5
        if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">ยังไม่มีข้อมูล — กดปุ่ม <b>📈 HK Index Max</b> หรือ <b>⚡ Quick Update</b> เพื่อดึงราคาและคำนวณ metrics</td></tr>`;
        return;
      }
      // กัน null entry ใน hk_index_metrics.json (JSON เพี้ยน) ทำให้ s[flag]/s.symbol throw
      // ทั้งหน้า — hardening แบบเดียวกับ renderer ของ Stock Rotation (commit aeb9dda)
      if (Array.isArray(d.stocks)) d.stocks = d.stocks.filter(s => s && typeof s === 'object');
      _hkData = d;
      _rebuildHkSectorFilter();
      renderHkTable();
      loadHkBreadthChart();
    })
    .catch(e => {
      if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    })
    .finally(() => { _hkStocksLoading = false; });
}

function _rebuildHkSectorFilter() {
  if (!_hkData) return;
  const flag = _HK_IDX_FLAG[_hkIndex];
  const inIdx = _hkData.stocks.filter(s => s[flag]);
  const sectors = ['ALL', ...[...new Set(inIdx.map(s => s.sector || 'Unknown'))].sort()];
  const sel = document.getElementById('hk-sector-filter');
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = sectors.map(s => `<option value="${s}">${s === 'ALL' ? 'ทุก Sector' : s}</option>`).join('');
  sel.value = sectors.includes(cur) ? cur : 'ALL';
  _hkSector = sel.value;
}

function _hkFilteredStocks() {
  if (!_hkData) return [];
  const flag = _HK_IDX_FLAG[_hkIndex];
  let rows = _hkData.stocks.filter(s => s[flag]);
  rows = rows.map(s => ({ ...s, _pct_off_high: _hkPctOffHigh(s) }));
  const sel = document.getElementById('hk-sector-filter');
  _hkSector = sel ? sel.value : 'ALL';
  if (_hkSector !== 'ALL') rows = rows.filter(s => (s.sector || 'Unknown') === _hkSector);
  const q = (document.getElementById('hk-search')?.value || '').trim().toLowerCase();
  if (q) rows = rows.filter(s => s.symbol.toLowerCase().includes(q) || (s.name || '').toLowerCase().includes(q));
  if (_hkView === 'rs80')     rows = rows.filter(s => (s.rs_score ?? -1) >= 80);
  else if (_hkView === 'stage2')   rows = rows.filter(s => s.stage === 2);
  else if (_hkView === 'nearhigh') rows = rows.filter(s => s._pct_off_high != null && s._pct_off_high >= -5);
  else if (_hkView === 'momentum') rows = rows.filter(s => (s.rs_momentum ?? 0) > 0);
  else if (_hkView === 'ema200')   rows = rows.filter(s => s.above_ema200 === true);
  return rows;
}

const _HK_COLS = [
  { key: 'rs_score',      label: 'RS',        w: 46 },
  { key: 'symbol',        label: 'Symbol',    w: 90, str: true },
  { key: 'sector',        label: 'Sector',    w: 150, str: true },
  { key: 'price',         label: 'ราคา',       w: 70 },
  { key: 'ret_1d',        label: '1D',        w: 62 },
  { key: 'ret_1w',        label: '1W',        w: 62 },
  { key: 'ret_1m',        label: '1M',        w: 62 },
  { key: 'ret_3m',        label: '3M',        w: 62 },
  { key: 'ret_1y',        label: '1Y',        w: 66 },
  { key: 'rs_momentum',   label: 'RS Δ4w',    w: 62 },
  { key: '_pct_off_high', label: '% จาก High', w: 76 },
  { key: 'above_ema50',   label: 'EMA50',     w: 56 },
  { key: 'above_ema200',  label: 'EMA200',    w: 58 },
  { key: 'stage',         label: 'Stage',     w: 80 },
];

// TradingView ใช้ HKEX:รหัส (ไม่มีเลข 0 นำหน้า, ไม่มี .HK) ต่างจาก symbol
// รูปแบบ yfinance ("0700.HK") ที่ใช้เก็บใน hk_prices.db/hk_index_metrics.json
function _hkTvLink(sym) {
  const code = sym.replace(/\.HK$/i, '').replace(/^0+/, '') || '0';
  return `<a class="tv-link" href="https://www.tradingview.com/chart/?symbol=HKEX%3A${encodeURIComponent(code)}" target="_blank" title="เปิด TradingView">↗</a>`;
}

function renderHkTable() {
  if (!_hkData) return;
  let rows = _hkFilteredStocks();
  rows.sort((a, b) => {
    const av = a[_hkSort.key], bv = b[_hkSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    if (typeof av === 'string') return av.localeCompare(bv) * (_hkSort.dir === 1 ? -1 : 1);
    return (bv - av) * _hkSort.dir;
  });

  const thead = document.getElementById('hk-thead');
  if (thead) thead.innerHTML = _HK_COLS.map(c => {
    const arrow = _hkSort.key === c.key ? (_hkSort.dir === 1 ? ' ▾' : ' ▴') : '';
    const align = c.str ? 'left' : 'right';
    return `<th style="width:${c.w}px;text-align:${align};cursor:pointer;white-space:nowrap" onclick="hkSortBy('${c.key}')">${c.label}${arrow}</th>`;
  }).join('');

  const body = rows.map(s => {
    const offHigh = s._pct_off_high;
    const offCls = offHigh == null ? 'text2' : offHigh >= -3 ? 'green' : offHigh >= -10 ? 'yellow' : 'text2';
    return `<tr>
      <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '-'}</span></td>
      <td><strong class="sym-link" onclick="openHkChartModal('${s.symbol}')">${s.symbol}</strong>${_hkTvLink(s.symbol)}</td>
      <td style="font-size:11px;color:var(--text2)">${s.sector || '—'}</td>
      <td class="r">${s.price != null ? s.price.toFixed(2) : '—'}</td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.rs_momentum != null ? `<span class="${s.rs_momentum > 0 ? 'green' : s.rs_momentum < 0 ? 'red' : 'text2'}">${s.rs_momentum > 0 ? '+' : ''}${s.rs_momentum}</span>` : '<span class="text2">—</span>'}</td>
      <td class="r"><span class="${offCls}" style="font-size:11px">${offHigh != null ? offHigh.toFixed(1) + '%' : '—'}</span></td>
      <td class="r">${emaBadge(s.above_ema50)}</td>
      <td class="r">${emaBadge(s.above_ema200)}</td>
      <td class="r">${stageBadge(s.stage)}</td>
    </tr>`;
  }).join('');
  const tbody = document.getElementById('hk-stocks-tbody');
  if (tbody) tbody.innerHTML = body || `<tr><td colspan="14" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีหุ้นตรงเงื่อนไข</td></tr>`;

  const total = _hkData.stocks.filter(s => s[_HK_IDX_FLAG[_hkIndex]]).length;
  const upd = _hkData.updated_at ? ` · อัพเดท ${_hkData.updated_at}` : '';
  const cnt = document.getElementById('hk-count');
  if (cnt) cnt.textContent = `แสดง ${rows.length}/${total} ตัว${upd}`;

  _renderHkBreadth();
}

// ── HK Sector Ranking (mode toggle บนหน้า "หุ้น HK") ──────────────────────
let _hkMode = 'stocks';
let _hkSectorRanks = {};      // { HSI: [...], HSTECH: [...], HSCEI: [...] }
let _hkSectorSort = { key: 'avg_rs', dir: 1 };

function setHkMode(mode) {
  _hkMode = mode;
  const btn = document.getElementById('hk-mode-sectors');
  if (btn) btn.classList.toggle('active', mode === 'sectors');
  document.getElementById('hk-stocks-wrap').style.display  = mode === 'sectors' ? 'none' : '';
  document.getElementById('hk-sectors-wrap').style.display = mode === 'sectors' ? '' : 'none';
  // เหตุผลเดียวกับ setUsMode — กันตารางค้างดัชนีเก่าตอนกลับมาโหมด stocks
  if (mode === 'sectors') loadHkSectorRanks();
  else renderHkTable();
}

function hkSectorSortBy(key) {
  if (_hkSectorSort.key === key) _hkSectorSort.dir *= -1;
  else _hkSectorSort = { key, dir: 1 };
  renderHkSectorTable();
}

function loadHkSectorRanks() {
  if (_hkSectorRanks[_hkIndex]) { renderHkSectorTable(); return; }
  const idx = _hkIndex;   // เหตุผลเดียวกับ loadUsSectorRanks — กัน race ตอนสลับดัชนีระหว่างรอ
  const tbody = document.getElementById('hk-sectors-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _fetchTimeout(`/api/hk-sector-ranks?index=${idx}`, 30000, 'หมดเวลารอ Sector Ranking หุ้น HK (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      const sectors = d.sectors || [];
      // อย่า cache ก้อนว่าง — [] เป็น truthy ทำให้ guard `if (_hkSectorRanks[_hkIndex])`
      // ข้าม fetch ถาวร (เมนู Sector Ranking ค้าง "ไม่มีข้อมูล" จนกว่าจะ F5) ตอน metrics
      // ยังไม่ถูก build หรือ response error ชั่วคราว
      if (sectors.length) _hkSectorRanks[idx] = sectors;
      if (idx === _hkIndex) renderHkSectorTable();
    })
    .catch(e => {
      if (idx === _hkIndex && tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    });
}

function renderHkSectorTable() {
  const rows = [...(_hkSectorRanks[_hkIndex] || [])];
  rows.sort((a, b) => {
    const av = a[_hkSectorSort.key], bv = b[_hkSectorSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    return (bv - av) * _hkSectorSort.dir;
  });
  const tbody = document.getElementById('hk-sectors-tbody');
  if (!tbody) return;
  tbody.innerHTML = rows.map((s, i) => `
    <tr style="cursor:pointer" onclick="_openHkSector('${s.name.replace(/'/g,"\\'")}')">
      <td class="text2">${i + 1}</td>
      <td><strong>${s.name}</strong></td>
      <td class="r text2">${s.count}</td>
      <td class="r"><span class="${rsColor(s.avg_rs)}" style="font-weight:700">${s.avg_rs ?? '—'}</span></td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.pct_above_ema50 != null ? s.pct_above_ema50 + '%' : '—'}</td>
    </tr>`).join('') || `<tr><td colspan="10" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีข้อมูล</td></tr>`;
}

function _openHkSector(name) {
  setHkMode('stocks');
  const sel = document.getElementById('hk-sector-filter');
  if (sel) { sel.value = name; _hkSector = name; }
  renderHkTable();
}

function _renderHkBreadth() {
  const flag = _HK_IDX_FLAG[_hkIndex];
  const all = _hkData.stocks.filter(s => s[flag]);
  const n = all.length || 1;
  const p200 = all.filter(s => s.above_ema200).length / n * 100;
  const p50  = all.filter(s => s.above_ema50).length / n * 100;
  const rs80 = all.filter(s => (s.rs_score ?? 0) >= 80).length;
  const nearHigh = all.filter(s => { const o = _hkPctOffHigh(s); return o != null && o >= -3; }).length;
  const s2 = all.filter(s => s.stage === 2).length;
  const tile = (label, val, sub, color) =>
    `<div class="card" style="padding:12px 14px">
      <div style="font-size:11px;color:var(--text2)">${label}</div>
      <div style="font-size:22px;font-weight:700;color:${color || 'var(--text)'}">${val}</div>
      <div style="font-size:10px;color:var(--text2)">${sub}</div>
    </div>`;
  const emaColor = p200 >= 60 ? '#3fb950' : p200 < 40 ? '#f85149' : '#e3b341';
  const strip = document.getElementById('hk-breadth-strip');
  if (strip) strip.innerHTML =
    tile('% เหนือ EMA200', p200.toFixed(0) + '%', `EMA50: ${p50.toFixed(0)}%`, emaColor) +
    tile('RS ≥ 80', rs80, `${(rs80 / n * 100).toFixed(0)}% ของดัชนี`, '#3fb950') +
    tile('Stage 2', s2, `${(s2 / n * 100).toFixed(0)}% กำลังขาขึ้น`, '#3fb950') +
    tile('ใกล้ 52W High', nearHigh, 'ห่าง high ≤ 3%', '#58a6ff');
}

// ============================================================
// หุ้น JP (Nikkei 225) — ดัชนีเดียว (ต่างจาก US/HK ที่มีหลายดัชนีให้สลับแท็บ)
// Phase 1: ไม่มี breadth-history chart/sector-ranking mode (ยังไม่มี /api/jp-breadth,
// /api/jp-sector-ranks backend — ดู PLAN Deferred) มีแค่ breadth strip สรุปสด ๆ
// จากข้อมูลที่โหลดมาแล้ว (ไม่ต้องยิง endpoint เพิ่ม)
// ============================================================
let _jpData = null;
let _jpStocksLoading = false;
let _jpView = 'all';         // all | rs80 | stage2 | nearhigh | momentum | ema200
let _jpSector = 'ALL';
let _jpSort = { key: 'rs_score', dir: 1 };

function _jpPctOffHigh(s) {
  if (!s.price || !s.high_52w) return null;
  return (s.price - s.high_52w) / s.high_52w * 100;
}

function setJpView(view, btn) {
  _jpView = view;
  document.querySelectorAll('#jp-view-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (view === 'nearhigh')      _jpSort = { key: '_pct_off_high', dir: 1 };
  else if (view === 'momentum') _jpSort = { key: 'rs_momentum', dir: 1 };
  else                          _jpSort = { key: 'rs_score', dir: 1 };
  renderJpTable();
}

function jpSortBy(key) {
  if (_jpSort.key === key) {
    _jpSort.dir *= -1;
  } else {
    const col = _JP_COLS.find(c => c.key === key);
    _jpSort = { key, dir: col && col.str ? -1 : 1 };
  }
  renderJpTable();
}

function loadJpStocksPage() {
  if (_jpData) { renderJpTable(); loadJpBreadthChart(); return; }
  if (_jpStocksLoading) return;
  const tbody = document.getElementById('jp-stocks-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _jpStocksLoading = true;
  _fetchTimeout('/api/jp-index-metrics', 30000, 'หมดเวลารอข้อมูลหุ้น JP (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      if (!d.stocks || !d.stocks.length) {
        if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--text2)">ยังไม่มีข้อมูล — กดปุ่ม <b>📈 JP Index Max</b> หรือ <b>⚡ Quick Update</b> เพื่อดึงราคาและคำนวณ metrics</td></tr>`;
        return;
      }
      // กัน null entry ใน jp_index_metrics.json (JSON เพี้ยน) ทำให้ s.sector/s.symbol throw
      // ทั้งหน้า — hardening แบบเดียวกับ loadHkStocksPage
      if (Array.isArray(d.stocks)) d.stocks = d.stocks.filter(s => s && typeof s === 'object');
      _jpData = d;
      _rebuildJpSectorFilter();
      renderJpTable();
      loadJpBreadthChart();
    })
    .catch(e => {
      if (tbody) tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    })
    .finally(() => { _jpStocksLoading = false; });
}

function _rebuildJpSectorFilter() {
  if (!_jpData) return;
  const sectors = ['ALL', ...[...new Set(_jpData.stocks.map(s => s.sector || 'Unknown'))].sort()];
  const sel = document.getElementById('jp-sector-filter');
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = sectors.map(s => `<option value="${_escHtml(s)}">${s === 'ALL' ? 'ทุก Sector' : _escHtml(s)}</option>`).join('');
  sel.value = sectors.includes(cur) ? cur : 'ALL';
  _jpSector = sel.value;
}

function _jpFilteredStocks() {
  if (!_jpData) return [];
  let rows = _jpData.stocks.map(s => ({ ...s, _pct_off_high: _jpPctOffHigh(s) }));
  const sel = document.getElementById('jp-sector-filter');
  _jpSector = sel ? sel.value : 'ALL';
  if (_jpSector !== 'ALL') rows = rows.filter(s => (s.sector || 'Unknown') === _jpSector);
  const q = (document.getElementById('jp-search')?.value || '').trim().toLowerCase();
  if (q) rows = rows.filter(s => s.symbol.toLowerCase().includes(q) || (s.name || '').toLowerCase().includes(q));
  if (_jpView === 'rs80')     rows = rows.filter(s => (s.rs_score ?? -1) >= 80);
  else if (_jpView === 'stage2')   rows = rows.filter(s => s.stage === 2);
  else if (_jpView === 'nearhigh') rows = rows.filter(s => s._pct_off_high != null && s._pct_off_high >= -5);
  else if (_jpView === 'momentum') rows = rows.filter(s => (s.rs_momentum ?? 0) > 0);
  else if (_jpView === 'ema200')   rows = rows.filter(s => s.above_ema200 === true);
  return rows;
}

const _JP_COLS = [
  { key: 'rs_score',      label: 'RS',        w: 46 },
  { key: 'symbol',        label: 'Symbol',    w: 90, str: true },
  { key: 'sector',        label: 'Sector',    w: 150, str: true },
  { key: 'price',         label: 'ราคา (JPY)', w: 80 },
  { key: 'ret_1d',        label: '1D',        w: 62 },
  { key: 'ret_1w',        label: '1W',        w: 62 },
  { key: 'ret_1m',        label: '1M',        w: 62 },
  { key: 'ret_3m',        label: '3M',        w: 62 },
  { key: 'ret_1y',        label: '1Y',        w: 66 },
  { key: 'rs_momentum',   label: 'RS Δ4w',    w: 62 },
  { key: '_pct_off_high', label: '% จาก High', w: 76 },
  { key: 'above_ema50',   label: 'EMA50',     w: 56 },
  { key: 'above_ema200',  label: 'EMA200',    w: 58 },
  { key: 'stage',         label: 'Stage',     w: 80 },
];

// TradingView ใช้ TSE:รหัส (ไม่มี .T) ต่างจาก symbol รูปแบบ yfinance ("7203.T") ที่ใช้
// เก็บใน jp_prices.db/jp_index_metrics.json
function _jpTvLink(sym) {
  const code = sym.replace(/\.T$/i, '');
  return `<a class="tv-link" href="https://www.tradingview.com/chart/?symbol=TSE%3A${encodeURIComponent(code)}" target="_blank" title="เปิด TradingView">↗</a>`;
}

function renderJpTable() {
  if (!_jpData) return;
  let rows = _jpFilteredStocks();
  rows.sort((a, b) => {
    const av = a[_jpSort.key], bv = b[_jpSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    if (typeof av === 'string') return av.localeCompare(bv) * (_jpSort.dir === 1 ? -1 : 1);
    return (bv - av) * _jpSort.dir;
  });

  const thead = document.getElementById('jp-thead');
  if (thead) thead.innerHTML = _JP_COLS.map(c => {
    const arrow = _jpSort.key === c.key ? (_jpSort.dir === 1 ? ' ▾' : ' ▴') : '';
    const align = c.str ? 'left' : 'right';
    return `<th style="width:${c.w}px;text-align:${align};cursor:pointer;white-space:nowrap" onclick="jpSortBy('${c.key}')">${c.label}${arrow}</th>`;
  }).join('');

  const body = rows.map(s => {
    const offHigh = s._pct_off_high;
    const offCls = offHigh == null ? 'text2' : offHigh >= -3 ? 'green' : offHigh >= -10 ? 'yellow' : 'text2';
    return `<tr>
      <td><span class="${rsColor(s.rs_score)}" style="font-weight:700">${s.rs_score ?? '-'}</span></td>
      <td><strong class="sym-link" onclick="openJpChartModal('${s.symbol}')">${s.symbol}</strong>${_jpTvLink(s.symbol)}</td>
      <td style="font-size:11px;color:var(--text2)">${s.sector ? _escHtml(s.sector) : '—'}</td>
      <td class="r">${s.price != null ? s.price.toFixed(1) : '—'}</td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.rs_momentum != null ? `<span class="${s.rs_momentum > 0 ? 'green' : s.rs_momentum < 0 ? 'red' : 'text2'}">${s.rs_momentum > 0 ? '+' : ''}${s.rs_momentum}</span>` : '<span class="text2">—</span>'}</td>
      <td class="r"><span class="${offCls}" style="font-size:11px">${offHigh != null ? offHigh.toFixed(1) + '%' : '—'}</span></td>
      <td class="r">${emaBadge(s.above_ema50)}</td>
      <td class="r">${emaBadge(s.above_ema200)}</td>
      <td class="r">${stageBadge(s.stage)}</td>
    </tr>`;
  }).join('');
  const tbody = document.getElementById('jp-stocks-tbody');
  if (tbody) tbody.innerHTML = body || `<tr><td colspan="14" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีหุ้นตรงเงื่อนไข</td></tr>`;

  const total = _jpData.stocks.length;
  const upd = _jpData.updated_at ? ` · อัพเดท ${_jpData.updated_at}` : '';
  const cnt = document.getElementById('jp-count');
  if (cnt) cnt.textContent = `แสดง ${rows.length}/${total} ตัว${upd}`;

  _renderJpBreadth();
}

function _renderJpBreadth() {
  const all = _jpData.stocks;
  const n = all.length || 1;
  const p200 = all.filter(s => s.above_ema200).length / n * 100;
  const p50  = all.filter(s => s.above_ema50).length / n * 100;
  const rs80 = all.filter(s => (s.rs_score ?? 0) >= 80).length;
  const nearHigh = all.filter(s => { const o = _jpPctOffHigh(s); return o != null && o >= -3; }).length;
  const s2 = all.filter(s => s.stage === 2).length;
  const tile = (label, val, sub, color) =>
    `<div class="card" style="padding:12px 14px">
      <div style="font-size:11px;color:var(--text2)">${label}</div>
      <div style="font-size:22px;font-weight:700;color:${color || 'var(--text)'}">${val}</div>
      <div style="font-size:10px;color:var(--text2)">${sub}</div>
    </div>`;
  const emaColor = p200 >= 60 ? '#3fb950' : p200 < 40 ? '#f85149' : '#e3b341';
  const strip = document.getElementById('jp-breadth-strip');
  if (strip) strip.innerHTML =
    tile('% เหนือ EMA200', p200.toFixed(0) + '%', `EMA50: ${p50.toFixed(0)}%`, emaColor) +
    tile('RS ≥ 80', rs80, `${(rs80 / n * 100).toFixed(0)}% ของดัชนี`, '#3fb950') +
    tile('Stage 2', s2, `${(s2 / n * 100).toFixed(0)}% กำลังขาขึ้น`, '#3fb950') +
    tile('ใกล้ 52W High', nearHigh, 'ห่าง high ≤ 3%', '#58a6ff');
}

// ── JP % ABOVE EMA ย้อนหลัง — เหมือน US/HK (reuse drawIndexBreadthChart/_bcSetup/_bcAxes/_bcLine) ──
let _jpBreadthData = null;
let _jpBreadthRange = '1y';
let _jpBreadthCacheByRange = {};
let _jpBreadthLoading = false;
// bump เมื่อ cache ถูกล้าง (Quick Update / JP Index Max เสร็จ) — response ที่ยิงค้างอยู่
// ก่อนล้างจะเช็ค epoch ไม่ตรงแล้วทิ้ง ไม่เขียนข้อมูลเก่าทับ cache ที่เพิ่งล้าง
let _jpBreadthEpoch = 0;

function setJpBreadthRange(range, btn) {
  if (_jpBreadthRange === range) return;
  _jpBreadthRange = range;
  document.querySelectorAll('#jp-breadth-range-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadJpBreadthChart();
}

async function loadJpBreadthChart() {
  const rng = _jpBreadthRange;
  const epoch = _jpBreadthEpoch;
  const cached = _jpBreadthCacheByRange[rng];
  if (cached) { _jpBreadthData = cached; drawJpBreadthChart(); return; }
  if (_jpBreadthLoading) return;
  _jpBreadthLoading = true;
  ['jp-bc-ema', 'jp-bc-nhnl', 'jp-bc-mcc'].forEach(id => {
    const loading = document.getElementById(id + '-loading');
    const canvas  = document.getElementById(id);
    if (loading) { loading.style.display = 'block'; loading.textContent = 'กำลังโหลด...'; }
    if (canvas)  canvas.style.display = 'none';
  });
  try {
    const r = await _fetchTimeout('/api/jp-breadth?range=' + encodeURIComponent(rng), 30000,
      'หมดเวลารอ Market Breadth หุ้น JP (เกิน 30 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    // cache ถูกล้างระหว่างรอ response (Quick Update/JP Index Max เสร็จ) — ข้อมูลนี้เก่าแล้ว ทิ้ง
    if (epoch !== _jpBreadthEpoch) return;
    _jpBreadthCacheByRange[rng] = d;
    if (rng === _jpBreadthRange) {
      _jpBreadthData = d;
      drawJpBreadthChart();
    }
  } catch (e) {
    ['jp-bc-ema', 'jp-bc-nhnl', 'jp-bc-mcc'].forEach(id => {
      const el = document.getElementById(id + '-loading');
      if (el) el.textContent = 'โหลดไม่สำเร็จ: ' + e.message;
    });
  } finally {
    _jpBreadthLoading = false;
    if (epoch === _jpBreadthEpoch && _jpBreadthRange !== rng && !_jpBreadthCacheByRange[_jpBreadthRange]) loadJpBreadthChart();
  }
}

function drawJpBreadthChart() {
  drawIndexBreadthChart('jp', _jpBreadthData);
}

// ── JP Sector Ranking (mode toggle บนหน้า "หุ้น JP") ──────────────────────
// อ่าน /api/jp-sector-ranks ซึ่ง reuse core.metrics.summarize_groups() ตัวเดียวกับ
// หน้า Sectors ของหุ้นไทย/US/HK — ไม่มี ?index= เพราะ JP มีดัชนีเดียว (Nikkei 225)
let _jpMode = 'stocks';
let _jpSectorRanks = null;    // [...] (ไม่ต้องแยก cache ตามดัชนีเหมือน US/HK เพราะมีดัชนีเดียว)
let _jpSectorSort = { key: 'avg_rs', dir: 1 };

function setJpMode(mode) {
  _jpMode = mode;
  const btn = document.getElementById('jp-mode-sectors');
  if (btn) btn.classList.toggle('active', mode === 'sectors');
  document.getElementById('jp-stocks-wrap').style.display  = mode === 'sectors' ? 'none' : '';
  document.getElementById('jp-sectors-wrap').style.display = mode === 'sectors' ? '' : 'none';
  if (mode === 'sectors') loadJpSectorRanks();
  else renderJpTable();
}

function jpSectorSortBy(key) {
  if (_jpSectorSort.key === key) _jpSectorSort.dir *= -1;
  else _jpSectorSort = { key, dir: 1 };
  renderJpSectorTable();
}

function loadJpSectorRanks() {
  if (_jpSectorRanks) { renderJpSectorTable(); return; }
  const tbody = document.getElementById('jp-sectors-tbody');
  if (tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text2)">กำลังโหลด...</td></tr>`;
  _fetchTimeout('/api/jp-sector-ranks', 30000, 'หมดเวลารอ Sector Ranking หุ้น JP (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      const sectors = d.sectors || [];
      // อย่า cache ก้อนว่าง — ดูเหตุผลใน loadHkSectorRanks
      if (sectors.length) _jpSectorRanks = sectors;
      renderJpSectorTable();
    })
    .catch(e => {
      if (tbody) tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${e.message}</td></tr>`;
    });
}

function renderJpSectorTable() {
  const rows = [...(_jpSectorRanks || [])];
  rows.sort((a, b) => {
    const av = a[_jpSectorSort.key], bv = b[_jpSectorSort.key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1; if (bv == null) return -1;
    return (bv - av) * _jpSectorSort.dir;
  });
  const tbody = document.getElementById('jp-sectors-tbody');
  if (!tbody) return;
  tbody.innerHTML = rows.map((s, i) => `
    <tr style="cursor:pointer" onclick="_openJpSector('${_escJsAttr(s.name || 'Unknown')}')">
      <td class="text2">${i + 1}</td>
      <td><strong>${_escHtml(s.name || 'Unknown')}</strong></td>
      <td class="r text2">${s.count}</td>
      <td class="r"><span class="${rsColor(s.avg_rs)}" style="font-weight:700">${s.avg_rs ?? '—'}</span></td>
      <td class="r">${pct(s.ret_1d)}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${s.pct_above_ema50 != null ? s.pct_above_ema50 + '%' : '—'}</td>
    </tr>`).join('') || `<tr><td colspan="10" style="text-align:center;padding:20px;color:var(--text2)">ไม่มีข้อมูล</td></tr>`;
}

// คลิกแถว sector → กลับไปหน้าตารางหุ้น กรองเฉพาะ sector นั้น
function _openJpSector(name) {
  setJpMode('stocks');
  const sel = document.getElementById('jp-sector-filter');
  if (sel) { sel.value = name; _jpSector = name; }
  renderJpTable();
}

// ============================================================
// HEATMAP — S&P 500 / Dow Jones / Nasdaq 100
// เปลี่ยนจาก treemap (ขนาดกล่อง=market cap) มาเป็น grid ขนาดเท่ากันจัดกลุ่มตาม sector แบบ
// หน้า "Market Heatmap" หุ้นไทย (renderHeatmap ด้านบน) — เหตุผล: treemap ต้องพึ่ง market cap
// ที่ต้องยิง Yahoo fast_info ทีละ ticker (ช้า ~30-60 วิตอน cache หมดอายุ) ตัด market cap ออก
// ทั้งฝั่ง backend แล้ว (ดู /api/us-index-heatmap) เปลี่ยนไปอ่านจาก us_index_metrics.json
// ตรงๆ (field เดียวกับหุ้นไทยทุกตัว — process_stock() เดียวกัน) เลยมี metric ให้เลือกสีได้
// ครบ 11 แบบเหมือนหน้าไทย ใช้ HM_CFG ชุดเดียวกัน (ดู setHeatmapPeriod/_hmGridHtml)
// ============================================================
let _hmIndex = 'SP500';
let _hmPeriod = 'ret_1d';   // key ใน HM_CFG — สลับดูได้ทันทีจากข้อมูลชุดเดียวกัน ไม่ยิง API ซ้ำ
let _hmSortDir = 1;    // 1 = มากไปน้อย, -1 = น้อยไปมาก — คลิกปุ่ม metric เดิมซ้ำเพื่อสลับ (ดู _hmCmp)
let _hmData = {};      // cache ในหน่วยความจำต่อ tab {SP500:{rows,ts,requested,missing}, DOW:{...}, NDX:{...}}

// ลิงก์ไปหน้า Heatmap จริงของ TradingView.com ต่อดัชนี — เผื่อผู้ใช้อยากดู treemap ขนาดกล่อง
// = market cap จริง (ของเราตัด market cap ออกแล้วเปลี่ยนเป็น grid ขนาดเท่ากันแทน เพราะเดิมต้อง
// ยิง Yahoo fast_info ทีละ ticker ทำให้หน้าโหลดช้ามาก — ดู _hmGridHtml ด้านล่าง)
//
// DOW ใช้ dataSource "DJCA" (Dow Jones Composite Average ~65 ตัว = อุตสาหกรรม 30 + ขนส่ง 20 +
// สาธารณูปโภค 15) ไม่ใช่ DJIA 30 ตัวล้วนที่หน้าเราแสดง — เช็คแล้วว่า widget heatmap สาธารณะของ
// TradingView (tradingview.com/heatmap/stock) ไม่มี dataSource ให้เลือกเฉพาะ DJIA 30 ตัวตรงๆ
// (ตัวเลือก "Dow Jones" ในหน้านั้นคือ DJCA นี่แหละ) เลยเป็นตัวที่ใกล้เคียงที่สุดที่มี ผู้ใช้คลิก
// จากแท็บ Dow แล้วจะเห็นหุ้นเพิ่มมาจากกลุ่มขนส่ง/สาธารณูปโภคที่ไม่ได้อยู่ใน DJIA 30 ตัว
const _HM_TV_URL = {
  SP500: 'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22SPX500%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
  NDX:   'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22NASDAQ100%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
  DOW:   'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22DJCA%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
};

function _hmOpenTradingView() {
  const url = _HM_TV_URL[_hmIndex];
  if (url) window.open(url, '_blank', 'noopener');
}

function usHmLiveUpdate() {
  const idx = _hmIndex;   // จับค่าแท็บตอนกดปุ่ม — ไม่ใช่ _hmIndex "ล่าสุด" ตอนงานเสร็จ (ดูคอมเมนต์ _hmLiveUpdate)
  _hmLiveUpdate('US', document.getElementById('hm-refresh-btn'), '⚡ อัพเดทราคา',
    () => loadHeatmapPage(true, idx), idx, 'hm-note', () => _hmIndex === idx);
}

function setHeatmapIndex(idx, btn) {
  _hmIndex = idx;
  document.querySelectorAll('#hm-idx-sp500,#hm-idx-dow,#hm-idx-ndx').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadHeatmapPage();
}

function setHeatmapPeriod(period, btn) {
  _hmSortDir = (period === _hmPeriod) ? -_hmSortDir : 1;
  _hmPeriod = period;
  document.querySelectorAll('#hm-period-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const hintEl = document.getElementById('us-hm-hint');
  if (hintEl) hintEl.textContent = (HM_CFG[period] || HM_CFG.ret_1d).hint +
    (_hmSortDir === 1 ? ' · เรียงมาก→น้อย' : ' · เรียงน้อย→มาก') + ' (คลิกปุ่มเดิมซ้ำเพื่อสลับ)';
  if (_hmData[_hmIndex]) _renderHeatmap(_hmData[_hmIndex]);
}

// targetIndex (optional) — ดัชนีที่ต้องการโหลด แทนที่จะเป็น _hmIndex "ล่าสุด" ตอน response
// กลับมา (เดิมอ่าน _hmIndex ซ้ำทั้งตอนสร้าง URL และตอนเขียน cache — ถ้าผู้ใช้สลับแท็บระหว่างรอ
// (เช่น กด Dow แล้วรีบสลับไป Nasdaq-100 ก่อน response ของ Dow กลับมา) response ของ Dow ที่มาช้า
// จะถูกเขียนทับ cache ของแท็บที่กำลังดูอยู่ (NDX) แทน ทำให้เห็นหุ้น Dow ติดป้ายว่าเป็น NDX)
// ใช้ตอนเรียกจาก onDone ของ live-update ด้วย (ต้อง refresh cache ของแท็บที่กดตอนเริ่ม ไม่ใช่
// แท็บที่กำลังดูอยู่ตอนงานเสร็จ)
function loadHeatmapPage(forceRefresh = false, targetIndex) {
  const idx = targetIndex || _hmIndex;
  const isActive = () => idx === _hmIndex;
  const box = document.getElementById('hm-box');
  const note = document.getElementById('hm-note');
  if (!box) return;
  if (!forceRefresh && _hmData[idx]) { if (isActive()) _renderHeatmap(_hmData[idx]); return; }
  const btn = document.getElementById('hm-refresh-btn');
  if (forceRefresh && btn && isActive()) { btn.disabled = true; btn.textContent = '⚡ กำลังอัพเดท...'; }
  if (isActive()) {
    box.innerHTML = `<div id="hm-loading" class="text2" style="font-size:13px">กำลังโหลด heatmap...</div>`;
    note.textContent = '';
  }
  return _fetchTimeout(`/api/us-index-heatmap?index=${idx}`, 30000, 'หมดเวลารอ heatmap หุ้น US (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      _hmData[idx] = d;
      if (!isActive()) return;
      _renderHeatmap(d);
      const age = Math.max(0, Math.round((Date.now() / 1000) - d.ts));
      const ageStr = age < 60 ? `${age} วิที่แล้ว` : `${Math.round(age / 60)} นาทีที่แล้ว`;
      const missNote = d.missing ? ` · ขาด ${d.missing} ตัว (ไม่มีราคาในเครื่อง)` : '';
      note.textContent = `ข้อมูล ณ ${ageStr} · ${(d.rows || []).length}/${d.requested} ตัว${missNote}`;
    })
    .catch(e => {
      if (!isActive()) return;
      box.innerHTML = `<div style="color:var(--red);font-size:13px;padding:20px;text-align:center">⚠ โหลดไม่สำเร็จ: ${e.message}</div>`;
    })
    .finally(() => {
      if (btn && isActive()) { btn.disabled = false; btn.textContent = '⚡ อัพเดทราคา'; }
    });
}

// Squarified treemap (Bruls/Huizing/van Wijk) — จัดกล่องให้สัดส่วนกว้าง:สูงใกล้ 1:1 มากที่สุด
// เท่าที่ทำได้ (ต่างจากแบ่งแถวธรรมดาที่กล่องเล็กสุดจะยาวเรียวจนอ่านตัวหนังสือไม่ได้) — heatmap
// US/HK/JP เลิกใช้แล้ว (เปลี่ยนเป็น grid ขนาดเท่ากัน) แต่ยังใช้กับ Hedge Holdings 13F heatmap
// (renderHedgeHeatmap) ที่ขนาดกล่อง = จำนวนกองถือ เลยเก็บฟังก์ชันนี้ไว้
function _squarify(data, x, y, w, h) {
  const total = data.reduce((a, d) => a + d.value, 0);
  if (total <= 0 || w <= 0 || h <= 0) return [];
  const scale = (w * h) / total;
  let items = data.map(d => ({ ...d, area: Math.max(d.value * scale, 0.01) }));
  let rect = { x, y, w, h };
  const result = [];

  const worstRatio = (row, side) => {
    const sum = row.reduce((a, d) => a + d.area, 0);
    let worst = 0;
    for (const d of row) {
      const r1 = (side * side * d.area) / (sum * sum);
      const r2 = (sum * sum) / (side * side * d.area);
      worst = Math.max(worst, r1, r2);
    }
    return worst;
  };

  while (items.length) {
    const side = Math.min(rect.w, rect.h);
    let row = [items[0]];
    let i = 1;
    while (i < items.length) {
      const testRow = row.concat([items[i]]);
      if (worstRatio(testRow, side) <= worstRatio(row, side)) { row = testRow; i++; }
      else break;
    }
    const rowSum = row.reduce((a, d) => a + d.area, 0);
    if (rect.w >= rect.h) {
      const colW = rowSum / rect.h;
      let oy = rect.y;
      row.forEach(d => {
        const boxH = d.area / colW;
        d.box = { x: rect.x, y: oy, w: colW, h: boxH };
        oy += boxH;
      });
      rect = { x: rect.x + colW, y: rect.y, w: rect.w - colW, h: rect.h };
    } else {
      const rowH = rowSum / rect.w;
      let ox = rect.x;
      row.forEach(d => {
        const boxW = d.area / rowH;
        d.box = { x: ox, y: rect.y, w: boxW, h: rowH };
        ox += boxW;
      });
      rect = { x: rect.x, y: rect.y + rowH, w: rect.w, h: rect.h - rowH };
    }
    items = items.slice(row.length);
    result.push(...row);
  }
  return result;
}

// สเกลสีแบบ diverging เขียว/แดง — ใช้คู่สีเดียวกับทั้งแอป (var(--green)/var(--red)) ไล่ความเข้ม
// จากเทากลาง (0%) ไปเข้มสุดที่ ±3% (คลิปไว้กันหุ้นข่าวช็อตทำให้กล่องอื่นดูจืดหมด)
// หมายเหตุ: heatmap US/HK/JP ไม่ได้ใช้ตัวนี้แล้ว (ใช้ HM_CFG[*].clr = _heatColor/_heatColorRS/
// _heatColorVol) — เหลือ caller เดียวคือ renderHedgeHeatmap (Hedge Holdings 13F) เท่านั้น
// อยู่ในโซน US HEATMAP เพราะประวัติศาสตร์ ไม่ใช่เพราะ heatmap หน้านี้เรียกใช้
function _hmColor(chg) {
  if (chg == null) return '#30363d';
  const clamp = Math.max(-3, Math.min(3, chg));
  const t = Math.abs(clamp) / 3;
  const neutral = [33, 38, 45];        // --bg3
  const pos = [63, 185, 80];           // --green
  const neg = [248, 81, 73];           // --red
  const target = clamp >= 0 ? pos : neg;
  const rgb = neutral.map((c, i) => Math.round(c + (target[i] - c) * t));
  return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
}

// วาดกล่องหุ้นหนึ่งตัวในกริด (ขนาดเท่ากันทุกกล่อง — คลาส .hm-cell ตัวเดียวกับ Market Heatmap
// หุ้นไทย) — dim กล่องที่ไม่ตรงคำค้นแทนการซ่อนทิ้ง เพื่อไม่ให้ layout เปลี่ยนฮวบฮาบเวลาพิมพ์ค้นหา
// ใช้ร่วมกันทั้ง US/HK/JP — popupFn คือชื่อฟังก์ชัน popup ของตลาดนั้นๆ (ต่าง state กัน)
// cfgKey คือ key ใน HM_CFG (ret_1d/ret_1w/.../rs_score/vol_ratio/from_52wh/ath_dist) — ตัวเดียว
// กับที่หน้า Market Heatmap หุ้นไทยใช้ (ดู renderHeatmap ด้านบน) ข้อมูล US/HK/JP มาจาก
// process_stock() เดียวกัน field ชื่อตรงกันทุกตัว เลยใช้ config ชุดเดียวกันได้เลยไม่ต้องแยก
function _hmGridCellHtml(r, cfgKey, search, popupFn) {
  const cfg = HM_CFG[cfgKey] || HM_CFG.ret_1d;
  const v = cfg.getV(r);
  let lbl = v != null ? cfg.fmt(v) : '—';
  // เมตริก "⚡ Live" fallback ไปโชว์ ret_1d ตอนไม่มี live_chg จริง (ตลาดปิด/ยังไม่กดปุ่ม —
  // ดู getV ใน HM_CFG.live_chg) ตัดไอคอน ⚡ ออกตอน fallback กันเข้าใจผิดว่าเป็นราคาสด
  // ทั้งที่จริงคือ % ปิดของวันปกติ
  if (cfgKey === 'live_chg' && v != null && r.live_chg == null) {
    lbl = (v > 0 ? '+' : '') + v.toFixed(2) + '%';
  }
  const dim = search && !r.symbol.toLowerCase().includes(search) && !(r.name || '').toLowerCase().includes(search);
  const priceV = r.live_price ?? r.price;
  const priceLbl = priceV != null ? priceV.toFixed(2) : '—';
  return `<div class="hm-cell" onclick="${popupFn}(event,'${_escJsAttr(r.symbol)}')"
    title="${_escHtml(r.name || '')} (${_escHtml(r.symbol)}): ${_escHtml(lbl)}"
    style="background:${cfg.clr(v)};color:${cfg.txt(v)};${dim ? 'opacity:.15;' : ''}">
    <span style="font-size:11px;font-weight:700">${_escHtml(r.symbol.replace(/\.(HK|T)$/, ''))}</span>
    <span style="font-size:9px;opacity:.85">${priceLbl}</span>
    <span style="font-size:10px;opacity:.92">${lbl}</span>
  </div>`;
}

// จัดกลุ่มแถวตาม sector แล้วเรียง sector ตามค่าเฉลี่ยของ metric ที่เลือก เหมือน renderHeatmap
// ของหุ้นไทยทุกประการ — dir: 1 = มากไปน้อย, -1 = น้อยไปมาก (ดู hmSortDir/_hmCmp ด้านบน)
// คืน HTML พร้อมใส่ลงกล่องได้เลย
function _hmGridHtml(rows, cfgKey, search, popupFn, dir = 1) {
  const cfg = HM_CFG[cfgKey] || HM_CFG.ret_1d;
  const groups = {};
  rows.forEach(r => { (groups[r.sector || 'อื่นๆ'] ??= []).push(r); });
  const sectorAvg = arr => { const vs = arr.map(cfg.getV).filter(v => v != null); return vs.length ? vs.reduce((s, v) => s + v, 0) / vs.length : null; };
  const sectorList = Object.entries(groups).sort(_hmCmp(x => sectorAvg(x[1]), dir));
  return sectorList.map(([sec, stocks]) => {
    const sorted = [...stocks].sort(_hmCmp(cfg.getV, dir));
    const withVal = sorted.filter(s => cfg.getV(s) != null);
    const avg = withVal.length ? withVal.reduce((s, x) => s + cfg.getV(x), 0) / withVal.length : null;
    const cells = sorted.map(r => _hmGridCellHtml(r, cfgKey, search, popupFn)).join('');
    const avgClass = avg != null ? (cfg.aPos(avg) ? 'green' : 'red') : 'text2';
    const avgDisp = avg != null ? cfg.aFmt(avg) : '—';
    return `
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;display:flex;align-items:center;gap:8px">
          ${_escHtml(sec)}
          <span class="${avgClass}">${avgDisp}</span>
          <span class="text2" style="font-size:10px">${stocks.length} หุ้น</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:2px">${cells}</div>
      </div>`;
  }).join('');
}

function _renderHeatmap(data) {
  const box = document.getElementById('hm-box');
  if (!box) return;
  // data เป็น undefined ได้ตอนพิมพ์ค้นหา (oninput) ก่อนโหลดเสร็จ/หลังโหลดล้มเหลว
  // (_hmData[_hmIndex] ยังไม่เคยตั้งค่า) — เดิมพัง data.rows ด้วย TypeError
  if (!data) return;
  const rows = data.rows || data;   // เผื่อเรียกจากที่อื่นด้วย array ตรงๆ
  if (!rows.length) {
    box.innerHTML = '<div class="text2" style="font-size:13px;padding:20px;text-align:center">ไม่มีข้อมูลราคาที่ใช้วาด heatmap ได้</div>';
    return;
  }
  const searchEl = document.getElementById('hm-search');
  const search = (searchEl?.value || '').trim().toLowerCase();
  box.innerHTML = _hmGridHtml(rows, _hmPeriod, search, '_hmOpenModal', _hmSortDir);
}

// เปิด chart modal เต็มรูปแบบทันที (เหมือนคลิกหุ้นไทยในหน้า Market Heatmap) แทนที่ popup
// ย่อเดิม — row จาก _hmData มี price_history/vol_history ครบอยู่แล้ว (source เดียวกับ
// /api/us-index-metrics) ส่งตรงเป็น rowOverride ให้ openUsChartModal ไม่ต้องรอ _usData โหลด
function _hmOpenModal(ev, sym) {
  const r = ((_hmData[_hmIndex] || {}).rows || []).find(x => x.symbol === sym);
  if (r) openUsChartModal(sym, r);
}

// ============================================================
// HK HEATMAP — HSI / HSTECH / HSCEI
// ก็อปโครงจาก US HEATMAP ด้านบนทั้งหมด — reuse _hmColor/_hmGridCellHtml/_hmGridHtml ตัวเดิม
// (generic ไม่มี id ผูกอยู่) ต่างแค่ prefix hm->hk-hm, endpoint /api/hk-index-heatmap
// ============================================================
let _hkHmIndex = 'HSI';
let _hkHmPeriod = 'ret_1d';   // key ใน HM_CFG (ดูคอมเมนต์หัวไฟล์ US heatmap ด้านบน)
let _hkHmSortDir = 1;    // 1 = มากไปน้อย, -1 = น้อยไปมาก — คลิกปุ่ม metric เดิมซ้ำเพื่อสลับ
let _hkHmData = {};      // {HSI:{rows,ts,requested,missing}, HSTECH:{...}, HSCEI:{...}}

// ลิงก์ TradingView Heatmap ต่อดัชนี — เหมือน _HM_TV_URL ของ US (ดูคอมเมนต์ตรงนั้น)
const _HK_HM_TV_URL = {
  HSI:    'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22HSI%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
  HSTECH: 'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22HSTECH%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
  HSCEI:  'https://www.tradingview.com/heatmap/stock/#%7B%22dataSource%22%3A%22HSCEI%22%2C%22blockColor%22%3A%22change%22%2C%22blockSize%22%3A%22market_cap_basic%22%2C%22grouping%22%3A%22sector%22%7D',
};

function _hkHmOpenTradingView() {
  const url = _HK_HM_TV_URL[_hkHmIndex];
  if (url) window.open(url, '_blank', 'noopener');
}

function hkHmLiveUpdate() {
  const idx = _hkHmIndex;   // จับค่าแท็บตอนกดปุ่ม — ดูคอมเมนต์ usHmLiveUpdate
  _hmLiveUpdate('HK', document.getElementById('hk-hm-refresh-btn'), '⚡ รีเฟรช',
    () => loadHkHeatmapPage(true, idx), idx, 'hk-hm-note', () => _hkHmIndex === idx);
}

function setHkHeatmapIndex(idx, btn) {
  _hkHmIndex = idx;
  document.querySelectorAll('#hk-hm-idx-hsi,#hk-hm-idx-hstech,#hk-hm-idx-hscei').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadHkHeatmapPage();
}

function setHkHeatmapPeriod(period, btn) {
  _hkHmSortDir = (period === _hkHmPeriod) ? -_hkHmSortDir : 1;
  _hkHmPeriod = period;
  document.querySelectorAll('#hk-hm-period-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const hintEl = document.getElementById('hk-hm-hint');
  if (hintEl) hintEl.textContent = (HM_CFG[period] || HM_CFG.ret_1d).hint +
    (_hkHmSortDir === 1 ? ' · เรียงมาก→น้อย' : ' · เรียงน้อย→มาก') + ' (คลิกปุ่มเดิมซ้ำเพื่อสลับ)';
  if (_hkHmData[_hkHmIndex]) _renderHkHeatmap(_hkHmData[_hkHmIndex]);
}

// targetIndex (optional) — ดูคอมเมนต์ loadHeatmapPage (US) ด้านบน เหตุผลเดียวกัน
function loadHkHeatmapPage(forceRefresh = false, targetIndex) {
  const idx = targetIndex || _hkHmIndex;
  const isActive = () => idx === _hkHmIndex;
  const box = document.getElementById('hk-hm-box');
  const note = document.getElementById('hk-hm-note');
  if (!box) return;
  if (!forceRefresh && _hkHmData[idx]) { if (isActive()) _renderHkHeatmap(_hkHmData[idx]); return; }
  const btn = document.getElementById('hk-hm-refresh-btn');
  if (forceRefresh && btn && isActive()) { btn.disabled = true; btn.textContent = '⚡ กำลังอัพเดท...'; }
  if (isActive()) {
    box.innerHTML = `<div id="hk-hm-loading" class="text2" style="font-size:13px">กำลังโหลด heatmap...</div>`;
    note.textContent = '';
  }
  return _fetchTimeout(`/api/hk-index-heatmap?index=${idx}`, 30000, 'หมดเวลารอ heatmap หุ้น HK (เกิน 30 วิ) — ลองใหม่อีกครั้ง')
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      _hkHmData[idx] = d;
      if (!isActive()) return;
      _renderHkHeatmap(d);
      const age = Math.max(0, Math.round((Date.now() / 1000) - d.ts));
      const ageStr = age < 60 ? `${age} วิที่แล้ว` : `${Math.round(age / 60)} นาทีที่แล้ว`;
      const missNote = d.missing ? ` · ขาด ${d.missing} ตัว` : '';
      note.textContent = `ข้อมูล ณ ${ageStr} · ${(d.rows || []).length}/${d.requested} ตัว${missNote}`;
    })
    .catch(e => {
      if (!isActive()) return;
      box.innerHTML = `<div style="color:var(--red);font-size:13px;padding:20px;text-align:center">⚠ โหลดไม่สำเร็จ: ${e.message}</div>`;
    })
    .finally(() => {
      if (btn && isActive()) { btn.disabled = false; btn.textContent = '⚡ รีเฟรช'; }
    });
}

function _renderHkHeatmap(data) {
  const box = document.getElementById('hk-hm-box');
  if (!box) return;
  // data undefined ได้ตอนพิมพ์ค้นหาก่อนโหลดเสร็จ/หลังโหลดล้มเหลว (ดูคอมเมนต์ใน _renderHeatmap)
  if (!data) return;
  const rows = data.rows || data;
  if (!rows.length) {
    box.innerHTML = '<div class="text2" style="font-size:13px;padding:20px;text-align:center">ไม่มีข้อมูลราคาที่ใช้วาด heatmap ได้</div>';
    return;
  }
  const searchEl = document.getElementById('hk-hm-search');
  const search = (searchEl?.value || '').trim().toLowerCase();
  box.innerHTML = _hmGridHtml(rows, _hkHmPeriod, search, '_hkHmOpenModal', _hkHmSortDir);
}

// เปิด chart modal เต็มรูปแบบทันที — ดูเหตุผล/comment เดียวกับ _hmOpenModal (US) ด้านบน
function _hkHmOpenModal(ev, sym) {
  const r = ((_hkHmData[_hkHmIndex] || {}).rows || []).find(x => x.symbol === sym);
  if (r) openHkChartModal(sym, r);
}

