// ============================================================
// ข่าวหุ้น (เมนู "📰 ข่าวหุ้น") — รวม SET.or.th + Yahoo + Google News ต่อหุ้นหนึ่งตัว
// ============================================================
let _newsTab = 'set';        // 'set' | 'dr'
let _newsSource = 'all';     // ตัวกรองแหล่ง: all | set | yahoo | google
let _newsRows = [];          // ผลล่าสุด (เก็บไว้กรองซ้ำฝั่ง client ไม่ต้องยิงใหม่)
let _newsReqSeq = 0;         // ตัวนับ request — ทิ้ง response ที่มาช้ากว่าการค้นหาครั้งล่าสุด
const NEWS_RECENT_KEY = 'newsRecentStocks';

const _NEWS_SRC_META = {
  set:    { label: '🏛️ SET.or.th', color: '#58a6ff' },
  yahoo:  { label: '🟣 Yahoo',      color: '#bc8cff' },
  google: { label: '🌐 Google News', color: '#3fb950' },
};

function initNewsPage() {
  initFinPage();   // ให้ datalist หุ้นไทย/DR ของหน้างบถูก populate ก่อน แล้วค่อยโคลนมาใช้
  _newsBuildDatalist();
  _newsRecentRender();
}

function _newsBuildDatalist() {
  const dl = document.getElementById('news-datalist');
  if (!dl) return;
  const src = document.getElementById(_newsTab === 'set' ? 'fin-set-datalist' : 'fin-dr-datalist');
  if (!src || !src.childElementCount) return;
  if (dl.dataset.tab === _newsTab && dl.childElementCount === src.childElementCount) return;
  dl.innerHTML = '';
  const frag = document.createDocumentFragment();
  [...src.children].forEach(o => frag.appendChild(o.cloneNode(true)));
  dl.appendChild(frag);
  dl.dataset.tab = _newsTab;
}

function setNewsTab(tab, btn) {
  _newsTab = tab;
  document.querySelectorAll('#news-tab-set,#news-tab-dr').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  // คนละ tab = คนละหุ้น/คนละชุดแหล่งข่าว — ล้างผลของหุ้นตัวก่อนไม่ให้ค้างจอ + ทิ้ง response ที่ยัง in-flight
  _newsReqSeq++;
  _newsRows = [];
  const out = document.getElementById('news-result'); if (out) out.innerHTML = '';
  const cnt = document.getElementById('news-count'); if (cnt) cnt.textContent = '';
  const filt = document.getElementById('news-src-filter'); if (filt) filt.style.display = 'none';
  const hint = document.getElementById('news-hint'); if (hint) hint.textContent = '';
  _newsBuildDatalist();
  // แหล่ง SET.or.th มีเฉพาะหุ้นไทย — ซ่อนปุ่มกรองนั้นตอนดูหุ้นต่างประเทศ
  const setBtn = document.getElementById('news-src-set');
  if (setBtn) setBtn.style.display = tab === 'dr' ? 'none' : '';
  if (tab === 'dr' && _newsSource === 'set') setNewsSource('all', document.getElementById('news-src-all'));
}

function setNewsSource(src, btn) {
  _newsSource = src;
  document.querySelectorAll('#news-src-all,#news-src-set,#news-src-yahoo,#news-src-google')
    .forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _renderNewsRows();
}

function _newsRecentRender() {
  const box = document.getElementById('news-recent');
  if (!box) return;
  let list = [];
  try { list = JSON.parse(localStorage.getItem(NEWS_RECENT_KEY)) || []; } catch {}
  if (!list.length) { box.style.display = 'none'; return; }
  box.style.display = 'flex';
  box.style.flexWrap = 'wrap';
  box.style.gap = '6px';
  box.style.alignItems = 'center';
  // sym มาจาก localStorage (ผู้ใช้พิมพ์เองไม่ validate) — กรองเป็น [A-Z0-9.-] ก่อนฝังลง onclick
  // เสมอ กันอักขระอย่าง ' แตก HTML/แทรกสคริปต์ (เหมือน pattern เดียวกับ _filRecentRender)
  const safe = s => String(s || '').replace(/[^A-Z0-9.\-]/gi, '');
  box.innerHTML = '<span style="color:var(--text2)">🕓 เพิ่งดู:</span>' +
    list.filter(r => safe(r.sym) && (r.tab === 'set' || r.tab === 'dr'))
      .map(r => `<button class="filter-btn" style="font-size:11px;padding:3px 10px"
      onclick="_newsRecentPick('${safe(r.sym)}','${r.tab}')">${r.tab === 'dr' ? '🌏' : '🇹🇭'} ${safe(r.sym)}</button>`).join('');
}

function _newsRecentAdd(sym, tab) {
  let list = [];
  try { list = JSON.parse(localStorage.getItem(NEWS_RECENT_KEY)) || []; } catch {}
  list = [{ sym, tab }, ...list.filter(r => !(r.sym === sym && r.tab === tab))].slice(0, 10);
  try { localStorage.setItem(NEWS_RECENT_KEY, JSON.stringify(list)); } catch {}
  _newsRecentRender();
}

function _newsRecentPick(sym, tab) {
  if (_newsTab !== tab) setNewsTab(tab, document.getElementById(tab === 'set' ? 'news-tab-set' : 'news-tab-dr'));
  document.getElementById('news-sym').value = sym;
  searchStockNews();
}

// เวลาแบบสัมพัทธ์ไทย — ข่าวเก่ากว่า 7 วันโชว์วันที่จริงแทน (นับ "45 วันที่แล้ว" ไม่ช่วยอะไร)
function _safeHref(u) {
  return /^https?:\/\//i.test(u || '') ? u : '#';
}

function _newsRelTime(iso) {
  if (!iso) return '';
  const t = new Date(iso);
  if (isNaN(t)) return '';
  const mins = Math.round((Date.now() - t.getTime()) / 60000);
  if (mins < 1) return 'เมื่อสักครู่';
  if (mins < 60) return `${mins} นาทีที่แล้ว`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs} ชม.ที่แล้ว`;
  const days = Math.round(hrs / 24);
  if (days <= 7) return `${days} วันที่แล้ว`;
  return t.toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: '2-digit' });
}

async function searchStockNews() {
  const sym = (document.getElementById('news-sym').value || '').trim().toUpperCase();
  if (!sym) return;
  const seq = ++_newsReqSeq;   // ค้นใหม่แซง → response เก่าที่มาช้ากว่าจะถูกทิ้ง (กันโชว์ข่าวผิดตัว)
  const isDr = _newsTab === 'dr';
  const hint = document.getElementById('news-hint');
  const out = document.getElementById('news-result');
  hint.textContent = 'กำลังรวมข่าวจากทุกแหล่ง...';
  out.innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข่าว (ครั้งแรกของหุ้นตัวนี้ ~5-15 วิ)...</div>';
  const market = isDr ? (typeof _finGuessDrMarket === 'function' ? _finGuessDrMarket(sym) : 'US') : '';
  try {
    const r = await _fetchTimeout(`/api/stock-news/${encodeURIComponent(sym)}${isDr ? `?is_dr=1&market=${market}` : ''}`, 35000);
    if (seq !== _newsReqSeq) return;
    if (!r.ok || !(r.headers.get('content-type') || '').includes('application/json')) {
      throw new Error('เมนูนี้ต้องรัน Flask server ในเครื่อง — ใช้บนเวอร์ชัน static/GitHub Pages ไม่ได้ (ดึงข่าวสดต่อหุ้น bake ล่วงหน้าไม่ได้)');
    }
    const d = await r.json();
    if (seq !== _newsReqSeq) return;
    if (d.error) throw new Error(d.error);
    _newsRows = d.rows || [];
    _newsRecentAdd(sym, _newsTab);
    document.getElementById('news-src-filter').style.display = 'flex';
    const age = Math.max(0, Math.round(Date.now() / 1000 - d.ts));
    hint.textContent = `ข้อมูล ณ ${age < 60 ? age + ' วิ' : Math.round(age / 60) + ' นาที'}ที่แล้ว`;
    // backend ส่งสาเหตุรายแหล่งมาแล้ว — เอาไปใส่ tooltip แทนที่จะโชว์แค่ชื่อแหล่ง
    // (ใช้ textContent/title ไม่ใช่ innerHTML เพราะข้อความ error มาจาก exception ภายนอก)
    const errs = Object.entries(d.errors || {});
    if (errs.length) {
      const note = document.createElement('span');
      note.textContent = ` · ⚠ แหล่งที่ดึงไม่สำเร็จ: ${errs.map(([k]) => k).join(', ')}`;
      note.title = errs.map(([k, v]) => `${k}: ${v}`).join('\n');
      note.style.cssText = 'color:var(--red);cursor:help';
      hint.appendChild(note);
    }
    _renderNewsRows();
  } catch (e) {
    if (seq !== _newsReqSeq) return;
    hint.textContent = '';
    out.innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${e.message}</div>`;
  }
}

function _renderNewsRows() {
  const out = document.getElementById('news-result');
  if (!out) return;
  const rows = _newsSource === 'all' ? _newsRows : _newsRows.filter(r => r.source === _newsSource);
  const cnt = document.getElementById('news-count');
  if (cnt) cnt.textContent = `${rows.length} ข่าว`;
  if (!rows.length) {
    out.innerHTML = '<div class="empty" style="padding:24px">ไม่พบข่าวจากแหล่งที่เลือก</div>';
    return;
  }
  out.innerHTML = `<div class="card" style="padding:4px 16px">` + rows.map(r => {
    const m = _NEWS_SRC_META[r.source] || { label: r.source, color: 'var(--text2)' };
    const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
    return `<div style="padding:11px 0;border-bottom:1px solid var(--border)">
      <div style="display:flex;gap:8px;align-items:baseline;flex-wrap:wrap;margin-bottom:3px;font-size:11px">
        <span style="color:${m.color};font-weight:600;white-space:nowrap">${m.label}</span>
        <span style="color:var(--text2)">${esc(r.publisher)}</span>
        <span style="color:var(--text2);margin-left:auto;white-space:nowrap" title="${esc(r.ts)}">${_newsRelTime(r.ts)}</span>
      </div>
      <a href="${esc(_safeHref(r.url))}" target="_blank" rel="noopener" style="color:var(--text);font-size:13.5px;font-weight:600;text-decoration:none;line-height:1.45"
        onmouseenter="this.style.color='var(--blue)'" onmouseleave="this.style.color='var(--text)'">${esc(r.title)}</a>
      ${r.summary ? `<div style="font-size:12px;color:var(--text2);margin-top:3px;line-height:1.5">${esc(r.summary)}</div>` : ''}
    </div>`;
  }).join('') + `</div>
  <div style="font-size:10.5px;color:var(--text2);margin-top:8px">คลิกหัวข้อเพื่อเปิดข่าวเต็มในแท็บใหม่ · ข่าว cache 15 นาทีต่อหุ้น · Google News รวมสื่อไทย (ทันหุ้น/ข่าวหุ้น/HoonVision ฯลฯ) และสำนักสากลให้อัตโนมัติ</div>`;
}

// สร้าง datalist ค้นหาหุ้นต่างประเทศ = DR ในพอร์ต (มีชื่อบริษัท) + หุ้น US/HK ทั้งตลาด (mirror)
function _buildDrDatalist() {
  const drd = document.getElementById('fin-dr-datalist');
  if (!drd) return;
  const drStocks = _drData || [];
  const mir = _finDrMirrorSyms || {};
  const inPort = new Set(drStocks.map(s => s.sym));
  const mirList = [...(mir.US || []).map(s => [s, 'US']), ...(mir.HK || []).map(s => [s, 'HK'])]
    .filter(([s]) => !inPort.has(s));   // ไม่ซ้ำกับ DR ในพอร์ต
  const want = drStocks.length + mirList.length;
  if (want === 0 || drd.childElementCount === want) return;   // ไม่มีอะไรเปลี่ยน ข้าม
  const frag = document.createDocumentFragment();
  drStocks.forEach(s => {
    const o = document.createElement('option');
    o.value = s.sym;
    o.label = s.etf ? `${s.name} ⚠ ETF — ไม่มีงบการเงิน` : s.name;
    frag.appendChild(o);
  });
  mirList.forEach(([sym, mk]) => {
    const o = document.createElement('option');
    o.value = sym;
    const nm = _finMirName(mk, sym);
    o.label = nm ? `${nm} · ${mk}` : `${sym} · ${mk} (Finnomena 16 ปี)`;
    frag.appendChild(o);
  });
  drd.innerHTML = '';
  drd.appendChild(frag);
  // datalist ต้นทางเพิ่งพร้อม (โหลด /api/dr + /api/mirror-symbols แบบ async) — โคลนเข้าหน้า
  // Filings ด้วย ไม่งั้น autocomplete ที่นั่นค้างว่างจนกว่าจะสลับแท็บ/เข้าหน้าใหม่
  if (typeof _filBuildDatalist === 'function') _filBuildDatalist();
}

// ประวัติหุ้นที่เพิ่งดูในหน้างบการเงิน (localStorage) — เก็บ 10 ตัวล่าสุด ไม่ซ้ำ
// คลิกชิปแล้วสลับแท็บ/เติมช่องค้นหา/ค้นหาให้อัตโนมัติ ลดการพิมพ์ซ้ำเวลาสลับดูหุ้นไปมา
const FIN_RECENT_KEY = 'finRecentStocks';
const FIN_RECENT_MAX = 10;

function _finRecentLoad() {
  try { return JSON.parse(localStorage.getItem(FIN_RECENT_KEY)) || []; }
  catch { return []; }
}

// mkt (US/HK/JP) จำไว้ด้วยเฉพาะแท็บ dr — หุ้น mirror ตัวเลข (เช่นรหัส JP) ชนกับรหัสตลาด
// อื่นได้ (ดู bug _finn_mirror_keys) ถ้าไม่จำตลาดไว้ คลิกชิปซ้ำตอนแท็บตลาดปัจจุบันไม่ตรง
// จะ resolve yf ticker ผิดตลาดแบบเงียบๆ
function _finRecentAdd(sym, tab, mkt) {
  let list = _finRecentLoad().filter(r => !(r.sym === sym && r.tab === tab));
  list.unshift({ sym, tab, mkt: mkt || null });
  list = list.slice(0, FIN_RECENT_MAX);
  try { localStorage.setItem(FIN_RECENT_KEY, JSON.stringify(list)); } catch {}
  _finRecentRender();
}

const FIN_RECENT_FLAG = { US: '🇺🇸', HK: '🇭🇰', JP: '🇯🇵' };

function _finRecentRender() {
  const box = document.getElementById('fin-recent');
  if (!box) return;
  // โหมด "เทียบหุ้น 2 ตัว" เปิดอยู่ → ซ่อนชิป "เพิ่งดู" (คนละบริบทกับค้นหุ้นเดี่ยว) — กัน
  // initFinPage()->_finRecentRender() ที่เรียกตอน toggleFinCompare เปิดพาเนล มาโชว์ชิปกลับ
  const cmpPanel = document.getElementById('fin-compare-panel');
  if (cmpPanel && cmpPanel.style.display !== 'none') { box.style.display = 'none'; return; }
  const list = _finRecentLoad();
  if (!list.length) { box.style.display = 'none'; return; }
  box.style.display = 'flex';
  box.style.flexWrap = 'wrap';
  box.style.gap = '6px';
  box.style.alignItems = 'center';
  box.innerHTML = '<span style="color:var(--text2);margin-right:2px">🕓 เพิ่งดู:</span>' +
    list.map(r => `<button class="filter-btn" style="font-size:11px;padding:3px 10px"
      onclick="_finRecentPick('${_escJsAttr(r.sym)}','${_escJsAttr(r.tab)}','${_escJsAttr(r.mkt || '')}')">${r.tab === 'dr' ? (FIN_RECENT_FLAG[r.mkt] || '🌏') : '🇹🇭'} ${_escHtml(r.sym)}</button>`).join('');
}

function _finRecentPick(sym, tab, mkt) {
  if (tab === 'dr' && mkt && mkt !== _finMirMarket) _finMirSelectMarket(mkt);
  if (_finTab !== tab) {
    setFinTab(tab, document.getElementById(tab === 'set' ? 'fin-tab-set-btn' : 'fin-tab-dr-btn'));
  }
  const inp = document.getElementById(tab === 'set' ? 'fin-sym-set' : 'fin-sym-dr');
  if (inp) inp.value = sym;
  searchFinancials();
}

// ============================================================
// เทียบหุ้น 2 ตัว — ตาราง P&L รายไตรมาส/รายปีย้อนหลัง + สรุป snapshot (ค่าล่าสุด) ของหุ้นสองตัว
// เทียบกัน จากงบ Finnomena 16 ปี / SET.or.th / Yahoo (กราฟ dual-line overlay รายได้ indexed +
// net margin ถูกถอดออกใน commit d0241a5 — ตอนนี้เป็นตารางล้วน)
// ผสมหุ้นไทย/ต่างประเทศกันได้ — ป้าย 🇹🇭/🌏 กำหนดตลาดตรงๆ ไม่มีการเดา (symbol บางตัวชนกัน
// เช่น META = Meta Platforms สหรัฐฯ vs META Corporation หุ้นไทย mai — เดาแล้วผิดมาแล้ว)
// ฝั่ง 🌏 มีปุ่มย่อย US/HK/JP อีกชั้น (ไม่เดา sub-market จาก mirror list — รหัสตัวเลข JP/HK ชนกัน)
// เลือกป้ายก่อนพิมพ์ · autocomplete + แหล่งข้อมูลอิงป้ายที่เลือกเสมอ พิมพ์ไม่ทำให้ป้ายสลับเอง
// ============================================================
let _finCmpMarket = { a: 'set', b: 'dr' };   // ค่าเริ่มต้น: A=ไทย, B=ต่างประเทศ (ตรงกับ placeholder)
let _finCmpDrMkt = { a: 'US', b: 'US' };     // sub-market ของฝั่ง 🌏 (ใช้เมื่อ _finCmpMarket[side]==='dr')
let _finCmpSeq = 0;                          // กัน response เก่าที่มาช้าทับผลใหม่ / กดเทียบซ้ำ
// 'q' = รายไตรมาส (ฝั่งไทยใช้ SET.or.th เป็นหลัก, DR ใช้ Finnomena) · 'y' = รายปี (ทั้งสองฝั่ง
// ใช้ Finnomena เสมอ — SET.or.th/Yahoo ไม่มี endpoint รายปีย้อนลึกพอสำหรับโหมดนี้)
let _finCmpPeriod = 'q';

function setFinCmpPeriod(period) {
  _finCmpPeriod = period;
  document.getElementById('fin-cmp-period-q')?.classList.toggle('active', period === 'q');
  document.getElementById('fin-cmp-period-y')?.classList.toggle('active', period === 'y');
  // แค่ตั้งค่าไว้ ไม่ re-render ตารางที่แสดงอยู่เอง (ต้องกด "เทียบ" ใหม่) — เตือนตอนนี้เฉพาะกรณีมี
  // ผลลัพธ์ค้างอยู่แล้วเท่านั้น กันผู้ใช้เข้าใจผิดว่าเป็น toggle แบบเปลี่ยนผลทันที
  const out = document.getElementById('fin-cmp-result');
  const hint = document.getElementById('fin-cmp-hint');
  if (hint && out && out.innerHTML.trim()) hint.textContent = 'เปลี่ยนช่วงเวลาแล้ว — กด "⚖️ เทียบ" อีกครั้งเพื่ออัพเดทตาราง';
}

function _finCmpIsDr(side) {
  return _finCmpMarket[side] === 'dr';
}

function _finCmpSyncMarketUI(side) {
  const isDr = _finCmpIsDr(side);
  document.getElementById(`fin-cmp-${side}-set`)?.classList.toggle('active', !isDr);
  document.getElementById(`fin-cmp-${side}-dr`)?.classList.toggle('active', isDr);
  // autocomplete ต้องเป็นรายชื่อของตลาดที่ป้ายนี้เลือกอยู่เท่านั้น — ใช้ datalist เดียวกับ
  // ช่องค้นหาหุ้นเดี่ยว (fin-set-datalist/fin-dr-datalist) ไม่ต้องโคลนซ้ำ
  document.getElementById(`fin-cmp-${side}`)?.setAttribute('list', isDr ? 'fin-dr-datalist' : 'fin-set-datalist');
  // ปุ่มย่อย US/HK/JP โผล่เฉพาะตอนเลือก 🌏 — ไม่เดา sub-market จาก mirror list อีกต่อไป
  const sub = document.getElementById(`fin-cmp-${side}-drmkt`);
  if (sub) {
    sub.style.display = isDr ? 'flex' : 'none';
    ['US', 'HK', 'JP'].forEach(mk => document.getElementById(`fin-cmp-${side}-mk-${mk}`)
      ?.classList.toggle('active', _finCmpDrMkt[side] === mk));
  }
}

function setFinCmpMarket(side, mkt) {
  _finCmpMarket[side] = mkt;
  _finCmpSyncMarketUI(side);
}

function setFinCmpDrMkt(side, mk) {
  _finCmpDrMkt[side] = mk;
  _finCmpSyncMarketUI(side);
}

function toggleFinCompare() {
  const panel = document.getElementById('fin-compare-panel');
  const opening = panel.style.display === 'none';
  panel.style.display = opening ? '' : 'none';
  document.getElementById('fin-compare-btn').classList.toggle('active', opening);
  // ซ่อนช่องค้นหาปกติ + ผลลัพธ์เดี่ยวตอนเปิดโหมดเทียบ กันสับสนว่ากำลังดูโหมดไหนอยู่
  const recent = document.getElementById('fin-recent');
  if (recent && opening) recent.style.display = 'none';   // ตอนปิด: _finRecentRender() ด้านล่างคืนแถวเอง
  if (!opening) _finCmpSeq++;   // ปิดโหมดเทียบ = ทิ้ง response ที่ยัง in-flight ไม่ให้เขียนลงพาเนลที่ซ่อนแล้ว
  ['fin-search-set', 'fin-search-dr', 'fin-result'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = opening ? 'none' : '';
  });
  if (!opening) {
    setFinTab(_finTab, document.getElementById(_finTab === 'set' ? 'fin-tab-set-btn' : 'fin-tab-dr-btn'));
    _finRecentRender();   // setFinTab->initFinPage เรียกอยู่แล้ว แต่ระบุชัดเจนกันพลาด
    // setFinTab ล้าง fin-result ทิ้งเสมอ (เผื่อกรณีสลับแท็บจริง) แต่ตรงนี้แท็บไม่ได้เปลี่ยน
    // (ปิดโหมดเทียบ = แท็บเดิมก่อนเปิด) — คืนผลค้นหุ้นเดี่ยวล่าสุดกลับมาแทนปล่อยว่างเปล่า
    if (_finData) _renderFinancialsFull(_finData, _finRenderSource);
    return;
  }
  initFinPage();   // ให้แน่ใจว่า fin-set-datalist/fin-dr-datalist โหลดแล้ว (ช่องเทียบชี้ไปใช้ตรงๆ)
  const runBtn = document.getElementById('fin-cmp-run-btn');
  if (runBtn) runBtn.disabled = false;   // เผื่อรอบก่อนปิดพาเนลตอนยัง in-flight (finally ไม่คืนปุ่มข้าม seq)
  _finCmpSyncMarketUI('a');
  _finCmpSyncMarketUI('b');
}

function _finGuessDrMarket(sym) {
  const mir = _finDrMirrorSyms || {};
  if ((mir.HK || []).includes(sym)) return 'HK';
  if ((mir.JP || []).includes(sym)) return 'JP';
  return 'US';
}

async function _finCompareFetch(sym, isDr, period, drMkt) {
  // drMkt = ตลาดที่ผู้ใช้เลือกตรงๆ จากปุ่ม US/HK/JP (fallback เป็นการเดาเดิมเฉพาะตอนไม่ได้ส่งมา)
  const market = isDr ? (drMkt || _finGuessDrMarket(sym)) : null;
  const base = `/api/financials-full/${encodeURIComponent(sym)}`;
  const qs = src => `?source=${src}${isDr ? '&is_dr=1' : ''}${market ? `&market=${market}` : ''}`;

  // โหมดรายปี: ใช้ Finnomena เสมอทั้งสองฝั่ง (ไม่แตะ /api/financials-compare ของฝั่งไทย เพราะ
  // เป็นรายไตรมาสล้วน — finnomena_y คำนวณจาก finnomena_q ได้ทั้งหุ้นไทยและ DR อยู่แล้ว)
  if (period === 'y') {
    let r = await _fetchTimeout(base + qs('finnomena_y'), 30000);
    let d = await r.json();
    d._srcLabel = 'Finnomena รายปี';
    if (d.error) {
      r = await _fetchTimeout(base + qs('yahoo'), 30000);
      d = await r.json();
      d._srcLabel = 'Yahoo Finance รายปี';
    }
    d._isDr = isDr;
    return d;
  }

  // หุ้นไทย (ไม่ใช่ DR): ใช้ SET.or.th เป็นหลักก่อนเสมอ (P&L รายไตรมาส + ROE/ROA/D-E จาก
  // company-highlight, เสริม valuation จาก Finnomena เฉพาะ 4 แถวที่ SET ไม่มี — ดู
  // /api/financials-compare ใน app.py) fallback ไป Finnomena/Yahoo แบบเดิมเฉพาะตอน SET
  // ไม่มีข้อมูลพอ (เช่น หุ้นเพิ่งเข้าตลาด) หรือ endpoint ล่ม
  if (!isDr) {
    try {
      const r = await _fetchTimeout(`/api/financials-compare/${encodeURIComponent(sym)}`, 30000);
      const d = await r.json();
      if (!d.error) { d._isDr = false; d._srcLabel = 'SET.or.th (+Finnomena เฉพาะ valuation)'; return d; }
    } catch (e) { /* เงียบไว้ — ตกไป fallback แหล่งเดิมด้านล่าง */ }
  }
  let r = await _fetchTimeout(base + qs('finnomena_q'), 30000);
  let d = await r.json();
  d._srcLabel = 'Finnomena รายไตรมาส';
  if (d.error) {
    r = await _fetchTimeout(base + qs('yahoo_q'), 30000);
    d = await r.json();
    d._srcLabel = 'Yahoo Finance รายไตรมาส';
  }
  d._isDr = isDr;
  return d;
}

function _finCmpMetric(label, valA, valB, fmt, higherBetter) {
  const numA = typeof valA === 'number' ? valA : null, numB = typeof valB === 'number' ? valB : null;
  let clsA = '', clsB = '';
  if (numA != null && numB != null && numA !== numB && higherBetter != null) {
    const aWins = higherBetter ? numA > numB : numA < numB;
    clsA = aWins ? 'color:var(--green);font-weight:700' : '';
    clsB = !aWins ? 'color:var(--green);font-weight:700' : '';
  }
  return `<tr>
    <td style="padding:6px 8px;color:var(--text2);font-size:11.5px">${label}</td>
    <td style="padding:6px 8px;text-align:right;${clsA}">${fmt(valA)}</td>
    <td style="padding:6px 8px;text-align:right;${clsB}">${fmt(valB)}</td>
  </tr>`;
}

function _finCmpSection(label) {
  return `<tr><td colspan="3" style="padding:10px 8px 4px;font-size:10.5px;font-weight:700;color:var(--accent);border-bottom:none">${label}</td></tr>`;
}

// อัตราเติบโตทบต้นต่อปี ปีแรกสุด -> ล่าสุดที่มีข้อมูล — ต้องห่างกัน >= 1.5 ปีถึงจะมีความหมาย
// (กันหุ้นที่เพิ่งมีข้อมูล 2-3 ไตรมาสได้ CAGR ที่ผันผวนเกินจริง)
function _finCagr(series) {
  if (series.length < 2) return null;
  const first = series[0], last = series[series.length - 1];
  if (first.v <= 0) return null;
  const years = (new Date(last.d) - new Date(first.d)) / (365.25 * 86400000);
  if (years < 1.5) return null;
  return (Math.pow(last.v / first.v, 1 / years) - 1) * 100;
}

// ดึง series ของ field หนึ่งจาก d.qpl ({date: rawRow}) — เหมือน _finSeries แต่ rawRow เป็น
// object ทั้งแถว (จาก compute_qpl_report) ไม่ใช่ dict {date:val} แบบ income/ratios ปกติ
// ไม่มี d.qpl เลย (เช่น DR ที่ fallback ไป finnomena_q/yahoo_q ตรงๆ ไม่ผ่าน compute_qpl_report)
// -> คืน [] เฉยๆ ให้กลุ่มแถวนั้นถูกกรองทิ้งอัตโนมัติใน _finCmpHistTable
function _qplFieldSeries(qpl, field) {
  if (!qpl) return [];
  return Object.entries(qpl).map(([d, row]) => ({ d, v: row[field] }))
    .filter(o => o.v != null && !isNaN(o.v)).sort((a, b) => a.d < b.d ? -1 : 1);
}

// ต้นทุนขาย = รายได้ − กำไรขั้นต้น ต่องวด — ใช้ fallback ตอนไม่มี qpl (COGS แยกเฉพาะจาก SET/Yahoo)
// แต่ Finnomena ดิบมีทั้งรายได้และกำไรขั้นต้นอยู่แล้ว คำนวณเองได้ไม่ต้องพึ่ง qpl
function _finDiffSeries(minuend, subtrahend) {
  const subMap = Object.fromEntries(subtrahend.map(o => [o.d, o.v]));
  return minuend.filter(o => subMap[o.d] != null)
    .map(o => ({ d: o.d, v: o.v - subMap[o.d] }));
}

function _finCmpQtrLabel(dateStr) {
  const y = parseInt(dateStr.slice(0, 4), 10), m = parseInt(dateStr.slice(5, 7), 10);
  return { yearBe: y + 543, q: Math.ceil(m / 3) };
}

function _finCmpYearLabel(dateStr) {
  return parseInt(dateStr.slice(0, 4), 10) + 543;
}

// ตารางเทียบย้อนหลังของหุ้นสองตัว — mode 'q' (คอลัมน์ = ปี พ.ศ. × Q1-Q4) หรือ 'y' (คอลัมน์ = ปี พ.ศ.)
// รวมโค้ดตารางรายไตรมาส/รายปีที่เดิมเกือบซ้ำกันทั้งดุ้นไว้ที่เดียว ต่างกันแค่การจัดกลุ่มคอลัมน์
// ── คีย์คอลัมน์เป็น "งวด" (ปี×10+ไตรมาส หรือ ปี พ.ศ.) ไม่ใช่วันที่ดิบ: หุ้นไทย/SET.or.th ใช้วัน
//    สิ้นงวดสังเคราะห์ 'YYYY-03-31/-06-30/...' ส่วน Yahoo (fallback ตอน Finnomena ไม่มี) ใช้วัน
//    สิ้นงวดจริง เช่น AAPL '2024-06-29' — ถ้า match ด้วยวันที่ตรงๆ ฝั่งที่วันไม่ตรงจะขึ้น '—' ทั้งแถว
// ── แถว % QoQ/% YoY: field ที่ "ยิ่งน้อยยิ่งดี" (ต้นทุน/ภาษี/หนี้ ฯลฯ — series entry มี invert:true)
//    ระบายสีกลับด้าน คือ เพิ่มขึ้น=แดง ลดลง=เขียว ให้ตรงกับตาราง snapshot ด้านล่าง
function _finCmpHistTable(symA, symB, COL_A, COL_B, series, scrollId, mode) {
  const isYr = mode === 'y';
  const colKeyOf = d => isYr ? _finCmpYearLabel(d)
    : (() => { const { yearBe, q } = _finCmpQtrLabel(d); return yearBe * 10 + q; })();

  const keySet = new Set();
  Object.values(series).forEach(({ a, b }) => {
    a.forEach(o => keySet.add(colKeyOf(o.d)));
    b.forEach(o => keySet.add(colKeyOf(o.d)));
  });
  if (!keySet.size) return '';

  // รายการคีย์คอลัมน์ที่จะ render: รายปี = เฉพาะปีที่มีข้อมูล · รายไตรมาส = ทุกปีที่โผล่ × Q1-Q4
  // ครบ (เก็บช่องไตรมาสที่ยังไม่มีข้อมูลไว้เป็น '—' เหมือนพฤติกรรมเดิม)
  let cols;
  if (isYr) {
    cols = [...keySet].sort((x, y) => x - y);
  } else {
    const yrs = [...new Set([...keySet].map(k => Math.floor(k / 10)))].sort((x, y) => x - y);
    cols = [];
    yrs.forEach(y => [1, 2, 3, 4].forEach(qn => cols.push(y * 10 + qn)));
  }

  // คอลัมน์ซ้ายสุด (ชื่อรายการ) ตรึงไว้ไม่ขยับตอนเลื่อนดูงวดเก่า/ใหม่ — ต้องมี background ทึบ
  // (ไม่โปร่งใสแบบเซลล์อื่น) ไม่งั้นข้อมูลคอลัมน์ที่เลื่อนผ่านจะทะลุให้เห็นข้างหลัง
  const stickyCol = 'position:sticky;left:0;z-index:1;background:var(--bg2)';
  const row = (label, color, map, fmt, opts = {}) => `<tr>
    <td style="${stickyCol};padding:${opts.indent ? '3px 8px 3px 22px' : '5px 8px'};border:1px solid var(--border);font-size:${opts.indent ? '10.5px' : '12px'};white-space:nowrap${opts.indent ? ';color:var(--text2)' : ''}">
      ${opts.indent ? '' : `<span style="width:8px;height:8px;border-radius:50%;background:${color};display:inline-block;margin-right:5px"></span>`}${label}
    </td>
    ${cols.map(k => {
      const v = map[k];
      const cellColor = opts.pctColor && v != null
        ? (v > 0 ? (opts.invert ? 'var(--red)' : 'var(--green)') : v < 0 ? (opts.invert ? 'var(--green)' : 'var(--red)') : 'var(--text2)')
        : (opts.indent ? 'var(--text2)' : '');
      return `<td class="r" style="padding:${opts.indent ? '3px 6px' : '4px 6px'};border:1px solid var(--border);font-size:${opts.indent ? '10.5px' : '11.5px'}${cellColor ? `;color:${cellColor}` : ''}">${v != null ? fmt(v) : '—'}</td>`;
    }).join('')}
  </tr>`;

  // ตัว <td> ของหัวกลุ่ม colspan กว้างเต็มแถวอยู่แล้ว (ไม่ได้เลื่อนหลุดจอ) แต่ "ข้อความ" ข้างในจะ
  // เลื่อนตามไปด้วยถ้าไม่ทำอะไรเพิ่ม — ต้องห่อข้อความด้วย <div> sticky แยกอีกชั้น ข้อความถึงจะ
  // ลอยค้างที่ขอบซ้ายตามจอเหมือนคอลัมน์ชื่อรายการด้านล่าง
  const groupHdr = label => `<tr><td colspan="${1 + cols.length}" style="font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:var(--blue);background:var(--card2);border:1px solid var(--border);padding:0"><div style="position:sticky;left:0;width:max-content;padding:6px 8px">${label}</div></td></tr>`;

  const toMap = s => Object.fromEntries(s.map(o => [colKeyOf(o.d), o.v]));
  const fmtPP = v => v == null ? '—' : (v >= 0 ? '+' : '') + v.toFixed(2) + 'pp';
  // % เทียบ "งวดก่อนหน้าจริงในอนุกรมของหุ้นตัวเอง" (s[i-1]) ไม่ใช่ช่องตารางก่อนหน้า เพราะคอลัมน์
  // เป็น union ของงวดทั้งสองฝั่ง อาจมีช่องว่างปนอยู่ · field ที่เป็น % อยู่แล้ว (GPM/NPM) ใช้
  // "ผลต่างจุดเปอร์เซ็นต์ (pp)" แทน % growth ซ้อน %
  const growthMap = (s, isPctField) => {
    const out = {};
    for (let i = 1; i < s.length; i++) {
      const cur = s[i].v, prev = s[i - 1].v;
      if (cur == null || prev == null) continue;
      out[colKeyOf(s[i].d)] = isPctField ? (cur - prev) : (prev > 0 ? (cur / prev - 1) * 100 : null);
    }
    return out;
  };
  const growLabel = isYr ? '% YoY' : '% QoQ';

  // thead: รายไตรมาส = 2 แถว (ปี colspan 4 + Q1-Q4), รายปี = แถวเดียว (ปี พ.ศ.)
  let theadRows;
  if (isYr) {
    theadRows = `<tr><th style="${stickyCol};z-index:2;border:1px solid var(--border)"></th>` +
      cols.map(y => `<th style="text-align:center;background:#8b2fc9;color:#fff;padding:6px 4px;border:1px solid var(--border);font-size:11px">${y}</th>`).join('') + `</tr>`;
  } else {
    const yrs = [...new Set(cols.map(k => Math.floor(k / 10)))];
    theadRows =
      `<tr><th style="${stickyCol};z-index:2;border:1px solid var(--border)"></th>` +
      yrs.map(y => `<th colspan="4" style="text-align:center;background:#8b2fc9;color:#fff;padding:6px 4px;border:1px solid var(--border)">${y}</th>`).join('') + `</tr>` +
      `<tr><th style="${stickyCol};z-index:2;border:1px solid var(--border)"></th>` +
      yrs.map(() => [1, 2, 3, 4].map(qn => `<th style="text-align:center;background:#c93fd6;color:#fff;padding:4px;border:1px solid var(--border);font-size:11px">Q${qn}</th>`).join('')).join('') + `</tr>`;
  }

  // กรองกลุ่มที่ไม่มีข้อมูลทั้งสองฝั่งทิ้ง — เช่นฝั่ง DR ที่ fallback ไป finnomena_q/yahoo_q ตรงๆ
  // จะไม่มี breakdown COGS/SG&A แยก/ต้นทุนการเงิน/ภาษี เลย (ไม่ผ่าน compute_qpl_report) กันแถวโล่ง
  const rowsHtml = Object.entries(series).filter(([, { a, b }]) => a.length || b.length)
    .map(([label, { a, b, fmt, isPctField, invert }]) => {
      const gFmt = isPctField ? fmtPP : _finPct;
      const gOpts = { indent: true, pctColor: true, invert: !!invert };
      return groupHdr(label)
        + row(symA, COL_A, toMap(a), fmt)
        + row(growLabel, COL_A, growthMap(a, isPctField), gFmt, gOpts)
        + row(symB, COL_B, toMap(b), fmt)
        + row(growLabel, COL_B, growthMap(b, isPctField), gFmt, gOpts);
    }).join('');
  if (!rowsHtml) return '';

  return `
    <div style="font-size:11px;color:var(--accent);font-weight:600;margin:0 0 4px">📅 เทียบ${isYr ? 'รายปี' : 'รายไตรมาส'}ย้อนหลัง (ตัวเลขจริง — เลื่อนซ้ายเพื่อดูงวดเก่ากว่า)</div>
    <div id="${scrollId}" style="overflow-x:auto">
      <table class="tbl" style="border-collapse:collapse;min-width:600px">
        <thead>${theadRows}</thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>`;
}

function _renderFinCompare(symA, dA, symB, dB, period) {
  const incA = dA.income || {}, ratA = dA.ratios || {}, valA = dA.valuation || {};
  const incB = dB.income || {}, ratB = dB.ratios || {}, valB = dB.valuation || {};
  const revA = _finSeries(incA['Total Revenue'] || incA['Operating Revenue']);
  const revB = _finSeries(incB['Total Revenue'] || incB['Operating Revenue']);
  const niA = _finSeries(incA['Net Income'] || incA['Net Income Common Stockholders']);
  const niB = _finSeries(incB['Net Income'] || incB['Net Income Common Stockholders']);
  const marginA = _finSeries(ratA['Net Margin']), marginB = _finSeries(ratB['Net Margin']);
  const gpmA = _finSeries(ratA['Gross Margin']), gpmB = _finSeries(ratB['Gross Margin']);
  const roeA = _finSeries(ratA['ROE']), roeB = _finSeries(ratB['ROE']);
  const roaA = _finSeries(ratA['ROA']), roaB = _finSeries(ratB['ROA']);
  const deA = _finSeries(ratA['Debt To Equity']), deB = _finSeries(ratB['Debt To Equity']);
  const mcapA = _finSeries(valA['Market Cap']), mcapB = _finSeries(valB['Market Cap']);
  const pbvA = _finSeries(valA['PBV']), pbvB = _finSeries(valB['PBV']);
  const dyA = _finSeries(valA['Dividend Yield']), dyB = _finSeries(valB['Dividend Yield']);
  // P/E ใช้ TTM ที่คำนวณเองจาก Basic EPS (ไม่ใช่ field 'PE' ดิบของ Finnomena ที่เคยเจอค่าเพี้ยน
  // เช่น 655x — ดู _ttmPeSeries) แม่นกว่าและตรงกับที่หน้าค้นหาหุ้นเดี่ยวใช้อยู่แล้ว — ตัดค่าที่เกิน
  // เพดานสมเหตุสมผลทิ้ง (ไตรมาสที่ TTM EPS ใกล้ 0 ทำให้ Close÷EPS ระเบิดเป็นพันๆ เท่า แล้วโดน
  // ไฮไลท์เขียวว่า "ถูกกว่า" — เกณฑ์เดียวกับ _annualPeSeries)
  const PE_CMP_MAX = 1000;
  const peA = _ttmPeSeries(incA['Basic EPS'], valA['Close']).filter(o => o.v > 0 && o.v <= PE_CMP_MAX);
  const peB = _ttmPeSeries(incB['Basic EPS'], valB['Close']).filter(o => o.v > 0 && o.v <= PE_CMP_MAX);
  const COL_A = '#58a6ff', COL_B = '#e8a33d';

  // บรรทัดแยกย่อยของงบกำไรขาดทุนรายไตรมาส (COGS/SG&A แยกขาย-บริหาร/กำไรดำเนินงาน/ต้นทุนการเงิน/
  // กำไรก่อนภาษี/ภาษี) — มีเฉพาะฝั่งที่ผ่าน /api/financials-compare (คีย์ 'qpl', หุ้นไทยที่ SET
  // มีข้อมูล) ฝั่ง DR ที่ fallback ไป finnomena_q/yahoo_q ตรงๆ หรือโหมดรายปี (finnomena_y เสมอ
  // ทั้งสองฝั่ง) จะไม่มี d.qpl เลย (_qplFieldSeries คืน [] ให้เอง)
  const qplA = dA.qpl || null, qplB = dB.qpl || null;
  // กำไรขั้นต้น/รวม SG&A: Finnomena ดิบมีให้ตรงๆ อยู่แล้ว (ใช้ตอน qpl ไม่มี) — ส่วนต้นทุนขาย
  // ไม่มี field ตรงๆ แต่คำนวณได้จาก รายได้ − กำไรขั้นต้น (ดู _finDiffSeries) เฉพาะ 3 รายการนี้
  // เท่านั้นที่มี fallback ได้ ที่เหลือ (แยกขาย-บริหาร/กำไรดำเนินงาน/ต้นทุนการเงิน/ก่อนภาษี/ภาษี)
  // ไม่มีใน Finnomena เลย ต้องพึ่ง qpl (SET/Yahoo) อย่างเดียว — ไม่มีก็แสดง '—' ไปตามเดิม
  const gpFallbackA = _finSeries(incA['Gross Profit']), gpFallbackB = _finSeries(incB['Gross Profit']);
  const sgaFallbackA = _finSeries(incA['Selling General And Administration']),
        sgaFallbackB = _finSeries(incB['Selling General And Administration']);
  const qplGpA = _qplFieldSeries(qplA, 'gross_profit'), qplGpB = _qplFieldSeries(qplB, 'gross_profit');
  const gpA = qplGpA.length ? qplGpA : gpFallbackA, gpB = qplGpB.length ? qplGpB : gpFallbackB;
  const qplCogsA = _qplFieldSeries(qplA, 'cogs'), qplCogsB = _qplFieldSeries(qplB, 'cogs');
  const cogsA = qplCogsA.length ? qplCogsA : _finDiffSeries(revA, gpA);
  const cogsB = qplCogsB.length ? qplCogsB : _finDiffSeries(revB, gpB);
  const sellA = _qplFieldSeries(qplA, 'selling_exp'), sellB = _qplFieldSeries(qplB, 'selling_exp');
  const adminA = _qplFieldSeries(qplA, 'admin_exp'), adminB = _qplFieldSeries(qplB, 'admin_exp');
  const qplSgaA = _qplFieldSeries(qplA, 'sga_total'), qplSgaB = _qplFieldSeries(qplB, 'sga_total');
  const sgaA = qplSgaA.length ? qplSgaA : sgaFallbackA, sgaB = qplSgaB.length ? qplSgaB : sgaFallbackB;
  const opA = _qplFieldSeries(qplA, 'operating_profit'), opB = _qplFieldSeries(qplB, 'operating_profit');
  const finCostA = _qplFieldSeries(qplA, 'financial_cost'), finCostB = _qplFieldSeries(qplB, 'financial_cost');
  const pretaxA = _qplFieldSeries(qplA, 'pretax_profit'), pretaxB = _qplFieldSeries(qplB, 'pretax_profit');
  const taxA = _qplFieldSeries(qplA, 'tax_expense'), taxB = _qplFieldSeries(qplB, 'tax_expense');
  // อัตราส่วนสำเร็จรูปจาก Finnomena (ratios) — มีครบทุกงวดเสมอไม่ว่าจะ qpl หรือไม่ (คนละแหล่งกับ
  // breakdown งบกำไรขาดทุนด้านบน) SGA To Revenue/Cash Cycle ไม่เคยถูกใช้ในตารางเทียบมาก่อน
  const sgaRevA = _finSeries(ratA['SGA To Revenue']), sgaRevB = _finSeries(ratB['SGA To Revenue']);
  const cashCycleA = _finSeries(ratA['Cash Cycle']), cashCycleB = _finSeries(ratB['Cash Cycle']);

  const isYear = period === 'y';
  // YoY ของ snapshot ด้านล่าง: รายไตรมาสเทียบ 4 ไตรมาสก่อนหน้า (index -5), รายปีเทียบปีก่อนหน้า
  // ตรงๆ (index -2) — คนละ offset เพราะ series มีความถี่ต่างกัน
  const lastYoy = (s) => {
    if (isYear) {
      if (s.length < 2) return null;
      const last = s[s.length - 1].v, prior = s[s.length - 2].v;
      return prior > 0 ? (last / prior - 1) * 100 : null;
    }
    if (s.length < 5) return null;
    const last = s[s.length - 1].v, prior = s[s.length - 5].v;
    return prior > 0 ? (last / prior - 1) * 100 : null;
  };
  const last = s => s.length ? s[s.length - 1].v : null;
  const fmtPct = v => v == null ? '—' : _finPct(v);
  const fmtNum = v => v == null ? '—' : _finFmt(v);
  const fmtX = v => v == null ? '—' : v.toFixed(2) + 'x';
  const fmtDays = v => v == null ? '—' : v.toFixed(1) + ' วัน';
  const periodLabel = isYear ? 'ปีล่าสุด' : 'ไตรมาสล่าสุด';

  const nameA = _escHtml((dA.name && dA.name !== symA) ? dA.name : symA);
  const nameB = _escHtml((dB.name && dB.name !== symB) ? dB.name : symB);
  const esA = _escHtml(symA), esB = _escHtml(symB);   // symbol มาจากช่องกรอก (uppercase อย่างเดียว) — escape ก่อนฝัง HTML
  const srcLabelA = dA._srcLabel || 'Finnomena รายไตรมาส', srcLabelB = dB._srcLabel || 'Finnomena รายไตรมาส';
  const srcNote = srcLabelA === srcLabelB ? srcLabelA : `${esA}: ${srcLabelA} · ${esB}: ${srcLabelB}`;

  // invert:true = รายการ "ยิ่งน้อยยิ่งดี" (ต้นทุน/ภาษี/หนี้/วงจรเงินสด) — แถว %QoQ/%YoY ระบายสีกลับด้าน
  // ให้ตรงกับ FIN_INVERT_KEYS / _finColCls ที่ตาราง snapshot ด้านล่างใช้ (เดิมเขียวเมื่อบวกทุกแถว
  // ทำให้ต้นทุน/หนี้ที่พุ่งขึ้นดูเป็นสีเขียว = "ดี")
  const periodSeries = {
    'รายได้': { a: revA, b: revB, fmt: fmtNum },
    'ต้นทุนขาย': { a: cogsA, b: cogsB, fmt: fmtNum, invert: true },
    'กำไรขั้นต้น': { a: gpA, b: gpB, fmt: fmtNum },
    'Gross Margin %': { a: gpmA, b: gpmB, fmt: fmtPct, isPctField: true },
    'ค่าใช้จ่ายในการขาย': { a: sellA, b: sellB, fmt: fmtNum, invert: true },
    'ค่าใช้จ่ายในการบริหาร': { a: adminA, b: adminB, fmt: fmtNum, invert: true },
    'รวม SG&A': { a: sgaA, b: sgaB, fmt: fmtNum, invert: true },
    'กำไรจากการดำเนินงาน': { a: opA, b: opB, fmt: fmtNum },
    'ต้นทุนทางการเงิน': { a: finCostA, b: finCostB, fmt: fmtNum, invert: true },
    'กำไรก่อนภาษี': { a: pretaxA, b: pretaxB, fmt: fmtNum },
    'ค่าใช้จ่ายภาษีเงินได้': { a: taxA, b: taxB, fmt: fmtNum, invert: true },
    'กำไรสุทธิ': { a: niA, b: niB, fmt: fmtNum },
    'Net Margin %': { a: marginA, b: marginB, fmt: fmtPct, isPctField: true },
    // อัตราส่วนสำเร็จรูปจาก Finnomena — ROE/ROA มีอยู่แล้วในตาราง snapshot (ค่าล่าสุด) แต่ที่นี่
    // เห็นย้อนหลังทุกงวดพร้อม %QoQ/%YoY เหมือน field อื่นในตารางนี้
    'ROE %': { a: roeA, b: roeB, fmt: fmtPct, isPctField: true },
    'ROA %': { a: roaA, b: roaB, fmt: fmtPct, isPctField: true },
    'Debt to Equity': { a: deA, b: deB, fmt: fmtX, invert: true },
    'SGA to Revenue %': { a: sgaRevA, b: sgaRevB, fmt: fmtPct, isPctField: true, invert: true },
    'Cash Cycle': { a: cashCycleA, b: cashCycleB, fmt: fmtDays, invert: true },
  };
  // CAGR รายได้: โหมดรายไตรมาส ใช้ผลรวม TTM (4 ไตรมาสต่อเนื่อง) เป็นจุดหัว-ท้าย ไม่ใช่ไตรมาสเดี่ยว
  // (ไตรมาสแรกที่เป็น Q1 เทียบไตรมาสท้ายที่เป็น Q4 มีความต่างฤดูกาลปน ทำให้ annualized เพี้ยน และ
  // หุ้นสองตัวมักเริ่ม/จบคนละไตรมาส ทำให้ไฮไลท์ "ผู้ชนะ CAGR" ไม่น่าเชื่อถือ)
  const ttm4 = arr => {
    if (arr.length < 4) return [];
    const o = [];
    for (let i = 3; i < arr.length; i++) o.push({ d: arr[i].d, v: arr[i - 3].v + arr[i - 2].v + arr[i - 1].v + arr[i].v });
    return o;
  };
  const cagrRevA = isYear ? revA : ttm4(revA), cagrRevB = isYear ? revB : ttm4(revB);
  // ตารางเทียบย้อนหลังอยู่บนสุดตามที่ user ขอ (เห็นตัวเลขจริงก่อนสรุป snapshot ด้านล่าง) — โหมด
  // รายไตรมาสจัดกลุ่มคอลัมน์เป็นปี×Q1-Q4, โหมดรายปีคอลัมน์ = ปีตรงๆ (ดู _finCmpHistTable)
  const html = `
  ${_finCmpHistTable(esA, esB, COL_A, COL_B, periodSeries, isYear ? 'fin-cmp-yr-scroll' : 'fin-cmp-qtr-scroll', isYear ? 'y' : 'q')}
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0 14px">
    <div style="padding:8px 12px;border-radius:8px;background:${COL_A}18;border:1px solid ${COL_A}55">
      <span style="width:10px;height:10px;border-radius:50%;background:${COL_A};display:inline-block;margin-right:6px"></span>
      <b>${esA}</b> <span style="color:var(--text2);font-size:12px">${nameA}</span>
    </div>
    <div style="padding:8px 12px;border-radius:8px;background:${COL_B}18;border:1px solid ${COL_B}55">
      <span style="width:10px;height:10px;border-radius:50%;background:${COL_B};display:inline-block;margin-right:6px"></span>
      <b>${esB}</b> <span style="color:var(--text2);font-size:12px">${nameB}</span>
    </div>
  </div>
  <table class="tbl" style="width:100%">
    <thead><tr>
      <th style="padding:6px 8px"></th>
      <th style="padding:6px 8px;text-align:right;color:${COL_A}">${esA}</th>
      <th style="padding:6px 8px;text-align:right;color:${COL_B}">${esB}</th>
    </tr></thead>
    <tbody>
      ${_finCmpSection('📈 ขนาด/การเติบโต')}
      ${_finCmpMetric('Market Cap', last(mcapA), last(mcapB), fmtNum, null)}
      ${_finCmpMetric(`รายได้${periodLabel}`, last(revA), last(revB), fmtNum, null)}
      ${_finCmpMetric(`รายได้ YoY (${periodLabel})`, lastYoy(revA), lastYoy(revB), fmtPct, true)}
      ${_finCmpMetric('CAGR รายได้ (เต็มช่วงข้อมูล)', _finCagr(cagrRevA), _finCagr(cagrRevB), fmtPct, true)}
      ${_finCmpMetric(`กำไรสุทธิ${periodLabel}`, last(niA), last(niB), fmtNum, null)}
      ${_finCmpMetric(`กำไรสุทธิ YoY (${periodLabel})`, lastYoy(niA), lastYoy(niB), fmtPct, true)}
      ${_finCmpSection('💎 คุณภาพ')}
      ${_finCmpMetric('Gross Margin ล่าสุด', last(gpmA), last(gpmB), fmtPct, true)}
      ${_finCmpMetric('Net Margin ล่าสุด', last(marginA), last(marginB), fmtPct, true)}
      ${_finCmpMetric('ROE ล่าสุด', last(roeA), last(roeB), fmtPct, true)}
      ${_finCmpMetric('ROA ล่าสุด', last(roaA), last(roaB), fmtPct, true)}
      ${_finCmpSection('⚠️ ความเสี่ยง/มูลค่า')}
      ${_finCmpMetric('Debt to Equity ล่าสุด', last(deA), last(deB), fmtX, false)}
      ${_finCmpMetric('P/E (TTM)', last(peA), last(peB), fmtX, false)}
      ${_finCmpMetric('P/BV ล่าสุด', last(pbvA), last(pbvB), fmtX, false)}
      ${_finCmpMetric('Dividend Yield ล่าสุด', last(dyA), last(dyB), fmtPct, true)}
    </tbody>
  </table>
  <div style="font-size:10.5px;color:var(--text2);margin-top:8px">ข้อมูลจาก ${srcNote} · สีเขียว = ฝั่งที่ดีกว่าในแถวนั้น (P/E, P/BV, D/E ยิ่งต่ำยิ่งเขียว — แต่ถูกไม่ได้แปลว่าน่าลงทุนกว่าเสมอ ต้องดูเหตุผลประกอบ) · Market Cap/รายได้/กำไร ไม่ไฮไลท์สีเพราะขนาดต่างกันเทียบตรงๆ ไม่มีความหมาย</div>`;

  // ต้องเลื่อนตาราง qpl ไปสุดขวา "หลัง" innerHTML ถูกแทรกเข้า DOM จริงแล้วเท่านั้น (ต้องมี
  // element จริงให้วัด scrollWidth) — caller เรียก afterInsert() เองหลังจาก out.innerHTML = result.html
  const afterInsert = () => {
    _qplScrollToLatest(isYear ? 'fin-cmp-yr-scroll' : 'fin-cmp-qtr-scroll');
  };
  return { html, afterInsert };
}

async function runFinCompare() {
  const symA = (document.getElementById('fin-cmp-a').value || '').trim().toUpperCase();
  const symB = (document.getElementById('fin-cmp-b').value || '').trim().toUpperCase();
  const hint = document.getElementById('fin-cmp-hint');
  const out = document.getElementById('fin-cmp-result');
  if (!symA || !symB) { hint.textContent = 'กรอกหุ้นทั้งสองฝั่งก่อน'; return; }
  const isDrA = _finCmpIsDr('a'), isDrB = _finCmpIsDr('b');
  const mkA = isDrA ? _finCmpDrMkt.a : null, mkB = isDrB ? _finCmpDrMkt.b : null;
  const period = _finCmpPeriod;
  const seq = ++_finCmpSeq;   // กดเทียบซ้ำ/ปิดพาเนล → response รอบก่อนที่มาช้ากว่าจะถูกทิ้ง
  const btn = document.getElementById('fin-cmp-run-btn');
  if (btn) btn.disabled = true;
  hint.textContent = 'กำลังโหลด...';
  out.innerHTML = '';
  try {
    const [dA, dB] = await Promise.all([_finCompareFetch(symA, isDrA, period, mkA), _finCompareFetch(symB, isDrB, period, mkB)]);
    if (seq !== _finCmpSeq) return;
    if (dA.error) throw new Error(`${symA}: ${dA.error}`);
    if (dB.error) throw new Error(`${symB}: ${dB.error}`);
    hint.textContent = '';
    const result = _renderFinCompare(symA, dA, symB, dB, period);
    out.innerHTML = result.html;
    result.afterInsert();
  } catch (e) {
    if (seq !== _finCmpSeq) return;
    hint.textContent = '';
    out.innerHTML = `<div class="empty" style="padding:20px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  } finally {
    if (seq === _finCmpSeq && btn) btn.disabled = false;
  }
}

function resetFinCompare() {
  document.getElementById('fin-cmp-a').value = '';
  document.getElementById('fin-cmp-b').value = '';
  document.getElementById('fin-cmp-hint').textContent = '';
  document.getElementById('fin-cmp-result').innerHTML = '';
  _finCmpMarket = { a: 'set', b: 'dr' };
  _finCmpDrMkt = { a: 'US', b: 'US' };
  _finCmpSeq++;   // ทิ้ง response ที่ยัง in-flight
  const runBtn = document.getElementById('fin-cmp-run-btn');
  if (runBtn) runBtn.disabled = false;
  _finCmpSyncMarketUI('a');
  _finCmpSyncMarketUI('b');
  setFinCmpPeriod('q');
  document.getElementById('fin-cmp-a').focus();
}

// URL hash deep-link: #fin/set/PTT หรือ #fin/dr/NVDA — เปิดหน้างบการเงินพร้อมค้นหาหุ้นทันที
// รองรับ refresh/back-forward/แชร์ลิงก์ (เดิมไม่มี hash routing เลย รีเฟรชแล้วหลุดกลับหน้าแรกทุกครั้ง)
// รูปแบบ #fin/dr/HK:0700 (มี prefix ตลาด) ใช้ตอนเปิดเป็นแท็บใหม่จาก Heatmap HK/JP —
// แท็บใหม่ไม่ได้สืบทอด _finMirMarket จากแท็บเดิม ถ้าไม่พกตลาดมาด้วยจะเดา yf ticker ผิด
function _finApplyHash() {
  // เว็บ static (มือถือ/ไอแพด GitHub Pages) ไม่มีหน้านี้เลย (ปุ่ม nav ถูกซ่อนไว้ด้วย
  // CSS .static-mode) แต่ hash deep-link นี้เรียก showPage() ตรงๆ ข้าม CSS guard ได้
  // — ถ้าไม่กันไว้ตรงนี้ hash เก่า/แชร์ลิงก์มา/แท็บที่เบราว์เซอร์ restore จะเปิดหน้าที่
  // ควรถูกซ่อนแล้วเจอ error แทน
  if (IS_STATIC) return;
  const m = location.hash.match(/^#fin\/(set|dr)\/(?:(US|HK|JP):)?([^/]+)$/);
  if (!m) return;
  const [, tab, mkt, symRaw] = m;
  const sym = decodeURIComponent(symRaw).toUpperCase();
  showPage('financials', document.querySelector('.nav-btn[onclick*="financials"]'));
  if (mkt) _finMirSelectMarket(mkt);
  setFinTab(tab, document.getElementById(tab === 'set' ? 'fin-tab-set-btn' : 'fin-tab-dr-btn'));
  const inp = document.getElementById(tab === 'set' ? 'fin-sym-set' : 'fin-sym-dr');
  if (inp) inp.value = sym;
  searchFinancials();
}
window.addEventListener('hashchange', _finApplyHash);
window.addEventListener('DOMContentLoaded', () => { if (location.hash.startsWith('#fin/')) _finApplyHash(); });

// URL hash deep-link: #ts/us/AAPL — เปิดหน้า Tearsheet พร้อมโหลดหุ้นทันที (ใช้โดยปุ่ม
// "เปิดแท็บใหม่" เช่น hedgeOpenTearsheet ใน Hedge Holdings) เหมือน #fin/ ด้านบน
function _tsApplyHash() {
  // ดูคอมเมนต์เดียวกันใน _finApplyHash — หน้า Tearsheet ก็ถูกซ่อนด้วย .static-mode เช่นกัน
  if (IS_STATIC) return;
  const m = location.hash.match(/^#ts\/(th|us|hk|jp)\/([^/]+)$/);
  if (!m) return;
  const [, mktRaw, symRaw] = m;
  const mkt = mktRaw.toUpperCase();
  const sym = decodeURIComponent(symRaw).toUpperCase();
  showPage('tearsheet', document.querySelector('.nav-btn[onclick*="tearsheet"]'));
  setTsMarket(mkt, document.getElementById('ts-tab-' + mktRaw));
  loadTearsheet(sym, mkt);
}
window.addEventListener('hashchange', _tsApplyHash);
window.addEventListener('DOMContentLoaded', () => { if (location.hash.startsWith('#ts/')) _tsApplyHash(); });

// URL hash deep-link: #peer/us/AAPL — เปิดหน้า "เทียบเพื่อน" พร้อมโหลดกลุ่มของหุ้นนั้นทันที
// (ใช้โดยปุ่มเทียบเพื่อนต่าง ๆ เมื่อผู้ใช้เลือกโหมด "🗗 แท็บใหม่") เหมือน #ts/ ด้านบน
// หมายเหตุ: หุ้น DR ต้องส่ง market='DR' ให้ backend resolve underlying จึงไม่ผ่าน route นี้
function _peerApplyHash() {
  // ดูคอมเมนต์เดียวกันใน _finApplyHash — หน้าเทียบเพื่อนก็ถูกซ่อนด้วย .static-mode เช่นกัน
  if (IS_STATIC) return;
  const m = location.hash.match(/^#peer\/(th|us|hk|jp)\/([^/]+)$/);
  if (!m) return;
  const [, mktRaw, symRaw] = m;
  const mkt = mktRaw.toUpperCase();
  const sym = decodeURIComponent(symRaw).toUpperCase();
  showPage('peer', document.querySelector('.nav-btn[onclick*="peer"]'));
  setPeerMarket(mkt, document.getElementById('peer-tab-' + mktRaw));
  loadPeerCompare(sym, mkt);
}
window.addEventListener('hashchange', _peerApplyHash);
window.addEventListener('DOMContentLoaded', () => { if (location.hash.startsWith('#peer/')) _peerApplyHash(); });

// URL hash deep-link: #stock/us/AAPL — เปิดหน้าหุ้น US/HK/JP แล้วเด้ง popup รายละเอียด
// (chart-modal) ให้เองทันที (ใช้โดยปุ่ม "เปิดแท็บใหม่" เช่น hedgeOpenDetail ใน Hedge
// Holdings — หุ้นจาก Dataroma เป็น US เท่านั้นตอนนี้ จึงยังไม่มีที่เรียก jp/ จริง แต่รองรับ
// ไว้ให้ครบเผื่อจุดเรียกอื่นในอนาคต ไม่มี th เพราะหน้าหุ้นไทยไม่ได้ผูกกับ pageId นี้)
async function _stockApplyHash() {
  // ดูคอมเมนต์เดียวกันใน _finApplyHash — หน้าหุ้น US/HK/JP ก็ถูกซ่อนด้วย .static-mode เช่นกัน
  // (/api/us-index-metrics, /api/hk-index-metrics, /api/jp-index-metrics ไม่ได้ bake ไว้เลย)
  if (IS_STATIC) return;
  const m = location.hash.match(/^#stock\/(us|hk|jp)\/([^/]+)$/);
  if (!m) return;
  const [, mktRaw, symRaw] = m;
  const sym = decodeURIComponent(symRaw).toUpperCase();
  // เช็ค/โหลด _usData|_hkData|_jpData ให้เสร็จก่อนเรียก showPage เสมอ — ถ้าโหลดทีหลัง
  // showPage จะไปเรียก loadUsStocksPage/loadHkStocksPage/loadJpStocksPage ที่ยิง fetch
  // เส้นเดียวกันซ้ำอีกรอบ (เพราะตอนนั้น _usData/_hkData/_jpData ยังว่างอยู่)
  const pageId = mktRaw === 'us' ? 'us-stocks' : mktRaw === 'hk' ? 'hk-stocks' : 'jp-stocks';
  if (mktRaw === 'us') {
    if (!_usData) {
      // เช็ค d.error/d.stocks ก่อนเก็บ — ถ้า server ตอบ error object (เช่นยังไม่เคยกด
      // US Index Max) แล้วเก็บดื้อๆ renderUsTable จะ crash เพราะ _usData.stocks undefined
      try {
        const d = await (await fetch('/api/us-index-metrics')).json();
        if (!d.error && d.stocks && d.stocks.length) _usData = d;
      } catch (e) { /* เช็ค found ใน openUsChartModal จะแจ้งเตือนเอง */ }
      if (_usData) _rebuildUsSectorFilter();   // เดิม path ปกติ (loadUsStocksPage) เรียกอยู่แล้ว
                                                // แต่ deep-link เซ็ต _usData เองข้าม path นั้น
                                                // ทำให้ dropdown Sector ค้างว่างจนกว่าจะสลับดัชนี
    }
    showPage(pageId, document.querySelector(`.nav-btn[onclick*="${pageId}"]`));
    openUsChartModal(sym);
  } else if (mktRaw === 'hk') {
    const hkSym = sym.endsWith('.HK') ? sym : `${sym}.HK`;
    if (!_hkData) {
      try {
        const d = await (await fetch('/api/hk-index-metrics')).json();
        if (!d.error && d.stocks && d.stocks.length) _hkData = d;
      } catch (e) { /* เช็ค found ใน openHkChartModal จะแจ้งเตือนเอง */ }
      if (_hkData) _rebuildHkSectorFilter();   // เหตุผลเดียวกับฝั่ง US ด้านบน
    }
    showPage(pageId, document.querySelector(`.nav-btn[onclick*="${pageId}"]`));
    openHkChartModal(hkSym);
  } else {
    const jpSym = sym.endsWith('.T') ? sym : `${sym}.T`;
    if (!_jpData) {
      try {
        const d = await (await fetch('/api/jp-index-metrics')).json();
        if (!d.error && d.stocks && d.stocks.length) _jpData = d;
      } catch (e) { /* เช็ค found ใน openJpChartModal จะแจ้งเตือนเอง */ }
      if (_jpData) _rebuildJpSectorFilter();   // เหตุผลเดียวกับฝั่ง US/HK ด้านบน
    }
    showPage(pageId, document.querySelector(`.nav-btn[onclick*="${pageId}"]`));
    openJpChartModal(jpSym);
  }
}
window.addEventListener('hashchange', _stockApplyHash);
window.addEventListener('DOMContentLoaded', () => { if (location.hash.startsWith('#stock/')) _stockApplyHash(); });

function initFinPage() {
  _finRecentRender();
  // populate SET datalist once DATA is ready
  const dl = document.getElementById('fin-set-datalist');
  if (dl && DATA && !dl.childElementCount) {
    DATA.stocks.forEach(s => {
      const o = document.createElement('option');
      o.value = s.symbol; o.label = s.name;
      dl.appendChild(o);
    });
  }
  // populate DR datalist — rebuild เมื่อจำนวน universe เปลี่ยน (เดิมเติมครั้งเดียว
  // แล้วล็อกถาวร ทำให้ underlying ใหม่จาก auto-sync ไม่โผล่ใน dropdown เลย
  // จนกว่าจะเปิด browser ใหม่ทั้งบาน แม้ค้นหาตรงๆ จะเจอก็ตาม)
  const drd = document.getElementById('fin-dr-datalist');
  if (drd) {
    if (_drData && _drData.length) {
      _buildDrDatalist();
    } else {
      _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000).then(r => r.json()).then(d => {
        if (d.stocks) { _drData = _drData || d.stocks; _buildDrDatalist(); }
        if (typeof _newsBuildDatalist === 'function') _newsBuildDatalist();
      }).catch(() => {});
    }
    // โหลดรายชื่อหุ้น US/HK ทั้งตลาด (mirror) ครั้งเดียว แล้วเติมเข้า datalist ค้นหา
    if (_finDrMirrorSyms === null) {
      _finDrMirrorSyms = {};   // กันยิงซ้ำ
      fetch('/api/mirror-symbols').then(r => r.json()).then(d => {
        _finDrMirrorSyms = d || {};
        _buildDrDatalist();
        _finMirRender();   // เติมรายการ browse US/HK เมื่อโหลดรายชื่อเสร็จ
        if (typeof _newsBuildDatalist === 'function') _newsBuildDatalist();
      }).catch(() => {});
      // ชื่อบริษัทของหุ้น mirror (แยก request — ใหญ่กว่า) โหลดเสร็จค่อยเติมชื่อในรายการ
      fetch('/api/mirror-names').then(r => r.json()).then(d => {
        _finMirNames = d || {};
        const dl = document.getElementById('fin-dr-datalist');
        if (dl) dl.innerHTML = '';   // บังคับ rebuild ด้วยชื่อ (ข้าม guard นับจำนวน)
        _buildDrDatalist();
        _finMirRender();
        if (typeof _newsBuildDatalist === 'function') _newsBuildDatalist();
      }).catch(() => {});
    }
  }
}

function setFinTab(tab, btn) {
  _finTab = tab;
  document.querySelectorAll('#fin-tab-set-btn,#fin-tab-dr-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('fin-search-set').style.display = tab === 'set' ? '' : 'none';
  document.getElementById('fin-search-dr').style.display  = tab === 'dr'  ? '' : 'none';
  document.getElementById('fin-result').innerHTML = '';
  // SET.or.th มีข้อมูลเฉพาะหุ้นไทย — หุ้นต่างประเทศ (DR) ปิดปุ่ม SET/สุขภาพการเงิน/กระแสเงินสด
  // และเด้งกลับ Finnomena
  const setSrcBtn = document.getElementById('fin-view-set-btn');
  const healthBtn = document.getElementById('fin-view-health-btn');
  const cashflowBtn = document.getElementById('fin-view-cashflow-btn');
  const factsheetBtn = document.getElementById('fin-view-factsheet-btn');
  if (tab === 'dr') {
    [setSrcBtn, healthBtn, cashflowBtn, factsheetBtn].forEach(b => { b.disabled = true; b.style.opacity = '0.4'; b.style.cursor = 'not-allowed'; });
    if (_finView === 'set' || _finView === 'health' || _finView === 'cashflow' || _finView === 'factsheet') setFinView('finnomena', document.getElementById('fin-view-finn-btn'));
  } else {
    [setSrcBtn, healthBtn, cashflowBtn, factsheetBtn].forEach(b => { b.disabled = false; b.style.opacity = ''; b.style.cursor = ''; });
  }
  initFinPage();
}

// sync ปุ่มแหล่งข้อมูลให้ตรงกับ 'แหล่งจริง' ที่แสดง — พอ fallback (เช่นหุ้นไม่มีงบ Yahoo
// -> Finnomena) ปุ่มจะย้ายมา active ตรงกับ badge ไม่ให้ปุ่มบอก Yahoo แต่ข้อมูลเป็น Finnomena
function _finSyncViewButton(source) {
  const map = { finnomena_q: ['finnomena', 'fin-view-finn-btn'], finnomena_y: ['finnomena_y', 'fin-view-fyear-btn'],
                yahoo: ['yahoo', 'fin-view-yyear-btn'],
                yahoo_q: ['yahoo_q', 'fin-view-yq-btn'], set: ['set', 'fin-view-set-btn'] };
  const m = map[source];
  if (!m) return;
  _finView = m[0];
  document.querySelectorAll('#fin-view-finn-btn,#fin-view-fyear-btn,#fin-view-yyear-btn,#fin-view-yq-btn,#fin-view-set-btn,#fin-view-qpl-btn,#fin-view-div-btn')
    .forEach(b => b.classList.remove('active'));
  const btn = document.getElementById(m[1]);
  if (btn) btn.classList.add('active');
}

function setFinView(view, btn) {
  _finView = view;
  document.querySelectorAll('#fin-view-finn-btn,#fin-view-fyear-btn,#fin-view-yyear-btn,#fin-view-yq-btn,#fin-view-set-btn,#fin-view-health-btn,#fin-view-factsheet-btn,#fin-view-cashflow-btn,#fin-view-qpl-btn,#fin-view-merged-btn,#fin-view-div-btn')
    .forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('fin-result').innerHTML = '';
  // ถ้ามีคำค้นอยู่แล้ว ค้นซ้ำทันทีด้วยแหล่งใหม่ (ไม่ต้องกดค้นหาซ้ำเอง)
  const inp = document.getElementById(_finTab === 'set' ? 'fin-sym-set' : 'fin-sym-dr');
  if (inp && inp.value.trim()) searchFinancials();
}

// fetch มี timeout — endpoint งบการเงินบางแหล่ง (finnomena_q/yahoo/yahoo_q) ถ้าหุ้นนั้นยัง
// ไม่เคย sync ในเครื่อง จะ fallback ไปดึงสดจาก network (yfinance/Finnomena) ซึ่งฝั่ง backend
// มี timeout ต่อ request ย่อยอยู่แล้วแต่รวมหลายรอบ (income/balance/cashflow/info) อาจกินเวลา
// นาทีกว่า — ถ้าไม่ตั้ง timeout ฝั่งนี้ด้วย spinner จะค้างเงียบๆ โดยผู้ใช้ไม่รู้ว่ากำลังรออะไรอยู่
async function _fetchTimeout(url, ms = 25000, errMsg, options) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  try {
    return await fetch(url, { ...options, signal: ctrl.signal });
  } catch (e) {
    if (e.name === 'AbortError') throw new Error(errMsg || 'หมดเวลารอข้อมูล (เกิน 25 วิ) — หุ้นนี้อาจยังไม่เคย sync ในเครื่อง กำลังลองดึงสดจากแหล่งข้อมูลแต่ช้าเกินไป ลองใหม่อีกครั้งหรือเปลี่ยนแหล่งข้อมูล');
    throw e;
  } finally {
    clearTimeout(t);
  }
}

async function searchFinancials() {
  const inputId = _finTab === 'set' ? 'fin-sym-set' : 'fin-sym-dr';
  const hintId  = _finTab === 'set' ? 'fin-set-hint' : 'fin-dr-hint';
  const sym = (document.getElementById(inputId).value || '').trim().toUpperCase();
  if (!sym) return;
  _finViewSeq++;   // คำขอใหม่ — response ช้าของหุ้น/มุมมองก่อนหน้าจะถูก stale-guard ตัดทิ้ง
  const hint = document.getElementById(hintId);
  const isDrSym = _finTab === 'dr';
  // มุมมองปันผลใช้ endpoint/renderer แยกจากงบการเงิน (ไม่ใช่ financials-full) — แตกสาขาออก
  // จาก flow เดิมตรงนี้เลย กัน VIEW_MAP/fallback logic ของงบไม่เกี่ยวข้องมาปนกัน
  if (_finView === 'dividends') {
    // มุมมองปันผลก็แยกตลาด DR (loadDividendsView รับ market) — เก็บ mkt ในชิปเหมือน qpl/merged
    // ไม่งั้นคลิกชิปตอนแท็บตลาดปัจจุบันไม่ตรงจะ resolve ตลาดผิด
    _finRecentAdd(sym, _finTab, isDrSym ? _finMirMarket : null);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + (isDrSym ? _finMirMarket + ':' : '') + encodeURIComponent(sym));
    loadDividendsView(sym, isDrSym ? _finMirMarket : 'TH', hint);
    return;
  }
  // ตาราง P&L รายไตรมาส — endpoint/renderer แยกจาก financials-full เหมือนมุมมองปันผล
  // (โครงสร้างข้อมูลคนละแบบ: รายการต่อไตรมาสที่ผสาน 2 แหล่งมาแล้ว ไม่ใช่ section->field->date)
  if (_finView === 'qpl') {
    _finRecentAdd(sym, _finTab, isDrSym ? _finMirMarket : null);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + (isDrSym ? _finMirMarket + ':' : '') + encodeURIComponent(sym));
    loadFinQplReport(sym, isDrSym, isDrSym ? _finMirMarket : null, hint);
    return;
  }
  // ตาราง 'งบรวมทุกแหล่ง' — P&L+งบดุล+กระแสเงินสด ผสานมาแล้ว มีทั้งรายไตรมาส/รายปีในเรสปอนส์
  // เดียว (endpoint/renderer แยกเหมือน qpl ด้านบน)
  if (_finView === 'merged') {
    _finRecentAdd(sym, _finTab, isDrSym ? _finMirMarket : null);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + (isDrSym ? _finMirMarket + ':' : '') + encodeURIComponent(sym));
    loadFinMergedReport(sym, isDrSym, isDrSym ? _finMirMarket : null, hint);
    return;
  }
  // SET Financial Health Check — หุ้นไทยเท่านั้น (ปุ่มถูกปิดไว้แล้วตอนอยู่แท็บ DR ใน
  // setFinTab แต่กันไว้อีกชั้นเผื่อ state ค้าง) ดู PLAN_set_api_expansion.txt งาน #5
  if (_finView === 'health') {
    _finRecentAdd(sym, _finTab);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + encodeURIComponent(sym));
    loadFinHealthView(sym, hint);
    return;
  }
  // Factsheet SET.or.th (วงจรเงินสด/อัตราส่วนการเงิน/อัตราการเติบโต/สถิติซื้อขาย/ผลตอบแทน
  // เทียบ sector-market) — หุ้นไทยเท่านั้น เหมือน health/cashflow ด้านบน
  if (_finView === 'factsheet') {
    _finRecentAdd(sym, _finTab);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + encodeURIComponent(sym));
    loadFinFactsheetView(sym, hint);
    return;
  }
  // กระแสเงินสด + งบดุลย่อจาก SET official — หุ้นไทยเท่านั้น (ปุ่มถูกปิดไว้แล้วตอนอยู่แท็บ DR
  // ใน setFinTab แต่กันไว้อีกชั้นเผื่อ state ค้าง)
  if (_finView === 'cashflow') {
    _finRecentAdd(sym, _finTab);
    history.replaceState(null, '', '#fin/' + _finTab + '/' + encodeURIComponent(sym));
    loadFinCashflowBalanceView(sym, hint);
    return;
  }
  // แปลงมุมมองที่ผู้ใช้เลือก -> source ที่ดึง (+ fallback ถ้าแหล่งนั้นไม่มีข้อมูลหุ้นตัวนี้)
  const VIEW_MAP = {
    finnomena:   { src: 'finnomena_q', fb: 'yahoo_q' },   // Finnomena ไม่มี JP/EU -> yahoo_q
    finnomena_y: { src: 'finnomena_y', fb: 'yahoo' },     // งบรายปีลึก 16 ปี (รวมจากไตรมาส) -> Yahoo รายปี
    yahoo_q:     { src: 'yahoo_q',     fb: 'finnomena_q' },
    yahoo:       { src: 'yahoo',       fb: null },
    set:         { src: 'set',         fb: null },
  };
  let view = _finView;
  if (isDrSym && view === 'set') view = 'finnomena';   // DR ไม่มี SET.or.th
  let source = VIEW_MAP[view].src;
  const reqSrc = source;               // แหล่งที่ผู้ใช้ขอ (ไว้เช็คว่ามี fallback ไหม)
  const fallback = VIEW_MAP[view].fb;
  // market = US/HK ที่เลือกอยู่ตอนนี้ — ใช้เดา yf ticker ตอน symbol ไม่อยู่ใน DR
  // universe ที่ curate ไว้ (หุ้น mirror ทั่วไปนอกพอร์ต S&P500/Dow/Nasdaq100 บางตัว)
  // กัน fetch_yahoo_full/quarterly พลาดไปดึงเป็นหุ้นไทย .BK (ดู financials_store.py)
  const marketQS = isDrSym ? `&market=${_finMirMarket}` : '';
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูลงบการเงิน...</div>';
  try {
    let r = await _fetchTimeout(`/api/financials-full/${encodeURIComponent(sym)}?source=${source}${isDrSym ? '&is_dr=1' : ''}${marketQS}`);
    let d = await r.json();
    if (d.error && fallback) {
      source = fallback;
      r = await _fetchTimeout(`/api/financials-full/${encodeURIComponent(sym)}?source=${source}${isDrSym ? '&is_dr=1' : ''}${marketQS}`);
      d = await r.json();
    }
    // หุ้น DR/US/HK นอกพอร์ต (mirror) ไม่มีงบ Yahoo — ลอง Finnomena ย้อนยาวเป็นทางสุดท้าย
    // เช็คกับทั้ง reqSrc และ fallback กัน request ซ้ำแหล่งที่เพิ่งพังไปแล้วรอบก่อนหน้า
    // (เดิมเช็คแค่ source !== 'finnomena_q' — พอ finnomena_q พังแล้ว fallback ไป yahoo_q
    // ก็พังอีก จะยิง finnomena_q ซ้ำเป็นครั้งที่สามทั้งที่รู้อยู่แล้วว่าพัง)
    if (d.error && isDrSym && reqSrc !== 'finnomena_q' && fallback !== 'finnomena_q') {
      source = 'finnomena_q';
      r = await _fetchTimeout(`/api/financials-full/${encodeURIComponent(sym)}?source=finnomena_q&is_dr=1`);
      d = await r.json();
    }
    if (d.error) throw new Error(d.error);
    _finData = d;
    _finSyncViewButton(source);   // ปุ่มแหล่งตรงกับข้อมูลจริง (พอ fallback ปุ่มย้ายตาม)
    // ถ้าแหล่งจริงต่างจากที่ขอ = เกิด fallback (หุ้นนี้ไม่มีงบตามแหล่งที่เลือก) — บอกให้รู้
    const srcName = { yahoo: 'Yahoo รายปี', yahoo_q: 'Yahoo รายไตรมาส', finnomena_y: 'Finnomena รายปี' };
    const shownName = { finnomena_q: 'Finnomena ไตรมาส', yahoo: 'Yahoo รายปี', yahoo_q: 'Yahoo ไตรมาส' }[source] || 'แหล่งอื่น';
    const fbNote = (source !== reqSrc && srcName[reqSrc])
      ? `⚠ หุ้นนี้ไม่มีงบ ${srcName[reqSrc]} — แสดง ${shownName} แทน · ` : '';
    hint.innerHTML = fbNote + (d.synced_at ? `sync ล่าสุด: ${d.synced_at}` : '');
    // จำว่าค้นหุ้นตัวนี้ (ใช้เลือกหุ้นค้นบ่อยมาอัพเดทงบในโหมดเบา) — เงียบ ไม่บล็อก
    fetch('/api/track-search', { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ symbol: sym }) }).catch(() => {});
    _finRecentAdd(sym, _finTab, isDrSym ? _finMirMarket : null);   // ประวัติหุ้นที่เพิ่งดู (localStorage ฝั่ง client)
    // อัพเดท URL hash ให้ refresh/back-forward/แชร์ลิงก์กลับมาที่หุ้นตัวนี้ได้ — replaceState
    // แทนการเซ็ต location.hash ตรงๆ กัน hashchange ยิงซ้ำแล้ว _finApplyHash ค้นหาซ้ำเป็นลูป
    // ต้องพก market (US/HK/JP) ไปกับ DR เสมอ — ไม่งั้น refresh/แชร์ลิงก์หุ้น mirror ที่ไม่ใช่
    // ตลาด default (US) จะ resolve yf ticker ผิดตลาด (ดู bug รหัส JP ชนกับ HK ใน _finn_mirror_keys)
    const hashMkt = isDrSym ? _finMirMarket + ':' : '';
    history.replaceState(null, '', '#fin/' + _finTab + '/' + hashMkt + encodeURIComponent(sym));
    _renderFinancialsFull(d, source);
    // เทียบ Yahoo vs SET.or.th — เดิมรันเฉพาะมุมมอง Yahoo รายปี ทั้งที่ Finnomena (มุมมอง
    // default) ก็น่าเตือนเหมือนกัน — endpoint อ่านจาก cache ทั้งสองแหล่งเสมออยู่แล้ว
    // (ไม่ผูกกับ source ที่ขอ) ไม่มี side effect เพิ่มถ้ายังไม่เคย sync มาก่อน
    if (_finTab !== 'dr' && (source === 'yahoo' || source === 'finnomena_q' || source === 'finnomena_y'))
      _checkFinDQ(sym);
  } catch(e) {
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

async function _checkFinDQ(sym) {
  try {
    const r = await fetch(`/api/financials-dq-check/${encodeURIComponent(sym)}`);
    const d = await r.json();
    if (_finData?.sym !== sym) return;   // เปลี่ยนหุ้นไปแล้วระหว่างรอโหลด — กันแบนเนอร์ของหุ้นเก่าไปแปะหน้าหุ้นใหม่
    if (d.status !== 'mismatch') return;
    const box = document.getElementById('fin-result');
    if (!box || !box.firstElementChild) return;
    const rows = d.mismatches.map(m =>
      `${m.metric} ปี ${m.year}: Yahoo ${_finFmt(m.yahoo)} vs SET.or.th ${_finFmt(m.set)} (ต่างกัน ${m.diff_pct}%)`
    ).join('<br>');
    const callout = document.createElement('div');
    callout.innerHTML = `<div style="display:flex;gap:10px;background:#d9932e1f;border:1px solid #d9932e;border-radius:10px;padding:12px 14px;margin-bottom:12px;font-size:12.5px;line-height:1.6">
      <div style="font-size:16px">⚠</div>
      <div><b style="color:#d9932e">พบตัวเลขต่างกันระหว่าง Yahoo Finance กับ SET.or.th เกิน 5%</b><br>${rows}</div>
    </div>`;
    box.insertBefore(callout, box.firstChild);
  } catch (e) { /* เงียบ — ไม่ใช่ฟีเจอร์หลัก */ }
}

// มุมมอง "📋 P&L รายไตรมาส" — ตาราง broker-style ผสาน Finnomena (ยาว)+Yahoo (ละเอียด)
// ใช้ endpoint แยก /api/financials-qpl-report ไม่ใช่ financials-full (โครงสร้างข้อมูล
// เป็นรายการต่อไตรมาสที่ผสานมาแล้ว ไม่ใช่ section->field->date) ดู compute_qpl_report()
// ใน sources/financials_store.py
// SET Financial Health Check — เมนูงบการเงิน แท็บ "🩺 สุขภาพการเงิน (SET)" (ดู
// PLAN_set_api_expansion.txt งาน #5) โครงสร้าง theme > category > account > ค่า
// 5 งวด (ปกติ 3 ปีเต็ม + 2 ครึ่งปี) ที่ SET จัดหมวดมาให้เอง (คุณภาพรายได้/สภาพคล่อง/
// หนี้สิน ฯลฯ) ต่างจากตาราง P&L/งบรวมที่ dashboard ประกอบเอง — ตัวนี้เป็นเลขทางการที่
// SET คำนวณจากงบที่บริษัทยื่นจริง
async function loadFinHealthView(sym, hint) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูล Financial Health...</div>';
  try {
    const r = await _fetchTimeout(`/api/financial-health/${encodeURIComponent(sym)}`, 20000,
      'หมดเวลารอข้อมูล (เกิน 20 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ
    if (d.error) throw new Error(d.error);
    hint.textContent = '';
    _renderFinHealth(d);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

function _finHealthPeriodLabel(p) {
  const q = p.quarter === 'YE' ? 'ปี' : p.quarter;
  return `${q} ${p.year}`;
}
function _finHealthFmt(v, unit) {
  if (v == null || isNaN(v)) return '—';
  const n = Math.abs(v) >= 1000 ? v.toLocaleString('en-US', { maximumFractionDigits: 0 }) : v.toLocaleString('en-US', { maximumFractionDigits: 2 });
  return n;
}
function _finHealthChange(v, unit) {
  if (v == null || isNaN(v)) return '';
  const clr = v > 0 ? 'var(--green)' : v < 0 ? 'var(--red)' : 'var(--text2)';
  const sign = v > 0 ? '+' : '';
  return `<span style="font-size:10px;color:${clr}">${sign}${v.toFixed(1)}${unit === '%' ? 'pp' : (unit || '')}</span>`;
}

function _renderFinHealth(d) {
  const box = document.getElementById('fin-result');
  if (!d.themes || !d.themes.length) {
    box.innerHTML = '<div class="empty" style="padding:24px">ไม่มีข้อมูล Financial Health ของหุ้นนี้</div>';
    return;
  }
  const periods = d.periods || [];
  const themesHtml = d.themes.map(theme => {
    const catsHtml = theme.categories.map(cat => {
      const rowsHtml = cat.accounts.map(acc => {
        // จับคู่ค่าของบัญชีนี้กับ periods หลัก (แม่นยำกว่า index ตรงๆ — บาง account
        // อาจไม่มีค่าครบทุกงวด SET จะข้ามงวดนั้นไปเงียบๆ)
        const byKey = {};
        (acc.values || []).forEach(v => { byKey[`${v.quarter}-${v.year}`] = v; });
        const cellsHtml = periods.map(p => {
          const v = byKey[`${p.quarter}-${p.year}`];
          if (!v) return `<td style="text-align:right;color:var(--text2)">—</td>`;
          return `<td style="text-align:right;white-space:nowrap">${_finHealthFmt(v.amount)}<br>${_finHealthChange(v.change, acc.change_unit)}</td>`;
        }).join('');
        return `<tr>
          <td style="font-size:12px;max-width:260px">${(acc.name || '').replace(/</g,'&lt;')}${acc.unit ? ` <span style="color:var(--text2);font-size:10px">(${acc.unit})</span>` : ''}</td>
          ${cellsHtml}
        </tr>`;
      }).join('');
      return `<div style="margin-bottom:14px">
        <div style="font-size:12px;font-weight:600;margin-bottom:4px">${(cat.name || '').replace(/</g,'&lt;')}
          ${cat.description ? ` <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:260px">${cat.description.replace(/</g,'&lt;')}</div></span>` : ''}
        </div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:520px;font-size:12px">
          <thead><tr><th style="text-align:left">รายการ</th>${periods.map(p => `<th style="text-align:right">${_finHealthPeriodLabel(p)}</th>`).join('')}</tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table></div>
      </div>`;
    }).join('');
    return `<div class="card" style="padding:16px;margin-bottom:12px">
      <div style="font-size:14px;font-weight:700;margin-bottom:12px">${(theme.name || '').replace(/</g,'&lt;')}</div>
      ${catsHtml}
    </div>`;
  }).join('');

  box.innerHTML = `
    <div style="font-size:11px;color:var(--text2);margin-bottom:12px">
      เลขทางการที่ SET คำนวณจากงบที่บริษัทยื่นจริง — ${periods.length} งวด (ปีเต็ม + ครึ่งปี ไม่ใช่รายไตรมาสครบทุกงวด)
      <span style="color:var(--text2)"> · แถวที่ชื่อลงท้าย * ใน SET หมายถึง ratio ที่ SET คำนวณเอง ไม่ใช่ตัวเลขจากงบตรงๆ</span>
    </div>
    ${themesHtml}`;
}

// Factsheet SET.or.th — เมนูงบการเงิน แท็บ "📄 Factsheet (SET)" (endpoint ตระกูล
// /api/set/factsheet/<sym>/... ไม่มีเอกสารรองรับทางการ เจอตอนตรวจสอบตัวเลข "วงจรเงินสด" ที่
// หน้า factsheet จริงของ SET.or.th โชว์ — ดักฟัง network ด้วย Playwright แล้วพบว่าตรงกับ
// /financial-health เดิมไม่ครบ) รวม 5 sub-endpoint: วงจรเงินสด/อัตราส่วนการเงิน/อัตราการเติบโต/
// สถิติซื้อขายรายปี/ผลตอบแทนเทียบ sector-market — cash_cycle เป็น null ปกติสำหรับหุ้นกลุ่ม
// การเงิน/REIT (endpoint นั้น 404 เสมอ) โดยอีก 4 sub-endpoint ยังมีข้อมูล
async function loadFinFactsheetView(sym, hint) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูล Factsheet...</div>';
  try {
    const r = await _fetchTimeout(`/api/financial-factsheet/${encodeURIComponent(sym)}`, 20000,
      'หมดเวลารอข้อมูล (เกิน 20 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ
    if (d.error) throw new Error(d.error);
    hint.textContent = '';
    _renderFinFactsheet(d);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

function _finFactsheetPeriodLabel(p) {
  // งวดปีเต็มของ factsheet ใช้รหัส 'Q9' (ต่างจาก set_health ที่ใช้ 'YE')
  const q = p.quarter === 'Q9' ? 'ปี' : p.quarter;
  return `${q} ${p.year}`;
}
function _finFactsheetFmt(v) {
  if (v == null || isNaN(v)) return '—';
  return Math.abs(v) >= 1000 ? v.toLocaleString('en-US', { maximumFractionDigits: 0 }) : v.toLocaleString('en-US', { maximumFractionDigits: 2 });
}

// รายการที่ "ค่าลดลง = ดีขึ้น" (ตรงข้ามกับ default) — จับด้วย keyword ในชื่อบัญชีไทย กันสะกด/
// วงเล็บหน่วยต่างกันเล็กน้อยข้ามรอบ SET แก้ wording (เหมือน _PEER_GROUP_LOWER_BETTER ที่ใช้ใน
// มุมมองเทียบกลุ่ม) ทุกอย่างที่ไม่อยู่ในนี้ถือว่า "ค่าเพิ่มขึ้น = ดีขึ้น" เป็นค่าเริ่มต้น —
// ตัวหมุนเวียนเจ้าหนี้การค้าจับคู่กับระยะเวลาชำระหนี้เจ้าหนี้ (DPO) โดยเจตนา: DPO สูง = เก็บเงินสด
// ไว้ได้นานกว่า (ดีต่อบริษัท) ดังนั้นอัตราหมุนเวียนเจ้าหนี้ (ตัวผกผันของ DPO) ยิ่งต่ำยิ่งดีตามกัน
const _FS_LOWER_BETTER_KEYWORDS = ['ระยะเวลาเก็บหนี้', 'ระยะเวลาขายสินค้า', 'หมุนเวียนเจ้าหนี้การค้า',
  'วงจรเงินสด', 'หนี้สินต่อส่วนของผู้ถือหุ้น', 'เปลี่ยนแปลงต้นทุน', 'เปลี่ยนแปลงค่าใช้จ่ายรวม'];
function _fsIsLowerBetter(name) {
  return _FS_LOWER_BETTER_KEYWORDS.some(k => (name || '').includes(k));
}
function _fsTrendColor(delta, lowerBetter) {
  if (delta == null || isNaN(delta) || delta === 0) return '';
  const improved = lowerBetter ? delta < 0 : delta > 0;
  return improved ? 'var(--green)' : 'var(--red)';
}
function _fsSignColor(v) {
  if (v == null || isNaN(v) || v === 0) return '';
  return v > 0 ? 'var(--green)' : 'var(--red)';
}
function _fsCell(v, color) {
  const style = color ? `text-align:right;color:${color};font-weight:600` : 'text-align:right';
  return `<td style="${style}">${_finFactsheetFmt(v)}</td>`;
}

// คีย์เรียงงวดตามเวลาจริง — SET คืน list ไม่เรียง (มักเป็น [งวดสะสมล่าสุด, งวดสะสมปีก่อน,
// ปีเต็มล่าสุด, ปีเต็มก่อนหน้า]) และ _merge_factsheet_period_list เรียงใหม่ตอน sync รอบ 2
// เท่านั้น — frontend ต้องเรียงเองเสมอ ไม่งั้นคอลัมน์สลับ + สีแนวโน้มเทียบผิดงวด
function _fsPeriodSortKey(p) {
  if (p.end_date) return p.end_date;
  if (p.as_of_date) return p.as_of_date;
  const qn = { Q1: '03-31', Q2: '06-30', Q3: '09-30', Q9: '12-31' }[p.quarter] || '12-31';
  return `${p.year || 0}-${qn}`;
}

// ตารางแบบ period -> data[{account_name,value}] ใช้ร่วมกัน cash_cycle/financial_ratio/
// financial_growth (รูปร่างเหมือนกันเป๊ะ) รวม account_name ทุกงวดเป็นแถว (งวดไหนไม่มีค่า
// ของรายการนั้นโชว์ '—' — SET บางงวดให้ไม่ครบทุกบัญชีเหมือน financial-health)
// เรียงงวดเก่า→ใหม่ก่อนเสมอ · signColor=true (financial_growth ที่เป็นค่า YoY อยู่แล้ว): ใส่สีตาม
// เครื่องหมายของตัวเองทีละเซลล์ · signColor=false (cash_cycle/financial_ratio): เทียบกับงวด
// "ชนิดเดียวกัน" (quarter code เท่ากัน — งวดสะสมเทียบงวดสะสม / ปีเต็มเทียบปีเต็ม ไม่ปนกัน)
// ที่ใกล้ที่สุดก่อนหน้า ใส่เขียว/แดงตาม _fsIsLowerBetter
function _finFactsheetSeriesTable(periods, emptyMsg, signColor) {
  if (!periods || !periods.length) {
    return `<div style="font-size:12px;color:var(--text2)">${emptyMsg || 'ไม่มีข้อมูล'}</div>`;
  }
  const sorted = periods.slice().sort((a, b) => _fsPeriodSortKey(a).localeCompare(_fsPeriodSortKey(b)));
  const names = [];
  const seen = new Set();
  sorted.forEach(p => (p.data || []).forEach(a => {
    if (a.account_name && !seen.has(a.account_name)) { seen.add(a.account_name); names.push(a.account_name); }
  }));
  const rows = names.map(name => {
    const lowerBetter = _fsIsLowerBetter(name);
    const vals = sorted.map(p => {
      const a = (p.data || []).find(x => x.account_name === name);
      return a ? a.value : null;
    });
    const cells = vals.map((v, i) => {
      let color = '';
      if (v != null) {
        if (signColor) {
          color = _fsSignColor(v);
        } else {
          // งวดก่อนหน้าที่เป็น "ชนิดเดียวกัน" (quarter code ตรงกัน) เท่านั้น — กันเทียบงวดสะสม
          // 6 เดือน กับปีเต็ม หรือ Q ต่างกัน
          let prev = null;
          for (let j = i - 1; j >= 0; j--) {
            if (sorted[j].quarter === sorted[i].quarter && vals[j] != null) { prev = vals[j]; break; }
          }
          if (prev != null) color = _fsTrendColor(v - prev, lowerBetter);
        }
      }
      return _fsCell(v, color);
    }).join('');
    return `<tr><td style="font-size:12px;max-width:260px">${name.replace(/</g, '&lt;')}</td>${cells}</tr>`;
  }).join('');
  return `<div style="overflow-x:auto"><table class="tbl" style="min-width:480px;font-size:12px">
    <thead><tr><th style="text-align:left">รายการ</th>${sorted.map(p => `<th style="text-align:right">${_finFactsheetPeriodLabel(p)}</th>`).join('')}</tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

// %เปลี่ยนแปลงรายปี (percent_change) เป็นค่า return อยู่แล้ว ใส่สีตามเครื่องหมายของตัวเองได้เลย
// (บวก=เขียว/ลบ=แดง) ไม่ต้องเทียบกับงวดก่อนหน้า ต่างจาก PE/PBV/Yield/Beta/Payout/Turnover/
// MktCap ที่ไม่มีทิศทาง "ดีขึ้น" ที่ชัดเจนพอจะฟันธงสี เลยปล่อยไม่มีสี
function _finFactsheetTradingStatTable(rowsIn) {
  if (!rowsIn || !rowsIn.length) return `<div style="font-size:12px;color:var(--text2)">ไม่มีข้อมูล</div>`;
  // SET คืน + _merge_factsheet_trading_stat สะสมตามลำดับ dict-insertion (เช่น [YTD,2025,2024]
  // และเพี้ยนหนักขึ้นหลังข้ามปี) — เรียงเก่า→ใหม่ตาม date จริง (YTD = วันล่าสุดจึงอยู่ขวาสุด)
  const _tsKey = r => r.date || (/^\d{4}$/.test(r.period || '') ? `${r.period}-12-31` : '9999-12-31');
  const rows = rowsIn.slice().sort((a, b) => _tsKey(a).localeCompare(_tsKey(b)));
  const fields = [['close', 'ราคาปิด'], ['percent_change', '%เปลี่ยนแปลง (%)'],
    ['pe', 'P/E (เท่า)'], ['pbv', 'P/BV (เท่า)'], ['dividend_yield', 'Div Yield (%)'],
    ['dividend_payout_ratio', 'Payout Ratio'], ['beta', 'Beta'],
    ['turnover_ratio', 'Turnover Ratio (%)'], ['market_cap', 'Market Cap (บาท)']];
  const head = rows.map(r => `<th style="text-align:right">${(r.period || '').replace(/</g, '&lt;')}</th>`).join('');
  const body = fields.map(([k, label]) => {
    const cells = rows.map(r => _fsCell(r[k], k === 'percent_change' ? _fsSignColor(r[k]) : '')).join('');
    return `<tr><td style="font-size:12px">${label}</td>${cells}</tr>`;
  }).join('');
  return `<div style="overflow-x:auto"><table class="tbl" style="min-width:420px;font-size:12px">
    <thead><tr><th style="text-align:left">รายการ</th>${head}</tr></thead>
    <tbody>${body}</tbody>
  </table></div>`;
}

// 5 แถว %เปลี่ยนแปลงราคา (5วัน/1ด./3ด./6ด./YTD) เป็นค่า return ของตัวเอง ใส่สีตามเครื่องหมาย
// ได้เลยทีละเซลล์ (ไม่ต้องเทียบ หุ้น vs sector vs market — คนละความหมายกับ "ดีขึ้น/แย่ลง")
// PE/PBV/Turnover ไม่มีทิศทางชัดเจนเหมือนกัน ปล่อยไม่มีสี
function _finFactsheetPricePerfTable(pp) {
  if (!pp) return `<div style="font-size:12px;color:var(--text2)">ไม่มีข้อมูล</div>`;
  const pctFields = new Set(['five_day_percent_change', 'one_month_percent_change',
    'three_month_percent_change', 'six_month_percent_change', 'ytd_percent_change']);
  const fields = [['five_day_percent_change', '5 วัน (%)'], ['one_month_percent_change', '1 เดือน (%)'],
    ['three_month_percent_change', '3 เดือน (%)'], ['six_month_percent_change', '6 เดือน (%)'],
    ['ytd_percent_change', 'YTD (%)'], ['pe_ratio', 'P/E (เท่า)'],
    ['pb_ratio', 'P/BV (เท่า)'], ['turnover_ratio', 'Turnover (%)']];
  const cols = [['stock', 'หุ้น (' + (pp.stock?.symbol || '—') + ')'],
                ['sector', 'กลุ่ม (' + (pp.sector?.symbol || '—') + ')'],
                ['market', 'ตลาด (' + (pp.market?.symbol || '—') + ')']];
  const head = cols.map(([, label]) => `<th style="text-align:right">${label}</th>`).join('');
  const body = fields.map(([k, label]) => {
    const cells = cols.map(([ck]) => {
      const v = pp[ck] ? pp[ck][k] : null;
      return _fsCell(v, pctFields.has(k) ? _fsSignColor(v) : '');
    }).join('');
    return `<tr><td style="font-size:12px">${label}</td>${cells}</tr>`;
  }).join('');
  return `<div style="overflow-x:auto"><table class="tbl" style="min-width:420px;font-size:12px">
    <thead><tr><th style="text-align:left">รายการ</th>${head}</tr></thead>
    <tbody>${body}</tbody>
  </table></div>`;
}

function _renderFinFactsheet(d) {
  const box = document.getElementById('fin-result');
  const has = k => {
    const v = d[k];
    if (!v) return false;
    return Array.isArray(v) ? v.length > 0 : true;
  };
  if (!has('cash_cycle') && !has('financial_ratio') && !has('financial_growth')
      && !has('trading_stat') && !has('price_performance')) {
    box.innerHTML = '<div class="empty" style="padding:24px">ไม่มีข้อมูล Factsheet ของหุ้นนี้</div>';
    return;
  }
  const cards = [];
  cards.push(`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:700;margin-bottom:8px">💧 วงจรเงินสด</div>
    ${_finFactsheetSeriesTable(d.cash_cycle, 'วงจรเงินสดไม่มีข้อมูลสำหรับหุ้นกลุ่มการเงิน/REIT (SET.or.th ไม่คำนวณให้กลุ่มนี้ — สูตรไม่ใช้กับงบดุลธนาคาร/ประกัน)')}
  </div>`);
  if (has('financial_ratio')) cards.push(`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:700;margin-bottom:8px">📐 อัตราส่วนทางการเงิน</div>
    ${_finFactsheetSeriesTable(d.financial_ratio)}
  </div>`);
  if (has('financial_growth')) cards.push(`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:700;margin-bottom:8px">📈 อัตราการเติบโต (YoY)</div>
    ${_finFactsheetSeriesTable(d.financial_growth, null, true)}
  </div>`);
  if (has('trading_stat')) cards.push(`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:700;margin-bottom:8px">📊 สถิติซื้อขายรายปี</div>
    ${_finFactsheetTradingStatTable(d.trading_stat)}
  </div>`);
  if (has('price_performance')) cards.push(`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:700;margin-bottom:8px">⚖️ ผลตอบแทนเทียบ หุ้น/กลุ่ม/ตลาด</div>
    ${_finFactsheetPricePerfTable(d.price_performance)}
  </div>`);
  box.innerHTML = `
    <div style="font-size:11px;color:var(--text2);margin-bottom:12px">
      ข้อมูลจาก factsheet SET.or.th (endpoint ไม่มีเอกสารรองรับทางการ — โครงสร้างอาจเปลี่ยนได้โดยไม่แจ้งล่วงหน้า) · หุ้นไทยเท่านั้น
      <span style="color:var(--text2)"> · งวดเรียงเก่า→ใหม่ (ซ้าย→ขวา) · วงจรเงินสด/อัตราส่วน: <span style="color:var(--green);font-weight:600">เขียว</span> = ดีขึ้นจากงวดชนิดเดียวกันก่อนหน้า,
      <span style="color:var(--red);font-weight:600">แดง</span> = แย่ลง (เทียบทิศทางตามธรรมชาติของแต่ละรายการ เช่น ระยะเวลาเก็บหนี้/วงจรเงินสด สั้นลง = ดีขึ้น) · อัตราการเติบโต: เขียว/แดง = ค่า YoY เป็นบวก/ลบ</span>
    </div>
    ${cards.join('')}`;
}

// มุมมอง "💵 กระแสเงินสด & งบดุล (SET)" — /api/financial-cashflow-balance (source set_cashflow/
// set_balance ใน financials_store.py) OCF/CFI/CFF/CapEx + งบดุลย่อรายไตรมาส หุ้นไทยเท่านั้น
async function loadFinCashflowBalanceView(sym, hint) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูลกระแสเงินสด/งบดุล...</div>';
  try {
    const r = await _fetchTimeout(`/api/financial-cashflow-balance/${encodeURIComponent(sym)}`, 20000,
      'หมดเวลารอข้อมูล (เกิน 20 วิ) — ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ
    if (d.error) throw new Error(d.error);
    hint.textContent = '';
    _renderFinCashflowBalance(d);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

function _finCfQuarterLabel(q) {
  if (!q) return '—';
  const [y, qq] = q.split('-');
  return `Q${qq}/${parseInt(y, 10) + 543}`;
}
function _finCfFmt(v) {
  if (v == null) return '<span class="text2">—</span>';
  return (v / 1e6).toLocaleString('en-US', { maximumFractionDigits: 1 }) + ' ลบ.';
}

// แถวรายการ — จัดกลุ่ม 2 หมวด (กระแสเงินสดจาก set_cashflow, งบดุลย่อจาก set_balance) คีย์ตรงกับ
// field ที่ _set_cashflow_row_from_amt/_set_balance_row_from_amt คืนมา (financials_store.py)
const _FIN_CF_ROWS = [
  { group: 'กระแสเงินสด (จากงบที่ยื่นจริง)', key: 'ocf', label: 'เงินสดจากการดำเนินงาน (OCF)' },
  { group: 'กระแสเงินสด (จากงบที่ยื่นจริง)', key: 'cfi', label: 'เงินสดจากการลงทุน (CFI)' },
  { group: 'กระแสเงินสด (จากงบที่ยื่นจริง)', key: 'cff', label: 'เงินสดจากการจัดหาเงิน (CFF)' },
  { group: 'กระแสเงินสด (จากงบที่ยื่นจริง)', key: 'capex', label: 'CapEx (ซื้อสินทรัพย์ถาวร)' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'cash', label: 'เงินสดและรายการเทียบเท่า' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'receivables', label: 'ลูกหนี้การค้า' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'inventory', label: 'สินค้าคงเหลือ' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'current_assets', label: 'สินทรัพย์หมุนเวียนรวม' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'current_liabilities', label: 'หนี้สินหมุนเวียนรวม' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'total_liabilities', label: 'หนี้สินรวม' },
  { group: 'งบดุลย่อ (ณ สิ้นงวด)', key: 'total_equity_parent', label: 'ส่วนของผู้ถือหุ้น (บริษัทใหญ่)' },
];

function _renderFinCashflowBalance(d) {
  const box = document.getElementById('fin-result');
  const quarters = d.quarters || [];
  if (!quarters.length) {
    box.innerHTML = '<div class="empty" style="padding:24px">ไม่มีข้อมูลกระแสเงินสด/งบดุลของหุ้นนี้</div>';
    return;
  }
  let curGroup = null;
  const rowsHtml = _FIN_CF_ROWS.map(r => {
    const groupHtml = r.group !== curGroup
      ? `<tr><td colspan="${quarters.length + 1}" style="font-size:12px;font-weight:600;padding-top:10px">${r.group}</td></tr>` : '';
    curGroup = r.group;
    const cellsHtml = quarters.map(q => `<td style="text-align:right">${_finCfFmt(q[r.key])}</td>`).join('');
    return `${groupHtml}<tr><td style="font-size:12px;padding-left:8px">${r.label}</td>${cellsHtml}</tr>`;
  }).join('');

  // Current Ratio / Net Cash คำนวณฝั่ง client จากงบดุลย่อ (ไม่ได้มาจาก SET ตรงๆ) — Current
  // Ratio สูง = สภาพคล่องดี (สินทรัพย์หมุนเวียนพอจ่ายหนี้สินหมุนเวียน), Net Cash ติดลบ = มีหนี้
  // สุทธิมากกว่าเงินสดที่ถือ (ใช้หนี้สินรวมเทียบ ไม่ใช่แค่หนี้ที่มีดอกเบี้ย — อนุรักษ์นิยมกว่า)
  const currentRatioCells = quarters.map(q => {
    const v = (q.current_assets != null && q.current_liabilities) ? q.current_assets / q.current_liabilities : null;
    return `<td style="text-align:right">${v == null ? '<span class="text2">—</span>' : v.toFixed(2) + ' เท่า'}</td>`;
  }).join('');
  const netCashCells = quarters.map(q => {
    const v = (q.cash != null && q.total_liabilities != null) ? q.cash - q.total_liabilities : null;
    return `<td style="text-align:right">${_finCfFmt(v)}</td>`;
  }).join('');

  box.innerHTML = `
    <div style="font-size:11px;color:var(--text2);margin-bottom:12px">
      กระแสเงินสด+งบดุลจากงบที่บริษัทยื่นจริง (SET.or.th) — เก็บสะสม ~3-4 ไตรมาสล่าสุดต่อรอบ sync
      (periods ของ SET มีแค่ปีปัจจุบัน+ปีก่อนหน้า) · Current Ratio/Net Cash คำนวณเองฝั่งนี้
    </div>
    <div style="overflow-x:auto"><table class="tbl" style="min-width:520px">
      <thead><tr><th style="text-align:left">รายการ</th>${quarters.map(q => `<th style="text-align:right">${_finCfQuarterLabel(q.quarter)}</th>`).join('')}</tr></thead>
      <tbody>${rowsHtml}
        <tr><td colspan="${quarters.length + 1}" style="font-size:12px;font-weight:600;padding-top:10px">อัตราส่วนคำนวณเอง</td></tr>
        <tr><td style="font-size:12px;padding-left:8px">Current Ratio</td>${currentRatioCells}</tr>
        <tr><td style="font-size:12px;padding-left:8px">Net Cash (เงินสด−หนี้สินรวม)</td>${netCashCells}</tr>
      </tbody>
    </table></div>`;
}

// หาบัญชีตาม code ทั่วทุก theme/category ของ Financial Health Check — ใช้กับการ์ดย่อ
// Tearsheet ที่หยิบเฉพาะตัวเด่นจากทั้งหมดที่ SET จัดหมวดมาให้ (ดู _tsLoadFinHealthMini)
function _finHealthFindAccount(themes, code) {
  for (const th of themes || []) {
    for (const c of th.categories || []) {
      const a = (c.accounts || []).find(x => x.code === code);
      if (a) return a;
    }
  }
  return null;
}

// การ์ดย่อ "🩺 สุขภาพการเงิน (SET)" ใน Tearsheet — หยิบ 5 ตัวเด่นจาก Financial Health
// Check เต็ม (ดู PLAN_set_api_expansion.txt งาน #5B) + cross-check วงจรเงินสดกับค่าที่
// dashboard คำนวณเองจาก Yahoo ใน factor_snapshot (งาน #5C) เตือนถ้าต่างกันมาก (สูตร/
// ช่วงเวลาที่ใช้อาจต่างกัน — ไม่จำเป็นว่าตัวไหนผิด แค่เตือนให้เช็ค)
const _TS_FIN_HEALTH_PICKS = [
  { code: 'r_debt_to_equity',          label: 'D/E',              suffix: ' เท่า' },
  { code: 'q_cash_cycle',              label: 'วงจรเงินสด',       suffix: ' วัน' },
  { code: 'p_net_income_margin',       label: 'Net Margin',       suffix: '%' },
  { code: 'p_ebitda_margin',           label: 'EBITDA Margin',    suffix: '%' },
  { code: 'r_interest_coverage_cfo',   label: 'Interest Coverage', suffix: ' เท่า' },
];
async function _tsLoadFinHealthMini(sym, yahooCashCycle) {
  const box = document.getElementById('ts-fin-health-mini');
  if (!box) return;
  try {
    const r = await _fetchTimeout(`/api/financial-health/${encodeURIComponent(sym)}`, 12000);
    const d = await r.json();
    if (_tsData?.symbol !== sym) return;
    if (d.error) { box.innerHTML = ''; return; }   // ไม่มีข้อมูล — ซ่อนการ์ดเงียบๆ ไม่บังคับให้เห็น error รบกวน
    const tiles = _TS_FIN_HEALTH_PICKS.map(p => {
      const acc = _finHealthFindAccount(d.themes, p.code);
      const latest = acc?.values?.length ? acc.values[acc.values.length - 1] : null;
      const val = latest?.amount;
      return `<div style="min-width:100px">
        <div style="font-size:16px;font-weight:700">${val != null ? val.toFixed(2) + p.suffix : '—'}</div>
        <div style="font-size:10.5px;color:var(--text2)">${p.label}</div>
      </div>`;
    }).join('');
    if (!tiles) { box.innerHTML = ''; return; }

    // cross-check วงจรเงินสด SET (q_cash_cycle) vs ที่ dashboard คำนวณเองจาก Yahoo
    const setCC = _finHealthFindAccount(d.themes, 'q_cash_cycle')?.values?.slice(-1)[0]?.amount;
    let crossCheck = '';
    if (setCC != null && yahooCashCycle != null) {
      const diff = Math.abs(setCC - yahooCashCycle);
      if (diff >= 15) {
        crossCheck = `<div style="font-size:10.5px;color:#e8a33d;margin-top:8px">⚠ วงจรเงินสดที่คำนวณเอง (Yahoo) = ${yahooCashCycle.toFixed(1)} วัน ต่างจาก SET ทางการ (${setCC.toFixed(1)} วัน) อยู่ ${diff.toFixed(0)} วัน — สูตร/ช่วงเวลาที่ใช้อาจต่างกัน ไม่จำเป็นว่าตัวไหนผิด ดูรายละเอียดเต็มในเมนูงบการเงิน</div>`;
      }
    }

    box.innerHTML = `<div class="card" style="padding:16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:13px;font-weight:700">🩺 สุขภาพการเงิน (SET)
          <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:260px">
            เลขทางการที่ SET คำนวณจากงบที่บริษัทยื่นจริง — หยิบมา 5 ตัวเด่นจากทั้งหมดที่ SET จัดหมวดไว้ (หนี้สิน/วงจรเงินสด/กำไร) ดูฉบับเต็มได้ในเมนูงบการเงิน
          </div></span>
        </div>
        <a href="#" onclick="_tsGoFinHealth('${sym}');return false" style="font-size:11px;color:var(--blue)">ดูเต็มในเมนูงบการเงิน →</a>
      </div>
      <div style="display:flex;gap:16px;flex-wrap:wrap">${tiles}</div>
      ${crossCheck}
    </div>`;
  } catch (e) {
    if (_tsData?.symbol !== sym) return;
    box.innerHTML = '';   // เป็นการ์ดเสริม — โหลดไม่สำเร็จก็ซ่อนไปเงียบๆ ไม่รบกวนหน้าหลัก
  }
}

function _tsGoFinHealth(sym) {
  showPage('financials');
  setFinTab('set', document.getElementById('fin-tab-set-btn'));
  document.getElementById('fin-sym-set').value = sym;
  setFinView('health', document.getElementById('fin-view-health-btn'));
  setTimeout(searchFinancials, 150);
}

async function loadFinQplReport(sym, isDr, market, hint) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูลงบการเงิน...</div>';
  try {
    const qs = (isDr ? '?is_dr=1' : '') + (market ? (isDr ? '&' : '?') + 'market=' + market : '');
    const r = await _fetchTimeout(`/api/financials-qpl-report/${encodeURIComponent(sym)}${qs}`, 25000,
      'หมดเวลารอข้อมูล (เกิน 25 วิ) — หุ้นนี้อาจยังไม่เคย sync ในเครื่อง กำลังลองดึงสดแต่ช้าเกินไป ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ view + poison _finQplData
    if (d.error) throw new Error(d.error);
    hint.textContent = '';
    _renderFinQplReport(d);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

// ค่าเงิน (บาท) -> หน่วยพันบาท คั่นหลักพัน — ตามธรรมเนียมตาราง broker research ของไทย
function _qplNum(v) {
  if (v == null || isNaN(v)) return '—';
  return Math.round(v / 1000).toLocaleString('en-US');
}
// แถวต้นทุน/ภาษี แสดงติดลบด้วยวงเล็บ (ธรรมเนียมงบการเงิน) แม้ payload เก็บเป็นค่าบวก (magnitude)
function _qplNumNeg(v) {
  if (v == null || isNaN(v)) return '—';
  return `(${Math.round(v / 1000).toLocaleString('en-US')})`;
}
function _qplPct(v) {
  if (v == null || isNaN(v)) return '—';
  return (v >= 0 ? '+' : '') + v.toFixed(2) + '%';
}
// คำเรียกสกุลเงินของงบสำหรับ label หน่วย — DR US/HK/JP งบเป็น USD/HKD/JPY ไม่ใช่บาท
// (compute_qpl_report/compute_full_report ไม่แปลงค่าเงิน) THB/ว่าง/— = บาท ที่เหลือใช้รหัสสกุลตรงๆ
function _finCurWord(cur) {
  const c = String(cur || '').toUpperCase();
  return (!c || c === 'THB' || c === '—' || c === 'บาท') ? 'บาท' : c;
}

// แกนสร้างตาราง P&L รายไตรมาส (ใช้ร่วมกัน 2 จุด: มุมมอง "📋 P&L รายไตรมาส" ผสาน 3 แหล่ง
// และตาราง "SET.or.th" ล้วนๆ ที่แทรกในแท็บ 🇹🇭 SET.or.th — ดู _loadSetQplTable) คืน
// {html, hasCoarse} ไม่รวมหัวการ์ด/scroll-to-latest เพื่อให้ผู้เรียกจัดวางเองได้ scrollId
// ต้องไม่ซ้ำกันถ้าทั้งสองตารางอาจอยู่บนหน้าพร้อมกัน (ปัจจุบันไม่ซ้ำเพราะคนละแท็บ แต่กันไว้)
function _qplTableCore(qs, scrollId, extraRowsFn) {
  // จัดกลุ่มตามปี พ.ศ. -> { 2565: [Q1,Q2,Q3,Q4], ... } ช่องที่ไม่มีข้อมูลเป็น null
  const byYear = {};
  qs.forEach(q => { (byYear[q.year_be] = byYear[q.year_be] || [null, null, null, null])[q.q - 1] = q; });
  const years = Object.keys(byYear).map(Number).sort((a, b) => a - b);
  const hasCoarse = qs.some(q => !q.detail);

  // % QoQ/YoY คำนวณจาก "ไตรมาสก่อนหน้าจริงในอนุกรมของหุ้นตัวเอง" (คีย์ year_be*4+q) ไม่ใช่ตำแหน่ง
  // ในตาราง กันกรณีมีไตรมาสขาดหาย (เช่นหุ้นเพิ่งเข้าตลาด) เทียบข้ามไตรมาสผิดโดยไม่รู้ตัว
  const byKey = {};
  qs.forEach(q => { byKey[q.year_be * 4 + q.q] = q; });
  // หารด้วย |ฐาน| แทน pv ตรงๆ — กันฐานติดลบ/ศูนย์พลิกทิศทาง % ผิดความหมาย (เช่น กำไรสุทธิ/
  // กำไรก่อนภาษี/ส่วนของผู้ถือหุ้นติดลบได้จริง) สอดคล้องกับ _qplYoySeries ของกราฟด้านบนและ
  // _pct_change ฝั่ง backend (compute_qpl_report/rollup_full_report_annual)
  const _qplChg = (getter, offset) => c => {
    const prev = byKey[c.year_be * 4 + c.q - offset];
    if (!prev) return null;
    const cur = getter(c), pv = getter(prev);
    if (cur == null || pv == null || !pv) return null;
    return (cur - pv) / Math.abs(pv) * 100;
  };
  const qoqOf = getter => _qplChg(getter, 1);
  const yoyOf = getter => _qplChg(getter, 4);

  const yearHead = years.map(y => `<th colspan="4" style="text-align:center;background:var(--bg3);color:var(--text);padding:6px 4px;border-bottom:1px solid var(--border);font-weight:700">${y}</th>`).join('');
  const qHead = years.map(y => [1, 2, 3, 4].map(qn => {
    const cell = byYear[y][qn - 1];
    const dim = cell && !cell.detail ? ';opacity:.65' : '';
    const mark = cell && !cell.detail ? ' †' : '';
    return `<th style="text-align:center;background:var(--bg2);color:var(--text2);padding:4px;border-bottom:1px solid var(--border);font-size:11px;font-weight:600${dim}">Q${qn}${mark}</th>`;
  }).join('')).join('');

  // สีเชิงความหมาย: รายได้/กำไร = ขาวหนา, ต้นทุน/ค่าใช้จ่าย = แดงอมชมพู (ดูจากรูปแบบตารางอ้างอิง)
  const COST_CLR = '#e2828f';
  const NET_ACCENT = '#4dabf7';

  const cellsOf = (getter, fmt, opts = {}) => years.map(y => [1, 2, 3, 4].map(qn => {
    const cell = byYear[y][qn - 1];
    const v = cell ? getter(cell) : null;
    const dim = cell && !cell.detail ? ';color:var(--text2)' : '';
    const boldStyle = opts.bold ? ';font-weight:700;color:var(--text)' : '';
    const costStyle = opts.costColor ? `;color:${COST_CLR}` : '';
    const pctColor = opts.pctColor && v != null ? `;color:${v > 0 ? 'var(--green)' : v < 0 ? 'var(--red)' : 'var(--text2)'}` : '';
    const accent = opts.topAccent ? `;border-top:2px solid ${NET_ACCENT}` : '';
    // ค่าที่ไม่ควรติดลบตามธรรมชาติ (สินทรัพย์/เงินสด/หนี้) แต่ติดลบจริง — เจอใน Finnomena raw
    // บางหุ้น (เช่น CHMOBILE, ATP30) เป็นข้อมูลต้นทางคลาดเคลื่อน ไม่ใช่ตัวเลขจริงของบริษัท
    const warn = opts.warnNegative && v != null && v < 0;
    const warnStyle = warn ? ';color:var(--red);font-weight:700' : '';
    const warnAttr = warn ? ' title="⚠ ค่านี้ติดลบผิดปกติ — น่าจะเป็นข้อมูลคลาดเคลื่อนจากต้นทาง (Finnomena/Yahoo) ไม่ใช่ตัวเลขจริงของบริษัท"' : '';
    return `<td class="r"${warnAttr} style="padding:4px 6px;border-bottom:1px solid #1c2128;font-size:12px${dim}${boldStyle}${costStyle}${pctColor}${accent}${warnStyle}">${warn ? '⚠ ' : ''}${cell ? fmt(v) : '—'}</td>`;
  }).join('')).join('');

  const row = (label, getter, fmt, opts = {}) => `<tr>
    <td style="padding:5px 8px;border-bottom:1px solid #1c2128;font-size:12.5px;white-space:nowrap${opts.bold ? ';font-weight:700;color:var(--text)' : ''}${opts.costColor ? `;color:${COST_CLR}` : ''}${opts.indent ? ';padding-left:18px;color:var(--text2)' : ''}${opts.topAccent ? `;border-top:2px solid ${NET_ACCENT}` : ''}">${label}</td>
    ${cellsOf(getter, fmt, opts)}
  </tr>`;

  // แถว %QoQ/%YoY คู่กันใต้แถวหลัก — ใช้ getter ของแถวหลักคำนวณจาก _qplChg เอง ไม่พึ่งฟิลด์ที่
  // backend ส่งมา (revenue_yoy/pretax_yoy เดิม) เพื่อให้มีครบทุกบรรทัดตัวเงินหลักสม่ำเสมอกัน
  const growthRows = getter => [
    row('% QoQ', qoqOf(getter), _qplPct, { indent: true, pctColor: true }),
    row('% YoY', yoyOf(getter), _qplPct, { indent: true, pctColor: true }),
  ].join('');

  const rowsHtml = [
    row('รายได้จากการขาย', c => c.revenue, _qplNum, { bold: true }),
    growthRows(c => c.revenue),
    row('ต้นทุนขาย', c => c.cogs, _qplNum, { costColor: true }),
    growthRows(c => c.cogs),
    row('กำไรขั้นต้น', c => c.gross_profit, _qplNum, { bold: true }),
    growthRows(c => c.gross_profit),
    row('% GPM', c => c.gpm, _qplPct, { indent: true }),
    row('ค่าใช้จ่ายในการขาย', c => c.selling_exp, _qplNum, { costColor: true }),
    row('% to Revenue', c => c.selling_pct, _qplPct, { indent: true }),
    row('ค่าใช้จ่ายในการบริหาร', c => c.admin_exp, _qplNum, { costColor: true }),
    row('% to Revenue', c => c.admin_pct, _qplPct, { indent: true }),
    row('รวม SG&A', c => c.sga_total, _qplNum, { costColor: true }),
    growthRows(c => c.sga_total),
    row('SG&A to Sales', c => c.sga_pct, _qplPct, { indent: true }),
    row('รวมค่าใช้จ่าย', c => c.total_expenses, _qplNum, { costColor: true }),
    row('กำไรจากการดำเนินงาน', c => c.operating_profit, _qplNum, { bold: true }),
    growthRows(c => c.operating_profit),
    row('ต้นทุนทางการเงิน', c => c.financial_cost, _qplNumNeg, { costColor: true }),
    row('กำไรก่อนภาษี', c => c.pretax_profit, _qplNum, { bold: true }),
    growthRows(c => c.pretax_profit),
    row('ค่าใช้จ่ายภาษีเงินได้', c => c.tax_expense, _qplNumNeg, { costColor: true }),
    row('% TAX', c => c.tax_pct == null ? null : -Math.abs(c.tax_pct), _qplPct, { indent: true }),
    row('กำไรสำหรับงวด', c => c.net_profit, _qplNum, { bold: true, topAccent: true }),
    growthRows(c => c.net_profit),
    row('% NPM', c => c.npm, _qplPct, { indent: true }),
  ].join('') + (extraRowsFn ? extraRowsFn(row, growthRows, years) : '');

  const caveat = hasCoarse ? `
    <div style="margin-top:10px;font-size:11.5px;color:var(--text2);line-height:1.6">
      † = ไตรมาสที่ไม่มีการแยกค่าใช้จ่ายขาย/บริหาร (แหล่งหยาบ เช่น Finnomena หรือ SET chart 5 ปี) — คำนวณต้นทุนขาย/กำไรจากการดำเนินงานเองจากอัตลักษณ์ทางบัญชีได้ (ตรงเป๊ะ)
      แต่ <b>แยกค่าใช้จ่ายขาย/บริหารไม่ได้ และอาจไม่มีต้นทุนทางการเงิน/กำไรก่อนภาษี/ภาษีเงินได้</b> — ปล่อยว่างไว้ ไม่ใช่ error
      แนะนำอ้างอิงเฉพาะรายได้/กำไรขั้นต้น/กำไรสุทธิสำหรับไตรมาสที่มีเครื่องหมาย †
    </div>` : '';

  const html = `
    <div id="${scrollId}" style="overflow-x:auto">
      <table class="tbl" style="border-collapse:collapse;min-width:600px">
        <thead>
          <tr><th style="border-bottom:1px solid var(--border);background:var(--bg3)"></th>${yearHead}</tr>
          <tr><th style="border-bottom:1px solid var(--border);background:var(--bg2)"></th>${qHead}</tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>
    ${caveat}`;
  return { html, hasCoarse };
}

// เลื่อนกล่อง overflow-x ของตาราง qpl ไปสุดขวา (ปีล่าสุด) เป็นค่าเริ่มต้น — ผู้ใช้เลื่อนซ้าย
// เองเพื่อย้อนดูปีเก่ากว่า รอ layout เสร็จก่อนด้วย rAF กัน scrollWidth ยังไม่นิ่งตอน DOM เพิ่งแทรก
// — ใช้ rAF ซ้อน 2 ชั้น (ไม่ใช่ชั้นเดียว) เพราะตารางเทียบหุ้นมีคอลัมน์ sticky ซ้ายสุดด้วย บาง
// เบราว์เซอร์คำนวณ scrollWidth ไม่นิ่งพอใน rAF แรกตอน DOM เพิ่งแทรกใหม่ๆ (ยิ่งตารางแถวเยอะ 50+)
function _qplScrollToLatest(scrollId) {
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const box = document.getElementById(scrollId);
      if (box) box.scrollLeft = box.scrollWidth;
    });
  });
}

// กราฟ "P&L CHANGE" — รายได้/ต้นทุน/กำไรขั้นต้น/กำไรสุทธิ · เทียบงวดเดียวกันปีก่อน (YoY, offset 4)
// หรือไตรมาสก่อนหน้าติดกัน (QoQ, offset 1) สลับด้วยปุ่ม — ใช้ในทั้งแท็บ 📋 P&L รายไตรมาส
// (_renderFinQplReport, 20Q ล่าสุด) และ 🧩 งบรวมทุกแหล่ง (_renderFinMergedReport รายไตรมาส —
// รายปีไม่มี QoQ) · 3 view นี้ไม่ render พร้อมกันใน #fin-result เลยใช้ canvas id เดียวกันได้
let _qplYoyChartInst = null;

// โหมดเทียบของกราฟ/heatmap รายไตรมาส (ตารางด้านล่างมี %QoQ + %YoY อยู่แล้วทั้งคู่ ปุ่มนี้คุมเฉพาะ
// กราฟเส้น P&L CHANGE + Heatmap + กราฟ Operating Leverage — ทั้งหมดสลับพร้อมกันด้วยปุ่มเดียว)
let _qplChgMode = 'yoy';   // 'yoy' | 'qoq'
let _finQplData = null;    // cache payload ของมุมมอง 📋 P&L รายไตรมาส (ให้ setQplChgMode วาดกราฟใหม่จาก cache)
const _qplChgOffset = () => _qplChgMode === 'qoq' ? 1 : 4;
const _qplChgLabel = () => _qplChgMode === 'qoq' ? 'QoQ' : 'YoY';

// แถวปุ่ม % YoY / % QoQ — วางเหนือกราฟ P&L CHANGE ทั้งมุมมอง 📋 และ 🧩 (เฉพาะโหมดรายไตรมาส)
function _qplChgToggleHtml() {
  const b = (m, lbl, rad) => `<button class="filter-btn${_qplChgMode === m ? ' active' : ''}" id="qpl-chg-${m}-btn" onclick="setQplChgMode('${m}')" style="border-radius:${rad};font-size:11px;padding:4px 10px">${lbl}</button>`;
  return `<div class="filter-row" style="gap:0;margin:0 0 8px" title="YoY = เทียบไตรมาสเดียวกันปีก่อน (ตัดผลฤดูกาล) · QoQ = เทียบไตรมาสก่อนหน้าติดกัน — ระวังหุ้นมีฤดูกาลแกว่งตามฤดู">
    ${b('yoy', '% YoY', '6px 0 0 6px')}${b('qoq', '% QoQ', '0 6px 6px 0')}
  </div>`;
}

// สลับ YoY/QoQ แล้ว re-render กราฟตามมุมมองที่กำลังโชว์อยู่ (🧩 งบรวมทุกแหล่ง มี #fin-merged-period-q,
// 📋 P&L รายไตรมาส มี #qpl-scroll) — re-render จาก cache ไม่ fetch ใหม่ (เหมือน setFinMergedPeriod)
function setQplChgMode(mode) {
  if (mode !== 'yoy' && mode !== 'qoq') return;
  _qplChgMode = mode;
  document.querySelectorAll('#qpl-chg-yoy-btn,#qpl-chg-qoq-btn').forEach(x =>
    x.classList.toggle('active', x.id === `qpl-chg-${mode}-btn`));
  document.querySelectorAll('#qpl-chg-title').forEach(x => { x.textContent = _qplChgLabel(); });
  if (document.getElementById('fin-merged-period-q')) {
    if (_finMergedData) _renderFinMergedReport(_finMergedData);
  } else if (document.getElementById('qpl-scroll') && _finQplData) {
    _drawQplYoyChart(_finQplData.quarters || [], 'qpl-yoy-chart');
  }
}

// offset: 4 = YoY (ไตรมาสเดียวกันปีก่อน, ค่าเริ่มต้น) · 1 = QoQ (ไตรมาสก่อนหน้าติดกัน)
function _qplYoySeries(sortedQs, field, offset = 4) {
  const byKey = {};
  sortedQs.forEach(q => { byKey[q.year_be * 4 + q.q] = q; });
  return sortedQs.map(c => {
    const prev = byKey[c.year_be * 4 + c.q - offset];
    if (!prev) return null;
    const cur = c[field], pv = prev[field];
    if (cur == null || pv == null || !pv) return null;
    // หารด้วย |ฐาน| แทน pv ตรงๆ — กันฐานติดลบพลิกทิศทาง % ผิดความหมาย (เช่น ขาดทุนน้อยลงจาก
    // -545 ลบ. → -39 ลบ. ควรเป็น "ดีขึ้น" +% ไม่ใช่ -93% ที่ดูเหมือนแย่ลง) สอดคล้องกับ _pct_change
    // ฝั่ง backend (compute_qpl_report/rollup_full_report_annual ใน sources/financials_store.py)
    return parseFloat(((cur - pv) / Math.abs(pv) * 100).toFixed(1));
  });
}

function _qplYoySeriesAnnual(sortedYears, field) {
  const byYear = {};
  sortedYears.forEach(y => { byYear[y.year_ad] = y; });
  return sortedYears.map(y => {
    const prev = byYear[y.year_ad - 1];
    if (!prev) return null;
    const cur = y[field], pv = prev[field];
    if (cur == null || pv == null || !pv) return null;
    // ดูเหตุผลหารด้วย |ฐาน| ใน _qplYoySeries ด้านบน
    return parseFloat(((cur - pv) / Math.abs(pv) * 100).toFixed(1));
  });
}

// กำไรขั้นต้น: โชว์เป็น margin ตรงๆ (gross_profit/revenue) แทน YoY% growth — อ่านง่ายกว่าและ
// ไม่ผันผวนตามฐานปีก่อนเหมือน YoY, เข้าคู่กับแกน y1 (ขวา) ของกราฟ
function _gpmSeries(sortedQs) {
  return sortedQs.map(c => {
    const rev = c.revenue, gp = c.gross_profit;
    if (rev == null || gp == null || !rev) return null;
    return parseFloat((gp / rev * 100).toFixed(1));
  });
}

function _gpmSeriesAnnual(sortedYears) {
  return sortedYears.map(y => {
    const rev = y.revenue, gp = y.gross_profit;
    if (rev == null || gp == null || !rev) return null;
    return parseFloat((gp / rev * 100).toFixed(1));
  });
}

// Operating Margin (OPM%) — เหมือน GPM/NPM แต่ backend ไม่ได้คำนวณสำเร็จรูปมาให้ (มีแค่ gpm/npm
// ดู compute_qpl_report ใน sources/financials_store.py) เลยคำนวณฝั่ง client เอง
function _opmSeries(sortedQs) {
  return sortedQs.map(c => {
    const rev = c.revenue, op = c.operating_profit;
    if (rev == null || op == null || !rev) return null;
    return parseFloat((op / rev * 100).toFixed(1));
  });
}
function _opmSeriesAnnual(sortedYears) {
  return sortedYears.map(y => {
    const rev = y.revenue, op = y.operating_profit;
    if (rev == null || op == null || !rev) return null;
    return parseFloat((op / rev * 100).toFixed(1));
  });
}

// หน่วย 'พันบาท' เหมือนตาราง (_qplNum หารด้วย 1000 ตอนแสดงผล) — ใช้กับกราฟระดับ (ไม่ใช่ %) ทุกกราฟ
// ด้านล่าง (โครงสร้างหนี้/เงินสด/ทุน, CFO vs กำไรสุทธิ, Net Debt) ให้สเกลตรงกับตาราง
function _toKb(v) { return v == null ? null : v / 1000; }
function _kbFieldSeries(rows, key) { return rows.map(c => _toKb(c[key])); }

// Net Debt = หนี้มีภาระดอกเบี้ย - เงินสด (ติดลบ = เงินสดมากกว่าหนี้ สถานะการเงินสุทธิเป็นบวก)
function _netDebtSeries(rows) {
  return rows.map(c => (c.total_debt == null || c.cash == null) ? null : _toKb(c.total_debt - c.cash));
}

// ROE รายไตรมาส ใช้กำไรสุทธิสะสม TTM (4 ไตรมาสล่าสุดรวมไตรมาสนี้) หารด้วยส่วนผู้ถือหุ้น ณ ไตรมาสนี้
// แทนกำไรไตรมาสเดียว — เพราะส่วนผู้ถือหุ้นเป็นยอดสะสม (stock) เทียบกับกำไรไตรมาสเดียว (flow) ตรงๆ จะ
// ได้ตัวเลขเล็กเกินจริงและแกว่งตามฤดูกาลธุรกิจ ต้องมีกำไรครบ 4 ไตรมาสก่อนหน้า (รวมตัวเอง) เท่านั้นถึงคำนวณ
function _roeSeriesTtm(sortedQs) {
  const byKey = {};
  sortedQs.forEach(c => { byKey[c.year_be * 4 + c.q] = c; });
  return sortedQs.map(c => {
    const eq = c.total_equity;
    if (eq == null || !eq) return null;
    let sum = 0;
    for (let off = 0; off < 4; off++) {
      const p = byKey[c.year_be * 4 + c.q - off];
      if (!p || p.net_profit == null) return null;
      sum += p.net_profit;
    }
    return parseFloat((sum / eq * 100).toFixed(1));
  });
}
function _roeSeriesAnnual(sortedYears) {
  return sortedYears.map(y => {
    const eq = y.total_equity, np = y.net_profit;
    if (eq == null || np == null || !eq) return null;
    return parseFloat((np / eq * 100).toFixed(1));
  });
}

// หนี้สินต่อทุน (D/E Ratio %) = total_debt/total_equity — สูตรเดียวกันทั้งรายไตรมาส/รายปี (ต่างจาก
// ROE ที่ต้องพิเศษ TTM เฉพาะรายไตรมาส เพราะ D/E เทียบยอดคงเหลือ (stock) กับยอดคงเหลือ (stock) ไม่ใช่
// กำไรสะสม (flow) กับยอดคงเหลือ เลยใช้ฟังก์ชันเดียวรับได้ทั้งแถวรายไตรมาส/รายปี (field ชื่อเดียวกัน)
function _deRatioSeries(rows) {
  return rows.map(c => (c.total_debt == null || c.total_equity == null || !c.total_equity)
    ? null : parseFloat((c.total_debt / c.total_equity * 100).toFixed(1)));
}

// FCF (กระแสเงินสดอิสระ) = CFO - |CapEx| — capex เก็บมาจาก Yahoo/Finnomena เป็นค่าลบ (เงินสดไหลออก)
// ตามธรรมเนียมงบกระแสเงินสด เลย abs() ก่อนหักเสมอกันเผลอบวกซ้ำถ้าบางงวดเก็บเป็นค่าบวก
function _fcfSeries(rows) {
  return rows.map(c => (c.cfo == null || c.capex == null) ? null : _toKb(c.cfo - Math.abs(c.capex)));
}

// Inventory Turnover (รอบ, rolling TTM) = COGS TTM ÷ สินค้าคงเหลือเฉลี่ย (ต้น-ปลายงวด TTM) — สูตร
// เดียวกับ 'inventory_turnover' ใน /api/peer-group-detail (app.py) แต่คืนเป็น series ทุกไตรมาส
// แทนค่าล่าสุดค่าเดียว ต้องมีครบ 4 ไตรมาสติดกันของ COGS ถึงจะคำนวณ (เข้มงวดแบบเดียวกับ ROE TTM ด้านบน)
function _inventoryTurnoverSeries(sortedQs) {
  const byKey = {};
  sortedQs.forEach(c => { byKey[c.year_be * 4 + c.q] = c; });
  return sortedQs.map(c => {
    let cogsSum = 0;
    for (let off = 0; off < 4; off++) {
      const p = byKey[c.year_be * 4 + c.q - off];
      if (!p || p.cogs == null) return null;
      cogsSum += p.cogs;
    }
    if (c.inventory == null) return null;
    const start = byKey[c.year_be * 4 + c.q - 4];
    const invAvg = (start && start.inventory != null) ? (c.inventory + start.inventory) / 2 : c.inventory;
    return invAvg ? parseFloat((cogsSum / invAvg).toFixed(2)) : null;
  });
}

// จำกัดขอบเขตแกน YoY% ไม่ให้ตัวที่กระโดดสุดขั้ว (เช่น กำไรสุทธิ YoY 700%) บีบเส้นอื่นจนแบนติดพื้น
// cap = median ของ |ค่า| ทั้งหมด x 4 (อย่างน้อย ±60%) แล้ว clamp จุดที่เกิน cap ไว้ที่ขอบแกน
// ค่าจริงยังโชว์ผ่าน tooltip (rawData) และจุดที่ถูก clamp จะเปลี่ยน pointStyle เป็นสี่เหลี่ยมข้าวหลามตัด
function _clampYoyOutliers(seriesArrays) {
  const vals = [];
  seriesArrays.forEach(arr => arr.forEach(v => { if (v != null) vals.push(Math.abs(v)); }));
  if (!vals.length) return null;
  vals.sort((a, b) => a - b);
  const median = vals[Math.floor(vals.length / 2)];
  const cap = Math.max(median * 4, 60);
  const maxVal = Math.max(...vals);
  return maxVal > cap ? cap : null; // ไม่มีตัวไหนหลุด cap ก็ไม่ต้อง clamp
}

function _clampForChart(arr, cap) {
  if (cap == null) return { data: arr, raw: arr, pointStyle: undefined, pointRadius: undefined };
  const data = arr.map(v => v == null ? null : Math.max(-cap, Math.min(cap, v)));
  const pointStyle = arr.map(v => (v != null && Math.abs(v) > cap) ? 'rectRot' : 'circle');
  const pointRadius = arr.map(v => (v != null && Math.abs(v) > cap) ? 5 : 3);
  return { data, raw: arr, pointStyle, pointRadius };
}

// วาดค่าจริงค้างไว้บนจุดที่โดน clamp ตรงๆ บนกราฟ (ไม่ต้อง hover) — สโคปแค่ chart instance นี้ผ่าน
// `plugins: []` ระดับ config ไม่ใช่ Chart.register แบบ global กัน conflict กับกราฟอื่นในหน้า
// ไตรมาสที่กระโดดติดกันหลายไตรมาส (เช่นสไปค์ยาว 4-5Q) จะโดน clamp ที่ค่าใกล้เคียงกันหมด ถ้าติด label
// ทุกจุดจะทับกันอ่านไม่ออก เลยยุบ "ช่วงที่ต่อเนื่องกัน" ต่อเส้นให้เหลือ label เดียวตรงจุดพีค (ค่าจริงสูงสุด
// ของช่วงนั้น) แล้วยังกันชนข้ามเส้น/ข้ามช่วงด้วยการข้าม label ที่ตำแหน่ง x ใกล้ label ก่อนหน้าเกินไป
const _qplClampLabelPlugin = {
  id: 'qplClampLabels',
  afterDatasetsDraw(chart) {
    const { ctx } = chart;
    const peaks = [];
    chart.data.datasets.forEach((ds, dsIndex) => {
      if (!ds.rawData) return;
      const meta = chart.getDatasetMeta(dsIndex);
      if (meta.hidden) return;
      let run = [];
      const flushRun = () => {
        if (!run.length) return;
        run.sort((a, b) => Math.abs(b.raw) - Math.abs(a.raw));
        peaks.push(run[0]);
        run = [];
      };
      meta.data.forEach((point, i) => {
        const raw = ds.rawData[i];
        const val = ds.data[i];
        if (raw == null || val == null || raw === val) { flushRun(); return; } // ไม่ถูก clamp = จบช่วง
        run.push({ point, raw, above: raw > val, color: ds.borderColor });
      });
      flushRun();
    });

    peaks.sort((a, b) => a.point.x - b.point.x);
    ctx.save();
    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    const lastRight = { above: -Infinity, below: -Infinity };
    peaks.forEach(({ point, raw, above, color }) => {
      const lane = above ? 'above' : 'below';
      const text = `${raw > 0 ? '+' : ''}${raw.toFixed(0)}%`;
      const halfW = ctx.measureText(text).width / 2;
      if (point.x - halfW < lastRight[lane] + 4) return; // ใกล้ label ก่อนหน้าเลนเดียวกันเกินไป ข้าม
      ctx.fillStyle = color;
      ctx.fillText(text, point.x, above ? point.y - 8 : point.y + 14);
      lastRight[lane] = point.x + halfW;
    });
    ctx.restore();
  }
};

// วาดกราฟจริงจาก labels/series ที่คำนวณ YoY/QoQ มาแล้ว (ใช้ร่วมกันทั้งมุมมองรายไตรมาส/รายปี)
// chgLabel = 'YoY' | 'QoQ' — ป้ายเส้น/แกน (รายปีส่ง 'YoY' เสมอ)
function _renderYoyLineChart(canvasId, labels, seriesMap, chgLabel = 'YoY') {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  if (_qplYoyChartInst) { _qplYoyChartInst.destroy(); _qplYoyChartInst = null; }
  if (!labels.length || !Object.values(seriesMap).some(s => s.some(v => v != null))) return;

  const mkDataset = (label, data, color, extra = {}) => ({
    label, data,
    borderColor: color,
    backgroundColor: color,
    borderWidth: 2,
    pointRadius: 3,
    pointHoverRadius: 5,
    tension: 0.25,
    spanGaps: true,
    fill: false,
    yAxisID: 'y',
    ...extra,
  });

  // clamp เฉพาะ 3 เส้น YoY% (รายได้/ต้นทุน/กำไรสุทธิ) ที่แชร์แกนซ้ายด้วยกัน — กำไรขั้นต้น (GPM%)
  // อยู่คนละแกน (y1) อยู่แล้วไม่โดนบีบ
  const cap = _clampYoyOutliers([seriesMap.rev, seriesMap.cogs, seriesMap.np]);
  const revC  = _clampForChart(seriesMap.rev, cap);
  const cogsC = _clampForChart(seriesMap.cogs, cap);
  const npC   = _clampForChart(seriesMap.np, cap);

  _qplYoyChartInst = new Chart(canvas, {
    type: 'line',
    plugins: [_qplClampLabelPlugin],
    data: {
      labels,
      datasets: [
        mkDataset(`รายได้ ${chgLabel}%`, revC.data, '#4dabf7', { rawData: revC.raw, pointStyle: revC.pointStyle, pointRadius: revC.pointRadius }),
        mkDataset(`ต้นทุน ${chgLabel}%`, cogsC.data, '#e2828f', { rawData: cogsC.raw, pointStyle: cogsC.pointStyle, pointRadius: cogsC.pointRadius }),
        mkDataset('กำไรขั้นต้น (GPM%)', seriesMap.gp, '#e8b84b', { yAxisID: 'y1' }),
        mkDataset(`กำไรสุทธิ ${chgLabel}%`, npC.data, '#3fb950', { rawData: npC.raw, pointStyle: npC.pointStyle, pointRadius: npC.pointRadius }),
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      layout: { padding: { top: 16, bottom: 16 } },
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { labels: { color: '#8b949e', font: { size: 11 }, boxWidth: 14, padding: 14 } },
        tooltip: {
          backgroundColor: '#1c2128', borderColor: '#30363d', borderWidth: 1,
          titleColor: '#e6edf3', bodyColor: '#8b949e',
          callbacks: {
            label: ctx => {
              const ds = ctx.dataset;
              const raw = ds.rawData ? ds.rawData[ctx.dataIndex] : ctx.raw;
              if (raw == null) return null;
              const isGpm = ds.yAxisID === 'y1';
              const sign = !isGpm && raw > 0 ? '+' : '';
              const clipped = cap != null && !isGpm && Math.abs(raw) > cap ? ' (เกินขอบแกน)' : '';
              return ` ${ds.label}: ${sign}${raw.toFixed(1)}%${clipped}`;
            }
          }
        }
      },
      scales: {
        x: { ticks: { color: '#8b949e', font: { size: 10 } }, grid: { color: '#1e2736' } },
        y: {
          position: 'left',
          ticks: { color: '#8b949e', font: { size: 10 }, callback: v => v + '%' },
          grid: { color: '#1e2736' },
          title: { display: true, text: `${chgLabel}%`, color: '#8b949e', font: { size: 10 } }
        },
        y1: {
          position: 'right',
          ticks: { color: '#8b949e', font: { size: 10 }, callback: v => v + '%' },
          grid: { drawOnChartArea: false },
          title: { display: true, text: 'GPM%', color: '#8b949e', font: { size: 10 } }
        }
      }
    }
  });
}

// กราฟตัวชี้วัดเพิ่มเติม 5 ตัวใน 🧩 งบรวมทุกแหล่ง (OPM/NPM, โครงสร้างหนี้-เงินสด-ทุน, CFO vs กำไรสุทธิ,
// Net Debt, ROE) — เก็บ instance แยก keyed by canvasId (ต่างจาก _qplYoyChartInst ตัวเดียวของกราฟหลัก
// เพราะมีหลายกราฟพร้อมกันบนหน้าเดียว) ต้อง destroy ก่อน redraw ทุกครั้งที่สลับ toggle รายไตรมาส/รายปี
let _finExtraChartInsts = {};
function _destroyExtraChart(id) {
  if (_finExtraChartInsts[id]) { _finExtraChartInsts[id].destroy(); _finExtraChartInsts[id] = null; }
}

// เปิด/ปิด caption เตือนใต้กราฟตัวชี้วัดเพิ่มเติม (ใช้ร่วมกับ warnFlags ใน _renderMetricChart) —
// element เป็น <div style="display:none"> เปล่าใน template อยู่แล้ว (ดู _renderFinMergedReport)
// no-op ถ้าไม่มี element (view อื่นกำลังโชว์อยู่) เหมือน _renderMetricChart
function _setChartWarnCaveat(elId, show, text) {
  const el = document.getElementById(elId);
  if (!el) return;
  el.style.display = show ? '' : 'none';
  el.textContent = show ? text : '';
}

// กราฟทั่วไปสำหรับตัวชี้วัดเพิ่มเติม — ไม่มีแกนคู่เหมือน _renderYoyLineChart (แต่ละกราฟใช้หน่วยเดียว
// ทั้งหมดในตัวมันเอง) pct=true ควบคุมฟอร์แมตแกน y/tooltip เป็น % แทนตัวเลขพันบาท · type='bar' ใช้กับ
// กราฟที่อ่านง่ายกว่าเป็นแท่ง (เช่น Operating Leverage) · unit ใช้กับ series ที่ไม่ใช่ % และไม่ใช่
// เงิน (เช่น Inventory Turnover หน่วย "รอบ") แทนที่ label ตัวเลข/tooltip เริ่มต้น "พันบาท"
function _renderMetricChart(canvasId, labels, datasets, { pct = false, type = 'line', unit } = {}) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  _destroyExtraChart(canvasId);
  const hasData = labels.length && datasets.some(ds => ds.data.some(v => v != null));
  if (!hasData) return;

  _finExtraChartInsts[canvasId] = new Chart(canvas, {
    type,
    data: {
      labels,
      // warnFlags (optional, ขนาดเท่า data) = จุดที่ต้องเตือนผู้ใช้เป็นพิเศษ (เช่น D/E Ratio/ROE ตอน
      // total_equity ติดลบ, Inventory Turnover ตอน inventory ติดลบ — ค่าที่ได้สลับเครื่องหมายผิด
      // ทางอ่านตรงๆ ไม่ได้) วาดเป็นจุดสีแดงรูปข้าวหลามตัดแทนวงกลมปกติ (คอนเซ็ปต์เดียวกับจุด clamp ใน
      // _renderYoyLineChart) · warnLabel (optional) = ข้อความ prefix ใน tooltip เฉพาะกราฟนั้น
      // (ต่างกราฟมีสาเหตุติดลบไม่เหมือนกัน) ไม่ใส่ = ใช้ข้อความกลาง
      datasets: datasets.map(ds => type === 'bar' ? {
        label: ds.label, data: ds.data,
        backgroundColor: ds.color, borderColor: ds.color, borderWidth: 1,
      } : {
        label: ds.label, data: ds.data,
        borderColor: ds.color, backgroundColor: ds.color,
        borderWidth: 2,
        pointRadius: ds.warnFlags ? ds.data.map((v, i) => ds.warnFlags[i] ? 6 : 3) : 3,
        pointHoverRadius: 6,
        pointBackgroundColor: ds.warnFlags ? ds.data.map((v, i) => ds.warnFlags[i] ? '#f85149' : ds.color) : ds.color,
        pointBorderColor: ds.warnFlags ? ds.data.map((v, i) => ds.warnFlags[i] ? '#f85149' : ds.color) : ds.color,
        pointStyle: ds.warnFlags ? ds.data.map((v, i) => ds.warnFlags[i] ? 'rectRot' : 'circle') : 'circle',
        tension: 0.25, spanGaps: true, fill: false,
        warnFlags: ds.warnFlags, warnLabel: ds.warnLabel || 'ค่านี้ผิดปกติ',
      }),
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { labels: { color: '#8b949e', font: { size: 10 }, boxWidth: 12, padding: 10 } },
        tooltip: {
          backgroundColor: '#1c2128', borderColor: '#30363d', borderWidth: 1,
          titleColor: '#e6edf3', bodyColor: '#8b949e',
          callbacks: {
            label: ctx => {
              const v = ctx.raw;
              if (v == null) return null;
              const warn = ctx.dataset.warnFlags && ctx.dataset.warnFlags[ctx.dataIndex] ? `⚠ ${ctx.dataset.warnLabel} — ` : '';
              if (pct) return ` ${warn}${ctx.dataset.label}: ${v > 0 ? '+' : ''}${v.toFixed(1)}%`;
              if (unit) return ` ${warn}${ctx.dataset.label}: ${v.toFixed(2)} ${unit}`;
              return ` ${warn}${ctx.dataset.label}: ${Math.round(v).toLocaleString('en-US')} พันบาท`;
            }
          }
        }
      },
      scales: {
        x: { ticks: { color: '#8b949e', font: { size: 9 } }, grid: { color: '#1e2736' } },
        y: {
          ticks: { color: '#8b949e', font: { size: 9 }, callback: v => pct ? v + '%' : (unit ? Number(v).toFixed(1) : Number(v).toLocaleString('en-US')) },
          grid: { color: '#1e2736' },
        }
      }
    }
  });
}

// เรียงตามลำดับไตรมาสจริง (year_be*4+q) ก่อนคำนวณ YoY/QoQ ให้ครบ แล้วค่อยตัดโชว์ 20 ไตรมาสหลังสุด
// (คำนวณจากชุดเต็มก่อนตัด กัน 4 ไตรมาสแรกของ window ขาด prev ที่จริงๆ มีอยู่นอก window) —
// offset ตาม _qplChgMode (YoY=4 / QoQ=1)
function _drawQplYoyChart(qs, canvasId) {
  const sorted = [...qs].sort((a, b) => (a.year_be * 4 + a.q) - (b.year_be * 4 + b.q));
  if (!sorted.length) return;
  const N = 20;
  const from = Math.max(0, sorted.length - N);
  const off = _qplChgOffset();
  const revYoy  = _qplYoySeries(sorted, 'revenue', off).slice(from);
  const cogsYoy = _qplYoySeries(sorted, 'cogs', off).slice(from);
  const gpm     = _gpmSeries(sorted).slice(from);
  const npYoy   = _qplYoySeries(sorted, 'net_profit', off).slice(from);
  const labels  = sorted.slice(from).map(c => `${c.q}Q${String(c.year_be).slice(-2)}`);
  _renderYoyLineChart(canvasId, labels, { rev: revYoy, cogs: cogsYoy, gp: gpm, np: npYoy }, _qplChgLabel());
}

// มุมมองรายปีของ 🧩 งบรวมทุกแหล่ง — เทียบ year_ad กับปีก่อนหน้าตรงๆ (ไม่มี Q ให้ชดเชยไตรมาสขาดหาย
// เหมือนฝั่งรายไตรมาส) ปีที่ complete===false ใส่ * กำกับเหมือนตารางรายปี (_mergedTableAnnual)
function _drawQplYoyChartAnnual(years, canvasId) {
  const sorted = [...years].sort((a, b) => a.year_ad - b.year_ad);
  if (!sorted.length) return;
  const N = 15;
  const from = Math.max(0, sorted.length - N);
  const revYoy  = _qplYoySeriesAnnual(sorted, 'revenue').slice(from);
  const cogsYoy = _qplYoySeriesAnnual(sorted, 'cogs').slice(from);
  const gpm     = _gpmSeriesAnnual(sorted).slice(from);
  const npYoy   = _qplYoySeriesAnnual(sorted, 'net_profit').slice(from);
  const labels  = sorted.slice(from).map(y => `${y.year_be}${y.complete ? '' : '*'}`);
  _renderYoyLineChart(canvasId, labels, { rev: revYoy, cogs: cogsYoy, gp: gpm, np: npYoy });
}

// วาดกราฟตัวชี้วัดเพิ่มเติมใน 🧩 งบรวมทุกแหล่ง — เฉพาะแท็บนี้เพราะต้องใช้ฟิลด์งบดุล/กระแสเงินสด
// (total_debt/cash/total_equity/cfo ฯลฯ) ที่มุมมอง 📋 P&L รายไตรมาส ไม่มี (ดู compute_full_report
// vs compute_qpl_report ใน sources/financials_store.py) canvas id คงที่ เรียก _renderMetricChart
// ต่อกราฟ ถ้า element ไม่มี (view อื่นกำลังโชว์อยู่) ฟังก์ชันข้างในจะ no-op เอง · arSales/invTurn/depPct
// วาดเฉพาะรายไตรมาส (period==='q') เพราะ d.years (รายปี) ไม่มี field accounts_receivable/
// inventory/current_assets/current_liabilities/capex เลย (ดู _BSCF_FLOW_FIELDS/_BSCF_STOCK_FIELDS
// ใน rollup_full_report_annual — ไม่ครอบคลุม field เหล่านี้) canvas ของ 3 ตัวนี้เลยถูกซ่อนไปเองที่
// _renderFinMergedReport (ไม่ถูกสร้างใน DOM เวลาโหมดรายปี) _renderMetricChart จะ no-op เพราะหา
// element ไม่เจอ ไม่ error
const _FIN_EXTRA_CHART_IDS = {
  opmNpm: 'fin-chart-opm-npm', opLev: 'fin-chart-oplev', debt: 'fin-chart-debt',
  cfoNp: 'fin-chart-cfo-np', netDebt: 'fin-chart-netdebt', roe: 'fin-chart-roe',
  de: 'fin-chart-de', sga: 'fin-chart-sga',
  arSales: 'fin-chart-arsales', invTurn: 'fin-chart-invturn', depPct: 'fin-chart-deppct',
};

// canvas id ที่มี caption เตือนใต้กราฟ (element "<id>-warn" ต้องถูกสร้างไว้ใน template ของ
// _renderFinMergedReport ด้วย) — กราฟที่ตัวหารมี "ค่าติดลบ" ที่อ่านผิดทางได้ (D/E Ratio/ROE ตอน
// total_equity ติดลบ, Inventory Turnover ตอน inventory ติดลบ) ดู _setChartWarnCaveat
const _FIN_CHART_WARN_IDS = new Set(['fin-chart-de', 'fin-chart-roe', 'fin-chart-invturn']);

function _drawFinExtraCharts(rows, period) {
  const ids = _FIN_EXTRA_CHART_IDS;
  if (!rows.length) return;

  let sorted, win, labels;
  if (period === 'q') {
    sorted = [...rows].sort((a, b) => (a.year_be * 4 + a.q) - (b.year_be * 4 + b.q));
    const from = Math.max(0, sorted.length - 20);
    win = sorted.slice(from);
    labels = win.map(c => `${c.q}Q${String(c.year_be).slice(-2)}`);
    _renderMetricChart(ids.opmNpm, labels, [
      { label: 'Operating Margin (OPM%)', color: '#4dabf7', data: _opmSeries(sorted).slice(from) },
      { label: 'Net Margin (NPM%)', color: '#3fb950', data: win.map(c => c.npm) },
    ], { pct: true });
    // total_equity ติดลบทำให้ ROE สลับเครื่องหมายผิดทางแบบเดียวกับ D/E (ดู comment ใหญ่ที่ D/E
    // ด้านล่าง) แต่อันตรายกว่าเพราะ "negative ROE trap": กำไรบวก+equity ลบ = ROE โชว์ติดลบ (ดูแย่
    // ทั้งที่กำลังดีขึ้น) หรือขาดทุน+equity ลบ = ลบ/ลบ = ROE โชว์บวกสูงลิ่ว (ดูดีทั้งที่จริงคือหายนะ)
    const roeEqNegQ = win.map(c => c.total_equity != null && c.total_equity < 0);
    _renderMetricChart(ids.roe, labels, [
      { label: 'ROE (TTM %)', color: '#8b2fc9', data: _roeSeriesTtm(sorted).slice(from), warnFlags: roeEqNegQ, warnLabel: 'ส่วนผู้ถือหุ้นติดลบ (negative ROE trap)' },
    ], { pct: true });
    _setChartWarnCaveat('fin-chart-roe-warn', roeEqNegQ.some(Boolean),
      '⚠ จุดสีแดง = ส่วนของผู้ถือหุ้นติดลบช่วงนั้น — ROE ที่โชว์อาจสลับเครื่องหมายผิดทาง (negative ROE trap) อย่าอ่านตัวเลขตรงๆ');
    const olOff = _qplChgOffset(), olLbl = _qplChgLabel();
    _renderMetricChart(ids.opLev, labels, [
      { label: `รายได้ ${olLbl}%`, color: '#4dabf7', data: _qplYoySeries(sorted, 'revenue', olOff).slice(from) },
      { label: `กำไรสุทธิ ${olLbl}%`, color: '#3fb950', data: _qplYoySeries(sorted, 'net_profit', olOff).slice(from) },
    ], { pct: true, type: 'bar' });
    _renderMetricChart(ids.arSales, labels, [
      { label: 'AR / ยอดขาย %', color: '#e8b84b', data: win.map(c => (c.accounts_receivable != null && c.revenue) ? parseFloat((c.accounts_receivable / c.revenue * 100).toFixed(1)) : null) },
    ], { pct: true });
    // สินค้าคงเหลือติดลบไม่มีความหมายทางบัญชีที่ถูกต้อง (ต่างจาก total_equity ที่ติดลบได้จริง) —
    // เกิดจากข้อมูลต้นทาง Finnomena/Yahoo คลาดเคลื่อนเท่านั้น (แพทเทิร์นเดียวกับ total_assets/
    // total_debt/cash ใน _mergedBsCfRowDefs) แต่ถ้าเกิดขึ้นจะทำให้ Inventory Turnover สลับ
    // เครื่องหมายผิดทางเหมือน D/E Ratio ทำเครื่องหมายเตือนไว้เผื่อเจอเช่นกัน
    const invNegQ = win.map(c => c.inventory != null && c.inventory < 0);
    _renderMetricChart(ids.invTurn, labels, [
      { label: 'Inventory Turnover', color: '#4dabf7', data: _inventoryTurnoverSeries(sorted).slice(from), warnFlags: invNegQ, warnLabel: 'สินค้าคงเหลือติดลบ (ข้อมูลต้นทางน่าจะคลาดเคลื่อน)' },
    ], { unit: 'รอบ' });
    _setChartWarnCaveat('fin-chart-invturn-warn', invNegQ.some(Boolean),
      '⚠ จุดสีแดง = สินค้าคงเหลือติดลบช่วงนั้น (ไม่ปกติทางบัญชี น่าจะเป็นข้อมูลคลาดเคลื่อนจากต้นทาง) — Inventory Turnover ที่โชว์ไม่น่าเชื่อถือ');
    _renderMetricChart(ids.depPct, labels, [
      { label: 'Depreciation % ของรายได้', color: '#8b2fc9', data: win.map(c => (c.da != null && c.revenue) ? parseFloat((c.da / c.revenue * 100).toFixed(1)) : null) },
    ], { pct: true });
  } else {
    sorted = [...rows].sort((a, b) => a.year_ad - b.year_ad);
    const from = Math.max(0, sorted.length - 15);
    win = sorted.slice(from);
    labels = win.map(y => `${y.year_be}${y.complete ? '' : '*'}`);
    _renderMetricChart(ids.opmNpm, labels, [
      { label: 'Operating Margin (OPM%)', color: '#4dabf7', data: _opmSeriesAnnual(win) },
      { label: 'Net Margin (NPM%)', color: '#3fb950', data: win.map(y => y.npm) },
    ], { pct: true });
    const roeEqNegY = win.map(y => y.total_equity != null && y.total_equity < 0);
    _renderMetricChart(ids.roe, labels, [
      { label: 'ROE (%)', color: '#8b2fc9', data: _roeSeriesAnnual(win), warnFlags: roeEqNegY, warnLabel: 'ส่วนผู้ถือหุ้นติดลบ (negative ROE trap)' },
    ], { pct: true });
    _setChartWarnCaveat('fin-chart-roe-warn', roeEqNegY.some(Boolean),
      '⚠ จุดสีแดง = ส่วนของผู้ถือหุ้นติดลบปีนั้น — ROE ที่โชว์อาจสลับเครื่องหมายผิดทาง (negative ROE trap) อย่าอ่านตัวเลขตรงๆ');
    _renderMetricChart(ids.opLev, labels, [
      { label: 'รายได้ YoY%', color: '#4dabf7', data: _qplYoySeriesAnnual(sorted, 'revenue').slice(from) },
      { label: 'กำไรสุทธิ YoY%', color: '#3fb950', data: _qplYoySeriesAnnual(sorted, 'net_profit').slice(from) },
    ], { pct: true, type: 'bar' });
  }

  _renderMetricChart(ids.debt, labels, [
    { label: 'หนี้มีภาระดอกเบี้ย', color: '#e2828f', data: _kbFieldSeries(win, 'total_debt') },
    { label: 'เงินสด', color: '#3fb950', data: _kbFieldSeries(win, 'cash') },
    { label: 'ส่วนของผู้ถือหุ้น', color: '#4dabf7', data: _kbFieldSeries(win, 'total_equity') },
  ]);
  // FCF ต้องใช้ field 'capex' ซึ่งข้อมูลรายปี (rollup_full_report_annual) ไม่มีให้ (ดู
  // _BSCF_FLOW_FIELDS ใน financials_store.py — ครอบแค่ cfo/cfi/cff/da) ใส่เส้น FCF เฉพาะรายไตรมาส
  // ไม่งั้น _fcfSeries จะคืน null ทุกจุดเงียบๆ ทำให้ legend "FCF" โชว์แต่ไม่มีเส้นเวลาดูรายปี
  _renderMetricChart(ids.cfoNp, labels, [
    { label: 'CFO (กระแสเงินสดดำเนินงาน)', color: '#3fb950', data: _kbFieldSeries(win, 'cfo') },
    ...(period === 'q' ? [{ label: 'FCF (กระแสเงินสดอิสระ)', color: '#58a6ff', data: _fcfSeries(win) }] : []),
    { label: 'กำไรสุทธิ', color: '#e8b84b', data: _kbFieldSeries(win, 'net_profit') },
  ]);
  _renderMetricChart(ids.netDebt, labels, [
    { label: 'Net Debt (หนี้ - เงินสด)', color: '#e2828f', data: _netDebtSeries(win) },
  ]);
  // total_equity ติดลบ (บริษัทขาดทุนสะสม — ค่านี้ถูกต้องตามจริง ไม่ใช่ error ดู _mergedBsCfRowDefs)
  // ทำให้ D/E Ratio ออกมาเป็นค่าติดลบซึ่งอ่านผิดทางง่ายมาก (ดูเหมือน leverage ต่ำ ทั้งที่จริงคือ
  // สัญญาณอันตรายสุด) — ทำเครื่องหมายจุดนั้นเป็นสีแดง + เตือนใน tooltip + caption ใต้กราฟ
  const deEqNegative = win.map(c => c.total_equity != null && c.total_equity < 0);
  _renderMetricChart(ids.de, labels, [
    { label: 'D/E Ratio (หนี้สิน/ทุน)', color: '#e8b84b', data: _deRatioSeries(win), warnFlags: deEqNegative, warnLabel: 'ส่วนผู้ถือหุ้นติดลบ' },
  ], { pct: true });
  _setChartWarnCaveat('fin-chart-de-warn', deEqNegative.some(Boolean),
    '⚠ จุดสีแดง = ส่วนของผู้ถือหุ้นติดลบช่วงนั้น — D/E ที่โชว์เป็นค่าติดลบ ไม่ได้แปลว่า leverage ต่ำ (สัญญาณอันตรายสุด ไม่ใช่ปลอดภัย)');
  _renderMetricChart(ids.sga, labels, [
    { label: 'SG&A to Sales %', color: '#e2828f', data: win.map(c => c.sga_pct) },
  ], { pct: true });
}

function _renderFinQplReport(d) {
  const qs = d.quarters || [];
  if (!qs.length) {
    document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">ไม่พบข้อมูลงบไตรมาสของหุ้นนี้</div>';
    return;
  }
  _finQplData = d;   // cache ให้ setQplChgMode วาดกราฟใหม่จากข้อมูลเดิม ไม่ fetch ซ้ำ
  const { html } = _qplTableCore(qs, 'qpl-scroll');

  document.getElementById('fin-result').innerHTML = `
    <div class="card" style="padding:14px 16px">
      <div style="font-size:13px;font-weight:700;margin-bottom:2px">${_escHtml(d.sym)} ${d.name && d.name !== d.sym ? `— ${_escHtml(d.name)}` : ''}</div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:10px">งบกำไรขาดทุนรายไตรมาส (หน่วย: พัน${_finCurWord(d.currency)}) — ผสาน Finnomena + Yahoo Finance + SET.or.th · เลื่อนซ้ายเพื่อดูปีเก่ากว่า</div>
      <div style="font-size:12px;font-weight:700;margin-bottom:6px">📈 P&amp;L CHANGE <span id="qpl-chg-title">${_qplChgLabel()}</span>% (รายได้/ต้นทุน/กำไรสุทธิ) + กำไรขั้นต้น GPM% (20Q)</div>
      ${_qplChgToggleHtml()}
      <div style="position:relative;height:260px;margin-bottom:16px"><canvas id="qpl-yoy-chart"></canvas></div>
      ${html}
    </div>`;
  _qplScrollToLatest('qpl-scroll');
  _drawQplYoyChart(qs, 'qpl-yoy-chart');
}

// ตาราง P&L รายไตรมาสจาก SET.or.th ล้วนๆ (source 'set_qpl' อย่างเดียว ไม่ผสาน Finnomena/Yahoo)
// แทรกเสริมท้ายตาราง Company Highlight รายปีในแท็บ 🇹🇭 SET.or.th ของหน้างบการเงิน — โหลด async
// หลังตารางหลักแสดงแล้ว (เหมือน pattern _loadPriceAnalyticsFin/_loadFinDescription) ไม่บล็อกการโหลดหลัก
async function _loadSetQplTable(sym) {
  const box = document.getElementById('fin-set-qpl-box');
  if (!box) return;
  box.style.display = '';
  box.innerHTML = '<div class="empty" style="padding:16px;font-size:12px">กำลังโหลดงบไตรมาสจาก SET.or.th...</div>';
  try {
    const r = await _fetchTimeout(`/api/financials-qpl-set/${encodeURIComponent(sym)}`, 25000,
      'หมดเวลารอข้อมูลงบไตรมาส SET.or.th (เกิน 25 วิ)');
    const d = await r.json();
    const qs = d.quarters || [];
    if (d.error || !qs.length) {
      box.innerHTML = `<div style="font-size:11.5px;color:var(--text2);padding-top:4px">ℹ ไม่พบข้อมูลงบไตรมาสจาก SET.or.th ของหุ้นนี้</div>`;
      return;
    }
    const { html } = _qplTableCore(qs, 'qpl-scroll-set');
    box.innerHTML = `
      <div style="font-size:13px;font-weight:700;margin:16px 0 2px">📋 งบกำไรขาดทุนรายไตรมาส (SET.or.th)</div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:8px">หน่วย: พันบาท · เฉพาะข้อมูลจาก SET.or.th (งบที่บริษัทยื่นจริง) ไม่ผสานแหล่งอื่น${d.synced_at ? ` · sync ล่าสุด: ${d.synced_at}` : ''} · เลื่อนซ้ายเพื่อดูปีเก่ากว่า</div>
      ${html}`;
    _qplScrollToLatest('qpl-scroll-set');
  } catch (e) {
    box.innerHTML = `<div style="font-size:11.5px;color:var(--red);padding-top:4px">⚠ ${e.message}</div>`;
  }
}

// มุมมอง "🧩 งบรวมทุกแหล่ง" — ผสาน P&L (3 แหล่งเหมือน qpl ด้านบน) + งบดุล/กระแสเงินสด
// (Finnomena+Yahoo เท่านั้น — SET.or.th ไม่มีรายไตรมาสจริงของ 2 งบนี้) มี toggle รายไตรมาส/
// รายปี — endpoint เดียวคืนทั้งคู่ ("quarters"+"years") จึงสลับ toggle ได้โดยไม่ fetch ซ้ำ
// ดู compute_full_report()/rollup_full_report_annual() ใน sources/financials_store.py
let _finMergedData = null;
let _finMergedPeriod = 'q';
// จำ isDr ของหุ้นตั้งต้นไว้คู่กับ _finMergedData — ต้องรู้ตอน re-render จาก setFinMergedPeriod()
// (ไม่ fetch ใหม่) ว่าปุ่ม "เทียบกับกลุ่ม" ควรโชว์ไหม (เฉพาะหุ้นไทย sector grouping ไม่รองรับ DR)
let _finMergedIsDr = false;

async function loadFinMergedReport(sym, isDr, market, hint) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงข้อมูลงบการเงิน...</div>';
  try {
    const qs = (isDr ? '?is_dr=1' : '') + (market ? (isDr ? '&' : '?') + 'market=' + market : '');
    const r = await _fetchTimeout(`/api/financials-merged-report/${encodeURIComponent(sym)}${qs}`, 25000,
      'หมดเวลารอข้อมูล (เกิน 25 วิ) — หุ้นนี้อาจยังไม่เคย sync ในเครื่อง กำลังลองดึงสดแต่ช้าเกินไป ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ view + poison _finMergedData
    if (d.error) throw new Error(d.error);
    hint.textContent = '';
    _finMergedData = d;
    _finMergedPeriod = 'q';
    _finMergedIsDr = !!isDr;
    _renderFinMergedReport(d);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

// สลับรายไตรมาส/รายปี — re-render จากข้อมูลที่ cache ไว้แล้วใน _finMergedData ไม่ fetch ใหม่
function setFinMergedPeriod(period) {
  _finMergedPeriod = period;
  document.getElementById('fin-merged-period-q')?.classList.toggle('active', period === 'q');
  document.getElementById('fin-merged-period-y')?.classList.toggle('active', period === 'y');
  if (_finMergedData) _renderFinMergedReport(_finMergedData);
}

// รายการแถวงบดุล/กระแสเงินสดที่ใช้ร่วมกันทั้งตารางรายไตรมาส (_mergedExtraQuarterlyRows)
// และตารางรายปี (_mergedTableAnnual) — 4 ตัวแรกคืองบดุล (stock) ที่เหลือคือกระแสเงินสด (flow)
// warnNegative: total_assets/total_debt/cash ติดลบไม่ได้ตามธรรมชาติทางบัญชี — ถ้าติดลบคือข้อมูล
// ต้นทาง (Finnomena/Yahoo) คลาดเคลื่อน ไม่ใช่ตัวเลขจริง (เจอกับ CHMOBILE/ATP30/PTC ฯลฯ ตอนสุ่มตรวจ
// 2026-08-17) — total_equity ไม่ใส่ warn เพราะติดลบได้จริงสำหรับบริษัทขาดทุนสะสม/เพิ่งเข้าตลาด
function _mergedBsCfRowDefs() {
  return [
    { label: 'สินทรัพย์รวม', key: 'total_assets', opts: { bold: true, warnNegative: true } },
    { label: 'ส่วนของผู้ถือหุ้น', key: 'total_equity', opts: { bold: true } },
    { label: 'หนี้สินที่มีภาระดอกเบี้ยรวม (Total Debt)', key: 'total_debt', opts: { warnNegative: true } },
    { label: 'เงินสดและรายการเทียบเท่าเงินสด', key: 'cash', opts: { warnNegative: true } },
    { label: 'กระแสเงินสดจากการดำเนินงาน (CFO)', key: 'cfo', opts: { bold: true, hlGreen: true } },
    { label: 'กระแสเงินสดจากการลงทุน (CFI)', key: 'cfi', opts: {} },
    { label: 'กระแสเงินสดจากการจัดหาเงิน (CFF)', key: 'cff', opts: {} },
    { label: 'ค่าเสื่อมราคา/ตัดจำหน่าย (D&A)', key: 'da', opts: {} },
  ];
}

// ต่อท้ายตาราง P&L ของ _qplTableCore ด้วยแถวงบดุล/กระแสเงินสด — เรียกผ่านพารามิเตอร์
// extraRowsFn ของ _qplTableCore (ใช้ helper row()/growthRows() เดียวกัน ได้สไตล์/QoQ-YoY
// เหมือนแถว P&L ทุกประการ) years.length*4+1 = จำนวนคอลัมน์ทั้งหมดของตาราง ใช้ทำ section header
function _mergedExtraQuarterlyRows(row, growthRows, years) {
  const sep = label => `<tr><td colspan="${years.length * 4 + 1}" style="padding:10px 8px 4px;font-size:11.5px;font-weight:700;color:var(--text2);border:none">${label}</td></tr>`;
  const defs = _mergedBsCfRowDefs();
  const bsRows = defs.slice(0, 4).map(d => row(d.label, c => c[d.key], _qplNum, d.opts) + growthRows(c => c[d.key])).join('');
  const cfRows = defs.slice(4).map(d => row(d.label, c => c[d.key], _qplNum, d.opts) + growthRows(c => c[d.key])).join('');
  return sep('📋 งบดุล (Finnomena + Yahoo)') + bsRows + sep('💵 กระแสเงินสด (Finnomena + Yahoo)') + cfRows;
}

// ตารางรายปี — คอลัมน์ = ปี (rollup จากรายไตรมาสฝั่ง backend แล้ว) มีแค่ %YoY (ไม่มี QoQ)
// ปีที่ complete===false (ยังไม่ครบ 4 ไตรมาส เช่นปีปัจจุบัน) ใส่เครื่องหมาย * เตือน
function _mergedTableAnnual(years, scrollId) {
  const byYear = {};
  years.forEach(y => { byYear[y.year_ad] = y; });

  // หารด้วย |ฐาน| แทน pv ตรงๆ — กันฐานติดลบ/ศูนย์พลิกทิศทาง % ผิดความหมาย ดูเหตุผลเดียวกันใน
  // _qplChg ของ _qplTableCore
  const yoyOf = getter => c => {
    const prev = byYear[c.year_ad - 1];
    if (!prev) return null;
    const cur = getter(c), pv = getter(prev);
    if (cur == null || pv == null || !pv) return null;
    return (cur - pv) / Math.abs(pv) * 100;
  };

  const yearHead = years.map(y => `<th style="text-align:center;background:#8b2fc9;color:#fff;padding:6px 4px;border:1px solid var(--border);font-size:12px">${y.year_be}${y.complete ? '' : ' *'}</th>`).join('');

  const cellsOf = (getter, fmt, opts = {}) => years.map(y => {
    const v = getter(y);
    const dim = !y.complete ? ';color:var(--text2)' : '';
    const hl = opts.hlYellow ? ';background:#f2c94c26' : (opts.hlGreen ? ';background:#3fb95014' : (opts.hlPeach ? ';background:#e8823014' : ''));
    const pctColor = opts.pctColor && v != null ? `;color:${v > 0 ? 'var(--green)' : v < 0 ? 'var(--red)' : 'var(--text2)'}` : '';
    const warn = opts.warnNegative && v != null && v < 0;
    const warnStyle = warn ? ';color:var(--red);font-weight:700' : '';
    const warnAttr = warn ? ' title="⚠ ค่านี้ติดลบผิดปกติ — น่าจะเป็นข้อมูลคลาดเคลื่อนจากต้นทาง (Finnomena/Yahoo) ไม่ใช่ตัวเลขจริงของบริษัท"' : '';
    return `<td class="r"${warnAttr} style="padding:4px 6px;border:1px solid var(--border);font-size:12px${dim}${hl}${pctColor}${warnStyle}">${warn ? '⚠ ' : ''}${fmt(v)}</td>`;
  }).join('');

  const row = (label, getter, fmt, opts = {}) => `<tr>
    <td style="padding:5px 8px;border:1px solid var(--border);font-size:12.5px;white-space:nowrap${opts.bold ? ';font-weight:700' : ''}${opts.indent ? ';padding-left:18px;color:var(--text2)' : ''}">${label}</td>
    ${cellsOf(getter, fmt, opts)}
  </tr>`;

  const growthRow = getter => row('% YoY', yoyOf(getter), _qplPct, { indent: true, pctColor: true });

  const plRows = [
    row('รายได้จากการขาย', c => c.revenue, _qplNum, { bold: true }),
    growthRow(c => c.revenue),
    row('ต้นทุนขาย', c => c.cogs, _qplNum),
    row('กำไรขั้นต้น', c => c.gross_profit, _qplNum, { bold: true, hlGreen: true }),
    growthRow(c => c.gross_profit),
    row('% GPM', c => c.gpm, _qplPct, { indent: true }),
    row('รวม SG&A', c => c.sga_total, _qplNum, { bold: true, hlPeach: true }),
    row('กำไรจากการดำเนินงาน', c => c.operating_profit, _qplNum, { bold: true, hlYellow: true }),
    growthRow(c => c.operating_profit),
    row('ต้นทุนทางการเงิน', c => c.financial_cost, _qplNumNeg),
    row('กำไรก่อนภาษี', c => c.pretax_profit, _qplNum, { bold: true, hlYellow: true }),
    growthRow(c => c.pretax_profit),
    row('ค่าใช้จ่ายภาษีเงินได้', c => c.tax_expense, _qplNumNeg),
    row('กำไรสำหรับงวด', c => c.net_profit, _qplNum, { bold: true, hlYellow: true }),
    growthRow(c => c.net_profit),
    row('% NPM', c => c.npm, _qplPct, { indent: true }),
  ].join('');

  const bsCfDefs = _mergedBsCfRowDefs();
  const sep = label => `<tr><td colspan="${years.length + 1}" style="padding:10px 8px 4px;font-size:11.5px;font-weight:700;color:var(--text2);border:none">${label}</td></tr>`;
  const bsRows = bsCfDefs.slice(0, 4).map(d => row(d.label, c => c[d.key], _qplNum, d.opts) + growthRow(c => c[d.key])).join('');
  const cfRows = bsCfDefs.slice(4).map(d => row(d.label, c => c[d.key], _qplNum, d.opts) + growthRow(c => c[d.key])).join('');

  const hasPartial = years.some(y => !y.complete);
  const caveat = hasPartial ? `
    <div style="margin-top:10px;font-size:11.5px;color:var(--text2)">
      * = ปีที่ยังไม่ครบ 4 ไตรมาส (rollup จากไตรมาสเท่าที่มีข้อมูลตอนนี้ ไม่ใช่ยอดเต็มปี) — อย่าเทียบตรงๆ กับปีที่ครบแล้ว
    </div>` : '';

  return `
    <div id="${scrollId}" style="overflow-x:auto">
      <table class="tbl" style="border-collapse:collapse;min-width:500px">
        <thead><tr><th style="border:1px solid var(--border)"></th>${yearHead}</tr></thead>
        <tbody>${plRows}${sep('📋 งบดุล (Finnomena + Yahoo)')}${bsRows}${sep('💵 กระแสเงินสด (Finnomena + Yahoo)')}${cfRows}</tbody>
      </table>
    </div>
    ${caveat}`;
}

// "🌊 Income Sankey Diagram — TTM 4Q" บนสุดของแท็บ 🧩 งบรวมทุกแหล่ง — โครงสร้างเป็น tree แยก 2
// ทางทุกจุด (ต้นทุน/ค่าใช้จ่ายด้านบน vs กำไรที่เหลือด้านล่าง) ต่อกันเป็นลูกโซ่ตามอัตลักษณ์ทางบัญชี:
// Rev -> COGS+GP -> GP -> SGA+EBIT -> EBIT -> FinCost+Pretax -> Pretax -> Tax+NetProfit
// ความสูงกล่องทุกกล่องคำนวณจาก value/revenue (global scale เดียวกันหมด) ทำให้กล่องลูกรวมกัน
// เท่ากล่องแม่พอดีโดยอัตโนมัติ ไม่ต้องพึ่ง recursive proportion
const _FIN_SANKEY_CLR = { revenue: '#58a6ff', cost: '#f85149', grossProfit: '#39c5cf', profit: '#3fb950' };

// วัดความกว้างข้อความจริงด้วย canvas 2D (แม่นกว่าเดาจากจำนวนตัวอักษร โดยเฉพาะภาษาไทยที่ความกว้าง
// ต่อตัวอักษรไม่เท่ากัน) ใช้ font-family เดียวกับที่ --font กำหนดไว้ให้ body (SVG text ไม่ได้ตั้ง
// font-family เอง เลย inherit มาจาก body) แคช context ไว้ตัวเดียวไม่ต้องสร้างใหม่ทุกครั้ง
let _finSankeyMeasureCtx = null;
let _finSankeyFontFam = null;   // --font ของ body คงที่ทั้ง session — อ่าน getComputedStyle ครั้งเดียวพอ
function _finSankeyTextWidth(text, fontSize, weight) {
  if (!_finSankeyMeasureCtx) _finSankeyMeasureCtx = document.createElement('canvas').getContext('2d');
  if (!_finSankeyFontFam) _finSankeyFontFam = getComputedStyle(document.body).fontFamily || 'sans-serif';
  _finSankeyMeasureCtx.font = `${weight} ${fontSize}px ${_finSankeyFontFam}`;
  return _finSankeyMeasureCtx.measureText(text).width;
}

// ตัดบรรทัด label ยาวๆ (เช่น "กำไรจากการดำเนินงาน (EBIT)" ที่กว้างเกิน colW ที่ font-size ปกติ) ให้
// ขึ้นบรรทัดใหม่ตรงช่องว่างแทนโดน clip-path ตัดกลางคำดิบๆ — greedy word-wrap ธรรมดา จำกัดไม่เกิน
// maxLines บรรทัด (เกินนั้นตัดทิ้ง ปล่อยให้ clip-path ที่มีอยู่แล้วเป็นตาข่ายกันสุดท้ายเหมือนเดิม)
function _wrapSankeyLabel(text, maxWidth, fontSize, weight, maxLines) {
  const words = text.split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const trial = cur ? cur + ' ' + w : w;
    if (cur && _finSankeyTextWidth(trial, fontSize, weight) > maxWidth) {
      lines.push(cur);
      cur = w;
    } else {
      cur = trial;
    }
  }
  if (cur) lines.push(cur);
  return lines.slice(0, maxLines);
}

// ผลรวม TTM 4 ไตรมาสล่าสุดจาก qs (เรียงเก่า->ใหม่แล้ว) — เข้มงวดแบบเดียวกับ _ttm_sum ฝั่ง backend
// ใน sources/financials_store.py (ต้องมี 4 ไตรมาสติดกันจริง ฟิลด์ไหน null แม้แค่ 1 งวดใน 4 ให้ทั้ง
// ฟิลด์นั้นเป็น null กันผลรวมครึ่งๆ กลางๆ หลอกตา) คืน null ถ้าข้อมูลไม่พอหรือ revenue ไม่มี
// เติมฟิลด์ที่ขาดหายระหว่างกลาง (financial_cost/pretax_profit/tax_expense) จากฟิลด์ข้างเคียงที่มีครบ
// — Yahoo บางบริษัทไม่คืนค่าฟิลด์เหล่านี้ตรงๆ ทั้งที่คำนวณย้อนจากอัตลักษณ์ทางบัญชีได้ (เช่น AAPL ที่
// ดอกเบี้ยรับสุทธิเป็นบวก [EBIT<Pretax] Yahoo เลยไม่ส่ง financial_cost มา, หรือ AMZN/WMT/NVDA ที่ไม่มี
// "Pretax Income"/"Interest Expense" แยกให้เลย) เดิมพลาดฟิลด์เดียวใน 1 งวดก็ทำให้ _computeFinSankeyTtm
// (strict-null ทั้ง TTM) ตัดสเตจที่เหลือทั้งหมดทิ้ง (ภาษี/กำไรสุทธิหายไปด้วยทั้งที่มีข้อมูลจริง) —
// สืบย้อนจาก EBIT-FinCost=Pretax และ Pretax-Tax=Net แทน ยังเข้มงวดเหมือนเดิม: ถ้าฟิลด์ข้างเคียงที่ต้อง
// ใช้ derive ก็ไม่มีอยู่ดี ปล่อย null ต่อ ไม่เดาสุ่ม
function _deriveFinQuarterFields(r) {
  const out = { ...r };
  if (out.pretax_profit == null && out.operating_profit != null && out.financial_cost != null) {
    out.pretax_profit = out.operating_profit - out.financial_cost;
  }
  if (out.pretax_profit == null && out.tax_expense != null && out.net_profit != null) {
    out.pretax_profit = out.tax_expense + out.net_profit;
  }
  if (out.financial_cost == null && out.operating_profit != null && out.pretax_profit != null) {
    out.financial_cost = out.operating_profit - out.pretax_profit;
  }
  if (out.tax_expense == null && out.pretax_profit != null && out.net_profit != null) {
    out.tax_expense = out.pretax_profit - out.net_profit;
  }
  return out;
}

// ประมวลผลหน้าต่าง 4 ไตรมาสเดียว (เรียงเก่า->ใหม่, ผ่าน _deriveFinQuarterFields แล้ว) — คืน null ถ้า
// ไม่ติดกันจริงหรือไม่มีรายได้ ไม่งั้นคืน out พร้อม out._complete บอกว่าฟิลด์สาย financial_cost/
// pretax_profit/tax_expense/net_profit ครบหรือไม่ (แบงก์/สถาบันการเงินนับว่า "ครบ" เสมอเพราะไม่มี
// แนวคิดพวกนี้อยู่แล้วโดยธรรมชาติ ไม่ใช่ data gap)
function _tryFinSankeyTtmWindow(last4) {
  // ต้องเป็น 4 ไตรมาสติดกันจริง ไม่ใช่แค่ 4 แถวหลังสุดของอาเรย์ — หุ้นที่ sync ไม่ครบ (มักเจอกับ
  // DR/mirror) อาจมีช่วงขาดหายกลางทาง ถ้าไม่เช็คจะรวมไตรมาสไม่ติดกันแล้วติดป้าย "TTM 4Q" ผิด
  // ความหมายแบบไม่มีคำเตือน (ให้เข้มงวดแบบเดียวกับ _ttm_sum ฝั่ง backend จริงๆ ตามที่คอมเมนต์บอก)
  for (let i = 1; i < last4.length; i++) {
    if ((last4[i].year_ad * 4 + last4[i].q) - (last4[i - 1].year_ad * 4 + last4[i - 1].q) !== 1) return null;
  }
  const FIELDS = ['revenue', 'cogs', 'gross_profit', 'sga_total', 'operating_profit',
                   'financial_cost', 'pretax_profit', 'tax_expense', 'net_profit'];
  const out = {};
  for (const f of FIELDS) {
    let total = 0, ok = true;
    for (const r of last4) {
      if (r[f] == null) { ok = false; break; }
      total += r[f];
    }
    out[f] = ok ? total : null;
  }
  if (out.revenue == null || out.revenue <= 0) return null;
  // แบงก์/สถาบันการเงิน (ธนาคาร/ประกัน/เงินทุนฯ) ไม่มีแนวคิด COGS/กำไรขั้นต้นแบบธุรกิจทั่วไป —
  // cogs/gross_profit จะเป็น null ทุกงวดเสมอเพราะผังบัญชีคนละแบบ (ไม่ใช่ข้อมูลขาดหาย) เช็คว่า
  // null ทั้ง 4 งวดถึงจะถือว่าเป็นกลุ่มนี้จริง (ต่างจาก data gap ที่มักหายแค่บางงวด)
  out.isBankLike = last4.every(r => r.cogs == null && r.gross_profit == null);
  const first = last4[0], lastQ = last4[3];
  out.periodLabel = `Q${first.q}'${String(first.year_be).slice(-2)} → Q${lastQ.q}'${String(lastQ.year_be).slice(-2)}`;
  out._complete = out.isBankLike ||
    (out.financial_cost != null && out.pretax_profit != null && out.tax_expense != null && out.net_profit != null);
  return out;
}

function _computeFinSankeyTtm(qs) {
  if (!qs || qs.length < 4) return null;
  const sorted = [...qs].sort((a, b) => a.year_ad - b.year_ad || a.q - b.q).map(_deriveFinQuarterFields);
  const latestQ = sorted[sorted.length - 1];
  const latestQLabel = `Q${latestQ.q}'${String(latestQ.year_be).slice(-2)}`;
  // ลองหน้าต่าง TTM ล่าสุดก่อนเสมอ ถ้าไตรมาสล่าสุดสุดยังมาไม่ครบจากต้นทาง (เช่น Yahoo ยังไม่อัพเดต
  // pretax/tax ของไตรมาสที่เพิ่งปิดงวด — ปกติมาช้ากว่า revenue/net_profit ที่มาจาก Finnomena คนละชั้น
  // เจอจริงกับ AMZN 2026-08-19) ให้ถอยทั้งหน้าต่างไปทีละไตรมาส สูงสุด MAX_BACK แทนที่จะโชว์ Sankey
  // ตัดครึ่งไปเรื่อยๆ — เลื่อนทั้งหน้าต่างพร้อมกันเสมอ (ไม่ใช่แยกทีละ field) ทุกกล่องเลยยังอ้างอิง
  // ช่วงเวลาเดียวกันแน่นอน ไม่ผสมกัน periodLabel จะโชว์ช่วงจริงที่ใช้เสมอให้เห็นว่าไม่ใช่ TTM ล่าสุด
  // สุดถ้าต้องถอย — ถ้าไม่มีหน้าต่างไหนครบเลยภายใน MAX_BACK ก็ fallback กลับไปโชว์หน้าต่างล่าสุดสุด
  // (ของเดิม บางส่วนดีกว่าไม่มีเลย)
  const MAX_BACK = 2;
  let fallback = null, fallbackBack = 0;
  for (let back = 0; back <= MAX_BACK && sorted.length - 4 - back >= 0; back++) {
    const last4 = back === 0 ? sorted.slice(-4) : sorted.slice(-4 - back, -back);
    const result = _tryFinSankeyTtmWindow(last4);
    if (!result) continue;
    if (!fallback) { fallback = result; fallbackBack = back; }
    if (result._complete) {
      // ถอยหน้าต่างจริง — ติด flag ให้การ์ดโชว์ note เตือนว่านี่ไม่ใช่ TTM ของไตรมาสล่าสุดสุด (ไตรมาส
      // ล่าสุดสุดข้อมูลยังมาไม่ครบจากต้นทาง) กันผู้ใช้เข้าใจผิดว่าเป็นตัวเลขล่าสุด
      if (back > 0) { result.staleBy = back; result.latestQLabel = latestQLabel; }
      return result;
    }
  }
  // ไม่มีหน้าต่างไหนครบเลยภายใน MAX_BACK — ใช้ผลลัพธ์แรกที่ไม่ null (ของเดิม บางส่วนดีกว่าไม่มีเลย)
  // ถ้าหน้าต่างนั้นไม่ใช่ไตรมาสล่าสุดสุด (back=0 คืน null เอง เช่น revenue ยังไม่เข้าระบบ) ก็ต้อง
  // ติด staleBy เหมือนกัน ไม่งั้น badge เตือนจะไม่ขึ้นทั้งที่ตัวเลขเก่ากว่าไตรมาสล่าสุดจริง
  if (fallback && fallbackBack > 0) { fallback.staleBy = fallbackBack; fallback.latestQLabel = latestQLabel; }
  return fallback;
}

function _renderFinSankeySvg(v) {
  const stages = [
    { costKey: 'cogs', costLabel: 'ต้นทุนขาย', contKey: 'gross_profit', contLabel: 'กำไรขั้นต้น' },
    { costKey: 'sga_total', costLabel: 'SG&A', contKey: 'operating_profit', contLabel: 'กำไรจากการดำเนินงาน (EBIT)' },
    { costKey: 'financial_cost', costLabel: 'ต้นทุนทางการเงิน', contKey: 'pretax_profit', contLabel: 'กำไรก่อนภาษี' },
    { costKey: 'tax_expense', costLabel: 'ค่าใช้จ่ายภาษีเงินได้', contKey: 'net_profit', contLabel: 'กำไรสุทธิ' },
  ];
  const OFF = 8, barW = 10, colGap = 200, x0 = 8, LABEL_TAIL_W = 140;
  const rev = v.revenue;
  const esc = _escHtml;
  const _curAbbr = (v._curWord && v._curWord !== 'บาท') ? ` ล.${v._curWord}` : ' ลบ.';
  const fmtM = n => n == null ? '—' : (n / 1e6).toLocaleString('en-US', { maximumFractionDigits: 1 }) + _curAbbr;
  const fmtPct = n => n == null ? '' : (n / rev * 100).toFixed(1) + '% of Rev';
  const fmtPctShort = n => n == null ? '' : (n / rev * 100).toFixed(1) + '%';

  // buildTree แบ่ง "พื้นที่ยืน" (slot, y0/y1) ต่อโหนดล้วนๆ เพื่อกันไม่ให้ label ที่วางไว้ข้างแท่งชนกัน
  // — MIN_H=52 ตรงกับพื้นที่แนวตั้งที่ label เต็ม (ชื่อ/มูลค่า/% of Rev) ต้องใช้ ไม่เกี่ยวกับความหนา
  // ของแท่งที่วาดจริง (คำนวณแยกจาก value/revenue ตรงๆ ด้านล่าง หลัง buildTree) จองพื้นที่ล่วงหน้า
  // (reserveAfter) ให้พอสำหรับ label ของทุกสเตจที่เหลือ + label กำไรตัวสุดท้าย ไม่ใช่แค่กิ่งถัดไปกิ่ง
  // เดียว — ถ้าจองแค่กิ่งถัดไป (ของเดิม) กิ่งกำไรจะไปโดนบีบต่ออีกทีตอนแยกกิ่งลึกถัดๆไป จนบางกล่องท้ายสุด
  // (เช่น ภาษี/กำไรสุทธิ) ยังเล็กกว่า MIN_H อยู่ดี
  //
  // ⚠ ข้อบังคับที่ buildTree ต้องการจริงๆ: H >= (stages.length+1) * MIN_H เสมอ (พิสูจน์: แต่ละสเตจ
  // "เฉือน" กล่องต้นทุนสูง MIN_H ออกจากด้านบนของพื้นที่ที่เหลือ 4 ครั้ง + เหลือกล่องกำไรสุทธิท้ายสุดอีก
  // MIN_H = 5*MIN_H รวม) เจอบั๊กจริง 2026-08-19: ตอนย่อขนาดทั้งภาพลง H เคยลดเหลือ 200 แต่ MIN_H ยังอยู่
  // 52 (5*52=260 > 200) ทำให้ parentH หดจนต่ำกว่า MIN_H*2 ตั้งแต่สเตจที่ 3 (ต้นทุนทางการเงิน/กำไรก่อน
  // ภาษี) เงื่อนไข fallback ทั้ง 2 ชั้นใน buildTree ไม่ผ่านสักอัน เลยไม่มีการบังคับขั้นต่ำใดๆ เหลือแค่
  // สัดส่วนจริงดิบๆ (สไลซ์เหลือ 0.69px!) กล่อง "ต้นทุนทางการเงิน" ยุบจนกล่อง "กำไรก่อนภาษี" ทับซ้อน —
  // แก้โดยเพิ่ม H กลับให้ผ่านเงื่อนไข (270 > 260 มีเผื่อนิดหน่อย) แล้วชดเชยด้วยการขยาย colGap ให้ภาพ
  // แบนลง (landscape มากขึ้น) รักษาความสูงพิกเซลจริงตอน render ให้ใกล้เคียงเดิม ไม่งั้นจะย้อนกลับไปเป็น
  // ปัญหา "ต้องเลื่อนดู" ที่เพิ่งแก้ไปก่อนหน้านี้
  const MIN_H = 52, H = 270;

  function buildTree() {
    const nodes = [{ col: 0, label: 'รายได้จากการขาย', value: rev, y0: 0, y1: H, color: _FIN_SANKEY_CLR.revenue }];
    const links = [];
    let parentNode = nodes[0];
    for (let k = 0; k < stages.length; k++) {
      const st = stages[k];
      const costVal = v[st.costKey], contVal = v[st.contKey];
      if (costVal == null || contVal == null) break;
      const parentH = parentNode.y1 - parentNode.y0;
      const denom = costVal + contVal;
      const costHRaw = denom > 0 ? (costVal / denom) * parentH : parentH / 2;
      // clamp ไว้ใน [0, parentH] เสมอ — ถ้า contVal (กำไรขั้นต้น/EBIT/กำไรก่อนภาษี) ติดลบ (ขาดทุน
      // จริงในไตรมาสนั้น) ขณะ costVal ยังบวก costVal จะเกิน denom ทำให้ costH เกิน parentH ได้
      // ถ้าไม่ clamp จะทำให้ contNode.y0 > contNode.y1 (สูงติดลบ) แล้วพัง cascade ไปทุกกล่องถัดไป
      let costH = Math.max(0, Math.min(parentH, costHRaw));
      // reserveAfter คือพื้นที่ขั้นต่ำที่กิ่งกำไร (contH) ต้อง "เหลือติดตัว" ไว้ให้พอสำหรับกล่องต้นทุน
      // ของทุกสเตจที่เหลือ (คนละ MIN_H) บวกกล่องกำไรตัวสุดท้ายอีก MIN_H — ถ้า parent เหลือพอจองได้เต็ม
      // ใช้แบบนั้น ถ้าไม่พอ (parent เองก็โดนบีบมาจากชั้นก่อนหน้าจนเหลือน้อย) ถอยไปแค่การันตี MIN_H ให้
      // ทั้ง 2 กิ่งของสเตจนี้พอ (เท่าที่ทำได้)
      const stagesLeftAfter = stages.length - k - 1;
      const reserveAfter = (stagesLeftAfter + 1) * MIN_H;
      if (parentH >= MIN_H + reserveAfter) {
        costH = Math.min(Math.max(costH, MIN_H), parentH - reserveAfter);
      } else if (parentH >= MIN_H * 2) {
        costH = Math.min(Math.max(costH, MIN_H), parentH - MIN_H);
      }
      const costNode = { col: parentNode.col + 1, label: st.costLabel, value: costVal,
                          y0: parentNode.y0, y1: parentNode.y0 + costH, color: _FIN_SANKEY_CLR.cost };
      // สเตจแรก (k===0) เท่านั้นที่ contNode คือ "กำไรขั้นต้น" — ให้สีต่างจากกำไรที่เหลือขั้นถัดๆไป
      // (EBIT/กำไรก่อนภาษี/กำไรสุทธิ ยังใช้สี profit ปกติ) ตามที่ legend อ้างอิงแยก Gross Profit ไว้
      const contNode = { col: parentNode.col + 1, label: st.contLabel, value: contVal,
                          y0: parentNode.y0 + costH, y1: parentNode.y1,
                          color: k === 0 ? _FIN_SANKEY_CLR.grossProfit : _FIN_SANKEY_CLR.profit };
      nodes.push(costNode, contNode);
      links.push({ from: parentNode, to: costNode });
      links.push({ from: parentNode, to: contNode });
      parentNode = contNode;
    }
    return { nodes, links };
  }

  const { nodes, links } = buildTree();
  if (nodes.length < 3) return '';   // แม้แต่ COGS/กำไรขั้นต้นก็ไม่มี — ไม่พอวาดอะไรที่มีความหมาย

  const cx = col => x0 + col * (barW + colGap);

  // ความหนาของแท่ง/ริบบอนคงที่ทุกกล่องทุกหุ้นเสมอ (FIXED_THICK) — ไม่ผูกกับ value/revenue อีกต่อไป
  // เดิมเคยคำนวณตามสัดส่วนจริง (ต้นทุนขายแท่งใหญ่ ภาษี/ดอกเบี้ยแท่งเรียวบาง แบบ Sankey ทั่วไป) แต่ผล
  // คือขนาดรวมของภาพ "ขยาย/บวม" ต่างกันไปตามโครงสร้างมาร์จิ้นของแต่ละหุ้น (หุ้นมาร์จิ้นสูงเช่น AAPL
  // ริบบอนหลายเส้นหนาพร้อมกันจนภาพดูใหญ่กว่าหุ้นทั่วไปทั้งที่ viewBox ขนาดเท่ากัน) ผู้ใช้ต้องการให้ทุก
  // หุ้นหน้าตาเท่ากันเป๊ะไม่ว่าตัวเลขจะใหญ่/มาร์จิ้นจะเบี้ยวแค่ไหน เลยล็อกความหนาคงที่แทน (สัดส่วนจริง
  // ยังอ่านได้จากตัวเลข/% ที่ label ข้างแท่งอยู่แล้ว ไม่ต้องพึ่งพาความหนาเป็นตัวสื่อสาร)
  const FIXED_THICK = 18;
  nodes.forEach(n => {
    const slotH = n.y1 - n.y0;
    n.thick = Math.min(slotH, FIXED_THICK);
    n.cy = OFF + (n.y0 + n.y1) / 2;
    n.by0 = n.cy - n.thick / 2;
    n.by1 = n.cy + n.thick / 2;
  });

  // ประมวลผลลิงก์เป็นคู่ (cost, cont) ต่อจุดแยกกิ่งหนึ่งจุด (buildTree push เข้าคู่กันเสมอ) เพื่อแบ่ง
  // จุดออกบนแท่งของ parent ตามสัดส่วนมูลค่าจริง (บนลงล่าง: ฝั่งต้นทุนก่อน ฝั่งกำไรที่เหลือ) แล้วโค้ง
  // เป็นเส้น bezier ไปยังจุดศูนย์กลางของแท่งปลายทาง — sy กับ ty ต่างกันได้ ทำให้ริบบอนโค้งขึ้น/ลงจริง
  // (ต่างจากเวอร์ชันกล่องเดิมที่ปลายทั้งคู่ยึด y เดียวกันเสมอจนได้แต่เส้นตรงแนวนอน)
  let gradDefs = '', linkPaths = '';
  for (let i = 0; i < links.length; i += 2) {
    const lkCost = links[i], lkCont = links[i + 1];
    const parent = lkCost.from;
    const costVal = lkCost.to.value, contVal = lkCont.to.value;
    const denom = costVal + contVal;
    const costFrac = denom > 0 ? Math.max(0, Math.min(1, costVal / denom)) : 0.5;
    const costSliceH = parent.thick * costFrac;
    const branchSy = [parent.by0 + costSliceH / 2, parent.by0 + costSliceH + (parent.thick - costSliceH) / 2];
    [lkCost, lkCont].forEach((lk, bi) => {
      const sx = cx(lk.from.col) + barW, tx = cx(lk.to.col);
      const sy = branchSy[bi], ty = lk.to.cy, midX = (sx + tx) / 2;
      const w = Math.max(1, lk.to.thick);
      const gid = `finSankeyGrad${i}_${bi}`;
      // gradientUnits="userSpaceOnUse" จำเป็น (ดู docstring เดิม) — ตอนนี้ sy!=ty เกือบทุกเส้นอยู่แล้ว
      // เลยไม่ค่อยเจอ bounding-box สูง=0 แบบเดิม แต่ใส่ไว้เผื่อกรณี sy==ty พอดี (parent/child อยู่แนว
      // เดียวกันเป๊ะ) ยังปลอดภัยเหมือนเดิม
      gradDefs += `<linearGradient id="${gid}" gradientUnits="userSpaceOnUse" x1="${sx}" x2="${tx}" y1="${sy}" y2="${ty}">
        <stop offset="0" stop-color="${lk.from.color}" stop-opacity=".55"/>
        <stop offset="1" stop-color="${lk.to.color}" stop-opacity=".55"/>
      </linearGradient>`;
      linkPaths += `<path d="M${sx},${sy} C${midX},${sy} ${midX},${ty} ${tx},${ty}" stroke="url(#${gid})" stroke-width="${w}" fill="none" stroke-linecap="round"/>`;
    });
  }

  // ใช้ stages.length คงที่เสมอ (ไม่ใช่ maxCol จาก nodes จริง) — หุ้นบางตัวมีบางฟิลด์ null (เช่น
  // financial_cost/tax_expense งวดนั้นไม่มี) ทำให้ buildTree break ก่อนครบ 4 สเตจ nodes สั้นกว่าปกติ
  // ถ้าใช้ maxCol จริง vbW จะแคบลงตามจำนวนคอลัมน์ที่เหลือ ขณะ vbH คงที่เท่าเดิม อัตราส่วนภาพเลยเพี้ยน
  // (แคบ+สูงกว่าเดิม) พอ scale ให้เต็มความกว้าง container เท่ากัน ภาพเลยดู "ใหญ่กว่า" หุ้นที่มีข้อมูล
  // ครบ 4 สเตจ — ตรงข้ามกับที่ผู้ใช้ต้องการ (ทุกหุ้นต้องมีอัตราส่วนภาพเดียวกันเป๊ะไม่ว่าข้อมูลจะครบแค่ไหน)
  const vbW = cx(stages.length) + barW + LABEL_TAIL_W + 8, vbH = H + OFF * 2;

  // label วางข้างแท่ง (ไม่ใช่ในกล่องที่หดตามความหนาแท่งอีกต่อไป) เลยมีที่ยืนเท่ากับ MIN_H เสมอไม่ว่า
  // แท่งจะบางแค่ไหน — ตัดขึ้นบรรทัดใหม่ตรงช่องว่างถ้ากว้างเกิน colGap (เช่น "กำไรจากการดำเนินงาน
  // (EBIT)") ด้วย _wrapSankeyLabel ตัวเดียวกับที่ใช้ตอนยังเป็นกล่อง — มูลค่า+% รวมบรรทัดเดียวกัน (คนละสี
  // ผ่าน tspan) แทนที่จะแยก 2 บรรทัดแบบเดิม เพื่อลดจำนวนบรรทัดที่ MIN_H ต้องจองพื้นที่ให้ (ยิ่งน้อย
  // บรรทัด ยิ่งลด MIN_H ได้มาก ทำให้ทั้งแผนภาพเตี้ยลงและกว้างน้อยลงตามไปด้วย โดยไม่เสียข้อมูลอะไรเลย)
  const LABEL_MAXW = colGap - 16;
  const nodeBoxes = nodes.map(n => {
    const nameLines = _wrapSankeyLabel(n.label, LABEL_MAXW, 10.5, 700, 2);
    const LINE_H = 12.5;
    const tx = cx(n.col) + barW + 8;
    const valStr = fmtM(n.value), pctStr = fmtPctShort(n.value), pctStrFull = fmtPct(n.value);
    // มูลค่า+% รวมบรรทัดเดียวกัน (คนละสีผ่าน tspan) เมื่อพอมีที่ — ประหยัดบรรทัดกว่าแยก 2 บรรทัดแบบเดิม
    // ทำให้ MIN_H เล็กลงได้มาก แต่ตัวเลขบางหุ้นยาวเกิน budget ต่อคอลัมน์ (colGap-16) ได้ เช่นรายได้หลัก
    // ล้านบาทที่มีหลายหลัก เจอจริงตอนทดสอบ AMZN (ตัวเลขยาวจนล้นทับคอลัมน์ถัดไป) เลยวัดความกว้างจริงก่อน
    // ถ้าไม่พอค่อย fallback แยกเป็น 2 บรรทัดเหมือนเดิม รับประกันไม่ล้นไม่ว่าตัวเลขจะยาวแค่ไหน
    const combinedW = _finSankeyTextWidth(valStr, 9.5, 400) + 5 + _finSankeyTextWidth(pctStr, 9.5, 600);
    const splitValuePct = combinedW > LABEL_MAXW;
    const totalLines = nameLines.length + (splitValuePct ? 2 : 1);
    const startY = n.cy - (totalLines - 1) * LINE_H / 2 + 4;
    const nameTextEls = nameLines.map((t, i) =>
      `<text x="${tx}" y="${startY + i * LINE_H}" fill="var(--text)" font-size="10.5" font-weight="700">${esc(t)}</text>`
    ).join('');
    const valueY = startY + nameLines.length * LINE_H;
    const valueLine = splitValuePct
      ? `<text x="${tx}" y="${valueY}" fill="var(--text)" font-size="9.5">${valStr}</text>
         <text x="${tx}" y="${valueY + LINE_H}" fill="${n.color}" font-size="9.5" font-weight="600">${pctStrFull}</text>`
      : `<text x="${tx}" y="${valueY}" font-size="9.5">` +
        `<tspan fill="var(--text)">${valStr}</tspan>` +
        `<tspan fill="${n.color}" font-weight="600" dx="5">${pctStr}</tspan></text>`;
    // ริบบอนพี่น้อง (เช่น SG&A ที่หนา) ยังแวะผ่านแถวเดียวกันได้ก่อนจะโค้งแยกออกไปสุดทาง ทำให้ label
    // ที่วางไว้ข้างแท่งของตัวเองมีโอกาสโดนริบบอนอื่นพาดผ่านทับจนอ่านยาก (ต่างจากบั๊กก่อนหน้าที่ล้น
    // ออกนอกกรอบ — อันนี้คือทับกับเส้นกราฟ) แก้ด้วยการใส่ชิปพื้นหลังสีเดียวกับการ์ด (var(--bg2))
    // หลัง text เพื่อ "ลบ" ริบบอนที่พาดผ่านทิ้งเฉพาะโซนตัวหนังสือ อ่านชัดเจนเสมอไม่ว่าเส้นจะพาดตรงไหน
    const pctFullW = splitValuePct ? _finSankeyTextWidth(pctStrFull, 9.5, 600) : 0;
    const maxLineW = Math.max(combinedW, pctFullW, ...nameLines.map(t => _finSankeyTextWidth(t, 10.5, 700)), 1);
    const chipY0 = startY - 10.5 - 3, chipY1 = valueY + (splitValuePct ? LINE_H : 0) + 4;
    return `<g>
      <rect x="${cx(n.col)}" y="${n.by0}" width="${barW}" height="${n.thick}" rx="${barW / 2}" fill="${n.color}"/>
      <title>${esc(n.label)}: ${valStr} ${pctStrFull}</title>
      <rect x="${tx - 4}" y="${chipY0}" width="${maxLineW + 8}" height="${chipY1 - chipY0}" rx="4" fill="var(--bg2)" fill-opacity="0.9"/>
      ${nameTextEls}
      ${valueLine}
    </g>`;
  }).join('');

  return `
    <div style="overflow-x:auto;margin-bottom:6px">
      <svg viewBox="0 0 ${vbW} ${vbH}" style="width:100%;min-width:640px;height:auto;display:block">
        <defs>${gradDefs}</defs>
        ${linkPaths}
        ${nodeBoxes}
      </svg>
    </div>`;
}

// การ์ด Sankey ที่วางบนสุดของแท็บ 🧩 งบรวมทุกแหล่ง (คืน '' เงียบๆ ถ้าข้อมูล TTM ไม่พอ หรือเป็นกลุ่ม
// แบงก์/สถาบันการเงินที่ไม่มีแนวคิด COGS/กำไรขั้นต้น — ไม่ใช่ error ไม่ต้องโชว์ข้อความเตือน)
// isFinancialSector: d.is_financial_sector จาก backend (industry 'Financials' ใน set_data.json —
// เชื่อถือได้กว่า เพราะ cogs ที่ผสานมาจาก Yahoo/Finnomena มักไม่ null สำหรับกลุ่มนี้ ต่างจากที่
// คาดไว้แต่แรก) undefined สำหรับ DR (ไม่มีข้อมูลใน set_data.json) — fallback ไปใช้ v.isBankLike
// (null ทั้ง 4 งวด TTM) แทน
// เก็บ v ของหุ้นตั้งต้น (TTM absolute values) ไว้ให้ปุ่ม "เทียบกับกลุ่ม" คำนวณ % ต่อรายได้/delta
// ต่อสเตจได้โดยไม่ต้องคำนวณ TTM ซ้ำ — global ตัวเดียวพอเพราะแท็บนี้โชว์ได้ทีละหุ้น (re-render ทับ
// ของเดิมทุกครั้งที่เปลี่ยนหุ้น/toggle รายไตรมาส-รายปีอยู่แล้ว)
let _finSankeyStockV = null;

function _finSankeyCardHtml(qs, isFinancialSector, sym, isDr, cur) {
  const v = _computeFinSankeyTtm(qs);
  if (!v) return '';
  const hideForFinSector = isFinancialSector === undefined ? v.isBankLike : isFinancialSector;
  if (hideForFinSector) return '';
  v._curWord = _finCurWord(cur);
  const svg = _renderFinSankeySvg(v);
  if (!svg) return '';
  _finSankeyStockV = v;
  const dot = c => `<span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${c};margin-right:4px"></span>`;
  // ปุ่ม "เทียบกับกลุ่ม" เฉพาะหุ้นไทย — sector/industry grouping มีแค่ TH ใน set_data.json
  // (เหมือน constraint ของ /api/peer-group-detail และ /api/peer-compare) DR ไม่มีข้อมูลนี้เลย
  const compareBtnHtml = (sym && !isDr) ? `
    <button class="filter-btn" id="fin-sankey-sector-btn" style="font-size:11px;padding:4px 10px;margin-left:auto;white-space:nowrap"
      onclick="_toggleFinSankeySectorCompare('${_escJsAttr(sym)}')">🆚 เทียบกับกลุ่ม (Sector Median)</button>` : '';
  return `
    <div class="card" style="padding:14px 16px;margin-bottom:16px">
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:2px">
        <div style="font-size:13px;font-weight:700">🌊 Income Sankey Diagram — TTM 4Q${_tipIconHtml('แผนภาพเส้นทางรายได้ → กำไรขั้นต้น → กำไรจากการดำเนินงาน (EBIT) → กำไรก่อนภาษี → กำไรสุทธิ แยกกิ่งต้นทุน/ค่าใช้จ่ายที่ถูกหักออกในแต่ละขั้น<br><br>ความหนาของแท่งคงที่ทุกกล่องเสมอ (ไม่ได้สื่อขนาดจริง) — เทียบสัดส่วนจากตัวเลข % ที่กำกับไว้ข้างแท่งแทน')}</div>
        ${compareBtnHtml}
      </div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:${v.staleBy ? 4 : 10}px">${v.periodLabel} · หน่วย: ล้าน${v._curWord || 'บาท'} · ผลรวม 4 ไตรมาสล่าสุด (TTM) จาก P&amp;L ผสานด้านล่าง</div>
      ${v.staleBy ? `<div style="font-size:11px;color:#e3b341;margin-bottom:10px">⚠ ไม่ใช่ TTM ของไตรมาสล่าสุด (${v.latestQLabel}) — ข้อมูลต้นทุนทางการเงิน/ภาษีของไตรมาสนั้นยังมาไม่ครบจากต้นทาง แสดง TTM ของ 4 ไตรมาสก่อนหน้าแทนชั่วคราว</div>` : ''}
      <div style="display:flex;gap:14px;margin-bottom:10px;font-size:10.5px;color:var(--text2)">
        <span>${dot(_FIN_SANKEY_CLR.revenue)}รายได้</span>
        <span>${dot(_FIN_SANKEY_CLR.cost)}ต้นทุน/ค่าใช้จ่าย/ภาษี</span>
        <span>${dot(_FIN_SANKEY_CLR.grossProfit)}กำไรขั้นต้น</span>
        <span>${dot(_FIN_SANKEY_CLR.profit)}กำไรที่เหลือ</span>
      </div>
      ${svg}
      <div id="fin-sankey-sector-box"></div>
    </div>`;
}

// ============================================================
// 🆚 เทียบกับกลุ่ม (Sector Median) — ต่อยอดการ์ด Sankey ด้านบน โหลดแบบ lazy ตอนกดปุ่มเท่านั้น
// (ไม่ยิง /api/financials-sankey-sector ทุกครั้งที่เปิดหน้า เพราะต้องวน TTM ทั้งกลุ่ม ~ช้ากว่า
// การ์ด Sankey เดี่ยวมาก) แคชผลไว้ต่อ symbol กันยิงซ้ำตอนกดปุ่มเปิด-ปิดสลับไปมา
// ============================================================
const _finSankeySectorCache = {};   // sym -> response จาก /api/financials-sankey-sector (หรือ {error})

// stages ต้องตรงกับที่ _renderFinSankeySvg วาดจริงเป๊ะ (costKey/contKey เดียวกัน) ใช้คำนวณ
// delta badge ต่อขั้นให้ตรงกับกล่องที่เห็นในทั้งสองต้นไม้ — lowerBetter บอกทิศทางที่ "ดีกว่า"
// สำหรับสีเขียว/แดงของ badge (ต้นทุน/ค่าใช้จ่าย/ภาษี ยิ่งต่ำยิ่งดี, กำไรทุกขั้นยิ่งสูงยิ่งดี)
const _FIN_SANKEY_DELTA_STAGES = [
  { key: 'cogs',             label: 'ต้นทุนขาย % ของรายได้',            lowerBetter: true  },
  { key: 'gross_profit',     label: 'กำไรขั้นต้น % ของรายได้ (GPM)',    lowerBetter: false },
  { key: 'sga_total',        label: 'SG&A % ของรายได้',                 lowerBetter: true  },
  { key: 'operating_profit', label: 'กำไรจากการดำเนินงาน % (EBIT/Rev)', lowerBetter: false },
  { key: 'financial_cost',   label: 'ต้นทุนทางการเงิน % ของรายได้',     lowerBetter: true  },
  { key: 'pretax_profit',    label: 'กำไรก่อนภาษี % ของรายได้',         lowerBetter: false },
  { key: 'tax_expense',      label: 'ภาษีเงินได้ % ของรายได้',          lowerBetter: true  },
  { key: 'net_profit',       label: 'กำไรสุทธิ % ของรายได้ (NPM)',      lowerBetter: false },
];

// สร้าง object ทรงเดียวกับ v ของหุ้นเดี่ยว (ให้ _renderFinSankeySvg เดิมใช้วาดได้ตรงๆ) จาก
// median % ของกลุ่ม × revenue ของหุ้นตั้งต้น — ใช้ revenue ฐานเดียวกับต้นไม้ด้านบนเจตนา ให้สอง
// ภาพสเกลพิกเซลเท่ากันเป๊ะ เทียบด้วยตาได้ตรงๆ โดยไม่ต้องคิดสัดส่วนเอง
function _finSankeySectorTreeV(medianPct, revenue) {
  const out = { revenue };
  for (const st of _FIN_SANKEY_DELTA_STAGES) {
    const p = medianPct[st.key];
    out[st.key] = p != null ? revenue * p / 100 : null;
  }
  return out;
}

function _finSankeySectorDeltaRowsHtml(data, stockV) {
  const rev = stockV.revenue;
  const mp = data.median_pct, cov = data.coverage;
  return _FIN_SANKEY_DELTA_STAGES.map(st => {
    const stockPct = (rev && stockV[st.key] != null) ? stockV[st.key] / rev * 100 : null;
    const secPct = mp[st.key];
    if (stockPct == null || secPct == null) return '';
    const delta = stockPct - secPct;
    const good = st.lowerBetter ? delta < 0 : delta > 0;
    const flat = Math.abs(delta) < 0.05;
    const color = flat ? 'var(--text2)' : (good ? 'var(--green,#3fb950)' : 'var(--red,#f85149)');
    const sign = delta > 0 ? '+' : '';
    const covN = cov[st.key] || 0;
    return `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:5px 0;border-bottom:1px solid var(--border);font-size:11.5px">
      <span style="color:var(--text2)">${st.label}${_tipIconHtml(`หุ้นนี้: <b>${stockPct.toFixed(1)}%</b> ของรายได้ · median กลุ่ม: <b>${secPct.toFixed(1)}%</b> (คำนวณจาก ${covN} หุ้นในกลุ่มที่มีข้อมูล TTM ครบรายการนี้)`)}</span>
      <span style="white-space:nowrap"><b style="color:var(--text,#e6edf3)">${stockPct.toFixed(1)}%</b> <span style="color:var(--text2);font-size:10.5px">vs กลุ่ม ${secPct.toFixed(1)}%</span> <b style="color:${color}">${sign}${delta.toFixed(1)}pp</b></span>
    </div>`;
  }).join('');
}

function _finSankeySectorBodyHtml(data, stockV) {
  if (data.error) {
    return `<div style="font-size:11.5px;color:var(--text2);padding:10px 0 2px">ℹ ${_escHtml(data.error)}</div>`;
  }
  const sectorV = _finSankeySectorTreeV(data.median_pct, stockV.revenue);
  const svg = _renderFinSankeySvg(sectorV);
  if (!svg) {
    return `<div style="font-size:11.5px;color:var(--text2);padding:10px 0 2px">ℹ ข้อมูลกลุ่มไม่พอสร้างแผนภาพเทียบ (หุ้นในกลุ่มมี TTM ไม่ครบพอ)</div>`;
  }
  const widenNote = data.widened
    ? `<div style="font-size:11px;color:var(--text2);margin-bottom:8px">ℹ กลุ่ม sector มีสมาชิกน้อยเกินไป (เทียบ % ได้ไม่มีนัยยะ) ระบบขยับไปเทียบระดับ <b>industry</b> ที่กว้างขึ้นแทนอัตโนมัติ</div>` : '';
  const levelLabel = data.level === 'industry' ? 'Industry' : 'Sector';
  return `
    <div style="border-top:1px dashed var(--border);padding-top:12px;margin-top:14px">
      <div style="font-size:13px;font-weight:700;margin-bottom:2px">🆚 เทียบกับกลุ่ม — ${_escHtml(data.sector_name)} <span style="font-weight:400;color:var(--text2);font-size:11px">(${levelLabel})</span>${_tipIconHtml('แท่งกลุ่มนี้คำนวณจาก <b>median</b> (ค่ากลาง) ของแต่ละ % ต่อรายได้ (COGS%, GPM%, SG&amp;A%, ...) แยกอิสระต่อรายการ ข้ามทุกหุ้นในกลุ่มเดียวกัน — ใช้ median แทน weighted-sum เพื่อไม่ให้หุ้นใหญ่ตัวเดียวครอบงำภาพ "โครงสร้างต้นทุนทั่วไปของกลุ่ม"<br><br>⚠ เพราะเป็นค่ากลางของคนละบริษัท ไม่ใช่งบจริงบริษัทเดียว ตัวเลขแต่ละขั้นอาจไม่รวมกันครบ 100% เป๊ะเหมือนต้นไม้ของหุ้นด้านบน — ใช้ดูรูปทรง/สัดส่วนเทียบเท่านั้น ไม่ใช่งบจริงของกลุ่ม')}</div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:10px">${data.member_count} หุ้นในกลุ่ม (ไม่รวมกลุ่มการเงิน/ตัวเอง) · revenue ฐานใช้ของหุ้นตั้งต้นเอง ให้สเกลพิกเซลตรงกับต้นไม้ด้านบนเทียบด้วยตาได้ตรงๆ</div>
      ${widenNote}
      ${svg}
      <div style="font-size:12px;font-weight:700;margin:12px 0 2px">📊 หุ้นนี้ vs ค่ากลางกลุ่ม — % ต่อรายได้ รายขั้น${_tipIconHtml('pp = percentage point (ผลต่างหน่วย %) เขียว = ดีกว่ากลุ่ม, แดง = แย่กว่ากลุ่ม (ต้นทุน/ค่าใช้จ่าย/ภาษี ยิ่งต่ำยิ่งดี, ทุกขั้นกำไร ยิ่งสูงยิ่งดี) แตะไอคอน ℹ ที่แต่ละแถวดูค่าดิบ + จำนวนหุ้นที่ใช้คำนวณ median')}</div>
      ${_finSankeySectorDeltaRowsHtml(data, stockV)}
    </div>`;
}

async function _toggleFinSankeySectorCompare(sym) {
  const box = document.getElementById('fin-sankey-sector-box');
  const btn = document.getElementById('fin-sankey-sector-btn');
  if (!box) return;
  // กดซ้ำตอนเปิดอยู่แล้ว = ปิด (toggle) ไม่ต้องยิง fetch ใหม่
  if (box.dataset.open === '1') {
    box.innerHTML = '';
    box.dataset.open = '0';
    return;
  }
  box.dataset.open = '1';
  box.innerHTML = '<div class="empty" style="padding:12px 0;font-size:12px">กำลังโหลดข้อมูลกลุ่ม (วนคำนวณ TTM ทุกหุ้นใน sector อาจใช้เวลาสักครู่)...</div>';
  const stockV = _finSankeyStockV;
  if (btn) { btn.disabled = true; btn.textContent = '⏳ กำลังโหลด...'; }
  // การ์ดอาจถูกแทนที่ทั้งหมด (สลับหุ้น/สลับรายไตรมาส-รายปี — _renderFinMergedReport เขียนทับ
  // #fin-result.innerHTML ทั้งก้อน) ระหว่างรอ fetch — box/btn ที่ capture ไว้ข้างบนจะกลาย
  // เป็น DOM node ที่หลุดไปแล้ว เขียนผลลงไปได้แต่ไม่มีใครเห็น เช็ค id เดิมยังชี้ node เดิมจริง
  // ก่อนเขียนทุกครั้ง กัน response เก่าไปเขียนทับ/ปลุกสถานะโหลดของการ์ดหุ้น/งวดอื่นที่ไม่เกี่ยวข้อง
  const stillCurrent = () => document.getElementById('fin-sankey-sector-box') === box;
  try {
    let data = _finSankeySectorCache[sym];
    if (!data) {
      // เท่ากับ timeout ของ /api/peer-group-detail (dashboard.js) ที่ทำงานหนักแบบเดียวกัน
      // (วน TTM หลายสิบหุ้น cache miss ยิง network ได้ถึง 3 แหล่ง/ตัว) — เดิมตั้งแค่ 25 วิ
      // สั้นกว่า precedent เกือบ 3 เท่า ทำให้ sector ที่ยังไม่เคย cache timeout ง่ายเกินจำเป็น
      const r = await _fetchTimeout(`/api/financials-sankey-sector/${encodeURIComponent(sym)}`, 60000,
        'หมดเวลารอข้อมูลกลุ่ม (เกิน 60 วิ)');
      data = await r.json();
      // ไม่ cache error — 404 {error} ตอน set_data.json ถูกเขียนทับกลางคัน (Quick Update) เป็น
      // transient ถ้า cache ไว้ ปุ่มจะโชว์ error ค้างจนกว่าจะ reload หน้า กดใหม่ไม่ช่วย
      if (data && !data.error) _finSankeySectorCache[sym] = data;
    }
    if (stillCurrent()) {
      box.innerHTML = (data && data.error)
        ? `<div style="font-size:11.5px;color:var(--red);padding:10px 0 2px">⚠ ${_escHtml(data.error)}</div>`
        : _finSankeySectorBodyHtml(data, stockV);
    }
  } catch (e) {
    if (stillCurrent()) box.innerHTML = `<div style="font-size:11.5px;color:var(--red);padding:10px 0 2px">⚠ ${_escHtml(e.message)}</div>`;
  } finally {
    if (btn && document.getElementById('fin-sankey-sector-btn') === btn) {
      btn.disabled = false; btn.textContent = '🆚 เทียบกับกลุ่ม (Sector Median)';
    }
  }
}

// การ์ดสรุปอัตราส่วนหลัก (KEY RATIOS) บนสุดของแท็บ "งบรวมทุกแหล่ง" — ใช้งวดล่าสุด/TTM จาก
// d.quarters เสมอไม่ว่า toggle รายไตรมาส/รายปีจะตั้งไว้ที่โหมดไหน (ต้องใช้ข้อมูลรายไตรมาสเท่านั้น
// ถึงจะคำนวณ TTM ได้ และ d.years ไม่มี field capex/current_assets/current_liabilities/inventory/
// accounts_receivable ให้ใช้ ดู docstring ของ rollup_full_report_annual ใน financials_store.py)
function _finKeyRatiosHtml(qs, cur) {
  if (!qs || qs.length < 4) return '';
  const sorted = [...qs].sort((a, b) => (a.year_be * 4 + a.q) - (b.year_be * 4 + b.q));
  const byKey = {};
  sorted.forEach(c => { byKey[c.year_be * 4 + c.q] = c; });
  // งบดุล/กระแสเงินสดรายไตรมาสจาก Yahoo มักตามหลัง P&L (ที่มาจาก SET/Finnomena) อยู่ 1 งวด —
  // ไตรมาสล่าสุดสุดอาจมี revenue/net_profit แล้วแต่ total_equity/cfo ยังไม่มา ใช้ pattern เดียวกับ
  // _latest_value ใน app.py (peer-group-detail): หา "ไตรมาสล่าสุดที่มี field นี้จริง" ก่อนเสมอ
  // แทนอ่านจากไตรมาสสุดท้ายของทั้งชุดตรงๆ (lookback 4 ไตรมาสพอสำหรับความล่าช้าปกติ) — ต้องเทียบ
  // ผ่าน byKey (year_be*4+q) เหมือน ttm() ด้านล่าง ไม่ใช่ไล่ตำแหน่ง sorted[i] ตรงๆ (เดิมเป็นแบบนั้น
  // ถ้า quarters มีไตรมาสไหนขาดหายไปทั้งงวด ตำแหน่ง "4 ตัวท้าย" จะย้อนไกลเกิน 4 ไตรมาสปฏิทินจริง
  // โดยไม่รู้ตัว — บั๊กเดียวกับที่แก้ไปแล้วใน app.py _latest_value)
  const anchorKey = sorted.length ? sorted[sorted.length - 1].year_be * 4 + sorted[sorted.length - 1].q : null;
  const latestVal = field => {
    if (anchorKey == null) return null;
    for (let off = 0; off < 4; off++) {
      const row = byKey[anchorKey - off];
      if (row && row[field] != null) return row[field];
    }
    return null;
  };
  // หา anchor ของ TTM ด้วย byKey (year_be*4+q) เหมือน latestVal ไม่ใช่ไล่ตำแหน่ง sorted[i] —
  // ถ้า quarters มีงวดขาดกลางชุด "4 ตัวท้าย" ของอาเรย์จะย้อนไกลเกิน 4 ไตรมาสปฏิทินจริง ทำให้
  // ได้ TTM ที่เก่าค้าง (บั๊กเดียวกับที่แก้ใน latestVal / app.py _latest_value)
  const ttm = field => {
    if (anchorKey == null) return null;
    let anchorK = null;
    for (let off = 0; off < 4; off++) {
      const row = byKey[anchorKey - off];
      if (row && row[field] != null) { anchorK = anchorKey - off; break; }
    }
    if (anchorK == null) return null;
    let sum = 0;
    for (let off = 0; off < 4; off++) {
      const p = byKey[anchorK - off];
      if (!p || p[field] == null) return null;
      sum += p[field];
    }
    return sum;
  };
  // ไตรมาสล่าสุดที่มี field นี้จริง อยู่ห่างจากงวดล่าสุดของชุดกี่ไตรมาส (สำหรับเตือนว่า TTM
  // คำนวณจากหน้าต่างเก่ากว่าไตรมาสล่าสุด — เหมือน staleBy ของการ์ด Sankey ด้านบน)
  const anchorOffOf = field => {
    if (anchorKey == null) return null;
    for (let off = 0; off < 4; off++) { const r = byKey[anchorKey - off]; if (r && r[field] != null) return off; }
    return null;
  };
  const npTtm = ttm('net_profit'), opTtm = ttm('operating_profit'), cfoTtm = ttm('cfo'),
        capexTtm = ttm('capex'), taxTtm = ttm('tax_expense'), pretaxTtm = ttm('pretax_profit'),
        daTtm = ttm('da');
  const npAnchorOff = anchorOffOf('net_profit');
  const eq = latestVal('total_equity'), ta = latestVal('total_assets'), td = latestVal('total_debt'),
        cash = latestVal('cash'), ca = latestVal('current_assets'), cl = latestVal('current_liabilities');

  // ROE / D/E / WC/E / ROA / FCF-NP / Capex-Dep หารด้วยฐานที่ "ติดลบไม่ได้ตามธรรมชาติ" (ส่วนของ
  // ผู้ถือหุ้น / สินทรัพย์รวม / กำไรสุทธิ / D&A) — ถ้าฐานติดลบ (ขาดทุนสะสม, หรือข้อมูลต้นทางเพี้ยน
  // แบบ warnNegative ของ total_assets) การหารจะกลับเครื่องหมายทำให้ค่าอ่านผิดความหมาย (เช่น ROE
  // ขาดทุน→โชว์ +สวยหรู) เหมือน "negative ROE trap" ที่กราฟ ROE/D/E ด้านล่างเตือนไว้ — ซ่อนค่าแทน
  // + ใส่ caveat (roic กันตัวเองด้วย invCap>0 อยู่แล้ว)
  const eqPos = eq != null && eq > 0;
  const taPos = ta != null && ta > 0;
  const npPos = npTtm != null && npTtm > 0;
  const daPos = daTtm != null && daTtm > 0;
  const roe = (npTtm != null && eqPos) ? npTtm / eq * 100 : null;
  const roa = (npTtm != null && taPos) ? npTtm / ta * 100 : null;
  // ROIC = NOPAT TTM (กำไรจากการดำเนินงาน หลังหักภาษีสมมติ) ÷ เงินทุนที่ลงทุน (หนี้+ทุน-เงินสด)
  // — clamp อัตราภาษีที่ 0-60% กันไตรมาสขาดทุน/มีรายการพิเศษทำให้อัตราภาษีดิบ (tax/pretax) เพี้ยน
  let roic = null;
  if (opTtm != null && pretaxTtm != null && pretaxTtm !== 0 && taxTtm != null && td != null && eq != null && cash != null) {
    const taxRate = Math.min(0.6, Math.max(0, taxTtm / Math.abs(pretaxTtm)));
    const invCap = td + eq - cash;
    if (invCap > 0) roic = opTtm * (1 - taxRate) / invCap * 100;
  }
  const deRatio = (td != null && eqPos) ? td / eq : null;
  const wcE = (ca != null && cl != null && eqPos) ? (ca - cl) / eq : null;
  const netDebt = (td != null && cash != null) ? td - cash : null;
  const capexDep = (capexTtm != null && daPos) ? Math.abs(capexTtm) / daTtm : null;
  const fcfNp = (cfoTtm != null && capexTtm != null && npPos) ? (cfoTtm - Math.abs(capexTtm)) / npTtm : null;

  const curW = _finCurWord(cur);
  const milUnit = curW === 'บาท' ? 'ล.บ.' : 'ล.' + curW;
  const milNote = curW === 'บาท' ? 'ล้านบาท' : 'ล้าน' + curW;
  const pct = v => v == null ? '—' : `${v.toFixed(1)}%`;
  const xf = v => v == null ? '—' : `${v.toFixed(2)}x`;
  const bahtM = v => v == null ? '—' : `${Math.round(v / 1e6).toLocaleString('en-US')} ${milUnit}`;

  const tile = (label, val, tip, color) => `
    <div title="${tip}" style="flex:1;min-width:112px;background:var(--card2);border:1px solid var(--border);border-radius:8px;padding:8px 10px;cursor:help">
      <div style="font-size:10.5px;color:var(--text2);white-space:nowrap">${label}</div>
      <div style="font-size:15px;font-weight:700;margin-top:2px${color ? `;color:${color}` : ''}">${val}</div>
    </div>`;

  return `
  <div style="margin-bottom:14px">
    <div style="font-size:12px;font-weight:700;margin-bottom:8px">📌 อัตราส่วนหลัก (งวดล่าสุด/TTM)</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      ${tile('ROE (TTM)', pct(roe), 'กำไรสุทธิ TTM ÷ ส่วนของผู้ถือหุ้นล่าสุด')}
      ${tile('ROIC (TTM)', pct(roic), 'NOPAT TTM (กำไรจากการดำเนินงาน × (1-อัตราภาษี)) ÷ เงินทุนที่ลงทุน (หนี้+ทุน-เงินสด) — วัดประสิทธิภาพใช้เงินทุนรวม ไม่ผูกกับโครงสร้างทุน')}
      ${tile('ROA (TTM)', pct(roa), 'กำไรสุทธิ TTM ÷ สินทรัพย์รวมล่าสุด')}
      ${tile('D/E Ratio', xf(deRatio), 'หนี้มีภาระดอกเบี้ย ÷ ส่วนของผู้ถือหุ้น')}
      ${tile('WC/E', xf(wcE), '(สินทรัพย์หมุนเวียน - หนี้สินหมุนเวียน) ÷ ส่วนของผู้ถือหุ้น — เงินทุนหมุนเวียนเทียบทุน')}
      ${tile('Net Debt', bahtM(netDebt), `หนี้มีภาระดอกเบี้ย - เงินสด (หน่วย${milNote}) — บวก(แดง)=หนี้มากกว่าเงินสด, ลบ(เขียว)=เงินสดสุทธิเป็นบวก`, netDebt == null ? null : (netDebt > 0 ? '#f85149' : '#3fb950'))}
      ${tile('Total Assets', bahtM(ta), `สินทรัพย์รวมล่าสุด (หน่วย${milNote})`)}
      ${tile('Equity', bahtM(eq), `ส่วนของผู้ถือหุ้นล่าสุด (หน่วย${milNote})`)}
      ${tile('Total Debt', bahtM(td), `หนี้ที่มีภาระดอกเบี้ยล่าสุด (หน่วย${milNote})`)}
      ${tile('Capex/Dep', xf(capexDep), 'CapEx TTM ÷ ค่าเสื่อมราคา&ตัดจำหน่าย (D&A) TTM — มากกว่า 1x แปลว่าลงทุนขยายเร็วกว่าสินทรัพย์เดิมเสื่อม')}
      ${tile('FCF/NP', xf(fcfNp), '(CFO - CapEx) TTM ÷ กำไรสุทธิ TTM — วัดคุณภาพกำไร ยิ่งใกล้/เกิน 1x ยิ่งแปลว่ากำไรเป็นเงินสดจริง')}
    </div>
    ${(eq != null && eq <= 0) ? `
    <div style="margin-top:8px;font-size:10.5px;color:var(--red);line-height:1.5">
      ⚠ ส่วนของผู้ถือหุ้นล่าสุด${eq < 0 ? 'ติดลบ' : 'เป็นศูนย์'} (${bahtM(eq)}) — ซ่อน ROE / D/E / WC/E เพราะการหารด้วยฐาน${eq < 0 ? 'ติดลบ' : 'ศูนย์'}อ่านค่าผิดความหมาย
    </div>` : ''}
    ${(ta != null && ta <= 0) ? `
    <div style="margin-top:6px;font-size:10.5px;color:var(--red);line-height:1.5">
      ⚠ สินทรัพย์รวมล่าสุด${ta < 0 ? 'ติดลบ' : 'เป็นศูนย์'} (น่าจะข้อมูลต้นทางคลาดเคลื่อน) — ซ่อน ROA
    </div>` : ''}
    ${(npTtm != null && npAnchorOff != null && npAnchorOff > 0) ? `
    <div style="margin-top:6px;font-size:10.5px;color:#e3b341;line-height:1.5">
      ⚠ ไตรมาสล่าสุดยังไม่มีกำไรสุทธิจากต้นทาง — ROE / ROIC / ROA / FCF-NP คำนวณจาก TTM ของ 4 ไตรมาสก่อนหน้า (เก่ากว่างวดล่าสุด ${npAnchorOff} ไตรมาส)
    </div>` : ''}
  </div>`;
}

// Heatmap YoY%/QoQ% ไตรมาส×ปี (1 ตัวชี้วัด/ตาราง) — สีไล่ตามขนาด % (เขียว=โต แดง=หด) ให้เห็น
// รูปแบบฤดูกาล/รอบธุรกิจไวกว่าไล่ดูตัวเลขในตาราง · offset ตาม _qplChgMode · ต้องมี ≥2 ปีถึงมีอะไรเทียบ
function _finYoyHeatmapHtml(qs, field, title) {
  const sorted = [...qs].sort((a, b) => (a.year_be * 4 + a.q) - (b.year_be * 4 + b.q));
  const yoy = _qplYoySeries(sorted, field, _qplChgOffset());
  const byYearQ = {};
  sorted.forEach((c, i) => { (byYearQ[c.year_be] = byYearQ[c.year_be] || {})[c.q] = yoy[i]; });
  const years = Object.keys(byYearQ).map(Number).sort((a, b) => a - b).slice(-8);
  if (years.length < 2) return '';
  const cellColor = v => {
    if (v == null) return 'transparent';
    const t = Math.max(-1, Math.min(1, v / 30));   // ±30% = สีเข้มสุด
    return t >= 0 ? `rgba(63,185,80,${(0.12 + Math.abs(t) * 0.55).toFixed(2)})` : `rgba(248,81,73,${(0.12 + Math.abs(t) * 0.55).toFixed(2)})`;
  };
  const headerRow = years.map(y => `<th style="padding:4px 7px;font-size:10px;color:var(--text2);text-align:center;white-space:nowrap">${y}</th>`).join('');
  const rows = [1, 2, 3, 4].map(q => {
    const cells = years.map(y => {
      const v = (byYearQ[y] || {})[q];
      const txt = v == null ? '—' : `${v > 0 ? '+' : ''}${v.toFixed(0)}%`;
      return `<td style="padding:4px 7px;text-align:center;font-size:10.5px;background:${cellColor(v)};border:1px solid var(--border)" title="${txt}">${txt}</td>`;
    }).join('');
    return `<tr><td style="padding:4px 7px;font-size:10.5px;font-weight:600;color:var(--text2);white-space:nowrap">Q${q}</td>${cells}</tr>`;
  }).join('');
  return `<div style="flex:1;min-width:260px">
    <div style="font-size:11px;color:var(--text2);margin-bottom:4px">${title}</div>
    <div style="overflow-x:auto"><table style="border-collapse:collapse">
      <thead><tr><th></th>${headerRow}</tr></thead>
      <tbody>${rows}</tbody>
    </table></div>
  </div>`;
}

// เทียบไตรมาสเดียวกันข้ามปี (Q1 ปีนี้ vs ปีก่อนๆ) — ตัดผลฤดูกาลออกเห็นแนวโน้มเนื้อธุรกิจจริง ต่างจาก
// กราฟ P&L YoY ที่ไล่ตามเวลาต่อเนื่อง อันนี้จัดกลุ่มเป็นแท่งข้างกันต่อไตรมาส (สูงสุด 5 ปีล่าสุด กันแท่ง
// แน่นเกินไป) reuse dict/destroy เดียวกับ _finExtraChartInsts เพราะ key ด้วย canvasId อยู่แล้ว
const _FIN_QCMP_DEFS = [
  ['fin-chart-qcmp-revenue', 'revenue', 'รายได้ — เทียบไตรมาสเดียวกันข้ามปี'],
  ['fin-chart-qcmp-gp', 'gross_profit', 'กำไรขั้นต้น — เทียบไตรมาสเดียวกันข้ามปี'],
  ['fin-chart-qcmp-sga', 'sga_total', 'SG&A — เทียบไตรมาสเดียวกันข้ามปี'],
  ['fin-chart-qcmp-np', 'net_profit', 'กำไรสุทธิ — เทียบไตรมาสเดียวกันข้ามปี'],
];
function _drawQuarterCompareCharts(qs) {
  const sorted = [...qs].sort((a, b) => (a.year_be * 4 + a.q) - (b.year_be * 4 + b.q));
  const byYQ = {};
  sorted.forEach(c => { (byYQ[c.year_be] = byYQ[c.year_be] || {})[c.q] = c; });
  const years = Object.keys(byYQ).map(Number).sort((a, b) => a - b).slice(-5);
  const palette = ['#6e7681', '#4dabf7', '#e8b84b', '#e2828f', '#3fb950'];
  _FIN_QCMP_DEFS.forEach(([id, field]) => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    _destroyExtraChart(id);
    const datasets = years.map((yr, i) => ({
      label: String(yr),
      backgroundColor: palette[i % palette.length],
      data: [1, 2, 3, 4].map(q => { const row = (byYQ[yr] || {})[q]; return (row && row[field] != null) ? _toKb(row[field]) : null; }),
    }));
    if (!datasets.some(ds => ds.data.some(v => v != null))) return;
    _finExtraChartInsts[id] = new Chart(canvas, {
      type: 'bar',
      data: { labels: ['Q1', 'Q2', 'Q3', 'Q4'], datasets },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: {
          legend: { labels: { color: '#8b949e', font: { size: 9 }, boxWidth: 10, padding: 8 } },
          tooltip: {
            backgroundColor: '#1c2128', borderColor: '#30363d', borderWidth: 1,
            titleColor: '#e6edf3', bodyColor: '#8b949e',
            callbacks: { label: ctx => ctx.raw == null ? '' : ` ${ctx.dataset.label}: ${Math.round(ctx.raw).toLocaleString('en-US')} พันบาท` }
          }
        },
        scales: {
          x: { ticks: { color: '#8b949e', font: { size: 9 } }, grid: { display: false } },
          y: { ticks: { color: '#8b949e', font: { size: 9 }, callback: v => Number(v).toLocaleString('en-US') }, grid: { color: '#1e2736' } }
        }
      }
    });
  });
}

// wrapper — เรียกได้จากทั้ง loadFinMergedReport (มี try/catch อยู่แล้ว) และปุ่ม toggle
// setFinMergedPeriod/setQplChgMode (onclick ตรงๆ ไม่มี guard) — ถ้าการประกอบตาราง/HTML
// (ส่วน synchronous ก่อน innerHTML) throw ปุ่มจะติ๊ก .active ใหม่แล้วแต่เนื้อหาไม่อัปเดต
// = toggle ค้างเงียบๆ ไม่ให้เกิดแบบนั้น โชว์ error card แทน
function _renderFinMergedReport(d) {
  try {
    _renderFinMergedReportImpl(d);
  } catch (e) {
    console.error('merged report render failed', e);
    const box = document.getElementById('fin-result');
    if (box) box.innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ แสดงผลงบผสานล้มเหลว: ${_escHtml(e && e.message || e)}</div>`;
  }
}
function _renderFinMergedReportImpl(d) {
  const qs = d.quarters || [];
  const ys = d.years || [];
  if (!qs.length && !ys.length) {
    document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">ไม่พบข้อมูลงบของหุ้นนี้</div>';
    return;
  }
  const periodToggle = `
    <div style="display:flex;flex-direction:column;gap:4px;margin-bottom:10px">
      <span style="font-size:10px;color:var(--text2)">ช่วงเวลา</span>
      <div class="filter-row" style="gap:0;margin:0">
        <button class="filter-btn ${_finMergedPeriod === 'q' ? 'active' : ''}" id="fin-merged-period-q" onclick="setFinMergedPeriod('q')" style="border-radius:6px 0 0 6px;font-size:11px;padding:4px 10px">รายไตรมาส</button>
        <button class="filter-btn ${_finMergedPeriod === 'y' ? 'active' : ''}" id="fin-merged-period-y" onclick="setFinMergedPeriod('y')" style="border-radius:0 6px 6px 0;font-size:11px;padding:4px 10px">รายปี</button>
      </div>
    </div>`;

  let tableHtml, scrollId;
  const isQMode = _finMergedPeriod === 'q';
  const hasChartData = isQMode ? qs.length : ys.length;
  // รายปีไม่มี QoQ (ปีก่อน = YoY อยู่แล้ว) — ปุ่มสลับโชว์เฉพาะโหมดรายไตรมาส
  const chgLabelHtml = isQMode ? `<span id="qpl-chg-title">${_qplChgLabel()}</span>` : 'YoY';
  const chartHtml = hasChartData ? `
    <div style="font-size:12px;font-weight:700;margin-bottom:6px">📈 P&amp;L CHANGE ${chgLabelHtml}% (รายได้/ต้นทุน/กำไรสุทธิ) + กำไรขั้นต้น GPM% ${isQMode ? '(20Q)' : '(รายปี)'}</div>
    ${isQMode ? _qplChgToggleHtml() : ''}
    <div style="position:relative;height:260px;margin-bottom:16px"><canvas id="qpl-yoy-chart"></canvas></div>` : '';

  // การ์ด KPI สรุปอัตราส่วนหลัก — เสมอโชว์ไม่ว่า toggle อยู่โหมดไหน (ดู docstring _finKeyRatiosHtml)
  const keyRatiosHtml = (() => { try { return _finKeyRatiosHtml(qs, d.currency); } catch (e) { return ''; } })();

  // Seasonality กำไรสุทธิ (นอกจากรายได้) + เทียบไตรมาสเดียวกันข้ามปี + Heatmap YoY% — มีความหมาย
  // เฉพาะรายไตรมาสเท่านั้น (ปีต่อปีไม่มี "ไตรมาส" ให้เทียบ) ห่อ try/catch กันกราฟเสริมพังหน้าหลัก
  const seasonalityHtml = (isQMode && qs.length) ? (() => { try {
    return `<div style="font-size:12px;font-weight:700;margin:4px 0 10px">📅 ฤดูกาล (Seasonality)</div>
    <div style="display:flex;gap:24px;flex-wrap:wrap;margin-bottom:6px">
      <div style="flex:1;min-width:260px">${_finSeasonalityBlock(_finQuartersToDateMap(qs, 'revenue'), 'รายได้')}</div>
      <div style="flex:1;min-width:260px">${_finSeasonalityBlock(_finQuartersToDateMap(qs, 'net_profit'), 'กำไรสุทธิ')}</div>
    </div>`;
  } catch (e) { return ''; } })() : '';

  const qcmpHtml = (isQMode && qs.length) ? `
    <div style="font-size:12px;font-weight:700;margin:4px 0 10px">📊 เทียบไตรมาสเดียวกันข้ามปี (ตัดผลฤดูกาล)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-bottom:18px">
      ${_FIN_QCMP_DEFS.map(([id, , title]) => `
        <div>
          <div style="font-size:11px;color:var(--text2);margin-bottom:4px">${title}</div>
          <div style="position:relative;height:200px"><canvas id="${id}"></canvas></div>
        </div>`).join('')}
    </div>` : '';

  const heatmapHtml = (isQMode && qs.length) ? (() => { try {
    const cl = _qplChgLabel();
    const rev = _finYoyHeatmapHtml(qs, 'revenue', `รายได้ ${cl}%`);
    const np = _finYoyHeatmapHtml(qs, 'net_profit', `กำไรสุทธิ ${cl}%`);
    if (!rev && !np) return '';
    return `<div style="font-size:12px;font-weight:700;margin:4px 0 10px">🗓 Heatmap ${cl}% รายไตรมาส</div>
    <div style="display:flex;gap:24px;flex-wrap:wrap;margin-bottom:18px">${rev}${np}</div>`;
  } catch (e) { return ''; } })() : '';

  // กราฟตัวชี้วัดเพิ่มเติมจากงบดุล/กระแสเงินสดที่ผสานได้ (ดู _drawFinExtraCharts) — วางเป็น grid
  // ตอบสนองขนาดจอ ไม่ fix จำนวนคอลัมน์ (auto-fit) กันล้นจอมือถือ · arSales/invTurn/depPct เฉพาะ
  // รายไตรมาสเท่านั้น เพราะ d.years ไม่มี field accounts_receivable/inventory/capex ให้ใช้
  const extraChartDefs = [
    ['fin-chart-opm-npm', 'Operating Margin vs Net Margin'],
    ['fin-chart-oplev', `Operating Leverage (รายได้ ${isQMode ? _qplChgLabel() : 'YoY'} vs กำไรสุทธิ ${isQMode ? _qplChgLabel() : 'YoY'})`],
    ['fin-chart-debt', 'โครงสร้างหนี้ / เงินสด / ส่วนของผู้ถือหุ้น'],
    ['fin-chart-cfo-np', 'กระแสเงินสดดำเนินงาน (CFO) vs กระแสเงินสดอิสระ (FCF) vs กำไรสุทธิ'],
    ['fin-chart-netdebt', 'Net Debt (หนี้ - เงินสด)'],
    ['fin-chart-roe', `ROE ${isQMode ? '(TTM 4 ไตรมาส)' : ''}`],
    ['fin-chart-de', 'หนี้สินต่อทุน (D/E Ratio)'],
    ['fin-chart-sga', 'SG&A to Sales %'],
    ...(isQMode ? [
      ['fin-chart-arsales', 'AR / ยอดขาย (Accounts Receivable to Sales %)'],
      ['fin-chart-invturn', 'Inventory Turnover (รอบ, TTM)'],
      ['fin-chart-deppct', 'Depreciation % ของรายได้'],
    ] : []),
  ];
  const extraChartsHtml = hasChartData ? `
    <div style="font-size:12px;font-weight:700;margin-bottom:10px">📊 ตัวชี้วัดเพิ่มเติม (จากงบดุล/กระแสเงินสดที่ผสานได้)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-bottom:18px">
      ${extraChartDefs.map(([id, title]) => `
        <div>
          <div style="font-size:11px;color:var(--text2);margin-bottom:4px">${title}</div>
          <div style="position:relative;height:200px"><canvas id="${id}"></canvas></div>
          ${_FIN_CHART_WARN_IDS.has(id) ? `<div id="${id}-warn" style="display:none;font-size:10px;color:var(--red);margin-top:4px;line-height:1.5"></div>` : ''}
        </div>`).join('')}
    </div>` : '';
  if (isQMode) {
    scrollId = 'merged-scroll-q';
    tableHtml = qs.length ? _qplTableCore(qs, scrollId, _mergedExtraQuarterlyRows).html
                          : '<div class="empty" style="padding:16px">ไม่พบข้อมูลรายไตรมาส</div>';
  } else {
    scrollId = 'merged-scroll-y';
    tableHtml = ys.length ? _mergedTableAnnual(ys, scrollId)
                          : '<div class="empty" style="padding:16px">ไม่พบข้อมูลรายปี</div>';
  }

  // เตือนถ้าเจอ สินทรัพย์รวม/หนี้/เงินสด ติดลบในชุดข้อมูลที่กำลังโชว์ (ดู warnNegative ใน
  // _mergedBsCfRowDefs) — เจอจริงกับบางหุ้น mirror เพราะ Finnomena raw ข้อมูลคลาดเคลื่อน
  const warnFields = ['total_assets', 'total_debt', 'cash'];
  const rowsShown = isQMode ? qs : ys;
  const hasBsWarn = rowsShown.some(r => warnFields.some(f => r[f] != null && r[f] < 0));
  const bsWarnCaveat = hasBsWarn ? `
    <div style="margin-top:10px;font-size:11.5px;color:var(--red);line-height:1.6">
      ⚠ = สินทรัพย์รวม/หนี้/เงินสดติดลบ (ไม่ปกติทางบัญชี) — น่าจะเป็นข้อมูลคลาดเคลื่อนจากต้นทาง
      (Finnomena/Yahoo) ไม่ใช่ตัวเลขจริงของบริษัท พบกับหุ้น mirror บางตัวที่ Finnomena เก็บผิด
      พลาด แนะนำอย่าอ้างอิงตัวเลขช่องที่มีเครื่องหมายนี้
    </div>` : '';

  // Sankey คำนวณจาก TTM 4 ไตรมาสล่าสุดใน d.quarters เสมอ ไม่ผูกกับ toggle รายไตรมาส/รายปี
  // (_finMergedPeriod) — วางบนสุดของแท็บตามที่ผู้ใช้ขอ
  const sankeyHtml = (() => { try { return _finSankeyCardHtml(qs, d.is_financial_sector, d.sym, _finMergedIsDr, d.currency); } catch (e) { return ''; } })();

  document.getElementById('fin-result').innerHTML = `
    ${sankeyHtml}
    <div class="card" style="padding:14px 16px">
      <div style="font-size:13px;font-weight:700;margin-bottom:2px">${_escHtml(d.sym)} ${d.name && d.name !== d.sym ? `— ${_escHtml(d.name)}` : ''}</div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:10px">งบผสานทุกแหล่ง (หน่วย: พัน${_finCurWord(d.currency)}) — P&L: Finnomena+Yahoo+SET.or.th (SET แม่นสุด ทับก่อนเสมอ) · งบดุล/กระแสเงินสดรายไตรมาส: Finnomena+Yahoo (SET.or.th ไม่มีรายไตรมาสจริงของ 2 งบนี้)${_finTab === 'set' ? ' · รายปี: สินทรัพย์รวม/ส่วนผู้ถือหุ้น/CFO/CFI/CFF ของหุ้นไทยใช้ตัวเลขทางการจาก SET company-highlight ทับผลรวม Finnomena+Yahoo' : ''} · เลื่อนซ้ายเพื่อดูปีเก่ากว่า</div>
      ${keyRatiosHtml}
      ${periodToggle}
      ${chartHtml}
      ${seasonalityHtml}
      ${qcmpHtml}
      ${heatmapHtml}
      ${extraChartsHtml}
      ${tableHtml}
      ${bsWarnCaveat}
    </div>`;
  _qplScrollToLatest(scrollId);
  // ห่อการวาดกราฟทั้งหมด — throw ที่นี่จะ propagate กลับไป catch ของ loadFinMergedReport แล้วเขียน
  // ทับรายงานที่ประกอบเสร็จแล้ว (หรือทำ toggle ช่วง/โหมดเงียบๆ ไม่ทำงาน) ทั้งที่ตัวรายงานยังดีอยู่
  try {
    if (isQMode && qs.length) _drawQplYoyChart(qs, 'qpl-yoy-chart');
    else if (!isQMode && ys.length) _drawQplYoyChartAnnual(ys, 'qpl-yoy-chart');
    _drawFinExtraCharts(isQMode ? qs : ys, _finMergedPeriod);
  } catch (e) { /* กราฟเท่านั้น ไม่ให้พังทั้งรายงาน */ }
  if (isQMode && qs.length) { try { _drawQuarterCompareCharts(qs); } catch (e) { /* กราฟเสริมเท่านั้น */ } }
}

// งาน #5 Dividend History — มุมมอง "💵 ปันผล" ในหน้างบการเงิน (ใช้ endpoint แยก
// /api/dividends ไม่ใช่ financials-full — ดู PLAN_stock_study_suite.txt งาน #5)
async function loadDividendsView(sym, market, hint, refresh) {
  const seq = _finViewSeq;
  hint.textContent = 'กำลังโหลด...';
  document.getElementById('fin-result').innerHTML = '<div class="empty" style="padding:24px">กำลังดึงประวัติปันผล...</div>';
  try {
    const qs = refresh ? '?refresh=1' : '';
    const r = await _fetchTimeout(`/api/dividends/${market}/${encodeURIComponent(sym)}${qs}`, 25000,
      'หมดเวลารอข้อมูล (เกิน 25 วิ) — ข้อมูลปันผลหุ้นนี้เก่าเกิน 30 วัน กำลังลองดึงสดจาก Yahoo แต่ช้าเกินไป ลองใหม่อีกครั้ง');
    const d = await r.json();
    if (seq !== _finViewSeq) return;   // เปลี่ยนหุ้น/มุมมองไปแล้วระหว่างรอโหลด — ห้ามทับ view + _divEventsLastArgs
    if (d.error) throw new Error(d.error);
    hint.innerHTML = (d.stale ? '⚠ ข้อมูลอาจเก่ากว่า 30 วัน · ' : '') +
      (d.synced_at ? `sync ล่าสุด: ${_escHtml(d.synced_at)}` : '');
    _renderDividendsView(d, sym, market, hint);
  } catch (e) {
    if (seq !== _finViewSeq) return;
    hint.textContent = '';
    document.getElementById('fin-result').innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ ${_escHtml(e.message)}</div>`;
  }
}

let _divEventsSort = null;   // { key, dir } — null = default (ล่าสุดก่อน, reverse chronological)
let _divEventsLastArgs = null;
function divEventsSortBy(key) {
  if (_divEventsSort && _divEventsSort.key === key) _divEventsSort.dir *= -1;
  else _divEventsSort = { key, dir: key === 'ex_date' ? -1 : 1 };
  if (_divEventsLastArgs) _renderDividendsView(..._divEventsLastArgs);
}
function _divEventsSortArrow(key) {
  if (!_divEventsSort || _divEventsSort.key !== key) return '';
  return _divEventsSort.dir === 1 ? ' ▼' : ' ▲';
}

function _renderDividendsView(d, sym, market, hint) {
  _divEventsLastArgs = [d, sym, market, hint];
  const years = d.years || [];
  const maxDps = Math.max(0.0001, ...years.map(y => y.dps));
  const tile = (label, val, suffix, tip) => `
    <div title="${tip || ''}" style="flex:1;min-width:110px;background:var(--bg2);border:1px solid var(--border);border-radius:8px;padding:10px 12px${tip ? ';cursor:help' : ''}">
      <div style="font-size:11px;color:var(--text2)">${label}</div>
      <div style="font-size:17px;font-weight:600;margin-top:2px">${val == null ? '—' : val + (suffix || '')}</div>
    </div>`;
  const summary = `
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">
      ${tile('จ่ายต่อเนื่อง', d.streak_paid_years, ' ปี', 'จำนวนปีติดต่อกันล่าสุดที่มีการจ่ายเงินปันผล (ไม่ขาดปีไหนเลย)')}
      ${tile('เพิ่ม/คงที่ต่อเนื่อง', d.streak_nondecreasing_years, ' ปี', 'จำนวนปีติดต่อกันที่ DPS ต่อปีไม่ลดลง (เพิ่มขึ้นหรือเท่าเดิม)')}
      ${tile('CAGR 5 ปี', d.cagr_5y_pct, '%', 'อัตราการเติบโตของ DPS เฉลี่ยต่อปี ย้อนหลัง 5 ปี')}
      ${tile('CAGR 10 ปี', d.cagr_10y_pct, '%', 'อัตราการเติบโตของ DPS เฉลี่ยต่อปี ย้อนหลัง 10 ปี')}
      ${tile('YoY ล่าสุด', d.yoy_growth_pct, '%', 'DPS ปีล่าสุดเทียบปีก่อนหน้า')}
      ${tile('ความถี่/ปี', d.events_per_year, ' ครั้ง', 'จำนวนครั้งที่จ่ายเงินปันผลโดยเฉลี่ยต่อปี (เช่น 4 = จ่ายรายไตรมาส)')}
      ${tile('Payout Ratio', d.payout_ratio_pct, '%', 'DPS ปีล่าสุด ÷ EPS งวดล่าสุด — ยิ่งต่ำยิ่งเหลือกำไรสะสมมาก, >100% = จ่ายเกินกำไรที่หาได้')}
    </div>`;

  const bars = years.map(y => {
    const h = Math.max(2, Math.round(y.dps / maxDps * 100));
    const color = y.complete ? 'var(--blue)' : 'var(--text2)';
    const yieldTxt = y.yield_pct != null ? `yield ${y.yield_pct}%` : '';
    return `<div style="flex:1;min-width:14px;display:flex;flex-direction:column;align-items:center;gap:4px" title="${_escHtml(y.year)}: ${_escHtml(y.dps)} บาท/หุ้น ${yieldTxt}${y.complete ? '' : ' (ยังไม่ครบปี)'}">
      <div style="width:100%;height:120px;display:flex;align-items:flex-end">
        <div style="width:100%;height:${h}%;background:${color};border-radius:3px 3px 0 0"></div>
      </div>
      <div style="font-size:10px;color:var(--text2);writing-mode:vertical-rl;transform:rotate(180deg)">${_escHtml(y.year)}</div>
    </div>`;
  }).join('');

  const yieldOf = e => { const yy = years.find(y => y.year === parseInt(e.ex_date.slice(0, 4))); return (yy && yy.yield_pct != null) ? yy.yield_pct : null; };
  let eventsList = (d.events || []).slice();
  if (_divEventsSort) {
    const key = _divEventsSort.key, dir = _divEventsSort.dir;
    eventsList.sort((a, b) => {
      if (key === 'ex_date') return dir === 1 ? (b.ex_date||'').localeCompare(a.ex_date||'') : (a.ex_date||'').localeCompare(b.ex_date||'');
      if (key === 'dps') return dir === 1 ? b.dps - a.dps : a.dps - b.dps;
      const va = yieldOf(a) ?? -Infinity, vb = yieldOf(b) ?? -Infinity;
      return dir === 1 ? vb - va : va - vb;
    });
  } else {
    eventsList.reverse();   // default: ล่าสุดก่อน
  }
  const eventsRows = eventsList.map(e => {
    const yv = yieldOf(e);
    return `<tr><td style="padding:4px 10px">${_escHtml(e.ex_date)}</td><td style="padding:4px 10px;text-align:right">${_escHtml(e.dps)}</td>
      <td style="padding:4px 10px;text-align:right;color:var(--text2)">${yv != null ? yv + '%' : '—'}</td></tr>`;
  }).join('');

  document.getElementById('fin-result').innerHTML = `
    <div class="card" style="padding:16px 18px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <h3 style="margin:0">💵 ประวัติปันผล ${_escHtml(sym)}</h3>
        <button class="filter-btn" style="font-size:12px" onclick="loadDividendsView('${_escJsAttr(sym)}','${_escJsAttr(market)}',document.getElementById('${_escJsAttr(hint.id)}'),true)">🔄 ดึงข้อมูลปันผลใหม่</button>
      </div>
      ${summary}
      <div style="display:flex;align-items:flex-end;gap:3px;overflow-x:auto;padding-bottom:4px;margin-bottom:16px">${bars}</div>
      <div style="max-height:320px;overflow-y:auto;border:1px solid var(--border);border-radius:8px">
        <table style="width:100%;border-collapse:collapse;font-size:12.5px">
          <thead style="position:sticky;top:0;background:var(--bg2)">
            <tr><th style="text-align:left;padding:6px 10px;cursor:pointer" onclick="divEventsSortBy('ex_date')">Ex-date${_divEventsSortArrow('ex_date')}</th><th style="text-align:right;padding:6px 10px;cursor:pointer" onclick="divEventsSortBy('dps')">DPS${_divEventsSortArrow('dps')}</th><th style="text-align:right;padding:6px 10px;cursor:pointer" onclick="divEventsSortBy('yield')">Yield ปีนั้น${_divEventsSortArrow('yield')}</th></tr>
          </thead>
          <tbody>${eventsRows}</tbody>
        </table>
      </div>
      <div style="font-size:11px;color:var(--text2);margin-top:10px">
        ปันผลปรับตาม stock split แล้ว (yfinance) · Payout Ratio = DPS ปีล่าสุด ÷ EPS งวดล่าสุด
        (${_escHtml(d.eps_latest_date || '—')}) จากงบ Yahoo — ไม่มีค่าถ้าขาดทุนหรือไม่มีข้อมูล EPS ·
        yield รายปีรองรับ TH/US/HK/JP (DR ยังไม่รองรับ — ไม่มี local price store ให้ underlying)
      </div>
    </div>`;
}

// งาน #4 Calendar — เฟส A: เฉพาะหุ้นใน Watchlist (ดู PLAN_stock_study_suite.txt งาน #4 —
// "อย่า fetch ทั้ง universe ตั้งแต่แรก จะโดน rate limit")
let _calRangeDays = 7;
let _calDirection = 'future';    // 'future' | 'past' — งาน "ดูย้อนหลัง" (ดู _calRenderList)
let _calView = 'list';           // 'list' | 'grid'
let _calMonthCursor = new Date(new Date().getFullYear(), new Date().getMonth(), 1);

function _calSetRange(days, btn) {
  _calRangeDays = days;
  document.querySelectorAll('#cal-range-7,#cal-range-30,#cal-range-all').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _calRenderFromCache();
}

// สลับดู "อนาคต" (default เดิม) กับ "ย้อนหลัง" — ย้อนหลังใช้ช่วงวันเดียวกับปุ่ม 7/30/ทั้งหมด แต่
// นับถอยจากวันนี้ไปข้างหลังแทน ใช้ได้เฉพาะมุมมอง "รายการ" (_calRenderList) เท่านั้น — มุมมอง
// "ปฏิทินเดือน" (grid) มีปุ่ม ◀/▶/วันนี้ เลื่อนดูเดือนย้อนหลังเองอยู่แล้ว เลยซ่อนแถวปุ่มนี้ไป
// ตอนอยู่ grid view (ดู _calSetView) ไม่ต้องพึ่ง _calDirection เลย ต้องมีข้อมูลย้อนหลังพอให้เห็น
// จริง ดู backend _CALENDAR_LOOKBACK_DAYS ที่ sync ให้ครอบคลุมช่วงย้อนหลังที่เลือกได้
function _calSetDirection(dir, btn) {
  _calDirection = dir;
  document.querySelectorAll('#cal-dir-future,#cal-dir-past').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _calRenderFromCache();
}

// ซิงก์การแสดง/ซ่อนแถวตัวกรองทั้งหมดตาม _calScope + _calView ปัจจุบัน — เรียกจากทั้ง
// _calSetView และ _calSetScope กันตรรกะ visibility กระจายซ้ำ (เดิม _calSetScope ตั้ง
// direction/range เป็น '' โดยไม่สน _calView ทำให้ grid view โชว์แถวที่ควรซ่อน และไม่เคย
// ซ่อน cal-month-nav ตอนเข้า scope ipo → ปุ่ม ◀▶ ค้างทับตาราง IPO)
function _calSyncFilterRows() {
  const ipo = _calScope === 'ipo';
  const grid = _calView === 'grid';
  const set = (id, show) => { const el = document.getElementById(id); if (el) el.style.display = show ? 'flex' : 'none'; };
  const viewRow = document.getElementById('cal-view-list') && document.getElementById('cal-view-list').closest('.filter-row');
  if (viewRow) viewRow.style.display = ipo ? 'none' : 'flex';
  set('cal-direction-row', !ipo && !grid);
  set('cal-range-row', !ipo && !grid);
  set('cal-month-nav', !ipo && grid);
  const marketRow = document.getElementById('cal-scope-market-row');
  if (marketRow) marketRow.style.display = (!ipo && _calScope === 'market') ? 'flex' : 'none';
  const refreshBtn = document.getElementById('cal-refresh-btn');
  if (refreshBtn) refreshBtn.style.display = _calScope === 'watchlist' ? '' : 'none';
}

function _calSetView(view, btn) {
  _calView = view;
  document.querySelectorAll('#cal-view-list,#cal-view-grid').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _calSyncFilterRows();
  _calRenderFromCache();
}

function _calMonthNav(delta, toToday) {
  _calMonthCursor = toToday
    ? new Date(new Date().getFullYear(), new Date().getMonth(), 1)
    : new Date(_calMonthCursor.getFullYear(), _calMonthCursor.getMonth() + delta, 1);
  _calRenderFromCache();
}

let _calCache = [];   // flat: [{symbol(display), market, type, date, confidence, source, detail}]
let _calFetchToken = 0;   // กัน request เก่า (สลับ scope เร็วๆ ก่อนของเดิม resolve) เขียนทับ _calCache ใหม่กว่า
let _calCacheKey = null;   // scope+market(+watchlist) ที่ _calCache ถือข้อมูลอยู่ — กันดึงซ้ำทุกครั้งที่เปิดหน้า

// ตัวกรองขอบเขต — เฟส A เดิมล็อกตายตัวที่ watchlist เท่านั้น ตอนนี้เพิ่มเลือกได้ 3 แบบ (ดู
// PLAN_stock_study_suite.txt งาน #4 ช่วง "Filter: watchlist-only (default ON) / ทั้งหมดที่มี
// ข้อมูล / ตลาด") — 'all'/'market' อ่านจาก local cache ล้วนๆ ผ่าน /api/calendar-events-all
// ไม่ fetch สดจาก yfinance/SET เลย กันโดน rate limit ตามที่แผนเตือนไว้ ("อย่า fetch ทั้ง
// universe ตั้งแต่แรก") ดังนั้นปุ่ม "ดึงข้อมูลใหม่" ใช้ได้เฉพาะ scope watchlist
let _calScope = 'watchlist';   // 'watchlist' | 'all' | 'market'
let _calScopeMarket = 'TH';

function _calSetScope(scope, btn) {
  _calScope = scope;
  document.querySelectorAll('#cal-scope-watchlist,#cal-scope-all,#cal-scope-market,#cal-scope-ipo').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _calSyncFilterRows();
  loadCalendarPage();
}

function _calSetScopeMarket(mkt, btn) {
  _calScopeMarket = mkt;
  document.querySelectorAll('#cal-scope-market-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  loadCalendarPage();
}

// prefix เดียวกับ watchlist ทั้งระบบ: ไม่มี prefix = TH, DR:/US:/HK: = ตลาดนั้น
// (ดู renderWatchlist ใน dashboard.js) — DR ส่ง market='DR' ไป backend (resolve_yf_ticker
// เช็ค DR universe ก่อนเสมอไม่ว่า market ที่ส่งมาคืออะไร ตราบใดที่ไม่ใช่ TH/SET — ดู
// sources/dr_descriptions.py) ได้แค่ earnings จาก yfinance (ไม่มี SET corporate-action
// เพราะ DR ไม่ใช่หุ้นไทยจริง — fetch_calendar_events ข้าม SET ให้เองเมื่อ market != TH/SET)
function _calResolveWatchlist() {
  const out = [];
  watchlist.forEach(sym => {
    // เช็ค prefix ว่างเปล่า ("DR:" ไม่มีรหัสตามหลัง — ไม่ควรเกิดจาก UI ปกติแต่กันไว้กันยิง
    // /api/calendar-events/DR/ ด้วย symbol ว่าง) ข้ามทิ้งเงียบๆ แทนที่จะนับเป็น fail ที่แจ้งผู้ใช้
    if (sym.startsWith('DR:')) { const s = sym.slice(3); if (s) out.push({ symbol: s, market: 'DR', display: 'DR:' + s }); }
    else if (sym.startsWith('US:')) { const s = sym.slice(3); if (s) out.push({ symbol: s, market: 'US', display: s }); }
    else if (sym.startsWith('HK:')) { const s = sym.slice(3); if (s) out.push({ symbol: s, market: 'HK', display: s }); }
    else if (sym.startsWith('JP:')) { const s = sym.slice(3); if (s) out.push({ symbol: s, market: 'JP', display: s }); }
    else if (sym) out.push({ symbol: sym, market: 'TH', display: sym });
  });
  return { list: out };
}

// display แบบเดียวกับ _calResolveWatchlist แต่ใช้กับ event ที่มาจาก /api/calendar-events-all
// (ทั้ง universe local ไม่ใช่แค่ watchlist) เพื่อให้ป้ายตลาดในตารางเหมือนกันทุก scope
function _calDisplayFor(market, symbol) {
  return market === 'DR' ? 'DR:' + symbol : symbol;
}

// สต๊อกเดียวกันอาจถูก sync ปฏิทินไว้ 2 ทาง: ผ่านหน้า DR (market='DR', symbol=รหัส DR เช่น
// "APPL") และผ่าน Tearsheet/หุ้น US-HK ตรงๆ ที่ resolve underlying แล้ว (market='US'/'HK',
// symbol=ticker จริงเช่น "AAPL") — earnings date ออกมาเป็นแถวซ้ำ 2 แถวได้ (ในสโคป "ทั้งหมด"/
// "ตามตลาด" หรือ Watchlist ถ้ามีทั้ง DR: และ US:/HK: ของหุ้นเดียวกันอยู่) ต้อง map รหัส DR เป็น
// underlying ก่อนเทียบซ้ำ โดยใช้ _drData ที่โหลดไว้แล้ว (ถ้ายังไม่เคยโหลดในเซสชันนี้ก็ข้ามการ
// map ไป — ไม่ crash แค่ dedupe ไม่ครบ ดีกว่าบังคับโหลด /api/dr ก้อนใหญ่แค่เพื่อ dedupe)
// ถ้าซ้ำจริง เก็บแถวที่ไม่ใช่ DR ไว้ (market จริงของ underlying อ่านง่ายกว่ารหัส DR)
function _calDedupeEvents(events) {
  const drMap = Object.fromEntries((_drData || []).map(s => [s.sym, s]));
  const canonical = e => {
    if (e.market !== 'DR') return `${e.market}:${e.symbol}`;
    const d = drMap[e.symbol];
    return d && d.region && d.yf ? `${d.region}:${d.yf.toUpperCase()}` : `DR:${e.symbol}`;
  };
  const seen = new Map();
  for (const e of events) {
    const key = `${canonical(e)}|${e.type}|${e.date}`;
    const prev = seen.get(key);
    if (!prev || (prev.market === 'DR' && e.market !== 'DR')) seen.set(key, e);
  }
  return [...seen.values()];
}

function _calCurrentCacheKey() {
  if (_calScope === 'watchlist') return 'watchlist:' + watchlist.join(',');
  if (_calScope === 'market') return 'market:' + _calScopeMarket;
  return _calScope;   // 'all'
}

async function loadCalendarPage(refresh) {
  const box = document.getElementById('cal-result');
  const note = document.getElementById('cal-fetch-note');
  if (note) note.textContent = '';

  // กัน request เก่าเขียนทับใหม่กว่า — สลับ scope เร็วๆ ก่อนของเดิม resolve (watchlist ยิง
  // Promise.all รวมหลายหุ้น มักช้ากว่า scope อื่น) — bump ก่อน early-return ของ scope 'ipo'
  // ด้วย ไม่งั้น watchlist fetch ที่ค้างอยู่ resolve ทีหลังแล้ว render ทับตาราง IPO
  const token = ++_calFetchToken;

  if (_calScope === 'ipo') { _calLoadIPO(token); return; }

  // เปิดหน้าเดิมซ้ำ (scope/ตลาด/watchlist ไม่เปลี่ยน) — render จาก cache เดิมเลย ไม่ยิงซ้ำ
  const cacheKey = _calCurrentCacheKey();
  if (!refresh && _calCacheKey === cacheKey && _calCache.length) { _calRenderFromCache(); return; }

  if (_calScope === 'watchlist') {
    const { list } = _calResolveWatchlist();
    if (list.length === 0) {
      box.innerHTML = `<div class="empty" style="padding:24px">Watchlist ว่าง — ไปหน้า Watchlist เพื่อเพิ่มหุ้นก่อน หรือสลับตัวกรองด้านบนเป็น "ทั้งหมดที่มีข้อมูล"</div>`;
      _calCache = [];
      return;
    }
    box.innerHTML = `<div class="empty" style="padding:24px">กำลังดึงปฏิทิน ${list.length} หุ้น...</div>`;
    const qs = refresh ? '?refresh=1' : '';
    // ยิงพร้อมกันทุกตัวใน watchlist — ถ้าตัวไหน timeout/error (โดยเฉพาะตอน refresh=1 ที่บังคับ
    // ดึงสดใหม่ทุกตัวพร้อมกัน หนัก/ช้ากว่าปกติ) จะหลุดเงียบๆ ถ้าไม่นับไว้ — แจ้งจำนวนที่พลาดให้
    // ผู้ใช้รู้ว่าปฏิทินที่เห็นอาจไม่ครบ ไม่ใช่แปลว่าหุ้นนั้นไม่มี event (พบจากรีวิวโค้ด 2026-08-02)
    let failCount = 0;
    const results = await Promise.all(list.map(async it => {
      try {
        const r = await _fetchTimeout(`/api/calendar-events/${it.market}/${encodeURIComponent(it.symbol)}${qs}`, 15000);
        const d = await r.json();
        // HTTP 200 แต่ backend ดึงสดจาก yfinance/SET ไม่สำเร็จ (เช่นโดน rate-limit) — d.fetch_error
        // มีค่า, events ที่ได้อาจว่างหรือเป็นชุดเก่า ต้องนับเป็น fail ด้วย ไม่ใช่แค่ตอน throw
        if (d && d.fetch_error) failCount++;
        return (d.events || []).map(e => ({ ...e, symbol: it.symbol, market: it.market }));
      } catch (e) { failCount++; return []; }
    }));
    if (token !== _calFetchToken) return;   // มี request ใหม่กว่าแซงไปแล้ว ทิ้งผลลัพธ์นี้
    const deduped = _calDedupeEvents(results.flat());
    _calCache = deduped.map(e => ({ ...e, symbol: _calDisplayFor(e.market, e.symbol) }));
    if (note && failCount) note.textContent = `⚠ ดึง/รีเฟรชไม่สำเร็จ ${failCount}/${list.length} ตัว (timeout/error/แหล่งข้อมูลล่ม) — ปฏิทินที่เห็นอาจไม่ครบหรือไม่ใช่ล่าสุด ลองกด "ดึงข้อมูลใหม่ทั้งหมด" อีกครั้ง`;
  } else {
    box.innerHTML = `<div class="empty" style="padding:24px">กำลังโหลดปฏิทิน...</div>`;
    const qs = _calScope === 'market' ? `?market=${_calScopeMarket}` : '';
    try {
      const r = await _fetchTimeout(`/api/calendar-events-all${qs}`, 25000);
      const d = await r.json();
      if (token !== _calFetchToken) return;
      const deduped = _calDedupeEvents(d.events || []);
      _calCache = deduped.map(e => ({ ...e, symbol: _calDisplayFor(e.market, e.symbol) }));
    } catch (e) {
      if (token !== _calFetchToken) return;
      _calCache = [];
    }
  }
  if (token !== _calFetchToken) return;
  _calCacheKey = cacheKey;
  _calRenderFromCache();
}

// หุ้น IPO กำลังจะเข้า/เพิ่งเข้าตลาด จาก SET.or.th (ดึงสด ไม่เก็บสะสม, ดู
// PLAN_set_api_expansion.txt งาน #6) — เติมช่องว่างฝั่งตรงข้ามของ delisted_log
// (ตัวออก) ระบบไม่มีตัวติดตาม "หุ้นเข้าใหม่" มาก่อนเลย — token จาก loadCalendarPage กัน
// watchlist/all fetch ที่ค้างอยู่ (หรือการสลับ scope กลับ) render ทับตาราง IPO นี้
async function _calLoadIPO(token) {
  const box = document.getElementById('cal-result');
  const note = document.getElementById('cal-fetch-note');
  if (note) note.textContent = '';
  box.innerHTML = '<div class="empty" style="padding:24px">กำลังโหลด...</div>';
  try {
    const r = await _fetchTimeout('/api/ipo-list', 25000);
    const d = await r.json();
    if (token != null && token !== _calFetchToken) return;
    if (!d.ok) throw new Error(d.error || 'โหลดไม่สำเร็จ');
    const up = d.upcoming || [], rec = d.recently || [];

    const upHtml = up.length ? `
      <div class="card" style="padding:16px;margin-bottom:12px">
        <div style="font-size:13px;font-weight:700;margin-bottom:10px">🆕 กำลังจะเข้าตลาด (${up.length} บริษัท)</div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:600px">
          <thead><tr><th>Symbol</th><th style="text-align:left">ชื่อ</th><th>ตลาด</th><th>อุตสาหกรรม</th><th>ราคา IPO</th><th>สถานะ</th></tr></thead>
          <tbody>${up.map(x => `<tr>
            <td><strong>${x.symbol || '—'}</strong></td>
            <td style="font-size:11px;max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${(x.business_description || '').replace(/"/g,'&quot;').replace(/</g,'&lt;')}">${(x.name_th || x.name_en || '').replace(/</g,'&lt;')}</td>
            <td style="font-size:11px;color:var(--text2)">${x.market || '—'}</td>
            <td style="font-size:11px;color:var(--text2)">${x.industry_name || '—'}</td>
            <td style="text-align:right">${x.ipo_price != null ? x.ipo_price : (x.ipo_price_desc || '—')}</td>
            <td style="font-size:11px;color:var(--text2)">${x.status || '—'}</td>
          </tr>`).join('')}</tbody>
        </table></div>
      </div>` : '<div class="empty" style="padding:16px;margin-bottom:12px">ไม่มีหุ้นกำลังเสนอขาย IPO ตอนนี้</div>';

    const recHtml = rec.length ? `
      <div class="card" style="padding:16px">
        <div style="font-size:13px;font-weight:700;margin-bottom:10px">📈 เพิ่งเข้าตลาด (${rec.length} บริษัท)
          <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:270px">
            <strong>ราคา IPO vs ราคาปัจจุบัน</strong><br>
            เขียว = เทรดเหนือราคาจอง · แดง = ต่ำกว่าจอง (break ราคาจอง)<hr>
            <span style="color:var(--text2)">⚠ หุ้น IPO ยังไม่มีในฐานราคา/งบของ dashboard จนกว่าจะรัน Full Update รอบถัดไป — เมนูอื่น (Screener/Tearsheet ฯลฯ) จะยังหาหุ้นพวกนี้ไม่เจอ</span>
          </div></span>
        </div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:560px">
          <thead><tr><th>Symbol</th><th style="text-align:left">ชื่อ</th><th>วันเทรดวันแรก</th><th>ราคา IPO</th><th>ราคาล่าสุด</th><th>%เปลี่ยน</th></tr></thead>
          <tbody>${rec.map(x => {
            const clr = (x.percent_change ?? 0) >= 0 ? 'var(--green)' : 'var(--red)';
            return `<tr>
              <td><strong>${x.symbol || '—'}</strong></td>
              <td style="font-size:11px;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${(x.name || '').replace(/</g,'&lt;')}</td>
              <td style="font-size:11px;color:var(--text2)">${x.first_trade_date || '—'}</td>
              <td style="text-align:right">${x.ipo_price != null ? x.ipo_price.toFixed(2) : '—'}</td>
              <td style="text-align:right;font-weight:600">${x.last != null ? x.last.toFixed(2) : '—'}</td>
              <td style="text-align:right;font-weight:600;color:${clr}">${x.percent_change != null ? (x.percent_change >= 0 ? '+' : '') + x.percent_change.toFixed(1) + '%' : '—'}</td>
            </tr>`;
          }).join('')}</tbody>
        </table></div>
      </div>` : '<div class="empty" style="padding:16px">ไม่มีข้อมูลหุ้นที่เพิ่งเข้าตลาด</div>';

    box.innerHTML = upHtml + recHtml;
    if (note) note.textContent = `ข้อมูล ณ ${d.as_of_date || '—'} · ดึงสดจาก SET.or.th ทุกครั้งที่เปิด (ไม่เก็บสะสม)`;
  } catch (e) {
    if (token != null && token !== _calFetchToken) return;
    box.innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">⚠ โหลดไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  }
}

function _calScopeEmptyLabel() {
  if (_calScope === 'watchlist') return 'สำหรับหุ้นใน Watchlist';
  if (_calScope === 'market') return `สำหรับตลาด ${_calScopeMarket}`;
  return '(ทั้งหมดที่มีข้อมูลในเครื่อง)';
}

const _CAL_TYPE_BADGE = { earnings: '📊 งบ', xd: '💵 XD', pay: '💰 จ่ายปันผล',
  xm: '🗳️ ประชุมผู้ถือหุ้น', xb: '📜 สิทธิจองซื้อ (XB)', xb_pay: '💳 ชำระค่าจองซื้อ' };
// backend ปล่อยแค่ 'confirmed' (SET.or.th corporate action) กับ 'estimated' (yfinance earnings)
// เท่านั้น — ไม่มี 'guessed' (fallback `|| e.confidence` รองรับค่าอื่นที่ไม่รู้จักอยู่แล้ว)
const _CAL_CONF_LABEL = { confirmed: 'ยืนยันแล้ว', estimated: 'ประมาณการ' };
const _CAL_CONF_COLOR = { confirmed: 'var(--green)', estimated: 'var(--blue)' };
// ลิงก์ไปดูงบจริงไม่ใช่ scrape/parse เอง เพราะ SET.or.th มี WAF (Incapsula) กับ API รายชื่อข่าว
// ต้องใช้ token ที่ดึงอัตโนมัติไม่ได้ (ต้อง login flow ผ่านเบราว์เซอร์จริง) — ปล่อยให้ผู้ใช้กด
// ลิงก์ไปดูเองในเบราว์เซอร์ตัวเองง่ายกว่ามาก ต้องมีข้อมูลย้อนหลังพอ (ดู _CALENDAR_LOOKBACK_DAYS
// ฝั่ง app.py ที่ sync ให้ครอบคลุม) ถึงจะเห็น event ประกาศงบที่ผ่านมาแล้วในโหมด "⏪ ย้อนหลัง"
//
// ลิงก์ไปหน้าข่าว "ผลประกอบการ" ของหุ้นตัวนั้นบน SET.or.th (ให้ผู้ใช้กดเข้าไปดู F45 +
  // คำอธิบายและวิเคราะห์ของฝ่ายจัดการ เอง) — โชว์เฉพาะหุ้นไทย (market TH) และเฉพาะ event
  // ประเภท earnings ที่วันที่ผ่านมาแล้ว (ถือว่า "น่าจะประกาศแล้ว")
function _calSourceLink(e) {
  if (e.type !== 'earnings' || e.market !== 'TH') return null;
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const dt = new Date(e.date + 'T00:00:00');
  if (isNaN(dt.getTime())) return null;   // e.date พังฟอร์แมต — กัน .toISOString() ด้านล่าง throw RangeError
  if (dt >= today) return null;
  // ต้องส่ง fromDate/toDate เอง ไม่งั้นหน้า SET จะ default เป็นช่วงสั้นๆ (~1 เดือนล่าสุดจากวันนี้)
  // ซึ่งอาจไม่ครอบคลุมวันที่ประกาศจริง เพราะวันที่ในปฏิทินเราเป็นแค่ 'ประมาณการ' จาก yfinance
  // (อาจเร็ว/ช้ากว่าวันจริงหลักสัปดาห์) — เผื่อ ±ให้กว้างพอ: 30 วันก่อนวันประมาณการ ถึงวันนี้
  // (หรือ 45 วันหลังวันประมาณการถ้ายังไม่ถึงวันนี้)
  const fmt = d => d.toISOString().slice(0, 10);
  const fromDate = fmt(new Date(dt.getTime() - 30 * 86400000));
  const toDateCandidate = new Date(dt.getTime() + 45 * 86400000);
  const toDate = fmt(toDateCandidate < today ? toDateCandidate : today);
  return `https://www.set.or.th/th/market/news-and-alert/news?source=company&symbol=${encodeURIComponent(e.symbol)}&securityType=S&type=3&fromDate=${fromDate}&toDate=${toDate}`;
}

// เปิดหน้าข่าว "ผลประกอบการ" ของ SET.or.th แบบไม่กรองหุ้น (ทั้งตลาด) ย้อนหลัง 90 วันล่าสุด — ทาง
// เลือกที่เบากว่าการ sync yfinance ทั้ง ~800 หุ้นไทยเข้า Watchlist (ซึ่งมีช่องโหว่ backfill ไม่ได้
// ถ้า sync ครั้งแรกมาช้ากว่าวันประกาศจริง ดู fetch_earnings_calendar) ปล่อยให้ผู้ใช้ไปดูฟีดข่าว
// จริงของ SET เองตรงๆ ไม่ต้องพึ่งข้อมูลใน local DB เลย
function _calOpenMarketWideNews() {
  const fmt = d => d.toISOString().slice(0, 10);
  const today = new Date();
  const from = new Date(today.getTime() - 90 * 86400000);
  const url = `https://www.set.or.th/th/market/news-and-alert/news?source=company&securityType=S&type=3&fromDate=${fmt(from)}&toDate=${fmt(today)}`;
  window.open(url, '_blank', 'noopener');
}

// เรียง _calCache (flat อยู่แล้ว ไม่ว่า scope ไหน) ตามวันที่ ไม่กรองวันที่ (ตัวกรองช่วง/เดือน
// ทำแยกที่ _calRenderList/_calRenderGrid) — ใช้ร่วมกันทั้ง 2 มุมมอง กันเขียน merge logic ซ้ำ
function _calFlatEvents() {
  return [..._calCache].sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
}

function _calRenderFromCache() {
  const box = document.getElementById('cal-result');
  if (!box) return;
  if (_calView === 'grid') { _calRenderGrid(); return; }
  _calRenderList();
}

let _calListSort = null;   // { key, dir } — null = default (วันที่ ascending)
function calListSortBy(key) {
  if (_calListSort && _calListSort.key === key) _calListSort.dir *= -1;
  else _calListSort = { key, dir: key === 'date' ? 1 : -1 };
  _calRenderList();
}
function _calListSortArrow(key) {
  if (!_calListSort || _calListSort.key !== key) return '';
  return _calListSort.dir === 1 ? ' ▼' : ' ▲';
}

function _calRenderList() {
  const box = document.getElementById('cal-result');
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const isPast = _calDirection === 'past';
  // ย้อนหลัง: [today - range, today] ทุกประเภท event (ไม่ใช่แค่ earnings) — ต้องมีข้อมูลจริงถึง
  // ย้อนไปได้ ดู _CALENDAR_LOOKBACK_DAYS ฝั่ง app.py ที่ sync ให้ครอบคลุมช่วงนี้ อนาคต: เหมือนเดิม
  const windowStart = isPast ? new Date(today.getTime() - _calRangeDays * 86400000) : today;
  const windowEnd = isPast ? today : new Date(today.getTime() + _calRangeDays * 86400000);

  let flat = _calFlatEvents().filter(e => {
    const dt = new Date(e.date + 'T00:00:00');
    return dt >= windowStart && dt <= windowEnd;
  });

  if (flat.length === 0) {
    const label = isPast ? `ย้อนหลัง ${_calRangeDays} วัน` : `${_calRangeDays} วันข้างหน้า`;
    box.innerHTML = `<div class="empty" style="padding:24px">ไม่มีเหตุการณ์ใน${label} ${_calScopeEmptyLabel()}</div>`;
    return;
  }
  if (_calListSort) {
    const { key, dir } = _calListSort;
    const getters = {
      date: e => e.date || '',
      symbol: e => e.symbol || '',
      type: e => _CAL_TYPE_BADGE[e.type] || e.type || '',
      detail: e => e.detail || '',
      confidence: e => _CAL_CONF_LABEL[e.confidence] || e.confidence || '',
    };
    const get = getters[key] || getters.date;
    flat = flat.slice().sort((a, b) => {
      const va = get(a), vb = get(b);
      return dir === 1 ? String(va).localeCompare(String(vb)) : String(vb).localeCompare(String(va));
    });
  }
  // e.detail/e.symbol/e.market มาจากข้อความสด (agenda จาก SET.or.th / EPS จาก yfinance / market
  // = path segment ที่ถูก persist ดิบๆ) — ไม่ใช่ literal ที่เราคุมเอง ต้อง escape ก่อนแทรก HTML
  // ใช้ _escHtml ตัวกลาง (escape ครบ 5 อักขระ) แทน escaper บางส่วนที่เคย copy ซ้ำ 3 จุด
  const esc = _escHtml;
  const rows = flat.map(e => {
    const dt = new Date(e.date + 'T00:00:00');
    const dLeft = Math.round((dt - today) / 86400000);
    const dLeftLabel = dLeft >= 0 ? `(อีก ${dLeft} วัน)` : `(${-dLeft} วันที่แล้ว)`;
    const link = _calSourceLink(e);
    const linkCell = link
      ? `<button onclick="window.open('${link}','_blank','noopener')" title="เปิดหน้าข่าวผลประกอบการของ ${esc(e.symbol)} บน SET.or.th" style="font-size:11px;padding:3px 8px;border-radius:5px;border:1px solid var(--border);background:var(--bg2);color:var(--blue);cursor:pointer;white-space:nowrap">🔗 ดูงบจริง</button>`
      : '';
    return `<tr>
      <td style="padding:8px 10px;white-space:nowrap">${e.date} <span style="color:var(--text2);font-size:11px">${dLeftLabel}</span></td>
      <td style="padding:8px 10px"><b>${esc(e.symbol)}</b> <span style="color:var(--text2);font-size:11px">${esc(e.market)}</span></td>
      <td style="padding:8px 10px">${_CAL_TYPE_BADGE[e.type] || e.type}</td>
      <td style="padding:8px 10px;color:var(--text2)">${esc(e.detail)}</td>
      <td style="padding:8px 10px;text-align:right"><span style="color:${_CAL_CONF_COLOR[e.confidence] || 'var(--text2)'};font-size:11px">${_CAL_CONF_LABEL[e.confidence] || e.confidence}</span></td>
      <td style="padding:8px 10px;text-align:right">${linkCell}</td>
    </tr>`;
  }).join('');

  box.innerHTML = `
    <div class="card" id="cal-list-card" style="padding:0;overflow-x:hidden">
      <table style="width:100%;border-collapse:collapse;font-size:13px">
        <thead style="background:var(--bg2)">
          <tr><th style="text-align:left;padding:8px 10px;cursor:pointer" onclick="calListSortBy('date')">วันที่${_calListSortArrow('date')}</th><th style="text-align:left;padding:8px 10px;cursor:pointer" onclick="calListSortBy('symbol')">หุ้น${_calListSortArrow('symbol')}</th>
            <th style="text-align:left;padding:8px 10px;cursor:pointer" onclick="calListSortBy('type')">ประเภท${_calListSortArrow('type')}</th><th style="text-align:left;padding:8px 10px;cursor:pointer" onclick="calListSortBy('detail')">รายละเอียด${_calListSortArrow('detail')}</th>
            <th style="text-align:right;padding:8px 10px;cursor:pointer" onclick="calListSortBy('confidence')">ความน่าเชื่อถือ${_calListSortArrow('confidence')}</th>
            <th style="text-align:right;padding:8px 10px">ต้นทาง</th></tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div style="font-size:11px;color:var(--text2);margin-top:10px">
      📊 งบ = ประมาณการจาก yfinance (อาจเลื่อน/คลาดเคลื่อน) · 💵 XD/💰 จ่ายปันผล/🗳️ ประชุมผู้ถือหุ้น/📜 สิทธิจองซื้อ = ประกาศทางการจาก SET.or.th (หุ้นไทยเท่านั้น) ·
      หุ้น DR/US/HK เห็นเฉพาะวันประกาศงบประมาณการ ·
      🔗 ดูงบจริง = เปิดหน้าข่าวผลประกอบการของหุ้นนั้นบน SET.or.th (F45 + คำอธิบายและวิเคราะห์ของฝ่ายจัดการ) ให้ไปดูเอกสารต้นทางเอง
    </div>`;
}

const _CAL_TYPE_ICON = { earnings: '📊', xd: '💵', pay: '💰', xm: '🗳️', xb: '📜', xb_pay: '💳' };
const _CAL_WEEKDAY_TH = ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'];
const _CAL_MONTH_TH = ['มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
  'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'];

// มุมมองปฏิทินรายเดือน (grid) — ใช้ _calCache เดิมที่โหลดไว้แล้วจาก loadCalendarPage เสมอ
// ไม่ fetch เพิ่ม (ย้อนหลังได้ถึง _CALENDAR_LOOKBACK_DAYS วันฝั่ง app.py ~1 ปี ไม่ได้ว่างเปล่า
// เสมอเหมือนที่เคยเขียนไว้ก่อนเพิ่ม lookback ย้อนหลัง — กด ◀ ย้อนดูเดือนก่อนได้จริง)
function _calRenderGrid() {
  const box = document.getElementById('cal-result');
  const year = _calMonthCursor.getFullYear(), month = _calMonthCursor.getMonth();
  const label = document.getElementById('cal-month-label');
  if (label) label.textContent = `${_CAL_MONTH_TH[month]} ${year + 543}`;

  const today = new Date(); today.setHours(0, 0, 0, 0);
  const byDate = {};
  _calFlatEvents().forEach(e => { (byDate[e.date] = byDate[e.date] || []).push(e); });

  const head = _CAL_WEEKDAY_TH.map(w => `<th style="padding:6px;font-size:11px;color:var(--text2)">${w}</th>`).join('');

  box.innerHTML = `
    <div class="card" style="padding:12px;overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;table-layout:fixed">
        <thead><tr>${head}</tr></thead>
        <tbody>${_calGridRows(year, month, byDate, today)}</tbody>
      </table>
    </div>
    <div style="font-size:11px;color:var(--text2);margin-top:10px">
      📊 งบ = ประมาณการจาก yfinance (อาจเลื่อน/คลาดเคลื่อน) · 💵 XD/💰 จ่ายปันผล/🗳️ ประชุมผู้ถือหุ้น/📜 สิทธิจองซื้อ = ประกาศทางการจาก SET.or.th (หุ้นไทยเท่านั้น) ·
      กด ◀ ย้อนดูเดือนก่อนได้ (มีข้อมูลย้อนหลังได้ถึง ~1 ปีถ้าเคย sync ไว้) · ชิป 📊 งบ ที่วันในอดีตกดเปิดลิงก์ไปดูงบจริงที่ SET.or.th ได้เลย (หุ้นไทย)
    </div>`;
}

function _calGridRows(year, month, byDate, today) {
  const firstOfMonth = new Date(year, month, 1);
  const startWeekday = firstOfMonth.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const totalCells = Math.ceil((startWeekday + daysInMonth) / 7) * 7;

  let html = '';
  for (let row = 0; row < totalCells / 7; row++) {
    html += '<tr>';
    for (let col = 0; col < 7; col++) {
      const i = row * 7 + col;
      const dayNum = i - startWeekday + 1;
      if (dayNum < 1 || dayNum > daysInMonth) { html += `<td style="background:var(--bg2);opacity:.3;border:1px solid var(--border)"></td>`; continue; }
      const cellDate = new Date(year, month, dayNum);
      const iso = `${year}-${String(month + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
      const isToday = cellDate.getTime() === today.getTime();
      const dayEvents = byDate[iso] || [];
      // title/symbol แทรกใน attribute + content — ใช้ _escHtml ตัวกลาง (escape ครบ 5 อักขระ
      // รวม ' และ >) แทน escaper บางส่วนที่เคย copy ซ้ำ กัน e.detail/e.symbol (ข้อความสดจาก
      // SET.or.th/yfinance ไม่ใช่ literal ที่เราคุมเอง) หลุด
      const escAttr = _escHtml;
      const chips = dayEvents.slice(0, 3).map(e => {
        const link = _calSourceLink(e);
        const title = escAttr(`${e.symbol} ${e.detail || ''}${link ? ' — คลิกดูงบจริงที่ SET.or.th' : ''}`);
        const style = "font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:1px 3px;margin-top:2px;border-radius:3px;background:var(--bg2)" + (link ? ";cursor:pointer;text-decoration:underline" : "");
        const onclick = link ? ` onclick="window.open('${link}','_blank','noopener')"` : '';
        // escape e.symbol เหมือน title ข้างบน — เดิม render ดิบ ต่างจาก _calRenderList ที่ escape
        // ไว้แล้ว (watchlist entry ที่มี prefix DR:/US:/HK: ไม่ผ่านการเช็ค whitelist ชื่อหุ้นจริง
        // ดู addToWatchlist ทำให้มี HTML แทรกเข้ามาได้ในทางทฤษฎี)
        return `<div title="${title}" style="${style}"${onclick}>${_CAL_TYPE_ICON[e.type] || '•'} ${escAttr(e.symbol)}</div>`;
      }).join('');
      const more = dayEvents.length > 3 ? `<div style="font-size:9px;color:var(--text2)">+${dayEvents.length - 3} อื่นๆ</div>` : '';
      html += `<td style="vertical-align:top;padding:4px;height:76px;max-width:120px;border:1px solid var(--border);${isToday ? 'background:color-mix(in srgb, var(--blue) 12%, transparent)' : ''}">
        <div style="font-size:11px;font-weight:${isToday ? '700' : '400'};color:${isToday ? 'var(--blue)' : 'var(--text2)'}">${dayNum}</div>
        ${chips}${more}
      </td>`;
    }
    html += '</tr>';
  }
  return html;
}

function _finFmt(v) {
  if (v == null || isNaN(v)) return '—';
  const abs = Math.abs(v), sign = v < 0 ? '-' : '';
  if (abs >= 1e12) return sign + (abs/1e12).toFixed(2) + 'T';
  if (abs >= 1e9)  return sign + (abs/1e9).toFixed(2) + 'B';
  if (abs >= 1e6)  return sign + (abs/1e6).toFixed(2) + 'M';
  if (abs >= 1e3)  return sign + (abs/1e3).toFixed(2) + 'K';
  return sign + abs.toFixed(2);
}

function _finPct(v) {
  if (v == null || isNaN(v)) return '—';
  return (v >= 0 ? '+' : '') + v.toFixed(2) + '%';
}

// รายการที่ "ยิ่งน้อยยิ่งดี" — เพิ่มขึ้นควรเป็นแดง ไม่ใช่เขียว (ตรงข้ามกับรายได้/กำไรที่ยิ่งมากยิ่งดี)
const FIN_INVERT_KEYS = new Set([
  'Total Expenses', 'Operating Expense', 'Cost Of Revenue', 'Reconciled Cost Of Revenue',
  'Selling General And Administration', 'Selling And Marketing Expense',
  'General And Administrative Expense', 'Other Gand A', 'Other Operating Expenses',
  'Interest Expense', 'Interest Expense Non Operating', 'Tax Provision',
  'Total Debt', 'Net Debt', 'Current Debt', 'Current Debt And Capital Lease Obligation',
  'Long Term Debt', 'Long Term Debt And Capital Lease Obligation',
  'Current Liabilities', 'Total Liabilities Net Minority Interest',
  'Total Non Current Liabilities Net Minority Interest',
  'Debt To Equity', 'SGA To Revenue', 'Cash Cycle',
  'totalExpense', 'totalLiability', 'deRatio',
]);

function _finColCls(v, prev, key) {
  if (v == null || prev == null) return '';
  if (v === prev) return '';
  const up = v > prev;
  const isGood = FIN_INVERT_KEYS.has(key) ? !up : up;
  return isGood ? 'green' : 'red';
}

// ============================================================
// แนวโน้มระยะยาว (งาน 3) — SVG chart จากงบไตรมาส Finnomena 16 ปี + PE/PBV band
// ============================================================
function _finSeries(row) {
  if (!row) return [];
  return Object.entries(row).map(([d, v]) => ({ d, v })).filter(o => o.v != null && !isNaN(o.v))
    .sort((a, b) => a.d < b.d ? -1 : 1);
}

// area + เส้น (แกน x = เวลา) ปรับขนาดตาม container ด้วย viewBox
function _svgArea(series, opt) {
  const W = 600, H = opt.height || 90, pad = 4;
  if (series.length < 2) return '';
  const xs = series.map((_, i) => pad + i * (W - 2 * pad) / (series.length - 1));
  const vals = series.map(o => o.v);
  let lo = Math.min(...vals, 0), hi = Math.max(...vals, 0);
  if (hi === lo) hi = lo + 1;
  const y = v => H - pad - (v - lo) / (hi - lo) * (H - 2 * pad);
  const line = series.map((o, i) => `${i ? 'L' : 'M'}${xs[i].toFixed(1)},${y(o.v).toFixed(1)}`).join('');
  const zeroY = y(0).toFixed(1);
  const area = `M${xs[0].toFixed(1)},${zeroY} ${line.replace('M', 'L')} L${xs[xs.length - 1].toFixed(1)},${zeroY} Z`;
  const c = opt.color || '#3fb950';
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:${H}px;display:block">
    <path d="${area}" fill="${c}" opacity="0.14"/>
    <path d="${line}" fill="none" stroke="${c}" stroke-width="1.6"/>
  </svg>`;
}

// แท่งกำไร (บวกเขียว/ลบแดง)
function _svgBars(series, opt) {
  const W = 600, H = opt.height || 80, pad = 4;
  if (!series.length) return '';
  const vals = series.map(o => o.v);
  let lo = Math.min(...vals, 0), hi = Math.max(...vals, 0);
  if (hi === lo) hi = lo + 1;
  const y = v => H - pad - (v - lo) / (hi - lo) * (H - 2 * pad);
  const bw = (W - 2 * pad) / series.length * 0.72;
  const z = y(0);
  const bars = series.map((o, i) => {
    const x = pad + i * (W - 2 * pad) / series.length;
    const yy = y(o.v), top = Math.min(yy, z), h = Math.abs(yy - z);
    // opt.qoq: สีเทียบกับงวดก่อนหน้า (โตขึ้น=เขียว ลดลง=แดง) — ใช้กับค่าที่บวกเสมอ เช่นรายได้
    // ปกติ: สีตามเครื่องหมาย (บวก=เขียว ลบ=แดง)
    // opt.invert: รายการ "ยิ่งน้อยยิ่งดี" (ค่าใช้จ่าย/หนี้สิน) — เพิ่มขึ้น = แดง (ตรงข้ามปกติ)
    let up = opt.qoq ? (i === 0 || o.v >= series[i - 1].v) : (o.v >= 0);
    if (opt.invert) up = !up;
    const col = up ? (opt.pos || '#3fb950') : (opt.neg || '#f85149');
    return `<rect x="${x.toFixed(1)}" y="${top.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(h, 0.5).toFixed(1)}" fill="${col}"/>`;
  }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:${H}px;display:block">
    <line x1="0" y1="${z.toFixed(1)}" x2="${W}" y2="${z.toFixed(1)}" stroke="var(--border)" stroke-width="0.8"/>${bars}</svg>`;
}

// PE ที่คำนวณเอง = Close ÷ TTM EPS (ผลรวม Basic EPS ย้อนหลัง 4 ไตรมาสจริง) แทนที่จะ
// เชื่อ field "PE" สำเร็จรูปของ Finnomena — ดู bands ใน _finTrendSectionImpl สำหรับ
// เหตุผลเต็ม (เทียบกับเว็บอื่นแล้วตรงกันเกือบเป๊ะเมื่อคำนวณแบบนี้)
function _ttmPeSeries(epsRow, closeRow) {
  const epsItems = _finSeries(epsRow);
  if (epsItems.length < 4) return [];
  const closeMap = {};
  Object.entries(closeRow || {}).forEach(([d, v]) => { if (v != null) closeMap[d] = v; });
  const out = [];
  for (let i = 3; i < epsItems.length; i++) {
    const ttmEps = epsItems[i - 3].v + epsItems[i - 2].v + epsItems[i - 1].v + epsItems[i].v;
    const dt = epsItems[i].d;
    const close = closeMap[dt];
    if (close != null && ttmEps > 0) out.push({ d: dt, v: close / ttmEps });
  }
  return out;
}

// TTM EPS ล่าสุด (4 ไตรมาสท้ายสุดที่มีข้อมูลจริง) — ใช้คำนวณ PE สดตอน live-patch
// (จุด "ปัจจุบัน" ต้องใช้ TTM ล่าสุดเสมอ ไม่ใช่รายปีที่ปิดไปแล้ว ไม่งั้นจะเก่าเกินไป)
function _ttmEpsLast(epsRow) {
  const epsItems = _finSeries(epsRow);
  if (epsItems.length < 4) return null;
  const last4 = epsItems.slice(-4);
  // กันไตรมาสขาดหาย (gap) ทำให้ TTM รวมข้ามช่วงเวลาที่ไม่ติดกันจริง — เช็คระยะห่างระหว่าง
  // ไตรมาสติดกันต้องไม่เกิน ~105 วัน เหมือนเกณฑ์ฝั่ง backend (ดู _calc_ttm ใน app.py)
  for (let i = 1; i < last4.length; i++) {
    const gapDays = (new Date(last4[i].d) - new Date(last4[i - 1].d)) / 86400000;
    if (gapDays > 105) return null;
  }
  const sum = last4.reduce((a, o) => a + o.v, 0);
  return sum > 0 ? sum : null;
}

// PE รายปี = Close ณ งวดสุดท้ายของปี ÷ EPS รวมทั้งปี (เฉพาะปีที่ครบ 4 ไตรมาสจริง) —
// ทดสอบเทียบกับเว็บอ้างอิงแล้วแม่นกว่า TTM รายไตรมาสแบบ rolling (_ttmPeSeries) เพราะ
// ตัดความผันผวนของแต่ละไตรมาสเดี่ยวๆ ออกไป เหลือแค่ภาพรวมทั้งปี — ใช้เป็นฐานข้อมูล
// ย้อนหลังสำหรับ band แทน ส่วนจุด "ปัจจุบัน" ยังใช้ TTM ล่าสุดอยู่ (ดู _ttmEpsLast)
function _annualPeSeries(epsRow, closeRow) {
  const epsItems = _finSeries(epsRow);
  if (epsItems.length < 4) return [];
  const closeMap = {};
  Object.entries(closeRow || {}).forEach(([d, v]) => { if (v != null) closeMap[d] = v; });
  const byYear = {};
  epsItems.forEach(o => { (byYear[o.d.slice(0, 4)] = byYear[o.d.slice(0, 4)] || []).push(o); });
  const out = [];
  Object.keys(byYear).sort().forEach(y => {
    const items = byYear[y];
    if (items.length !== 4) return;   // ปีที่ยังไม่ครบ 4 ไตรมาส (เช่นปีปัจจุบัน) ข้าม
    const annualEps = items.reduce((a, o) => a + o.v, 0);
    const lastDate = items[items.length - 1].d;   // งวดสุดท้ายของปีนั้น (ปกติ Q4)
    const close = closeMap[lastDate];
    // ปีที่กำไรรวมทั้งปีเกือบเป็นศูนย์ (ใกล้ breakeven) ทำให้ Close÷EPS ระเบิดเป็นเลขไร้
    // ความหมาย (เจอ PE หลักล้าน-พันล้านจริง กับ AMZN บางปี) — ตัด PE ที่เกินเพดานสมเหตุสมผล
    // ทิ้งไปเลย (ไม่ใช่แค่ winsorize เพราะ winsorize ใช้ percentile ซึ่งไม่ช่วยตอน n น้อย
    // p1/p99 อาจตกที่ตัวสุดขั้วเองพอดี) ดีกว่าเก็บค่าที่ไม่มีความหมายไว้ลากค่าเฉลี่ย/sigma พัง
    const PE_SANE_MAX = 1000;
    if (close != null && annualEps > 0 && close / annualEps <= PE_SANE_MAX) {
      out.push({ d: lastDate, v: close / annualEps });
    }
  });
  return out;
}

// TTM Revenue (ผลรวม Total Revenue 4 ไตรมาสท้ายสุด) — ใช้คำนวณ PS ด้านล่าง
function _ttmRevenueSeries(revRow) {
  const items = _finSeries(revRow);
  if (items.length < 4) return [];
  const out = [];
  for (let i = 3; i < items.length; i++) {
    // กันไตรมาสขาดหาย (gap) ทำให้ TTM รวมข้ามช่วงเวลาที่ไม่ติดกันจริง — เกณฑ์เดียวกับ
    // _ttmEpsLast (ระยะห่างไตรมาสติดกันต้องไม่เกิน ~105 วัน) ไม่งั้น PS band/กราฟเส้นเพี้ยน
    let contiguous = true;
    for (let k = i - 2; k <= i; k++) {
      if ((new Date(items[k].d) - new Date(items[k - 1].d)) / 86400000 > 105) { contiguous = false; break; }
    }
    if (!contiguous) continue;
    const ttm = items[i - 3].v + items[i - 2].v + items[i - 1].v + items[i].v;
    if (ttm > 0) out.push({ d: items[i].d, v: ttm });
  }
  return out;
}

// PS (Price to Sales) = Market Cap ÷ TTM Revenue — Finnomena ไม่มี field PS ตรงๆ คำนวณเอง
// เหมือนแนวคิด compute_ps() ฝั่ง backend (financials_store.py) ผูกกับวันที่ Market Cap
// (ถี่กว่า/สดกว่าวันปิดงบ) หา TTM revenue ล่าสุดที่ ≤ วันนั้น ข้ามถ้าห่างเกิน ~400 วัน
// (รายได้หยุดอัพเดทนานเกินปี — เอามาหารราคาสดจะหลอกตา)
function _psSeries(mcRow, revRow) {
  const mc = _finSeries(mcRow);
  const ttmRev = _ttmRevenueSeries(revRow);
  if (!mc.length || !ttmRev.length) return [];
  const out = [];
  let j = -1;
  for (const o of mc) {
    while (j + 1 < ttmRev.length && ttmRev[j + 1].d <= o.d) j++;
    if (j < 0 || o.v == null || o.v <= 0) continue;
    const gapDays = (new Date(o.d) - new Date(ttmRev[j].d)) / 86400000;
    if (gapDays > 400) continue;
    out.push({ d: o.d, v: o.v / ttmRev[j].v });
  }
  return out;
}

// แถบ valuation band: min | p25 | median | p75 | max + จุดค่าปัจจุบัน
// winsorize: หนีบค่าที่หลุดขอบเขตปกติเข้ามา (ไม่ทิ้งจุดข้อมูล แค่ลดความสุดโต่ง) — เก็บไว้
// เป็นเซฟตี้เน็ตกันจุดโดดเดี่ยวที่เพี้ยนจริงๆ ลาก mean/std/min/max ของทั้งชุดข้อมูลเพี้ยนไป
// ด้วยถ้าไม่ตัดก่อน (เหมือนหลักการ _sane() ที่ใช้ใน factor_snapshot.py ฝั่ง backend)
//
// สถิติตลาด (SET/mai รายเดือน 600+ จุด) ยังใช้ p1/p99 index-based เดิม — ที่ n ขนาดนั้น
// round(0.01×(n-1)) ตัดได้จริง ตรงกับตัวอย่างที่อธิบายไว้ใน _PE_BAND_NOTE_HTML ด้านล่าง
// (PE mai 937x -> ~429x) แต่ข้อมูลรายหุ้น (8-67 จุดต่อ PE/PBV/PS) ใช้สูตรเดียวกันไม่ได้ —
// round(0.01×(n-1)) ปัดลง index 0/ท้ายเสมอที่ n<~51 (ไม่ตัดอะไรเลย) ทำให้ปีที่ EPS/รายได้
// ใกล้ศูนย์พอดี (near-breakeven) พุ่งเป็นร้อยเท่าแบบไม่ถูกกรอง ลาก avg/std เพี้ยนหนัก
// (พิสูจน์จริง: PE เฉลี่ยหลุดไป 64x ทั้งที่ median 12x) — ที่ n<51 จึงสลับไปใช้ Tukey fence
// (median±3×IQR) แทน ซึ่ง Q1/Q3 (floor-based ไม่ใช่ round) นิยามได้มั่นคงไม่ว่า n จะเล็กแค่ไหน
function _winsorize(vals) {
  if (vals.length < 8) return vals;
  const sorted = [...vals].sort((a, b) => a - b);
  const n = sorted.length;
  if (n >= 51) {
    const q = p => sorted[Math.min(n - 1, Math.max(0, Math.round(p * (n - 1))))];
    const lo = q(0.01), hi = q(0.99);
    return vals.map(v => Math.min(hi, Math.max(lo, v)));
  }
  const q = p => sorted[Math.min(n - 1, Math.max(0, Math.floor(p * (n - 1))))];
  const q1 = q(0.25), q3 = q(0.75), iqr = q3 - q1;
  const lo = Math.max(sorted[0], q1 - 3 * iqr);
  const hi = Math.min(sorted[n - 1], q3 + 3 * iqr);
  return vals.map(v => Math.min(hi, Math.max(lo, v)));
}

// คำอธิบาย p25/p75 แบบเข้าใจง่าย — ใช้ร่วมกันทั้งแถบรายหุ้น (หน้างบการเงิน) และ
// แถบตลาดรวม (หน้า Valuation) เพราะเป็นแนวคิดเดียวกัน
const _PE_BAND_NOTE_HTML = `
  <b>p25 / p75 คืออะไร?</b><br><br>
  เอาค่า (เช่น PE) ทุกงวดย้อนหลังทั้งหมด มาเรียงจาก <b>ถูกสุด → แพงสุด</b> เป็นแถวเดียว
  แล้วแบ่งแถวนี้ออกเป็น 4 ส่วนเท่าๆ กัน<br><br>
  <b>p25</b> = จุดแบ่งช่วง 25% ถูกสุด — ถ้าค่าปัจจุบัน <b style="color:#3fb950">ต่ำกว่า p25</b>
  แปลว่านี่คือหนึ่งในช่วงเวลาที่ <b style="color:#3fb950">ถูกที่สุด 25%</b> ที่เคยเป็นมา (ไม่ใช่แค่รู้สึกว่าถูก)<br><br>
  <b>p75</b> = จุดแบ่งช่วง 25% แพงสุด — ถ้าค่าปัจจุบัน <b style="color:#f85149">สูงกว่า p75</b>
  แปลว่านี่คือหนึ่งในช่วงเวลาที่ <b style="color:#f85149">แพงที่สุด 25%</b> ที่เคยเป็นมา<br><br>
  ทำไมไม่ใช้แค่ "ค่าเฉลี่ย"? เพราะถ้ามีงวดไหนราคาพุ่งผิดปกติ ค่าเฉลี่ยจะถูกลากเพี้ยนไปด้วย
  แต่ p25/p75 สนใจแค่ "ตำแหน่ง" ในแถวเรียง ไม่ถูกกระทบง่ายๆ<hr>
  <b>ต่ำสุด / สูงสุด ที่โชว์ ≠ ค่าสุดขั้วจริงในประวัติศาสตร์</b><br><br>
  ก่อนคำนวณ ระบบตัดขอบค่าที่สุดโต่งผิดปกติออกก่อน (เรียกว่า winsorize) กันเดือน/ปี/ไตรมาสที่
  ข้อมูลผิดปกติสุดๆ (เช่น วิกฤตเศรษฐกิจ หรือช่วงกำไร/รายได้ใกล้ศูนย์พอดี) มาลากแถบทั้งเส้นให้
  ผิดสัดส่วนจนมองไม่เห็นความต่างของข้อมูลส่วนใหญ่ที่เหลือ<br><br>
  เช่น PE mai เคยพุ่งสูงสุดจริงถึง <b>937x</b> (ก.ค. 2546) แต่ตัดขอบ 1% ออกแล้ว "สูงสุด" ที่โชว์
  จะเหลือแค่ <b>~429x</b> — ไม่ได้ผิด แค่คนละความหมาย: ตัวที่โชว์คือ <b>"ขอบบนของ 99% ของเวลาทั้งหมด"</b>
  ไม่ใช่ตัวเลขสูงสุดที่เคยเกิดขึ้นจริงตัวเดียว (ข้อมูลตลาดรวมมีจุดข้อมูลเยอะพอให้ตัดแบบ
  percentile ได้ตรงๆ) ส่วนกราฟ <b>รายหุ้น</b> ที่มีข้อมูลแค่หลักสิบไตรมาส ใช้เกณฑ์ตัดขอบที่
  เหมาะกับชุดข้อมูลเล็ก (median ± ส่วนเบี่ยงเบนของควอร์ไทล์) แทน หลักการเดียวกันคือกันจุด
  โดดเดี่ยวที่ผิดปกติมาลากค่าเฉลี่ย/แกนกราฟให้เพี้ยน`;

function _svgBand(series, label, lowerIsCheap, idPrefix) {
  const vals = _winsorize(series.map(o => o.v).filter(v => v > 0)).sort((a, b) => a - b);
  if (vals.length < 8) return `<div style="font-size:12px;color:var(--text2)">${label}: ข้อมูลไม่พอ (${vals.length} งวด)</div>`;
  const q = p => vals[Math.min(vals.length - 1, Math.floor(p * (vals.length - 1)))];
  const lo = vals[0], hi = vals[vals.length - 1], med = q(0.5), p25 = q(0.25), p75 = q(0.75);
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  // งวดล่าสุดก็ต้อง winsorize ด้วยขอบเดียวกับ lo/hi ไม่งั้น "ปัจจุบัน" อาจโชว์เกิน
  // "สูงสุด" ที่ตัดขอบไปแล้ว (ขัดกับคำอธิบาย _PE_BAND_NOTE_HTML ด้านบน)
  const rawCur = series[series.length - 1].v;
  // ค่าปัจจุบัน ≤ 0 (เช่น PBV ติดลบจากส่วนของผู้ถือหุ้นติดลบ — NWR/TSR) ไม่มีความหมายเชิง
  // valuation — ห้ามหนีบเข้า lo แล้วโชว์เป็น "ถูกสุดที่เคยเป็นมา" (บริษัทใกล้ล้ม ไม่ใช่ของถูก)
  const curValid = rawCur > 0;
  const cur = curValid ? Math.min(hi, Math.max(lo, rawCur)) : rawCur;
  const pos = curValid ? Math.max(0, Math.min(100, (cur - lo) / (hi - lo || 1) * 100)) : 100;
  const meanPos = Math.max(0, Math.min(100, (mean - lo) / (hi - lo || 1) * 100));
  // สีจุด: ถูก=เขียว แพง=แดง (สำหรับ PE/PBV ที่ต่ำ=ถูก) — ค่าติดลบถือเป็นสัญญาณอันตราย (แดง)
  const cheap = curValid && (lowerIsCheap ? cur <= p25 : cur >= p75);
  const rich = !curValid || (lowerIsCheap ? cur >= p75 : cur <= p25);
  const col = cheap ? '#3fb950' : rich ? '#f85149' : '#d9932e';
  const f = v => (Math.round(v * 100) / 100);
  // idPrefix: ถ้าให้มา จะใส่ id ไว้ให้ _patchLiveBand แก้เป็นราคาสดจาก Yahoo ทีหลังได้
  // (ค่า "ปัจจุบัน" เดิมคืองวดสุดท้ายของ Finnomena ซึ่งอาจเป็นราคา ณ สิ้นไตรมาสก่อน ไม่ใช่วันนี้)
  const curId = idPrefix ? ` id="${idPrefix}-cur"` : '';
  const tickId = idPrefix ? ` id="${idPrefix}-tick"` : '';
  return `<div style="margin:6px 0"${idPrefix ? ` data-lo="${lo}" data-hi="${hi}" data-p25="${p25}" data-p75="${p75}" data-lower-cheap="${lowerIsCheap ? 1 : 0}"` : ''}>
    <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--text2)">
      <span><b style="color:var(--text)">${label}</b> ปัจจุบัน <b${curId} style="color:${col}">${curValid ? f(cur) : f(rawCur) + ' ⚠'}</b></span>
      <span>เฉลี่ย <span style="color:#58a6ff">${f(mean)}</span> · มัธยฐาน ${f(med)} · ต่ำสุด ${f(lo)} · สูงสุด ${f(hi)}</span>
    </div>
    <div style="position:relative;height:12px;margin-top:3px;border-radius:6px;background:linear-gradient(90deg,#3fb95055,#d9932e55,#f8514955)">
      <div style="position:absolute;left:${(p25 - lo) / (hi - lo || 1) * 100}%;top:0;bottom:0;width:1px;background:var(--text2)"></div>
      <div style="position:absolute;left:${(p75 - lo) / (hi - lo || 1) * 100}%;top:0;bottom:0;width:1px;background:var(--text2)"></div>
      <div style="position:absolute;left:${meanPos}%;top:-3px;bottom:-3px;width:0;border-left:1.5px dashed #58a6ff" title="ค่าเฉลี่ย ${f(mean)}"></div>
      <div${tickId} style="position:absolute;left:${pos}%;top:-2px;width:2px;height:16px;background:${col};box-shadow:0 0 3px ${col}"></div>
    </div>
  </div>`;
}

// แถวค่า mean±nσ ใต้แถบ _svgBand — คำนวณ mean/std เองจาก vals ดิบ (population std
// เหมือน calc_stats() ฝั่ง backend ที่ใช้กับ Valuation ตลาด) ใช้กับ PE/PBV รายหุ้น
// ที่ไม่มี server คำนวณ bands ไว้ล่วงหน้าแบบหน้า Valuation ตลาด
function _sigmaBandHtml(rawVals) {
  if (!rawVals || rawVals.length < 8) return '';
  const vals = _winsorize(rawVals);   // กัน mean/std บวมจากไตรมาสข้อมูลเพี้ยน (ดู _winsorize)
  const n = vals.length;
  const mean = vals.reduce((a, b) => a + b, 0) / n;
  const variance = vals.reduce((a, b) => a + (b - mean) * (b - mean), 0) / n;
  const std = Math.sqrt(variance);
  const f = v => Math.round(v * 100) / 100;
  // เรียงถูก(เขียว)→แพง(แดง) ซ้ายไปขวา ให้ตรงทิศทางแถบไล่สีของ _svgBand ด้านบน
  const items = [
    ['-3σ', mean - 3 * std, '#2f9e57', 'ถูกมากผิดปกติ'],
    ['-2σ', mean - 2 * std, '#3ab464', 'ถูกผิดปกติ'],
    ['-1σ', mean - std,     '#96c850', 'ถูกกว่าค่าเฉลี่ย'],
    ['+1σ', mean + std,     '#e0d060', 'แพงกว่าค่าเฉลี่ย'],
    ['+2σ', mean + 2 * std, '#dca032', 'แพงผิดปกติ'],
    ['+3σ', mean + 3 * std, '#dc503c', 'แพงมากผิดปกติ'],
  ];
  return `<div style="display:flex;flex-wrap:wrap;gap:6px 12px;font-size:10px;margin:2px 0 8px">
    ${items.map(([lbl, val, col, txt]) =>
      `<span style="color:${col}" title="${txt}"><b>${lbl}</b> ${f(val)} — ${txt}</span>`).join('')}
  </div>`;
}

// วิเคราะห์ฤดูกาล (seasonality) จากงบไตรมาสย้อนหลัง — seasonal index = ค่าไตรมาสนั้น
// หารด้วยค่าเฉลี่ยทั้งปี แล้วเฉลี่ยข้ามปี (>1 = ไฮซีซั่น, <1 = โลว์ซีซั่น)
// ใช้เฉพาะปีที่ครบ 4 ไตรมาส และต้องมี >=3 ปีถึงจะมีนัยยะ
function _finSeasonality(row) {
  if (!row) return null;
  const byYear = {};
  Object.entries(row).forEach(([dt, v]) => {
    if (v == null) return;
    // เดิม map เฉพาะเดือนปิดงวด 03/06/09/12 (ปีบัญชีตรงปฏิทิน) — หุ้น US ที่ปีบัญชีเลื่อน
    // (เช่น NVDA/MU ปิดงวด ม.ค./เม.ย./ก.ค./ต.ค.) จะไม่มี q เลยสักไตรมาส บล็อกฤดูกาลเลย
    // หายเงียบไปทั้งหมด ใช้ Math.ceil(เดือน/3) แทนครอบคลุมทุกเดือนปิดงวด
    const y = dt.slice(0, 4), q = Math.ceil(parseInt(dt.slice(5, 7), 10) / 3);
    if (q) (byYear[y] = byYear[y] || {})[q] = v;
  });
  const ratios = { 1: [], 2: [], 3: [], 4: [] };
  let years = 0;
  Object.values(byYear).forEach(qd => {
    if (Object.keys(qd).length !== 4) return;
    if ([1, 2, 3, 4].some(q => qd[q] <= 0)) return;   // ต้องบวกทุกไตรมาส กัน ratio ระเบิด
    const avg = (qd[1] + qd[2] + qd[3] + qd[4]) / 4;
    years++;
    [1, 2, 3, 4].forEach(q => ratios[q].push(qd[q] / avg));
  });
  if (years < 3) return null;
  const idx = {};
  [1, 2, 3, 4].forEach(q => idx[q] = _median(ratios[q]));   // median ทนปีเพี้ยน (ใช้ helper กลาง)
  let hi = 1, lo = 1;
  [2, 3, 4].forEach(q => { if (idx[q] > idx[hi]) hi = q; if (idx[q] < idx[lo]) lo = q; });
  const swing = (idx[hi] - idx[lo]) * 100;
  if (swing > 150) return null;   // ผิดปกติ — ไม่แสดง
  return { idx, hi, lo, swing, years };
}

// label: ชื่อรายการที่ใช้คำนวณ seasonality (ค่าเริ่มต้น 'รายได้' ให้ call site เดิมไม่ต้องแก้)
// — เพิ่ม param นี้เพื่อ reuse ฟังก์ชันเดียวกันกับกำไรสุทธิได้ (ดู _finKeyRatiosHtml/_renderFinMergedReport)
function _finSeasonalityBlock(rev, label = 'รายได้') {
  const s = _finSeasonality(rev);
  if (!s) return '';
  const weak = s.swing < 8;   // สวิงน้อย = แทบไม่มีฤดูกาล
  const bars = [1, 2, 3, 4].map(q => {
    const pct = s.idx[q] * 100;
    const h = Math.max(4, Math.min(80, (s.idx[q] / (s.idx[s.hi] || 1)) * 80));
    const col = weak ? '#58a6ff' : (q === s.hi ? '#3fb950' : q === s.lo ? '#e8a33d' : '#8b98a5');
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:2px;flex:1">
      <div style="font-size:10px;color:var(--text2)">${pct.toFixed(0)}%</div>
      <div style="width:60%;height:${h}px;background:${col};border-radius:2px 2px 0 0"></div>
      <div style="font-size:11px;font-weight:600;color:${q === s.hi && !weak ? '#3fb950' : q === s.lo && !weak ? '#e8a33d' : 'var(--text)'}">Q${q}</div>
    </div>`;
  }).join('');
  const summary = weak
    ? `<span style="color:var(--text2)">แทบไม่มีรูปแบบฤดูกาล (สวิงเพียง ${s.swing.toFixed(0)}%)</span>`
    : `ไฮซีซั่น <b style="color:#3fb950">ไตรมาส ${s.hi}</b> (${(s.idx[s.hi] * 100).toFixed(0)}%) · โลว์ซีซั่น <b style="color:#e8a33d">ไตรมาส ${s.lo}</b> (${(s.idx[s.lo] * 100).toFixed(0)}%) · สวิง ${s.swing.toFixed(0)}%`;
  return `<div style="margin-top:14px">
    <div style="font-size:11px;color:var(--accent);font-weight:600;margin-bottom:8px">📅 ฤดูกาล (Seasonality) — จาก${label}เฉลี่ย ${s.years} ปี</div>
    <div style="display:flex;align-items:flex-end;gap:8px;max-width:280px;height:126px;padding:2px 0">${bars}</div>
    <div style="font-size:11.5px;margin-top:2px">${summary}</div>
    <div style="font-size:10px;color:var(--text2);margin-top:2px">ดัชนี = ${label}ไตรมาสนั้น ÷ เฉลี่ยทั้งปี (100% = ปกติ) · Q1-Q4 = ไตรมาสตามปีบัญชี (บริษัทที่ปีบัญชีไม่ตรงปีปฏิทินจะเลื่อนจากเดือนจริง)</div>
  </div>`;
}

// แปลง d.quarters (โครง {year_ad,q,field,...} ของแท็บ "งบรวมทุกแหล่ง") เป็น {วันที่สิ้นงวด: ค่า}
// แบบเดียวกับ payload Yahoo/Finnomena ดิบ — ให้ reuse _finSeasonality/_finSeasonalityBlock เดิม
// ได้เลยโดยไม่ต้องเขียนใหม่ (เดือนสิ้นไตรมาส q*3 ทำให้ Math.ceil(เดือน/3) ข้างในคำนวณ q กลับมาตรงเป๊ะ)
function _finQuartersToDateMap(qs, field) {
  const out = {};
  (qs || []).forEach(c => {
    if (c[field] == null) return;
    out[`${c.year_ad}-${String(c.q * 3).padStart(2, '0')}-01`] = c[field];
  });
  return out;
}

// ชุดข้อมูล valuation ย้อนหลัง (PE/PBV/PS) จากงบไตรมาส — ใช้ทั้งแถบเกจ (_svgBand) และ
// กราฟเส้นย้อนหลังแบบเดียวกับหน้า Valuation ตลาด (ดู _drawFinTrendCharts ด้านล่าง)
// แยกออกมาจาก _finTrendSectionImpl เพื่อให้เรียกคำนวณซ้ำได้ตอน draw กราฟ (หลัง DOM
// มี canvas element แล้ว) โดยไม่ต้อง parse ทั้ง section ใหม่
const _finValSeriesCache = new WeakMap();   // memo ต่อ payload d — _finTrendSectionImpl กับ
                                            // _drawFinTrendCharts เรียกซ้ำด้วย d ก้อนเดียวกันทุก render
function _finValuationSeries(d) {
  if (_finValSeriesCache.has(d)) return _finValSeriesCache.get(d);
  const inc = d.income || {}, val = d.valuation || {};
  const pe = _annualPeSeries(inc['Basic EPS'], val['Close']);
  const pbv = _finSeries(val['PBV']);
  const ps = _psSeries(val['Market Cap'], inc['Total Revenue'] || inc['Operating Revenue']);
  const out = { pe, pbv, ps };
  _finValSeriesCache.set(d, out);
  return out;
}

// avg/std (population, หลัง winsorize กันค่าเพี้ยนสุดโต่งเหมือน _sigmaBandHtml) + p25/median/p75
// สำหรับกราฟเส้นย้อนหลัง — ต้องมี >=8 จุดถึงจะมีนัยยะ (เหมือนเกณฑ์ของ _svgBand)
function _seriesStats(series) {
  const raw = (series || []).map(o => o.v).filter(v => v > 0);
  if (raw.length < 8) return null;
  const vals = _winsorize(raw);
  const n = vals.length;
  const avg = vals.reduce((a, b) => a + b, 0) / n;
  const variance = vals.reduce((a, b) => a + (b - avg) * (b - avg), 0) / n;
  const std = Math.sqrt(variance);
  const sorted = [...vals].sort((a, b) => a - b);
  const q = p => sorted[Math.min(n - 1, Math.floor(p * (n - 1)))];
  return { avg, std, current: series[series.length - 1].v, thresholds: [q(0.25), q(0.5), q(0.75)] };
}

// หนีบค่าที่จะ "พล็อต" บนกราฟเส้นด้วย fence เดียวกับ _seriesStats/_svgBand (ไม่ใช่แค่ตอน
// คำนวณ avg/std) — ไม่งั้นแกน Y ยังต้องยืดไปหาจุดสุดขั้วดิบอยู่ดี (dataMax ที่ยังไม่ตัด) ทำให้
// เส้นค่าจริงส่วนใหญ่แบนติดขอบล่างเหมือนเดิม แม้ avg/std จะถูกต้องแล้วก็ตาม จุดที่ถูกหนีบ
// จะโชว์ค่าที่ถูกหนีบตอน hover ด้วย (ไม่ใช่ค่าจริงดิบ) — trade-off เดียวกับที่ _svgBand
// ทำกับจุด "ปัจจุบัน" อยู่แล้ว (_patchBandValue หนีบเข้า lo/hi เสมอ)
function _winsorizeSeriesForDisplay(series) {
  const positive = series.map(o => o.v).filter(v => v > 0);
  if (positive.length < 8) return series;
  const clipped = _winsorize(positive);
  let i = 0;
  return series.map(o => o.v > 0 ? { d: o.d, v: clipped[i++] } : o);
}

// คำเตือนเมื่อ Close/BVPS ของ Finnomena (ที่ใช้เป็นฐาน PE/PBV/PS band+กราฟเส้นทั้งหมด) ต่างจาก
// แหล่งอิสระอื่น (ราคาจริงใน {market}_prices.db, BVPS คำนวณเองจากงบ Yahoo) เกินเกณฑ์ หรือค้าง
// ไม่อัพเดทหลายไตรมาสติด — คำนวณไว้แล้วฝั่ง backend (financials_store.check_valuation_quality)
// แปะมาใน d.valuation_quality เฉพาะตอน source=finnomena_q (ดู /api/financials-full)
// เจอจริงกับหุ้นที่ equity ติดลบ/ใกล้ล้ม เช่น NWR/TSR — ราคาที่ Finnomena เก็บอาจต่างจากราคา
// เทรดจริงหลายเท่าตัวโดยไม่มีสัญญาณเตือนใดๆ ถ้าไม่เช็คแบบนี้
function _valuationQualityBanner(d) {
  const q = d.valuation_quality;
  if (!q || !q.warnings || !q.warnings.length) return '';
  const items = q.warnings.map(w => `<li style="margin:2px 0">${w.detail}</li>`).join('');
  return `<div style="margin:2px 0 8px;padding:7px 10px;border:1px solid #dca03255;background:#dca03214;color:#dca032;border-radius:6px;font-size:11.5px;line-height:1.5">
    ⚠ <b>ข้อมูลราคา/BVPS ของ Finnomena บางไตรมาสอาจไม่น่าเชื่อถือ</b> — ตรวจกับแหล่งอื่นแล้วต่างกันเกินเกณฑ์ปกติ ควรเทียบกับแหล่งอื่นก่อนใช้ตัดสินใจ:
    <ul style="margin:4px 0 0;padding-left:18px">${items}</ul>
  </div>`;
}

function _finLineChartBlock(title, canvasId) {
  return `<div style="margin-top:12px">
    <div style="font-size:11px;color:var(--text2);margin-bottom:2px">${title}</div>
    <canvas id="${canvasId}" style="width:100%;height:180px"></canvas>
  </div>`;
}

// วาดกราฟเส้น PE/PBV/PS ย้อนหลังรายหุ้น ด้วย engine เดียวกับกราฟ P/E ระดับตลาด
// (drawValChart/setupValHover — ดู loadValDailyBox/renderValuation) ต้องเรียกหลัง
// box.innerHTML ใส่ _finTrendSection ลง DOM แล้วเท่านั้น (ต้องมี <canvas> ให้เกาะ)
function _drawFinTrendCharts(d, idPrefix = '') {
  try {
    const { pe, pbv, ps } = _finValuationSeries(d);
    const draw = (series, canvasId, isPE) => {
      const canvas = document.getElementById(canvasId);
      const stats = _seriesStats(series);
      if (!canvas || !stats) return;
      const display = _winsorizeSeriesForDisplay(series);
      drawValChart(canvasId, display.map(o => o.d), display.map(o => o.v), stats.thresholds, stats);
      setupValHover(canvasId, stats.thresholds, stats.avg, isPE, stats.std);
    };
    draw(pe, idPrefix + 'pe-line', true);
    draw(pbv, idPrefix + 'pbv-line', false);
    draw(ps, idPrefix + 'ps-line', true);
  } catch (e) { /* กราฟเสริมเท่านั้น ห้ามพังหน้าหลัก */ }
}

function _finTrendSection(d, source, idPrefix = '') {
  try { return _finTrendSectionImpl(d, source, idPrefix); }
  catch (e) { return ''; }   // กันพลาด — กราฟเสริมเท่านั้น ห้ามทำให้ตารางงบพัง
}

// idPrefix: กันชน id ตอนเรียกซ้ำสองที่พร้อมกันในหน้าเดียว (หน้างบการเงินเต็ม vs popup
// กราฟหุ้น — ทั้งคู่อยู่ใน DOM พร้อมกันเสมอ แค่ซ่อน/โชว์สลับกัน) ไม่ใส่ = พฤติกรรมเดิม
function _finTrendSectionImpl(d, source, idPrefix = '') {
  if (source !== 'finnomena_q' && source !== 'yahoo_q') return '';
  const inc = d.income || {}, ratios = d.ratios || {}, val = d.valuation || {}, cf = d.cashflow || {};
  const rev = _finSeries(inc['Total Revenue'] || inc['Operating Revenue']);
  const ni  = _finSeries(inc['Net Income'] || inc['Net Income Common Stockholders']);
  if (rev.length < 8 && ni.length < 8) return '';   // ข้อมูลสั้นเกินไป ไม่ต้องโชว์กราฟ
  // net margin: ใช้ ratios ของ Finnomena ก่อน ไม่งั้นคำนวณ NI/Rev
  let margin = _finSeries(ratios['Net Margin']);
  if (!margin.length && rev.length && ni.length) {
    const rmap = Object.fromEntries(rev.map(o => [o.d, o.v]));
    margin = ni.filter(o => rmap[o.d] > 0).map(o => ({ d: o.d, v: o.v / rmap[o.d] * 100 }));
  }
  // แถวที่ 2: คุณภาพ (ROE) + เงินสดจริง (OCF) + ความเสี่ยง (D/E) — มีเฉพาะแหล่ง Finnomena
  const roe = _finSeries(ratios['ROE']);
  const ocf = _finSeries(cf['Operating Cash Flow']);
  const de  = _finSeries(ratios['Debt To Equity']);
  // PE (ฐานข้อมูลย้อนหลัง): คำนวณเอง = Close ÷ EPS รวมทั้งปี (รายปี ไม่ใช่ TTM
  // รายไตรมาส) แทนที่จะใช้ field "PE" ของ Finnomena ตรงๆ — พบว่างวดเก่าหลายตัว
  // (เช่น BDMS ก่อนกลางปี 2025) Finnomena ดูเหมือนคำนวณ PE จาก EPS ไตรมาสเดียวแทน
  // TTM ทำให้ PE พุ่งผิดปกติ (เคยเจอ 655x) ลองเทียบทั้งแบบ TTM รายไตรมาส (rolling)
  // กับรายปี (เฉพาะปีที่ปิดครบ 4 ไตรมาส) แล้วรายปีแม่นกว่า — ตรงกับเว็บอ้างอิงเกือบ
  // เป๊ะ เพราะตัดความผันผวนของไตรมาสเดี่ยวๆ ออกไป · PBV ไม่มีปัญหานี้ ใช้ field ของ
  // Finnomena ตรงๆ ได้ตามเดิม
  const { pe, pbv, ps } = _finValuationSeries(d);
  const span = rev.length ? `${rev[0].d.slice(0,7)} – ${rev[rev.length-1].d.slice(0,7)} (${rev.length} ไตรมาส)` : '';

  const chart = (title, svg, sub) => svg ? `
    <div style="flex:1;min-width:240px">
      <div style="font-size:11px;color:var(--text2);margin-bottom:2px">${title}${sub ? ` <span style="color:var(--text2)">${sub}</span>` : ''}</div>
      ${svg}
    </div>` : '';

  const bands = (pe.length >= 8 || pbv.length >= 8 || ps.length >= 8) ? `
    <div style="margin-top:10px">
      <div style="font-size:11px;color:var(--accent);font-weight:600;margin-bottom:2px">มูลค่าเทียบอดีตตัวเอง (PE/PBV/PS band)${_tipIconHtml(_PE_BAND_NOTE_HTML)} <span id="${idPrefix}fin-live-price" style="font-weight:400;color:var(--text2)"></span></div>
      ${_valuationQualityBanner(d)}
      ${pe.length ? _svgBand(pe, 'PE', true, idPrefix + 'peband') + _sigmaBandHtml(pe.map(o => o.v).filter(v => v > 0)) : ''}
      ${pbv.length ? _svgBand(pbv, 'PBV', true, idPrefix + 'pbvband') + _sigmaBandHtml(pbv.map(o => o.v).filter(v => v > 0)) : ''}
      ${ps.length ? _svgBand(ps, 'PS', true, idPrefix + 'psband') + _sigmaBandHtml(ps.map(o => o.v).filter(v => v > 0)) : ''}
      <div style="font-size:10px;color:var(--text2);margin-top:2px">เขียว = ถูกกว่าอดีต (≤ p25) · แดง = แพงกว่าอดีต (≥ p75) · ขีดทึบคือ p25/p75 · เส้นประฟ้าคือค่าเฉลี่ย · ฐานข้อมูลย้อนหลัง PE คำนวณจาก Close ÷ EPS รวมรายปีเอง (ไม่ใช้ field PE ของ Finnomena ตรงๆ — บางงวดเก่าคำนวณผิดจาก EPS ไตรมาสเดียว) · PS คำนวณจาก Market Cap ÷ TTM Revenue เอง (Finnomena ไม่มี field PS ตรงๆ) · "ปัจจุบัน" ใช้ TTM ล่าสุด × ราคาสดจาก Yahoo · PBV ใช้ field ของ Finnomena โดยตรง</div>
      ${pe.length >= 8 ? _finLineChartBlock('แนวโน้ม PE ย้อนหลัง (เทียบเฉลี่ย ± σ)', idPrefix + 'pe-line') : ''}
      ${pbv.length >= 8 ? _finLineChartBlock('แนวโน้ม PBV ย้อนหลัง (เทียบเฉลี่ย ± σ)', idPrefix + 'pbv-line') : ''}
      ${ps.length >= 8 ? _finLineChartBlock('แนวโน้ม PS ย้อนหลัง (เทียบเฉลี่ย ± σ)', idPrefix + 'ps-line') : ''}
    </div>` : '';

  return `<div class="card" style="margin-top:12px;background:var(--card2)">
    <div style="font-size:12px;font-weight:600;margin-bottom:2px">📈 แนวโน้มระยะยาว <span style="font-size:10px;color:var(--text2);font-weight:400">${span}</span></div>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:6px">
      ${chart('รายได้ (Total Revenue)', _svgBars(rev, { qoq: true }))}
      ${chart('กำไรสุทธิ (Net Income)', _svgBars(ni, {}))}
      ${chart('อัตรากำไรสุทธิ (Net Margin %)', _svgArea(margin, { color: '#3fb950', height: 90 }))}
      ${chart('ROE (%)', _svgArea(roe, { color: '#a371f7', height: 90 }))}
      ${chart('กระแสเงินสดดำเนินงาน (OCF)', _svgBars(ocf, {}))}
      ${chart('D/E (หนี้ต่อทุน · เท่า)', _svgArea(de, { color: '#e8a33d', height: 90 }))}
    </div>
    ${_finSeasonalityBlock(inc['Total Revenue'] || inc['Operating Revenue'])}
    ${bands}
  </div>`;
}

// ============================================================
// งบการเงินฉบับเต็ม (ทุก field) — tab Yahoo Finance / SET.or.th
// ============================================================
let _finFullShowAll = false;   // false = เฉพาะรายการหลัก, true = ทุก field
let _finViewMode = 'table';    // 'table' = ตารางตัวเลข, 'chart' = กราฟแนวโน้มรายบรรทัด

function _median(vals) {
  if (!vals.length) return null;
  const sorted = [...vals].sort((a, b) => a - b);
  const n = sorted.length, mid = Math.floor(n / 2);
  return n % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// context ของตาราง Ratios ที่ render อยู่ล่าสุด — เก็บไว้ให้ renderFinCustomAvg() คำนวณ
// เฉลี่ย/มัธยฐานตามช่วงปีที่ผู้ใช้กรอกเองได้ โดยไม่ต้อง fetch ข้อมูลใหม่
let _finRatiosCustomCtx = null;

function _finCustomAvgHtml() {
  const years = (_finRatiosCustomCtx.allColsFull || []).map(c => +c.slice(0, 4));
  if (!years.length) return '';   // ไม่มีคอลัมน์ปีเลย — Math.min/max(...[]) จะได้ Infinity/-Infinity
  const lo = Math.min(...years), hi = Math.max(...years);
  return `
  <div style="margin-top:10px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card2)">
    <div style="font-size:11px;color:var(--text2);margin-bottom:6px">🔎 คำนวณเฉลี่ย/มัธยฐานเฉพาะช่วงปีที่กรอกเอง (ข้อมูลมีปี ${lo}–${hi})</div>
    <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
      <input class="scr-input" type="number" id="fin-avg-from" placeholder="ปีเริ่ม" value="${lo}" style="width:90px" onkeydown="if(event.key==='Enter')renderFinCustomAvg()">
      <span style="color:var(--text2);font-size:12px">ถึง</span>
      <input class="scr-input" type="number" id="fin-avg-to" placeholder="ปีสิ้นสุด" value="${hi}" style="width:90px" onkeydown="if(event.key==='Enter')renderFinCustomAvg()">
      <button class="filter-btn" style="font-size:11px;padding:5px 10px" onclick="renderFinCustomAvg()">คำนวณ</button>
    </div>
    <div id="fin-custom-avg-result" style="margin-top:8px"></div>
  </div>`;
}

function renderFinCustomAvg() {
  const box = document.getElementById('fin-custom-avg-result');
  if (!box || !_finRatiosCustomCtx) return;
  const fromEl = document.getElementById('fin-avg-from'), toEl = document.getElementById('fin-avg-to');
  const from = parseInt(fromEl.value, 10), to = parseInt(toEl.value, 10);
  if (!from || !to || from > to) { box.innerHTML = `<div style="color:var(--red);font-size:12px">กรอกปีเริ่ม/ปีสิ้นสุดให้ถูกต้อง (ปีเริ่ม ≤ ปีสิ้นสุด)</div>`; return; }
  const { rat, allColsFull } = _finRatiosCustomCtx;
  const pickedCols = allColsFull.filter(c => { const y = +c.slice(0, 4); return y >= from && y <= to; });
  const rows = FIN_FINN_RATIO_GROUP.flatMap(g => g.rows).map(r => {
    const vals = pickedCols.map(c => (rat[r.key] || {})[c]).filter(v => v != null && !isNaN(v));
    const mean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
    const med = _median(vals);
    const fmt = v => v == null ? '—' : _finFmt(v);
    return `<tr><td style="font-size:12px;padding:4px 8px;white-space:nowrap">${_finLabel(r.key)}</td>
      <td class="r" style="font-size:12px">${fmt(mean)}</td>
      <td class="r" style="font-size:12px;font-weight:600">${fmt(med)}</td>
      <td class="r" style="font-size:11px;color:var(--text2)">${vals.length}</td></tr>`;
  }).join('');
  box.innerHTML = !pickedCols.length ? `<div style="color:var(--text2);font-size:12px">ไม่มีข้อมูลในช่วงปีที่เลือก</div>` : `
    <div style="overflow-x:auto"><table class="tbl" style="min-width:320px">
      <thead><tr><th>รายการ</th><th class="r">เฉลี่ย (${from}–${to})</th><th class="r">มัธยฐาน (${from}–${to})</th><th class="r">n ปี</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`;
}

// กลุ่ม field เฉพาะของ Finnomena (ratios/valuation รายไตรมาส) — hl:1 = โชว์ทั้งสองโหมด
const FIN_FINN_RATIO_GROUP = [{ group: 'อัตราส่วนการเงิน (Finnomena)', rows: [
  { key: 'Gross Margin', hl: 1 }, { key: 'Net Margin', hl: 1 }, { key: 'ROA', hl: 1 },
  { key: 'ROE', hl: 1 }, { key: 'Debt To Equity', hl: 1 }, { key: 'SGA To Revenue', hl: 1 },
  { key: 'Cash Cycle', hl: 1 }] }];
const FIN_FINN_VAL_GROUP = [{ group: 'มูลค่า / ราคา (Finnomena)', rows: [
  { key: 'Close', hl: 1 }, { key: 'Market Cap', hl: 1 }, { key: 'PE', hl: 1 },
  { key: 'PBV', hl: 1 }, { key: 'EV To EBITDA', hl: 1 }, { key: 'Dividend Yield', hl: 1 },
  { key: 'Book Value Per Share', hl: 1 }] }];

function _finLabel(key) {
  const th = (typeof FIN_TRANSLATE !== 'undefined') ? FIN_TRANSLATE[key] : null;
  const tip = (typeof FIN_TIPS !== 'undefined') ? FIN_TIPS[key] : null;
  const label = th ? `${key} <span style="color:var(--text2);font-weight:400">(${th})</span>` : key;
  return tip ? `${label}${_tipIconHtml(tip)}` : label;
}

function setFinFullShowAll(showAll, btn) {
  _finFullShowAll = showAll;
  document.querySelectorAll('#fin-view-hl-btn,#fin-view-all-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  // ใช้ source เดิมของข้อมูลที่ render อยู่ (รวม yahoo_q) — ไม่คำนวณใหม่จาก state
  if (_finData) _renderFinancialsFull(_finData, _finRenderSource);
}

function setFinPctMode(mode, btn) {
  _finPctMode = mode;
  document.querySelectorAll('#fin-pct-qoq-btn,#fin-pct-yoy-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (_finData) _renderFinancialsFull(_finData, _finRenderSource);
}

function setFinViewMode(mode, btn) {
  _finViewMode = mode;
  document.querySelectorAll('#fin-view-table-btn,#fin-view-chart-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (_finData) _renderFinancialsFull(_finData, _finRenderSource);
}

// แถวเดียวในโหมดกราฟ — เส้น sparkline (เก่า→ใหม่) + ค่าล่าสุด + %เปลี่ยนแปลงตลอดช่วงที่แสดง
// สีเส้น: ค่าล่าสุด ≥ ค่าแรกสุด = เขียว (โตขึ้น/ดีขึ้น) · น้อยกว่า = แดง (ลดลง)
// rowKey: ใช้เช็ค FIN_INVERT_KEYS — รายการ "ยิ่งน้อยยิ่งดี" (ค่าใช้จ่าย/หนี้) กลับสีให้ตรงกับตาราง
function _finRowChart(label, colLabels, vals, isRatioKey, rowKey) {
  const series = vals.map((v, i) => ({ d: colLabels[i], v })).filter(o => o.v != null && !isNaN(o.v));
  if (series.length < 2) return '';
  const invert = FIN_INVERT_KEYS.has(rowKey);
  const first = series[0].v, last = series[series.length - 1].v;
  let up = last >= first;
  if (invert) up = !up;
  const color = up ? '#3fb950' : '#f85149';
  const lastText = isRatioKey ? last.toFixed(2) : _finFmt(last);
  const pctChange = first !== 0 ? (last - first) / Math.abs(first) * 100 : null;
  const pctHtml = pctChange != null
    ? `<span style="color:${color};font-size:11px;font-weight:600">${pctChange >= 0 ? '+' : ''}${pctChange.toFixed(1)}%</span>`
    : '';
  return `
  <div style="padding:8px 8px 10px;border-bottom:1px solid var(--border)">
    <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:2px">
      <div style="font-size:12px;flex:1;min-width:160px">${label}</div>
      <div style="font-size:13px;font-weight:600">${lastText}</div>
      ${pctHtml}
    </div>
    <div style="font-size:10px;color:var(--text2);display:flex;justify-content:space-between">
      <span>${series[0].d}</span><span>${series[series.length - 1].d}</span>
    </div>
    ${_svgBars(series, { height: 60, qoq: true, invert, pos: '#3fb950', neg: '#f85149' })}
  </div>`;
}

// cols ของตารางงบเรียงเก่า->ใหม่เสมอ (ใช้คำนวณ QoQ/YoY แบบ i-1) ทำให้ปีล่าสุดอยู่ขวาสุด
// นอกจอตอนเปิดหน้าครั้งแรก — เลื่อนสกอลแนวนอนของทุกตารางไปขวาสุดให้เห็นปีล่าสุดก่อน
// ผู้ใช้ค่อยสกอเมาส์ (ลาก/สไลด์) ไปทางซ้ายเองถ้าอยากดูปีเก่า
function _finScrollTablesToLatest() {
  document.querySelectorAll('#fin-result div[style*="overflow-x:auto"]').forEach(el => {
    el.scrollLeft = el.scrollWidth;
  });
}

function _finFullTable(title, cols, colLabels, groups, rows, getVal, isRatio, showAll, noPctCols, hideGroupHdr, pctOffset, showAvg, avgCols) {
  const skipPct = noPctCols || new Set();
  const offset = pctOffset || 1;   // 1 = เทียบคอลัมน์ก่อนหน้า (QoQ/รายปี) · 4 = เทียบไตรมาสเดียวกันปีก่อน (YoY)
  // หา index คอลัมน์ "ก่อนหน้า" ของแต่ละคอลัมน์ไว้ล่วงหน้า — offset=1 (QoQ/รายปี) ใช้ i-1
  // ตรงๆ ได้เสมอ (เทียบงวดก่อนหน้าไม่ว่าจะห่างแค่ไหนยังมีความหมาย) แต่ offset=4 (YoY) ต้องหา
  // คอลัมน์ที่ "ห่างจริง ~1 ปี" แทนนับถอยหลัง 4 ช่องตรงๆ เพราะถ้ามีไตรมาสขาดหายกลางทาง
  // (เช่น Finnomena บางตัวขาดงบไตรมาสหนึ่ง) การนับ index ถอยหลังจะเทียบผิดไตรมาสไปเงียบๆ
  const prevIdxByCol = cols.map((c, i) => {
    if (offset !== 4) return i - offset;
    const target = new Date(c); target.setDate(target.getDate() - 365);
    let best = -1, bestDiff = Infinity;
    for (let j = 0; j < i; j++) {
      const diff = Math.abs(new Date(cols[j]) - target);
      if (diff < bestDiff) { bestDiff = diff; best = j; }
    }
    return bestDiff <= 45 * 86400000 ? best : -1;   // ยอมรับคลาดเคลื่อนได้ไม่เกิน 45 วัน
  });
  const isChart = _finViewMode === 'chart';
  const headerCells = colLabels.map(c => `<th class="r" style="min-width:90px;white-space:nowrap">${c}</th>`).join('')
    + (showAvg && !isChart ? `<th class="r" style="min-width:90px;white-space:nowrap;color:var(--blue);border-left:1px solid var(--border)" title="ค่าเฉลี่ยเลขคณิตของทุกปีที่มีข้อมูล ไม่ผูกกับตัวกรอง เฉพาะรายการหลัก/ทุก field — ปีวิกฤตสุดขั้ว (เช่น COVID) จะลากค่านี้ไปไกลจากผลงานปกติของหุ้นได้">เฉลี่ย (ทั้งหมด)</th>
       <th class="r" style="min-width:90px;white-space:nowrap;color:var(--blue)" title="ค่ามัธยฐาน (median) ของทุกปีที่มีข้อมูล — ทนทานต่อปีวิกฤตสุดขั้วมากกว่าค่าเฉลี่ย เพราะไม่ถูกลากด้วยค่าที่สุดโต่ง">มัธยฐาน (ทั้งหมด)</th>` : '');
  let bodyHtml = '';
  let shown = 0;
  groups.forEach(g => {
    const grows = g.rows.filter(r => showAll || r.hl);
    if (!grows.length) return;
    // หาเฉพาะแถวที่มีข้อมูลจริงก่อน — กัน (1) หัวกลุ่มลอยไม่มีตัวเลข เช่น "สรุปเงินสด"
    // (2) หัวกลุ่มซ้ำกับชื่อรายการเมื่อกลุ่มเหลือแถวเดียว (เช่นงบ Finnomena ที่มี field น้อย)
    const dataRows = grows.filter(r => cols.some(c => getVal(r.key, c) != null));
    if (!dataRows.length) return;                    // ทั้งกลุ่มไม่มีข้อมูล -> ไม่แสดงหัวกลุ่ม
    // แสดงหัวกลุ่มเฉพาะตารางที่มีหลายกลุ่ม (Yahoo/SET) — ตาราง Finnomena มีกลุ่มเดียว
    // ชื่อกลุ่มจะซ้ำกับ title ของตาราง (เช่น "อัตราส่วนการเงิน (Ratios)" + "อัตราส่วนการเงิน (Finnomena)")
    // hideGroupHdr = ตารางงบ Finnomena (income/balance/cashflow) มี field น้อย 4-5 แถว
    //                หัวกลุ่มย่อยไม่จำเป็น รกตา — ซ่อนทั้งหมด แต่คงไว้ในโหมด Yahoo ที่ข้อมูลเยอะ
    const showGroupHdr = dataRows.length > 1 && groups.length > 1 && !hideGroupHdr;   // มีหลายแถว+หลายกลุ่มถึงจะมีหัวกลุ่ม
    if (showGroupHdr) {
      const colspan = cols.length + 1 + (showAvg && !isChart ? 2 : 0);
      bodyHtml += isChart
        ? `<div style="font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:var(--blue);background:var(--card2);padding:6px 8px;margin-top:6px">${g.group}</div>`
        : `<tr><td colspan="${colspan}" style="font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:var(--blue);background:var(--card2);padding:6px 8px">${g.group}</td></tr>`;
    }
    dataRows.forEach(r => {
      const vals = cols.map(c => getVal(r.key, c));
      if (isChart) {
        const rowChart = _finRowChart(_finLabel(r.key), colLabels, vals, isRatio(r.key), r.key);
        if (rowChart) { bodyHtml += rowChart; shown++; }
        return;
      }
      shown++;
      const cells = vals.map((v, i) => {
        const prevIdx = prevIdxByCol[i];
        const prev = prevIdx >= 0 ? vals[prevIdx] : null;
        const cls = _finColCls(v, prev, r.key);
        const text = v == null ? '—' : (isRatio(r.key) ? v.toFixed(2) : _finFmt(v));
        let pctHtml = '';
        if (prev != null && v != null && prev !== 0 && !skipPct.has(i)) {
          const pct = (v - prev) / Math.abs(prev) * 100;
          pctHtml = `<div class="${cls}" style="font-size:10px;line-height:1.3">${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%</div>`;
        }
        const cellCls = skipPct.has(i) ? '' : cls;
        return `<td class="r ${cellCls}" style="font-size:12px;white-space:nowrap;vertical-align:top">${text}${pctHtml}</td>`;
      }).join('');
      let avgCell = '';
      if (showAvg) {
        // โชว์ทั้งเฉลี่ยเลขคณิตและมัธยฐานคู่กัน (แทนที่จะเลือกใช้แบบใดแบบหนึ่ง) — เห็นชัดเจน
        // เวลาสองค่านี้ต่างกันมาก (เช่นหุ้นกลุ่มโดน COVID หนักอย่าง AAV/AOT/MINT) ว่ามีปีวิกฤต
        // สุดขั้วปนอยู่ในประวัติ ต่างจากหุ้นปกติที่เฉลี่ย/มัธยฐานควรใกล้เคียงกัน
        // คำนวณจาก avgCols (ทุกปีที่มีข้อมูลจริงเสมอ) ไม่ใช่ cols ที่ตารางกำลังแสดง — กัน
        // toggle "เฉพาะรายการหลัก" (ตัดเหลือ 10 ปี) ทำให้ค่าเปลี่ยนไปมาโดยไม่ตั้งใจ
        const avgVals = (avgCols || cols).map(c => getVal(r.key, c));
        const numericVals = avgVals.filter(v => v != null && !isNaN(v));
        const mean = numericVals.length ? numericVals.reduce((a, b) => a + b, 0) / numericVals.length : null;
        const med = _median(numericVals);
        const fmt = v => v == null ? '—' : (isRatio(r.key) ? v.toFixed(2) : _finFmt(v));
        avgCell = `<td class="r" style="font-size:12px;white-space:nowrap;vertical-align:top;color:var(--blue);border-left:1px solid var(--border)">${fmt(mean)}</td>
          <td class="r" style="font-size:12px;white-space:nowrap;vertical-align:top;font-weight:600;color:var(--blue)">${fmt(med)}</td>`;
      }
      bodyHtml += `<tr${r.hl ? ' style="font-weight:600"' : ''}><td style="font-size:12px;padding:5px 8px;white-space:nowrap">${_finLabel(r.key)}</td>${cells}${avgCell}</tr>`;
    });
  });
  if (!shown) return '';
  if (isChart) {
    return `
    <div style="margin-top:16px">
      <div style="font-size:13px;font-weight:600;color:var(--blue);margin-bottom:6px">${title}</div>
      <div style="border:1px solid var(--border);border-radius:8px;overflow:hidden">${bodyHtml}</div>
    </div>`;
  }
  return `
  <div style="margin-top:16px">
    <div style="font-size:13px;font-weight:600;color:var(--blue);margin-bottom:6px">${title}</div>
    <div style="overflow-x:auto"><table class="tbl" style="min-width:400px">
      <thead><tr><th style="min-width:220px">รายการ (English / คำแปลไทย)</th>${headerCells}</tr></thead>
      <tbody>${bodyHtml}</tbody>
    </table></div>
  </div>`;
}

// ก็อปตัวเลขจากตาราง HTML ลำบาก (คอลัมน์เว้นไม่ตรงกันหลายงวด) — อ่านทุก table.tbl ที่
// render อยู่จริงใน #fin-result ตรงๆ (ไม่ต้องคำนวณ raw data ใหม่ ใช้ค่าที่แสดงจริงเป๊ะ)
// แล้วต่อกันเป็น CSV เดียวหลายบล็อก (คั่นบรรทัดว่าง) — ตัด pctHtml sub-line ออกด้วยการอ่าน
// childNodes[0] (text node แรกของ cell) เท่านั้น
function exportFinCSV() {
  const box = document.getElementById('fin-result');
  // ตัดตารางในกล่อง "คำนวณเฉลี่ย/มัธยฐานเอง" (_finCustomAvgHtml) ออก — โครงสร้าง DOM
  // ของมันไม่มี div ชื่อเรื่องแบบตารางงบทั่วไป (ดู title lookup ด้านล่างที่ทึกทักว่า
  // overflowWrap.parentElement.firstElementChild คือ div ชื่อเรื่องเสมอ) รวมเข้าไปจะได้
  // บล็อกชื่อเรื่องเพี้ยนปนอยู่ใน CSV
  const tables = box ? [...box.querySelectorAll('table.tbl')].filter(t => !t.closest('#fin-custom-avg-result')) : [];
  if (!tables.length) { alert('ยังไม่มีข้อมูลงบการเงินให้ export'); return; }
  const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const blocks = tables.map(table => {
    const overflowWrap = table.closest('div[style*="overflow-x:auto"]');
    const wrap = overflowWrap ? overflowWrap.parentElement : null;
    const title = wrap ? wrap.firstElementChild.textContent.trim() : '';
    // อ่าน text ของ cell โดยตัดกล่อง tooltip ที่ซ่อนอยู่ (_tipIconHtml → .scr-tip-icon) ออกก่อน —
    // ไม่งั้น textContent จะลากคำอธิบาย tooltip ทั้งย่อหน้ามาต่อกับชื่อรายการใน CSV
    const cellText = el => {
      const c = el.cloneNode(true);
      c.querySelectorAll('.scr-tip-icon').forEach(n => n.remove());
      return c.textContent.trim().replace(/\s+/g, ' ');
    };
    const headRow = [...table.querySelectorAll('thead th')].map(th => esc(cellText(th)));
    const bodyRows = [...table.querySelectorAll('tbody tr')].map(tr => {
      const cells = [...tr.children];
      if (cells.length === 1 && cells[0].hasAttribute('colspan')) return null;   // แถวหัวกลุ่ม ไม่ใช่ข้อมูล
      return cells.map((td, i) => {
        if (i === 0) return esc(cellText(td));
        const raw = td.childNodes[0] ? td.childNodes[0].textContent.trim() : td.textContent.trim();
        return esc(raw);
      }).join(',');
    }).filter(Boolean);
    return `${title}\n${headRow.join(',')}\n${bodyRows.join('\n')}`;
  });
  const csv = '﻿' + blocks.join('\n\n');
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })),
    download: `Financials_${(_finData && _finData.sym) || 'export'}_${new Date().toISOString().slice(0, 10)}.csv`,
  });
  a.click(); URL.revokeObjectURL(a.href);
}

function _renderFinancialsFull(d, source) {
  _finRenderSource = source;
  if (source === 'yahoo' || source === 'yahoo_q' || source === 'finnomena_q' || source === 'finnomena_y') {
    const isQ = source === 'yahoo_q' || source === 'finnomena_q';
    // QoQ อย่างเดียวหลอกตากับหุ้นมีฤดูกาล (เช่นค้าปลีก Q4 สูงกว่า Q3 ทุกปีเป็นปกติ ไม่ได้
    // แปลว่าธุรกิจโต) — เพิ่มตัวเลือก YoY (เทียบไตรมาสเดียวกันปีก่อน) เฉพาะตารางรายไตรมาส
    const pctOffset = isQ && _finPctMode === 'yoy' ? 4 : 1;
    const isFinnY = source === 'finnomena_y';                          // Finnomena รายปี (รวมจากไตรมาส 16 ปี)
    const isFinn = source === 'finnomena_q' || isFinnY;                // ใช้ badge/ตาราง ratio+valuation ของ Finnomena
    const toggleHtml = `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap">
      <div class="filter-row" style="gap:0;margin:0">
        <button class="filter-btn${_finFullShowAll ? '' : ' active'}" id="fin-view-hl-btn"  onclick="setFinFullShowAll(false,this)" style="border-radius:6px 0 0 6px;font-size:11px;padding:5px 10px">เฉพาะรายการหลัก</button>
        <button class="filter-btn${_finFullShowAll ? ' active' : ''}" id="fin-view-all-btn" onclick="setFinFullShowAll(true,this)"  style="border-radius:0 6px 6px 0;font-size:11px;padding:5px 10px">ทุก field</button>
      </div>
      <div class="filter-row" style="gap:0;margin:0" title="สลับมุมมองตาราง/กราฟแนวโน้มรายบรรทัด">
        <button class="filter-btn${_finViewMode === 'chart' ? '' : ' active'}" id="fin-view-table-btn" onclick="setFinViewMode('table',this)" style="border-radius:6px 0 0 6px;font-size:11px;padding:5px 10px">📋 ตาราง</button>
        <button class="filter-btn${_finViewMode === 'chart' ? ' active' : ''}" id="fin-view-chart-btn" onclick="setFinViewMode('chart',this)" style="border-radius:0 6px 6px 0;font-size:11px;padding:5px 10px">📈 กราฟ</button>
      </div>
      ${isQ ? `
      <div class="filter-row" style="gap:0;margin:0" title="QoQ = เทียบไตรมาสก่อนหน้า · YoY = เทียบไตรมาสเดียวกันของปีก่อน (ตัดผลฤดูกาลออก)">
        <button class="filter-btn${_finPctMode === 'yoy' ? '' : ' active'}" id="fin-pct-qoq-btn" onclick="setFinPctMode('qoq',this)" style="border-radius:6px 0 0 6px;font-size:11px;padding:5px 10px">% QoQ</button>
        <button class="filter-btn${_finPctMode === 'yoy' ? ' active' : ''}" id="fin-pct-yoy-btn" onclick="setFinPctMode('yoy',this)" style="border-radius:0 6px 6px 0;font-size:11px;padding:5px 10px">% YoY</button>
      </div>` : ''}
      <button class="filter-btn" style="margin-left:auto;font-size:11px;padding:5px 10px" onclick="exportFinCSV()" title="ดาวน์โหลดตารางงบการเงินที่แสดงอยู่เป็น CSV">⬇ CSV</button>
    </div>`;
    const inc = d.income || {}, bal = d.balance || {}, cf = d.cashflow || {};
    const rat = d.ratios || {}, val = d.valuation || {};
    // คอลัมน์ของตารางงบ (income/balance/cashflow/ratios) อิงวันที่ของ "งบจริง" เท่านั้น —
    // ไม่รวม valuation เพราะราคา/PE/Market Cap อัปเดตล่วงหน้ากว่างบ 1-2 ไตรมาส (มีงวดอนาคต)
    // ถ้ารวมเข้ามาจะทำให้ตารางงบมีคอลัมน์ขวาสุดว่างเปล่า (ดูเหมือน "ไม่มีตัวเลข")
    const allDates = new Set();
    [inc, bal, cf, rat].forEach(sec => Object.values(sec).forEach(row => Object.keys(row).forEach(k => allDates.add(k))));
    // ไตรมาส/รายปีลึก: default โชว์งวดล่าสุด — "ทุก field" โชว์ทั้งหมด (ไตรมาส ~65 งวด / รายปี 16 ปี)
    const deepAnnual = isFinnY;
    const _slice = isQ ? (_finFullShowAll ? -999 : -8) : (deepAnnual ? (_finFullShowAll ? -999 : -10) : -6);
    const allColsFull = [...allDates].sort();     // ชุดวันที่เต็ม ไม่ตัดตาม _slice — ใช้เป็นฐานคำนวณเฉลี่ย/มัธยฐานของตาราง Ratios
    const cols = allColsFull.slice(_slice);
    const colLabels = cols.map(c => isQ ? c.slice(0, 7) : c.slice(0, 4));
    // valuation ใช้ชุดวันที่ของตัวเอง (ยาวกว่า) เพื่อให้โชว์งวดราคาล่าสุดครบ ไม่มีคอลัมน์ว่าง
    const valDates = new Set();
    Object.values(val).forEach(row => Object.keys(row).forEach(k => valDates.add(k)));
    const valCols = [...valDates].sort().slice(_slice);
    const valColLabels = valCols.map(c => isQ ? c.slice(0, 7) : c.slice(0, 4));
    const isRatio = () => false;

    // ป้าย SET/DR อิงแท็บที่ผู้ใช้เลือก (_finTab) ไม่ใช่ d.type — เพราะ payload จาก
    // Finnomena mirror มี type='mirror' จะตกไปโชว์ DR ผิดสำหรับหุ้นไทย
    const typeLabel = _finTab === 'dr'
      ? `<span style="background:#3fb95022;color:#3fb950;padding:2px 8px;border-radius:4px;font-size:11px">🌏 DR</span>`
      : `<span style="background:#1f6feb22;color:#58a6ff;padding:2px 8px;border-radius:4px;font-size:11px">🇹🇭 SET</span>`;

    // badge แหล่งข้อมูลจริง (เด่นชัด) — ต่างจากปุ่มสลับด้านบนที่เป็นตัวเลือก ไม่ใช่แหล่งที่ใช้จริง
    const finnLabel = isFinnY ? 'งบรายปี ย้อน 16 ปี (รวมจากไตรมาส)' : 'งบไตรมาสย้อน 16 ปี';
    const srcBadge = isFinn
      ? `<span style="background:#8957e522;color:#a371f7;padding:2px 9px;border-radius:4px;font-size:11px;font-weight:600">📊 ข้อมูลจาก Finnomena · ${finnLabel}</span>`
      : `<span style="background:#e3742022;color:#e87d3e;padding:2px 9px;border-radius:4px;font-size:11px;font-weight:600">📊 ข้อมูลจาก Yahoo Finance</span>`;

    // ป้ายสถานะการตรวจทานงบรวมปีกับ Yahoo (เฉพาะ finnomena_y — จาก fy_status ที่ endpoint ส่งมา)
    // ทุกกรณีคอลัมน์คือ "ปีปฏิทิน (ม.ค.–ธ.ค.)" — พิสูจน์แล้วว่า Finnomena จัดกลุ่มแบบปฏิทิน
    // (MSFT/NIKE ตรวจกับผลรวมไตรมาส Yahoo แล้วตรง 0.0%) ป้ายแค่บอกว่าเทียบข้ามแหล่งยังไง
    const _fyBanners = {
      calendar_verified: ['#3fb950', `✓ บริษัทนี้ใช้<b>ปีบัญชีไม่ตรงปีปฏิทิน</b> แต่ตารางนี้รวมเป็น "ปีปฏิทิน ม.ค.–ธ.ค." ซึ่ง<b>ตรวจกับผลรวมไตรมาสจริงของ Yahoo แล้วตรงกัน</b>${d.fy_diff_pct != null ? ` (ต่าง ${d.fy_diff_pct}%)` : ''} — ตัวเลขถูกต้อง ใช้ดู YoY ได้ปกติ · แค่จะไม่ตรงกับ "งบปีบัญชี" ที่บริษัท/Yahoo รายปีรายงาน (คนละหน้าต่างเวลา)`],
      calendar_window: ['#e3b341', `⚠ บริษัทนี้ใช้<b>ปีบัญชีไม่ตรงปีปฏิทิน</b> — ตารางนี้รวมเป็น "ปีปฏิทิน ม.ค.–ธ.ค." (ผลรวม 12 เดือนจริง ใช้ดูแนวโน้ม/YoY ภายในตารางได้) แต่จะ<b>ไม่ตรงกับงบปีบัญชี</b>ที่บริษัท/Yahoo รายปีรายงาน${d.fy_diff_pct != null ? ` (ต่างมัธยฐาน ${d.fy_diff_pct}%)` : ''} เพราะคนละหน้าต่างเวลา — เทียบข้ามแหล่งให้ใช้รายไตรมาสแทน`],
      fiscal_shift: ['#e3b341', `⚠ บริษัทนี้ปีบัญชีจบต้นปีปฏิทิน (~ม.ค.) — ตารางรวมเป็นปีปฏิทิน ยอดใกล้เคียงปีบัญชีของบริษัทแต่<b>ป้ายปีเหลื่อมกัน ~1 ปี</b> (ตรวจกับ Yahoo แล้วยอดตรงเมื่อเลื่อนป้าย${d.fy_diff_pct != null ? ` ต่าง ${d.fy_diff_pct}%` : ''}) เช่นคอลัมน์ 2024 ≈ FY2025 ของบริษัท`],
      unverified: ['#8b949e', `ℹ ไม่มีงบ Yahoo ให้ตรวจทาน (หุ้นนอกพอร์ต) — ยอดรวมจากไตรมาส Finnomena ล้วน สม่ำเสมอในชุดเดียวกัน ใช้ดูแนวโน้ม/เทียบปีต่อปีได้ · บริษัทปีบัญชีไม่ตรงปฏิทินจะเป็นผลรวมแบบปีปฏิทิน (ไม่ตรงรายงานปีบัญชีของบริษัท)`],
      definition: ['#f85149', `⚠ ยอดรวมต่างจาก Yahoo เกินเกณฑ์${d.fy_diff_pct != null ? ` (มัธยฐาน ${d.fy_diff_pct}%)` : ''} ทั้งที่ปีบัญชีตรงกัน — มักเกิดกับธนาคาร/ประกัน/โฮลดิ้งที่นิยาม "รายได้" ต่างกันระหว่างแหล่ง (เช่น gross vs net interest income) · ตัวเลขสม่ำเสมอในชุด Finnomena เอง ใช้ดูแนวโน้มได้ แต่อย่าเทียบค่าตรงๆ กับแหล่งอื่น`],
    };
    const _fyB = isFinnY ? _fyBanners[d.fy_status] : null;
    const fyBanner = _fyB
      ? `<div style="margin:2px 0 8px;padding:7px 10px;border:1px solid ${_fyB[0]}55;background:${_fyB[0]}14;color:${_fyB[0]};border-radius:6px;font-size:11.5px;line-height:1.5">${_fyB[1]}</div>`
      : '';

    const srcNote = isFinnY
      ? 'Finnomena · รายได้/กำไร/กระแสเงินสด = รวม 4 ไตรมาสของปี · งบดุล/valuation = ณ สิ้นปี · เฉพาะปีที่ครบ 4 ไตรมาส'
      : isFinn
        ? 'Finnomena · วันที่งวดสังเคราะห์จาก fiscal+ไตรมาส · แหล่งงบไตรมาสย้อนยาวที่สุด'
        : `Yahoo Finance · yfinance: ${_escHtml(d.yf || '—')}`;
    const disclaimer = isFinnY
      ? '⚠ งบรายปีนี้รวมจากงบไตรมาส Finnomena (พิสูจน์แล้วยอดตรงกับ Yahoo รายปี) — ลึกถึง ~16-20 ปี · EPS รายปีเป็นการรวม 4 ไตรมาส อาจคลาดจากจำนวนหุ้นที่เปลี่ยนระหว่างปีเล็กน้อย'
      : isFinn
        ? '⚠ Finnomena ครอบคลุมหุ้นไทย/US/HK — งบไตรมาสย้อนยาวถึง ~16 ปี · ใช้ดูแนวโน้มระยะยาว'
        : '⚠ ข้อมูลจาก Yahoo Finance อาจไม่ครบถ้วนสำหรับหุ้นบางตัว โดยเฉพาะ VN/EU — ใช้เพื่อดูแนวโน้มเท่านั้น';

    // ชื่อบริษัท: หุ้น mirror US/HK เก็บ name = ticker — หาชื่อเต็มจาก _finMirNames (แยกตลาดด้วยสกุลเงิน)
    let dispName = (d.name && d.name !== d.sym) ? d.name : '';
    if (!dispName) {
      const mk = d.currency === 'USD' ? 'US' : d.currency === 'HKD' ? 'HK' : d.currency === 'JPY' ? 'JP' : null;
      if (mk) dispName = _finMirName(mk, d.sym);
    }

    // ปุ่มเปิด TradingView — เฉพาะแท็บ DR (US/HK) แสดง placeholder ก่อนแล้วค่อย resolve
    // yf ticker จริงแบบ async (/api/resolve-yf — เช็ค DR universe ก่อน เช่น MICRON -> MU,
    // ไม่เจอค่อยเดาจาก currency) กันเดาผิดตอน _drData ยังไม่โหลด (เช่นเข้าหน้างบการเงิน
    // ตรงๆ โดยไม่ผ่านหน้า DR มาก่อน)
    const tvMarket = d.currency === 'USD' ? 'US' : d.currency === 'HKD' ? 'HK' : d.currency === 'JPY' ? 'JP' : null;
    const tvIcon = `<svg width="13" height="13" viewBox="0 0 32 32" fill="#2962ff"><path d="M16 2C8.268 2 2 8.268 2 16s6.268 14 14 14 14-6.268 14-14S23.732 2 16 2zm0 2c6.627 0 12 5.373 12 12S22.627 28 16 28 4 22.627 4 16 9.373 4 16 4zm-1 4v9H9l7 7 7-7h-6V8h-2z"/></svg>`;
    const tvLinkStyle = `display:none;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer`;
    let tvHtml = '';
    if (_finTab === 'dr' && !IS_STATIC) {
      // หุ้น DR/mirror: sym ไม่ตรงกับ yf ticker เสมอ (เช่น MICRON -> MU) ต้อง resolve
      // แบบ async ผ่าน /api/resolve-yf ก่อน ถึงจะรู้ symbol ที่ถูกต้องของ TradingView
      tvHtml = `<a id="fin-tv-link" href="#" target="_blank" rel="noopener" style="${tvLinkStyle}" title="เปิดใน TradingView">${tvIcon}TradingView</a>`;
    } else if (_finTab === 'set') {
      // หุ้นไทย: symbol ตรงกับ TradingView namespace "SET:" อยู่แล้ว ไม่ต้อง resolve
      tvHtml = `<a href="https://www.tradingview.com/chart/?symbol=SET:${encodeURIComponent(d.sym)}&interval=D" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer" title="เปิดใน TradingView">${tvIcon}TradingView</a>`;
    }
    // ปุ่ม Jitta — เทียบงบ Finnomena ที่โชว์อยู่ในหน้านี้กับ Jitta ได้ในคลิกเดียว
    const jittaDot = `<span style="width:8px;height:8px;border-radius:50%;background:#1fd18f;display:inline-block"></span>`;
    let jittaHtml = '';
    if (_finTab === 'dr' && !IS_STATIC) {
      // เหมือน fin-tv-link: ต้อง resolve yf ก่อนถึงจะรู้ exchange ที่ถูกต้อง (เติมใน _loadFinTVLink)
      jittaHtml = `<a id="fin-jitta-link" href="#" target="_blank" rel="noopener" style="${tvLinkStyle}" title="เปิดใน Jitta (Jitta Score/Line + งบรายปี 10 ปี)">${jittaDot}Jitta</a>`;
    } else if (_finTab === 'set') {
      jittaHtml = `<a href="https://www.jitta.com/stock/bkk:${encodeURIComponent(d.sym.toLowerCase())}/factsheet" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer" title="เปิดใน Jitta (Jitta Score/Line + งบรายปี 10 ปี)">${jittaDot}Jitta</a>`;
    }
    // ปุ่ม Factsheet / SET — เฉพาะหุ้นไทย ลิงก์ตรงไปหน้า SET.or.th ของหุ้นนั้น
    // (URL เดียวกับที่ chart modal ใช้อยู่แล้ว — ดู openChartModal ด้านบน)
    let fsSetHtml = '';
    if (_finTab === 'set') {
      const fsUrl = `https://www.set.or.th/th/market/product/stock/quote/${encodeURIComponent(d.sym.toLowerCase())}/factsheet`;
      const setUrl = `https://www.set.or.th/th/market/product/stock/quote/${encodeURIComponent(d.sym)}/financial-statement/company-highlights`;
      const bpUrl = `https://bullpedia.ai/?ticker=${encodeURIComponent(d.sym)}`;
      fsSetHtml = `
        <a href="${fsUrl}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer" title="ดู Factsheet บน SET">📄 Factsheet</a>
        <a href="${setUrl}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer" title="ดูหน้าหุ้นบน SET.or.th">🌐 SET</a>
        <a href="${bpUrl}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 10px;border-radius:6px;border:1px solid var(--border);background:var(--card2);color:var(--text2);text-decoration:none;cursor:pointer" title="เปิดใน Bullpedia">🐂 Bullpedia</a>`;
    }

    // ผูก context ให้ renderFinCustomAvg() คำนวณช่วงปีที่ผู้ใช้กรอกเองได้ (เฉพาะตาราง Ratios
    // ของ Finnomena) — ต้องตั้งก่อน render กล่องคำนวณด้านล่าง เพราะฟังก์ชันนั้นอ่านจาก global
    _finRatiosCustomCtx = isFinn ? { rat, allColsFull } : null;
    document.getElementById('fin-result').innerHTML = `
    <div class="card" style="margin-top:12px">
      ${_finTab === 'dr' && !IS_STATIC ? `
      <!-- TRADINGVIEW LIVE WIDGET — เฉพาะ DR ที่อ้างอิงหุ้นสหรัฐฯ เพราะ widget ฟรีของ
           TradingView มีข้อมูลครบเฉพาะตลาด US เท่านั้น (แสดง/ผูก symbol ให้ใน _loadFinTVLink) -->
      <div id="fin-tv-widget-box" style="display:none;margin-bottom:14px">
        <div id="fin-tv-widget" style="height:480px;border-radius:6px;overflow:hidden;background:#131722"></div>
      </div>` : ''}
      <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:4px">
        <span style="font-size:18px;font-weight:700">${_escHtml(d.sym)}</span>
        ${typeLabel}
        ${srcBadge}
        <span style="font-size:13px;color:var(--text2)">${_escHtml(dispName || '')}</span>
        ${tvHtml}
        ${jittaHtml}
        ${fsSetHtml}
        <span style="font-size:11px;color:var(--text2);margin-left:auto">สกุลเงิน: <strong>${_escHtml(d.currency || '—')}</strong></span>
      </div>
      <div style="font-size:11px;color:var(--text2);margin-bottom:10px">${srcNote} · ${isQ ? `ข้อมูลรายไตรมาส (% = ${pctOffset === 4 ? 'เทียบไตรมาสเดียวกันปีก่อน YoY' : 'เทียบงวดก่อนหน้า QoQ'})` : 'ข้อมูลรายปี'}</div>
      ${fyBanner}
      <div id="fin-desc-box" style="display:none;background:var(--card2);border:1px solid var(--border);border-radius:8px;padding:10px 12px;margin-bottom:10px"></div>
      ${_finTab === 'set' ? `<div id="fin-lts" style="display:none;margin-bottom:10px"></div>` : ''}
      ${_finTrendSection(d, source)}
      ${toggleHtml}
      ${_finFullTable('📊 งบกำไรขาดทุน (Income Statement)', cols, colLabels, FIN_YAHOO_GROUPS.income,   null, (key,c) => (inc[key]||{})[c],  isRatio, _finFullShowAll, null, isFinn, pctOffset)}
      ${_finFullTable('📋 งบดุล (Balance Sheet)',           cols, colLabels, FIN_YAHOO_GROUPS.balance,  null, (key,c) => (bal[key]||{})[c],  isRatio, _finFullShowAll, null, isFinn, pctOffset)}
      ${_finFullTable('💵 กระแสเงินสด (Cash Flow)',          cols, colLabels, FIN_YAHOO_GROUPS.cashflow, null, (key,c) => (cf[key]||{})[c],   isRatio, _finFullShowAll, null, isFinn, pctOffset)}
      ${isFinn ? _finFullTable('📐 อัตราส่วนการเงิน (Ratios)', cols, colLabels, FIN_FINN_RATIO_GROUP, null, (key,c) => (rat[key]||{})[c], () => false, true, null, false, pctOffset, true, allColsFull) : ''}
      ${isFinn ? _finCustomAvgHtml() : ''}
      ${isFinn ? _finFullTable('💰 มูลค่า / Valuation', valCols, valColLabels, FIN_FINN_VAL_GROUP, null, (key,c) => (val[key]||{})[c], () => false, true, null, false, pctOffset) : ''}
      <div style="font-size:10px;color:var(--text2);margin-top:16px">${disclaimer}</div>
    </div>`;
    _finScrollTablesToLatest();
    _loadFinDescription(d.sym, _finTab === 'dr' ? tvMarket : 'TH');
    if (_finTab === 'dr' && !IS_STATIC) _loadFinTVLink(d.sym, tvMarket);
    if (_finTab === 'set') _loadPriceAnalyticsFin(d.sym);
    _drawFinTrendCharts(d);
    if (isFinn && !IS_STATIC) _loadLiveValuationBand(d, _finTab === 'dr', tvMarket);
    return;
  }

  // source === 'set'
  const entries = d.entries || [];
  const cols = entries.map((_, i) => i);
  // quarter="Q9" = รหัสภายในของ SET.or.th แปลว่า "งบเต็มปี" (ไม่ใช่ไตรมาสที่ 9)
  // quarter อื่นๆ (Q1/Q2/Q3) = ปีนั้นยังไม่ปิดงบเต็มปี มีแค่ไตรมาสล่าสุดที่รายงานเข้ามา
  const colLabels = entries.map(e => e.quarter === 'Q9' ? `${e.year}` : `${e.year}*`);
  const hasPartial = entries.some(e => e.quarter !== 'Q9');
  // ไม่คำนวณ % ของคอลัมน์ปีที่ยังไม่ปิดงบเต็มปี (เทียบไตรมาสเดียวกับยอดเต็มปีจะเพี้ยน)
  const noPctCols = new Set(entries.map((e, i) => e.quarter !== 'Q9' ? i : -1).filter(i => i >= 0));
  const isRatio = (key) => (typeof FIN_SET_RATIO_FIELDS !== 'undefined') && FIN_SET_RATIO_FIELDS.has(key);
  const getVal = (key, i) => {
    const v = entries[i] ? entries[i][key] : null;
    return (v == null) ? null : v * (isRatio(key) ? 1 : 1000);   // API หน่วยพันบาท ยกเว้น ratio/eps
  };

  document.getElementById('fin-result').innerHTML = `
  <div class="card" style="margin-top:12px">
    <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:4px">
      <span style="font-size:18px;font-weight:700">${_escHtml(d.sym)}</span>
      <span style="background:#d9932e22;color:#d9932e;padding:2px 8px;border-radius:4px;font-size:11px">🇹🇭 SET.or.th</span>
      <span style="font-size:11px;color:var(--text2);margin-left:auto">สกุลเงิน: <strong>THB</strong></span>
    </div>
    <div style="font-size:11px;color:var(--text2);margin-bottom:6px">company-highlight API · หน่วยที่แปลงแล้ว: บาทเต็ม (API ส่งมาเป็นพันบาท)</div>
    ${hasPartial ? `<div style="font-size:10px;color:var(--text2);margin-bottom:10px">⚠ ปีที่มี <b>*</b> ต่อท้าย = ยังไม่ปิดงบเต็มปี มีแค่ไตรมาสล่าสุดที่บริษัทรายงานเข้ามาเท่านั้น ไม่ใช่ยอดสะสมทั้งปี — อย่าเทียบตรงๆ กับปีอื่นที่เป็นงบเต็มปี</div>` : ''}
    <div id="fin-lts" style="display:none;margin-bottom:10px"></div>
    <div style="display:flex;margin-bottom:4px">
      <button class="filter-btn" style="margin-left:auto;font-size:11px;padding:5px 10px" onclick="exportFinCSV()" title="ดาวน์โหลดตารางงบการเงินที่แสดงอยู่เป็น CSV">⬇ CSV</button>
    </div>
    ${_finFullTable('🧾 งบการเงิน (Company Highlight)', cols, colLabels, FIN_SET_GROUPS, null, getVal, isRatio, true, noPctCols)}
    <div id="fin-set-qpl-box" style="display:none;margin-top:4px"></div>
  </div>`;
  _finScrollTablesToLatest();
  _loadPriceAnalyticsFin(d.sym);
  _loadSetQplTable(d.sym);
}

// ============================================================
// VALUATION BAND PAGE
// ============================================================
let _bandGateShown = false;

// Valuation Band scrape สดจาก mrlikestock.com ตอน request เข้ามา — bake เป็นไฟล์
// static ล่วงหน้าไม่ได้ (ต้องรู้ symbol ที่ผู้ใช้จะค้นก่อน) เดิมผู้ใช้บนเวอร์ชันเว็บ
// ต้องพิมพ์+กดค้นหาก่อนถึงจะเจอข้อความ error ว่าใช้ไม่ได้ — แจ้งไว้ล่วงหน้าแทน
// เหมือนหน้า Fundamental Screener (fs-gate)
function loadBandPage() {
  if (_bandGateShown || !IS_STATIC) return;
  _bandGateShown = true;
  const gate = document.getElementById('band-gate'), body = document.getElementById('band-body');
  if (!gate || !body) return;
  gate.style.display = ''; body.style.display = 'none';
  gate.innerHTML = '📊 Valuation Band ใช้ได้เฉพาะเวอร์ชันรันบนเครื่อง (local) — ดึงข้อมูลสดจาก mrlikestock.com / 9hoon.com / settrade ตอนค้นหา ไม่สามารถ bake เป็นไฟล์ static ล่วงหน้าได้ (ไม่รู้ล่วงหน้าว่าจะค้นหุ้นตัวไหน)';
}

function _bandZone(cur, b) {
  if (cur == null) return { label: '—', color: 'var(--text2)' };
  if (cur < b.m2sd) return { label: 'ต่ำกว่า -2SD  (Undervalued มาก)', color: '#22c55e' };
  if (cur < b.m1sd) return { label: '-2SD ถึง -1SD  (Undervalued)',      color: '#86efac' };
  if (cur < b.avg)  return { label: '-1SD ถึง AVG  (ต่ำกว่าค่าเฉลี่ย)', color: '#facc15' };
  if (cur < b.p1sd) return { label: 'AVG ถึง +1SD  (สูงกว่าค่าเฉลี่ย)', color: '#fb923c' };
  if (cur < b.p2sd) return { label: '+1SD ถึง +2SD  (Overvalued)',        color: '#f87171' };
  return               { label: 'สูงกว่า +2SD  (Overvalued มาก)',         color: '#ef4444' };
}

// request token กัน race — ถ้าผู้ใช้ค้นหุ้นใหม่ก่อนผลของหุ้นก่อนหน้าโหลดเสร็จ
// ผลที่มาช้ากว่า (ของหุ้นเก่า) ต้องไม่ทับผลของหุ้นล่าสุดที่ผู้ใช้เพิ่งค้น
let _bandReqSeq = 0;

async function searchBand() {
  const sym = (document.getElementById('band-input').value || '').trim().toUpperCase();
  if (!sym) return;
  const myReq = ++_bandReqSeq;
  document.getElementById('band-loading').style.display = 'block';
  document.getElementById('band-result').style.display  = 'none';
  document.getElementById('band-error').style.display   = 'none';
  document.getElementById('np-card').style.display      = 'block';
  document.getElementById('np-error').style.display     = 'none';
  document.getElementById('np-body').style.display      = 'none';
  document.getElementById('rr-card').style.display      = 'block';
  document.getElementById('rr-error').style.display     = 'none';
  document.getElementById('rr-body').style.display      = 'none';

  // สอง endpoint นี้ดึงจากคนละเว็บ ยิงพร้อมกันแล้วเรนเดอร์แยกกัน — ตัวหนึ่งพังไม่ควรบัง
  // ผลของอีกตัว (mrlikestock.com ล่ม 9hoon.com ก็ยังอยากเห็น, และกลับกัน)
  const bandTask = (async () => {
    try {
      // backend มี timeout 20s ต่อการเชื่อมต่อ mrlikestock.com แต่เป็น per-chunk ไม่ใช่ hard cap
      // รวม — ถ้าเว็บต้นทางตอบช้ามาก fetch เปล่าจะค้าง spinner ไม่มีทางยกเลิกนอกจากรีเฟรชหน้า
      const res  = await _fetchTimeout(`/api/band/${encodeURIComponent(sym)}`, 30000,
        'หมดเวลารอข้อมูล Band (เกิน 30 วิ) — เว็บต้นทางอาจช้าหรือไม่ตอบสนอง ลองใหม่อีกครั้ง');
      const data = await res.json();
      if (myReq !== _bandReqSeq) return; // มีคำค้นใหม่กว่าเข้ามาแล้ว ทิ้งผลนี้
      if (data.error) {
        document.getElementById('band-error').style.display   = 'block';
        document.getElementById('band-error').textContent     = '⚠ ' + data.error;
        return;
      }
      _renderBandResult(data, myReq);
    } catch(e) {
      if (myReq !== _bandReqSeq) return;
      document.getElementById('band-error').style.display   = 'block';
      document.getElementById('band-error').textContent     = '⚠ เกิดข้อผิดพลาด: ' + e.message;
    }
  })();

  const npTask = (async () => {
    try {
      const res  = await _fetchTimeout(`/api/npdata/${encodeURIComponent(sym)}`, 30000,
        'หมดเวลารอข้อมูลกำไรสุทธิ (เกิน 30 วิ) — 9hoon.com อาจช้าหรือไม่ตอบสนอง ลองใหม่อีกครั้ง');
      const data = await res.json();
      if (myReq !== _bandReqSeq) return;
      if (data.error) {
        document.getElementById('np-error').style.display = 'block';
        document.getElementById('np-error').textContent   = '⚠ ' + data.error;
        return;
      }
      _renderNpResult(data);
    } catch(e) {
      if (myReq !== _bandReqSeq) return;
      document.getElementById('np-error').style.display = 'block';
      document.getElementById('np-error').textContent   = '⚠ เกิดข้อผิดพลาด: ' + e.message;
    }
  })();

  const rrTask = (async () => {
    try {
      const res  = await _fetchTimeout(`/api/research-reports/${encodeURIComponent(sym)}`, 30000,
        'หมดเวลารอบทวิเคราะห์ (เกิน 30 วิ) — settrade/9hoon อาจช้าหรือไม่ตอบสนอง ลองใหม่อีกครั้ง');
      const data = await res.json();
      if (myReq !== _bandReqSeq) return;
      if (data.error) {
        document.getElementById('rr-error').style.display = 'block';
        document.getElementById('rr-error').textContent   = '⚠ ' + data.error;
        return;
      }
      _renderResearchReports(data);
    } catch(e) {
      if (myReq !== _bandReqSeq) return;
      document.getElementById('rr-error').style.display = 'block';
      document.getElementById('rr-error').textContent   = '⚠ เกิดข้อผิดพลาด: ' + e.message;
    }
  })();

  await Promise.allSettled([bandTask, npTask, rrTask]);
  if (myReq === _bandReqSeq) {
    document.getElementById('band-loading').style.display = 'none';
  }
}

function _rrBadgeClass(rating) {
  const r = (rating || '').toLowerCase();
  if (r.includes('buy') || r.includes('ซื้อ') || r.includes('outperform') || r.includes('overweight')) return 'buy';
  if (r.includes('sell') || r.includes('ขาย') || r.includes('underperform') || r.includes('underweight') || r.includes('reduce')) return 'sell';
  return 'hold';
}

function _renderResearchReports(data) {
  const card = document.getElementById('rr-card');
  const body = document.getElementById('rr-body');
  card.style.display = 'block';
  body.style.display = 'block';

  const srcEl = document.getElementById('rr-source');
  if (srcEl) {
    const src = data.source === 'settrade' ? 'settrade IAA consensus'
      : data.source === '9hoon' ? '9hoon.com (สำรอง)' : '';
    srcEl.textContent = src ? `· ${src}${data.cached_at ? ' · cache ' + data.cached_at : ''}` : '';
  }

  const s = data.summary;
  const sEl = document.getElementById('rr-summary');
  const nameHdr = data.company_name
    ? `<div style="font-size:14px;font-weight:600;margin-bottom:8px">${_escHtml(data.company_name)}</div>` : '';
  if (s) {
    const cell = (lbl, val) => val == null || val === ''
      ? '' : `<div><span class="rr-s-lbl">${_escHtml(lbl)}</span><br><span class="rr-s-val">${_escHtml(val)}</span></div>`;
    sEl.innerHTML = nameHdr + `<div class="rr-summary-row">
      ${cell('ราคาล่าสุด', s.last_price)}
      ${cell('โบรกคัฟเวอร์', s.coverage)}
      ${cell('Buy / Hold / Sell', (s.buy != null || s.hold != null || s.sell != null) ? `${s.buy ?? '—'} / ${s.hold ?? '—'} / ${s.sell ?? '—'}` : null)}
      ${cell('คำแนะนำ', s.rating)}
      ${cell('เป้าหมาย (Avg)', s.target_avg)}
      ${cell('เป้าหมาย (Median)', s.target_median)}
      ${cell('Upside', s.upside)}
      ${cell('EPS ' + (data.year_labels?.[0] || 'F1') + ' / ' + (data.year_labels?.[1] || 'F2'),
             (s.eps_y1 != null) ? `${s.eps_y1} / ${s.eps_y2 ?? '—'}` : null)}
      ${cell('P/E ' + (data.year_labels?.[0] || 'F1') + ' / ' + (data.year_labels?.[1] || 'F2'),
             (s.pe_y1 != null) ? `${s.pe_y1} / ${s.pe_y2 ?? '—'}` : null)}
    </div>`;
  } else {
    sEl.innerHTML = nameHdr;
  }

  const grid = document.getElementById('rr-grid');
  const reps = data.reports || [];
  if (!reps.length) {
    grid.innerHTML = '<div class="text2" style="padding:12px;font-size:13px">— ยังไม่มีไฟล์บทวิเคราะห์ (PDF) ที่เปิดอ่านได้สำหรับหุ้นนี้ —</div>';
    return;
  }
  grid.innerHTML = reps.map(r => {
    const bc = _rrBadgeClass(r.rating);
    const pdf = _escHtml(r.pdf_url);
    return `<div class="rr-item">
      <div class="rr-item-head">
        <div>
          <div class="rr-item-broker">${_escHtml(r.broker || '—')}</div>
          <div class="rr-item-date">${_escHtml(r.date || '')}</div>
        </div>
        ${r.rating ? `<span class="rr-badge ${bc}">${_escHtml(r.rating)}</span>` : ''}
      </div>
      <div class="rr-item-meta">
        ${r.target ? `<div><span class="rr-m-lbl">เป้าหมาย</span> <b>${_escHtml(r.target)}</b></div>` : ''}
        ${r.year ? `<div><span class="rr-m-lbl">ปี</span> ${_escHtml(r.year)}</div>` : ''}
        ${r.analyst ? `<div><span class="rr-m-lbl">นักวิเคราะห์</span> ${_escHtml(r.analyst)}</div>` : ''}
        ${(r.rec && r.rec !== r.rating) ? `<div class="rr-m-rec">"${_escHtml(r.rec)}"</div>` : ''}
      </div>
      <iframe src="${pdf}" loading="lazy" title="บทวิเคราะห์ ${_escHtml(r.broker || '')}"></iframe>
      <a class="rr-item-open" href="${pdf}" target="_blank" rel="noopener noreferrer">เปิดฉบับเต็มในแท็บใหม่ ↗</a>
    </div>`;
  }).join('');
}

function _renderBandResult(data, seq) {
  document.getElementById('band-result').style.display = 'block';
  document.getElementById('band-sym-title').textContent = data.symbol;
  _loadBandSetCheck(data.symbol, data.pe?.current, data.pbv?.current, seq);
  const cacheTag = document.getElementById('band-cache-tag');
  if (data.cached_at) {
    cacheTag.textContent = `cache ${data.cached_at}`;
    cacheTag.style.display = 'inline';
  } else {
    cacheTag.style.display = 'none';
  }
  ['pe','pbv'].forEach(type => {
    const d   = data[type];
    const card = document.getElementById(`band-${type}-card`);
    if (!d) { card.style.display = 'none'; return; }
    card.style.display = 'block';
    const zone = _bandZone(d.current, d);
    const fmtN = v => v != null ? v : '—';
    document.getElementById(`band-${type}-metrics`).innerHTML = `
      <div class="band-metric"><div class="band-metric-val" style="color:${zone.color}">${fmtN(d.current)}</div><div class="band-metric-lbl">ปัจจุบัน</div></div>
      <div class="band-metric"><div class="band-metric-val" style="color:#22c55e">${fmtN(d.m2sd)}</div><div class="band-metric-lbl">-2SD</div></div>
      <div class="band-metric"><div class="band-metric-val" style="color:#86efac">${fmtN(d.m1sd)}</div><div class="band-metric-lbl">-1SD</div></div>
      <div class="band-metric"><div class="band-metric-val" style="color:#94a3b8">${fmtN(d.avg)}</div><div class="band-metric-lbl">AVG</div></div>
      <div class="band-metric"><div class="band-metric-val" style="color:#fb923c">${fmtN(d.p1sd)}</div><div class="band-metric-lbl">+1SD</div></div>
      <div class="band-metric"><div class="band-metric-val" style="color:#f87171">${fmtN(d.p2sd)}</div><div class="band-metric-lbl">+2SD</div></div>
      <div class="band-zone-badge" style="color:${zone.color};border:1px solid ${zone.color}30">${zone.label}</div>
    `;
    requestAnimationFrame(() => _drawBandChart(`band-${type}-canvas`, d));
  });
}

// เส้นตรวจสอบ PE/PBV ทางการจาก SET.or.th (~6 เดือนล่าสุด, ดู
// PLAN_set_api_expansion.txt งาน #4) — เทียบกับค่า "ปัจจุบัน" ที่ mrlikestock.com ให้
// ในการ์ด Band ด้านบน ไม่ใช่แทนที่ pipeline หลัก (SET ให้ย้อนหลังแค่ ~6 เดือน band
// ต้องใช้หลายปี) ถ้าห่างกันมาก = แหล่งใดแหล่งหนึ่งอาจเพี้ยน ควรเช็ค
async function _loadBandSetCheck(sym, mrPe, mrPbv, seq) {
  const box = document.getElementById('band-set-check');
  if (!box) return;
  box.innerHTML = '';
  try {
    const r = await _fetchTimeout(`/api/set-valuation-check/${encodeURIComponent(sym)}`, 15000);
    // guard race เหมือน bandTask/npTask/rrTask — ผลของหุ้นเก่าที่มาช้าต้องไม่ทับการ์ด
    // ตรวจสอบของหุ้นที่ผู้ใช้เพิ่งค้นล่าสุด (seq มาจาก _bandReqSeq ตอนเริ่ม request)
    if (seq != null && seq !== _bandReqSeq) return;
    const d = await r.json();
    if (seq != null && seq !== _bandReqSeq) return;
    if (d.error) return;   // เงียบๆ พอ — เป็นแค่เส้นตรวจสอบเสริม ไม่ควรบัง error ทับการ์ดหลัก
    const diffRow = (label, mr, set) => {
      if (mr == null || set == null) return '';
      const diffPct = mr !== 0 ? Math.abs((set - mr) / mr * 100) : 0;
      const clr = diffPct >= 15 ? 'var(--red)' : diffPct >= 5 ? '#e8a33d' : 'var(--green)';
      return `<div style="display:flex;gap:10px;align-items:center;font-size:12px">
        <span style="min-width:36px;color:var(--text2)">${label}</span>
        <span>mrlikestock <b>${mr}</b></span>
        <span style="color:var(--text2)">vs</span>
        <span>SET.or.th <b>${set}</b></span>
        <span style="color:${clr};font-weight:600">ต่างกัน ${diffPct.toFixed(1)}%</span>
      </div>`;
    };
    const rows = diffRow('PE', mrPe, d.pe?.current) + diffRow('PBV', mrPbv, d.pbv?.current);
    if (!rows) return;
    // งาน #4B: dashboard สะสม PE/PBV รายวันทางการเองทุก Quick Update — ถ้าสะสมเกิน 6 เดือนที่
    // SET ให้ย้อนหลัง (d.accumulated) โชว์ช่วง avg/min/max จากประวัติสะสมเป็นแถบเทียบเพิ่ม
    const acc = d.accumulated;
    const rangeRow = (label, s) => {
      if (!s || s.avg == null) return '';
      return `<div style="display:flex;gap:8px;font-size:11px;color:var(--text2)">
        <span style="min-width:36px">${label}</span>
        <span>เฉลี่ย <b style="color:var(--text)">${s.avg}</b></span>
        <span>ต่ำสุด ${s.min}</span><span>สูงสุด ${s.max}</span></div>`;
    };
    const accBlock = acc ? `
      <div style="border-top:1px solid var(--border);margin-top:8px;padding-top:6px">
        <div style="font-size:11px;font-weight:600;margin-bottom:3px">📈 ช่วงจากประวัติทางการที่สะสมไว้ (${acc.count_days} วันทำการ · ${acc.date_from}–${acc.date_to})</div>
        ${rangeRow('PE', d.pe)}${rangeRow('PBV', d.pbv)}
      </div>` : '';
    const depthNote = acc
      ? `สะสมทางการแล้ว ${acc.count_days} วันทำการ (${acc.date_from} ถึง ${acc.date_to}) — โตขึ้นทุกวันผ่าน Quick Update`
      : `SET ให้ย้อนหลังแค่ ~${d.live_count_days || d.count_days} วันทำการ (~6 เดือน) · dashboard เริ่มสะสมเองแล้ว จะยาวขึ้นเรื่อย ๆ`;
    box.innerHTML = `<div class="card" style="padding:12px 16px">
      <div style="font-size:12px;font-weight:700;margin-bottom:8px">🔍 เส้นตรวจสอบจาก SET.or.th ทางการ
        <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:280px">
          <strong>PE/PBV ทางการจาก SET.or.th</strong><br>
          ตัวเลขเดียวกับที่ SET เผยแพร่บนหน้าหุ้นแต่ละตัว<hr>
          ใช้เป็น <b>เส้นตรวจสอบ</b> ไม่ใช่แทนที่ band ด้านบน — SET endpoint ให้ย้อนหลังสดแค่ ~6 เดือน<br>
          dashboard เก็บสะสมเองทุก Quick Update (pattern เดียวกับ SET P&amp;L รายไตรมาส) → ประวัติทางการจะยาวขึ้นเรื่อย ๆ<br>
          <span style="color:var(--text2)">ถ้า current ต่างกันมาก (≥15%) = แหล่งใดแหล่งหนึ่งอาจเพี้ยน ควรเช็ค (เช่น mrlikestock ขูดพลาด/ค้าง)</span>
        </div></span>
      </div>
      <div style="display:flex;flex-direction:column;gap:4px">${rows}</div>
      ${accBlock}
      <div style="font-size:10px;color:var(--text2);margin-top:6px">${depthNote}</div>
    </div>`;
  } catch (e) { /* เงียบๆ — ข้อมูลเสริม ไม่กระทบการใช้งานหลัก */ }
}

function _renderNpResult(data) {
  document.getElementById('np-body').style.display = 'block';
  document.getElementById('np-company-name').textContent =
    data.company_name ? `${data.symbol} — ${data.company_name}` : data.symbol;
  document.getElementById('np-chips').innerHTML =
    (data.chips || []).map(c => `<span class="np-chip">${_escHtml(c)}</span>`).join('');

  const fmt = v => v != null && v !== '' ? _escHtml(v) : '—';
  document.getElementById('np-metrics').innerHTML = `
    <div class="band-metric"><div class="band-metric-val">${fmt(data.market_cap)}</div><div class="band-metric-lbl">มูลค่าตลาด</div></div>
    <div class="band-metric"><div class="band-metric-val">${fmt(data.pe)}</div><div class="band-metric-lbl">P/E</div></div>
    <div class="band-metric"><div class="band-metric-val">${fmt(data.pbv)}</div><div class="band-metric-lbl">P/BV</div></div>
    <div class="band-metric"><div class="band-metric-val">${fmt(data.div_yield)}</div><div class="band-metric-lbl">Dividend Yield</div></div>
  `;

  const deltaColor = v => {
    if (!v) return 'var(--text)';
    if (v.includes('▲')) return '#3fb950';
    if (v.includes('▼')) return '#f85149';
    return 'var(--text)';
  };
  const yoy = data.yoy || {}, qoq = data.qoq || {};
  document.getElementById('np-delta-row').innerHTML = `
    <div class="band-metric"><div class="band-metric-val">${fmt(data.latest_val)}</div><div class="band-metric-lbl">${fmt(data.latest_label)}</div></div>
    <div class="band-metric"><div class="band-metric-val" style="color:${deltaColor(yoy.value)}">${fmt(yoy.value)}</div><div class="band-metric-lbl">YoY${yoy.sub ? ` (${_escHtml(yoy.sub)})` : ''}</div></div>
    <div class="band-metric"><div class="band-metric-val" style="color:${deltaColor(qoq.value)}">${fmt(qoq.value)}</div><div class="band-metric-lbl">QoQ${qoq.sub ? ` (${_escHtml(qoq.sub)})` : ''}</div></div>
  `;

  const fmtCell = cell => {
    if (!cell || cell.val == null) return '<td class="np-empty">—</td>';
    const eps = cell.eps ? `<div class="np-eps">[${_escHtml(cell.eps)}]</div>` : '';
    return `<td>${_escHtml(cell.val)}${eps}</td>`;
  };
  const rows = (data.table || []).map(r =>
    `<tr><td>${_escHtml(r.year)}</td>${fmtCell(r.q1)}${fmtCell(r.q2)}${fmtCell(r.q3)}${fmtCell(r.q4)}${fmtCell(r.total)}</tr>`
  ).join('');
  document.getElementById('np-table').innerHTML = `
    <thead><tr><th>ปี</th><th>Q1</th><th>Q2</th><th>Q3</th><th>Q4</th><th>รวม</th></tr></thead>
    <tbody>${rows}</tbody>
  `;

  // ตาราง TTM ไล่ตามเวลา — 4 ไตรมาสต่อเนื่องจริง (ไม่ใช่ปีปฏิทิน) เทียบ stage เดียวกัน YoY
  const seq      = data.table_seq;
  const seqEl    = document.getElementById('np-table-seq');
  const ttmSumEl = document.getElementById('np-ttm-summary');
  const discEl   = document.getElementById('np-disclaimer');
  if (seq && seq.rows && seq.rows.length) {
    const qo = seq.quarter_order || [];
    const seqCell = c => {
      if (!c || c.val == null) return '<td class="np-empty">—</td>';
      const eps = c.eps ? `<div class="np-eps">[${_escHtml(c.eps)}]</div>` : '';
      const yy  = c.yoy ? `<div class="np-eps" style="color:${deltaColor(c.yoy)}">${_escHtml(c.yoy)}</div>` : '';
      return `<td>${_escHtml(c.val)}${eps}${yy}</td>`;
    };
    const seqRows = seq.rows.map(r => {
      const qmap = {};
      (r.quarters || []).forEach(qc => { qmap[qc.q] = qc; });
      const qtds = qo.map(q => seqCell(qmap[q])).join('');
      const t = r.total || {};
      const tEps = t.eps ? `<div class="np-eps">[${_escHtml(t.eps)}]</div>` : '';
      const tYoy = t.yoy ? `<div class="np-eps" style="color:${deltaColor(t.yoy)}">${_escHtml(t.yoy)}</div>` : '';
      const tCell = t.val == null ? '<td class="np-empty">—</td>'
        : `<td style="font-weight:700;background:rgba(88,166,255,0.10)">${_escHtml(t.val)}${tEps}${tYoy}</td>`;
      return `<tr><td>${_escHtml(r.year)}</td>${qtds}${tCell}</tr>`;
    }).join('');
    seqEl.innerHTML = `
      <thead><tr><th>ปี</th>${qo.map(q => `<th>${_escHtml(q)}</th>`).join('')}<th>TTM</th></tr></thead>
      <tbody>${seqRows}</tbody>
    `;
    seqEl.parentElement.style.display = '';

    const ttm = data.ttm;
    ttmSumEl.innerHTML = `
      <div style="font-size:12px;font-weight:600;margin-bottom:6px">
        📊 TTM &amp; กำไรสุทธิไล่ตามเวลา — ผลรวม 4 ไตรมาสต่อเนื่องกันจริง${ttm && ttm.period_label ? ` ณ ${_escHtml(ttm.period_label)}` : ''}
      </div>` + ((ttm && ttm.value != null) ? `
      <div class="band-metrics-row">
        <div class="band-metric"><div class="band-metric-val">${_escHtml(ttm.value)}</div><div class="band-metric-lbl">TTM ล่าสุด${ttm.eps ? ` · EPS ${_escHtml(ttm.eps)}` : ''}</div></div>
        <div class="band-metric"><div class="band-metric-val" style="color:${deltaColor(ttm.yoy)}">${ttm.yoy ? _escHtml(ttm.yoy) : '—'}</div><div class="band-metric-lbl">YoY เทียบ stage เดียวกันปีก่อน</div></div>
      </div>` : '');
  } else {
    if (seqEl)    { seqEl.innerHTML = ''; seqEl.parentElement.style.display = 'none'; }
    if (ttmSumEl) ttmSumEl.innerHTML = '';
  }
  if (discEl) discEl.textContent = data.disclaimer || '';

  requestAnimationFrame(() => _drawNpChart('np-chart-canvas', data.chart));
}

// ไล่สีเทา→ฟ้าเข้มขึ้นเรื่อยๆ ตามปี ปีล่าสุด (คอลัมน์ขวาสุด) เน้นส้ม — จำลองพาเลตต์
// กราฟต้นฉบับของ 9hoon.com (เทา/ฟ้าอ่อน/ฟ้า/ฟ้าเข้ม/กรมท่า/ส้ม)
function _npYearColors(n) {
  const blues = ['#8b949e', '#a9c7e8', '#7fb2e5', '#4f8fdb', '#2f6fc4', '#1d4f96'];
  const colors = [];
  for (let i = 0; i < n; i++) {
    colors.push(i === n - 1 ? '#f0883e' : blues[Math.min(i, blues.length - 1)]);
  }
  return colors;
}

function _drawNpChart(canvasId, chart) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const years = (chart && chart.years) || [];
  const groups = (chart && chart.quarters) || [];
  if (!years.length || !groups.length) { canvas.style.display = 'none'; return; }
  canvas.style.display = 'block';

  const dpr = window.devicePixelRatio || 1;
  const W   = Math.min(canvas.parentElement.clientWidth || 680, 900);
  const H   = 260;
  canvas.width  = W * dpr; canvas.height = H * dpr;
  canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  const PAD = { top: 14, right: 12, bottom: 46, left: 56 };
  const PW  = W - PAD.left - PAD.right;
  const PH  = H - PAD.top  - PAD.bottom;

  ctx.fillStyle = '#0d1117';
  ctx.fillRect(0, 0, W, H);

  const allVals = groups.flatMap(g => g.vals).filter(v => v != null);
  if (!allVals.length) return;
  const maxV  = Math.max(...allVals, 0) * 1.12 || 1;
  const minV  = Math.min(0, ...allVals);
  const toY   = v => PAD.top + (1 - (v - minV) / (maxV - minV)) * PH;
  const fmtV  = v => Math.round(v).toLocaleString('en-US');

  // Grid + Y labels
  ctx.setLineDash([2,4]); ctx.lineWidth = 0.5; ctx.strokeStyle = 'rgba(48,54,61,0.8)';
  [0, 0.25, 0.5, 0.75, 1].forEach(t => {
    const y = PAD.top + t * PH;
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + PW, y); ctx.stroke();
    const v = maxV - t * (maxV - minV);
    ctx.fillStyle = '#8b949e'; ctx.font = '9px Segoe UI,sans-serif'; ctx.textAlign = 'right';
    ctx.fillText(fmtV(v), PAD.left - 5, y + 3);
  });
  ctx.setLineDash([]);

  const n       = years.length;
  const groupW  = PW / groups.length;
  const barGap  = 2;
  const barW    = Math.max(2, (groupW - 8) / n - barGap);
  const colors  = _npYearColors(n);
  const zeroY   = toY(0);

  groups.forEach((g, gi) => {
    const gx0 = PAD.left + gi * groupW + 4;
    years.forEach((yr, yi) => {
      const v = g.vals[yi];
      if (v == null) return;
      const x = gx0 + yi * (barW + barGap);
      const y = toY(v);
      ctx.fillStyle = colors[yi];
      ctx.fillRect(x, Math.min(y, zeroY), barW, Math.max(Math.abs(zeroY - y), 1));
    });
    ctx.fillStyle = '#8b949e'; ctx.font = '11px Segoe UI,sans-serif'; ctx.textAlign = 'center';
    ctx.fillText(g.q, gx0 + (groupW - 8) / 2, H - PAD.bottom + 16);
  });

  // Legend
  ctx.font = '10px Segoe UI,sans-serif';
  let lx = PAD.left;
  const ly = H - 12;
  years.forEach((yr, i) => {
    ctx.fillStyle = colors[i];
    ctx.fillRect(lx, ly - 8, 10, 9);
    ctx.fillStyle = '#ccc'; ctx.textAlign = 'left';
    ctx.fillText(yr, lx + 13, ly);
    lx += 13 + ctx.measureText(yr).width + 14;
  });
}

function _drawBandChart(canvasId, d) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const history = (d.history || []).filter(r => r.val != null);
  if (!history.length) return;

  const dpr = window.devicePixelRatio || 1;
  const W   = canvas.offsetWidth || 600;
  const H   = 260;
  canvas.width  = W * dpr;
  canvas.height = H * dpr;
  canvas.style.height = H + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  const PAD = { top:16, right:96, bottom:34, left:44 };
  const cW  = W - PAD.left - PAD.right;
  const cH  = H - PAD.top  - PAD.bottom;

  const vals = history.map(r => r.val);
  const rawMin = Math.min(...vals, d.m2sd, d.current ?? Infinity);
  const rawMax = Math.max(...vals, d.p2sd, d.current ?? -Infinity);
  const pad    = (rawMax - rawMin) * 0.08;
  const minV   = rawMin - pad;
  const maxV   = rawMax + pad;
  const range  = maxV - minV;

  const toX = i => PAD.left + (i / Math.max(history.length - 1, 1)) * cW;
  const toY = v => PAD.top  + cH - ((v - minV) / range) * cH;

  // Zone fills
  const zoneFills = [
    [minV,    d.m2sd, 'rgba(34,197,94,0.13)'],
    [d.m2sd,  d.m1sd, 'rgba(134,239,172,0.09)'],
    [d.m1sd,  d.avg,  'rgba(250,204,21,0.07)'],
    [d.avg,   d.p1sd, 'rgba(251,146,60,0.09)'],
    [d.p1sd,  d.p2sd, 'rgba(248,113,113,0.12)'],
    [d.p2sd,  maxV,   'rgba(239,68,68,0.17)'],
  ];
  zoneFills.forEach(([lo, hi, color]) => {
    const y1 = toY(Math.min(hi, maxV));
    const y2 = toY(Math.max(lo, minV));
    if (y2 > y1) { ctx.fillStyle = color; ctx.fillRect(PAD.left, y1, cW, y2 - y1); }
  });

  // SD dashed lines
  const sdLines = [
    [d.m2sd, `-2SD  ${d.m2sd}`, '#22c55e'],
    [d.m1sd, `-1SD  ${d.m1sd}`, '#86efac'],
    [d.avg,  `AVG  ${d.avg}`,   '#94a3b8'],
    [d.p1sd, `+1SD  ${d.p1sd}`, '#fb923c'],
    [d.p2sd, `+2SD  ${d.p2sd}`, '#f87171'],
  ];
  ctx.font = '10px sans-serif';
  sdLines.forEach(([val, label, color]) => {
    if (val < minV || val > maxV) return;
    const y = toY(val);
    ctx.setLineDash([4,4]); ctx.lineWidth = 1; ctx.strokeStyle = color;
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + cW, y); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = color; ctx.textAlign = 'left';
    ctx.fillText(label, PAD.left + cW + 4, y + 4);
  });

  // Current value highlight line
  if (d.current != null && d.current >= minV && d.current <= maxV) {
    const zone = _bandZone(d.current, d);
    const y = toY(d.current);
    ctx.setLineDash([]); ctx.lineWidth = 1.5; ctx.strokeStyle = zone.color + 'cc';
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + cW, y); ctx.stroke();
  }

  // Historical value line
  ctx.setLineDash([]); ctx.lineWidth = 2; ctx.strokeStyle = '#60a5fa'; ctx.lineJoin = 'round';
  ctx.beginPath();
  history.forEach((r, i) => {
    const x = toX(i), y = toY(r.val);
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.stroke();

  // X axis labels (every Jan / Jul)
  ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
  history.forEach((r, i) => {
    if (!r.month) return;
    const m = r.month.split('/')[0];
    if (m === '01' || m === '07') ctx.fillText(r.month, toX(i), H - PAD.bottom + 13);
  });

  // Y axis labels
  ctx.textAlign = 'right'; ctx.fillStyle = '#64748b';
  for (let i = 0; i <= 4; i++) {
    const v = minV + (range / 4) * i;
    ctx.fillText(v.toFixed(1), PAD.left - 4, toY(v) + 4);
  }
}

