// พาไปหน้าต้นทาง — หา nav-btn ที่ onclick อ้างถึง pageId นั้นแล้วสั่ง showPage ให้
// เหมือนกดปุ่มเมนูจริง (ไฮไลท์ nav ถูกต้อง) ใช้แพทเทิร์นเดียวกับ goToFinUpdate()
function _dhGoto(pageId) {
  const btn = [...document.querySelectorAll('.nav-btn')].find(b => b.getAttribute('onclick')?.includes(`'${pageId}'`));
  showPage(pageId, btn);
}

let _dhActBtnSeq = 0;
function _dhRunAction(fnName, btn) {
  const fn = window[fnName];
  if (typeof fn !== 'function') return;
  // เดิมเรียก fn() เฉยๆ ไม่ส่ง btnId เลย — ฟังก์ชันปลายทางหลายตัว (startUSIndexSync/
  // startHedgeRefresh/startFinancialsSync/startDRDescriptionSync ฯลฯ) รับ btnId เป็น optional
  // param ที่ default ไปที่ id ปุ่มบนหน้า "บ้าน" ของมันเอง (เช่น us-idx-sync-btn บนหน้างบการเงิน)
  // ถ้าไม่ได้สลับไปหน้านั้นจริง element ปลายทางจะซ่อนอยู่ มองไม่เห็นการเปลี่ยนแปลงเลย — ส่ง id
  // ของปุ่มที่กดจริงในตาราง Data Health เข้าไปแทนเสมอ (code review 2026-09-02)
  if (btn && !btn.id) btn.id = `dh-act-btn-${++_dhActBtnSeq}`;
  // ให้ feedback ทันทีที่จุดที่กดเสมอ ไม่ว่าฟังก์ชันปลายทางจะรองรับ btnId ด้านบนหรือมี progress
  // overlay กลางของตัวเองหรือไม่ — เคสที่แย่สุด (เช่น refreshMarketStats ของหน้า Valuation ไม่รับ
  // btnId เลยและไม่มี overlay กลาง เขียนสถานะไปที่ element บนหน้า Valuation ที่ซ่อนอยู่ล้วนๆ) กด
  // แล้วไม่มีอะไรเกิดขึ้นให้เห็นบนหน้า Data Health เลย — ล้างเองใน 2 วิถ้าไม่มีใครมาเขียนทับก่อน
  // (ฟังก์ชันที่รับ btnId จริงจะเขียนทับข้อความนี้เกือบทันทีตอน _startJob เริ่มงานอยู่แล้ว)
  if (btn) {
    const orig = btn.textContent;
    btn.disabled = true;
    btn.textContent = '...';
    setTimeout(() => {
      if (btn.textContent === '...') { btn.disabled = false; btn.textContent = orig; }
    }, 2000);
  }
  fn(btn ? btn.id : undefined);
}

// เช็ค drift ดัชนี US/HK/JP ตรงๆ ในหน้า Data Health (ไม่ต้องเด้งไปหน้างบการเงิน) — ยิง endpoint
// เดียวกับ checkUSIndexUpdates/HK/JP (หน้างบการเงิน แท็บต่างประเทศ (DR)) แต่เขียนผลลง container
// ของตัวเองที่อยู่ใต้ปุ่มในตาราง Data Health โดยตรง เดิมปุ่มนี้เรียก checkUSIndexUpdates ฯลฯ ตรงๆ
// ซึ่งเขียนผลลง DOM id คงที่ในหน้างบการเงิน (เช่น us-idx-diff-result) — ถ้าไม่ได้สลับไปหน้านั้น
// element ปลายทางจะซ่อนอยู่ (display:none) ทำให้ดูเหมือนกดแล้วไม่ทำงาน หน้างบการเงินเองยังมีปุ่ม
// เดิม (checkUSIndexUpdates ฯลฯ) ใช้งานได้ตามปกติ ไม่ได้แตะ
const _DH_DRIFT_CFG = {
  US: { endpoint: '/api/us-index-check-updates', keys: ['SP500', 'DOW', 'NDX'], labels: FIN_IDX_LABEL },
  HK: { endpoint: '/api/hk-index-check-updates', keys: ['HSI', 'HSCEI', 'HSTECH'], labels: FIN_HK_IDX_LABEL },
  JP: { endpoint: '/api/jp-index-check-updates', keys: ['NIKKEI225'], labels: FIN_JP_IDX_LABEL },
};
// boxId: ระบุเมื่อผู้เรียกมี container ของตัวเอง — ปุ่มชุดนี้มี 2 ที่ในหน้า Data Health
// (แถวในตารางสถานะ + การ์ด "🔍 เช็คหุ้นเข้าใหม่/ถูกถอด" ล่างสุด) ถ้าใช้ id เดียวกันทั้งคู่จะกลาย
// เป็น duplicate id — getElementById คืนตัวแรกเสมอ กดปุ่มในการ์ดล่างแล้วผลไปโผล่ในตารางบนแทน
async function _dhCheckIndexDrift(market, btn, boxId) {
  const cfg = _DH_DRIFT_CFG[market];
  if (!cfg) return;
  const box = document.getElementById(boxId || `dh-drift-result-${market.toLowerCase()}`);
  if (btn) btn.disabled = true;
  if (box) { box.style.display = 'block'; box.innerHTML = '<span style="color:var(--text2)">กำลังเช็คกับ Wikipedia...</span>'; }
  try {
    const r = await _fetchTimeout(cfg.endpoint, 30000);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    if (box) _renderIndexDiff(box.id, cfg.keys, cfg.labels, d);
  } catch (e) {
    if (box) box.innerHTML = `<span style="color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</span>`;
  } finally {
    if (btn) btn.disabled = false;
  }
}

// checkSetUniverseUpdates เขียนผลลง DOM ของการ์ด "🔍 เช็คหุ้นเข้าใหม่/ถูกถอด" ที่อยู่คนละ
// การ์ดกับตารางสถานะด้านบน (อยู่หน้าเดียวกันแต่ไกลกัน) — ปุ่มในแถวตารางเองไม่มี id เลย
// ไม่มีการเปลี่ยนแปลงให้เห็นตรงจุดที่กด ถ้าผู้ใช้ไม่เลื่อนจอลงไปดูจะดูเหมือน "กดแล้วไม่ทำงาน"
// ทั้งที่ backend สำเร็จจริง — scroll ไปหาการ์ดปลายทางก่อนค่อยรันเช็ค
const _DH_LOCAL_SCROLL_TARGET = { checkSetUniverseUpdates: 'dh-th-diff-btn' };
function _dhRunLocalCheck(fnName) {
  const id = _DH_LOCAL_SCROLL_TARGET[fnName];
  const el = id && document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  const fn = window[fnName];
  if (typeof fn === 'function') fn();
}

// ปุ่ม filter-btn ขนาดเล็กใน source cell — เดิมพิมพ์ style/class ซ้ำ 5 จุดใน _dhSourceCell
// (code review 2026-09-02 กลุ่ม B4) รวมเป็น helper เดียว
function _dhBtn(label, onclick) {
  return `<button class="filter-btn" style="font-size:10.5px;padding:2px 8px" onclick="${onclick}">${label}</button>`;
}

function _dhSourceCell(key) {
  const src = DH_SOURCE_MAP[key];
  if (!src) return '—';
  const btns = [];
  if (src.driftMarket) {
    btns.push(_dhBtn(src.fnLabel || 'เช็ค', `_dhCheckIndexDrift('${src.driftMarket}', this)`));
  } else if (src.fn) {
    // _dhRunLocalCheck ไม่รับ btn (จัดการ element จริงของมันเองผ่าน scroll แล้ว) ส่วน
    // _dhRunAction ต้องรับ `this` เพื่อรู้ว่าปุ่มไหนถูกกดจริง (ดูคอมเมนต์ใน _dhRunAction)
    const call = _DH_LOCAL_SCROLL_TARGET[src.fn] ? `_dhRunLocalCheck('${src.fn}')` : `_dhRunAction('${src.fn}', this)`;
    btns.push(_dhBtn(src.fnLabel || 'อัพเดท', call));
  }
  if (src.gotoPage) btns.push(_dhBtn(src.gotoLabel || 'ไปหน้านั้น', `_dhGoto('${src.gotoPage}')`));
  // fn2/gotoPage2: ใช้กับ key ที่มีมากกว่า 1 หน้า/ปุ่มเขียนลงไฟล์เดียวกัน (เช่น financials.db
  // ที่ทั้งหน้า "งบการเงิน" และปุ่มงบ DR ในหน้า DR/DRx ต่างก็เขียนทับ)
  if (src.fn2) btns.push(_dhBtn(src.fnLabel2 || 'อัพเดท', `_dhRunAction('${src.fn2}', this)`));
  if (src.gotoPage2) btns.push(_dhBtn(src.gotoLabel2 || 'ไปหน้านั้น', `_dhGoto('${src.gotoPage2}')`));
  const btnRow = btns.length ? `<div style="margin-top:4px;display:flex;gap:6px;flex-wrap:wrap">${btns.join('')}</div>` : '';
  const resultBox = src.driftMarket ? `<div id="dh-drift-result-${src.driftMarket.toLowerCase()}" style="display:none;margin-top:6px;font-size:11px"></div>` : '';
  return `<span>${src.text}</span>${btnRow}${resultBox}`;
}

function _dhAgeText(item) {
  if (item.age_hours == null) {
    return item.last_at ? item.last_at : '—';
  }
  const h = item.age_hours;
  if (h < 1) return `${Math.round(h * 60)} นาทีก่อน`;
  if (h < 48) return `${h.toFixed(1)} ชม.ก่อน`;
  return `${(h / 24).toFixed(1)} วันก่อน`;
}

async function loadDataHealth(fresh) {
  if (IS_STATIC) return;
  const wrap = document.getElementById('dh-table-wrap');
  const summaryEl = document.getElementById('dh-summary');
  const checkedEl = document.getElementById('dh-checked-at');
  wrap.innerHTML = '<div class="empty" style="padding:16px">กำลังเช็ค...</div>';
  loadFinUpdateAllStatus();
  // ยิงพร้อมกับ fetch หลักด้านล่างเลย (ไม่รอ) — ไม่มีตัวไหนอ่านผลจาก /api/data-health เอง
  // (code review 2026-09-02: เดิมเรียกหลัง try{...} จบแล้ว ทำให้ 4 คำขอนี้เรียงกันซีเรียล)
  loadBackupFilesStatus();
  loadLastRuns();
  loadUpdateHistory();
  try {
    // ปุ่ม "🔄 เช็คใหม่" ส่ง fresh=true เพื่อข้าม cache 5 นาทีฝั่ง backend จริง (เดิม route มีคอมเมนต์
    // ว่าปุ่มนี้ใช้ ?fresh=1 ได้ แต่ฝั่งนี้ไม่เคยส่งจริง กดเช็คใหม่/รีเฟรชหลัง sync เสร็จเลยยังเห็น
    // ค่าเดิมค้างได้ถึง 5 นาที — code review 2026-09-02) ใช้ _fetchTimeout ตาม pattern endpoint อื่น
    // ที่มี live fallback (fetch_ipo_recently ยิงสดถ้า cache ว่าง)
    const r = await _fetchTimeout(`/api/data-health${fresh ? '?fresh=1' : ''}`, 30000);
    const d = await r.json();
    _dhApplyBadge(d);
    checkedEl.textContent = `เช็คล่าสุด: ${d.checked_at}`;
    summaryEl.innerHTML = `<span style="color:var(--green)">🟢 ${d.summary.ok}</span> · ` +
      `<span style="color:var(--yellow)">🟡 ${d.summary.warn}</span> · ` +
      `<span style="color:var(--red)">🔴 ${d.summary.red}</span>` +
      (d.summary.na ? ` · <span style="color:var(--text2)">⚪ ${d.summary.na}</span>` : '');

    // จัดกลุ่มตาม category ให้อ่านง่าย
    const byCategory = {};
    d.items.forEach(it => {
      (byCategory[it.category] = byCategory[it.category] || []).push(it);
    });
    wrap.innerHTML = Object.entries(byCategory).map(([cat, items]) => `
      <div class="card" style="padding:14px 16px;margin-bottom:10px">
        <div style="font-size:13px;font-weight:600;margin-bottom:8px">${cat}</div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:640px">
          <thead><tr><th>แหล่งข้อมูล</th><th>สถานะ</th><th>อัพเดทล่าสุด</th><th>มาจากปุ่ม/หน้าไหน</th><th>หมายเหตุ</th></tr></thead>
          <tbody>${items.map(it => `
            <tr>
              <td>${it.label}</td>
              <td style="color:${_DH_STATUS_COLOR[it.status]};font-weight:600;white-space:nowrap">${_DH_STATUS_LABEL[it.status]}</td>
              <td style="font-size:11px;color:var(--text2);white-space:nowrap">${_dhAgeText(it)}</td>
              <td style="font-size:11px;color:var(--text2);min-width:180px">${_dhSourceCell(it.key)}</td>
              <td style="font-size:11px;color:var(--text2)">${it.note || '—'}</td>
            </tr>`).join('')}</tbody>
        </table></div>
      </div>`).join('');
  } catch (e) {
    wrap.innerHTML = `<div class="empty" style="padding:16px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  }
}

// ตาราง "วงจรเงินสด SET vs Yahoo" เต็ม (ไม่ตัด 12 ตัวแรกเหมือนตารางใน note ของ item
// q_cash_cycle_crosscheck) — เปิดจากลิงก์ "และอีก N ตัว" โหลดผ่าน
// /api/data-health/cash-cycle-crosscheck-full แยกต่างหาก ไม่ผูกกับ /api/data-health หลัก
// ที่ถูกเรียกบ่อย (badge เช็คทุกครั้งเปิดแอป) กันยัดตารางเต็ม ~470+ แถวเข้าไปทุกครั้ง
let _dhCcFullRows = null;
// request-seq guard กัน response เก่ามาทับผลใหม่กว่า (code review 2026-09-02) — เดิมไม่มี ถ้าเปิด/
// ปิด/เปิดซ้ำ modal เร็วๆ (หรือ fetch แรกช้าผิดปกติ) response เก่าที่มาทีหลัง response ใหม่จะทับ
// _dhCcFullRows + ตารางด้วยข้อมูลเก่า เหมือน pattern _insReqSeq ของหน้า Insider
let _dhCcReqSeq = 0;
async function _dhShowCashCycleFull() {
  const body = document.getElementById('dh-cc-body');
  if (!body) return;
  const mySeq = ++_dhCcReqSeq;
  body.innerHTML = '<div class="empty" style="padding:16px">กำลังโหลด...</div>';
  document.getElementById('dh-cc-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
  try {
    const r = await _fetchTimeout('/api/data-health/cash-cycle-crosscheck-full', 20000, 'หมดเวลาโหลด (เกิน 20 วิ)');
    const d = await r.json();
    if (mySeq !== _dhCcReqSeq) return;   // มีคำขอใหม่กว่าแซงไปแล้ว — ทิ้ง response นี้
    if (d.error) { body.innerHTML = `<div class="empty" style="color:var(--red)">⚠ ${_escHtml(d.error)}</div>`; return; }
    _dhCcFullRows = d.rows || [];
    body.innerHTML = `
      <div style="font-size:11px;color:var(--text2);margin-bottom:8px">
        ต่างกัน ≥${d.diff_days} วัน ทั้งหมด <b>${_dhCcFullRows.length}</b> ตัว — เรียงจากต่างมากไปน้อย
      </div>
      <input id="dh-cc-search" class="scr-input" placeholder="ค้นหา symbol..." style="width:100%;margin-bottom:8px" oninput="_dhCcFilterRows(this.value)">
      <div id="dh-cc-table-wrap" style="max-height:60vh;overflow-y:auto"></div>`;
    _dhCcRenderRows(_dhCcFullRows);
  } catch (e) {
    if (mySeq !== _dhCcReqSeq) return;
    body.innerHTML = `<div class="empty" style="color:var(--red)">⚠ โหลดไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  }
}

function _dhCcRenderRows(rows) {
  const wrap = document.getElementById('dh-cc-table-wrap');
  if (!wrap) return;
  if (!rows.length) { wrap.innerHTML = '<div class="empty" style="padding:12px">ไม่พบ</div>'; return; }
  wrap.innerHTML = `<table class="tbl" style="width:100%">
    <thead><tr><th>Symbol</th><th class="r">Yahoo</th><th class="r">SET</th><th class="r">Δ วัน</th></tr></thead>
    <tbody>${rows.map(r => `
      <tr>
        <td><b>${_escHtml(r.symbol)}</b></td>
        <td class="r" style="color:var(--text2)">${r.yahoo.toFixed(0)}</td>
        <td class="r" style="color:var(--text2)">${r.set.toFixed(0)}</td>
        <td class="r" style="color:#e8a33d">Δ${r.diff.toFixed(0)}</td>
      </tr>`).join('')}</tbody>
  </table>`;
}

function _dhCcFilterRows(q) {
  if (!_dhCcFullRows) return;
  const needle = (q || '').trim().toUpperCase();
  _dhCcRenderRows(needle ? _dhCcFullRows.filter(r => r.symbol.toUpperCase().includes(needle)) : _dhCcFullRows);
}

function closeDhCashCycleModal() {
  const modal = document.getElementById('dh-cc-modal');
  if (modal) modal.classList.remove('open');
  document.body.style.overflow = '';
}

// กดล่าสุดของ Quick Update / Full Refresh — ใช้ /api/update-status ตัวเดียวกับที่
// checkRunFailures() ใช้ทำ banner แดง (core/run_log.py เขียนตอนจบแต่ละรอบ)
// จัดกลุ่มตาม 3 การ์ดจริงในหน้า Data Health (แถบเมนูบนสุด / การ์ด "อัพเดทราคาดัชนี
// US/HK/JP + Sync Mirror" / การ์ด "อัพเดทงบไตรมาส") ให้เห็นชัดว่าปุ่มไหนอยู่กลุ่มไหน
// กดไปหรือยัง แทนที่จะเป็น list เดียวเรียงปนกันเดาไม่ออกว่าอันไหนคู่กับปุ่มไหน
const _DH_LAST_RUN_GROUPS = [
  { title: '📅 ทุกวันทำการ (แถบเมนูบนสุด)', rows: [
    { key: 'quick_update', label: '⚡ Quick Update' },
    { key: 'full_refresh', label: '⟳ Full Refresh' },
  ]},
  { title: '📈 อัพเดทราคาดัชนี US/HK/JP + Sync Mirror (กดมือเป็นครั้งคราว)', rows: [
    { key: 'us_index_full_refresh', label: '📈 US Index Max' },
    { key: 'hk_index_full_refresh', label: '📈 HK Index Max' },
    { key: 'jp_index_full_refresh', label: '📈 JP Index Max' },
    { key: 'mirror_yahoo_index_sync', label: '🌐 Sync Mirror US/HK เต็ม' },
    { key: 'static_bake', label: '🧱 Bake ไฟล์ static ทั้งหมด' },
  ]},
  { title: '📊 อัพเดทงบไตรมาส / 13F (ก.พ. / พ.ค. / ส.ค. / พ.ย. — หลัง SET 45-day deadline)', rows: [
    { key: 'financials_sync', label: '🔄 อัพเดทงบการเงินทั้งหมด' },
    { key: 'hedge_refresh', label: '🐋 Hedge Holdings (13F — ดีเลย์ ~45 วัน หน้า Hedge Holdings)' },
    { key: 'mirror_finnomena', label: '📥 Mirror ทั้งตลาด (force)' },
    { key: 'mirror_finnomena_normal', label: '📥 Mirror ทั้งตลาด (ปกติ — เฉพาะที่ขาด)' },
    { key: 'build_mirror_names', label: '🏷️ ดึงชื่อหุ้น mirror ใหม่' },
  ]},
  { title: '🧱 run_static_update.py — sub-step (รันบนเครื่องเท่านั้นถึงจะเห็นที่นี่ — บน GitHub Actions ดูที่ Actions log แทน)', rows: [
    { key: 'static_indices_refresh', label: '📊 Indices' },
    { key: 'static_short_sales', label: '📉 Short Sales' },
    { key: 'static_nvdr', label: '📥 NVDR' },
    { key: 'static_sec_sync', label: '🕵️ sec_filings.db sync' },
    { key: 'static_snapshot_optional', label: '📦 Snapshot endpoint เสริม' },
  ]},
];

function _dhLastRunItemHtml(label, v) {
  if (!v) return `<div><b>${label}</b><br><span style="color:var(--text2)">ยังไม่เคยกด</span></div>`;
  const at = new Date(v.at.replace(' ', 'T'));
  const hAgo = (Date.now() - at.getTime()) / 3600000;
  // ใช้ _dhAgeText กลางแทนสำเนากฎ format เดิม (h<1 นาที / h<48 ชม. / อื่นๆ วัน) — เดิม copy-paste
  // ไว้ 2 ที่ ถ้าเกณฑ์เปลี่ยนจุดหนึ่งจะลืมแก้อีกจุด (code review 2026-09-02)
  const ageTxt = _dhAgeText({ age_hours: hAgo });
  const color = !v.ok ? 'var(--red)' : hAgo >= 48 ? 'var(--yellow)' : 'var(--green)';
  const statusIcon = v.ok ? '🟢' : '🔴';
  const msgColor = !v.ok ? 'var(--red)' : 'var(--text2)';
  return `<div><b>${label}</b><br>
    <span style="color:${color};font-weight:600">${statusIcon} ${v.at}</span>
    <span style="color:var(--text2)"> (${ageTxt})</span>
    ${v.message ? `<br><span style="color:${msgColor};font-size:11px">${_escHtml(v.message || '')}</span>` : ''}
  </div>`;
}

async function loadLastRuns() {
  const wrap = document.getElementById('dh-last-runs-wrap');
  if (!wrap) return;
  wrap.innerHTML = '<span style="color:var(--text2)">กำลังเช็ค...</span>';
  try {
    const r = await fetch('/api/update-status');
    const d = await r.json();
    wrap.innerHTML = _DH_LAST_RUN_GROUPS.map(({ title, rows }) => `
      <div style="flex:1 1 100%">
        <div style="font-size:11.5px;font-weight:600;color:var(--text2);margin:${title.startsWith('📅') ? '0' : '10px'} 0 6px">${title}</div>
        <div style="display:flex;gap:24px;flex-wrap:wrap">
          ${rows.map(({ key, label }) => _dhLastRunItemHtml(label, d.all[key])).join('')}
        </div>
      </div>`).join('');
  } catch (e) {
    wrap.innerHTML = `<span style="color:var(--red)">⚠ เช็คไม่สำเร็จ: ${e.message}</span>`;
  }
}

// ประวัติล้มเหลวสะสม (ไม่ใช่แค่รอบล่าสุดแบบ loadLastRuns ด้านบน) — ใช้ดูแนวโน้ม
// "ล้มติดกันกี่รอบ / ล้มตอนไหนบ้าง" อ่านจาก /api/update-history (core/run_log.py
// เก็บ 50 รอบล่าสุด/กลไก ใน logs/update_history.json)
async function loadUpdateHistory() {
  const wrap = document.getElementById('dh-update-history-wrap');
  if (!wrap) return;
  wrap.innerHTML = '<div class="empty" style="padding:12px">กำลังเช็ค...</div>';
  try {
    const r = await fetch('/api/update-history');
    const d = await r.json();
    const fails = d.recent_failures || [];
    if (!fails.length) {
      wrap.innerHTML = '<div class="empty" style="padding:12px;color:var(--green)">🟢 ไม่มีประวัติล้มเหลวใน 50 รอบล่าสุดของแต่ละกลไก</div>';
      return;
    }
    wrap.innerHTML = `<div style="overflow-x:auto"><table class="tbl" style="min-width:640px">
      <thead><tr><th>กลไก</th><th>เวลา</th><th>ข้อความ</th></tr></thead>
      <tbody>${fails.map(f => `
        <tr>
          <td style="white-space:nowrap">${f.label}</td>
          <td style="font-size:11px;color:var(--text2);white-space:nowrap">${f.at}</td>
          <td style="font-size:11px;color:var(--red)">${_escHtml(f.message || '')}</td>
        </tr>`).join('')}</tbody>
      </table></div>`;
  } catch (e) {
    wrap.innerHTML = `<div class="empty" style="padding:12px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  }
}

// ตารางแยกรายไฟล์ — ไฟล์สร้างใหม่ไม่ได้ (financials.db/set_prices.db/sec_filings.db/
// delisted_log.json) แต่ละตัวถูกสำรองนอกเครื่องล่าสุดวันไหน/ขนาดเท่าไหร่/เก็บกี่ชุด
// ต่างจาก item "offsite_backup" ในตารางบน (บอกแค่รวมๆ ว่าสำรองล่าสุดเมื่อไหร่)
async function loadBackupFilesStatus() {
  const wrap = document.getElementById('dh-backup-files-wrap');
  if (!wrap) return;
  wrap.innerHTML = '<div class="empty" style="padding:12px">กำลังเช็ค...</div>';
  try {
    const r = await fetch('/api/backup-files-status');
    const d = await r.json();
    if (!d.files || !d.files.length) {
      wrap.innerHTML = `<div class="empty" style="padding:12px">${d.note || 'ยังไม่มีข้อมูลสำรอง'}</div>`;
      return;
    }
    const destLine = d.dest_dir
      ? `<div style="font-size:11px;color:var(--text2);margin-bottom:8px">ปลายทาง: ${d.dest_dir}</div>` : '';
    wrap.innerHTML = destLine + `
      <div style="overflow-x:auto"><table class="tbl" style="min-width:520px">
        <thead><tr><th>ไฟล์</th><th>สำรองล่าสุด</th><th>ขนาด</th><th>เก็บไว้กี่ชุด</th></tr></thead>
        <tbody>${d.files.map(f => {
          const missing = !f.last_backup_at;
          const color = missing ? 'var(--red)' : (f.age_hours != null && f.age_hours >= 60 * 24 ? 'var(--red)'
                        : (f.age_hours != null && f.age_hours >= 35 * 24 ? 'var(--yellow)' : 'var(--green)'));
          return `
            <tr>
              <td>${f.label}</td>
              <td style="color:${color};font-weight:600;white-space:nowrap">${missing ? '🔴 ไม่พบสำรอง' : _dhAgeText(f)}</td>
              <td style="font-size:11px;color:var(--text2)">${f.size_mb != null ? f.size_mb + ' MB' : '—'}</td>
              <td style="font-size:11px;color:var(--text2)">${f.versions_kept || 0}</td>
            </tr>`;
        }).join('')}</tbody>
      </table></div>`;
  } catch (e) {
    wrap.innerHTML = `<div class="empty" style="padding:12px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  }
}

// เรียกตอนเปิดแอป (เงียบๆ) — แค่เอาไว้เติม badge แดงบนปุ่ม nav ถ้ามีรายการค้าง
// ไม่ render ตารางเต็ม (ตารางเต็มโหลดตอนกดเข้าเมนูเองผ่าน loadDataHealth)
// ใช้ผลจาก /api/data-health ที่ fetch มาแล้ว (เช่นจาก loadDataHealth) เติม badge
// แดงบนปุ่ม nav ได้เลยโดยไม่ต้องยิง fetch ซ้ำ (สถานะรายปุ่มดูที่การ์ด "สถานะ /
// อัพเดทล่าสุด" — loadLastRuns — ที่เดียวพอ ไม่ต้องมี last-run แยกที่นี่ซ้ำ)
function _dhApplyBadge(d) {
  const badge = document.getElementById('dh-nav-badge');
  if (badge) {
    if (d.summary.red > 0) {
      badge.textContent = d.summary.red;
      badge.style.display = 'inline-block';
    } else {
      badge.style.display = 'none';
    }
  }
}

async function checkDataHealthBadge() {
  if (IS_STATIC) return;
  try {
    // /api/data-health มี live fallback ได้ (เช่น fetch_ipo_recently ยิงสดถ้า cache ว่าง) — ต้องมี
    // timeout กัน UI ค้าง (pattern เดียวกับ endpoint network อื่นในไฟล์นี้ ดู pingDataSources,
    // memory frontend-fetch-timeout-pattern, code review 2026-09-02)
    const r = await _fetchTimeout('/api/data-health', 15000);
    const d = await r.json();
    _dhApplyBadge(d);
  } catch (e) { /* เงียบ — ไม่ใช่ฟีเจอร์หลัก */ }
}

// เรียกตอนเปิดหน้า ETF — ผู้ใช้เห็น badge แล้ว เคลียร์ pending_new ฝั่ง backend (ไม่งั้น
// badge จะค้างเตือนตัวเดิมซ้ำไปเรื่อยๆ) + ซ่อน badge ทันทีฝั่ง UI ไม่ต้องรอ response
function _ackEtfNewListings() {
  const badge = document.getElementById('etf-new-badge');
  if (badge) badge.style.display = 'none';
  if (IS_STATIC) return;
  fetch('/api/etf-new-listings/ack', { method: 'POST' }).catch(() => {});
}

// เรียกตอนเปิดแอป — เติม badge สีฟ้าบนปุ่ม nav "ETF ไทย" ถ้ามี ETF จดทะเบียนใหม่ที่
// ยังไม่เคยเห็น (backend เทียบ symbol สดจาก SET กับ known set ทุกรอบ rebuild เอง —
// ดู _check_etf_new_listings ใน app.py) — ไม่ใช่ปัญหาเหมือน Data Health เลยไม่ใช้สีแดง
async function checkEtfNewListingsBadge() {
  if (IS_STATIC) return;
  try {
    const r = await _fetchTimeout('/api/etf-new-listings', 10000);
    const d = await r.json();
    const badge = document.getElementById('etf-new-badge');
    if (!badge) return;
    if (d.count > 0) {
      badge.textContent = d.count;
      badge.title = 'ETF จดทะเบียนใหม่: ' + (d.symbols || []).join(', ');
      badge.style.display = 'inline-block';
    } else {
      badge.style.display = 'none';
    }
  } catch (e) { /* เงียบ — ไม่ใช่ฟีเจอร์หลัก */ }
}

async function pingDataSources() {
  const btn = document.getElementById('dh-ping-btn');
  const box = document.getElementById('dh-ping-result');
  btn.disabled = true;
  btn.textContent = '📡 กำลังปิง...';
  box.style.display = 'block';
  box.innerHTML = '<div class="empty" style="padding:12px">กำลังยิงทดสอบ SET.or.th / Yahoo / Finnomena / TradingView / siamchart...</div>';
  try {
    // ping ยิง 5 แหล่งภายนอกจริง (timeout ฝั่ง server 6-8 วิ/แหล่ง แต่ยิงขนาน) — ห่อ
    // _fetchTimeout กัน UI ค้างถ้า worker ฝั่ง Flask แฮงค์ (pattern เดียวกับ endpoint network อื่น)
    const r = await _fetchTimeout('/api/data-health-ping', 30000, 'หมดเวลารอผลปิง (เกิน 30 วิ) — server อาจค้าง ลองใหม่อีกครั้ง');
    const d = await r.json();
    box.innerHTML = `
      <div class="card" style="padding:12px 14px">
        <div style="font-size:11px;color:var(--text2);margin-bottom:8px">เช็คเมื่อ: ${d.checked_at}</div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:420px">
          <thead><tr><th>แหล่ง</th><th>สถานะ</th><th>เวลาตอบ</th><th>รายละเอียด</th></tr></thead>
          <tbody>${d.results.map(x => `
            <tr>
              <td>${x.label}</td>
              <td style="color:${x.ok ? 'var(--green)' : 'var(--red)'};font-weight:600">${x.ok ? '🟢 ตอบสนอง' : '🔴 ไม่ตอบ'}</td>
              <td style="font-size:11px;color:var(--text2)">${x.ms} ms</td>
              <td style="font-size:11px;color:var(--text2)">${x.error ? _escHtml(x.error) : (x.http_status ? 'HTTP ' + x.http_status : '—')}</td>
            </tr>`).join('')}</tbody>
        </table></div>
      </div>`;
  } catch (e) {
    box.innerHTML = `<div class="empty" style="padding:16px;color:var(--red)">⚠ ปิงไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  } finally {
    btn.disabled = false;
    btn.textContent = '📡 ปิงแหล่งข้อมูลภายนอก';
  }
}

// ============================================================
// เช็คหุ้นเข้าใหม่/ถูกถอด — หุ้นไทย (เทียบ SET.or.th สด) + Mirror US/HK (เทียบ Finnomena สด)
// อยู่ในหน้า Data Health คู่กับตารางความสดของไฟล์ (แนวเดียวกับ checkDRUpdates)
// ============================================================
async function checkSetUniverseUpdates() {
  const btn  = document.getElementById('dh-th-diff-btn');
  const note = document.getElementById('dh-th-diff-note');
  const box  = document.getElementById('dh-th-diff-result');
  btn.disabled = true;
  note.textContent = 'กำลังเช็คกับ SET.or.th...';
  box.style.display = 'none';
  try {
    const r = await _fetchTimeout('/api/set-universe-check-updates', 30000);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    note.textContent = `SET.or.th มี ${d.live_count} ตัว · เครื่องนี้มี ${d.local_count} ตัว` +
      (d.tracked_delisted_count ? ` · บันทึกไว้แล้ว ${d.tracked_delisted_count} ตัว (delisted_log.json — เสริม backtest)` : '');
    box.style.display = 'block';
    const newHtml = d.new.length ? `
      <div style="margin-bottom:8px">
        <div style="font-size:12px;font-weight:600;color:var(--green);margin-bottom:6px">🆕 มีบน SET.or.th แต่ยังไม่มีในเครื่อง (${d.new.length} ตัว)</div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:400px">
          <thead><tr><th>Symbol</th><th>ชื่อ</th><th>ตลาด</th></tr></thead>
          <tbody>${d.new.map(x => `<tr><td><strong>${_escHtml(x.symbol)}</strong></td><td style="font-size:11px;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(x.name)}</td><td style="font-size:11px;color:var(--text2)">${_escHtml(x.market)}</td></tr>`).join('')}</tbody>
        </table></div>
      </div>` : '';
    // removed: {symbol, renamed_to} — renamed_to มาจาก oldSymbols ของ SET (ดู
    // /api/set-universe-check-updates) ถ้าเจอ = เปลี่ยนชื่อย่อ ไม่ใช่เพิกถอน แยกแสดง
    // คนละกลุ่มกัน (ดู PLAN_set_api_expansion.txt งาน #8)
    const renamedRows  = (d.removed || []).filter(x => x.renamed_to);
    const delistedRows = (d.removed || []).filter(x => !x.renamed_to);
    const renamedHtml = renamedRows.length ? `
      <div style="margin-bottom:8px">
        <div style="font-size:12px;font-weight:600;color:#e3b341;margin-bottom:6px">🔄 น่าจะแค่เปลี่ยนชื่อย่อ (${renamedRows.length} ตัว)
          <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:290px">
            <strong>เปลี่ยนชื่อ ≠ เพิกถอน</strong><br>
            หุ้นที่หายจากรายชื่ออาจแค่เปลี่ยนชื่อย่อ (ควบรวม/rebrand) ราคาและงบเก่ายังใช้ได้
            ต้องย้ายไปชื่อใหม่ ไม่ใช่ทิ้ง<hr>
            ระบบเทียบจากรายชื่อทางการของ SET (oldSymbols) ให้แล้ว — <b>ห้ามลบข้อมูลเก่าทิ้ง</b><br>
            <b>วิธีอัปเดต:</b>
            1) กด "📋 คัดลอกคำสั่ง" ในแถวที่ต้องการ<br>
            2) เปิด Command Prompt/PowerShell ที่โฟลเดอร์โปรเจกต์ แล้ววางคำสั่ง (Ctrl+V) กด Enter —
            หรือดับเบิลคลิก <code>rename_symbol.bat</code> ที่ root แล้วพิมพ์ชื่อเดิม/ใหม่ตามที่ถามแทนก็ได้<br>
            3) สคริปต์จะสำรอง <code>set_prices.db</code>/<code>financials.db</code> อัตโนมัติก่อนย้ายข้อมูลเสมอ<br>
            4) เสร็จแล้ว restart แอป (<code>start.bat</code>) แล้วกด ⚡ Quick Update อีกรอบ ให้ RS/EMA/Stage คำนวณใหม่จากประวัติเต็ม
          </div></span>
        </div>
        <div style="overflow-x:auto"><table class="tbl" style="min-width:360px">
          <thead><tr><th>เดิม</th><th></th><th>ชื่อใหม่</th><th>คำสั่ง</th></tr></thead>
          <tbody>${renamedRows.map(x => `<tr>
            <td><strong>${_escHtml(x.symbol)}</strong></td><td style="color:var(--text2)">→</td><td><strong>${_escHtml(x.renamed_to)}</strong></td>
            <td><button class="filter-btn" style="font-size:10.5px;padding:3px 8px" onclick="_dhCopyRenameCmd('${_escJsAttr(x.symbol)}','${_escJsAttr(x.renamed_to)}',this)" title="คัดลอกคำสั่ง rename_symbol.py ไปวางใน terminal — ย้ายราคา/งบ/ปันผลไปชื่อใหม่ให้ต่อเนื่อง">📋 คัดลอกคำสั่ง</button></td>
          </tr>`).join('')}</tbody>
        </table></div>
      </div>` : '';
    const remHtml = delistedRows.length ? `
      <div>
        <div style="font-size:12px;font-weight:600;color:var(--red);margin-bottom:6px">🗑 น่าจะเพิกถอนจริง — ไม่พบชื่อใหม่ (${delistedRows.length} ตัว)</div>
        <div style="font-size:11.5px">${delistedRows.map(x => _escHtml(x.symbol)).join(', ')}</div>
        <div style="font-size:10.5px;color:var(--text2);margin-top:4px">ไม่เจอใน oldSymbols ของ SET — อาจเพิกถอน/ควบรวมหายไปเลย (เช่น BPP→BANPU) ตรวจก่อนสรุปว่าเป็นเพิกถอนจริง (เช่นเช็คข่าว SET.or.th)<br>
          ถ้ายืนยันแล้ว: <code>python mark_delisted.py &lt;symbol&gt; "เหตุผล"</code> — มี .bat ให้ดับเบิลคลิกที่ root โปรเจกต์</div>
      </div>` : '';
    box.innerHTML = (newHtml || renamedHtml || remHtml) ? newHtml + renamedHtml + remHtml
      : '<div class="empty" style="padding:8px">ตรงกับ SET.or.th ทั้งหมด ไม่มีอะไรต้องอัปเดต</div>';
  } catch (e) {
    note.textContent = '';
    box.style.display = 'block';
    box.innerHTML = `<div class="empty" style="padding:16px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  } finally {
    btn.disabled = false;
  }
}

function _dhCopyRenameCmd(oldSym, newSym, btn) {
  const cmd = `python rename_symbol.py ${oldSym} ${newSym}`;
  const orig = btn.textContent;
  const done = () => { btn.textContent = '✓ คัดลอกแล้ว'; setTimeout(() => { btn.textContent = orig; }, 2500); };
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(cmd).then(done).catch(() => _filCopyFallback(cmd, done));
  } else {
    _filCopyFallback(cmd, done);
  }
}

let _dhMirrorNewTotal = 0;

async function checkMirrorUpdates() {
  const btn  = document.getElementById('dh-mirror-diff-btn');
  const note = document.getElementById('dh-mirror-diff-note');
  const box  = document.getElementById('dh-mirror-diff-result');
  const syncBtn = document.getElementById('dh-mirror-sync-btn');
  btn.disabled = true;
  note.textContent = 'กำลังเช็คกับ Finnomena...';
  box.style.display = 'none';
  syncBtn.style.display = 'none';
  try {
    const r = await _fetchTimeout('/api/mirror-check-updates', 30000);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    const totalNew = (d.new_counts.US || 0) + (d.new_counts.HK || 0);
    _dhMirrorNewTotal = totalNew;
    note.textContent = `Finnomena มี US ${d.live_counts.US} / HK ${d.live_counts.HK} ตัว · ` +
      (totalNew ? `พบตัวใหม่ ${totalNew} ตัว` : 'ไม่มีตัวใหม่');
    box.style.display = 'block';
    if (totalNew) {
      box.innerHTML = ['US', 'HK'].filter(ex => d.new_counts[ex]).map(ex => `
        <div style="margin-bottom:6px">
          <div style="font-size:12px;font-weight:600;color:var(--green)">🆕 ${ex} ตัวใหม่ (${d.new_counts[ex]} ตัว)</div>
          <div style="font-size:11.5px;color:var(--text2)">${(d.new_samples[ex] || []).map(_escHtml).join(', ')}${d.new_counts[ex] > (d.new_samples[ex] || []).length ? ', …' : ''}</div>
        </div>`).join('');
      syncBtn.style.display = 'inline-block';
    } else {
      box.innerHTML = '<div class="empty" style="padding:8px">mirror ในเครื่องครบตาม Finnomena แล้ว</div>';
    }
  } catch (e) {
    note.textContent = '';
    box.style.display = 'block';
    box.innerHTML = `<div class="empty" style="padding:16px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${_escHtml(e.message)}</div>`;
  } finally {
    btn.disabled = false;
  }
}

function startMirrorSyncNew() {
  const n = _dhMirrorNewTotal || 0;
  if (!confirm(`ดึงงบ Finnomena ของหุ้น mirror US/HK ตัวใหม่ที่เจอ (${n} ตัว)?\n\nเวลาที่ใช้ขึ้นกับจำนวนตัวใหม่ (มากอาจกินเวลาหลายนาทีถึงเป็นชั่วโมง) — ปิดแท็บ/ปิดคอมได้ระหว่างรัน`)) return;
  _startJob('/api/mirror-sync-new', 'dh-mirror-sync-btn', '📥 ดึงเฉพาะตัวใหม่ (local)', null, () => {
    document.getElementById('dh-mirror-diff-note').textContent = '';
    document.getElementById('dh-mirror-diff-result').style.display = 'none';
    document.getElementById('dh-mirror-sync-btn').style.display = 'none';
    loadDataHealth(true);   // ข้าม cache 5 นาที — sync เพิ่งเสร็จ ต้องเห็นผลใหม่ทันที ไม่ใช่ค่าค้าง
  });
}

async function checkDRUpdates() {
  const btn  = document.getElementById('dr-diff-btn');
  const note = document.getElementById('dr-diff-note');
  const box  = document.getElementById('dr-diff-result');
  btn.disabled = true;
  note.textContent = 'กำลังเช็คกับ SET.or.th...';
  box.style.display = 'none';
  try {
    const r = await _fetchTimeout('/api/dr/check-updates', 30000);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    const renamedN = (d.renamed_new?.length || 0) + (d.renamed_removed?.length || 0);
    note.textContent = `SET.or.th มี DR underlying ${d.live_underlying_count} ตัว · ลิสต์เรามี ${d.our_count} ตัว` +
      (renamedN ? ` · ${renamedN} ตัวชื่อไม่ตรงกันแต่ข้อมูลมีอยู่แล้ว (ไม่ต้องทำอะไร)` : '');
    _renderDRDiff(d);
  } catch (e) {
    note.textContent = '';
    box.style.display = 'block';
    box.innerHTML = `<div class="empty" style="padding:16px;color:var(--red)">⚠ เช็คไม่สำเร็จ: ${e.message}</div>`;
  } finally {
    btn.disabled = false;
  }
}

function _renderDRDiff(d) {
  const box = document.getElementById('dr-diff-result');
  box.style.display = 'block';

  const newHtml = d.new.length ? `
    <div style="margin-bottom:10px">
      <div style="font-size:12.5px;font-weight:600;color:var(--green);margin-bottom:6px">🆕 มี DR ซื้อขายจริงแล้ว แต่ยังไม่มีในลิสต์ (${d.new.length} ตัว)</div>
      <div style="overflow-x:auto"><table class="tbl" style="min-width:500px">
        <thead><tr><th>Symbol (เดา)</th><th>ชื่อ</th><th>ตลาด</th><th>DR Tickers บน SET</th></tr></thead>
        <tbody>${d.new.map(x => `
          <tr>
            <td><strong>${_escHtml(x.symbol_guess)}</strong></td>
            <td style="font-size:11px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(x.name || '—')}</td>
            <td style="font-size:11px;color:var(--text2)">${_escHtml(x.exchange || '—')}</td>
            <td style="font-size:11px">${_escHtml(x.dr_tickers.join(', '))}</td>
          </tr>`).join('')}</tbody>
      </table></div>
    </div>` : '';

  const removedHtml = d.removed.length ? `
    <div>
      <div style="font-size:12.5px;font-weight:600;color:var(--red);margin-bottom:6px">🗑 อยู่ในลิสต์เรา แต่ไม่มี DR ซื้อขายบน SET.or.th แล้ว (${d.removed.length} ตัว)</div>
      <div style="overflow-x:auto"><table class="tbl" style="min-width:400px">
        <thead><tr><th>Symbol</th><th>ชื่อ</th><th>Region</th><th>DR Tickers เดิม</th></tr></thead>
        <tbody>${d.removed.map(x => `
          <tr>
            <td><strong>${_escHtml(x.symbol)}</strong></td>
            <td style="font-size:11px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(x.name || '—')}</td>
            <td style="font-size:11px;color:var(--text2)">${_escHtml(x.region || '—')}</td>
            <td style="font-size:11px">${_escHtml((x.drs || []).join(', '))}</td>
          </tr>`).join('')}</tbody>
      </table></div>
    </div>` : '';

  const renamedHtml = (d.renamed_new?.length || d.renamed_removed?.length) ? `
    <details style="margin-top:14px">
      <summary style="cursor:pointer;font-size:11.5px;color:var(--text2)">ℹ️ ${(d.renamed_new?.length||0) + (d.renamed_removed?.length||0)} ตัวชื่อไม่ตรงกัน แต่ข้อมูลมีอยู่แล้ว — ไม่ต้องทำอะไร (กดดูรายละเอียด)</summary>
      <div style="font-size:10.5px;color:var(--text2);margin:8px 0">SET.or.th เปลี่ยนสตริงระบุ underlying ของกองทุน/ตราสารบางตัว (เช่น underlying โค้ด "CAMCSI300" ขณะที่ลิสต์เรา curate ไว้สั้นๆ ว่า "CN") ทำให้เทียบชื่อไม่ตรง ทั้งที่ DR ticker เดียวกันซื้อขายอยู่จริงทั้งคู่ (มีข้อมูลราคาในหน้า DR ปกติ) — เกิดจากตัวเช็คนี้เทียบด้วยชื่อ ไม่ใช่ข้อมูลหายจริง</div>
      ${d.renamed_new?.length ? `<div style="overflow-x:auto;margin-bottom:8px"><table class="tbl" style="min-width:500px">
        <thead><tr><th>SET เรียกว่า</th><th>DR Tickers</th><th>เรามีอยู่แล้วในชื่อ</th></tr></thead>
        <tbody>${d.renamed_new.map(x => `<tr><td>${_escHtml(x.symbol_guess)}</td><td style="font-size:11px">${_escHtml(x.dr_tickers.join(', '))}</td><td><strong>${_escHtml(x.already_tracked_as.join(', '))}</strong></td></tr>`).join('')}</tbody>
      </table></div>` : ''}
      ${d.renamed_removed?.length ? `<div style="overflow-x:auto"><table class="tbl" style="min-width:500px">
        <thead><tr><th>เราเรียกว่า</th><th>DR Tickers เดิม</th><th>ยังเทรดอยู่จริง</th></tr></thead>
        <tbody>${d.renamed_removed.map(x => `<tr><td>${_escHtml(x.symbol)}</td><td style="font-size:11px">${_escHtml((x.drs||[]).join(', '))}</td><td style="font-size:11px"><strong>${_escHtml(x.still_trading_as.join(', '))}</strong></td></tr>`).join('')}</tbody>
      </table></div>` : ''}
    </details>` : '';

  box.innerHTML = `
  <div class="card" style="padding:14px 16px">
    <div style="font-size:10.5px;color:var(--text2);margin-bottom:12px">
      ⚠ บางชื่ออาจเป็นแค่สะกดไม่ตรงกัน (เช่น SET.or.th เขียน "BILIBI" แต่ลิสต์เราเขียน "BILIBILI") — ต้องรีวิวด้วยตาก่อนแก้ <span style="font-family:monospace">sources/dr_universe.py</span> จริง ไม่ได้แก้ให้อัตโนมัติ
    </div>
    ${newHtml}
    ${removedHtml}
    ${!d.new.length && !d.removed.length ? '<div class="empty" style="padding:8px">ลิสต์ตรงกับ SET.or.th ทั้งหมด (นับเฉพาะที่ต้องเพิ่ม/ถอดจริง) ไม่มีอะไรต้องอัปเดต</div>' : ''}
    ${renamedHtml}
  </div>`;
}

// แบนเนอร์เตือนใต้ status ของหน้า DR/ETF — เดิม market cap/ราคาที่ดึงพลาด fallback
// เงียบๆ ใช้ค่าเก่า ไม่มีใครรู้ — server แนบ d.warnings (สรุปสั้นๆ ว่าตัวไหนพัง) มาด้วยเสมอ
// ใช้ร่วมกันทั้งหน้า DR (loadDRPage/_drPollRefresh) และ ETF (loadETFPage/_etfPollRefresh)
function _warnBannerHtml(d) {
  if (!d.warnings || !d.warnings.length) return '';
  return `<br><span style="color:var(--yellow)">⚠ ${d.warnings.join(' · ')}</span>`;
}

function loadDRPage() {
  // ต้องเช็ค .length ด้วย — ถ้ารอบก่อน /api/dr ตอบ stocks:[] (Yahoo ล่ม) _drData = []
  // ซึ่ง truthy ทำให้เข้าเงื่อนไขนี้แล้ว return ทันที ไม่ยอม refetch ทั้ง session
  if (_drLoaded && _drData && _drData.length) { renderDRTable(); return; }
  document.getElementById('dr-status').textContent = 'กำลังดึงข้อมูล...';
  document.getElementById('dr-table-wrap').innerHTML =
    '<div class="dr-loading"><span class="dr-load-spin"></span>กำลังโหลดข้อมูล DR/DRx... (ช้าเฉพาะการรันครั้งแรกสุดของเครื่อง ~1 นาที — ปกติขึ้นทันที)</div>';

  _fetchTimeout('/api/dr', IS_STATIC ? 25000 : 150000)
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      _drData   = d.stocks || [];
      _drLoaded = true;
      _mergeFinAnalyticsInto(_drData, s => s.sym, 'dr');   // ผสาน growth/peg/fcf ถ้าโหลดไว้ก่อนแล้ว (เช็คว่ามีงบการเงินไหมด้วย)
      const ts = d.ts ? d.ts.replace('T', ' ').slice(0, 16) : '—';
      const drTotal = _drData.reduce((s, x) => s + (x.drs?.length || 0), 0);
      document.querySelector('#page-dr .page-sub').textContent =
        `ราคาและ Performance ของ Underlying Stocks ที่มี DR/DRx เทรดบน SET (${drTotal} DR จาก ${_drData.length} หุ้นต่างประเทศ)`;
      document.getElementById('dr-status').innerHTML =
        `อัปเดต: ${ts} &nbsp;|&nbsp; ${_drData.length} underlying stocks &nbsp;|&nbsp; cache 4 ชั่วโมง` +
        (d.refreshing ? ' &nbsp;|&nbsp; <span style="color:var(--accent)">⟳ กำลังดึงข้อมูลชุดใหม่เบื้องหลัง...</span>' : '') +
        _warnBannerHtml(d);
      if (d.refreshing) _drPollRefresh(0);   // server กำลัง rebuild — poll จนได้ชุดใหม่
      _updateDRRegionCounts();
      renderDRTable();
      // รีเฟรช datalist และ watchlist ถ้าเปิดอยู่
      const wlDl = document.getElementById("wl-sym-list");
      if (wlDl) wlDl.innerHTML = "";  // reset ให้ _wlPopulateSymList rebuild ใหม่
      if (document.getElementById("page-watchlist")?.classList.contains("active")) renderWatchlist();
    })
    .catch(e => {
      document.getElementById('dr-table-wrap').innerHTML =
        `<div class="empty">เกิดข้อผิดพลาด: ${e.message}</div>`;
    });
}

// stale-while-revalidate: server ตอบข้อมูลเก่าทันทีแล้ว rebuild เบื้องหลัง —
// poll ทุก 30 วิ (สูงสุด ~4 นาที) จนได้ชุดใหม่แล้ววาดตารางซ้ำเงียบๆ
// ใช้ร่วมกัน 2 หน้า (หน้า DR + แท็บ TH ของ Stock Rotation) — guard กัน start ซ้อน
// ไม่งั้นเปิดทั้งสองหน้าไล่กันจะยิง /api/dr คู่ขนานทุก 30 วิ
let _drPollActive = false;
function _drPollRefresh(attempt) {
  if (attempt === 0) {
    if (_drPollActive) return;
    _drPollActive = true;
  }
  if (attempt >= 8) { _drPollActive = false; return; }   // เกินนี้ปล่อย — เปิดหน้าครั้งถัดไปก็ได้ชุดใหม่เอง
  setTimeout(() => {
    _fetchTimeout('/api/dr', 30000).then(r => r.json()).then(d => {
      if (!d.stocks || !d.stocks.length) { _drPollActive = false; return; }
      if (d.refreshing) { _drPollRefresh(attempt + 1); return; }
      _drPollActive = false;
      _drData = d.stocks;
      _drLoaded = true;
      _mergeFinAnalyticsInto(_drData, s => s.sym, 'dr');
      const ts = d.ts ? d.ts.replace('T', ' ').slice(0, 16) : '—';
      const st = document.getElementById('dr-status');
      if (st) st.innerHTML =
        `อัปเดต: ${ts} &nbsp;|&nbsp; ${_drData.length} underlying stocks &nbsp;|&nbsp; cache 4 ชั่วโมง <span style="color:var(--green)">✓ ข้อมูลชุดใหม่แล้ว</span>` +
        _warnBannerHtml(d);
      _updateDRRegionCounts();
      if (document.getElementById('page-dr')?.classList.contains('active')) renderDRTable();
      // แท็บ TH ของ Stock Rotation ใช้ _drData ชุดเดียวกัน — ปิดป้ายและวาดซ้ำถ้าดูอยู่
      const rf = document.getElementById('drrot-refreshing');
      if (rf) rf.style.display = 'none';
      if (document.getElementById('page-stock-rotation')?.classList.contains('active') && _srMarket === 'TH') renderDRRotation();
    }).catch(() => _drPollRefresh(attempt + 1));
  }, 30000);
}

function drQuickUpdate() {
  const btn = document.getElementById('dr-quick-btn');
  if (!_drData) { loadDRPage(); return; }
  if (btn) { btn.disabled = true; btn.textContent = '⏳ กำลังอัปเดต...'; }
  const statusEl = document.getElementById('dr-status');

  _fetchTimeout('/api/dr-quick-update', 30000, null, { method: 'POST' })
    .then(r => r.json())
    .then(res => {
      // 400 (ยังไม่มี DR cache ฯลฯ) — backend ส่ง {error} มา + เคลียร์ _dr_refresh_state แล้ว
      // เดิมไม่เช็ค res.error เลย ปล่อยเข้า poll ต่อ แล้ว /api/dr-quick-status ของรอบก่อน
      // (done=true, n_updated ค้าง) ทำให้ขึ้น "✓ สำเร็จ N/M" หลอก
      if (res && res.error) {
        if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
        if (statusEl) statusEl.textContent = 'อัปเดตไม่สำเร็จ: ' + res.error;
        return;
      }
      // status "running" = มีงาน DR quick-update ค้างอยู่แล้วจากที่อื่น (เช่นปุ่ม "⚡ Quick
      // Update" หลักที่ยิง /api/dr-quick-update คู่กันอัตโนมัติทุกครั้ง — ดู startQuickUpdate())
      // ปุ่มนี้เลยไม่ได้เริ่มงานใหม่ตามที่กด แค่ไปรอผลรอบเก่าแทน ต้องบอกผู้ใช้ตรงๆ กันเข้าใจผิด
      // ว่าราคาที่ได้ท้ายสุดคือของรอบที่เพิ่งกด
      if (res.status === 'running' && btn) {
        btn.textContent = '⏳ มีงานอัปเดตค้างอยู่ กำลังรอผล...';
      }
      // cap จำนวนรอบ poll (เหมือน _drPollRefresh ด้านล่าง) — กัน backend thread ค้าง
      // (เช่น yf.download ไม่ตอบ) ทำให้ปุ่มนี้ disabled ค้างถาวรไม่มีทางกู้คืนได้เอง
      let _drQuickPollTries = 0;
      const poll = setInterval(() => {
        if (++_drQuickPollTries > 160) {   // ~4 นาที (1.5วิ x 160) — เกินนี้ถือว่าผิดปกติ
          clearInterval(poll);
          if (statusEl) statusEl.textContent = 'อัปเดตนานผิดปกติ (>4 นาที) — ลองกดใหม่ หรือรีเฟรชหน้า';
          if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
          return;
        }
        _fetchTimeout('/api/dr-quick-status', 15000).then(r => r.json()).then(s => {
          if (!s.running) {
            clearInterval(poll);
            if (s.error) {
              if (statusEl) statusEl.textContent = 'อัปเดตไม่สำเร็จ: ' + s.error;
              if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
            } else {
              _fetchTimeout('/api/dr', 30000).then(r => r.json()).then(d => {
                if (d.stocks) {
                  _drData = d.stocks;
                  const ts = d.ts ? d.ts.replace('T',' ').slice(0,16) : '—';
                  // ราคาสด ณ HH:MM:SS · สำเร็จ N/M ตัว — แบบเดียวกับปุ่ม "⚡ ราคาล่าสุด" ของ
                  // Watchlist (ดู wlRefreshLivePrices) n_updated/n_total มาจาก _dr_refresh_state
                  // ฝั่ง backend (ดู _do_quick ใน app.py) นับเฉพาะตัวที่อัปเดตราคาสำเร็จจริง
                  const liveNote = s.n_total != null
                    ? ` &nbsp;|&nbsp; ราคาสด ณ ${new Date().toLocaleTimeString('th-TH')} · สำเร็จ ${s.n_updated}/${s.n_total} ตัว`
                    : '';
                  if (statusEl) statusEl.innerHTML =
                    `อัปเดต: ${ts} &nbsp;|&nbsp; ${_drData.length} stocks &nbsp;|&nbsp; <span style="color:var(--green)">✓ อัปเดตราคาสำเร็จ</span>${liveNote}`;
                  _updateDRRegionCounts();
                  renderDRTable();
                }
                if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
              }).catch(e => {
                if (statusEl) statusEl.textContent = 'โหลด DR ไม่ได้: ' + e.message;
                if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
              });
            }
          }
        }).catch(e => {
          clearInterval(poll);
          if (statusEl) statusEl.textContent = 'ตรวจสอบสถานะไม่ได้: ' + e.message;
          if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
        });
      }, 1500);
    })
    .catch(e => {
      if (btn) { btn.disabled = false; btn.textContent = '⚡ อัปเดตราคา'; }
      if (statusEl) statusEl.textContent = 'เกิดข้อผิดพลาด: ' + e.message;
    });
}

function _updateDRRegionCounts() {
  if (!_drData) return;
  const counts = {};
  _drData.forEach(s => { counts[s.region] = (counts[s.region] || 0) + 1; });
  document.querySelectorAll('#dr-region-btns .dr-region-count-badge').forEach(el => {
    const region = el.dataset.region;
    const n = region === 'ALL' ? _drData.length
            : region === 'HK'  ? (counts.HK || 0) + (counts.CN || 0)
            : (counts[region] || 0);
    el.textContent = `(${n})`;
  });
}

function setDRRegion(r, btn) {
  _drRegion = r;
  document.querySelectorAll('#dr-region-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (_drData) renderDRTable();
}

function setDRSort(s, btn) {
  _drSort = s;
  document.querySelectorAll('#dr-sort-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (_drData) renderDRTable();
}

function filterDR() {
  _drSearch = document.getElementById('dr-search').value.toLowerCase().trim();
  if (_drData) renderDRTable();
}

function _sortDR(arr) {
  return [...arr].sort((a, b) => {
    if (_drSort === 'rs_desc')     return (b.rs_score ?? -1)  - (a.rs_score ?? -1);
    if (_drSort === 'chg_desc')    return (b.chg ?? -999)     - (a.chg ?? -999);
    if (_drSort === 'chg_asc')     return (a.chg ?? 999)      - (b.chg ?? 999);
    if (_drSort === 'ret_1m_desc') return (b.ret_1m ?? -999)  - (a.ret_1m ?? -999);
    if (_drSort === 'ret_1y_desc') return (b.ret_1y ?? -999)  - (a.ret_1y ?? -999);
    if (_drSort === 'mkt_cap')     return (b.mkt_cap || 0)    - (a.mkt_cap || 0);
    return a.sym.localeCompare(b.sym);
  });
}

function setDRView(v, btn) {
  _drView = v;
  document.querySelectorAll('.dr-view-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  // แถบเลือก metric สี + hint โผล่เฉพาะตอนดูมุมมอง Heatmap
  const periodRow = document.getElementById('dr-hm-period-row');
  const hint      = document.getElementById('dr-hm-hint');
  if (periodRow) periodRow.style.display = v === 'heatmap' ? '' : 'none';
  if (hint)      hint.style.display      = v === 'heatmap' ? '' : 'none';
  if (_drData) renderDRTable();
}

// ============================================================
// DR HEATMAP — เฉพาะหุ้น underlying stocks (ตัด ETF ออก) จัดกลุ่มตามภูมิภาค
// reuse _heatColor/_heatColorRS ตัวเดียวกับ Market Heatmap (หน้าหุ้นไทย)
// ============================================================
let _drHmPeriod = 'chg';

function setDrHmPeriod(key, btn) {
  _drHmPeriod = key;
  document.querySelectorAll('#dr-hm-period-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (_drData) renderDRTable();
}

const DR_HM_CFG = {
  // ใช้ live_chg (ราคาสด เทียบราคาปิดที่นิ่งล่าสุด) เมื่อตลาดนั้นกำลังเทรดอยู่จริง
  // (มีค่าเฉพาะตอน is_latest_bar_stable()==false ฝั่ง backend) ไม่งั้น fallback เป็น
  // chg ปกติ (เทียบ session ก่อนหน้า) — กันสีค้างของเมื่อวานทั้งที่ราคาสดขยับไปมากแล้ว
  // (ผู้ใช้รายงานพบ: GIGA chg -4.82% แต่ live จริง -11.69% จากราคาปิด)
  chg:      { getV:s=>s.live_chg ?? s.chg, isLive:s=>s.live_chg!=null, clr:v=>_heatColor(v,15), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)',  hint:'เขียว = ขึ้น · แดง = ลง · ⚡ = ราคาสด (ตลาดกำลังเทรด) ไม่มี ⚡ = ราคาปิด session ก่อนหน้า' },
  ret_1w:   { getV:s=>s.ret_1w,   clr:v=>_heatColor(v,15), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)',  hint:'เขียว = ขึ้น · แดง = ลง (1 สัปดาห์)' },
  ret_1m:   { getV:s=>s.ret_1m,   clr:v=>_heatColor(v,20), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>8?'#fff':'var(--text)',  hint:'เขียว = ขึ้น · แดง = ลง (1 เดือน)' },
  ret_3m:   { getV:s=>s.ret_3m,   clr:v=>_heatColor(v,30), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>12?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (3 เดือน)' },
  ret_6m:   { getV:s=>s.ret_6m,   clr:v=>_heatColor(v,40), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>16?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (6 เดือน)' },
  ret_1y:   { getV:s=>s.ret_1y,   clr:v=>_heatColor(v,50), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0,  txt:v=>Math.abs(v??0)>20?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (1 ปี)' },
  rs_score: { getV:s=>s.rs_score, clr:v=>_heatColorRS(v),  fmt:v=>'RS '+Math.round(v),            aFmt:v=>'avg RS '+Math.round(v),      aPos:v=>v>=50, txt:v=>(v??50)>70||(v??50)<30?'#fff':'var(--text)', hint:'เขียว = RS สูง (แข็งแกร่งเทียบกลุ่ม DR) · แดง = RS ต่ำ' },
  ath_dist: { getV:s=>s.ath_pct??null, clr:v=>_heatColor(v,50), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>'avg '+(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>20?'#fff':'var(--text)', hint:'เขียว = ใกล้/ทำ ATH · แดง = ห่างจาก All-Time High มาก' },
};

function _renderDRHeatmap(stocks) {
  const wrap = document.getElementById('dr-table-wrap');
  const cfg  = DR_HM_CFG[_drHmPeriod] || DR_HM_CFG.chg;
  const hintEl = document.getElementById('dr-hm-hint');
  if (hintEl) hintEl.textContent = cfg.hint;

  // ทำเฉพาะ underlying stocks — ตัด ETF ออกเสมอไม่ว่าจะกรอง region ไหนอยู่ (ตามที่ตั้งใจ)
  const nonEtf = stocks.filter(s => !s.etf);
  if (!nonEtf.length) { wrap.innerHTML = '<div class="empty">ไม่พบหุ้น underlying ที่ตรงกับเงื่อนไข (ETF ถูกตัดออกจาก Heatmap เสมอ)</div>'; return; }

  const groups = {};
  nonEtf.forEach(s => {
    const key = s.region || 'Other';
    (groups[key] = groups[key] || []).push(s);
  });
  const regionOrder = ['US','HK','CN','JP','EU','SG','VN','TW'];
  const orderedRegions = regionOrder.filter(r => groups[r]?.length);

  wrap.innerHTML = orderedRegions.map(region => {
    const list = groups[region];
    const sorted = [...list].sort((a, b) => (cfg.getV(b) ?? -999) - (cfg.getV(a) ?? -999));
    const withVal = sorted.filter(s => cfg.getV(s) != null);
    const avg = withVal.length ? withVal.reduce((s, x) => s + cfg.getV(x), 0) / withVal.length : null;
    const cells = sorted.map(s => {
      const v      = cfg.getV(s);
      const bg     = cfg.clr(v);
      const txt    = cfg.txt(v);
      const lbl    = v != null ? cfg.fmt(v) : '—';
      const isLive = cfg.isLive ? cfg.isLive(s) : false;
      // ⚡ บอกว่าเซลล์นี้ใช้ราคาสด (ตลาดกำลังเทรด) ไม่ใช่ราคาปิด — กันสับสนตอนบาง
      // เซลล์ในกลุ่มเดียวกันเป็นราคาสด บางเซลล์เป็นราคาปิด (ต่างตลาด/ต่างเวลาเปิดปิด)
      const tip = isLive
        ? `${s.sym} — ${s.name} — ⚡ ราคาสด ${lbl} (เทียบราคาปิดล่าสุด, ตลาดกำลังเทรดอยู่)`
        : `${s.sym} — ${s.name} — ${lbl} (ราคาปิด)`;
      return `<div class="hm-cell" style="background:${bg};color:${txt}" title="${tip}" onclick="openDRChartModal('${s.sym}')">
        <span style="font-size:11px;font-weight:700;line-height:1">${isLive ? '⚡' : ''}${s.sym.slice(0,6)}</span>
        <span style="font-size:9px;line-height:1;opacity:0.85">${_drFmtPrice(s.live_price ?? s.price)}</span>
        <span style="font-size:10px;line-height:1;opacity:0.92">${lbl}</span>
      </div>`;
    }).join('');
    const avgClass = avg != null ? (cfg.aPos(avg) ? 'green' : 'red') : 'text2';
    const avgDisp  = avg != null ? cfg.aFmt(avg) : '—';
    return `
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;display:flex;align-items:center;gap:8px">
          ${DR_REGION_LABEL[region] || region}
          <span class="${avgClass}">${avgDisp}</span>
          <span class="text2" style="font-size:10px">${list.length} หุ้น</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:2px">${cells}</div>
      </div>`;
  }).join('');
}

function _drExchBadge(yf) {
  if (!yf) return '';
  if (yf.endsWith('.HK'))  return '🇭🇰 HKEX';
  if (yf.endsWith('.T'))   return '🇯🇵 TSE';
  if (yf.endsWith('.SI'))  return '🇸🇬 SGX';
  if (yf.endsWith('.VN'))  return '🇻🇳 HOSE';
  if (yf.endsWith('.TW'))  return '🇹🇼 TWSE';
  if (yf.endsWith('.PA'))  return '🇫🇷 EPA';
  if (yf.endsWith('.MI'))  return '🇮🇹 BIT';
  if (yf.endsWith('.SS'))  return '🇨🇳 SSE';
  if (yf.endsWith('.SZ'))  return '🇨🇳 SZSE';
  if (yf.endsWith('.DE'))  return '🇩🇪 XETRA';
  if (yf.endsWith('.AS'))  return '🇳🇱 AEX';
  if (yf.endsWith('.L'))   return '🇬🇧 LSE';
  return '🇺🇸 US';
}

// badge ลิงก์ TradingView ต่อ DR ticker — ใช้ร่วมกันทั้งมุมมองตาราง (_drRows) และการ์ด
// (_drCardGrid) เดิม copy-paste เหมือนกัน 2 ที่
function _drBadgesHtml(drs) {
  return (drs || []).map(d =>
    `<a class="dr-badge${d.endsWith('X') ? ' dr-badge-x' : ''}" href="https://www.tradingview.com/chart/?symbol=SET:${encodeURIComponent(d)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="เปิด ${d} ใน TradingView">${d}</a>`
  ).join('');
}

function _drCardGrid(stocks) {
  return stocks.map(s => {
    const chgCls  = s.chg == null ? '' : (s.chg >= 0 ? 'green' : 'red');
    const chgStr  = s.chg != null ? (s.chg >= 0 ? '+' : '') + s.chg.toFixed(2) + '%' : '—';
    const logoHtml = _drLogoHtml(s, 'dr-card-logo');
    const badges = _drBadgesHtml(s.drs);
    const cPct = v => v != null ? `<span class="${v>=0?'green':'red'}">${v>=0?'+':''}${v.toFixed(2)}%</span>` : '—';
    const rsDisp = s.rs_score != null ? `<span class="${rsColor(s.rs_score)}" style="font-weight:700">RS ${s.rs_score}</span>` : '';
    return `<div class="dr-card" onclick="openDRChartModal('${s.sym}')" style="cursor:pointer">
      <div class="dr-card-header">
        ${logoHtml}
        <div>
          <div class="dr-card-sym" style="color:var(--blue)">${s.yf}</div>
          <span class="dr-card-exch">${_drExchBadge(s.yf)}</span>
        </div>
        ${rsDisp ? `<div style="margin-left:auto;font-size:11px">${rsDisp}</div>` : ''}
        <a class="tv-link" href="https://www.tradingview.com/chart/?symbol=${yfToTVSym(s.yf)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView" style="margin-left:${rsDisp?'6px':'auto'}">↗</a>
      </div>
      <div class="dr-card-name">${s.name}</div>
      <div class="dr-card-price-row">
        <span class="dr-card-price">${_drFmtPrice(s.price)}</span>
        <span class="dr-card-chg ${chgCls}">${chgStr}</span>
      </div>
      ${_drLiveTag(s)}
      <div style="display:flex;gap:6px;font-size:10px;color:var(--text2);margin:3px 0 2px">
        <span>1M ${cPct(s.ret_1m)}</span><span>3M ${cPct(s.ret_3m)}</span><span>1Y ${cPct(s.ret_1y)}</span>
      </div>
      <canvas class="dr-card-chart dr-trend-cv" data-close='${JSON.stringify(s.close100||[])}' width="200" height="52"></canvas>
      <div class="dr-card-badges">${badges}</div>
    </div>`;
  }).join('');
}

function renderDRTable() {
  if (!_drData) return;

  let stocks = _drData;
  // ปุ่ม "HK/CN" ครอบทั้งหุ้นฮ่องกงและ A-share จีน (ตลาด Shanghai/Shenzhen) — สอง region
  // แยกกันในข้อมูล แต่ curate รวมเป็นปุ่มเดียวเพราะจำนวนหุ้น CN ยังน้อยมาก
  if (_drRegion === 'HK') stocks = stocks.filter(s => s.region === 'HK' || s.region === 'CN');
  else if (_drRegion !== 'ALL') stocks = stocks.filter(s => s.region === _drRegion);
  if (_drSearch) {
    stocks = stocks.filter(s =>
      s.sym.toLowerCase().includes(_drSearch) ||
      s.name.toLowerCase().includes(_drSearch) ||
      s.ind.toLowerCase().includes(_drSearch) ||
      s.drs.some(d => d.toLowerCase().includes(_drSearch))
    );
  }

  const wrap = document.getElementById('dr-table-wrap');
  // .tbl-scroll-page (max-height:70vh sticky header) มีไว้เฉพาะมุมมอง Table — Cards/Heatmap
  // ไม่ใช่ตาราง ไม่ควรโดนบีบใส่กล่อง scroll ในตัวเอง (เดิมติด class คงที่ใน HTML กระทบทั้ง 3 มุมมอง)
  wrap.classList.toggle('tbl-scroll-page', _drView === 'table');
  if (!stocks.length) { wrap.innerHTML = '<div class="empty">ไม่พบข้อมูลที่ตรงกับเงื่อนไข</div>'; return; }

  if (_drView === 'cards') {
    let html = '<div class="dr-card-grid">';
    if (_drRegion === 'ALL') {
      for (const region of ['US','HK','CN','JP','EU','SG','VN','TW']) {
        const rs = _sortDR(stocks.filter(s => s.region === region));
        if (!rs.length) continue;
        html += `<div class="dr-region-hdr-card">${DR_REGION_LABEL[region] || region} — ${rs.length} stocks</div>`;
        html += _drCardGrid(rs);
      }
    } else {
      html += _drCardGrid(_sortDR(stocks));
    }
    html += '</div>';
    wrap.innerHTML = html;
    requestAnimationFrame(() => _drawAllDRCharts());
    return;
  }

  if (_drView === 'heatmap') {
    _renderDRHeatmap(stocks);
    return;
  }

  const thead = `<thead><tr>
    <th style="width:112px" title="ชื่อย่อหุ้นต่างประเทศ (underlying) — คลิกเพื่อเปิดกราฟ">Symbol</th>
    <th class="r" style="width:80px" title="ราคาปิดล่าสุด (สกุลเงินท้องถิ่นของตลาดนั้น)">Close</th>
    <th class="r" style="width:64px">CHG%${colTipIcon('ret_1d')}</th>
    <th class="r" style="width:42px" title="RS Score 0–99 — จัดอันดับเทียบภายในกลุ่ม underlying stocks ทั้งหมด ยิ่งสูงยิ่งแข็งแกร่ง">RS</th>
    <th class="r" style="width:58px">1W%${colTipIcon('ret_1w')}</th>
    <th class="r" style="width:58px">1M%${colTipIcon('ret_1m')}</th>
    <th class="r" style="width:58px">3M%${colTipIcon('ret_3m')}</th>
    <th class="r" style="width:58px">1Y%${colTipIcon('ret_1y')}</th>
    <th style="min-width:150px">Company${colTipIcon('name')}</th>
    <th style="min-width:180px" title="DR/DRx ที่อ้างอิงหุ้นตัวนี้ ซื้อขายได้บน SET ด้วยเงินบาท">DR Tickers บน SET</th>
    <th style="min-width:140px">Industry${colTipIcon('industry')}</th>
    <th class="r" style="width:72px">MKT CAP${colTipIcon('mkt_cap')}</th>
    <th style="width:108px;text-align:center" title="กราฟเส้นราคาปิดย้อนหลัง 100 วันทำการ — ดูแนวโน้มระยะกลางแบบรวดเร็ว">Trend (100D)</th>
    <th style="width:136px;text-align:center" title="กราฟแท่งเทียน (candlestick) ย้อนหลัง 30 วันทำการ — ดูรูปแบบราคาระยะสั้น">Pattern (30D)</th>
    <th class="r" style="width:52px" title="ตั้งราคาแจ้งเตือน">🔔</th>
  </tr></thead>`;

  let tbody = '';
  if (_drRegion === 'ALL') {
    for (const region of ['US','HK','CN','JP','EU','SG','VN','TW']) {
      const rs = _sortDR(stocks.filter(s => s.region === region));
      if (!rs.length) continue;
      tbody += `<tr><td colspan="15" class="dr-region-hdr">${DR_REGION_LABEL[region] || region} <span class="dr-region-count">${rs.length} stocks</span></td></tr>`;
      tbody += _drRows(rs);
    }
  } else {
    tbody = _drRows(_sortDR(stocks));
  }

  wrap.innerHTML = `<table class="tbl dr-tbl">${thead}<tbody>${tbody}</tbody></table>`;
  requestAnimationFrame(() => _drawAllDRCharts());
}

function _drRows(stocks) {
  return stocks.map(s => {
    const chgCls   = s.chg == null ? '' : (s.chg >= 0 ? 'green' : 'red');
    const chgStr   = s.chg != null ? (s.chg >= 0 ? '+' : '') + s.chg.toFixed(2) + '%' : '—';
    const badges   = _drBadgesHtml(s.drs);
    const logoHtml = _drLogoHtml(s, 'dr-logo');

    const drPct = v => v != null
      ? `<span class="${v >= 0 ? 'green' : 'red'}" style="font-size:11px">${v >= 0 ? '+' : ''}${v.toFixed(2)}%</span>`
      : '<span style="color:var(--text2);font-size:11px">—</span>';
    const rsNum = s.rs_score != null
      ? `<span class="${rsColor(s.rs_score)}" style="font-weight:700;font-size:11px">${s.rs_score}</span>`
      : '<span style="color:var(--text2);font-size:11px">—</span>';

    return `<tr>
      <td>
        <div class="dr-sym-cell" onclick="openDRChartModal('${s.sym}')" style="cursor:pointer" title="ดูกราฟ ${s.yf}">
          ${logoHtml}
          <span class="dr-sym-text" style="color:var(--blue)">${s.yf}</span>
          <a class="tv-link" href="https://www.tradingview.com/chart/?symbol=${yfToTVSym(s.yf)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView">↗</a>
        </div>
      </td>
      <td class="r" style="font-size:12px;font-weight:600">${_drFmtPrice(s.price)}${_drLiveTag(s)}</td>
      <td class="r ${chgCls}" style="font-size:12px;font-weight:600">${chgStr}</td>
      <td class="r">${rsNum}</td>
      <td class="r">${drPct(s.ret_1w)}</td>
      <td class="r">${drPct(s.ret_1m)}</td>
      <td class="r">${drPct(s.ret_3m)}</td>
      <td class="r">${drPct(s.ret_1y)}</td>
      <td style="font-size:11px">${s.name}${s.yf ? '<br><span style="font-size:10px;color:var(--text2)">(' + s.yf + ')</span>' : ''}</td>
      <td style="font-size:9.5px;line-height:1.8">${badges}</td>
      <td style="font-size:11px;color:var(--text2)">${s.ind}</td>
      <td class="r" style="font-size:11px">${_drFmtCap(s.mkt_cap)}</td>
      <td style="padding:4px 5px">
        <canvas class="dr-trend-cv" data-close='${JSON.stringify(s.close100||[])}' width="104" height="36" style="display:block;width:104px;height:36px"></canvas>
      </td>
      <td style="padding:4px 5px">
        <canvas class="dr-candle-cv" data-ohlc='${JSON.stringify(s.ohlc30||[])}' width="130" height="36" style="display:block;width:130px;height:36px"></canvas>
      </td>
      <td class="r" style="white-space:nowrap">${_wlAlertCell("DR:" + s.sym)}</td>
    </tr>`;
  }).join('');
}

function _drawAllDRCharts() {
  document.querySelectorAll('.dr-trend-cv').forEach(cv => {
    try { const d = JSON.parse(cv.dataset.close||'[]'); if (d.length>=2) _drawDRSparkline(cv,d); } catch(e) {}
  });
  document.querySelectorAll('.dr-candle-cv').forEach(cv => {
    try { const d = JSON.parse(cv.dataset.ohlc||'[]'); if (d.length>=2) _drawDRCandles(cv,d); } catch(e) {}
  });
}

function _drawDRSparkline(canvas, prices) {
  const dpr = window.devicePixelRatio || 1;
  const W = 104, H = 36;
  canvas.width = W * dpr; canvas.height = H * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  const min = Math.min(...prices), max = Math.max(...prices), rng = max - min || 1;
  const isUp = prices[prices.length-1] >= prices[0];
  const col  = isUp ? '#3fb950' : '#f85149';
  const pad  = 3;

  ctx.clearRect(0, 0, W, H);
  ctx.beginPath();
  prices.forEach((p, i) => {
    const x = (i / (prices.length-1)) * W;
    const y = H - pad - ((p - min) / rng) * (H - pad*2);
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.strokeStyle = col; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath();
  ctx.fillStyle = isUp ? 'rgba(63,185,80,0.12)' : 'rgba(248,81,73,0.12)';
  ctx.fill();
}

function _drawDRCandles(canvas, ohlc) {
  const dpr = window.devicePixelRatio || 1;
  const W = 130, H = 36;
  canvas.width = W * dpr; canvas.height = H * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);

  const hasVol = ohlc.length > 0 && ohlc[0].length >= 5 && ohlc.some(d => d[4] > 0);
  const priceH = hasVol ? Math.floor(H * 0.70) : H;
  const volH   = hasVol ? H - priceH - 1 : 0;

  const hiVal = Math.max(...ohlc.map(c => c[1]));
  const loVal = Math.min(...ohlc.map(c => c[2]));
  const rng   = hiVal - loVal || 1;
  const pad   = 2, n = ohlc.length;
  const slotW = W / n;
  const cw    = Math.max(1, Math.floor(slotW * 0.65));
  const toY   = v => priceH - pad - ((v - loVal) / rng) * (priceH - pad*2);

  ohlc.forEach(([o, h, l, c], i) => {
    const cx  = i * slotW + slotW / 2;
    const col = c >= o ? '#3fb950' : '#f85149';
    ctx.strokeStyle = col; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(cx, toY(h)); ctx.lineTo(cx, toY(l)); ctx.stroke();
    const top = toY(Math.max(o,c)), bot = toY(Math.min(o,c));
    ctx.fillStyle = col;
    ctx.fillRect(cx - cw/2, top, cw, Math.max(1, bot - top));
  });

  if (hasVol) {
    const vols  = ohlc.map(d => d[4] || 0);
    const maxVol = Math.max(...vols) || 1;
    const volTop = priceH + 1;
    ohlc.forEach(([o,,, c], i) => {
      const v  = vols[i];
      const bh = Math.max(1, Math.round((v / maxVol) * (volH - 1)));
      const cx = i * slotW + slotW / 2;
      ctx.fillStyle = c >= o ? 'rgba(63,185,80,0.5)' : 'rgba(248,81,73,0.5)';
      ctx.fillRect(cx - cw/2, volTop + volH - bh, cw, bh);
    });
  }
}

// ============================================================
// ETF (SET-listed) — ต่างจาก DR ตรงที่เป็นตราสารจดทะเบียนบน SET เอง universe เล็ก
// (~13 ตัว) reuse CSS classes ของ DR (.dr-card/.dr-tbl/...) และ canvas draw functions
// (_drawDRSparkline/_drawDRCandles) ตรงๆ — เขียนแค่ data-layer/render ใหม่
// ============================================================
let _etfData     = null;
let _etfLoaded   = false;
let _etfTs       = null;
let _etfCategory = 'ALL';
let _etfView     = 'table';
let _etfSort     = 'rs_desc';
let _etfSearch   = '';

const ETF_CATEGORY_LABEL = {
  TH_EQ: '🇹🇭 ดัชนีในประเทศ', FOREIGN: '🌏 ดัชนีต่างประเทศ',
  BOND: '💵 ตราสารหนี้', COMMODITY: '🪙 โภคภัณฑ์', OTHER: 'อื่นๆ',
};

function _etfLogoUrl(sym) {
  return `https://media.set.or.th/common/logo/company/${encodeURIComponent(sym)}.png`;
}

function loadETFPage() {
  _ackEtfNewListings();
  // ต้องเช็ค .length ด้วย — ถ้ารอบก่อน /api/etf ตอบ stocks:[] (SET API + etf_prices.db
  // ล่มพร้อมกัน) _etfData = [] ซึ่ง truthy ทำให้ return ทันที ไม่ยอม refetch ทั้ง session
  // (bug เดียวกับที่ loadDRPage guard ไว้)
  if (_etfLoaded && _etfData && _etfData.length) { renderETFTable(); return; }
  document.getElementById('etf-status').textContent = 'กำลังดึงข้อมูล...';
  document.getElementById('etf-table-wrap').innerHTML =
    '<div class="dr-loading"><span class="dr-load-spin"></span>กำลังโหลดข้อมูล ETF...</div>';

  _fetchTimeout('/api/etf', 60000)
    .then(r => r.json())
    .then(d => {
      if (d.error) throw new Error(d.error);
      _etfData   = d.stocks || [];
      _etfLoaded = true;
      _etfTs     = d.ts;
      const ts = d.ts ? d.ts.replace('T', ' ').slice(0, 16) : '—';
      document.getElementById('etf-status').innerHTML =
        `อัปเดต: ${ts} &nbsp;|&nbsp; ${_etfData.length} ETF &nbsp;|&nbsp; cache 2 ชั่วโมง` +
        (d.refreshing ? ' &nbsp;|&nbsp; <span style="color:var(--accent)">⟳ กำลังดึงข้อมูลชุดใหม่เบื้องหลัง...</span>' : '') +
        _warnBannerHtml(d);
      if (d.refreshing) _etfPollRefresh(0);
      _updateETFCategoryCounts();
      renderETFTable();
    })
    .catch(e => {
      document.getElementById('etf-status').textContent = 'เกิดข้อผิดพลาด';
      document.getElementById('etf-table-wrap').innerHTML =
        `<div class="empty">เกิดข้อผิดพลาด: ${e.message}</div>`;
    });
}

let _etfPollActive = false;
function _etfPollRefresh(attempt) {
  if (attempt === 0) {
    if (_etfPollActive) return;
    _etfPollActive = true;
  }
  if (attempt >= 6) {
    _etfPollActive = false;
    // poll หมดโควตา (~3 นาที) แต่ background rebuild ยังไม่เสร็จ — เลิก loop แล้วเก็บ
    // suffix "⟳ กำลังดึงข้อมูลชุดใหม่เบื้องหลัง..." ที่ค้างอยู่ใน etf-status ออก
    // ไม่งั้นผู้ใช้เข้าใจผิดว่ากำลังโหลดตลอดไป (indicator เดิมเคลียร์เฉพาะ path สำเร็จ)
    const st = document.getElementById('etf-status');
    if (st && _etfData) {
      const ts0 = _etfTs ? _etfTs.replace('T', ' ').slice(0, 16) : '—';
      st.innerHTML =
        `อัปเดต: ${ts0} &nbsp;|&nbsp; ${_etfData.length} ETF &nbsp;|&nbsp; cache 2 ชั่วโมง ` +
        `<span style="color:var(--text2)">(ยังดึงชุดใหม่ไม่เสร็จ — เปิดหน้านี้ใหม่ภายหลัง)</span>`;
    }
    const rf0 = document.getElementById('etfrot-refreshing');
    if (rf0) rf0.style.display = 'none';
    return;
  }
  setTimeout(() => {
    _fetchTimeout('/api/etf', 30000).then(r => r.json()).then(d => {
      if (!d.stocks || !d.stocks.length) { _etfPollActive = false; return; }
      if (d.refreshing) { _etfPollRefresh(attempt + 1); return; }
      _etfPollActive = false;
      _etfData = d.stocks;
      _etfLoaded = true;
      _etfTs   = d.ts;
      const ts = d.ts ? d.ts.replace('T', ' ').slice(0, 16) : '—';
      const st = document.getElementById('etf-status');
      if (st) st.innerHTML =
        `อัปเดต: ${ts} &nbsp;|&nbsp; ${_etfData.length} ETF &nbsp;|&nbsp; cache 2 ชั่วโมง <span style="color:var(--green)">✓ ข้อมูลชุดใหม่แล้ว</span>` +
        _warnBannerHtml(d);
      _updateETFCategoryCounts();
      const rf = document.getElementById('etfrot-refreshing');
      if (rf) rf.style.display = 'none';
      if (document.getElementById('page-etf')?.classList.contains('active')) renderETFTable();
      if (document.getElementById('page-stock-rotation')?.classList.contains('active') && _srMarket === 'ETF') renderEtfRotation();
    }).catch(() => _etfPollRefresh(attempt + 1));
  }, 30000);
}

function reloadETFPage() {
  _etfLoaded = false;
  _etfData   = null;
  document.getElementById('etf-status').textContent = 'กำลังดึงข้อมูลใหม่...';
  document.getElementById('etf-table-wrap').innerHTML =
    '<div class="dr-loading"><span class="dr-load-spin"></span>กำลังโหลดข้อมูล ETF...</div>';
  // ต้องรอ POST ตั้ง ts=0 ให้เสร็จก่อนยิง GET /api/etf — ไม่งั้น GET อาจถึง get_etf_data
  // ก่อน (คนละ worker thread) เห็น cache ยังไม่หมดอายุ แล้วตอบของเก่าโดยไม่ rebuild
  // (bug + fix เดียวกับ confirmRefresh ของหน้า DR)
  fetch('/api/etf-full-refresh', { method: 'POST' })
    .catch(() => {})
    .then(() => loadETFPage());
}

// ราคาสดระหว่างวัน — เรียก /api/live-price/<symbol> (fast_info, ไม่โหลดประวัติ/ไม่ยิง
// SET.or.th) ต่อ ETF ทั้ง 13 ตัวแบบขนาน เร็วกว่ารอ cache 2 ชั่วโมงหมดอายุ แบบเดียวกับปุ่ม
// "⚡ ราคาล่าสุด" ของ Watchlist (ดู wlRefreshLivePrices) — เก็บผลใน live_price/live_chg
// เทียบกับ s.price (ราคาปิดล่าสุดที่นิ่งแล้วใน cache) แสดงคู่กันผ่าน _drLiveTag()
// เดียวกับที่ DR ใช้ (ไม่แก้ s.chg/CHG% หลัก — ต้องกด "รีเฟรชราคา" เต็มถึงจะนิ่งเป็นทางการ)
async function etfQuickUpdate() {
  if (!_etfData || !_etfData.length) { loadETFPage(); return; }
  const btn  = document.getElementById('etf-live-btn');
  const note = document.getElementById('etf-live-note');
  if (btn) { btn.disabled = true; btn.textContent = '⚡ กำลังดึง...'; }
  if (note) note.textContent = '';
  let ok = 0, fail = 0;
  await Promise.all(_etfData.map(async (s) => {
    try {
      const r = await _fetchTimeout(`/api/live-price/${encodeURIComponent(s.symbol)}`, 15000);
      const d = await r.json();
      if (d.price != null && s.price) {
        // ตลาดปิด (นอกเวลาเทรด/วันหยุด) Yahoo คืนราคาปิดล่าสุดตัวเดิมซ้ำ — ตั้ง live_price
        // เท่ากับ s.price เป๊ะ ถ้าตั้งไปตรงๆ จะขึ้น "⚡ Live +0.00%" เป็นขยะทุกครั้งที่กด
        // นอกเวลาตลาด ทั้งที่ไม่มีอะไรใหม่จริง — โชว์เฉพาะตอนราคาขยับจริงเท่านั้น
        if (Math.abs(d.price - s.price) > 1e-9) {
          s.live_price = d.price;
          s.live_chg   = +((d.price - s.price) / s.price * 100).toFixed(2);
        } else {
          delete s.live_price;
          delete s.live_chg;
        }
        ok++;
      } else fail++;
    } catch { fail++; }
  }));
  if (btn) { btn.disabled = false; btn.textContent = '⚡ อัพเดทราคาล่าสุด'; }
  if (note) note.textContent = `ราคาสด ณ ${new Date().toLocaleTimeString('th-TH')} · สำเร็จ ${ok}/${_etfData.length} ตัว${fail ? ` (พลาด ${fail})` : ''}`;
  renderETFTable();
}

function _updateETFCategoryCounts() {
  if (!_etfData) return;
  document.querySelectorAll('#etf-category-btns .dr-region-count-badge').forEach(el => {
    const cat = el.dataset.etfCat;
    const n = cat === 'ALL' ? _etfData.length : _etfData.filter(s => _etfCategoryMatch(s, cat)).length;
    el.textContent = `(${n})`;
  });
  // ปุ่ม "อื่นๆ" โผล่เฉพาะตอนมี ETF ที่ classify_category() (backend) จัดเข้า OTHER จริง —
  // ปกติไม่ควรมีเลย ถ้าโผล่แปลว่า SET เปลี่ยน underlyingClassName เป็นค่าใหม่ที่ยังไม่รู้จัก
  const otherBtn = document.getElementById('etf-cat-other-btn');
  if (otherBtn) {
    const nOther = _etfData.filter(s => _etfCategoryMatch(s, 'OTHER')).length;
    otherBtn.style.display = nOther > 0 ? '' : 'none';
  }
}

function _etfCategoryMatch(s, cat) {
  if (cat === 'ALL') return true;
  if (cat === 'LNI') return !!s.is_lna;
  return s.category === cat && !s.is_lna;
}

function setETFCategory(c, btn) {
  _etfCategory = c;
  document.querySelectorAll('#etf-category-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (_etfData) renderETFTable();
}

function setETFSort(s, btn) {
  _etfSort = s;
  document.querySelectorAll('#etf-sort-btns .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  if (_etfData) renderETFTable();
}

function filterETF() {
  _etfSearch = document.getElementById('etf-search').value.toLowerCase().trim();
  if (_etfData) renderETFTable();
}

// RS Score เป็น percentile (0–99) ของกลุ่ม non-L&I ทั้งหมด (~10 ตัว คละสินทรัพย์) —
// ตัวเลขเดี่ยวๆ ตีความยากในกลุ่มเล็กขนาดนี้ (เช่น GLD ได้ 0 ทั้งที่ผลตอบแทน 1Y +24.8%
// เพราะบังเอิญโหล่สุดเทียบหุ้นไทยขาขึ้นแรงกว่า) โชว์อันดับ "X/N" คู่กันให้ตีความง่ายขึ้นว่า
// เป็นการเทียบสัมพัทธ์ในกลุ่มเล็ก ไม่ใช่คะแนนความแข็งแกร่งสัมบูรณ์
function _etfRsRankText(s) {
  if (s.rs_score == null || !_etfData) return '';
  const cohort = _etfData.filter(x => !x.is_lna && x.rs_raw != null).sort((a, b) => b.rs_raw - a.rs_raw);
  const idx = cohort.findIndex(x => x.symbol === s.symbol);
  if (idx < 0) return '';
  return `RS ${s.rs_score} — อันดับ ${idx + 1}/${cohort.length} ในกลุ่ม ETF ที่ไม่ใช่ L&I (คละสินทรัพย์ ไม่ใช่ผลตอบแทนสัมบูรณ์)`;
}

function _sortETF(arr) {
  return [...arr].sort((a, b) => {
    if (_etfSort === 'rs_desc')     return (b.rs_score ?? -1)   - (a.rs_score ?? -1);
    if (_etfSort === 'chg_desc')    return (b.chg ?? -999)      - (a.chg ?? -999);
    if (_etfSort === 'chg_asc')     return (a.chg ?? 999)       - (b.chg ?? 999);
    if (_etfSort === 'ret_1m_desc') return (b.ret_1m ?? -999)   - (a.ret_1m ?? -999);
    if (_etfSort === 'ret_1y_desc') return (b.ret_1y ?? -999)   - (a.ret_1y ?? -999);
    if (_etfSort === 'pnav_desc')   return (b.premium_pct ?? -999) - (a.premium_pct ?? -999);
    if (_etfSort === 'mkt_cap')     return (b.aum || 0)          - (a.aum || 0);
    return a.symbol.localeCompare(b.symbol);
  });
}

function setETFView(v, btn) {
  _etfView = v;
  document.querySelectorAll('#page-etf .dr-view-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  const periodRow = document.getElementById('etf-hm-period-row');
  const hint      = document.getElementById('etf-hm-hint');
  if (periodRow) periodRow.style.display = v === 'heatmap' ? '' : 'none';
  if (hint)      hint.style.display      = v === 'heatmap' ? '' : 'none';
  if (_etfData) renderETFTable();
}

const ETF_HM_CFG = {
  chg:        { getV:s=>s.live_chg ?? s.chg, isLive:s=>s.live_chg!=null, clr:v=>_heatColor(v,10), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>4?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง · ⚡ = ราคาสด (กด "อัพเดทราคาล่าสุด" แล้ว)' },
  ret_1w:     { getV:s=>s.ret_1w,     clr:v=>_heatColor(v,10), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>4?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (1 สัปดาห์)' },
  ret_1m:     { getV:s=>s.ret_1m,     clr:v=>_heatColor(v,15), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>6?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (1 เดือน)' },
  ret_3m:     { getV:s=>s.ret_3m,     clr:v=>_heatColor(v,20), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>8?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (3 เดือน)' },
  ret_6m:     { getV:s=>s.ret_6m,     clr:v=>_heatColor(v,25), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>10?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (6 เดือน)' },
  ret_1y:     { getV:s=>s.ret_1y,     clr:v=>_heatColor(v,30), fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>12?'#fff':'var(--text)', hint:'เขียว = ขึ้น · แดง = ลง (1 ปี)' },
  rs_score:   { getV:s=>s.rs_score,   clr:v=>_heatColorRS(v),  fmt:v=>'RS '+Math.round(v), aFmt:v=>'avg RS '+Math.round(v), aPos:v=>v>=50, txt:v=>(v??50)>70||(v??50)<30?'#fff':'var(--text)', hint:'เขียว = RS สูง · แดง = RS ต่ำ — เทียบสัมพัทธ์ในกลุ่ม ETF ที่ไม่ใช่ L&I เท่านั้น (~10 ตัว คละสินทรัพย์) ไม่ใช่ผลตอบแทนสัมบูรณ์' },
  premium_pct: { getV:s=>s.premium_pct, clr:v=>_heatColor(v,3),  fmt:v=>(v>0?'+':'')+v.toFixed(2)+'%', aFmt:v=>'avg '+(v>0?'+':'')+v.toFixed(2)+'%', aPos:v=>v>=0, txt:v=>Math.abs(v??0)>1.5?'#fff':'var(--text)', hint:'เขียว = Premium (ราคา>NAV) · แดง = Discount (ราคา<NAV) — เทียบราคาปิดล่าสุดกับ NAV ล่าสุด (อาจเหลื่อมวัน 1 วัน)' },
};

function setEtfHmPeriod(key, btn) {
  _etfHmPeriod = key;
  document.querySelectorAll('#etf-hm-period-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  if (_etfData) renderETFTable();
}
let _etfHmPeriod = 'chg';

function _renderETFHeatmap(stocks) {
  const wrap = document.getElementById('etf-table-wrap');
  const cfg  = ETF_HM_CFG[_etfHmPeriod] || ETF_HM_CFG.chg;
  const hintEl = document.getElementById('etf-hm-hint');
  if (hintEl) hintEl.textContent = cfg.hint;
  if (!stocks.length) { wrap.innerHTML = '<div class="empty">ไม่พบ ETF ที่ตรงกับเงื่อนไข</div>'; return; }

  const groups = {};
  stocks.forEach(s => {
    const key = s.is_lna ? 'LNI' : (s.category || 'OTHER');
    (groups[key] = groups[key] || []).push(s);
  });
  const order = ['TH_EQ', 'FOREIGN', 'BOND', 'COMMODITY', 'LNI', 'OTHER'];
  const label = { ...ETF_CATEGORY_LABEL, LNI: '⚡ Leveraged/Inverse' };

  wrap.innerHTML = order.filter(k => groups[k]?.length).map(key => {
    const list = groups[key];
    const sorted = [...list].sort((a, b) => (cfg.getV(b) ?? -999) - (cfg.getV(a) ?? -999));
    const withVal = sorted.filter(s => cfg.getV(s) != null);
    const avg = withVal.length ? withVal.reduce((s, x) => s + cfg.getV(x), 0) / withVal.length : null;
    const cells = sorted.map(s => {
      const v      = cfg.getV(s);
      const bg     = cfg.clr(v);
      const txt    = cfg.txt(v);
      const lbl    = v != null ? cfg.fmt(v) : '—';
      const isLive = cfg.isLive ? cfg.isLive(s) : false;
      const nm = _escHtml(s.name_th || '');
      const tip = isLive
        ? `${s.symbol} — ${nm} — ⚡ ราคาสด ${lbl} (เทียบราคาปิดล่าสุด)`
        : `${s.symbol} — ${nm} — ${lbl}`;
      return `<div class="hm-cell" style="background:${bg};color:${txt}" title="${tip}" onclick="openETFChartModal('${s.symbol}')">
        <span style="font-size:11px;font-weight:700;line-height:1">${isLive ? '⚡' : ''}${s.symbol.slice(0,8)}</span>
        <span style="font-size:9px;line-height:1;opacity:0.85">${_drFmtPrice(s.live_price ?? s.price)}</span>
        <span style="font-size:10px;line-height:1;opacity:0.92">${lbl}</span>
      </div>`;
    }).join('');
    const avgClass = avg != null ? (cfg.aPos(avg) ? 'green' : 'red') : 'text2';
    const avgDisp  = avg != null ? cfg.aFmt(avg) : '—';
    return `
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:4px;display:flex;align-items:center;gap:8px">
          ${label[key] || key}
          <span class="${avgClass}">${avgDisp}</span>
          <span class="text2" style="font-size:10px">${list.length} ETF</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:2px">${cells}</div>
      </div>`;
  }).join('');
}

function _etfCardGrid(stocks) {
  return stocks.map(s => {
    const chgCls  = s.chg == null ? '' : (s.chg >= 0 ? 'green' : 'red');
    const chgStr  = s.chg != null ? (s.chg >= 0 ? '+' : '') + s.chg.toFixed(2) + '%' : '—';
    const nameTh  = _escHtml(s.name_th || s.symbol);
    const color   = _drSymColor(s.symbol);
    const initials = s.symbol.slice(0, 4);
    const logoUrl = _etfLogoUrl(s.symbol);
    const logoHtml = `<img src="${logoUrl}" class="dr-card-logo-img" onerror="_drLogoFallback(this)"><div class="dr-card-logo" style="background:${color};display:none">${initials}</div>`;
    const cPct = v => v != null ? `<span class="${v>=0?'green':'red'}">${v>=0?'+':''}${v.toFixed(2)}%</span>` : '—';
    const rsDisp = s.rs_score != null ? `<span class="${rsColor(s.rs_score)}" style="font-weight:700">RS ${s.rs_score}</span>` : '';
    return `<div class="dr-card" onclick="openETFChartModal('${s.symbol}')" style="cursor:pointer">
      <div class="dr-card-header">
        ${logoHtml}
        <div>
          <div class="dr-card-sym" style="color:var(--blue)">${s.symbol}</div>
          <span class="dr-card-exch">${s.is_lna ? '⚡ L&I' : (ETF_CATEGORY_LABEL[s.category] || '')}</span>
        </div>
        ${rsDisp ? `<div style="margin-left:auto;font-size:11px">${rsDisp}</div>` : ''}
        <a class="tv-link" href="https://www.tradingview.com/chart/?symbol=SET:${encodeURIComponent(s.symbol)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView" style="margin-left:${rsDisp?'6px':'auto'}">↗</a>
      </div>
      <div class="dr-card-name">${nameTh}</div>
      <div class="dr-card-price-row">
        <span class="dr-card-price">${_drFmtPrice(s.price)}</span>
        <span class="dr-card-chg ${chgCls}">${chgStr}</span>
      </div>
      ${_drLiveTag(s)}
      <div style="display:flex;gap:6px;font-size:10px;color:var(--text2);margin:3px 0 2px">
        <span>1M ${cPct(s.ret_1m)}</span><span>3M ${cPct(s.ret_3m)}</span><span>1Y ${cPct(s.ret_1y)}</span>
      </div>
      <canvas class="dr-card-chart dr-trend-cv" data-close='${JSON.stringify(s.close100||[])}' width="200" height="52"></canvas>
    </div>`;
  }).join('');
}

function renderETFTable() {
  if (!_etfData) return;
  let stocks = _etfData.filter(s => _etfCategoryMatch(s, _etfCategory));
  if (_etfSearch) {
    stocks = stocks.filter(s =>
      s.symbol.toLowerCase().includes(_etfSearch) ||
      (s.name_th || '').toLowerCase().includes(_etfSearch) ||
      (s.name_en || '').toLowerCase().includes(_etfSearch) ||
      (s.underlying || '').toLowerCase().includes(_etfSearch) ||
      (s.issuer || '').toLowerCase().includes(_etfSearch) ||
      // ค้นคำที่อยู่แค่ในนโยบายการลงทุน เช่น "ทองคำ" (ชื่อกองจริงเป็นภาษาอังกฤษ/ทับศัพท์
      // ไม่มีคำนี้เลย แต่ผู้ใช้คุ้นค้นด้วยคำไทยของสินทรัพย์อ้างอิงมากกว่า)
      (s.investment_policy || '').toLowerCase().includes(_etfSearch)
    );
  }
  stocks = _sortETF(stocks);

  const wrap = document.getElementById('etf-table-wrap');
  // .tbl-scroll-page มีไว้เฉพาะมุมมอง Table เหมือน DR (ดูคอมเมนต์ renderDRTable)
  wrap.classList.toggle('tbl-scroll-page', _etfView === 'table');
  if (!stocks.length) { wrap.innerHTML = '<div class="empty">ไม่พบ ETF ที่ตรงกับเงื่อนไข</div>'; return; }

  if (_etfView === 'cards') {
    wrap.innerHTML = `<div class="dr-card-grid">${_etfCardGrid(stocks)}</div>`;
    requestAnimationFrame(() => _drawAllDRCharts());
    return;
  }
  if (_etfView === 'heatmap') { _renderETFHeatmap(stocks); return; }

  const thead = `<thead><tr>
    <th style="width:100px">Symbol</th>
    <th style="min-width:160px">ชื่อกองทุน</th>
    <th class="r" style="width:76px">ราคา</th>
    <th class="r" style="width:60px">CHG%</th>
    <th class="r" style="width:42px" title="RS Score 0–99 — จัดอันดับเทียบภายในกลุ่ม ETF ที่ไม่ใช่ L&amp;I ด้วยกันเอง (คละสินทรัพย์ หุ้น/ทอง/พันธบัตร) ไม่ได้บอกผลตอบแทนสัมบูรณ์ — กองที่กำไรดีอาจได้ RS ต่ำถ้ากลุ่มอื่นแรงกว่า เพราะกลุ่มมีแค่ ~10 ตัว">RS</th>
    <th class="r" style="width:56px">1W%</th>
    <th class="r" style="width:56px">1M%</th>
    <th class="r" style="width:56px">3M%</th>
    <th class="r" style="width:56px">1Y%</th>
    <th class="r" style="width:76px" title="ส่วนต่างราคาปิดล่าสุดเทียบ NAV ล่าสุด (คำนวณเอง ไม่ใช่ P/NAV เท่าของ SET) — บวก = Premium (แพงกว่ามูลค่าทรัพย์สินสุทธิ) ลบ = Discount · NAV มักช้ากว่าราคา 1 วันทำการ">Premium/NAV</th>
    <th class="r" style="width:64px">NAV</th>
    <th class="r" style="width:64px">Div Yield</th>
    <th class="r" style="width:56px">Mgmt Fee</th>
    <th class="r" style="width:64px" title="มูลค่าทรัพย์สินสุทธิกองทุน (AUM) — ไม่ใช่ market cap ของหน่วยจดทะเบียนที่อาจสูงกว่าเงินจริงที่บริหารอยู่มาก">AUM</th>
    <th class="r" style="width:76px" title="มูลค่าซื้อขายเฉลี่ย 20 วันทำการ (ประมาณจากราคาปิด x ปริมาณเฉลี่ย) — บอกสภาพคล่องจริง ETF บางตัวเทรดเบามากจนซื้อขายจริงได้ยาก">สภาพคล่อง/วัน</th>
    <th style="width:110px">ประเภท</th>
    <th style="width:108px;text-align:center">Trend (100D)</th>
    <th style="width:136px;text-align:center">Pattern (30D)</th>
  </tr></thead>`;

  const rows = stocks.map(s => {
    const chgCls = s.chg == null ? '' : (s.chg >= 0 ? 'green' : 'red');
    const chgStr = s.chg != null ? (s.chg >= 0 ? '+' : '') + s.chg.toFixed(2) + '%' : '—';
    const color    = _drSymColor(s.symbol);
    const initials = s.symbol.slice(0, 4);
    const logoUrl  = _etfLogoUrl(s.symbol);
    const logoHtml = `<img src="${logoUrl}" class="dr-logo-img" onerror="_drLogoFallback(this)"><div class="dr-logo" style="background:${color};display:none">${initials}</div>`;
    const pct = v => v != null
      ? `<span class="${v >= 0 ? 'green' : 'red'}" style="font-size:11px">${v >= 0 ? '+' : ''}${v.toFixed(2)}%</span>`
      : '<span style="color:var(--text2);font-size:11px">—</span>';
    const rsRank = _etfRsRankText(s);
    const rsNum = s.rs_score != null
      ? `<span class="${rsColor(s.rs_score)}" style="font-weight:700;font-size:11px" title="${rsRank}">${s.rs_score}</span>`
      : '<span style="color:var(--text2);font-size:11px">—</span>';
    const catLbl = s.is_lna ? '⚡ L&I' : (ETF_CATEGORY_LABEL[s.category] || '—');

    return `<tr>
      <td>
        <div class="dr-sym-cell" onclick="openETFChartModal('${s.symbol}')" style="cursor:pointer" title="ดูรายละเอียด ${s.symbol}">
          ${logoHtml}
          <span class="dr-sym-text" style="color:var(--blue)">${s.symbol}</span>
          <a class="tv-link" href="https://www.tradingview.com/chart/?symbol=SET:${encodeURIComponent(s.symbol)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView">↗</a>
        </div>
      </td>
      <td style="font-size:11px">${_escHtml(s.name_th || s.symbol)}${s.issuer ? '<br><span style="font-size:10px;color:var(--text2)">' + _escHtml(s.issuer) + '</span>' : ''}</td>
      <td class="r" style="font-size:12px;font-weight:600">${_drFmtPrice(s.price)}${_drLiveTag(s)}</td>
      <td class="r ${chgCls}" style="font-size:12px;font-weight:600">${chgStr}</td>
      <td class="r">${rsNum}</td>
      <td class="r">${pct(s.ret_1w)}</td>
      <td class="r">${pct(s.ret_1m)}</td>
      <td class="r">${pct(s.ret_3m)}</td>
      <td class="r">${pct(s.ret_1y)}</td>
      <td class="r">${pct(s.premium_pct)}</td>
      <td class="r" style="font-size:11px">${_drFmtPrice(s.nav)}</td>
      <td class="r" style="font-size:11px">${s.div_yield != null ? s.div_yield.toFixed(2) + '%' : '—'}</td>
      <td class="r" style="font-size:11px">${s.mgmt_fee != null ? s.mgmt_fee.toFixed(2) + '%' : '—'}</td>
      <td class="r" style="font-size:11px">${_drFmtCap(s.aum)}</td>
      <td class="r" style="font-size:11px">${_drFmtCap(s.value_avg20)}</td>
      <td style="font-size:10.5px;color:var(--text2)">${catLbl}</td>
      <td style="padding:4px 5px">
        <canvas class="dr-trend-cv" data-close='${JSON.stringify(s.close100||[])}' width="104" height="36" style="display:block;width:104px;height:36px"></canvas>
      </td>
      <td style="padding:4px 5px">
        <canvas class="dr-candle-cv" data-ohlc='${JSON.stringify(s.ohlc30||[])}' width="130" height="36" style="display:block;width:130px;height:36px"></canvas>
      </td>
    </tr>`;
  }).join('');

  wrap.innerHTML = `<table class="tbl dr-tbl">${thead}<tbody>${rows}</tbody></table>`;
  requestAnimationFrame(() => _drawAllDRCharts());
}

function _renderETFDescription(s) {
  const box = document.getElementById('cm-desc-box');
  if (!box) return;
  if (!s.investment_policy && !s.market_maker) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.style.display = 'block';
  box.innerHTML =
    (s.investment_policy ? `<div style="font-size:11px;color:var(--text2);margin-bottom:4px">📄 นโยบายการลงทุน (SET.or.th)</div>
    <div style="font-size:12.5px;line-height:1.6">${_escHtml(s.investment_policy)}</div>` : '') +
    // market maker เป็นตัวชี้คุณภาพสภาพคล่อง ETF ที่นักลงทุนใช้จริง (คอยดูแล spread ให้แคบ) —
    // ตัดตัดสินทรัพย์ที่ไม่มี market maker ระบุไว้ก็มักเป็นตัวที่เทรดเบามาก (ดู value_avg20 คู่กัน)
    (s.market_maker ? `<div style="font-size:11px;color:var(--text2);margin:10px 0 4px">🤝 Market Maker</div>
    <div style="font-size:12.5px;line-height:1.6">${_escHtml(s.market_maker)}</div>` : '');
}

function openETFChartModal(sym) {
  const s = (_etfData || []).find(x => x.symbol === sym);
  if (!s) return;

  const titleEl = document.getElementById('cm-title');
  titleEl.textContent = `${s.symbol}  ${s.name_th || ''}`;
  titleEl.title = `${s.symbol}  ${s.name_th || ''}`;
  const catLbl = s.is_lna ? '⚡ Leveraged/Inverse' : (ETF_CATEGORY_LABEL[s.category] || '—');
  document.getElementById('cm-sub').textContent = `${catLbl} · ${s.underlying || ''} · ${s.issuer || ''}`;
  document.getElementById('cm-tv-link').href = `https://www.tradingview.com/chart/?symbol=SET:${encodeURIComponent(s.symbol)}&interval=D`;
  const jittaLink = document.getElementById('cm-jitta-link');
  if (jittaLink) jittaLink.style.display = 'none';   // Jitta วิเคราะห์บริษัท ไม่ใช้กับ ETF/กองทุน

  const mk = (val, lbl, cls = '') =>
    `<div><div class="cm-metric-val ${cls}">${val}</div><div class="cm-metric-lbl">${lbl}</div></div>`;
  const cPct = v => v != null ? (v >= 0 ? '+' : '') + v.toFixed(2) + '%' : '—';
  const pCls = v => v == null ? '' : v >= 0 ? 'green' : 'red';
  const athPctCls = v => v == null ? '' : v >= -5 ? 'green' : v >= -20 ? 'yellow' : 'red';
  const fmtPx = v => v != null ? _drFmtPrice(v) : '—';

  document.getElementById('cm-metrics').innerHTML = [
    mk(_drFmtPrice(s.price) + _drLiveTag(s), 'ราคา'),
    mk(cPct(s.chg),    '1D%', pCls(s.chg)),
    mk(cPct(s.ret_1w), '1W%', pCls(s.ret_1w)),
    mk(cPct(s.ret_1m), '1M%', pCls(s.ret_1m)),
    mk(cPct(s.ret_3m), '3M%', pCls(s.ret_3m)),
    mk(cPct(s.ret_6m), '6M%', pCls(s.ret_6m)),
    mk(cPct(s.ret_1y), '1Y%', pCls(s.ret_1y)),
    mk(cPct(s.ret_ytd), 'YTD%', pCls(s.ret_ytd)),
    // ต่อจากนี้เป็น field ที่ backend คำนวณไว้อยู่แล้ว (_etf_do_rebuild) แต่เดิมไม่เคยโผล่
    // ใน UI เลยสักจุด — รูปแบบเดียวกับที่ DR ใช้ใน openDRChartModal (คงไว้ให้ตรงกัน)
    `<span id="cm-extra-metrics" style="display:contents">` +
      mk(fmtPx(s.high_52w), '52W High', 'text2') +
      mk(fmtPx(s.low_52w),  '52W Low',  'text2') +
      mk(fmtPx(s.ath),      'ATH',      'text2') +
      mk(s.ath_pct != null ? (s.ath_pct >= 0 ? '+' : '') + s.ath_pct.toFixed(2) + '%' : '—', '% จาก ATH', athPctCls(s.ath_pct)) +
    `</span>`,
    mk(_drFmtPrice(s.nav), `NAV${s.nav_date ? ' (' + s.nav_date.slice(0,10) + ')' : ''}`, 'text2'),
    mk(cPct(s.premium_pct), 'Premium/NAV', pCls(s.premium_pct)),
    mk(s.div_yield != null ? s.div_yield.toFixed(2) + '%' : '—', 'Div Yield', 'text2'),
    mk(s.mgmt_fee != null ? s.mgmt_fee.toFixed(2) + '%' : '—', 'ค่าธรรมเนียมจัดการ', 'text2'),
    mk(s.dividend != null ? s.dividend.toFixed(4) + ' บาท' : '—', `ปันผลล่าสุด${s.xd_date ? ' (XD ' + s.xd_date.slice(0,10) + ')' : ''}`, 'text2'),
    mk(_drFmtCap(s.aum), 'AUM', 'text2'),
    mk(_drFmtCap(s.value_avg20), 'สภาพคล่อง/วัน (เฉลี่ย 20 วัน)', 'text2'),
    mk(s.rs_score != null ? s.rs_score : '—', 'RS Score', s.rs_score != null ? rsColor(s.rs_score) : 'text2'),
    mk(`${emaBadge(s.above_ema50)} ${emaBadge(s.above_ema200)}`, 'EMA50 / EMA200'),
  ].join('');

  _cmStock = { ...s, symbol: s.symbol, _isETF: true, _isDR: false };
  _cmSyncPeerTearsheetButtons();
  _cmTf = '1y';
  _cmHistoryData = null;
  _cmVolumeData  = null;
  _cmLivePrice = null; _cmLivePriceSym = null;
  _cmFinLoaded = null;
  // ETF ไม่มีงบการเงิน/สมาชิกดัชนี/factsheet SET รูปแบบหุ้น — ซ่อนปุ่มที่ไม่เกี่ยวข้องทั้งหมด
  ['cm-mode-stocks', 'cm-mode-fin', 'cm-factsheet-link', 'cm-set-link', 'cm-bullpedia-link', 'cm-iaa-link'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
  const fullFinBtn = document.getElementById('cm-fullfin-link');
  if (fullFinBtn) fullFinBtn.style.display = 'none';
  _loadPriceAnalytics(sym, 'cm-lts', () => _cmStock?.symbol === sym, `${sym}.BK`);
  _renderETFDescription(s);
  setCmMode('chart');
  document.querySelectorAll('#chart-modal .filter-btn').forEach(b => b.classList.remove('active'));
  const tfBtn = document.getElementById('cm-tf-1y');
  if (tfBtn) tfBtn.classList.add('active');
  document.getElementById('chart-modal').classList.add('open');
  document.body.style.overflow = 'hidden';

  // price_history มาพร้อมวันที่จริงจาก backend อยู่แล้ว (ต่างจาก DR ที่มีแค่ close100
  // ไม่มีวันที่ ต้องประมาณจากปฏิทิน) ใช้ตรงๆ เป็น preview ระหว่างรอ full history ยาวกว่า
  if (s.price_history?.length) {
    requestAnimationFrame(() => _drawChart(_cmStock, s.price_history));
  }
  _fetchETFFullHistory(sym);
}

async function _fetchETFFullHistory(sym) {
  if (IS_STATIC) { _cmStaticLimitNote(); return; }
  try {
    const r = await _fetchTimeout(`/api/etf-history/${encodeURIComponent(sym)}`, 25000);
    const d = await r.json();
    if (d.error || !d.dates) return;
    const hist = d.dates.map((date, i) => [date, d.closes[i]]);
    _cmHistoryData = hist;
    if (_cmStock?.symbol === sym) _drawChart(_cmStock, hist);
  } catch (e) { console.error('ETF history fetch error:', e); }
}

// ── ETF ROTATION — RRG เทียบค่าเฉลี่ยกลุ่ม ETF (ตัด Leveraged/Inverse ออกจาก cohort) ──
// benchmark เลือกได้ 2 แบบ: 'avg' (ค่าเฉลี่ยกลุ่ม ETF ทั้งหมด — เดิม แต่คละสินทรัพย์ หุ้น/
// ทอง/พันธบัตร ทำให้ตำแหน่งใน quadrant ตีความยาก เช่น GLD/ABFTH ที่มีธรรมชาติต่างจากหุ้นมาก)
// หรือ 'tdex' (เทียบกับ TDEX ตัวแทนหุ้นไทย SET50 ตรงๆ — เห็นชัดว่าชนะ/แพ้ตลาดหุ้นไทยจริงไหม)
let _etfRotTf = 'long';
let _etfRotBenchmark = 'avg';

function _etfRotUpdateSubtitle() {
  const sub = document.getElementById('etfrot-subtitle');
  if (!sub) return;
  const bmLabel = _etfRotBenchmark === 'tdex'
    ? 'TDEX (ETF อ้างอิง SET50)'
    : 'ค่าเฉลี่ยของกลุ่ม ETF ทั้งหมด (คละสินทรัพย์)';
  sub.innerHTML = `RRG ของ ETF ไทยแต่ละตัว — เทียบกับ <b>${bmLabel}</b> (ไม่รวม Leveraged/Inverse) · ` +
    (_etfRotTf === 'short' ? 'แกน X = 1M% Y = 1W% (เทียบ benchmark)' : 'แกน X = 3M% Y = 1M% (เทียบ benchmark)');
}

function setEtfRotTf(tf, btn) {
  _etfRotTf = tf;
  document.querySelectorAll('#etfrot-tf-long,#etfrot-tf-short').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _etfRotUpdateSubtitle();
  renderEtfRotation();
}

function setEtfRotBenchmark(bm, btn) {
  _etfRotBenchmark = bm;
  document.querySelectorAll('#etfrot-bm-avg,#etfrot-bm-tdex').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _etfRotUpdateSubtitle();
  renderEtfRotation();
}

// สภาพคล่องต่ำกว่านี้ (มูลค่าซื้อขายเฉลี่ย 20 วัน, บาท/วัน) ถือว่า return ที่คำนวณได้
// อาจเกิดจากเทรดไม่กี่หน่วย ไม่ใช่แรงซื้อขายจริง — เตือนแทนตัดทิ้ง (cohort เหลือแค่
// ~10 ตัว ตัดแล้วแผนที่โล่งเกินไป)
const ETF_LOW_LIQ_BAHT = 100000;

async function loadEtfRotation() {
  const gate = document.getElementById('etfrot-gate'), body = document.getElementById('etfrot-body');
  if (!_etfData || !_etfData.length) {
    _rotGateState(gate, body, 'loading', 'กำลังดึงข้อมูล ETF...');
    try {
      const d = await _rotFetchJson('/api/etf', 60000);
      if (d.stocks) { _etfData = d.stocks; _etfLoaded = true; _etfTs = d.ts; }
      const rf = document.getElementById('etfrot-refreshing');
      if (rf) rf.style.display = d.refreshing ? '' : 'none';
      if (d.refreshing) _etfPollRefresh(0);
    } catch (e) { _rotGateState(gate, body, 'error', 'โหลดข้อมูล ETF ไม่สำเร็จ: ' + e.message); return; }
  }
  if (!_etfData || !_etfData.length) { _rotGateState(gate, body, 'error', 'ไม่มีข้อมูล ETF'); return; }
  _rotGateState(gate, body, 'ready');
  _etfRotUpdateSubtitle();
  renderEtfRotation();
}

function renderEtfRotation() {
  if (!_etfData || !_etfData.length) return;
  _etfData = _etfData.filter(s => s && typeof s === 'object');   // กัน entry null จาก JSON เพี้ยน
  const isShort = _etfRotTf === 'short';
  const useTdex = _etfRotBenchmark === 'tdex';
  const tdex = useTdex ? _etfData.find(s => s.symbol === 'TDEX') : null;
  // TDEX เองไม่ต้อง plot เป็นจุด (เทียบกับตัวเองจะติดอยู่ (0,0) เสมอ ไม่มีประโยชน์ และ
  // จะบังจุดอื่นที่บังเอิญมาอยู่ตำแหน่งเดียวกันพอดี)
  const valid = _etfData.filter(s => !s.is_lna && (!useTdex || s.symbol !== 'TDEX') && (isShort
    ? (s.ret_1m != null && s.ret_1w != null)
    : (s.ret_3m != null && s.ret_1m != null)));
  if (!valid.length) {
    _rotRenderEmpty('etf-rotation-map', 'etf-rot-legend', 'etfrot-info',
      'ไม่มี ETF ที่มีผลตอบแทนครบตามกรอบเวลาที่เลือก');
    return;
  }
  // ใช้ TDEX เป็นเส้นฐานแทนค่าเฉลี่ยกลุ่ม ถ้าเลือกโหมด 'tdex' — fallback ไปค่าเฉลี่ยกลุ่ม
  // ถ้าหา TDEX ไม่เจอหรือ TDEX เองไม่มีค่าตอนนั้น (กันหน้าจอว่างเปล่าไปเลย)
  const R = _rotRelativeFromBm(f => useTdex && tdex && tdex[f] != null ? tdex[f] : _rotAvg(valid, f));
  const items = valid.map(s => {
    const lowLiq = s.value_avg20 != null && s.value_avg20 < ETF_LOW_LIQ_BAHT;
    const catLbl = ETF_CATEGORY_LABEL[s.category] || s.category || '';
    return {
      name: s.symbol, ind: [catLbl, s.name_th].filter(Boolean).join(' · '),
      ...R.apply(s),
      avg_rs: s.rs_score,
      lowLiq, liqText: lowLiq ? _drFmtCap(s.value_avg20) : undefined,
    };
  });
  const info = document.getElementById('etfrot-info');
  const bmName = useTdex && tdex ? 'TDEX (SET50)' : 'ค่าเฉลี่ยกลุ่ม';
  const tsLabel = _etfTs ? _etfTs.replace('T', ' ').slice(0, 16) : '—';
  if (info) info.textContent = `${valid.length} ETF (ไม่รวม L&I) · benchmark = ${bmName} · ข้อมูล ณ ${tsLabel}` +
    _rotInfoSuffix(isShort, R);
  drawRotationScatter(items, {
    canvasId: 'etf-rotation-map', legendId: 'etf-rot-legend', tf: _etfRotTf, onOpen: openETFChartModal, relative: true,
    relativeLabel: bmName, rsLabel: 'RS', showCount: false,
    excludedTitle: 'ETF ที่ไม่มีค่า return ครบตามกรอบเวลาที่เลือก (ราคาขาดช่วง/ยังเทรดไม่ถึง)', excludedUnit: 'ตัว',
    // cohort ETF ~10 ตัว คละสินทรัพย์ แกว่งแคบกว่าหุ้นรายตัวมาก — cap แกวกว้างเท่า default
    // (±60%) ทำให้จุดทั้งหมดกองอยู่แถบแคบๆ กลางจอ (ดู PLAN/รีวิว 2026-08-03)
    caps: { long: { xLo: -25, xHi: 15, yLo: -10, yHi: 10 }, short: { xLo: -10, xHi: 10, yLo: -6, yHi: 12 } },
  });
}

// ============================================================
// INDICES PAGE
// ============================================================
let _idxData    = null;
let _idxGroup   = 'ALL';
let _idxSortKey = 'ret_1d';
let _idxView    = 'cards';
let _idxFilterReversal = false;

// ── Tooltip system ─────────────────────────────────────────────
function showIdxTT(html, e) {
  const tt = document.getElementById('idx-tt');
  if (!tt) return;
  tt.innerHTML = html; tt.style.display = 'block'; _moveIdxTT(e);
}
// จำนวนหุ้นในตัวหาร RS เปลี่ยนได้ทุกรอบ Refresh (เข้าใหม่/ถูกถอด) — ดึงจาก DATA สดแทน
// hardcode ตัวเลขในข้อความ tooltip ที่จะค้างผิดทันทีที่ universe เปลี่ยน
function _rsSetTip(label) {
  const n = DATA?.stocks?.length ?? '—';
  return `<b>${label}</b><br>Relative Strength เทียบหุ้น SET ${n} ตัว<br>0=อ่อนสุด · 99=แรงสุด<br>≥70 แรง · 40–69 กลาง · &lt;40 อ่อน`;
}
function hideIdxTT() {
  const tt = document.getElementById('idx-tt');
  if (tt) tt.style.display = 'none';
}
function _moveIdxTT(e) {
  const tt = document.getElementById('idx-tt');
  if (!tt) return;
  const vw = window.innerWidth, vh = window.innerHeight;
  let x = e.clientX + 14, y = e.clientY + 14;
  if (x + 270 > vw) x = e.clientX - 274;
  if (y + 160 > vh) y = e.clientY - 164;
  tt.style.left = x + 'px'; tt.style.top = y + 'px';
}
document.addEventListener('mousemove', e => {
  const tt = document.getElementById('idx-tt');
  if (tt && tt.style.display !== 'none') _moveIdxTT(e);
});
// จอสัมผัส: ไม่มี mouseenter -> ใช้ tap เปิด/ปิดแทน (onclick ยิงได้ทั้งคลิกเมาส์และแตะ)
// ทริกเกอร์ tooltip เรียก event.stopPropagation() เอง ทำให้ click นี้ไม่มาถึง document -> tooltip ค้างเปิดจนกว่าจะแตะที่อื่น
document.addEventListener('click', () => hideIdxTT());

// จอสัมผัส: tooltip ที่เดิมเปิดด้วย CSS :hover เท่านั้น (.scr-tip-icon, .regime-wrap)
// ไม่มีทาง trigger ได้เลยบนมือถือ -> เพิ่ม tap toggle ผ่าน class .tt-open (ไม่กระทบ hover เดิมบนเดสก์ท็อป)
document.addEventListener('click', e => {
  const hit = e.target.closest('.scr-tip-icon, .regime-wrap');
  // scope เฉพาะ element ของ delegate นี้เอง — เดิม query ".tt-open" กว้างเกินไป
  // ไปเคลียร์ .tt-open ของ .btn-wrap (ปุ่ม Stage/Quick Update) ที่ผูก tap-toggle แยกไว้ด้วย
  document.querySelectorAll('.scr-tip-icon.tt-open, .regime-wrap.tt-open').forEach(el => { if (el !== hit) el.classList.remove('tt-open'); });
  if (hit) {
    e.stopPropagation();
    if (hit.classList.contains('scr-tip-icon')) _tipIconPosition(hit);
    hit.classList.toggle('tt-open');
  }
});

function toggleIdxReversal(btn) {
  _idxFilterReversal = !_idxFilterReversal;
  btn.classList.toggle('active', _idxFilterReversal);
  renderIdxGrid();
}

function toggleIdxGuide() {
  const box = document.getElementById('idx-guide-box');
  const btn = document.getElementById('idx-guide-btn');
  const open = box.style.display === 'none';
  box.style.display = open ? '' : 'none';
  btn.style.background = open ? '#1f6feb44' : '#1f6feb22';
  const nEl = document.getElementById('idx-guide-nstocks');
  if (nEl && DATA?.stocks?.length) nEl.textContent = DATA.stocks.length;
}

// in-flight guard: Overview เรียก _ensureIdxDataLoaded (ยิง /api/indices ~4.5MB) ตอน boot
// อยู่แล้ว — ถ้าผู้ใช้กด nav "ดัชนีกลุ่ม" หรือคลิกการ์ด (openIdxChartModal) ก่อน request แรก
// เสร็จ จะยิงซ้อนอีกก้อน (โหลด ~9MB) เก็บ promise ก้อนเดียวให้ caller ที่มาทีหลัง await ต่อ
let _idxLoadingPromise = null;
function loadIndicesPage() {
  _idxLoadFF();   // การ์ดเสริม FF-adjusted — แยกอิสระจากกริดหลัก ไม่ต้องรอ/ไม่บล็อคกัน
  if (_idxData) { renderIdxGrid(); return Promise.resolve(); }
  if (_idxLoadingPromise) return _idxLoadingPromise;
  const grid = document.getElementById('idx-grid');
  grid.innerHTML = '<div style="color:var(--text2);padding:20px">กำลังโหลดข้อมูลดัชนี...</div>';
  _idxLoadingPromise = (async () => {
    try {
      const res = await _fetchTimeout('/api/indices?t=' + Date.now());
      const d   = await res.json();
      if (d.error) {
        grid.innerHTML = `<div style="padding:20px">
          <div class="text2" style="margin-bottom:12px">${d.error}</div>
          <button onclick="_idxDownloadFirstTime()" id="idx-first-download-btn" style="padding:6px 16px;border-radius:6px;border:1px solid var(--border);background:#238636;color:#fff;cursor:pointer;font-size:12px">
            ⟳ ดาวน์โหลดข้อมูล (ใช้เวลา ~30 วินาที)
          </button>
        </div>`;
        return;
      }
      _idxData = d;
      _idxDataFails = 0;
      _setIdxUpdated();
      renderIdxGrid();
    } catch(e) {
      grid.innerHTML = `<div style="color:var(--red)">โหลดไม่ได้: ${e.message}</div>`;
    } finally {
      _idxLoadingPromise = null;
    }
  })();
  return _idxLoadingPromise;
}

// ดัชนี Free-Float Adjusted (SET50FF ฯลฯ) จาก SET.or.th โดยตรง real-time — ดู
// PLAN_set_api_expansion.txt งาน #7 · TradingView ไม่มีตระกูลนี้เลย เป็น snapshot
// วันนี้เท่านั้น (ไม่มีประวัติย้อนหลังให้คำนวณ RS/momentum เหมือนการ์ดหลัก) จึงแยก
// กล่องต่างหาก ไม่ผสมกับ idx-grid — โหลดครั้งเดียวต่อเซสชัน (cache ใน _idxFFData)
let _idxFFData = null;
async function _idxLoadFF() {
  const box = document.getElementById('idx-ff-box');
  if (!box) return;
  if (_idxFFData) { _idxRenderFF(_idxFFData); return; }
  try {
    const r = await _fetchTimeout('/api/index-info-list', 15000);
    const d = await r.json();
    if (!d.ok) return;   // เงียบๆ พอ — เป็นข้อมูลเสริม ไม่ควรโชว์ error รบกวนหน้าหลัก
    const ff = (d.items || []).filter(x => (x.symbol || '').endsWith('FF'));
    if (!ff.length) return;
    _idxFFData = ff;
    _idxRenderFF(ff);
  } catch (e) { /* เงียบๆ — ข้อมูลเสริม ไม่กระทบการใช้งานหลัก */ }
}
function _idxRenderFF(ff) {
  const box = document.getElementById('idx-ff-box');
  if (!box) return;
  const asOf = ff[0]?.market_datetime ? new Date(ff[0].market_datetime).toLocaleString('th-TH') : '—';
  const status = ff[0]?.market_status || '—';
  box.style.display = 'block';
  box.innerHTML = `<div class="card" style="padding:14px 16px">
    <div style="font-size:12.5px;font-weight:700;margin-bottom:8px">🌐 ดัชนี Free-Float Adjusted (SET.or.th real-time)
      <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:270px">
        <strong>FF = Free Float Adjusted</strong><br>
        ถ่วงน้ำหนักด้วยหุ้นที่หมุนเวียนซื้อขายจริง ไม่ใช่หุ้นจดทะเบียนทั้งหมด — บริษัทที่ผู้ถือหุ้นใหญ่ถือเยอะจะมีน้ำหนักน้อยลงเทียบดัชนีปกติ สะท้อนสภาพตลาดจริงกว่า<hr>
        <span style="color:var(--text2)">⚠ เป็นข้อมูล snapshot วันนี้จาก SET.or.th โดยตรง ไม่มีประวัติย้อนหลัง (ต่างจากการ์ด/heatmap ด้านล่างที่ใช้ TradingView ซึ่งไม่มีดัชนีตระกูลนี้)</span>
      </div></span>
    </div>
    <div style="display:flex;gap:16px;flex-wrap:wrap">
      ${ff.map(x => {
        const clr = (x.percent_change ?? 0) > 0 ? 'var(--green)' : (x.percent_change ?? 0) < 0 ? 'var(--red)' : 'var(--text2)';
        return `<div style="min-width:110px">
          <div style="font-size:11px;color:var(--text2)">${x.symbol}</div>
          <div style="font-size:16px;font-weight:700">${x.last != null ? x.last.toFixed(2) : '—'}</div>
          <div style="font-size:11px;font-weight:600;color:${clr}">${x.percent_change != null ? (x.percent_change >= 0 ? '+' : '') + x.percent_change.toFixed(2) + '%' : '—'}</div>
        </div>`;
      }).join('')}
    </div>
    <div style="font-size:10px;color:var(--text2);margin-top:8px">ตลาด: ${status} · ข้อมูล ณ ${asOf}</div>
  </div>`;
}

// ยังไม่เคยมี indices_cache.json บนเครื่องนี้เลย — เดิมปุ่มนี้แค่ยิง GET /api/indices
// ซ้ำซึ่งได้ 404 วนไปตลอด เพราะไฟล์ยังไม่มีให้อ่าน ต้องสั่ง POST /api/indices-refresh
// ให้ backend ไปดึงจาก TradingView จริงก่อน (full_refresh=True, ~20 ปีย้อนหลัง)
async function _idxDownloadFirstTime() {
  const btn = document.getElementById('idx-first-download-btn');
  const grid = document.getElementById('idx-grid');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ กำลังดาวน์โหลด... (~30 วินาที)'; }
  try {
    const res = await fetch('/api/indices-refresh', { method: 'POST' });
    const d   = await res.json();
    if (d.error) throw new Error(d.error);
    // TradingView ล่ม → _fetch_indices_tv คืน fetched==0 ไม่เขียนไฟล์ ตอบ {ok:false,
    // warning:'ดึงไม่สำเร็จ N/N ดัชนี'} โดยไม่มี key 'error' — เดิม fall through ไป
    // loadIndicesPage() ที่ได้ 404 ซ้ำ แล้วโชว์ปุ่ม download เดิมเงียบๆ เหมือนไม่มีอะไรเกิดขึ้น
    if (d.ok === false) throw new Error(d.warning || 'ดึงข้อมูลจาก TradingView ไม่สำเร็จ — ลองใหม่อีกครั้ง');
    _idxData = null; _idxDataDone = false; _idxDataFails = 0;   // บังคับ loadIndicesPage + _ensureIdxDataLoaded ดึง /api/indices ใหม่
    await loadIndicesPage();
  } catch (e) {
    grid.innerHTML = `<div style="padding:20px">
      <div style="color:var(--red);margin-bottom:12px">ดาวน์โหลดไม่สำเร็จ: ${e.message}</div>
      <button onclick="_idxDownloadFirstTime()" style="padding:6px 16px;border-radius:6px;border:1px solid var(--border);background:#238636;color:#fff;cursor:pointer;font-size:12px">
        ⟳ ลองใหม่
      </button>
    </div>`;
  }
}

function _setIdxUpdated() {
  const sample = _idxData && Object.values(_idxData)[0];
  const el = document.getElementById('idx-updated');
  if (el && sample?.updated_at) el.textContent = 'อัปเดต: ' + sample.updated_at;
}


function setIdxGroup(g, btn) {
  _idxGroup = g;
  document.querySelectorAll('#idx-group-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderIdxGrid();
}

function setIdxSort(key, btn) {
  _idxSortKey = key;
  document.querySelectorAll('#idx-sort-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  // sync active button by id when called programmatically
  const byId = document.getElementById('idx-sort-btn-' + key);
  if (byId && byId !== btn) { btn.classList.remove('active'); byId.classList.add('active'); }
  renderIdxGrid();
}

function setIdxView(view, btn) {
  _idxView = view;
  document.querySelectorAll('#idx-view-cards,#idx-view-heatmap,#idx-view-compare').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  // sort label หายไปเมื่อ heatmap (period ทำหน้าที่แทน)
  const lbl = document.getElementById('idx-sort-label');
  if (lbl) lbl.textContent = view === 'heat' ? 'สี/เรียงตาม:' : 'เรียงตาม:';
  // มุมมอง "เปรียบเทียบ Sector" ใช้ dataset/แถวปุ่มเรียงคนละชุดกับราคาดัชนี (revenue/profit/roe
  // ไม่ใช่ ret_1d/RS/Momentum) — สลับซ่อนแถวควบคุมที่ไม่เกี่ยวข้องแทนการซ้อนกันให้งง
  const isCompare = view === 'compare';
  document.getElementById('idx-sort-row').style.display = isCompare ? 'none' : '';
  document.getElementById('idx-cmp-sort-row').style.display = isCompare ? 'flex' : 'none';
  document.getElementById('idx-group-row').style.display = isCompare ? 'none' : '';
  document.getElementById('idx-cmp-chart-wrap').style.display = isCompare ? 'block' : 'none';
  renderIdxGrid();
}

function setCmpSort(key, btn) {
  _cmpSortKey = key;
  document.querySelectorAll('#idx-cmp-sort-row .filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _renderSectorCmpGrid();
}

// ── มุมมอง "เปรียบเทียบ Sector" — รวมรายได้/กำไร/ROE รายไตรมาสกลุ่มตาม Sector (SET) ──
let _sectorCmpData    = null;
let _sectorCmpLoading = false;
let _cmpSortKey       = 'revenue';
let _sectorCmpChart   = null;

// กราฟใช้ metric เดียวกับปุ่ม "เรียงตาม" ของการ์ดด้านล่างเสมอ (_cmpSortKey ตัวเดียวกัน) — ตั้งใจ
// ไม่แยกปุ่มควบคุมของกราฟออกมาต่างหาก เพราะเคยลองแยกแล้วผู้ใช้กดปุ่มเรียงตามคาดว่ากราฟต้องเปลี่ยน
// ตามด้วยแต่ไม่เปลี่ยน (กราฟฟังปุ่มตัวเอง) ทำให้ดูเหมือนกราฟค้าง/บั๊ก
const CMP_CHART_CONFIG = {
  revenue:     { title: '📊 รายได้รวมตาม Sector — เรียงตามขนาดตลาด',                    label: 'รายได้รวม',      percent: false, colorBySign: false },
  revenue_yoy: { title: '📊 เติบโตรายได้ YoY ตาม Sector — ไตรมาสนี้ sector ไหนโตเด่น',   label: 'รายได้โต YoY %', percent: true,  colorBySign: true },
  revenue_qoq: { title: '📊 เติบโตรายได้ QoQ ตาม Sector — เทียบไตรมาสก่อนหน้าติดกัน',    label: 'รายได้โต QoQ %', percent: true,  colorBySign: true },
  profit_yoy:  { title: '📊 เติบโตกำไรสุทธิ YoY ตาม Sector — ไตรมาสนี้ sector ไหนโตเด่น', label: 'กำไรโต YoY %',   percent: true,  colorBySign: true },
  profit_qoq:  { title: '📊 เติบโตกำไรสุทธิ QoQ ตาม Sector — เทียบไตรมาสก่อนหน้าติดกัน',  label: 'กำไรโต QoQ %',   percent: true,  colorBySign: true },
  roe:         { title: '📊 ROE ตาม Sector',                                             label: 'ROE %',          percent: true,  colorBySign: true },
  profit:      { title: '📊 กำไรสุทธิรวมตาม Sector',                                     label: 'กำไรสุทธิรวม',   percent: false, colorBySign: true },
};

// กราฟแท่งแนวนอนต่อ sector เรียงมาก->น้อย — ตอบคำถาม "ไตรมาสนี้ sector ไหนโตเด่น/ใหญ่สุด/ฯลฯ"
// ในทีเดียว ต่างจากการ์ดด้านล่างที่ต้องไล่อ่านทีละใบ (การ์ดยังโชว์รายละเอียด/coverage ต่อ)
function _renderSectorCmpChart() {
  if (!_sectorCmpData) return;
  const canvas = document.getElementById('idx-cmp-chart');
  if (!canvas) return;
  if (_sectorCmpChart) { _sectorCmpChart.destroy(); _sectorCmpChart = null; }

  const cfg = CMP_CHART_CONFIG[_cmpSortKey] || CMP_CHART_CONFIG.revenue;
  const titleEl = document.getElementById('idx-cmp-chart-title');
  if (titleEl) titleEl.textContent = cfg.title;

  const rows = (_sectorCmpData.sectors || [])
    .filter(s => s[_cmpSortKey] != null)
    .sort((a, b) => b[_cmpSortKey] - a[_cmpSortKey]);
  if (!rows.length) {
    canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
    return;
  }

  // ความสูง fix เดิม (380px) บีบให้ Chart.js ต้อง autoSkip label แกน y ทิ้งเมื่อจำนวน sector
  // เยอะ (เจอบั๊ก 2026-08-17 sector หายจาก list แม้แท่งยังโชว์ครบ) ปรับความสูงตามจำนวนแถวแทน
  const boxEl = document.getElementById('idx-cmp-chart-box');
  if (boxEl) boxEl.style.height = Math.max(380, rows.length * 24) + 'px';

  const fmtTHB = v => Math.round(v / 1e6).toLocaleString('en-US') + ' ลบ.';
  const fmtVal = v => cfg.percent ? `${v > 0 ? '+' : ''}${v.toFixed(1)}%` : fmtTHB(v);

  let axisMin, axisMax;
  if (cfg.percent) {
    // sector ฐานเล็ก (เช่น mai) โต/ลด % เป็นร้อยเป็นพันได้จากฐานปีก่อนใกล้ศูนย์ — ปล่อยแกนขยาย
    // ตามค่าสุดโต่งจะบีบแท่งอื่นๆ จนเทียบกันไม่ได้เลย (ผิดจุดประสงค์กราฟนี้) ครอบแกนไว้ที่ ~4 เท่า
    // ของ median magnitude (พอเห็นภาพรวมกลุ่มปกติ) แท่งที่เกินโดนตัดที่ขอบแกน แต่ tooltip ยังโชว์
    // ค่าจริงตอน hover — เมตริกระดับ (รายได้/กำไรรวม บาท) ไม่มีปัญหานี้ ปล่อย auto-scale ตามปกติ
    const mags = rows.map(s => Math.abs(s[_cmpSortKey])).sort((a, b) => a - b);
    const median = mags[Math.floor(mags.length / 2)] || 0;
    const cap = Math.min(300, Math.max(60, Math.ceil(median * 4 / 10) * 10));
    axisMin = -cap; axisMax = cap;
  }

  _sectorCmpChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: rows.map(s => s.sector),
      datasets: [{
        label: cfg.label,
        data: rows.map(s => s[_cmpSortKey]),
        backgroundColor: rows.map(s => !cfg.colorBySign ? '#58a6ff' : (s[_cmpSortKey] >= 0 ? '#3fb950' : '#f85149')),
      }]
    },
    options: {
      indexAxis: 'y',
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: ctx => `${cfg.label}: ${fmtVal(ctx.parsed.x)}` } },
      },
      scales: {
        x: { min: axisMin, max: axisMax, ticks: { callback: v => cfg.percent ? v + '%' : fmtTHB(v) }, grid: { color: 'rgba(139,148,158,0.15)' } },
        y: { grid: { display: false }, ticks: { font: { size: 11 }, autoSkip: false } },
      }
    }
  });
}

async function renderSectorCompare() {
  if (_sectorCmpData) { _renderSectorCmpGrid(); return; }
  if (_sectorCmpLoading) return;
  _sectorCmpLoading = true;
  const grid = document.getElementById('idx-grid');
  grid.style.display = 'block';
  grid.innerHTML = '<div style="color:var(--text2);padding:20px">กำลังรวมข้อมูลรายได้/กำไรทั้งตลาด... (ครั้งแรกอาจช้า ~20-30 วิ)</div>';
  try {
    const res = await _fetchTimeout('/api/sector-compare?t=' + Date.now(), 45000,
      'หมดเวลารอข้อมูล (เกิน 45 วิ) — เซิร์ฟเวอร์กำลังรวมข้อมูลรายได้/กำไรทั้งตลาด (ครั้งแรกหลัง restart/sync อาจช้า) ลองใหม่อีกครั้ง');
    const d = await res.json();
    if (d.error) throw new Error(d.error);
    _sectorCmpData = d;
    _renderSectorCmpGrid();
  } catch (e) {
    grid.innerHTML = `<div style="color:var(--red)">โหลดไม่ได้: ${e.message}</div>`;
  } finally {
    _sectorCmpLoading = false;
  }
}

function _renderSectorCmpGrid() {
  if (!_sectorCmpData) return;
  _renderSectorCmpChart();
  const grid = document.getElementById('idx-grid');
  grid.style.display = 'grid';
  grid.style.gridTemplateColumns = 'repeat(auto-fill,minmax(260px,1fr))';
  grid.style.gap = '12px';

  const fmtTHB = v => v == null ? '—' : Math.round(v / 1e6).toLocaleString('en-US') + ' ลบ.';
  const fmtPct = v => v == null ? '—' : `<span style="color:${v>0?'var(--green)':v<0?'var(--red)':'var(--text2)'}">${v>0?'+':''}${v.toFixed(1)}%</span>`;

  const sorted = [...(_sectorCmpData.sectors || [])].sort((a,b) => (b[_cmpSortKey] ?? -Infinity) - (a[_cmpSortKey] ?? -Infinity));
  const qParts = (_sectorCmpData.quarter || '').split('-');
  const quarterLabel = qParts.length === 2 ? `Q${qParts[1]}/${qParts[0].slice(-2)}` : '—';

  const cards = sorted.map(s => {
    const total = s.profit_stocks + s.loss_stocks;
    const profitPct = total ? (s.profit_stocks / total * 100) : 0;
    const covN = s.reported ?? s.count, covTotal = s.total ?? covN;
    const covMissing = covTotal - covN;
    const covColor = covMissing > 0 ? 'var(--yellow)' : 'var(--text2)';
    const missingList = (s.missing_symbols || []).join(', ');
    return `<div class="idx-card" onclick="openSectorCompareModal('${s.sector.replace(/'/g, "\\'")}')">
      <div class="idx-card-name">${s.sector}</div>
      <div class="idx-card-sym">${quarterLabel}
        <span style="color:${covColor};margin-left:6px">📄 ${covN}/${covTotal}</span>
      </div>
      <div style="font-size:11px;color:var(--text2);margin-top:8px">รายได้รวม</div>
      <div style="font-size:14px;font-weight:700">${fmtTHB(s.revenue)}</div>
      <div style="font-size:11px;font-weight:400;color:var(--text2)">${fmtPct(s.revenue_yoy)} YoY &nbsp;·&nbsp; ${fmtPct(s.revenue_qoq)} QoQ</div>
      <div style="font-size:11px;color:var(--text2);margin-top:6px">กำไรรวม</div>
      <div style="font-size:14px;font-weight:700">${fmtTHB(s.profit)}</div>
      <div style="font-size:11px;font-weight:400;color:var(--text2)">${fmtPct(s.profit_yoy)} YoY &nbsp;·&nbsp; ${fmtPct(s.profit_qoq)} QoQ</div>
      <div style="display:flex;gap:12px;margin-top:8px;font-size:11px;color:var(--text2)">
        <div>ROE <b style="color:var(--text)">${s.roe != null ? s.roe.toFixed(1)+'%' : '—'}</b></div>
        <div>NPM <b style="color:var(--text)">${s.npm != null ? s.npm.toFixed(1)+'%' : '—'}</b></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--text2);margin-top:8px">
        <span>กำไร/ขาดทุน</span><span>${s.profit_stocks}/${s.loss_stocks}</span>
      </div>
      <div style="height:5px;border-radius:3px;overflow:hidden;background:var(--red);margin-top:3px">
        <div style="height:100%;width:${profitPct}%;background:var(--green)"></div>
      </div>
      <div style="font-size:10px;color:var(--text2);margin-top:6px">สัดส่วนกำไรตลาด ${s.profit_share_pct != null ? s.profit_share_pct.toFixed(1)+'%' : '—'}</div>
      ${covMissing > 0 ? `<div style="font-size:10px;color:var(--yellow);margin-top:6px;padding-top:6px;border-top:1px solid var(--border)">⚠ ยังไม่มีงบ ${covMissing} บริษัท: ${missingList}</div>` : ''}
    </div>`;
  }).join('');

  grid.innerHTML = cards || '<div class="text2">ไม่มีข้อมูล</div>';
}

const isReversal = (i) => i.ret_1m > 0 && (i.ret_6m == null || i.ret_6m < 15) && (i.mom == null || i.mom > 1);

function renderIdxHeatmap(items) {
  const grid = document.getElementById('idx-grid');
  grid.style.display = 'block';
  grid.style.gridTemplateColumns = '';
  grid.style.gap = '';
  const pct = (v) => v == null ? '—' : (v > 0 ? '+' : '') + v.toFixed(2) + '%';
  const groupOrder = ['SET_INDICES','SET_INDUSTRY','SET_SECTORS','MAI_INDUSTRY'];
  const groupLabel = {
    SET_INDICES:  'SET Indices', SET_INDUSTRY: 'Industry Group',
    SET_SECTORS:  'Sector (SET)', MAI_INDUSTRY: 'mai'
  };

  const byGroup = {};
  items.forEach(idx => {
    const g = idx.group || 'OTHER';
    if (!byGroup[g]) byGroup[g] = [];
    byGroup[g].push(idx);
  });

  const v = (idx) => idx[_idxSortKey] ?? null;
  const isRS  = _idxSortKey === 'rs_set';
  const isMom = _idxSortKey === 'mom';
  const cap = { ret_1d:10, ret_1w:15, ret_1m:20, ret_3m:30, ret_6m:40, ret_1y:50, mom:15 }[_idxSortKey] || 20;

  const html = groupOrder.filter(g => byGroup[g]?.length).map(g => {
    const sorted = [...byGroup[g]].sort((a,b) => (v(b)??-999)-(v(a)??-999));
    const cells = sorted.map(idx => {
      const val = v(idx);
      const bg  = isRS ? _heatColorRS(val) : _heatColor(val, cap);
      const txtCol = isRS
        ? ((val??50) > 70 || (val??50) < 30 ? '#fff' : 'var(--text)')
        : (Math.abs(val??0) > cap*0.6 ? '#fff' : 'var(--text)');
      const label = isRS ? (val != null ? 'RS '+val : '—')
                  : isMom ? (val != null ? (val>0?'+':'')+val.toFixed(1) : '—')
                  : pct(val);
      const revDot = isReversal(idx) ? ' 🔄' : '';
      return `<div onclick="openIdxChartModal('${idx.sym}')"
        title="${idx.name} ${label}"
        style="background:${bg};color:${txtCol};border-radius:6px;padding:10px 8px;cursor:pointer;
               min-width:80px;text-align:center;transition:opacity .15s"
        onmouseover="this.style.opacity='.8'" onmouseout="this.style.opacity='1'">
        <div style="font-size:11px;font-weight:700;margin-bottom:3px">${idx.sym.replace(/^\^/,'').replace(/\.BK$/,'')}${revDot}</div>
        <div style="font-size:10px;color:${txtCol};opacity:.85;margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:80px">${idx.name}</div>
        <div style="font-size:12px;font-weight:700">${label}</div>
      </div>`;
    }).join('');
    const validVals = sorted.filter(x=>v(x)!=null);
    const avg = validVals.length ? validVals.reduce((s,x)=>s+v(x),0) / validVals.length : null;
    const avgStr = avg == null ? '—' : isRS ? 'RS ' + Math.round(avg) : pct(avg);
    const avgCls = avg == null ? '' : isRS ? (avg >= 50 ? 'green' : 'red') : (avg >= 0 ? 'green' : 'red');
    return `<div style="margin-bottom:20px">
      <div style="font-size:11px;font-weight:600;color:var(--text2);margin-bottom:8px;display:flex;align-items:center;gap:8px">
        ${groupLabel[g]}
        <span class="${avgCls}">${avgStr}</span>
        <span class="text2" style="font-size:10px">${sorted.length} ดัชนี</span>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px">${cells}</div>
    </div>`;
  }).join('');

  document.getElementById('idx-grid').innerHTML = html || '<div class="text2">ไม่มีข้อมูล</div>';
}

function renderIdxGrid() {
  if (_idxView === 'compare') { renderSectorCompare(); return; }
  if (!_idxData) {
    // ยังไม่มีข้อมูล (first-run ไม่มี cache / โหลดล้ม) แล้วผู้ใช้เพิ่งสลับกลับจากมุมมอง
    // "⚖ เปรียบเทียบ Sector" ที่ renderSectorCompare เขียนทับ #idx-grid ไปแล้ว —
    // เดิม return เปล่าทิ้งการ์ด compare ค้าง + ปุ่ม download หายถาวร (reload เท่านั้นถึงกลับมา)
    // เรียก loadIndicesPage ใหม่เพื่อคืนปุ่มดาวน์โหลด/ข้อความสถานะ (มี in-flight guard กันยิงซ้อน)
    loadIndicesPage();
    return;
  }
  let items = Object.values(_idxData);
  if (_idxGroup !== 'ALL') items = items.filter(x => x.group === _idxGroup);

  // คำนวณ Momentum Score = ret_1m − (ret_6m ÷ 6) — ถ้าไม่มี ret_6m (ดัชนีประวัติสั้น) เดิม
  // fallback เป็น ret_1m เต็มๆ ซึ่งไม่ใช่ momentum score จริง (ไม่ได้หักส่วน long-term avg
  // ออก) ทำให้ค่าเว่อร์กว่าดัชนีอื่นที่คำนวณสูตรเต็มได้ — คืน null (โชว์ "—") ปลอดภัยกว่า
  items = items.map(i => ({
    ...i,
    mom: (i.ret_1m != null && i.ret_6m != null)
      ? +((i.ret_1m - i.ret_6m / 6).toFixed(2))
      : null
  }));

  // Filter กลับตัว
  if (_idxFilterReversal) {
    items = items.filter(i =>
      i.ret_1m != null && i.ret_1m > 0 &&
      (i.ret_6m == null || i.ret_6m < 15) &&
      (i.mom == null || i.mom > 1)
    );
  }

  items.sort((a,b) => (b[_idxSortKey]??-999) - (a[_idxSortKey]??-999));

  if (_idxView === 'heat') { renderIdxHeatmap(items); return; }

  // cards view — reset grid layout
  const grid = document.getElementById('idx-grid');
  grid.style.display = 'grid';
  grid.style.gridTemplateColumns = 'repeat(auto-fill,minmax(260px,1fr))';
  grid.style.gap = '12px';

  const pct = (v) => v == null ? '—'
    : `<span class="${v>0?'green':v<0?'red':'text2'}">${v>0?'+':''}${v.toFixed(2)}%</span>`;

  // RS trend arrow จาก rs_history — เทียบตาม "วันที่จริง" ห่างกัน ~28 วัน ไม่ใช่นับ
  // ถอยหลัง 4 รายการตายตัว: backfill ชุดแรกเติมรายสัปดาห์ แต่หลังจากนั้นสะสม
  // วันละ 1 รายการทุก Quick Update — นับ index ถอยหลัง 4 จะกลายเป็นแค่ ~4 วันทำการ
  // เงียบๆ เมื่อข้อมูลสะสมเกินชุด backfill แรก ทำให้ป้าย "4 สัปดาห์" ไม่ตรงจริง
  const rsTrend = (hist) => {
    if (!hist || hist.length < 2) return '<span style="color:var(--text2);font-size:11px">ยังไม่มีประวัติ</span>';
    const lastEntry = hist[hist.length - 1];
    const lastTime  = new Date(lastEntry.date).getTime();
    const targetTime = lastTime - 28 * 86400000;   // ~4 สัปดาห์ก่อน
    let prevEntry = hist[0];
    for (let i = hist.length - 2; i >= 0; i--) {
      if (new Date(hist[i].date).getTime() <= targetTime) { prevEntry = hist[i]; break; }
    }
    const last = lastEntry.rs;
    const prev = prevEntry.rs;
    const diff = last - prev;
    const daysSpan = Math.round((lastTime - new Date(prevEntry.date).getTime()) / 86400000);
    const spanLbl = daysSpan >= 25 ? '4 สัปดาห์' : `${daysSpan} วัน`;
    if (diff >= 5)  return `<span style="color:var(--green);font-weight:700" title="RS ขึ้น +${diff} ใน${spanLbl}">↑ +${diff}</span>`;
    if (diff <= -5) return `<span style="color:var(--red);font-weight:700"   title="RS ลง ${diff} ใน${spanLbl}">↓ ${diff}</span>`;
    return `<span style="color:#e3b341;font-weight:700" title="RS ทรงตัว (${diff>=0?'+':''}${diff}) ใน${spanLbl}">→ ${diff>=0?'+':''}${diff}</span>`;
  };

  // Momentum bar
  const momBar = (m) => {
    if (m == null) return '<span class="text2">—</span>';
    const c = m > 3 ? 'var(--green)' : m > 0 ? '#3fb950' : m > -3 ? '#e3b341' : 'var(--red)';
    const w = Math.min(100, Math.abs(m) * 5);
    const sign = m > 0 ? '+' : '';
    return `<div>
      <span style="font-size:12px;font-weight:700;color:${c}">${sign}${m.toFixed(1)}</span>
      <div style="height:3px;border-radius:2px;background:var(--border);margin-top:2px">
        <div style="height:3px;border-radius:2px;width:${w}%;background:${c};transition:width .3s"></div>
      </div>
    </div>`;
  };

  // RS bar
  const rsBar2 = (v) => {
    if (v == null) return '<span class="text2">—</span>';
    const c = v >= 70 ? 'var(--green)' : v >= 40 ? '#e3b341' : 'var(--red)';
    return `<div>
      <span style="font-size:12px;font-weight:700;color:${c}">${v}</span>
      <div style="height:3px;border-radius:2px;background:var(--border);margin-top:2px">
        <div style="height:3px;border-radius:2px;width:${v}%;background:${c};transition:width .3s"></div>
      </div>
    </div>`;
  };

  const cards = items.map(idx => {
    const spark = `<canvas class="idx-spark" id="idxspark_${idx.sym.replace(/[^a-z0-9]/gi,'_')}"></canvas>`;
    const revBadge = isReversal(idx)
      ? `<span style="font-size:9px;background:#1f6feb33;color:#58a6ff;border:1px solid #1f6feb;border-radius:4px;padding:1px 5px;margin-left:6px"
           onmouseenter="showIdxTT('<b>🔄 สัญญาณกลับตัว</b><br>• 1M% &gt; 0 ✓ เดือนนี้เริ่มเป็นบวก<br>• 6M% &lt; 15 ✓ ยังไม่วิ่งไปไกล<br>• Momentum &gt; 1 ✓ momentum กำลังเร่ง<br><br>ตรวจสอบกราฟว่าตัดขึ้น EMA50 หรือยัง',event)" onmouseleave="hideIdxTT()"
           onclick="event.stopPropagation(); showIdxTT('<b>🔄 สัญญาณกลับตัว</b><br>• 1M% &gt; 0 ✓ เดือนนี้เริ่มเป็นบวก<br>• 6M% &lt; 15 ✓ ยังไม่วิ่งไปไกล<br>• Momentum &gt; 1 ✓ momentum กำลังเร่ง<br><br>ตรวจสอบกราฟว่าตัดขึ้น EMA50 หรือยัง',event)">🔄 กลับตัว</span>`
      : '';
    return `
      <div class="idx-card" onclick="openIdxChartModal('${idx.sym}')">
        <div style="display:flex;align-items:center;justify-content:space-between">
          <div class="idx-card-sym">${idx.sym}</div>${revBadge}
        </div>
        <div class="idx-card-name" title="${idx.name}" style="display:flex;align-items:center;gap:4px">
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${idx.name}</span>
          <a class="tv-link" href="https://www.tradingview.com/chart/?symbol=${idxToTVSym(idx.sym)}&interval=D" target="_blank" rel="noopener" onclick="event.stopPropagation()" title="ดูใน TradingView" style="flex-shrink:0">↗</a>
        </div>
        <div class="idx-card-val">${idx.last != null ? idx.last.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) : '—'}</div>
        ${spark}
        <div class="idx-rets">
          <div class="idx-ret-cell"><div class="idx-ret-lbl">1D%</div><div class="idx-ret-val">${pct(idx.ret_1d)}</div></div>
          <div class="idx-ret-cell"><div class="idx-ret-lbl">1W%</div><div class="idx-ret-val">${pct(idx.ret_1w)}</div></div>
          <div class="idx-ret-cell"><div class="idx-ret-lbl">1M%</div><div class="idx-ret-val">${pct(idx.ret_1m)}</div></div>
          <div class="idx-ret-cell"><div class="idx-ret-lbl">3M%</div><div class="idx-ret-val">${pct(idx.ret_3m)}</div></div>
          <div class="idx-ret-cell"><div class="idx-ret-lbl">6M%</div><div class="idx-ret-val">${pct(idx.ret_6m)}</div></div>
          <div class="idx-ret-cell"><div class="idx-ret-lbl">1Y%</div><div class="idx-ret-val">${pct(idx.ret_1y)}</div></div>
        </div>
        <div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border);display:grid;grid-template-columns:1fr 1fr;gap:8px">
          <div onmouseenter="showIdxTT('<b>Momentum Score</b><br>สูตร: 1M% − (6M%÷6)<br>บวกมาก = momentum เพิ่งเร่งขึ้น<br>ลบมาก = momentum กำลังชะลอ<br><br>&gt;3 แรงมาก · 1–3 ดีขึ้น · &lt;0 ชะลอ',event)" onmouseleave="hideIdxTT()"
            onclick="event.stopPropagation(); showIdxTT('<b>Momentum Score</b><br>สูตร: 1M% − (6M%÷6)<br>บวกมาก = momentum เพิ่งเร่งขึ้น<br>ลบมาก = momentum กำลังชะลอ<br><br>&gt;3 แรงมาก · 1–3 ดีขึ้น · &lt;0 ชะลอ',event)">
            <div class="idx-ret-lbl">Momentum</div>
            ${momBar(idx.mom)}
          </div>
          <div onmouseenter="showIdxTT(_rsSetTip('RS (vs SET)'),event)" onmouseleave="hideIdxTT()"
            onclick="event.stopPropagation(); showIdxTT(_rsSetTip('RS (vs SET)'),event)">
            <div class="idx-ret-lbl">RS SET</div>
            ${rsBar2(idx.rs_set)}
          </div>
        </div>
        <div style="margin-top:6px;display:flex;align-items:center;gap:6px"
          onmouseenter="showIdxTT('<b>RS Trend</b><br>ทิศทาง RS เทียบ 4 สัปดาห์ก่อน<br>↑ RS กำลังดีขึ้น (สัญญาณดี)<br>→ RS ทรงตัว<br>↓ RS กำลังอ่อนลง<br><br>ข้อมูลสะสมหลังกด Quick Update ทุกครั้ง',event)" onmouseleave="hideIdxTT()"
          onclick="event.stopPropagation(); showIdxTT('<b>RS Trend</b><br>ทิศทาง RS เทียบ 4 สัปดาห์ก่อน<br>↑ RS กำลังดีขึ้น (สัญญาณดี)<br>→ RS ทรงตัว<br>↓ RS กำลังอ่อนลง<br><br>ข้อมูลสะสมหลังกด Quick Update ทุกครั้ง',event)">
          <div class="idx-ret-lbl">RS Trend</div>
          ${rsTrend(idx.rs_history)}
        </div>
      </div>`;
  }).join('');

  document.getElementById('idx-grid').innerHTML = cards || '<div class="text2">ไม่มีข้อมูล</div>';

  requestAnimationFrame(() => {
    items.forEach(idx => {
      const id  = 'idxspark_' + idx.sym.replace(/[^a-z0-9]/gi,'_');
      const cvs = document.getElementById(id);
      if (cvs && idx.closes?.length > 1) _drawIdxSpark(cvs, idx.closes.slice(-60), idx.ret_1d);
    });
  });
}

function _drawIdxSpark(canvas, closes, ret1d) {
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth || 232, H = 48;
  canvas.width  = W * dpr; canvas.height = H * dpr;
  canvas.style.width = W+'px'; canvas.style.height = H+'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const mn = Math.min(...closes), mx = Math.max(...closes);
  const rng = mx - mn || 1;
  const toX = i => i / (closes.length-1) * W;
  const toY = v => H - (v - mn) / rng * (H-4) - 2;
  const color = ret1d >= 0 ? '#3fb950' : '#f85149';
  ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.lineJoin = 'round';
  ctx.beginPath();
  closes.forEach((v,i) => i===0 ? ctx.moveTo(toX(i),toY(v)) : ctx.lineTo(toX(i),toY(v)));
  ctx.stroke();
  const grad = ctx.createLinearGradient(0,0,0,H);
  grad.addColorStop(0, ret1d>=0 ? 'rgba(63,185,80,0.25)' : 'rgba(248,81,73,0.25)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grad;
  ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
}

function openIdxChartModal(sym) {
  // ถ้ายังไม่มีข้อมูล indices ให้โหลดก่อนแล้วค่อยเปิด modal
  if (!_idxData) {
    loadIndicesPage().then(() => { if (_idxData) openIdxChartModal(sym); });
    return;
  }
  const idx = _idxData?.[sym];
  if (!idx || !idx.closes?.length) {
    // ไม่มีกราฟ index → เปิด sector modal (รายการหุ้น) แทน
    const sectorName = (IDX_TO_SECTOR[sym] || [])[0];
    if (sectorName) { openSectorModal(sectorName); return; }
    window.open(`https://www.tradingview.com/chart/?symbol=${idxToTVSym(sym)}&interval=D`, '_blank');
    return;
  }

  // build [[date,price],...] history
  const hist = idx.dates.map((d,i) => [d, idx.closes[i]]);

  // fake stock object — enough for _drawChart
  const fakeStock = {
    symbol: sym,
    name:   idx.name,
    price_history: hist,
    ath: null,
    _isIndex: true,
  };

  // populate modal header
  const _cmTitleEl3 = document.getElementById('cm-title');
  _cmTitleEl3.textContent = idx.name;
  _cmTitleEl3.title = idx.name;
  document.getElementById('cm-sub').textContent   = sym;
  document.getElementById('cm-tv-link').href = `https://www.tradingview.com/chart/?symbol=${idxToTVSym(sym)}&interval=D`;
  const jittaLinkIdx = document.getElementById('cm-jitta-link');
  if (jittaLinkIdx) jittaLinkIdx.style.display = 'none';   // ดัชนี/กลุ่มอุตสาหกรรม — Jitta ไม่มี factsheet รายดัชนี

  const mk = (val, lbl, cls='') =>
    `<div><div class="cm-metric-val ${cls}">${val}</div><div class="cm-metric-lbl">${lbl}</div></div>`;
  const pp = (v) => v==null ? '—'
    : `<span class="${v>0?'green':v<0?'red':''}">${v>0?'+':''}${v.toFixed(2)}%</span>`;
  document.getElementById('cm-metrics').innerHTML = [
    mk(idx.last?.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) ?? '—', 'ราคา'),
    mk(pp(idx.ret_1d), '1D%'),
    mk(pp(idx.ret_1w), '1W%'),
    mk(pp(idx.ret_1m), '1M%'),
    mk(pp(idx.ret_3m), '3M%'),
    mk(pp(idx.ret_6m), '6M%'),
    mk(pp(idx.ret_1y), '1Y%'),
  ].join('');

  // hide งบการเงิน, show/hide หุ้นในกลุ่ม based on mapping
  const finBtn    = document.getElementById('cm-mode-fin');
  const stocksBtn = document.getElementById('cm-mode-stocks');
  if (finBtn)    finBtn.style.display    = 'none';
  if (stocksBtn) stocksBtn.style.display = IDX_TO_SECTOR[sym]?.length ? '' : 'none';
  const fullFinLinkIdx = document.getElementById('cm-fullfin-link');
  if (fullFinLinkIdx) fullFinLinkIdx.style.display = 'none';   // ดัชนี/กลุ่มอุตสาหกรรม — ไม่มีงบการเงินรายดัชนี
  const fsLinkIdx = document.getElementById('cm-factsheet-link');
  if (fsLinkIdx) fsLinkIdx.style.display = 'none';
  const setLinkIdx = document.getElementById('cm-set-link');
  if (setLinkIdx) setLinkIdx.style.display = 'none';
  const bpLinkIdx = document.getElementById('cm-bullpedia-link');
  if (bpLinkIdx) bpLinkIdx.style.display = 'none';
  const iaaLinkIdx = document.getElementById('cm-iaa-link');
  if (iaaLinkIdx) iaaLinkIdx.style.display = 'none';

  // set chart state
  _cmStock       = fakeStock;
  _cmTf          = '1y';
  _cmHistoryData = hist;   // full history already loaded
  _cmVolumeData  = null;
  _cmFinLoaded   = null;
  _cmLivePrice = null; _cmLivePriceSym = null;   // ดัชนีไม่มีราคาสดจาก Yahoo แบบเดียวกับหุ้น

  setCmMode('chart');
  document.querySelectorAll('#chart-modal .filter-btn').forEach(b => b.classList.remove('active'));
  const tfBtn = document.getElementById('cm-tf-1y');
  if (tfBtn) tfBtn.classList.add('active');

  document.getElementById('chart-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
  requestAnimationFrame(() => _drawChart(fakeStock, hist));
}


