// ═══════════════════════════════════════════════
//  STOCK VALUATION (cross-sectional)
// ═══════════════════════════════════════════════
let _valStockData = null;
let _valStockInflight = null;   // กัน fetch ซ้ำเมื่อหลาย consumer (ตาราง sector + ค้นหา + โซน σ) เรียกพร้อมกันตอน _valStockData ยัง null
let _valSecSort = 'pe';

async function _loadStockValStats() {
  if (_valStockData) return _valStockData;
  if (_valStockInflight) return _valStockInflight;
  _valStockInflight = (async () => {
    const r = await _fetchTimeout('/api/stock-valuation-stats?t=' + Date.now(), 25000,
      'หมดเวลารอข้อมูล PE/PBV รายตัว (เกิน 25 วิ) ลองใหม่อีกครั้ง');
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const d = await r.json();
    if (d.error) throw new Error(d.error);
    _valStockData = d;
    return d;
  })();
  try {
    return await _valStockInflight;
  } finally {
    _valStockInflight = null;
  }
}

function _zColor(z) {
  if (z === null || z === undefined) return 'rgba(255,255,255,0.25)';
  if (z >  2) return '#dc503c';
  if (z >  1) return '#dca032';
  if (z > -1) return '#c8d0dc';
  if (z > -2) return '#96c850';
  return '#3ab464';
}
function _zLabel(z, isPE) {
  if (z === null || z === undefined) return '—';
  const s = (z >= 0 ? '+' : '') + z.toFixed(2) + 'σ';
  if (isPE) {
    if (z >  2) return s + ' แพงผิดปกติ';
    if (z >  1) return s + ' แพง';
    if (z > -1) return s + ' ปานกลาง';
    if (z > -2) return s + ' ถูก';
    return s + ' ถูกผิดปกติ';
  } else {
    if (z >  2) return s + ' Overvalued';
    if (z >  1) return s + ' สูง';
    if (z > -1) return s + ' ปานกลาง';
    if (z > -2) return s + ' Undervalued';
    return s + ' Undervalued มาก';
  }
}

function _sdBar(val, avg, std, min, max) {
  // draw a mini bar showing where val sits between avg-2σ and avg+2σ
  const lo = avg - 2*std, hi = avg + 2*std;
  const pct = Math.max(0, Math.min(100, (val - lo) / (hi - lo) * 100));
  const z = std ? (val - avg)/std : 0;
  const col = _zColor(z);
  return `<div style="position:relative;background:var(--bg-card2);border-radius:3px;height:5px;width:80px;display:inline-block;vertical-align:middle">
    <div style="position:absolute;left:50%;top:0;width:1px;height:100%;background:rgba(255,255,255,0.2)"></div>
    <div style="position:absolute;left:${pct}%;top:-1px;width:6px;height:7px;border-radius:2px;background:${col};transform:translateX(-50%)"></div>
  </div>`;
}

async function searchValStock(query) {
  query = (query || '').trim().toUpperCase();
  const el = document.getElementById('val-stock-result');
  if (!query) { el.innerHTML = ''; return; }

  el.innerHTML = '<span style="color:var(--muted);font-size:12px">กำลังโหลด...</span>';
  let data;
  try {
    data = await _loadStockValStats();
  } catch(e) {
    el.innerHTML = `<span style="color:var(--red)">โหลดข้อมูลไม่สำเร็จ: ${e.message}<br>ลอง restart Flask server แล้วกดค้นหาใหม่</span>`;
    return;
  }
  const stock = data.stocks.find(s => s.symbol === query || s.symbol === query + '.BK');
  if (!stock) {
    // fuzzy match
    const matches = data.stocks.filter(s =>
      s.symbol.includes(query) || (s.name||'').toUpperCase().includes(query)
    ).slice(0, 5);
    if (!matches.length) { el.innerHTML = `<span style="color:var(--muted)">ไม่พบหุ้น "${_escHtml(query)}"</span>`; return; }
    el.innerHTML = `<div style="color:var(--muted);font-size:12px;margin-bottom:6px">พบ ${matches.length} รายการ:</div>` +
      matches.map(m => `<button onclick="document.getElementById('val-stock-input').value='${_escJsAttr(m.symbol)}';searchValStock('${_escJsAttr(m.symbol)}')"
        style="background:var(--bg-card2);border:1px solid var(--border);color:#c8d0dc;padding:4px 10px;border-radius:4px;cursor:pointer;margin:2px;font-size:12px">
        ${_escHtml(m.symbol)} <span style="color:var(--muted)">${_escHtml((m.name||'').slice(0,30))}</span>
      </button>`).join('');
    return;
  }

  const sec = data.sectors[stock.sector] || {};
  const mkt = data.market;

  function metricCard(label, val, mktDist, secDist, isPE) {
    if (!val) return `<div style="padding:12px;background:var(--bg-card2);border-radius:8px;min-width:160px">
      <div style="font-size:11px;color:var(--muted)">${label}</div>
      <div style="color:var(--muted)">—</div></div>`;
    const zMkt = mktDist && mktDist.std ? (val - mktDist.avg)/mktDist.std : null;
    const zSec = secDist && secDist.std ? (val - secDist.avg)/secDist.std : null;
    return `<div style="padding:14px;background:var(--bg-card2);border-radius:8px;min-width:180px">
      <div style="font-size:11px;color:var(--muted);margin-bottom:4px">${label}</div>
      <div style="font-size:22px;font-weight:700">${val.toFixed(2)}x</div>
      <div style="margin-top:8px">
        <div style="font-size:11px;color:var(--muted)">เทียบตลาด (${mktDist?mktDist.n:'?'} หุ้น)</div>
        <div style="font-size:13px;font-weight:600;color:${_zColor(zMkt)}">${_zLabel(zMkt, isPE)}</div>
        ${mktDist ? _sdBar(val, mktDist.avg, mktDist.std, mktDist.min, mktDist.max) : ''}
        <div style="font-size:10px;color:var(--muted);margin-top:2px">avg=${mktDist?mktDist.avg:'?'}x ±σ=${mktDist?mktDist.std:'?'}</div>
      </div>
      <div style="margin-top:10px">
        <div style="font-size:11px;color:var(--muted)">เทียบ ${_escHtml(stock.sector)} (${secDist?secDist.n:'?'} หุ้น)</div>
        <div style="font-size:13px;font-weight:600;color:${_zColor(zSec)}">${_zLabel(zSec, isPE)}</div>
        ${secDist ? _sdBar(val, secDist.avg, secDist.std, secDist.min, secDist.max) : ''}
        <div style="font-size:10px;color:var(--muted);margin-top:2px">avg=${secDist?secDist.avg:'?'}x ±σ=${secDist?secDist.std:'?'}</div>
      </div>
    </div>`;
  }

  el.innerHTML = `
    <div style="font-weight:600;font-size:14px;margin-bottom:10px">
      ${_escHtml(stock.symbol)} <span style="font-size:12px;color:var(--muted)">${_escHtml(stock.name||'')}</span>
      <span style="font-size:11px;color:var(--muted);margin-left:8px">Sector: ${_escHtml(stock.sector)}</span>
    </div>
    <div style="display:flex;gap:12px;flex-wrap:wrap">
      ${metricCard('P/E Ratio', stock.pe, mkt.pe, sec.pe, true)}
      ${metricCard('P/BV Ratio', stock.pbv, mkt.pbv, sec.pbv, false)}
    </div>`;
}

function setValSecSort(by, btn) {
  _valSecSort = by;
  // scope แค่ปุ่มเรียง sector table ของตัวเอง — เดิมกวาดทั้งหน้า Valuation ซึ่งมี
  // ปุ่มกลุ่มอื่นอีกเพียบ (ช่วงเวลา, metric P/E-P/BV, เทียบตลาด/sector, โซน σ)
  // ทำให้ไฮไลต์พวกนั้นหายทั้งที่ตัวกรองยังทำงานอยู่ (แบบเดียวกับที่ setValPeriod เคยแก้ไปแล้ว)
  document.querySelectorAll('#page-valuation .filter-btn[onclick^="setValSecSort"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderValSectorTable();
}

// ── SD Zone Browser ──────────────────────────────────────────
let _vsdMetric = 'pe';   // 'pe' | 'pbv'
let _vsdScope  = 'mkt';  // 'mkt' | 'sec'
let _vsdZone   = null;

function resetVsdZone() {
  _vsdZone = null;
  document.querySelectorAll('#page-valuation .card .filter-btn[onclick^="showVsdZone"]').forEach(b => b.classList.remove('active'));
  document.getElementById('vsd-result').innerHTML = '';
}

function setVsdMetric(m, btn) {
  _vsdMetric = m;
  document.getElementById('vsd-pe-btn').classList.toggle('active',  m === 'pe');
  document.getElementById('vsd-pbv-btn').classList.toggle('active', m === 'pbv');
  if (_vsdZone) showVsdZone(_vsdZone);
}
function setVsdScope(s, btn) {
  _vsdScope = s;
  document.getElementById('vsd-mkt-btn').classList.toggle('active', s === 'mkt');
  document.getElementById('vsd-sec-btn').classList.toggle('active', s === 'sec');
  if (_vsdZone) showVsdZone(_vsdZone);
}

async function showVsdZone(zone, btn) {
  _vsdZone = zone;
  // highlight active zone button — ผูกไฮไลต์กับค่า zone ไม่ใช่ตัว btn ที่ส่งมา เพราะ
  // setVsdMetric/setVsdScope เรียก showVsdZone(_vsdZone) ต่อโดยไม่มี btn ทำให้ไฮไลต์
  // โซนหายทั้งที่ตัวกรองยังทำงานอยู่
  document.querySelectorAll('#page-valuation .card .filter-btn[onclick^="showVsdZone"]').forEach(b => b.classList.remove('active'));
  const zoneBtn = btn || document.querySelector(`#page-valuation .card .filter-btn[onclick^="showVsdZone('${zone}'"]`);
  if (zoneBtn) zoneBtn.classList.add('active');

  const el = document.getElementById('vsd-result');
  el.innerHTML = '<span style="color:var(--muted);font-size:12px">กำลังโหลด...</span>';

  let data;
  try { data = await _loadStockValStats(); }
  catch(e) { el.innerHTML = `<span style="color:var(--red)">${e.message}</span>`; return; }

  // zone ranges: zone key → [lo, hi) exclusive on hi
  const ranges = {
    '+3': [2,    Infinity],
    '+2': [1,    2],
    '+1': [0,    1],
    '-1': [-1,   0],
    '-2': [-2,  -1],
    '-3': [-Infinity, -2],
  };
  const [lo, hi] = ranges[zone] || [0, 1];

  const zoneColors = {
    '+3':'#dc503c', '+2':'#dca032', '+1':'#e0d060',
    '-1':'#96c850', '-2':'#3ab464', '-3':'#1a9455',
  };
  const zoneLabels = {
    '+3':'แพงผิดปกติมาก (> +2σ)', '+2':'แพงผิดปกติ (+1σ ถึง +2σ)',
    '+1':'แพงกว่าค่าเฉลี่ย (0 ถึง +1σ)',
    '-1':'ถูกกว่าค่าเฉลี่ย (-1σ ถึง 0)', '-2':'ถูกผิดปกติ (-2σ ถึง -1σ)',
    '-3':'ถูกมากผิดปกติ (< -2σ)',
  };

  const zField = `${_vsdMetric}_z_${_vsdScope}`;
  const valField = _vsdMetric;

  // filter & sort
  let stocks = data.stocks.filter(s => {
    const z = s[zField];
    return z !== null && z !== undefined && z >= lo && z < hi;
  });
  // sort: positive zones → highest z first (แพงสุด); negative zones → lowest z first (ถูกสุด)
  stocks.sort((a,b) => zone.startsWith('+')
    ? (b[zField] ?? 0) - (a[zField] ?? 0)
    : (a[zField] ?? 0) - (b[zField] ?? 0));

  if (!stocks.length) {
    el.innerHTML = `<div style="color:var(--muted);font-size:12px;padding:8px 0">ไม่พบหุ้นใน zone นี้</div>`;
    return;
  }

  const scopeLabel = _vsdScope === 'mkt' ? 'เทียบตลาดรวม' : 'เทียบ Sector';
  const col = zoneColors[zone];

  // group by sector for easy reading
  const bySector = {};
  stocks.forEach(s => {
    const sec = s.sector || 'Other';
    (bySector[sec] = bySector[sec] || []).push(s);
  });

  el.innerHTML = `
    <div style="margin-bottom:10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
      <span style="font-size:13px;font-weight:700;color:${col}">${zoneLabels[zone]}</span>
      <span style="font-size:11px;color:var(--muted)">${_vsdMetric.toUpperCase()} ${scopeLabel} · ${stocks.length} หุ้น</span>
    </div>
    ${Object.entries(bySector).sort((a,b) => b[1].length - a[1].length).map(([sec, ss]) => `
      <div style="margin-bottom:12px">
        <div style="font-size:11px;color:var(--muted);font-weight:600;margin-bottom:5px;
          border-bottom:1px solid rgba(255,255,255,0.06);padding-bottom:3px">
          ${sec} <span style="font-weight:400">(${ss.length})</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:5px">
          ${ss.map(s => {
            const z = s[zField];
            const v = s[valField];
            const zStr = z !== null ? (z >= 0 ? '+' : '') + z.toFixed(2) + 'σ' : '—';
            const tip = _escHtml(`${s.name||s.symbol} | ${_vsdMetric.toUpperCase()}=${v != null ? v.toFixed(2)+'x' : '—'} | z=${zStr}`);
            return `<button
              onclick="openChartModal('${_escJsAttr(s.symbol)}')"
              title="${tip}"
              style="background:var(--bg-card2);border:1px solid ${col}30;border-radius:6px;
                     padding:5px 10px;cursor:pointer;font-size:12px;color:#c8d0dc;
                     display:flex;flex-direction:column;align-items:flex-start;gap:1px;
                     transition:border-color .15s;min-width:80px"
              onmouseover="this.style.borderColor='${col}';this.style.background='${col}18'"
              onmouseout="this.style.borderColor='${col}30';this.style.background='var(--bg-card2)'">
              <span style="font-weight:700;font-size:13px">${_escHtml(s.symbol)}</span>
              <span style="color:${col};font-size:10px">${zStr}</span>
              <span style="color:var(--muted);font-size:10px">${v != null ? v.toFixed(2)+'x' : '—'}</span>
            </button>`;
          }).join('')}
        </div>
      </div>
    `).join('')}`;
}

let _valSecModalSort = null;   // { key, dir } — null = default (PE z-score, ถูกสุดก่อน)
let _valSecModalLastName = null;
function valSecModalSortBy(key) {
  if (_valSecModalSort && _valSecModalSort.key === key) _valSecModalSort.dir *= -1;
  else _valSecModalSort = { key, dir: (key === 'symbol' || key === 'name') ? -1 : 1 };
  if (_valSecModalLastName) openValSectorModal(_valSecModalLastName);
}
function _valSecModalSortArrow(key) {
  if (!_valSecModalSort || _valSecModalSort.key !== key) return '';
  return _valSecModalSort.dir === 1 ? '▼' : '▲';
}

async function openValSectorModal(secName) {
  _valSecModalLastName = secName;
  let data;
  try { data = await _loadStockValStats(); }
  catch(e) {
    document.getElementById('modal-title').textContent = secName;
    document.getElementById('modal-abbr').textContent  = '';
    document.querySelector('#sector-modal .modal-body').innerHTML =
      `<span style="color:var(--red)">โหลดข้อมูลไม่สำเร็จ: ${e.message}</span>`;
    document.getElementById('sector-modal').classList.add('open');
    document.body.style.overflow = 'hidden';
    return;
  }
  const secStats = data.sectors[secName] || {};
  let stocks = data.stocks.filter(s => s.sector === secName);
  // ต้อง join กับ DATA.stocks ก่อนเรียง เพราะ rs/price/1D%/1M% อยู่คนละ object (main)
  // ใช้ _stockBySym() (Map ที่ prebuild ไว้แล้ว) แทน DATA.stocks.find() ต่อการเปรียบเทียบ+ต่อแถว — เดิม O(n²) บน sector ใหญ่
  const mainOf = s => _stockBySym(s.symbol) || null;
  if (_valSecModalSort) {
    const key = _valSecModalSort.key, dir = _valSecModalSort.dir;
    const getters = {
      symbol: s => s.symbol || '',
      name: s => s.name || '',
      pe: s => s.pe ?? -Infinity,
      pbv: s => s.pbv ?? -Infinity,
      rs: s => mainOf(s)?.rs_score ?? -Infinity,
      price: s => mainOf(s)?.price ?? -Infinity,
      ret_1d: s => mainOf(s)?.ret_1d ?? -Infinity,
      ret_1m: s => mainOf(s)?.ret_1m ?? -Infinity,
    };
    const get = getters[key] || getters.pe;
    stocks = stocks.slice().sort((a,b) => {
      const va = get(a), vb = get(b);
      if (typeof va === 'string') return dir === 1 ? vb.localeCompare(va) : va.localeCompare(vb);
      return dir === 1 ? vb - va : va - vb;
    });
  } else {
    stocks = stocks.slice().sort((a,b) => (a.pe_z_sec ?? 999) - (b.pe_z_sec ?? 999)); // cheapest first
  }

  // patch the existing modal with valuation-focused content
  document.getElementById('modal-title').textContent = secName;
  document.getElementById('modal-abbr').textContent  = `${stocks.length} หุ้น`;

  // stats bar: sector PE/PBV summary
  const pe  = secStats.pe;
  const pbv = secStats.pbv;
  document.getElementById('modal-stats').innerHTML = [
    pe  ? `<div class="modal-stat"><div class="modal-stat-val">${pe.median.toFixed(1)}x</div><div class="modal-stat-lbl">PE Median</div></div>` : '',
    pe  ? `<div class="modal-stat"><div class="modal-stat-val">${pe.avg.toFixed(1)}±${pe.std.toFixed(1)}</div><div class="modal-stat-lbl">PE avg±σ</div></div>` : '',
    pbv ? `<div class="modal-stat"><div class="modal-stat-val">${pbv.median.toFixed(1)}x</div><div class="modal-stat-lbl">PBV Median</div></div>` : '',
    pbv ? `<div class="modal-stat"><div class="modal-stat-val">${pbv.avg.toFixed(1)}±${pbv.std.toFixed(1)}</div><div class="modal-stat-lbl">PBV avg±σ</div></div>` : '',
    `<div class="modal-stat"><div class="modal-stat-val">${stocks.length}</div><div class="modal-stat-lbl">หุ้น</div></div>`,
  ].join('');

  function zBadge(z) {
    if (z === null || z === undefined) return '<span style="color:var(--muted)">—</span>';
    const col = _zColor(z);
    const s = (z >= 0 ? '+' : '') + z.toFixed(2) + 'σ';
    return `<span style="color:${col};font-weight:600;font-size:11px">${s}</span>`;
  }
  function valCell(val, z) {
    if (!val) return '<td class="r" style="color:var(--muted)">—</td>';
    return `<td class="r">${val.toFixed(2)}<br>${zBadge(z)}</td>`;
  }

  // Replace modal table with valuation columns
  const modalBody = document.querySelector('#sector-modal .modal-body');
  modalBody.innerHTML = `
    <table class="tbl tbl-clickable" style="width:100%">
      <thead><tr>
        <th style="cursor:pointer" onclick="valSecModalSortBy('symbol')">Symbol${colTipIcon('symbol')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='symbol'?' on':''}">${_valSecModalSortArrow('symbol')}</span></th>
        <th style="cursor:pointer" onclick="valSecModalSortBy('name')">ชื่อ${colTipIcon('name')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='name'?' on':''}">${_valSecModalSortArrow('name')}</span></th>
        <th class="r" style="color:#dca032;cursor:pointer" title="P/E ของหุ้น เทียบกับค่าเฉลี่ย sector — ต่ำกว่า -1σ = ถูกผิดปกติ, สูงกว่า +1σ = แพงผิดปกติ" onclick="valSecModalSortBy('pe')">PE<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='pe'?' on':''}">${_valSecModalSortArrow('pe')}</span><br><span style="font-size:9px;color:var(--muted)">vs sector</span></th>
        <th class="r" style="color:#5ab4ff;cursor:pointer" title="P/BV ของหุ้น เทียบกับค่าเฉลี่ย sector — ต่ำกว่า -1σ = ถูกผิดปกติ, สูงกว่า +1σ = แพงผิดปกติ" onclick="valSecModalSortBy('pbv')">PBV<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='pbv'?' on':''}">${_valSecModalSortArrow('pbv')}</span><br><span style="font-size:9px;color:var(--muted)">vs sector</span></th>
        <th class="r" style="cursor:pointer" onclick="valSecModalSortBy('rs')">RS${colTipIcon('rs_score')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='rs'?' on':''}">${_valSecModalSortArrow('rs')}</span></th>
        <th class="r" style="cursor:pointer" onclick="valSecModalSortBy('price')">ราคา${colTipIcon('price')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='price'?' on':''}">${_valSecModalSortArrow('price')}</span></th>
        <th class="r" style="cursor:pointer" onclick="valSecModalSortBy('ret_1d')">1D%${colTipIcon('ret_1d')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='ret_1d'?' on':''}">${_valSecModalSortArrow('ret_1d')}</span></th>
        <th class="r" style="cursor:pointer" onclick="valSecModalSortBy('ret_1m')">1M%${colTipIcon('ret_1m')}<span class="sort-ind${_valSecModalSort&&_valSecModalSort.key==='ret_1m'?' on':''}">${_valSecModalSortArrow('ret_1m')}</span></th>
      </tr></thead>
      <tbody>
      ${stocks.map(s => {
        const main = _stockBySym(s.symbol) || null;
        const rs    = main?.rs_score;
        const price = main?.price;
        const r1d   = main?.ret_1d;
        const r1m   = main?.ret_1m;
        const rsCol = rs >= 80 ? 'color:#3ab464' : rs >= 60 ? 'color:#96c850' : rs ? 'color:var(--muted)' : '';
        const r1dCol = r1d > 0 ? 'color:#3ab464' : r1d < 0 ? 'color:#dc503c' : '';
        const r1mCol = r1m > 0 ? 'color:#3ab464' : r1m < 0 ? 'color:#dc503c' : '';
        return `<tr>
          <td><strong class="sym-link" onclick="closeModal();openChartModal('${_escJsAttr(s.symbol)}')">${_escHtml(s.symbol)}</strong>${tvLink(s.symbol)}</td>
          <td style="font-size:11px;color:var(--text2);max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(s.name||'')}</td>
          ${valCell(s.pe, s.pe_z_sec)}
          ${valCell(s.pbv, s.pbv_z_sec)}
          <td class="r" style="${rsCol}">${rs ?? '—'}</td>
          <td class="r">${price != null ? price.toFixed(2) : '—'}</td>
          <td class="r" style="${r1dCol}">${r1d != null ? (r1d>0?'+':'')+r1d.toFixed(2)+'%' : '—'}</td>
          <td class="r" style="${r1mCol}">${r1m != null ? (r1m>0?'+':'')+r1m.toFixed(2)+'%' : '—'}</td>
        </tr>`;
      }).join('')}
      </tbody>
    </table>
    <div style="font-size:10px;color:var(--muted);padding:8px 0">
      ${_valSecModalSort ? 'z-score เทียบกับ sector เดียวกัน · คลิกหัวคอลัมน์เพื่อจัดเรียงใหม่' : 'เรียงตาม PE z-score (ถูกสุดก่อน) · z-score เทียบกับ sector เดียวกัน'}
    </div>`;

  document.getElementById('sector-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

async function renderValSectorTable() {
  const el = document.getElementById('val-sector-table');
  if (!el) return;
  el.innerHTML = '<span style="color:var(--muted);font-size:12px">กำลังโหลด...</span>';
  let data;
  try {
    data = await _loadStockValStats();
  } catch(e) {
    el.innerHTML = `<span style="color:var(--red)">โหลดไม่สำเร็จ: ${e.message} — กรุณา restart Flask</span>`;
    return;
  }

  let rows = Object.entries(data.sectors).map(([sec, v]) => ({ sec, ...v }));
  if (_valSecSort === 'pe')  rows.sort((a,b) => (a.pe?.avg||999) - (b.pe?.avg||999));
  if (_valSecSort === 'pbv') rows.sort((a,b) => (a.pbv?.avg||999) - (b.pbv?.avg||999));
  if (_valSecSort === 'n')   rows.sort((a,b) => b.n_stocks - a.n_stocks);

  const mkt = data.market;
  const legendEl = document.getElementById('val-sector-legend');
  if (legendEl) legendEl.innerHTML = (mkt.pe || mkt.pbv)
    ? `<span style="color:#3ab464">●</span> ต่ำกว่า -1σ ตลาด (ถูกชัดเจน) &nbsp;
       <span style="color:#e0d060">●</span> ต่ำกว่าเฉลี่ยตลาด &nbsp;
       <span style="color:#dca032">●</span> สูงกว่าเฉลี่ยตลาด &nbsp;
       <span style="color:#dc503c">●</span> สูงกว่า +1σ ตลาด (แพงชัดเจน)`
    : '';

  // เทียบ avg ของ sector กับค่าเฉลี่ย/แบนด์ ±1σ ของตลาดรวม เพื่อไฮไลต์ sector ที่ถูก/แพงกว่าตลาด
  function avgVsMkt(avg, mktRef) {
    if (!mktRef) return { style: '', title: '' };
    if (avg < mktRef.bands['-1σ']) return { style: 'color:#3ab464;font-weight:700', title: 'ต่ำกว่า -1σ ของตลาดรวม — ถูกกว่าตลาดชัดเจน' };
    if (avg < mktRef.avg)          return { style: 'color:#e0d060;font-weight:700', title: 'ต่ำกว่าค่าเฉลี่ยตลาดรวม' };
    if (avg > mktRef.bands['+1σ']) return { style: 'color:#dc503c;font-weight:700', title: 'สูงกว่า +1σ ของตลาดรวม — แพงกว่าตลาดชัดเจน' };
    if (avg > mktRef.avg)          return { style: 'color:#dca032;font-weight:700', title: 'สูงกว่าค่าเฉลี่ยตลาดรวม' };
    return { style: '', title: '' };
  }

  function bandCell(dist, mktRef) {
    if (!dist) return '<td colspan="4" style="color:var(--muted);text-align:center">—</td>';
    const {avg, std, median} = dist;
    const b = dist.bands;
    const av = avgVsMkt(avg, mktRef);
    return `
      <td style="text-align:right;${av.style}" title="${av.title}">${avg.toFixed(1)}<span style="color:var(--muted);font-size:10px"> ±${std.toFixed(1)}</span></td>
      <td style="text-align:right;color:#dca032">${b['+1σ'].toFixed(1)}</td>
      <td style="text-align:right;color:#96c850">${Math.max(0,b['-1σ']).toFixed(1)}</td>
      <td style="text-align:right;color:#5ab4ff;font-size:10px">${median.toFixed(1)}</td>`;
  }

  el.innerHTML = `
  <table style="width:100%;border-collapse:collapse;font-size:12px">
    <thead>
      <tr style="border-bottom:1px solid var(--border);color:var(--muted);font-size:11px">
        <th style="text-align:left;padding:5px 8px">Sector</th>
        <th style="text-align:center;padding:5px" colspan="4">P/E Ratio</th>
        <th style="text-align:center;padding:5px" colspan="4">P/BV Ratio</th>
        <th style="text-align:right;padding:5px">หุ้น</th>
      </tr>
      <tr style="border-bottom:1px solid var(--border);color:var(--muted);font-size:10px">
        <th></th>
        <th title="ค่าเฉลี่ย ± ส่วนเบี่ยงเบนมาตรฐาน (σ) ของหุ้นทุกตัวใน sector">avg±σ</th><th style="color:#dca032" title="เพดานบน = avg + 1σ — หุ้นที่สูงกว่านี้ถือว่าแพงผิดปกติเทียบกลุ่ม">+1σ</th><th style="color:#96c850" title="พื้นล่าง = avg − 1σ — หุ้นที่ต่ำกว่านี้ถือว่าถูกผิดปกติเทียบกลุ่ม">-1σ</th><th style="color:#5ab4ff" title="ค่ามัธยฐาน (median) — ตัวแทนกลางของกลุ่ม ทนต่อ outlier กว่า avg">med</th>
        <th title="ค่าเฉลี่ย ± ส่วนเบี่ยงเบนมาตรฐาน (σ) ของหุ้นทุกตัวใน sector">avg±σ</th><th style="color:#dca032" title="เพดานบน = avg + 1σ — หุ้นที่สูงกว่านี้ถือว่าแพงผิดปกติเทียบกลุ่ม">+1σ</th><th style="color:#96c850" title="พื้นล่าง = avg − 1σ — หุ้นที่ต่ำกว่านี้ถือว่าถูกผิดปกติเทียบกลุ่ม">-1σ</th><th style="color:#5ab4ff" title="ค่ามัธยฐาน (median) — ตัวแทนกลางของกลุ่ม ทนต่อ outlier กว่า avg">med</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
    ${rows.map((r,i) => `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.04);${i%2?'background:rgba(255,255,255,0.02)':''}">
        <td style="padding:5px 8px">
          <span onclick="openValSectorModal('${r.sec.replace(/'/g,"\\'")}',this)"
            style="font-weight:500;cursor:pointer;color:#c8d0dc;border-bottom:1px dashed rgba(90,180,255,0.4)"
            onmouseover="this.style.color='#5ab4ff'" onmouseout="this.style.color='#c8d0dc'">
            ${r.sec}
          </span>
        </td>
        ${bandCell(r.pe, mkt.pe)}
        ${bandCell(r.pbv, mkt.pbv)}
        <td style="text-align:right;color:var(--muted);padding:5px 8px">${r.n_stocks}</td>
      </tr>`).join('')}
    </tbody>
    <tfoot>
      <tr style="border-top:1px solid var(--border);font-weight:600;color:#5ab4ff">
        <td style="padding:6px 8px">ตลาดรวม</td>
        ${mkt.pe ? `<td style="text-align:right">${mkt.pe.avg.toFixed(1)}<span style="color:var(--muted);font-size:10px"> ±${mkt.pe.std.toFixed(1)}</span></td>
          <td style="text-align:right;color:#dca032">${mkt.pe.bands['+1σ'].toFixed(1)}</td>
          <td style="text-align:right;color:#96c850">${Math.max(0,mkt.pe.bands['-1σ']).toFixed(1)}</td>
          <td style="text-align:right;color:#5ab4ff;font-size:10px">${mkt.pe.median.toFixed(1)}</td>` : '<td colspan="4">—</td>'}
        ${mkt.pbv ? `<td style="text-align:right">${mkt.pbv.avg.toFixed(1)}<span style="color:var(--muted);font-size:10px"> ±${mkt.pbv.std.toFixed(1)}</span></td>
          <td style="text-align:right;color:#dca032">${mkt.pbv.bands['+1σ'].toFixed(1)}</td>
          <td style="text-align:right;color:#96c850">${Math.max(0,mkt.pbv.bands['-1σ']).toFixed(1)}</td>
          <td style="text-align:right;color:#5ab4ff;font-size:10px">${mkt.pbv.median.toFixed(1)}</td>` : '<td colspan="4">—</td>'}
        <td style="text-align:right;padding:6px 8px">${rows.reduce((a,r)=>a+r.n_stocks,0)}</td>
      </tr>
    </tfoot>
  </table>`;
}

// ═══════════════════════════════════════════════
//  VALUATION PAGE (INDEX P/E & PBV)
// ═══════════════════════════════════════════════
let _valData = null;
let _valDataInflight = null;   // กัน /api/market-stats ถูกยิงซ้ำตอนโหลดหน้าครั้งแรก (loadValuationPage + loadValDailyBox แข่งกันเช็ค !_valData)
let _valPeriod = 'ALL';

// โหลด set_market_stats.json (cache ใน _valData) — force=true บังคับดึงใหม่ (หลัง rebuild/merge)
async function _loadValData(force) {
  if (_valData && !force) return _valData;
  if (_valDataInflight && !force) return _valDataInflight;
  const p = (async () => {
    const r = await _fetchTimeout('/api/market-stats?t=' + Date.now(), 20000);
    if (!r.ok) throw new Error('ไม่พบข้อมูล');
    _valData = await r.json();
    return _valData;
  })();
  if (!force) _valDataInflight = p;
  try {
    return await p;
  } finally {
    if (_valDataInflight === p) _valDataInflight = null;
  }
}

// ── Global tooltip popup ─────────────────────
// เดิมเปิด/ปิด/วางตำแหน่งด้วย mousemove+mouseleave ล้วนๆ — ใช้ไม่ได้เลยบนจอสัมผัส
// (ไอแพด/มือถือ ไม่มี mousemove ตอนแตะ) เพิ่ม tap-to-pin ทำงานคู่กับ hover เดิมบน desktop
(function(){
  const pop = document.createElement('div');
  pop.id = '_vtip-popup';
  document.body.appendChild(pop);
  let pinnedEl = null;

  function place(x, y) {
    const vw = window.innerWidth, vh = window.innerHeight;
    const pw = pop.offsetWidth + 16, ph = pop.offsetHeight + 16;
    if (x + pw > vw) x = x - pw + 2;
    if (y + ph > vh) y = y - ph + 2;
    pop.style.left = Math.max(4, x) + 'px';
    pop.style.top  = Math.max(4, y) + 'px';
  }

  document.addEventListener('mousemove', e => {
    if (pinnedEl) return; // กำลังปักหมุดจากการแตะ ไม่ให้ hover ทับ
    const el = e.target.closest('[data-vtip]');
    if (!el) { pop.style.display='none'; return; }
    pop.innerHTML = el.dataset.vtip;
    pop.style.display = 'block';
    place(e.clientX + 14, e.clientY + 14);
  });
  document.addEventListener('mouseleave', () => { if (!pinnedEl) pop.style.display='none'; }, true);

  // จอสัมผัส: แตะไอคอนเพื่อเปิด/ปิด (ปักหมุดไว้จนกว่าจะแตะที่อื่นหรือแตะไอคอนเดิมซ้ำ)
  document.addEventListener('click', e => {
    const el = e.target.closest('[data-vtip]');
    if (!el) {
      if (pinnedEl) { pop.style.display = 'none'; pinnedEl = null; }
      return;
    }
    e.stopPropagation();
    if (pinnedEl === el) { pop.style.display = 'none'; pinnedEl = null; return; }
    pinnedEl = el;
    pop.innerHTML = el.dataset.vtip;
    pop.style.display = 'block';
    const r = el.getBoundingClientRect();
    place(r.left, r.bottom + 6);
  });
})();

async function refreshMarketStats() {
  const btn = document.getElementById('val-refresh-btn');
  const status = document.getElementById('val-refresh-status');
  btn.disabled = true;
  btn.textContent = '⟳ กำลังอัพเดท...';
  status.textContent = '';
  status.style.color = 'var(--muted)';

  try {
    const r = await _fetchTimeout('/api/refresh-market-stats', 60000, 'หมดเวลารอ rebuild (เกิน 60 วิ)', { method: 'POST' });
    const d = await r.json();

    if (!d.ok) {
      status.textContent = '✗ ' + d.error;
      status.style.color = 'var(--red)';
      return;
    }

    if (!d.new_data) {
      status.textContent = `✓ ข้อมูลเป็นปัจจุบันแล้ว (ล่าสุด: ${d.new_latest})`;
      status.style.color = '#96c850';
    } else {
      status.textContent = `✓ อัพเดทสำเร็จ! ${d.old_latest} → ${d.new_latest} | P/E=${d.pe_current}x (${d.pe_zscore > 0 ? '+' : ''}${d.pe_zscore}σ) | P/BV=${d.pbv_current}x`;
      status.style.color = '#3ab464';
    }
    // re-load + re-render เสมอหลัง refresh สำเร็จ — d.new_data เทียบแค่ "เดือนล่าสุด" ถ้า SET
    // revise ค่าเดือนเก่าย้อนหลัง (ยื่นงบช้า) โดยเดือนล่าสุดเท่าเดิม backend เขียนไฟล์ใหม่แล้ว
    // แต่ new_data=false — ไม่ re-render กราฟ/สถิติจะค้างค่าเก่าจนกว่าจะ reload หน้า
    // (renderValuation() บรรทัดแรก "if (!_valData) return" — ต้อง _loadValData ก่อนเสมอ)
    try { await _loadValData(true); } catch (e) { /* คง _valData เดิมไว้ */ }
    renderValuation();
    renderMarketStatsExtra();   // ปันผล/market cap/breadth ถูกคงไว้ตอน rebuild — วาดใหม่ให้ตรงชุดข้อมูลใหม่
    _showValDataMonth();   // อัพเดทป้ายเดือนข้อมูลให้ตรงหลัง refresh
  } catch(e) {
    status.textContent = '✗ ไม่สามารถเชื่อมต่อ server: ' + e.message;
    status.style.color = 'var(--red)';
  } finally {
    btn.disabled = false;
    btn.innerHTML = '⟳ Rebuild ประวัติ (Table_PE/PBV)';
  }
}

// อัพเดทจากไฟล์ Market_Statistics_Month_th_TH.xls (ไฟล์เดียว รายเดือนปกติ) — ต่าง
// จาก refreshMarketStats() ด้านบน (Table_PE/PBV.xls) ตรงที่ merge เพิ่มเข้า
// set_market_stats.json ไม่ rebuild ทับ และได้ div_yield/mkt_cap/breadth มาด้วย
async function refreshMarketStatsMonthly() {
  const btn = document.getElementById('val-refresh-monthly-btn');
  const status = document.getElementById('val-refresh-status');
  btn.disabled = true;
  btn.textContent = '⟳ กำลังอัพเดท...';
  status.textContent = '';
  status.style.color = 'var(--muted)';

  try {
    const r = await _fetchTimeout('/api/refresh-market-stats-monthly', 60000, 'หมดเวลารอ merge (เกิน 60 วิ)', { method: 'POST' });
    const d = await r.json();

    if (!d.ok) {
      status.textContent = '✗ ' + d.error;
      status.style.color = 'var(--red)';
      return;
    }

    if (!d.new_data) {
      status.textContent = `✓ ข้อมูลเป็นปัจจุบันแล้ว (ล่าสุด: ${d.new_latest})`;
      status.style.color = '#96c850';
    } else {
      status.textContent = `✓ อัพเดทสำเร็จ! ${d.old_latest} → ${d.new_latest} | P/E=${d.pe_current}x | P/BV=${d.pbv_current}x | ปันผล=${d.div_yield_current}%`;
      status.style.color = '#3ab464';
    }
    // re-load + re-render เสมอ — merge อาจ upsert ทับค่าเดือนเก่าโดยเดือนล่าสุดเท่าเดิม
    // (new_data=false) แต่ไฟล์เปลี่ยนแล้ว ถ้าไม่ re-render จะค้างค่าเก่าจนกว่าจะ reload หน้า
    try { await _loadValData(true); } catch (e) { /* คง _valData เดิมไว้ */ }
    renderValuation();
    renderMarketStatsExtra();
    _showValDataMonth();
  } catch (e) {
    status.textContent = '✗ ไม่สามารถเชื่อมต่อ server: ' + e.message;
    status.style.color = 'var(--red)';
  } finally {
    btn.disabled = false;
    btn.innerHTML = '⟳ อัพเดทข้อมูล (Market Statistics)';
  }
}

