// เช็คห้องต่างชาติใกล้เต็ม (SET.or.th ทางการ, ดู PLAN_set_api_expansion.txt งาน #2B) —
// sync โควตาต่างชาติทั้งกระดานสด (~7 วิ) แล้วเรียงตาม "% ที่ใช้ไปแล้ว" มากสุดก่อน
async function checkForeignRoomNew() {
  const btn = document.getElementById('val-check-foreign-btn');
  const status = document.getElementById('val-refresh-status');
  const box = document.getElementById('val-foreign-room-result');
  btn.disabled = true;
  btn.textContent = '🔍 กำลังเช็ค...';
  status.textContent = '';
  box.style.display = 'none';

  try {
    const r = await _fetchTimeout('/api/check-foreign-room', 30000, undefined, { method: 'POST' });
    const d = await r.json();
    if (!d.ok) throw new Error(d.error || 'เช็คไม่สำเร็จ');

    const asOf = d.as_of || '—';
    if (!d.watchlist_hits.length) {
      status.textContent = `✓ ไม่มีหุ้นใน Watchlist ที่ห้องต่างชาติตึง (ทั้งตลาดมีข้อมูล ${d.total_count} ตัว ณ ${asOf})`;
      status.style.color = '#96c850';
    } else {
      status.textContent = `⚠ พบ ${d.watchlist_hits.length} ตัวใน Watchlist ที่ห้องต่างชาติใช้ไปเกิน 80% (ทั้งตลาดมีข้อมูล ${d.total_count} ตัว)`;
      status.style.color = 'var(--red)';
    }

    const wlSet = new Set(d.watchlist_hits.map(x => x.symbol));
    // โชว์ Watchlist ก่อนเสมอ + ตัวที่ใช้ไป ≥80% ของทั้งตลาด (ตารางเต็มยาวเกินจะดูไหว
    // ถ้าโชว์ทั้ง 900 ตัว — เกณฑ์เดียวกับสีส้ม/แดงในตาราง)
    const tight = d.rows.filter(x => (x.used_pct ?? 0) >= 80 && !wlSet.has(x.symbol));
    const rows = [...d.watchlist_hits, ...tight];
    box.style.display = 'block';
    box.innerHTML = `<div class="card" style="padding:14px">
      <div style="font-size:12px;color:var(--muted);margin-bottom:8px">
        ห้องต่างชาติใช้ไป ≥80% (${tight.length} ตัว) + หุ้นใน Watchlist ทุกระดับ — ข้อมูล ณ ${asOf}
        <span class="scr-tip-icon" onclick="_tipIconToggle(this,event)">?<div class="scr-tip-box" style="width:270px">
          <strong>ห้องต่างชาติคืออะไร</strong><br>
          กฎหมายไทยจำกัดสัดส่วนที่ต่างชาติถือได้ (ปกติ 49% บางกลุ่มต่ำกว่านั้น) — "ใช้ไป" คือสัดส่วนที่ถือแล้วเทียบเพดานนั้น<hr>
          <span style="color:var(--text2)">เกณฑ์สี: 🔴 ≥95% · 🟠 ≥80% · หุ้นที่ไม่มีเพดานกำหนด (100%) จะไม่ขึ้นในตารางนี้ (ใช้ไปคำนวณไม่ได้)</span>
        </div></span>
      </div>
      <div style="overflow-x:auto;max-height:420px;overflow-y:auto"><table class="tbl" style="min-width:480px">
        <thead><tr><th>Symbol</th><th>ใช้ไป</th><th>เพดาน</th><th>เหลือ (หุ้น)</th></tr></thead>
        <tbody>${rows.map(x => {
          const clr = (x.used_pct ?? 0) >= 95 ? 'var(--red)' : (x.used_pct ?? 0) >= 80 ? '#e8a33d' : 'var(--text)';
          return `<tr${wlSet.has(x.symbol) ? ' style="background:rgba(255,90,90,0.1)"' : ''}>
            <td><strong>${wlSet.has(x.symbol) ? '⭐ ' : ''}${x.symbol}</strong></td>
            <td style="font-weight:600;color:${clr}">${x.used_pct != null ? x.used_pct.toFixed(1)+'%' : '—'}</td>
            <td style="font-size:11px;color:var(--text2)">${x.foreign_limit != null ? x.foreign_limit+'%' : '—'}</td>
            <td style="font-size:11px;color:var(--text2)">${x.foreign_available != null ? x.foreign_available.toLocaleString() : '—'}</td>
          </tr>`;
        }).join('')}</tbody>
      </table></div>
    </div>`;
  } catch (e) {
    status.textContent = '✗ เช็คไม่สำเร็จ: ' + e.message;
    status.style.color = 'var(--red)';
  } finally {
    btn.disabled = false;
    btn.innerHTML = '🌏 เช็คห้องต่างชาติใกล้เต็ม';
  }
}

// แปลง "2026-06" -> "มิ.ย. 2026"
function _thMonth(ym) {
  if (!ym || !/^\d{4}-\d{2}$/.test(ym)) return ym || '—';
  const TH = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  const [y, m] = ym.split('-');
  return `${TH[+m - 1]} ${y}`;
}

async function _showValDataMonth() {
  const el = document.getElementById('val-data-month');
  if (!el) return;
  try {
    const d = await (await _fetchTimeout('/api/market-stats-meta?t=' + Date.now(), 10000)).json();
    const pe = _thMonth(d.pe_date), pbv = _thMonth(d.pbv_date);
    const same = d.pe_date === d.pbv_date;
    const peLine = same
      ? `📅 ข้อมูลล่าสุด: <b style="color:var(--fg)">${pe}</b> <span style="color:var(--muted)">(P/E &amp; P/BV จาก SET มักช้ากว่าปัจจุบัน ~1 เดือนเป็นปกติ)</span>`
      : `📅 ข้อมูลล่าสุด: P/E <b style="color:var(--fg)">${pe}</b> · P/BV <b style="color:var(--fg)">${pbv}</b> <span style="color:var(--muted)">(SET มักช้า ~1 เดือน)</span>`;
    // ข้อมูลจาก Market_Statistics_Month_th_TH.xls (ปันผล / มูลค่าหลักทรัพย์ / จำนวนบริษัท
    // จดทะเบียน) — โชว์แยกบรรทัดเสมอ กันเข้าใจผิดว่าตกรุ่นตาม P/E-P/BV เวลาอัพเดทคนละรอบ
    let msLine = '';
    if (d.monthly_date) {
      const ms = _thMonth(d.monthly_date);
      msLine = `<br>📅 Market Statistics (ปันผล / มูลค่าหลักทรัพย์ / จำนวนบริษัทจดทะเบียน): <b style="color:var(--fg)">${ms}</b> <span style="color:var(--muted)">(จาก Market_Statistics_Month_th_TH.xls · SET มักช้า ~1 เดือน)</span>`;
    }
    el.innerHTML = peLine + msLine;
  } catch (e) { el.textContent = ''; }
}

// ข้อมูลเสริมจาก Market_Statistics_Month_th_TH.xls ที่ Table_PE/PBV.xls ไม่มี:
// อัตราปันผลตอบแทน, มูลค่าหลักทรัพย์ตามราคาตลาด, จำนวนบริษัทจดทะเบียน (breadth)
// — ใช้ _svgBand เดียวกับ P/E-P/BV ด้านบน (ฟังก์ชันเองจะโชว์ "ข้อมูลไม่พอ" เองถ้า
// ยังมีน้อยกว่า 8 งวด ซึ่งเป็นปกติช่วงแรกที่เพิ่งเริ่มเก็บ series พวกนี้)
function renderMarketStatsExtra() {
  const box = document.getElementById('val-extra-box');
  if (!box || !_valData) return;
  const dy = _valData.div_yield, mc = _valData.mkt_cap, br = _valData.breadth;
  const ok = s => !!(s && s.dates && s.dates.length && s.series);
  // ไฟล์เก่า (rebuild จาก Table_PE/PBV อย่างเดียว) ไม่มีคีย์พวกนี้เลย — ซ่อนกล่องไปทั้งอัน
  // แทนที่จะพังตอนอ่าน .series ของ undefined
  if (!ok(dy) && !ok(mc) && !ok(br)) { box.style.display = 'none'; return; }

  const toSeries = (stat, key) => (ok(stat) && stat.series[key])
    ? stat.dates.map((d, i) => ({ d, v: stat.series[key][i] })).filter(o => o.v != null)
    : [];
  const dySet = toSeries(dy, 'SET'), dyMai = toSeries(dy, 'mai');
  const mcSet = toSeries(mc, 'SET'), mcMai = toSeries(mc, 'mai');

  const last = arr => arr.length ? arr[arr.length - 1] : null;
  // %เปลี่ยนแปลงเทียบ n งวดก่อนหน้า — เทียบตามลำดับในซีรีส์ (ข้ามเดือนที่ไม่มีข้อมูลไปแล้ว)
  const chgPct = (arr, back) => {
    if (arr.length <= back) return null;
    const a = arr[arr.length - 1 - back].v, b = arr[arr.length - 1].v;
    return a ? (b - a) / a * 100 : null;
  };
  const chgHtml = (p, label) => p == null ? '' :
    `<span style="color:${p >= 0 ? '#3ab464' : '#dc503c'};font-size:11px;margin-left:8px">${p >= 0 ? '+' : ''}${p.toFixed(2)}% ${label}</span>`;
  // หน่วยในไฟล์ SET เป็น "ล้านบาท" — 20519190 -> 20.52 ล้านล้านบาท
  const fmtMB = v => v == null ? '—'
    : v >= 1e6 ? (v / 1e6).toFixed(2) + ' ล้านล้านบาท'
    : (v / 1e3).toFixed(2) + ' พันล้านบาท';

  // แถวสรุปค่าล่าสุด + MoM/YoY ใช้แทน _svgBand เมื่อยังไม่ถึง 8 งวด (ไม่งั้นกล่องจะขึ้นแค่
  // "ข้อมูลไม่พอ" เฉยๆ ซึ่งเป็นสภาพปกติช่วงแรกที่เพิ่งเริ่มเก็บซีรีส์พวกนี้)
  const latestRow = (arr, label, fmt) => {
    const l = last(arr);
    return `<div style="font-size:12px;margin:5px 0">
      <b style="color:var(--text)">${label}</b>
      <b style="margin-left:6px">${l ? fmt(l.v) : '—'}</b>
      ${chgHtml(chgPct(arr, 1), 'MoM')}${chgHtml(chgPct(arr, 12), 'YoY')}
      <span style="color:var(--muted);margin-left:8px">${l ? `ณ ${_thMonth(l.d)}` : ''} · เก็บมา ${arr.length} เดือน</span>
    </div>`;
  };
  // ปันผลใช้แถบเทียบอดีตได้ (สูง = ถูก จึงส่ง lowerIsCheap=false) ส่วน Market Cap ไม่ใช้
  // — โตขึ้นตามเวลาเป็นธรรมชาติ ถ้าเอาไปเข้าแถบ "ถูก/แพง" จุดจะติดแดงตลอดกาลโดยไม่มีความหมาย
  const dyBlock = arr => arr.length >= 8 ? _svgBand(arr, arr === dySet ? 'SET' : 'mai', false) : '';

  let breadthHtml = '<div style="font-size:12px;color:var(--text2)">ยังไม่มีข้อมูล</div>';
  if (ok(br)) {
    const i = br.dates.length - 1;
    const s = br.series;
    const col = n => n > 0 ? '#3ab464' : n < 0 ? '#dc503c' : 'var(--muted)';
    const block = (label, listedArr, newC, delC) => {
      const cur = listedArr[i], prev = i > 0 ? listedArr[i - 1] : null;
      const diff = (cur != null && prev != null) ? cur - prev : null;
      return `
      <div>
        <div style="color:var(--muted);font-size:11px">จำนวนบริษัทจดทะเบียน ${label}</div>
        <div style="font-size:18px;font-weight:700">${cur ?? '—'}
          ${diff != null ? `<span style="font-size:11px;font-weight:600;color:${col(diff)}">${diff > 0 ? '+' : ''}${diff} จากเดือนก่อน</span>` : ''}
        </div>
        <div style="font-size:11px;color:var(--muted)">เดือนนี้: เข้าใหม่ <span style="color:#3ab464">${newC ?? 0}</span> · เพิกถอน <span style="color:#dc503c">${delC ?? 0}</span></div>
      </div>`;
    };
    breadthHtml = `<div style="display:flex;gap:32px;flex-wrap:wrap">
      ${block('SET', s.listed_SET, s.new_listed_SET[i], s.delisted_SET[i])}
      ${block('mai', s.listed_mai, s.new_listed_mai[i], s.delisted_mai[i])}
    </div>
    <div style="font-size:10px;color:var(--muted);margin-top:8px">ผลต่าง "จากเดือนก่อน" อาจไม่เท่ากับ เข้าใหม่−เพิกถอน เพราะมีการย้ายตลาดระหว่าง SET↔mai ด้วย</div>`;
  }

  box.style.display = 'block';
  box.innerHTML = `
    <div class="card" style="padding:16px;margin-bottom:16px">
      <div style="font-weight:600;margin-bottom:4px;font-size:14px">อัตราเงินปันผลตอบแทนตลาด (Dividend Yield)</div>
      <div style="font-size:12px;color:var(--muted);margin-bottom:10px">ยิ่งสูง = ตลาดยิ่ง "ถูก" เทียบพื้นฐานปันผล (ทิศทางตรงข้ามกับ P/E &amp; P/BV)</div>
      ${latestRow(dySet, 'SET', v => v.toFixed(2) + '%')}${dyBlock(dySet)}
      ${latestRow(dyMai, 'mai', v => v.toFixed(2) + '%')}${dyBlock(dyMai)}
    </div>
    <div class="card" style="padding:16px;margin-bottom:16px">
      <div style="font-weight:600;margin-bottom:4px;font-size:14px">มูลค่าหลักทรัพย์ตามราคาตลาด (Market Cap)</div>
      <div style="font-size:12px;color:var(--muted);margin-bottom:10px">ขนาดตลาดรวม — ดูทิศทาง/อัตราเติบโต ไม่ใช่ตัวชี้ถูก-แพง</div>
      ${latestRow(mcSet, 'SET', fmtMB)}
      ${latestRow(mcMai, 'mai', fmtMB)}
    </div>
    <div class="card" style="padding:16px;margin-bottom:16px">
      <div style="font-weight:600;margin-bottom:10px;font-size:14px">Breadth — จำนวนบริษัทจดทะเบียน</div>
      ${breadthHtml}
    </div>
    <div style="font-size:10px;color:var(--muted);margin:-6px 0 16px">3 กล่องนี้มาจาก Market_Statistics_Month_th_TH.xls (ไม่ขึ้นกับปุ่มเลือกช่วงเวลาด้านล่าง — ใช้ข้อมูลเท่าที่เก็บสะสมไว้ทั้งหมด)</div>`;
}

async function loadValuationPage() {
  _showValDataMonth();
  // Load both in parallel
  const [_1, _2] = await Promise.allSettled([
    (async () => {
      try {
        await _loadValData();
        renderValuation();
        renderMarketStatsExtra();
      } catch(e) {
        document.getElementById('val-summary').innerHTML =
          '<div style="color:var(--red);padding:16px">ไม่พบ set_market_stats.json — รัน import_market_stats.py ก่อน</div>';
      }
    })(),
    renderValSectorTable(),
    loadValDailyBox(),
  ]);
}

// กล่อง P/E-P/BV "รายวัน" จาก SET.or.th โดยตรง (คู่กับตัวเลขรายเดือนจาก Excel
// ด้านล่าง) — scrape จากหน้า overview ของ SET.or.th เอง ไม่ใช่ Finnomena
async function loadValDailyBox() {
  const box = document.getElementById('val-daily-box');
  if (!box) return;
  try {
    const r = await _fetchTimeout('/api/set-daily-valuation?t=' + Date.now(), 25000);
    const d = await r.json();
    if (d.error || !d.SET) { box.style.display = 'none'; return; }
    const row = (label, key, suffix = '') => `
      <tr>
        <td style="padding:4px 10px 4px 0;color:var(--muted)">${label}</td>
        <td class="r" style="padding:4px 14px">${d.SET[key] != null ? d.SET[key].toLocaleString(undefined,{maximumFractionDigits:2}) + suffix : '—'}</td>
        <td class="r" style="padding:4px 0">${d.mai[key] != null ? d.mai[key].toLocaleString(undefined,{maximumFractionDigits:2}) + suffix : '—'}</td>
      </tr>`;

    // "มูลค่าเทียบอดีตตัวเอง" — เอาสถิติรายเดือนย้อนหลัง (Excel, ที่มีอยู่แล้วใน
    // _valData) มาต่อกับค่ารายวันของวันนี้ (SET.or.th) เป็นจุด "ปัจจุบัน" แทนที่
    // จะใช้ค่าสิ้นเดือนล่าสุดของ Excel (ค้างได้นานสุด ~1 เดือน) — ใช้ _svgBand
    // เดียวกับที่ใช้ในหน้างบการเงินรายหุ้น (ดู _loadLiveValuationBand)
    if (!_valData) {
      try { await _loadValData(); }
      catch (e) { /* ไม่มี Excel ก็แสดงแค่ตารางรายวันด้านบนไป */ }
    }
    const today = new Date().toISOString().slice(0, 10);
    const bandSeries = (market, statKey, liveVal) => {
      const stat = _valData && _valData[statKey];
      if (!stat || !stat.dates || !stat.series || !stat.series[market]) return [];
      const series = stat.dates.map((dt, i) => ({ d: dt, v: stat.series[market][i] }))
        .filter(o => o.v != null);
      if (liveVal != null) series.push({ d: today, v: liveVal });
      return series;
    };
    // เส้นค่า ±σ (mean ± n×std ของสถิติรายเดือนที่คำนวณไว้แล้วฝั่ง server ใน
    // calc_stats() — set_market_stats.json) แปะไว้ใต้แถบ percentile band แต่ละอัน
    // ให้เห็นว่าค่าปัจจุบันอยู่โซนไหนเทียบค่าเฉลี่ย/ส่วนเบี่ยงเบนมาตรฐาน
    const sigmaRow = (statKey, market) => {
      const s = _valData && _valData[statKey] && _valData[statKey].stats && _valData[statKey].stats[market];
      if (!s || !s.bands) return '';
      // เรียงถูก(เขียว)→แพง(แดง) จากซ้ายไปขวา ให้ตรงกับทิศทางแถบไล่สีด้านบน
      // (เขียว ซ้าย → แดง ขวา) ไม่ใช่เรียงจาก +3σ ก่อนแบบตัวเลข
      const items = [
        ['-3σ', s.bands['-3σ'], '#2f9e57', 'ถูกมากผิดปกติ'],
        ['-2σ', s.bands['-2σ'], '#3ab464', 'ถูกผิดปกติ'],
        ['-1σ', s.bands['-1σ'], '#96c850', 'ถูกกว่าค่าเฉลี่ย'],
        ['+1σ', s.bands['+1σ'], '#e0d060', 'แพงกว่าค่าเฉลี่ย'],
        ['+2σ', s.bands['+2σ'], '#dca032', 'แพงผิดปกติ'],
        ['+3σ', s.bands['+3σ'], '#dc503c', 'แพงมากผิดปกติ'],
      ].filter(([, val]) => val != null);
      if (!items.length) return '';
      return `<div style="display:flex;flex-wrap:wrap;gap:6px 12px;font-size:10px;margin:2px 0 8px">
        ${items.map(([lbl, val, col, txt]) =>
          `<span style="color:${col}" title="${txt}"><b>${lbl}</b> ${val}x — ${txt}</span>`).join('')}
      </div>`;
    };
    const bandsHtml = (market, label) => {
      const pe = bandSeries(market, 'pe', d[market] && d[market].pe);
      const pbv = bandSeries(market, 'pbv', d[market] && d[market].pbv);
      if (pe.length < 8 && pbv.length < 8) return '';
      return `
        <div style="font-size:11px;color:var(--muted);font-weight:600;margin:10px 0 2px">${label}</div>
        ${pe.length >= 8 ? _svgBand(pe, 'PE', true) + sigmaRow('pe', market) : ''}
        ${pbv.length >= 8 ? _svgBand(pbv, 'PBV', true) + sigmaRow('pbv', market) : ''}`;
    };
    const bandsBlock = bandsHtml('SET', 'SET') + bandsHtml('mai', 'mai');

    box.style.display = 'block';
    // หมายเหตุ: จงใจไม่ใช้ class="card" ตรงนี้ (แค่ inline style เทียบเท่า) — โค้ด
    // renderValuation() ด้านล่างมี selector "#page-valuation .card:last-child"
    // ที่ไปแม็ตช์ div.card ตัวไหนก็ได้ที่เป็นลูกคนสุดท้ายของ parent ตัวเอง ถ้าใช้
    // class="card" ตรงนี้จะไปชนกับ tooltip injection ของกล่องอื่นโดยไม่ตั้งใจ
    box.innerHTML = `
      <div style="background:var(--bg2);border:1px solid var(--border);border-radius:8px;padding:14px 16px">
        <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:6px">
          <div style="font-weight:600;font-size:13px">📅 วันนี้ (รายวัน — จาก SET.or.th โดยตรง)</div>
          <span style="font-size:11px;color:var(--muted)">ข้อมูล ณ วันที่ ${d.as_of || '—'}</span>
        </div>
        <div style="overflow-x:auto"><table style="border-collapse:collapse;font-size:12.5px">
          <tr style="color:var(--muted)"><td></td><td class="r" style="padding:0 14px">SET</td><td class="r">mai</td></tr>
          ${row('P/E (เท่า)', 'pe')}
          ${row('P/BV (เท่า)', 'pbv')}
          ${row('อัตราปันผล (%)', 'div_yield', '%')}
          ${row('กำไรสุทธิ/หุ้น', 'eps')}
        </table></div>
        <div style="font-size:10px;color:var(--muted);margin-top:6px">ตัวเลขจากตาราง "ผลการดำเนินงาน" บนหน้า SET.or.th โดยตรง — อัพเดทตามรอบของ SET เอง (ปกติวันละครั้งหลังตลาดปิด)</div>
        ${bandsBlock ? `<hr style="border:none;border-top:1px solid var(--border);margin:12px 0 8px">
        <div style="font-weight:600;font-size:12.5px">มูลค่าเทียบอดีตตัวเอง (PE/PBV band)${_tipIconHtml(_PE_BAND_NOTE_HTML)}</div>
        ${bandsBlock}
        <div style="font-size:10px;color:var(--muted);margin-top:2px">เขียว = ถูกกว่าอดีต (≤ p25) · แดง = แพงกว่าอดีต (≥ p75) · ค่า "ปัจจุบัน" คือตัวเลขรายวันด้านบน เทียบกับสถิติย้อนหลังจาก Excel รายเดือน</div>` : ''}
      </div>`;
  } catch (e) {
    box.style.display = 'none';
  }
}

function setValPeriod(p, btn) {
  _valPeriod = p;
  // ล้างเฉพาะกลุ่มปุ่มช่วงเวลาด้วยกันเอง — เดิมล้าง .filter-btn ทั้งหน้า ทำให้ไฮไลต์
  // ปุ่มโซน σ / P/E-P/BV / ขอบเขต หายไปทั้งที่ตัวกรองยังทำงานอยู่
  document.querySelectorAll('#page-valuation .filter-btn[onclick^="setValPeriod"]')
    .forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderValuation();
}

function filterByPeriod(dates, vals, period) {
  if (!vals || !dates) return { dates: dates || [], vals: vals || [] };
  if (period === 'ALL') return { dates, vals };
  const years = { '1Y':1, '2Y':2, '3Y':3, '5Y':5, '10Y':10, '20Y':20, '30Y':30 }[period] || 999;
  const cutoff = new Date();
  cutoff.setFullYear(cutoff.getFullYear() - years);
  const cutStr = cutoff.toISOString().slice(0,7);
  const idx = dates.findIndex(d => d >= cutStr);
  // ทุกงวดเก่ากว่า cutoff = ซีรีส์นี้หยุดอัพเดทไปแล้ว — คืนว่างให้ downstream ขึ้น "ไม่มีข้อมูล"
  // ดีกว่าคืนประวัติเต็มแล้วไปคิด avg/z-score ใต้ป้ายช่วงสั้น (เช่น "1 ปี")
  if (idx < 0) return { dates: [], vals: [] };
  return { dates: dates.slice(idx), vals: vals.slice(idx) };
}

const VAL_PERIOD_LABEL = { ALL:'ตลอดกาล', '30Y':'30 ปี', '20Y':'20 ปี', '10Y':'10 ปี', '5Y':'5 ปี', '3Y':'3 ปี', '2Y':'2 ปี', '1Y':'1 ปี' };

// ตัด leading/trailing null ออกก่อน filter period (ซีรีส์ mai เริ่มมีข้อมูลช้ากว่า SET)
function _trimNulls(dates, vals) {
  if (!vals || !dates) return { dates: dates || [], vals: vals || [] };
  let lo = 0, hi = vals.length - 1;
  while (lo <= hi && vals[lo] === null) lo++;
  while (hi >= lo && vals[hi] === null) hi--;
  return { dates: dates.slice(lo, hi + 1), vals: vals.slice(lo, hi + 1) };
}

// คำนวณ avg/std/percentile/zscore/bands จากช่วงเวลาที่เลือกจริง (ไม่ใช่ตลอดกาลเสมอ)
// current = ค่าล่าสุด (จุดท้ายของ array ที่กรองแล้ว) ส่วน avg/std/percentile scope ตามช่วงที่เลือก
function _calcStatsClient(vals) {
  const v = vals.filter(x => x !== null && x !== undefined && !Number.isNaN(x));
  if (!v.length) return {};
  const arr = [...v].sort((a, b) => a - b);
  const avg = v.reduce((a, b) => a + b, 0) / v.length;
  const variance = v.reduce((a, b) => a + (b - avg) ** 2, 0) / v.length;
  const std = Math.sqrt(variance);
  const current = v[v.length - 1];
  const round2 = x => Math.round(x * 100) / 100;
  const pct = Math.round((arr.filter(x => x <= current).length / arr.length) * 1000) / 10;
  return {
    current: round2(current), min: round2(arr[0]), max: round2(arr[arr.length - 1]),
    avg: round2(avg), median: round2(arr[Math.floor(arr.length / 2)]), std: round2(std),
    zscore: std ? round2((current - avg) / std) : 0, percentile: pct,
    bands: {
      '+3σ': round2(avg + 3 * std), '+2σ': round2(avg + 2 * std), '+1σ': round2(avg + std),
      '-1σ': round2(avg - std), '-2σ': round2(avg - 2 * std), '-3σ': round2(avg - 3 * std),
    },
  };
}

// คืน stats ตาม _valPeriod ที่เลือก — ใช้ของ backend (ตลอดกาล) เมื่อเลือก ALL,
// คำนวณสดฝั่ง client เมื่อเลือกช่วงสั้นกว่า เพื่อให้ avg/σ/percentile scope ตามช่วงจริง
function _periodStats(fullStats, filteredVals) {
  if (_valPeriod === 'ALL') return fullStats;
  return _calcStatsClient(filteredVals);
}

// เดิม copy ladder ของ _zColor เป๊ะ (2/1/-1/-2 → สีชุดเดียวกัน) ต่างแค่ fallback ตอน z
// ว่าง — ตารางเทียบช่วงเวลาอยากได้สีจางกลืนพื้นแทน dot สีขาวจางแบบ cross-sectional
function _valZColor(z) {
  return z == null ? 'var(--text2)' : _zColor(z);
}

// ตารางเปรียบเทียบ avg/z-score ทุกช่วงเวลา (Max→1Y) ของ P/E & P/BV ทั้ง SET และ mai
function renderValPeriodTable(seriesDefs) {
  const el = document.getElementById('val-period-table');
  if (!el) return;
  const periods = ['ALL', '30Y', '20Y', '10Y', '5Y', '3Y', '2Y', '1Y'];

  let html = `<thead><tr><th>ช่วงเวลา</th>` + seriesDefs.map(s =>
    `<th class="r" colspan="2">${s.label}<div style="font-weight:400;font-size:10px;color:var(--text2)">ปัจจุบัน ${s.current ?? '—'}x</div></th>`
  ).join('') + `</tr><tr><th style="font-size:10px;color:var(--text2)"></th>` + seriesDefs.map(() =>
    `<th class="r" style="font-size:10px;color:var(--text2)">avg</th><th class="r" style="font-size:10px;color:var(--text2)">z-score</th>`
  ).join('') + `</tr></thead><tbody>`;

  for (const p of periods) {
    html += `<tr><td style="font-weight:600">${p === 'ALL' ? 'Max' : p} <span style="color:var(--text2);font-weight:400;font-size:10px">(${VAL_PERIOD_LABEL[p]})</span></td>`;
    for (const s of seriesDefs) {
      const f = filterByPeriod(s.dates, s.vals, p);
      const st = p === 'ALL' ? (s.full || _calcStatsClient(f.vals)) : _calcStatsClient(f.vals);
      if (st.avg == null) { html += `<td class="r">—</td><td class="r">—</td>`; continue; }
      const z = st.zscore;
      html += `<td class="r">${st.avg}x</td>` +
        `<td class="r" style="color:${_valZColor(z)};font-weight:600" title="±1σ = ${st.std}x · ต่ำสุด ${st.min}x · สูงสุด ${st.max}x · percentile ${st.percentile}%">${z > 0 ? '+' : ''}${z}</td>`;
    }
    html += `</tr>`;
  }
  el.innerHTML = html + `</tbody>`;
}

function valZoneColor(v, thresholds) {
  const [t1, t2, t3] = thresholds;
  if (v === null) return 'rgba(0,0,0,0)';
  if (v < t1) return 'rgba(58,180,100,0.15)';
  if (v < t2) return 'rgba(150,200,80,0.12)';
  if (v < t3) return 'rgba(220,160,50,0.13)';
  return 'rgba(220,80,60,0.14)';
}

function valZoneLabel(v, thresholds, labels) {
  if (v === null) return '—';
  const [t1, t2, t3] = thresholds;
  if (v < t1) return labels[0];
  if (v < t2) return labels[1];
  if (v < t3) return labels[2];
  return labels[3];
}

function valZoneStyle(v, thresholds) {
  if (v === null) return '';
  const [t1, t2, t3] = thresholds;
  if (v < t1) return 'color:#3ab464;font-weight:700';
  if (v < t2) return 'color:#96c850;font-weight:700';
  if (v < t3) return 'color:#dca032;font-weight:700';
  return 'color:#dc503c;font-weight:700';
}

function drawValChart(canvasId, dates, vals, thresholds, stats) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  // ไม่มีจุดข้อมูลในช่วงที่เลือก (เช่น ซีรีส์หยุดอัพเดท + เลือกช่วงสั้น) — ล้าง canvas แล้วออก
  // ไม่งั้น Math.max(...[]) = -Infinity ลาก scale เพี้ยนทั้งกราฟ
  if (!dates || !dates.length || !vals || !vals.some(v => v !== null && v !== undefined)) {
    const c = canvas.getContext('2d');
    c.clearRect(0, 0, canvas.width, canvas.height);
    return;
  }
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.clientWidth || canvas.offsetWidth || 700;
  const H = canvas.clientHeight || 260;
  canvas.width  = W * dpr;
  canvas.height = H * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  const pad = { t: 16, r: 72, b: 32, l: 44 };
  const cw = W - pad.l - pad.r;
  const ch = H - pad.t - pad.b;

  const avg = stats.avg, std = stats.std;
  const bands = stats.bands || {};
  const current = stats.current;

  const validVals = vals.filter(v => v !== null);
  // แกน Y ผูกกับช่วง "ปกติ" ของข้อมูล — ใช้ค่า winsorize (ตัดขอบ p1/p99 ที่ n ใหญ่) เฉพาะตอน
  // คิดขอบแกน ไม่งั้นเดือนที่พุ่งผิดปกติจริงในประวัติ (เช่น P/E mai 937x ก.ค.2546 เทียบ median ~37x)
  // ลากสเกลจนเส้นส่วนใหญ่แบนติดขอบล่างอ่านไม่ออก — เส้น/จุด/แถบ ±σ ยังวาดจากค่าจริง (clip ที่ขอบ)
  const axisRef = _winsorize(validVals);
  const dataMax = Math.max(...axisRef);
  const dataMin = Math.max(0, Math.min(...axisRef));
  const dataRange = dataMax - dataMin || dataMax || 1;
  // ผูกขอบแกนกับช่วงข้อมูลจริงเป็นหลัก ไม่ปล่อยให้ avg±3.2σ ลาก scale ทั้งกราฟตรงๆ —
  // ชุดข้อมูลรายหุ้น (8-67 จุด) เจอ _winsorize (ตัดขอบ p1/p99) แทบไม่ตัด outlier เลยที่ n
  // เล็ก (round(p×(n-1)) ปัดลง index ต้น/ท้ายเองที่ n<~51) ปีที่ EPS/รายได้ใกล้ศูนย์พอดี
  // (near-breakeven) เลยพุ่งเป็นร้อยเท่าแบบไม่ถูกกรอง ลาก avg/std เพี้ยน (เจอจริง PE เฉลี่ย
  // 64x ทั้งที่ median 12x) ทำให้แกนยืดจนเส้นราคาจริงแบนติดขอบล่าง — clamp sdMax/sdMin ไม่ให้
  // ยื่นเกินช่วงข้อมูลจริง +30% (เส้น/พื้นที่ ±σ ยังวาดจาก avg/std จริงเหมือนเดิม แค่ไม่ปล่อย
  // ให้มันกำหนด scale ของแกน)
  const sdMax = Math.min(avg + 3.2 * std, dataMax + dataRange * 0.3);
  const sdMin = Math.max(0, avg - 3.2 * std, dataMin - dataRange * 0.3);
  const minV = Math.min(dataMin * 0.9, sdMin);
  const maxV = Math.max(dataMax * 1.02, sdMax);
  const scaleY = v => pad.t + ch - ((v - minV) / (maxV - minV)) * ch;
  const scaleX = i => pad.l + (i / (dates.length - 1)) * cw;

  // SD band fills (between consecutive bands)
  const sdLevels = [
    avg + 3*std, avg + 2*std, avg + std,
    avg,
    avg - std, avg - 2*std, Math.max(0, avg - 3*std)
  ];
  const sdFills = [
    'rgba(200,60,40,0.07)',   // +2σ to +3σ
    'rgba(220,130,40,0.07)',  // +1σ to +2σ
    'rgba(200,200,80,0.05)',  // avg to +1σ
    'rgba(200,200,80,0.05)',  // -1σ to avg
    'rgba(80,180,100,0.07)',  // -2σ to -1σ
    'rgba(40,160,80,0.08)',   // -3σ to -2σ
  ];
  for (let i = 0; i < sdFills.length; i++) {
    const hi = Math.min(sdLevels[i], maxV);
    const lo = Math.max(sdLevels[i+1], minV);
    if (hi <= lo) continue;
    ctx.fillStyle = sdFills[i];
    ctx.fillRect(pad.l, scaleY(hi), cw, scaleY(lo) - scaleY(hi));
  }

  // SD lines
  const sdLines = [
    { v: avg + 3*std, label:'+3σ', color:'rgba(200,60,40,0.7)',   dash:[3,4] },
    { v: avg + 2*std, label:'+2σ', color:'rgba(220,130,40,0.8)',  dash:[5,3] },
    { v: avg + std,   label:'+1σ', color:'rgba(220,200,80,0.7)',  dash:[6,3] },
    { v: avg,         label:'avg', color:'rgba(255,200,80,0.85)', dash:[7,3] },
    { v: avg - std,   label:'-1σ', color:'rgba(130,210,100,0.7)', dash:[6,3] },
    { v: avg - 2*std, label:'-2σ', color:'rgba(60,180,80,0.7)',   dash:[5,3] },
    { v: avg - 3*std, label:'-3σ', color:'rgba(40,140,60,0.7)',   dash:[3,4] },
  ];
  ctx.font = '9px sans-serif';
  ctx.textAlign = 'left';
  for (const sd of sdLines) {
    if (sd.v < minV || sd.v > maxV) continue;
    const y = scaleY(sd.v);
    ctx.strokeStyle = sd.color;
    ctx.setLineDash(sd.dash);
    ctx.lineWidth = sd.label === 'avg' ? 1.5 : 1;
    ctx.beginPath();
    ctx.moveTo(pad.l, y);
    ctx.lineTo(pad.l + cw, y);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = sd.color;
    ctx.fillText(`${sd.label} ${sd.v.toFixed(1)}`, pad.l + cw + 4, y + 3.5);
  }

  // Price line
  ctx.strokeStyle = '#5ab4ff';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  let first = true;
  for (let i = 0; i < vals.length; i++) {
    if (vals[i] === null) { first = true; continue; }
    const x = scaleX(i), y = scaleY(vals[i]);
    if (first) { ctx.moveTo(x, y); first = false; }
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  // X axis labels — เอาจุดแรกของแต่ละปี (year boundary) แทน step ตาม index คงที่เดิม เพราะ
  // ชุดข้อมูลรายไตรมาสที่มีปีไม่ครบ 4 ไตรมาส (เจอกับหลายหุ้น) ทำให้ step แบบเดิมสุ่มไปตกที่
  // ปีเดียวกันซ้ำๆ ติดกัน (เช่น "2023 2023 2024 2024 2024 2025 2025") อ่านแล้วดูเหมือนบัค
  const yearStarts = [];
  let lastYear = null;
  for (let i = 0; i < dates.length; i++) {
    const y = dates[i].slice(0, 4);
    if (y !== lastYear) { yearStarts.push(i); lastYear = y; }
  }
  ctx.fillStyle = 'rgba(255,255,255,0.4)';
  ctx.font = '10px sans-serif';
  ctx.textAlign = 'center';
  const labelStep = Math.max(1, Math.ceil(yearStarts.length / 8));
  for (let k = 0; k < yearStarts.length; k += labelStep) {
    const i = yearStarts[k];
    ctx.fillText(dates[i].slice(0,4), scaleX(i), H - 8);
  }

  // Y axis labels
  ctx.textAlign = 'right';
  const yTicks = 5;
  for (let i = 0; i <= yTicks; i++) {
    const v = minV + (maxV - minV) * i / yTicks;
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.fillText(v.toFixed(1), pad.l - 4, scaleY(v) + 4);
  }

  // Current value dot + label
  const lastVal = vals[vals.length - 1];
  if (lastVal !== null) {
    const x = scaleX(vals.length - 1), y = scaleY(lastVal);
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(x, y, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }

  // Store for hover
  canvas._dates = dates; canvas._vals = vals;
  canvas._pad = pad; canvas._cw = cw; canvas._len = dates.length;
  canvas._W = W; canvas._H = H; canvas._minV = minV; canvas._maxV = maxV;
}

function _valZoneNameFull(v, thresholds, isPE) {
  if (v === null) return '';
  const [t1, t2, t3] = thresholds;
  if (isPE) {
    if (v < t1) return '<span style="color:#3ab464">Cheap</span> — ถูกมาก โอกาสซื้อ';
    if (v < t2) return '<span style="color:#96c850">Fair</span> — ราคายุติธรรม';
    if (v < t3) return '<span style="color:#dca032">Slightly High</span> — ค่อนข้างแพง';
    return '<span style="color:#dc503c">Expensive</span> — แพงมาก ระวัง';
  } else {
    if (v < t1) return '<span style="color:#3ab464">Cheap</span> — ถูกกว่า Book Value';
    if (v < t2) return '<span style="color:#96c850">Fair</span> — สมเหตุสมผล';
    if (v < t3) return '<span style="color:#dca032">Slightly High</span> — ค่อนข้างแพง';
    return '<span style="color:#dc503c">Expensive</span> — แพงมาก';
  }
}

function setupValHover(canvasId, thresholds, avg, isPE, std) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  // อัพเดท threshold/avg/std ทุกครั้งที่เรียก (เช่น หลังแก้จุด "ปัจจุบัน" เป็นราคาสด)
  // แต่ผูก event listener แค่ครั้งเดียว กันซ้อนกันหลาย handler ตอน redraw ซ้ำ
  canvas._thresholds = thresholds;
  canvas._avg = avg;
  canvas._std = std || 1;
  canvas._isPE = isPE;
  if (canvas._hoverSet) return;
  canvas._hoverSet = true;

  const tip = document.createElement('div');
  tip.style.cssText = [
    'position:absolute','background:#1a2030','border:1px solid #3a4a5a',
    'padding:8px 12px','border-radius:8px','font-size:12px','line-height:1.7',
    'pointer-events:none','display:none','z-index:99','min-width:180px',
    'box-shadow:0 4px 16px rgba(0,0,0,0.5)'
  ].join(';');
  canvas.parentElement.style.position = 'relative';
  canvas.parentElement.appendChild(tip);

  // mousemove (desktop) กับ pointermove touch (ไอแพด/มือถือ — mousemove ไม่ทำงาน
  // บนจอสัมผัส) ใช้ตรรกะวาด tooltip เดียวกันทุกอย่าง ต่างกันแค่ต้นทางพิกัดเมาส์/นิ้ว
  // จึงรวมเป็นฟังก์ชันเดียวแล้วเรียกจากทั้งสอง event
  function showTip(clientX, clientY, rect) {
    const mx = clientX - rect.left;
    const idx = Math.round((mx - canvas._pad.l) / canvas._cw * (canvas._len - 1));
    if (idx < 0 || idx >= canvas._len) { tip.style.display = 'none'; return; }
    const val = canvas._vals[idx];
    if (val === null) { tip.style.display = 'none'; return; }
    const diff = val - canvas._avg;
    const zscore = canvas._std ? (diff / canvas._std) : 0;
    const diffStr = (diff >= 0 ? '+' : '') + diff.toFixed(2) + 'x';
    const zStr = (zscore >= 0 ? '+' : '') + zscore.toFixed(2) + 'σ';
    const zColor = Math.abs(zscore) > 2 ? (zscore>0?'#dc503c':'#3ab464')
                 : Math.abs(zscore) > 1 ? (zscore>0?'#dca032':'#96c850')
                 : 'rgba(255,255,255,0.6)';
    tip.innerHTML =
      `<b style="color:#e8eef5">${canvas._dates[idx]}</b><br>` +
      `<span style="font-size:15px;font-weight:700">${val.toFixed(2)}x</span>` +
      `<span style="font-size:12px;color:${zColor};margin-left:8px">${zStr}</span><br>` +
      `${_valZoneNameFull(val, canvas._thresholds, canvas._isPE)}<br>` +
      `<span style="color:rgba(255,255,255,0.4);font-size:11px">vs ค่าเฉลี่ย ${canvas._avg}x: </span>` +
      `<span style="color:${zColor};font-size:11px">${diffStr}</span>`;
    tip.style.display = 'block';
    const tipW = 200;
    const tipX = mx + 14 + tipW > canvas._W ? mx - tipW - 4 : mx + 14;
    tip.style.left = tipX + 'px';
    tip.style.top  = Math.max(4, clientY - rect.top - 60) + 'px';
  }

  canvas.addEventListener('mousemove', e => {
    if (!canvas._dates) return;
    showTip(e.clientX, e.clientY, canvas.getBoundingClientRect());
  });
  canvas.addEventListener('mouseleave', () => tip.style.display = 'none');

  // preventDefault กันหน้าเลื่อนตามตอนลากนิ้วสแกนดูค่าตามแนวแกน (chart scrubber
  // แบบแอปหุ้นทั่วไป) — เมาส์ไม่กระทบ ยังใช้ mousemove/mouseleave เดิม
  canvas.addEventListener('pointermove', e => {
    if (e.pointerType !== 'touch' || !canvas._dates) return;
    e.preventDefault();
    showTip(e.clientX, e.clientY, canvas.getBoundingClientRect());
  }, { passive: false });
  canvas.addEventListener('pointerup', e => { if (e.pointerType === 'touch') tip.style.display = 'none'; });
  canvas.addEventListener('pointercancel', e => { if (e.pointerType === 'touch') tip.style.display = 'none'; });
}

function renderValZoneFreq(containerId, vals, thresholds, labels, isPE) {
  const total = vals.filter(v => v !== null).length;
  if (!total) return;
  const counts = [0,0,0,0];
  for (const v of vals) {
    if (v === null) continue;
    if      (v < thresholds[0]) counts[0]++;
    else if (v < thresholds[1]) counts[1]++;
    else if (v < thresholds[2]) counts[2]++;
    else counts[3]++;
  }
  const colors = ['#3ab464','#96c850','#dca032','#dc503c'];
  const el = document.getElementById(containerId);
  if (!el) return;
  const thStr = isPE
    ? ['< 10x','10–15x','15–20x','> 20x']
    : ['< 1x', '1–1.5x','1.5–2x','> 2x'];
  const freqTips = counts.map((c, i) => {
    const pct = (c/total*100).toFixed(1);
    const rarity = c/total < 0.08 ? '⚡ หายากมาก — โอกาสพิเศษเมื่อเกิดขึ้น'
                 : c/total < 0.20 ? 'ค่อนข้างหายาก'
                 : c/total < 0.40 ? 'เกิดขึ้นพอสมควร'
                 : 'เกิดขึ้นบ่อย — เป็น zone ปกติของตลาด';
    return _zoneTip(labels[i], isPE) +
      `<hr><div class='tip-row'><span class='tip-label'>ความถี่</span>` +
      `<span class='tip-val'>${pct}% (${c}/${total} เดือน)</span></div>` +
      `<div style='margin-top:4px;font-size:11px;color:#96c850'>${rarity}</div>`;
  });
  el.innerHTML = counts.map((c, i) => `
    <div style="text-align:center;min-width:130px;cursor:help"
      data-vtip="${freqTips[i].replace(/"/g,'&quot;')}">
      <div style="font-size:22px;font-weight:700;color:${colors[i]}">${(c/total*100).toFixed(2)}%</div>
      <div style="font-size:12px;color:${colors[i]};font-weight:600">${labels[i]}</div>
      <div style="font-size:10px;color:var(--muted)">${thStr[i]} · ${c} เดือน</div>
      <div style="margin-top:4px;background:var(--bg-card2);border-radius:3px;height:4px">
        <div style="background:${colors[i]};opacity:0.6;height:100%;border-radius:3px;width:${Math.min(c/total*100,100)}%"></div>
      </div>
    </div>
  `).join('');
}

function _vtip(key, tips) {
  const t = tips[key] || '';
  return `<span class="val-tip" data-vtip="${t.replace(/"/g,'&quot;')}">ⓘ</span>`;
}

function _pctTip(pct) {
  let band, color, advice;
  if (pct < 30) { band='ถูกกว่าค่าเฉลี่ยมาก'; color='#3ab464'; advice='โอกาสซื้อระยะยาวที่หายาก'; }
  else if (pct < 60) { band='ปานกลาง สมเหตุสมผล'; color='#96c850'; advice='ราคายุติธรรมตามประวัติศาสตร์'; }
  else if (pct < 80) { band='แพงกว่าค่าเฉลี่ย'; color='#dca032'; advice='ควรระวัง ผลตอบแทนระยะยาวอาจต่ำกว่าปกติ'; }
  else { band='แพงมากในประวัติศาสตร์'; color='#dc503c'; advice='ความเสี่ยงสูง มักนำหน้าช่วงปรับฐาน'; }
  return `<div class='tip-head'>Percentile — ตำแหน่งในประวัติศาสตร์</div>` +
    `<b style='color:${color}'>${pct}%</b> — ${band}<hr>` +
    `<b>ความหมาย:</b> ใน 100 เดือนของประวัติศาสตร์<br>มี ${pct} เดือนที่ค่าต่ำกว่าปัจจุบัน<br>` +
    `→ ตลาดถูกกว่านี้มาแล้ว <b>${pct}%</b> ของเวลา<hr>` +
    `<div class='tip-row'><span class='tip-label'>0–30%</span><span class='tip-zone-cheap'>ถูกมาก (โอกาสซื้อ)</span></div>` +
    `<div class='tip-row'><span class='tip-label'>30–60%</span><span class='tip-zone-fair'>ปานกลาง</span></div>` +
    `<div class='tip-row'><span class='tip-label'>60–80%</span><span class='tip-zone-high'>แพงกว่าค่าเฉลี่ย</span></div>` +
    `<div class='tip-row'><span class='tip-label'>80–100%</span><span class='tip-zone-exp'>แพงมาก (เสี่ยงสูง)</span></div><hr>` +
    `<b>สรุป:</b> ${advice}`;
}

function _zoneTip(zone, isPE) {
  const tips = isPE ? {
    'Cheap':         { c:'#3ab464', desc:'P/E ต่ำกว่า 10x', detail:'ตลาดซื้อขายถูกมาก กำไรสูงเทียบราคา<br>เกิดเฉพาะช่วงวิกฤตหนัก (เช่น ปี 1997, 2008)<br><b>โอกาสทำกำไรระยะยาวสูงมาก</b>' },
    'Fair':          { c:'#96c850', desc:'P/E 10–15x',       detail:'ราคาสมเหตุสมผลตามมาตรฐาน SET<br>เป็น Zone ที่ตลาดอยู่บ่อยที่สุดในประวัติศาสตร์<br><b>เหมาะสำหรับลงทุนสะสมระยะยาว</b>' },
    'Slightly High': { c:'#dca032', desc:'P/E 15–20x',       detail:'ตลาดแพงกว่าค่าเฉลี่ยประวัติศาสตร์ (13.92x)<br>อาจอยู่ได้อีก 1-2 ปี หรือปรับฐานทุกเมื่อ<br><b>ลงทุนได้ แต่ควรเลือกหุ้นรายตัวมากกว่า DCA</b>' },
    'Expensive':     { c:'#dc503c', desc:'P/E > 20x',        detail:'ตลาดแพงมากในเชิงประวัติศาสตร์<br>มักเกิดช่วงฟองสบู่ (เช่น ปี 1993: P/E = 41x)<br><b>ความเสี่ยงสูง ควรระวังและลดการเปิดรับความเสี่ยง</b>' },
  } : {
    'Cheap':         { c:'#3ab464', desc:'P/BV ต่ำกว่า 1x',   detail:'ซื้อหุ้นได้ถูกกว่ามูลค่าทรัพย์สินสุทธิ<br>เกิดเฉพาะวิกฤตหนักมาก (เช่น ปี 1997–1998)<br><b>โอกาสทองที่หายากมากในประวัติศาสตร์</b>' },
    'Fair':          { c:'#96c850', desc:'P/BV 1–1.5x',       detail:'ราคาสมเหตุสมผล ตลาดซื้อขายใกล้มูลค่าทางบัญชี<br><b>เหมาะสำหรับลงทุนสะสมระยะยาว</b>' },
    'Slightly High': { c:'#dca032', desc:'P/BV 1.5–2x',       detail:'ตลาดมีพรีเมี่ยมเหนือมูลค่าทางบัญชีพอสมควร<br>ยังยอมรับได้ถ้ากำไรบริษัทยังเติบโต<br><b>เลือกหุ้น ROE สูงเพื่อ justify ราคา</b>' },
    'Expensive':     { c:'#dc503c', desc:'P/BV > 2x',         detail:'ตลาดซื้อขายแพงกว่ามูลค่าทางบัญชีมาก<br>ต้องการการเติบโตของกำไรสูงมากเพื่อ justify ราคา<br><b>ความเสี่ยงสูง ควรระวัง</b>' },
  };
  const t = tips[zone];
  if (!t) return '';
  return `<div class='tip-head' style='color:${t.c}'>${zone}</div>` +
    `<b>${t.desc}</b><hr>${t.detail}`;
}

function renderValuation() {
  if (!_valData) return;
  const pe  = _valData.pe;
  const pbv = _valData.pbv;
  // ไฟล์ที่ trim มือ/เวอร์ชันเก่า อาจขาด .series หรือ .stats ทั้งก้อน — กันไว้ให้ครบ
  // ไม่งั้น pe.series['SET'] / pe.stats['SET'] โยน TypeError กลางทาง หน้าเว็บว่างเปล่า
  if (!pe || !pbv || !pe.series || !pbv.series) {
    const el = document.getElementById('val-summary');
    if (el) el.innerHTML = '<div style="color:var(--red);padding:16px">ไฟล์ set_market_stats.json ไม่มีข้อมูล pe/pbv — ลองกด Rebuild ใหม่</div>';
    return;
  }
  pe.stats  = pe.stats  || {};
  pbv.stats = pbv.stats || {};

  const peF  = filterByPeriod(pe.dates,  pe.series['SET']  || [], _valPeriod);
  const pbvF = filterByPeriod(pbv.dates, pbv.series['SET'] || [], _valPeriod);

  const peStats  = _periodStats(pe.stats['SET']   || {}, peF.vals);
  const pbvStats = _periodStats(pbv.stats['SET']  || {}, pbvF.vals);

  const peThresh  = [10, 15, 20];
  const pbvThresh = [1, 1.5, 2];
  const zoneLabels = ['Cheap','Fair','Slightly High','Expensive'];

  // ── SD zone helper ───────────────────────────
  // color ใช้ _zColor เดียวกับ cross-sectional (ladder 2/1/-1/-2) — ที่นี่เพิ่มแค่ bg tint
  // + ข้อความไทยต่อโซน ไม่ทำ ladder สีซ้ำเอง
  function sdZoneInfo(zscore) {
    const z = zscore || 0;
    const color = _zColor(z);
    if (z >  2) return { label:`+${z.toFixed(2)}σ`, text:'แพงผิดปกติ',    color, bg:'rgba(220,80,60,0.12)'  };
    if (z >  1) return { label:`+${z.toFixed(2)}σ`, text:'แพงเกินค่าเฉลี่ย', color, bg:'rgba(220,160,50,0.10)' };
    if (z > -1) return { label:(z>=0?'+':'')+z.toFixed(2)+'σ', text:z>=0?'ใกล้ค่าเฉลี่ย (แพงกว่านิด)':'ใกล้ค่าเฉลี่ย (ถูกกว่านิด)', color, bg:'rgba(200,208,220,0.08)' };
    if (z > -2) return { label:`${z.toFixed(2)}σ`,  text:'ถูกกว่าค่าเฉลี่ย', color, bg:'rgba(150,200,80,0.10)'  };
    return              { label:`${z.toFixed(2)}σ`,  text:'ถูกผิดปกติ',    color, bg:'rgba(58,180,100,0.12)' };
  }

  function sdTipContent(s, label) {
    const bands = s.bands || {};
    const z = s.zscore || 0;
    const zi = sdZoneInfo(z);
    return `<div class='tip-head'>Z-Score — ตำแหน่ง SD</div>` +
      `ปัจจุบัน <b style='color:${zi.color}'>${zi.label}</b> — ${zi.text}<hr>` +
      `<div class='tip-row'><span class='tip-label'>+3σ</span><span class='tip-zone-exp'>${bands['+3σ']}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>+2σ</span><span class='tip-zone-high'>${bands['+2σ']}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>+1σ</span><span style='color:#e0d060'>${bands['+1σ']}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>avg</span><span class='tip-val'>${s.avg}x (±${s.std}x)</span></div>` +
      `<div class='tip-row'><span class='tip-label'>-1σ</span><span style='color:#96c850'>${bands['-1σ']}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>-2σ</span><span class='tip-zone-cheap'>${bands['-2σ']}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>-3σ</span><span class='tip-zone-cheap'>${bands['-3σ']}x</span></div><hr>` +
      `ค่า <0 = ถูกกว่าค่าเฉลี่ย | ค่า >0 = แพงกว่าค่าเฉลี่ย<br>` +
      `|z| > 2 พบแค่ ~5% ของเวลา = ผิดปกติมาก`;
  }

  // ── Tooltip content ──────────────────────────
  const TIPS = {
    pe: `<div class='tip-head'>P/E Ratio (Price-to-Earnings)</div>` +
      `<b>สูตร:</b> ราคาหุ้น ÷ กำไรต่อหุ้น (EPS)<br>` +
      `บอกว่านักลงทุนยอมจ่ายกี่บาทต่อกำไร 1 บาท<hr>` +
      `<div class='tip-row'><span class='tip-label'>ปัจจุบัน</span><span class='tip-val'>${peStats.current}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>ค่าเฉลี่ย</span><span class='tip-val'>${peStats.avg}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>ต่ำสุดเคย</span><span class='tip-zone-cheap'>${peStats.min}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>สูงสุดเคย</span><span class='tip-zone-exp'>${peStats.max}x (1993 ฟองสบู่)</span></div><hr>` +
      `<div class='tip-row'><span class='tip-label'>&lt; 10x</span><span class='tip-zone-cheap'>Cheap — โอกาสซื้อ</span></div>` +
      `<div class='tip-row'><span class='tip-label'>10–15x</span><span class='tip-zone-fair'>Fair — ราคายุติธรรม</span></div>` +
      `<div class='tip-row'><span class='tip-label'>15–20x</span><span class='tip-zone-high'>Slightly High — ระวัง</span></div>` +
      `<div class='tip-row'><span class='tip-label'>&gt; 20x</span><span class='tip-zone-exp'>Expensive — เสี่ยงสูง</span></div>`,

    pbv: `<div class='tip-head'>P/BV Ratio (Price-to-Book Value)</div>` +
      `<b>สูตร:</b> ราคาหุ้น ÷ มูลค่าทางบัญชีต่อหุ้น<br>` +
      `บอกว่าตลาดให้ราคากี่เท่าของทรัพย์สินสุทธิ<hr>` +
      `<div class='tip-row'><span class='tip-label'>ปัจจุบัน</span><span class='tip-val'>${pbvStats.current}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>ค่าเฉลี่ย</span><span class='tip-val'>${pbvStats.avg}x</span></div>` +
      `<div class='tip-row'><span class='tip-label'>ต่ำสุดเคย</span><span class='tip-zone-cheap'>${pbvStats.min}x (วิกฤต 1997)</span></div>` +
      `<div class='tip-row'><span class='tip-label'>สูงสุดเคย</span><span class='tip-zone-exp'>${pbvStats.max}x</span></div><hr>` +
      `<div class='tip-row'><span class='tip-label'>&lt; 1x</span><span class='tip-zone-cheap'>ถูกกว่ามูลค่าทรัพย์สิน</span></div>` +
      `<div class='tip-row'><span class='tip-label'>1–1.5x</span><span class='tip-zone-fair'>Fair — สมเหตุสมผล</span></div>` +
      `<div class='tip-row'><span class='tip-label'>1.5–2x</span><span class='tip-zone-high'>Slightly High</span></div>` +
      `<div class='tip-row'><span class='tip-label'>&gt; 2x</span><span class='tip-zone-exp'>Expensive</span></div>` +
      `<hr><b>ข้อดีเทียบ P/E:</b> เสถียรกว่าในช่วงกำไรผันผวน<br>เช่น COVID ที่กำไรร่วงแต่ Book Value คงที่`,

    peChart: `<div class='tip-head'>วิธีอ่านกราฟ P/E</div>` +
      `<div class='tip-row'><span class='tip-label'>เส้นฟ้า</span><span class='tip-val'>P/E รายเดือน</span></div>` +
      `<div class='tip-row'><span class='tip-label'>เส้นเหลือง</span><span class='tip-val'>ค่าเฉลี่ย${VAL_PERIOD_LABEL[_valPeriod]} (${peStats.avg}x)</span></div>` +
      `<div class='tip-row'><span class='tip-label'>จุดขาว</span><span class='tip-val'>ค่าปัจจุบัน</span></div><hr>` +
      `<b>เหตุการณ์สำคัญ:</b><br>` +
      `• <b>1993–1994:</b> P/E พุ่ง ~41x (ฟองสบู่ก่อนวิกฤต 2540)<br>` +
      `• <b>1997–1998:</b> วิกฤตต้มยำกุ้ง P/E ดิ่งหนัก<br>` +
      `• <b>2008–2009:</b> Subprime — P/E ต่ำมาก (โอกาสซื้อ)<br>` +
      `• <b>2020:</b> COVID — P/E สูงเพราะกำไรลด ไม่ใช่ราคาสูง<br>` +
      `• <b>hover</b> เหนือกราฟเพื่อดูค่ารายเดือน`,

    pbvChart: `<div class='tip-head'>วิธีอ่านกราฟ P/BV</div>` +
      `<div class='tip-row'><span class='tip-label'>เส้นฟ้า</span><span class='tip-val'>P/BV รายเดือน</span></div>` +
      `<div class='tip-row'><span class='tip-label'>เส้นเหลือง</span><span class='tip-val'>ค่าเฉลี่ย${VAL_PERIOD_LABEL[_valPeriod]} (${pbvStats.avg}x)</span></div><hr>` +
      `<b>เหตุการณ์สำคัญ:</b><br>` +
      `• <b>1997–1998:</b> P/BV ต่ำกว่า 1x — ซื้อถูกกว่า Book Value<br>` +
      `• SET ปกติซื้อขายที่ 1.3–1.8x<br>` +
      `• P/BV &lt; 1x เกิดได้เฉพาะวิกฤตระดับ systemic<hr>` +
      `<b>ข้อจำกัด:</b> บางอุตสาหกรรม (Tech, บริการ)<br>มี Book Value ต่ำตามธรรมชาติ ทำให้ P/BV ดูสูง`,

    zoneFreq: `<div class='tip-head'>Zone Frequency — สัดส่วนเวลาในแต่ละ Zone</div>` +
      `คำนวณจากข้อมูลรายเดือนทั้งหมดในประวัติศาสตร์<hr>` +
      `<b>วิธีใช้:</b><br>` +
      `• Zone ที่เกิดน้อย = โอกาสหายาก ควรให้ความสำคัญ<br>` +
      `• ถ้า Cheap เกิดแค่ 5% → เวลาตลาดถูกจริงๆ หายากมาก<hr>` +
      `<b>ตัวอย่าง:</b> ถ้า Cheap zone เกิด 8% ของเวลา<br>แต่ตอนนี้ตลาดอยู่ Cheap → โอกาสพิเศษมาก<br>` +
      `ควรเพิ่ม position มากกว่าเวลาปกติ`,
  };

  // ── Summary cards ────────────────────────────
  function makeCard(title, s, thresholds, isPE, overrideTip) {
    if (!s || !s.current) return '';
    const zone     = valZoneLabel(s.current, thresholds, zoneLabels);
    const zStyle   = valZoneStyle(s.current, thresholds);
    const zi       = sdZoneInfo(s.zscore);
    const sdTip    = sdTipContent(s, title).replace(/"/g,'&quot;');
    const zoneTip  = _zoneTip(zone, isPE).replace(/"/g,'&quot;');
    const pctTip   = _pctTip(s.percentile).replace(/"/g,'&quot;');
    const mainTip  = (overrideTip || (isPE ? TIPS.pe : TIPS.pbv)).replace(/"/g,'&quot;');
    return `
    <div class="card" style="flex:1;min-width:240px;padding:16px">
      <div style="font-size:12px;color:var(--muted);margin-bottom:6px;display:flex;align-items:center">
        ${title}
        <span class="val-tip" data-vtip="${mainTip}">ⓘ</span>
      </div>
      <div style="display:flex;align-items:baseline;gap:10px;margin-bottom:6px">
        <div style="font-size:28px;font-weight:700">${s.current}x</div>
        <div style="padding:2px 8px;border-radius:12px;font-size:12px;font-weight:700;
          background:${zi.bg};color:${zi.color};cursor:help;white-space:nowrap"
          data-vtip="${sdTip}">${zi.label} ${zi.text}</div>
      </div>
      <div style="margin:4px 0;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
        <span style="${zStyle};cursor:help" data-vtip="${zoneTip}">${zone}</span>
        <span style="font-size:11px;color:var(--muted)">·</span>
        <span style="font-size:11px;color:var(--muted);cursor:help" data-vtip="${pctTip}">
          Percentile <b style="color:#c8d0dc">${s.percentile}%</b>
        </span>
      </div>
      <div style="background:var(--bg-card2);border-radius:4px;height:5px;margin:8px 0;position:relative">
        <div style="background:#5ab4ff;height:100%;border-radius:4px;width:${Math.min(s.percentile,100)}%"></div>
      </div>
      <div style="font-size:11px;color:var(--muted)">
        เฉลี่ย ${s.avg}x &nbsp;·&nbsp; ±1σ = ${s.std}x &nbsp;·&nbsp; ต่ำสุด ${s.min}x &nbsp;·&nbsp; สูงสุด ${s.max}x
      </div>
    </div>`;
  }

  const maiPeRaw  = _trimNulls(pe.dates,  pe.series['mai']  || []);
  const maiPbvRaw = _trimNulls(pbv.dates, pbv.series['mai'] || []);
  const maiPeF  = filterByPeriod(maiPeRaw.dates,  maiPeRaw.vals,  _valPeriod);
  const maiPbvF = filterByPeriod(maiPbvRaw.dates, maiPbvRaw.vals, _valPeriod);
  const maiPeStats  = _periodStats(pe.stats['mai']  || {}, maiPeF.vals);
  const maiPbvStats = _periodStats(pbv.stats['mai'] || {}, maiPbvF.vals);
  const maiPeThresh  = [20, 40, 80];   // MAI PE สูงกว่า SET ตามธรรมชาติ
  const maiPbvThresh = [1, 1.5, 2];    // PBV เหมือนกัน

  renderValPeriodTable([
    { label: 'P/E SET',  dates: pe.dates,        vals: pe.series['SET'],  full: pe.stats['SET'],   current: (pe.stats['SET']   || {}).current },
    { label: 'P/BV SET', dates: pbv.dates,       vals: pbv.series['SET'], full: pbv.stats['SET'],  current: (pbv.stats['SET']  || {}).current },
    { label: 'P/E mai',  dates: maiPeRaw.dates,  vals: maiPeRaw.vals,     full: pe.stats['mai'],   current: (pe.stats['mai']   || {}).current },
    { label: 'P/BV mai', dates: maiPbvRaw.dates, vals: maiPbvRaw.vals,    full: pbv.stats['mai'],  current: (pbv.stats['mai']  || {}).current },
  ]);

  const TIPS_MAI_PE = `<div class='tip-head'>P/E Ratio (mai)</div>` +
    `<b>สูตร:</b> ราคา ÷ กำไรต่อหุ้น — ตลาด mai<hr>` +
    `<div class='tip-row'><span class='tip-label'>ปัจจุบัน</span><span class='tip-val'>${maiPeStats.current}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>ค่าเฉลี่ย</span><span class='tip-val'>${maiPeStats.avg}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>Median</span><span class='tip-val'>${maiPeStats.median}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>ต่ำสุดเคย</span><span class='tip-zone-cheap'>${maiPeStats.min}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>สูงสุดเคย</span><span class='tip-zone-exp'>${maiPeStats.max}x</span></div><hr>` +
    `<b>⚠ ข้อควรระวัง:</b> mai มีหุ้นขนาดเล็ก กำไรผันผวนสูง<br>P/E สูงมักเกิดจากกำไรหดชั่วคราว ไม่ใช่ราคาแพง<br>ควรดู <b>P/BV</b> และ <b>Median</b> มากกว่า avg<hr>` +
    `<div class='tip-row'><span class='tip-label'>&lt; 20x</span><span class='tip-zone-cheap'>Cheap</span></div>` +
    `<div class='tip-row'><span class='tip-label'>20–40x</span><span class='tip-zone-fair'>Fair</span></div>` +
    `<div class='tip-row'><span class='tip-label'>40–80x</span><span class='tip-zone-high'>Slightly High</span></div>` +
    `<div class='tip-row'><span class='tip-label'>&gt; 80x</span><span class='tip-zone-exp'>Expensive</span></div>`;

  const TIPS_MAI_PBV = `<div class='tip-head'>P/BV Ratio (mai)</div>` +
    `<b>สูตร:</b> ราคา ÷ มูลค่าทางบัญชี — ตลาด mai<hr>` +
    `<div class='tip-row'><span class='tip-label'>ปัจจุบัน</span><span class='tip-val'>${maiPbvStats.current}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>ค่าเฉลี่ย</span><span class='tip-val'>${maiPbvStats.avg}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>ต่ำสุดเคย</span><span class='tip-zone-cheap'>${maiPbvStats.min}x</span></div>` +
    `<div class='tip-row'><span class='tip-label'>สูงสุดเคย</span><span class='tip-zone-exp'>${maiPbvStats.max}x</span></div><hr>` +
    `P/BV เชื่อถือได้กว่า P/E สำหรับ mai<br>เพราะ Book Value เสถียรกว่ากำไร<hr>` +
    `<div class='tip-row'><span class='tip-label'>&lt; 1x</span><span class='tip-zone-cheap'>ถูกกว่า Book Value</span></div>` +
    `<div class='tip-row'><span class='tip-label'>1–1.5x</span><span class='tip-zone-fair'>Fair</span></div>` +
    `<div class='tip-row'><span class='tip-label'>1.5–2x</span><span class='tip-zone-high'>Slightly High</span></div>` +
    `<div class='tip-row'><span class='tip-label'>&gt; 2x</span><span class='tip-zone-exp'>Expensive</span></div>`;

  document.getElementById('val-summary').innerHTML =
    `<div style="width:100%;font-size:11px;color:var(--muted);margin-bottom:4px;font-weight:600;letter-spacing:.5px">SET INDEX</div>` +
    makeCard('P/E Ratio (SET)',  peStats,  peThresh,  true)  +
    makeCard('P/BV Ratio (SET)', pbvStats, pbvThresh, false) +
    `<div style="width:100%;font-size:11px;color:var(--muted);margin-top:10px;margin-bottom:4px;font-weight:600;letter-spacing:.5px">
       mai INDEX
       <span class="val-tip" data-vtip="&lt;div class='tip-head'&gt;mai vs SET&lt;/div&gt;mai (Market for Alternative Investment) คือตลาดสำหรับบริษัทขนาดกลาง-เล็ก&lt;hr&gt;&lt;b&gt;P/E mai&lt;/b&gt; มักสูงกว่า SET เพราะ&lt;br&gt;• หุ้นเล็กกำไรผันผวนสูง&lt;br&gt;• บางตัวขาดทุนชั่วคราวดึง avg ขึ้น&lt;br&gt;• ใช้ median แทน avg จะแม่นกว่า&lt;hr&gt;&lt;b&gt;P/BV mai&lt;/b&gt; เชื่อถือได้กว่า P/E&lt;br&gt;เพราะสะท้อน Book Value ที่เสถียรกว่า">ⓘ</span>
     </div>` +
    makeCard('P/E Ratio (mai)',  maiPeStats,  maiPeThresh,  true,  TIPS_MAI_PE)  +
    makeCard('P/BV Ratio (mai)', maiPbvStats, maiPbvThresh, false, TIPS_MAI_PBV);

  // ── Chart title tooltips (inject into DOM elements) ──
  setTimeout(() => {
    // ยิง id ตรงๆ — เดิมใช้ selector ตำแหน่ง (.card:nth-child(3)/(4)/:last-child) ซึ่งนับ
    // ลูกของ parent ตัวไหนก็ได้ในหน้า: การ์ด P/BV ใน #val-summary กับการ์ดใน #val-extra-box
    // ก็เข้าเงื่อนไขด้วย ทำให้ ⓘ "วิธีอ่านกราฟ P/E" ไปโผล่บนการ์ด Breadth และ ⓘ Zone
    // Frequency หายไปเฉยๆ (ดูบั๊กเดียวกันที่เตือนไว้ใน loadValDailyBox)
    const peTitle = document.getElementById('val-pe-chart-title');
    const pbvTitle = document.getElementById('val-pbv-chart-title');
    if (peTitle && !peTitle.querySelector('.val-tip')) {
      peTitle.insertAdjacentHTML('beforeend',
        `<span class="val-tip" data-vtip="${TIPS.peChart.replace(/"/g,'&quot;')}">ⓘ</span>`);
    }
    if (pbvTitle && !pbvTitle.querySelector('.val-tip')) {
      pbvTitle.insertAdjacentHTML('beforeend',
        `<span class="val-tip" data-vtip="${TIPS.pbvChart.replace(/"/g,'&quot;')}">ⓘ</span>`);
    }

    // Zone freq title
    const freqTitle = document.getElementById('val-zonefreq-title');
    if (freqTitle && !freqTitle.querySelector('.val-tip')) {
      freqTitle.insertAdjacentHTML('beforeend',
        `<span class="val-tip" data-vtip="${TIPS.zoneFreq.replace(/"/g,'&quot;')}">ⓘ</span>`);
    }

    // SET charts
    drawValChart('val-pe-canvas',  peF.dates,  peF.vals,  peThresh,  peStats);
    drawValChart('val-pbv-canvas', pbvF.dates, pbvF.vals, pbvThresh, pbvStats);
    setupValHover('val-pe-canvas',  peThresh,  peStats.avg,  true,  peStats.std);
    setupValHover('val-pbv-canvas', pbvThresh, pbvStats.avg, false, pbvStats.std);
    const infoTxt = (f, st) => f.dates.length
      ? `${f.dates[0]} – ${f.dates[f.dates.length-1]} | ${f.dates.length} เดือน | เส้นสีเหลือง = ค่าเฉลี่ย${VAL_PERIOD_LABEL[_valPeriod]} ${st.avg}x`
      : `ไม่มีข้อมูลในช่วง${VAL_PERIOD_LABEL[_valPeriod]}`;
    document.getElementById('val-pe-info').textContent  = infoTxt(peF,  peStats);
    document.getElementById('val-pbv-info').textContent = infoTxt(pbvF, pbvStats);

    // MAI charts — maiPeF/maiPbvF ถูกกรองตามช่วงเวลาแล้วด้านบน (ก่อน makeCard)
    if (maiPeStats.avg) {
      drawValChart('val-mai-pe-canvas',  maiPeF.dates,  maiPeF.vals,  maiPeThresh,  maiPeStats);
      setupValHover('val-mai-pe-canvas',  maiPeThresh,  maiPeStats.avg,  true,  maiPeStats.std);
      document.getElementById('val-mai-pe-info').textContent =
        `${maiPeF.dates[0]} – ${maiPeF.dates[maiPeF.dates.length-1]} | ${maiPeF.dates.length} เดือน | เส้นสีเหลือง = ค่าเฉลี่ย${VAL_PERIOD_LABEL[_valPeriod]} ${maiPeStats.avg}x (median ${maiPeStats.median}x)`;
    }
    if (maiPbvStats.avg) {
      drawValChart('val-mai-pbv-canvas', maiPbvF.dates, maiPbvF.vals, maiPbvThresh, maiPbvStats);
      setupValHover('val-mai-pbv-canvas', maiPbvThresh, maiPbvStats.avg, false, maiPbvStats.std);
      document.getElementById('val-mai-pbv-info').textContent =
        `${maiPbvF.dates[0]} – ${maiPbvF.dates[maiPbvF.dates.length-1]} | ${maiPbvF.dates.length} เดือน | เส้นสีเหลือง = ค่าเฉลี่ย${VAL_PERIOD_LABEL[_valPeriod]} ${maiPbvStats.avg}x`;
    }
  }, 50);

  // ── Zone frequency ───────────────────────────
  const zoneFreqEl = document.getElementById('val-zone-freq');
  zoneFreqEl.innerHTML = `
    <div style="width:100%">
      <div style="font-size:12px;color:var(--muted);margin-bottom:10px">P/E — ${(pe.dates||[]).length} เดือน</div>
      <div id="val-zone-pe" style="display:flex;gap:24px;flex-wrap:wrap;margin-bottom:16px"></div>
      <div style="font-size:12px;color:var(--muted);margin-bottom:10px">P/BV — ${(pbv.dates||[]).length} เดือน</div>
      <div id="val-zone-pbv" style="display:flex;gap:24px;flex-wrap:wrap"></div>
    </div>`;
  renderValZoneFreq('val-zone-pe',  pe.series['SET']  || [], peThresh,  zoneLabels, true);
  renderValZoneFreq('val-zone-pbv', pbv.series['SET'] || [], pbvThresh, zoneLabels, false);
}

// ══════════════════════════════════════════════════════════
// NVDR DATA
// ══════════════════════════════════════════════════════════
let _nvdrData = null;

async function loadNvdrData() {
  if (_nvdrData) return _nvdrData;
  try {
    // มือถือ/เน็ตช้า: fetch เปล่าค้างได้ไม่รู้จบถ้า TCP เงียบ (ไม่ resolve ไม่ reject) —
    // ต้องมี timeout ไม่งั้นหน้าที่พึ่งข้อมูลนี้ (Short/Confluence) ค้าง "กำลังโหลด" ตลอดกาล
    const r = await _fetchTimeout('/api/nvdr?t=' + Date.now(), 25000);
    if (!r.ok) return null;
    const raw = await r.json();
    // โหมด static (GitHub Pages/มือถือ): STATIC_MAP ชี้ /api/nvdr ไปที่ไฟล์สะสมดิบ
    // nvdr_data.json ตรงๆ ซึ่งแต่ละหุ้นมีแค่ {nvdr_pct, nvdr_shares, paid_up_shares, daily}
    // ต่างจาก route จริง (nvdr_summary) ที่แปลงเป็น {daily_count, last_snap, prev_snap,
    // daily_tail} ก่อนส่ง — reshape ให้ตรงกันตรงนี้ กันข้อความ "ยังไม่เก็บ daily trend"
    // หลอกผู้ใช้ทั้งที่ไฟล์ดิบมีประวัติจริงอยู่ (daily_count ที่หายไปจะเป็น undefined)
    const rawStocks = raw.stocks || {};
    const needsReshape = Object.values(rawStocks).some(v => v && v.daily_count === undefined && Array.isArray(v.daily));
    if (needsReshape) {
      const out = {};
      for (const [sym, v] of Object.entries(rawStocks)) {
        const daily = v.daily || [];
        out[sym] = {
          nvdr_pct:    v.nvdr_pct || 0,
          nvdr_shares: v.nvdr_shares || 0,
          daily_count: daily.length,
          last_snap:   daily.length ? daily[daily.length - 1] : null,
          prev_snap:   daily.length >= 2 ? daily[daily.length - 2] : null,
          daily_tail:  daily.slice(-21).map(dd => [dd.date, dd.nvdr_pct, dd.nvdr_shares || 0]),
        };
      }
      _nvdrData = { updated_at: raw.updated_at, stocks: out };
    } else {
      _nvdrData = raw;
    }
    return _nvdrData;
  } catch { return null; }
}

function nvdrBadge(sym) {
  if (!_nvdrData) return '';
  const v = _nvdrData.stocks?.[sym];
  if (!v || v.nvdr_pct < 5) return '';
  const col = v.nvdr_pct >= 20 ? '#5ab4ff' : v.nvdr_pct >= 10 ? '#7090d0' : '#5070a0';
  const tip = `NVDR ${v.nvdr_pct.toFixed(2)}% — ต่างชาติถือผ่าน NVDR`;
  return `<span title="${tip}" style="display:inline-block;font-size:8px;font-weight:700;color:${col};border:1px solid ${col};border-radius:3px;padding:0 3px;margin-left:3px;vertical-align:middle;line-height:13px;cursor:help">N</span>`;
}

function renderNvdrPopup(sym) {
  if (!_nvdrData) return '<div style="color:var(--muted);font-size:12px">กำลังโหลด...</div>';
  const v = _nvdrData.stocks?.[sym];
  if (!v) return `<div style="color:var(--muted);font-size:12px">ไม่มีข้อมูล NVDR สำหรับ ${sym}</div>`;

  const row = (label, val, color='', tip='') =>
    `<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05)"
          ${tip?`title="${tip}"`:''}><span style="font-size:11px;color:var(--muted);${tip?'cursor:help':''}">${label}</span>
     <span style="font-size:11px;font-weight:600;color:${color||'#c8d0dc'}">${val}</span></div>`;

  const pct = v.nvdr_pct;
  const pctCol = pct >= 20 ? '#5ab4ff' : pct >= 10 ? '#7090d0' : '#c8d0dc';
  const pctLevel = pct >= 20 ? 'สูงมาก — ต่างชาติ major holder'
                 : pct >= 10 ? 'สูง — ต่างชาติสนใจ'
                 : pct >= 5  ? 'ปานกลาง' : 'ต่ำ';

  const lastSnap = v.last_snap;
  const prevSnap = v.prev_snap;
  let trendHtml = '';
  if (lastSnap && prevSnap) {
    const chg = lastSnap.nvdr_pct - prevSnap.nvdr_pct;
    const chgStr = (chg >= 0 ? '+' : '') + chg.toFixed(3) + '%';
    const chgCol = chg > 0 ? '#3ab464' : '#e05252';
    const chgTip = chg > 0
      ? `NVDR เพิ่ม ${chgStr} จาก ${prevSnap.date} → ${lastSnap.date} — ต่างชาติซื้อเพิ่ม`
      : `NVDR ลด ${chgStr} จาก ${prevSnap.date} → ${lastSnap.date} — ต่างชาติขายออก`;
    trendHtml = row('เปลี่ยนแปลง (update ล่าสุด)', `<span style="color:${chgCol}">${chgStr}</span>`, '', chgTip);
  }

  return `
    <div style="font-size:10px;color:var(--muted);margin-bottom:6px">อัพเดท ${_nvdrData.updated_at||'—'}</div>
    ${row('NVDR% ถือครอง', pct.toFixed(3) + '% · ' + pctLevel, pctCol,
      'NVDR% = % ของหุ้นชำระแล้วที่ต่างชาติถือผ่าน NVDR · >5%=มีนัยยะ · >10%=สูง · >20%=สูงมาก')}
    ${row('จำนวน NVDR', (v.nvdr_shares/1e6).toFixed(2) + 'M หุ้น', '',
      'จำนวนหุ้น NVDR ที่ต่างชาติถืออยู่ทั้งหมด ณ วันอัพเดทล่าสุด')}
    ${trendHtml}
    ${v.daily_count > 0
      ? `<div style="font-size:10px;color:var(--muted);margin-top:6px" title="เพิ่มทุกครั้งที่กด Quick Update">มี ${v.daily_count} snapshots · กด Quick Update เพื่อดู trend</div>`
      : `<div style="font-size:10px;color:var(--muted);margin-top:6px">กด Quick Update เพื่อเริ่มเก็บ daily trend</div>`}`;
}

// ══════════════════════════════════════════════════════════
// FLOW CONFLUENCE — รวมสัญญาณ insider + short + NVDR
// ══════════════════════════════════════════════════════════
let _flowSigData = null;         // {stocks:[...], count, generated_at}
let _confluenceFilter = 'all';

// index หุ้นตาม symbol — ตารางสัญญาณรวม/Short เดิมเรียก DATA.stocks.find() ต่อแถว
// (และต่อการเปรียบเทียบตอน sort) ทำให้เป็น O(n²) บนตารางหลายร้อยแถว
// สร้าง Map ใหม่เมื่อ DATA ถูกแทนที่ด้วยก้อนใหม่เท่านั้น (เทียบ identity)
let _stockIdxMap = null, _stockIdxSrc = null;
function _stockBySym(sym) {
  // ต้องเช็ค !_stockIdxMap ด้วย ไม่ใช่แค่ _stockIdxSrc !== DATA — ตอนหน้าเว็บเพิ่งโหลด
  // ทั้งคู่เป็น null เท่ากัน (null !== null = false) ถ้าเรียกฟังก์ชันนี้ก่อน loadData()
  // เสร็จ (เช่นเปิดหน้า Insider เร็วๆ) จะข้าม Map ไปเลยแล้ว .get() ค้าง null พัง
  if (_stockIdxSrc !== DATA || !_stockIdxMap) {
    _stockIdxSrc = DATA;
    _stockIdxMap = new Map((DATA?.stocks || []).map(s => [s.symbol, s]));
  }
  return _stockIdxMap.get(sym);
}

// cache ฝั่ง client มีอายุจำกัด — เดิม cache ตลอด session ทำให้ checkWatchlistConfluence
// ที่ตั้ง interval ทุก 5 นาทีได้ก้อนเดิมทุกครั้ง (ไม่มีทางเจอสัญญาณใหม่จนกว่าจะ F5)
// ฝั่ง server cache 1 ชม. + invalidate ตอนข้อมูลต้นทางอัพเดตอยู่แล้ว ยิงถี่กว่านี้ไม่หนัก
let _flowSigTs = 0;
const _FLOW_SIG_TTL = 5 * 60 * 1000;

async function loadFlowSignals() {
  if (_flowSigData && (Date.now() - _flowSigTs < _FLOW_SIG_TTL)) return _flowSigData;
  try {
    // ดู loadNvdrData ด้านบน — fetch เปล่าไม่มี timeout ค้างได้ไม่รู้จบบนเน็ตมือถือที่ไม่นิ่ง
    const r = await _fetchTimeout('/api/flow-signals', 25000);
    if (!r.ok) return _flowSigData;   // ยิงไม่ผ่าน — ใช้ของเดิมดีกว่าคืน null ให้หน้าว่าง
    _flowSigData = await r.json();
    _flowSigTs = Date.now();
    return _flowSigData;
  } catch { return _flowSigData; }
}

function setConfluenceFilter(f, btn) {
  _confluenceFilter = f;
  document.querySelectorAll('#confluence-filters .filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  _renderConfluenceTable();
}

async function loadConfluencePage() {
  const body = document.getElementById('confluence-body');
  if (!body) return;
  const d = await loadFlowSignals();
  const meta = document.getElementById('confluence-meta');
  if (!d || !d.stocks) {
    body.innerHTML = '<div class="empty" style="padding:24px">ไม่มีข้อมูล (ต้องมี short/NVDR/insider sync ก่อน)</div>';
    return;
  }
  try {
    if (meta) meta.textContent = `${d.count} หุ้นมีสัญญาณ · อัพเดท ${d.generated_at || '—'}`;
    _renderConfluenceTable();
  } catch (e) {
    // กัน render พังแล้วค้างหน้าเดิมถาวรแบบไม่มี error โชว์เลย (ดู loadShortPage)
    console.error('loadConfluencePage render error:', e);
    body.innerHTML = `<div class="empty" style="padding:24px;color:var(--red)">เกิดข้อผิดพลาดขณะแสดงผล: ${e.message}</div>`;
  }
}

// ไอคอนทิศทางต่อสัญญาณ (▲ เขียว / ▼ แดง / – เทา)
function _dirIcon(dir, tip) {
  const t = tip ? ` title="${tip}"` : '';
  if (dir > 0) return `<span style="color:#3ab464;font-weight:700"${t}>▲</span>`;
  if (dir < 0) return `<span style="color:#e05252;font-weight:700"${t}>▼</span>`;
  return `<span style="color:#5a6472"${t}>–</span>`;
}

// ผู้ใช้คลิกหัวคอลัมน์เพื่อจัดเรียงเอง — ถ้ายังไม่คลิก (null) ใช้ลำดับ default ตาม preset filter ด้านล่าง (ไม่ทำลาย logic เดิม)
let _confluenceSort = null;   // { key, dir: 1=มาก→น้อย, -1=น้อย→มาก }
const _CONFLUENCE_SORT_GETTERS = {
  symbol: r => r.symbol || '',
  sector: r => _stockBySym(r.symbol)?.sector || '',
  price:  r => _stockBySym(r.symbol)?.price ?? null,
  ret_1d: r => _stockBySym(r.symbol)?.ret_1d ?? null,
  score:  r => r.score ?? null,
  ins_net: r => r.insider?.net_value_mbaht ?? null,
  short_pos: r => r.short?.short_pos_pct ?? null,
  nvdr_pct: r => r.nvdr?.nvdr_pct ?? null,
};
function confluenceSortBy(key) {
  if (_confluenceSort && _confluenceSort.key === key) _confluenceSort.dir *= -1;
  else _confluenceSort = { key, dir: (key === 'symbol' || key === 'sector') ? -1 : 1 };
  _renderConfluenceTable();
}
function _confluenceSortArrow(key) {
  if (!_confluenceSort || _confluenceSort.key !== key) return '';
  return _confluenceSort.dir === 1 ? ' ▼' : ' ▲';
}

function _renderConfluenceTable() {
  const body = document.getElementById('confluence-body');
  if (!body || !_flowSigData) return;
  let rows = _flowSigData.stocks;
  if (_confluenceFilter === 'bull')   rows = rows.filter(r => r.score >= 2);
  else if (_confluenceFilter === 'bear') {
    // เรียง bearish สุด (-3) ขึ้นก่อน — ลิสต์หลักเรียง score มาก→น้อย
    // ถ้าใช้ตรงๆ ฝั่ง bear จะได้ -2 ก่อน -3 (ตัวแรงสุดไปอยู่ท้าย)
    rows = rows.filter(r => r.score <= -2)
               .slice().sort((a, b) => a.score - b.score || b.n_signals - a.n_signals);
  }
  else if (_confluenceFilter === 'triple') rows = rows.filter(r => r.n_signals === 3);

  const searchQ = (document.getElementById('confluence-search')?.value || '').trim().toUpperCase();
  if (searchQ) rows = rows.filter(r => r.symbol.toUpperCase().includes(searchQ));

  if (_confluenceSort && _CONFLUENCE_SORT_GETTERS[_confluenceSort.key]) {
    // คลิกหัวคอลัมน์เองแล้ว — เรียงตามคอลัมน์นั้นแทน default ของ preset filter (ยังกรองตาม filter/search เดิมอยู่)
    const get = _CONFLUENCE_SORT_GETTERS[_confluenceSort.key];
    const dir = _confluenceSort.dir;
    rows = rows.slice().sort((a, b) => {
      const va = get(a), vb = get(b);
      if (typeof va === 'string' || typeof vb === 'string')
        return dir === 1 ? String(vb).localeCompare(String(va)) : String(va).localeCompare(String(vb));
      // แถวที่ไม่มีค่า (null/NaN) ลงล่างเสมอไม่ว่าเรียงทางไหน — กัน comparator คืน NaN
      // (เดิม getter คืน -Infinity ทำให้ -Infinity − (−Infinity) = NaN ตอนทั้งคู่ว่าง เรียงมั่ว)
      const na = va == null || Number.isNaN(va), nb = vb == null || Number.isNaN(vb);
      if (na && nb) return 0;
      if (na) return 1;
      if (nb) return -1;
      return dir === 1 ? vb - va : va - vb;
    });
  }

  if (!rows.length) {
    body.innerHTML = '<div class="empty" style="padding:24px">ไม่มีหุ้นตรงเงื่อนไขนี้</div>';
    return;
  }

  const scoreCell = s => {
    const col = s >= 2 ? '#3ab464' : s <= -2 ? '#e05252' : s > 0 ? '#7fae7f' : s < 0 ? '#c98787' : '#8899aa';
    return `<span style="font-weight:700;color:${col};font-size:14px">${s > 0 ? '+' : ''}${s}</span>`;
  };
  const mb = v => (v == null ? '' : (v >= 0 ? '+' : '') + v + ' ลบ.');

  const trs = rows.map(r => {
    const ins = r.insider || {}, sh = r.short || {}, nv = r.nvdr || {};
    // เช็คจาก detail field ไม่ใช่ dir — dir=0 อาจแปลว่า "มีข้อมูลแต่ทิศทางก้ำกึ่ง"
    // ไม่ใช่ "ไม่มีรายการ" (เดิม tooltip โกหกว่าไม่มีข้อมูลทั้งที่มี)
    const insTip = ins.n_buy != null ? `ผู้บริหารซื้อ ${ins.n_buy||0} / ขาย ${ins.n_sell||0} ครั้ง · สุทธิ ${mb(ins.net_value_mbaht)}${ins.dir ? '' : ' (ก้ำกึ่ง/มูลค่าน้อย — ไม่นับทิศทาง)'}` : 'ไม่มีรายการ insider 90 วัน';
    const shTip = sh.trend_pp != null ? `Short pos ${sh.short_pos_pct ?? '—'}% · เทรนด์ ${sh.trend_pp>0?'+':''}${sh.trend_pp} pp${sh.dir ? '' : ' (เปลี่ยนน้อยกว่า 0.1pp — ไม่นับทิศทาง)'}` : 'ไม่มีข้อมูล/เทรนด์ short';
    const nvTip = nv.trend_pp != null ? `NVDR ${nv.nvdr_pct ?? '—'}% · เทรนด์ ${nv.trend_pp>0?'+':''}${nv.trend_pp} pp${nv.dir ? '' : ' (เปลี่ยนน้อยกว่า 0.1pp — ไม่นับทิศทาง)'}` : 'ไม่มีข้อมูล/เทรนด์ NVDR';
    const star = r.n_signals === 3 ? ' <span title="ครบ 3 สัญญาณ" style="color:#e3b341">⭐</span>' : '';
    const stock = _stockBySym(r.symbol);
    const priceStr = stock?.price != null ? stock.price.toFixed(2) : '—';
    const retStr = stock ? pct(stock.ret_1d) : '—';
    const sectorStr = stock?.sector || '—';
    return `<tr style="border-bottom:1px solid rgba(255,255,255,0.05);cursor:pointer" onclick="openChartModal('${r.symbol}')">
      <td style="padding:6px 8px;font-weight:600;color:#58a6ff">${r.symbol}${star}${tvLink(r.symbol)}</td>
      <td style="padding:6px 8px;font-size:11px;color:#8899aa;max-width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${sectorStr}</td>
      <td style="padding:6px 8px;text-align:right;font-size:11px">${priceStr}</td>
      <td style="padding:6px 8px;text-align:right;font-size:11px">${retStr}</td>
      <td style="padding:6px 8px;text-align:center">${scoreCell(r.score)}</td>
      <td style="padding:6px 8px;text-align:center">${_dirIcon(ins.dir, insTip)}</td>
      <td style="padding:6px 8px;text-align:center">${_dirIcon(sh.dir, shTip)}</td>
      <td style="padding:6px 8px;text-align:center">${_dirIcon(nv.dir, nvTip)}</td>
      <td style="padding:6px 8px;text-align:right;font-size:11px;color:#8899aa">${ins.net_value_mbaht != null ? mb(ins.net_value_mbaht) : '—'}</td>
      <td style="padding:6px 8px;text-align:right;font-size:11px;color:#8899aa">${sh.short_pos_pct != null ? sh.short_pos_pct + '%' : '—'}</td>
      <td style="padding:6px 8px;text-align:right;font-size:11px;color:#8899aa">${nv.nvdr_pct != null ? nv.nvdr_pct + '%' : '—'}</td>
    </tr>`;
  }).join('');

  body.innerHTML = `<div class="tbl-scroll-page" style="overflow-x:auto"><table class="tbl" style="width:100%;min-width:820px;border-collapse:collapse">
    <thead><tr style="border-bottom:1px solid rgba(255,255,255,0.12);color:#8899aa;font-size:11px;text-align:center">
      <th style="padding:6px 8px;text-align:left;cursor:pointer" onclick="confluenceSortBy('symbol')">หุ้น${_confluenceSortArrow('symbol')}</th>
      <th style="padding:6px 8px;text-align:left;cursor:pointer" onclick="confluenceSortBy('sector')">Sector${_confluenceSortArrow('sector')}</th>
      <th style="padding:6px 8px;text-align:right;cursor:pointer" onclick="confluenceSortBy('price')">ราคา${_confluenceSortArrow('price')}</th>
      <th style="padding:6px 8px;text-align:right;cursor:pointer" onclick="confluenceSortBy('ret_1d')">1D%${_confluenceSortArrow('ret_1d')}</th>
      <th style="padding:6px 8px;cursor:pointer" onclick="confluenceSortBy('score')">Score${_confluenceSortArrow('score')}</th>
      <th style="padding:6px 8px" title="ผู้บริหารซื้อ/ขายสุทธิ 90 วัน">Insider</th>
      <th style="padding:6px 8px" title="เทรนด์สถานะ short">Short</th>
      <th style="padding:6px 8px" title="เทรนด์สัดส่วนต่างชาติ NVDR">NVDR</th>
      <th style="padding:6px 8px;text-align:right;cursor:pointer" onclick="confluenceSortBy('ins_net')">Insider สุทธิ${_confluenceSortArrow('ins_net')}</th>
      <th style="padding:6px 8px;text-align:right;cursor:pointer" onclick="confluenceSortBy('short_pos')">Short pos${_confluenceSortArrow('short_pos')}</th>
      <th style="padding:6px 8px;text-align:right;cursor:pointer" onclick="confluenceSortBy('nvdr_pct')">NVDR%${_confluenceSortArrow('nvdr_pct')}</th>
    </tr></thead><tbody>${trs}</tbody></table></div>`;
}

// สรุป flow confluence 1 บรรทัดในกราฟ modal (ใช้ข้อมูลชุดเดียวกับหน้า scanner)
function _loadFlowSummary(symbol) {
  const box = document.getElementById('cm-flow-summary');
  if (!box) return;
  box.innerHTML = '';
  box.style.display = 'none';
  loadFlowSignals().then(d => {
    if (_cmStock?.symbol !== symbol) return;   // เปลี่ยนหุ้นไปแล้ว
    if (!d || !d.stocks) return;
    const r = d.stocks.find(x => x.symbol === symbol);
    if (!r) return;
    const ins = r.insider || {}, sh = r.short || {}, nv = r.nvdr || {};
    const label = r.score >= 2 ? '<span style="color:#3ab464">เงินฉลาดไหลเข้า</span>'
                : r.score <= -2 ? '<span style="color:#e05252">เงินฉลาดไหลออก</span>'
                : r.score > 0 ? '<span style="color:#7fae7f">เอียงบวก</span>'
                : r.score < 0 ? '<span style="color:#c98787">เอียงลบ</span>' : 'ก้ำกึ่ง';
    box.innerHTML = `<div style="border:1px solid var(--border);background:var(--card2);border-radius:8px;padding:8px 12px;font-size:12px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      <span style="font-weight:600">🎯 สัญญาณเงินทุน: ${label} <span style="color:var(--text2);font-weight:400">(${r.score>0?'+':''}${r.score})</span></span>
      <span style="color:var(--text2);font-size:11px">Insider ${_dirIcon(ins.dir)} · Short ${_dirIcon(sh.dir)} · NVDR ${_dirIcon(nv.dir)}</span>
    </div>`;
    box.style.display = 'block';
  }).catch(() => {});
}

// ══════════════════════════════════════════════════════════
// SHORT SALES DATA
// ══════════════════════════════════════════════════════════
let _shortData = null;  // {period_from, period_to, last_api_update, stocks:{sym:{...}}}

// ── ป้ายช่วงเวลาของยอดสะสมรายงวด (period_vol / period_pct_value) ──────────────
// เดิม hardcode "6M" ทุกจุดเพราะ SET เคยให้ยอดย้อนหลัง 6 เดือน แต่ backend เปลี่ยนไป
// rebuild ตั้งแต่ 1 ม.ค. ของปี (YTD) แล้ว — ป้ายเลยโกหกผู้ใช้ (ข้อมูลจริง 9 ม.ค.–31 ก.ค.
// = ~7 เดือน) ทุกป้ายจึงต้อง derive จาก period_from/period_to ที่ API ส่งมาจริง
function _shortPeriodTag() {
  const f = _shortData?.period_from, t = _shortData?.period_to;
  if (!f || !t) return 'สะสม';
  // ต้นทางเริ่มนับใหม่ทุกต้นปี — from อยู่ในเดือน ม.ค. ปีเดียวกับ to = YTD
  if (f.slice(0, 4) === t.slice(0, 4) && f.slice(5, 7) === '01') return 'YTD';
  const months = Math.max(1, Math.round((new Date(t) - new Date(f)) / (30.44 * 864e5)));
  return months + 'M';
}

// ข้อความช่วงเต็มสำหรับ tooltip — บอกวันจริงไปเลย ไม่ต้องให้ผู้ใช้เดาว่า YTD คือกี่วัน
function _shortPeriodRange() {
  const f = _shortData?.period_from, t = _shortData?.period_to;
  return (f && t) ? `${f} ถึง ${t}` : 'ช่วงสะสมล่าสุด';
}

async function loadShortData() {
  if (_shortData) return _shortData;
  try {
    // ดู loadNvdrData ด้านบน — fetch เปล่าไม่มี timeout ค้างได้ไม่รู้จบบนเน็ตมือถือที่ไม่นิ่ง
    const r = await _fetchTimeout('/api/short-sales?t=' + Date.now(), 25000);
    if (!r.ok) return null;
    _shortData = await r.json();
    return _shortData;
  } catch { return null; }
}

function shortBadge(sym) {
  if (!_shortData) return '';
  const v = _shortData.stocks?.[sym];
  if (!v || !v.short_pos_pct) return '';
  const pct = v.short_pos_pct;
  // ไม่แสดงถ้า short position น้อยมาก
  if (pct < 0.5) return '';
  const col = pct >= 2 ? '#e05252' : pct >= 1 ? '#d07030' : '#b09030';
  const tip = `Short Position ${pct.toFixed(2)}% ของหุ้นชำระแล้ว · %Val ${_shortPeriodTag()} (${_shortPeriodRange()}): ${v.period_pct_value?.toFixed(2)}%`;
  return `<span title="${tip}" style="display:inline-block;font-size:8px;font-weight:700;color:${col};border:1px solid ${col};border-radius:3px;padding:0 3px;margin-left:4px;vertical-align:middle;line-height:13px;cursor:help">S</span>`;
}

function renderShortPopup(sym) {
  if (!_shortData) return '<div style="color:var(--muted);font-size:12px">ไม่มีข้อมูล (รัน import_short_sales.py ก่อน)</div>';
  const v = _shortData.stocks?.[sym];
  if (!v) return '<div style="color:var(--muted);font-size:12px">ไม่มีข้อมูล short sales สำหรับ ' + sym + '</div>';

  // กัน .toFixed()/เปรียบเทียบพังทั้ง popup ถ้าไฟล์ short_sales_data.json มีค่า null
  // (เขียนไม่สมบูรณ์/แก้มือ) — backend ปกติ default เป็น 0 อยู่แล้ว แต่กันซ้ำไว้เผื่อไฟล์เพี้ยน
  const shortPosPct = v.short_pos_pct ?? 0;
  const periodPctValue = v.period_pct_value ?? 0;
  const pos_m = ((v.short_pos ?? 0) / 1e6).toFixed(2);
  const vol_m = ((v.period_vol ?? 0) / 1e6).toFixed(1);
  const period = _shortData.period_from && _shortData.period_to
    ? `${_shortData.period_from} ถึง ${_shortData.period_to}` : '';
  const lastUpd = _shortData.last_api_update ? `อัพเดท ${_shortData.last_api_update}` : '';

  const row = (label, val, color='', tip='') =>
    `<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05)"
          ${tip ? `title="${tip}"` : ''}>
      <span style="font-size:11px;color:var(--muted);${tip?'cursor:help':''}">${label}</span>
      <span style="font-size:11px;font-weight:600;color:${color||'#c8d0dc'}">${val}</span>
    </div>`;

  const posColor = shortPosPct >= 2 ? '#e05252' : shortPosPct >= 1 ? '#d07030' : '#c8d0dc';
  const posLevel = shortPosPct >= 2 ? 'สูงมาก — squeeze potential สูง'
                 : shortPosPct >= 1 ? 'สูง สำหรับตลาดไทย'
                 : shortPosPct >= 0.5 ? 'เริ่มมีนัยยะ'
                 : 'ต่ำ';

  // daily trend — ใช้ last_snap + prev_snap จาก /api/short-sales (ไม่ได้ส่ง daily array ทั้งหมด)
  let dailyHtml = '';
  const lastSnap = v.last_snap;
  const prevSnap = v.prev_snap;
  const dailyCount = v.daily_count || 0;
  if (lastSnap && prevSnap) {
    const chg = (lastSnap.short_pos ?? 0) - (prevSnap.short_pos ?? 0);
    const chgStr = (chg >= 0 ? '+' : '') + (chg / 1e6).toFixed(2) + 'M';
    const chgCol = chg > 0 ? '#e05252' : '#3ab464';
    const chgTip = chg > 0
      ? `Short เพิ่ม ${chgStr} จาก ${prevSnap.date} → ${lastSnap.date} — short seller เพิ่มตำแหน่ง`
      : `Short ลด ${chgStr} จาก ${prevSnap.date} → ${lastSnap.date} — short seller กำลัง cover อาจเป็นแรงหนุนราคา`;
    dailyHtml = row('เปลี่ยนแปลง (update ล่าสุด)', `<span style="color:${chgCol}">${chgStr}</span>`, '', chgTip);
  }

  return `
    <div style="font-size:10px;color:var(--muted);margin-bottom:6px">${period} ${lastUpd ? '· ' + lastUpd : ''}</div>
    ${row('Short Position ค้าง', pos_m + 'M หุ้น', posColor,
      'จำนวนหุ้นที่ขาย short แล้วยังไม่ได้ซื้อคืน — ถ้าราคาขึ้น คนกลุ่มนี้ต้องรีบซื้อคืน (Short Squeeze)')}
    ${row('Short Position %', shortPosPct.toFixed(3) + '% · ' + posLevel, posColor,
      'Short Position % ของหุ้นชำระแล้วทั้งหมด — ตลาดไทย: >0.5%=มีนัยยะ · >1%=สูง · >2%=สูงมาก')}
    ${row(`ปริมาณ Short รวม (${_shortPeriodTag()})`, vol_m + 'M หุ้น', '',
      `ปริมาณหุ้นที่ถูกขาย short สะสมช่วง ${_shortPeriodRange()} — บอกว่า short seller สนใจหุ้นนี้มากแค่ไหน`)}
    ${row(`% Short ต่อการซื้อขาย (${_shortPeriodTag()})`, periodPctValue.toFixed(2) + '%', '',
      `% ของมูลค่าซื้อขายรวมที่เป็น short sell ช่วง ${_shortPeriodRange()} — ยิ่งสูง = short seller มีบทบาทในหุ้นนี้มาก`)}
    ${dailyHtml}
    ${dailyCount > 0
      ? `<div style="font-size:10px;color:var(--muted);margin-top:6px" title="อัพเดทเพิ่มทุกครั้งที่กด Quick Update">มี daily snapshot ${dailyCount} วัน · กด Quick Update เพื่อเพิ่ม</div>`
      : `<div style="font-size:10px;color:var(--muted);margin-top:6px">ยังไม่มี daily snapshot — กด Quick Update เพื่อเริ่มเก็บ trend</div>`}
  `;
}

// ══════════════════════════════════════════════════════════
// INSIDER — Accumulated Signal
// ══════════════════════════════════════════════════════════
let _insAccum = {};   // symbol → {buys, sells, net, people/sellPeople:Set, buyQty/sellQty, buyValue/sellValue, lastBuy, lastSell}

function buildInsAccum() {
  if (!_insData) return;
  _insAccum = {};
  _insData.r59.forEach(rec => {
    const sym = rec.symbol;
    if (!_insAccum[sym]) _insAccum[sym] = {
      buys:0, sells:0, net:0, people:new Set(), sellPeople:new Set(),
      // เก็บสองฝั่งสมมาตรกัน — เดิมเก็บเฉพาะฝั่งซื้อ ทำให้ไม่มีปริมาณ/มูลค่า/
      // ราคาเฉลี่ยของฝั่งขายให้โชว์เลย (valuedQty = เฉพาะรายการที่มีราคา
      // สำหรับ weighted avg ที่ถูกต้อง)
      buyQty:0,  buyValuedQty:0,  buyValue:0,
      sellQty:0, sellValuedQty:0, sellValue:0,
      lastBuy:null, lastSell:null,
    };
    const a = _insAccum[sym];
    const val = (rec.qty && rec.price && isFinite(rec.price)) ? rec.qty * rec.price : null;
    if (rec.action === 'buy') {
      a.buys++;
      a.people.add(rec.name || '?');
      a.buyQty += rec.qty || 0;
      if (val != null) { a.buyValue += val; a.buyValuedQty += rec.qty; }
      if (!a.lastBuy || rec.trade_date > a.lastBuy) a.lastBuy = rec.trade_date;
    } else if (rec.action === 'sell') {
      a.sells++;
      a.sellPeople.add(rec.name || '?');
      a.sellQty += rec.qty || 0;
      if (val != null) { a.sellValue += val; a.sellValuedQty += rec.qty; }
      if (!a.lastSell || rec.trade_date > a.lastSell) a.lastSell = rec.trade_date;
    }
  });
  // net = จำนวนครั้งซื้อ − ขาย — คิดครั้งเดียวหลังรวมครบ (เดิมคิดซ้ำทุก record)
  Object.values(_insAccum).forEach(a => { a.net = a.buys - a.sells; });
}

// ฝั่งเด่นของ insider ต่อหุ้น (>0 = ซื้อ, <0 = ขาย) — ใช้ "มูลค่าบาทสุทธิ" เป็นหลัก
// การนับ "จำนวนครั้ง" ล้วนๆ หลอกได้เมื่อขนาดธุรกรรมต่างกันมาก (ยืนยันจริง: GULF ซื้อ
// 1 ครั้ง 1,976.5M ขาย 2 ครั้งรวม 1,237.7M — นับครั้งได้ net=-1 จัดเป็น Net Sell ทั้งที่
// เงินไหลเข้าสุทธิ 738.8M บาท) fallback ไปนับครั้งเมื่อไม่มีราคาเลยทั้งสองฝั่ง
// ทุกที่ที่ตัดสินฝั่ง insider ต้องเรียกตัวนี้ ไม่ใช่อ่าน a.net ตรงๆ
function _insDominant(a) {
  if (!a) return 0;
  // มีราคาให้คิดมูลค่า -> ใช้มูลค่าบาทสุทธิ · แต่ถ้าบังเอิญซื้อ=ขายพอดี (net บาท = 0)
  // ทั้งที่มีธุรกรรมสองฝั่ง ให้ falls back ไปนับครั้ง แทนที่จะคืน 0 แล้วโดนกรองหายทั้งแถว
  if (a.buyValue > 0 || a.sellValue > 0) return (a.buyValue - a.sellValue) || a.net;
  return a.net;
}

// มูลค่าบาทแบบอ่านง่าย: ฿1.2B / ฿34.5M / ฿890K
function _insFmtBaht(v) {
  const a = Math.abs(v);
  if (a >= 1e9) return '฿' + (v / 1e9).toFixed(2) + 'B';
  if (a >= 1e6) return '฿' + (v / 1e6).toFixed(1) + 'M';
  if (a >= 1e3) return '฿' + (v / 1e3).toFixed(0) + 'K';
  return '฿' + v.toFixed(0);
}

function insiderBadge(sym) {
  const a = _insAccum[sym];
  // ฝั่งอิงมูลค่าบาทสุทธิเหมือนตารางสะสม Insider — เดิมใช้ a.net (นับครั้ง) ทำให้จุดสี
  // ขัดกับตัวเลขในแถวเดียวกันได้ (เคส GULF: จุดแดงแต่ตารางบอก Net Buy)
  const dom = _insDominant(a);
  if (!dom) return '';
  const netValue = a.buyValue - a.sellValue;
  const valPart = (a.buyValue > 0 || a.sellValue > 0)
    ? ` · สุทธิ ${netValue >= 0 ? '+' : '−'}${_insFmtBaht(Math.abs(netValue)).slice(1)}` : '';
  if (dom > 0) {
    const col = a.people.size >= 2 ? '#3ab464' : '#7dd4a0';
    const tip = `Insider ซื้อสะสม ${a.buys}x (${a.people.size} คน) ใน ${_insDays} วัน${valPart}`;
    return `<span title="${tip}" style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${col};margin-left:4px;vertical-align:middle;cursor:help"></span>`;
  } else {
    const col = '#dc503c';
    const tip = `Insider ขายสะสม ${a.sells}x (${a.sellPeople.size} คน) ใน ${_insDays} วัน${valPart}`;
    return `<span title="${tip}" style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${col};margin-left:4px;vertical-align:middle;cursor:help"></span>`;
  }
}

function renderInsAccumTable() {
  const el = document.getElementById('ins-accum-wrap');
  if (!el) return;
  // กล่องนี้สรุปจากแบบ 59 (ผู้บริหาร) ล้วนๆ — ถ้าปิดแหล่งข้อมูล 59 อยู่ ให้ซ่อนไปเลย
  // กันขัดกับตารางล่างที่เหลือแต่รายการผู้ถือหุ้นใหญ่
  if (!_insSrc.r59) { el.innerHTML = ''; return; }

  const allRows = Object.entries(_insAccum)
    .map(([sym, a]) => {
      const netValue = a.buyValue - a.sellValue;
      // ตัวชี้ขาดฝั่ง/กลุ่ม: มูลค่าบาทสุทธิเป็นหลัก (ดูเหตุผลที่ _insDominant)
      const dominant = _insDominant(a);
      return {sym, ...a, peopleCount: a.people.size, sellPeopleCount: a.sellPeople.size, netValue, dominant};
    })
    .filter(r => r.dominant !== 0);

  if (!allRows.length) { el.innerHTML = ''; return; }

  const q = (document.getElementById('ins-accum-search')?.value || '').trim().toUpperCase();
  const rows = (q ? allRows.filter(r => r.sym.toUpperCase().includes(q)) : allRows)
    .sort((a,b) => b.dominant - a.dominant);

  if (!rows.length) {
    el.innerHTML = `<div class="card" style="padding:14px;margin-bottom:14px;color:var(--muted);font-size:12px">ไม่พบหุ้นที่ตรงกับ "${_insEsc(q)}" ในสะสม Insider Activity ${_insDays} วัน</div>`;
    return;
  }

  const netBuyers  = rows.filter(r => r.dominant > 0);
  const netSellers = rows.filter(r => r.dominant < 0);

  // มูลค่าสุทธิรวมของแต่ละคอลัมน์ (บาท — เฉพาะรายการที่มีราคา)
  const buyersNetVal  = netBuyers.reduce((s, r) => s + r.netValue, 0);
  const sellersNetVal = netSellers.reduce((s, r) => s + r.netValue, 0);
  const sumTag = v => (r => `<span style="font-weight:400;opacity:.85"> · รวมสุทธิ ${r}${_insFmtBaht(Math.abs(v)).slice(1)}</span>`)(v >= 0 ? '+' : '−');

  el.innerHTML = `
    <div class="card" style="padding:14px;margin-bottom:14px">
      <div style="font-size:13px;font-weight:600;color:#c8d0dc;margin-bottom:12px">
        สะสม Insider Activity ${_insDays} วัน
        <span style="font-size:11px;font-weight:400;color:var(--muted);margin-left:8px">
          🟢 net buy: ${netBuyers.length} หุ้น &nbsp;|&nbsp; 🔴 net sell: ${netSellers.length} หุ้น
        </span>
      </div>
      <div style="display:flex;gap:16px;flex-wrap:wrap">

        ${netBuyers.length ? `
        <div style="flex:1;min-width:280px">
          <div style="font-size:11px;color:#3ab464;font-weight:600;margin-bottom:8px;padding-bottom:4px;border-bottom:1px solid rgba(58,180,100,0.2)">
            🟢 Net Buy — สะสมซื้อ (${netBuyers.length} หุ้น)${sumTag(buyersNetVal)}
          </div>
          ${netBuyers.map(r => _accumRow(r)).join('')}
        </div>` : ''}

        ${netSellers.length ? `
        <div style="flex:1;min-width:280px">
          <div style="font-size:11px;color:#dc503c;font-weight:600;margin-bottom:8px;padding-bottom:4px;border-bottom:1px solid rgba(220,80,60,0.2)">
            🔴 Net Sell — สะสมขาย (${netSellers.length} หุ้น)${sumTag(sellersNetVal)}
          </div>
          ${netSellers.slice().reverse().map(r => _accumRow(r)).join('')}
        </div>` : ''}

      </div>
    </div>`;
}

function _accumRow(r) {
  // ฝั่งเด่นของแถว (เลือกกลุ่มซื้อ/ขายให้แสดง avg price, cluster, badge) อิง
  // r.dominant (มูลค่าบาทสุทธิ เป็นหลัก, fallback นับครั้งเมื่อไม่มีราคาเลย — คำนวณไว้
  // แล้วใน renderInsAccumTable) — ตัวเลข "+54/-1" ที่โชว์ยังเป็นจำนวนครั้งดิบ (r.net)
  // แยกกันเจตนา: สีของตัวเลขนี้จึงอิงเครื่องหมายของตัวมันเอง ไม่ใช่ isBuySide เพื่อไม่ให้
  // เลข "-1" (ลบ) ไปโชว์เป็นสีเขียวตอนที่มูลค่าเงินเป็นฝั่งซื้อ (กรณี GULF)
  const isBuySide = r.dominant > 0;
  // cluster นับคนของฝั่งที่เด่น (ฝั่งซื้อสำหรับ net buy, ฝั่งขายสำหรับ net sell)
  const sideCount = isBuySide ? r.peopleCount : r.sellPeopleCount;
  const isCluster = sideCount >= 2;
  const netCol = r.net > 0 ? '#3ab464' : r.net < 0 ? '#dc503c' : 'var(--muted)';
  const netStr = (r.net > 0 ? '+' : '') + r.net;
  const clusterBadge = isCluster
    ? `<span style="font-size:9px;background:#1a3060;color:#5ab4ff;border-radius:3px;padding:1px 5px;margin-left:4px">Cluster ${sideCount} คน</span>`
    : '';
  const sideQty = isBuySide ? r.buyQty : r.sellQty;
  const qty = sideQty >= 1e6 ? (sideQty/1e6).toFixed(1)+'M' : sideQty >= 1e3 ? (sideQty/1e3).toFixed(0)+'K' : sideQty.toLocaleString();
  const lastDate = isBuySide ? r.lastBuy : r.lastSell;

  // find stock info from DATA
  const stock = _stockBySym(r.sym);
  const sector = stock?.sector || '';
  const curPrice = stock?.price;

  // มูลค่าสุทธิ (ซื้อรวม − ขายรวม, บาท) — โชว์เมื่อฝั่งใดฝั่งหนึ่งมีราคาให้คำนวณ
  const netValue = r.buyValue - r.sellValue;
  let netValuePart = '';
  if (r.buyValue > 0 || r.sellValue > 0) {
    const tip = `ซื้อรวม ${_insFmtBaht(r.buyValue)} · ขายรวม ${_insFmtBaht(r.sellValue)} (เฉพาะรายการที่มีราคา)`;
    netValuePart = `<span title="${tip}" style="font-size:10px;color:var(--muted);cursor:help">สุทธิ
      <span style="color:${netValue >= 0 ? '#3ab464' : '#dc503c'};font-weight:600">${netValue >= 0 ? '+' : '−'}${_insFmtBaht(Math.abs(netValue)).slice(1)}</span></span>`;
  }

  // % ของ MKT CAP (ใช้มูลค่าสุทธิ) — บอกนัยยะทั้งฝั่งซื้อและฝั่งขาย
  // เดิมคำนวณเป็น % ของจำนวนหุ้นและมีเฉพาะฝั่งซื้อ — ฝั่งขายใหญ่ๆ ไม่มีป้ายเตือนเลย
  let unusualBadge = '';
  if (stock?.mkt_cap > 0 && (r.buyValue > 0 || r.sellValue > 0)) {
    const pctCap = Math.abs(netValue) / stock.mkt_cap * 100;
    const verb = netValue >= 0 ? 'ซื้อ' : 'ขาย';
    const mk = (emoji, bg, col, label) =>
      `<span title="${verb}สุทธิ ${pctCap.toFixed(3)}% ของ Market Cap — ${label}" style="font-size:9px;background:${bg};color:${col};border-radius:3px;padding:1px 5px;margin-left:4px;font-weight:700">${emoji} ${pctCap.toFixed(2)}% ของ MKT CAP</span>`;
    if (pctCap >= 1)         unusualBadge = mk('🔴', '#5c1a0a', '#ff7070', 'ผิดปกติมาก มีนัยยะสูง');
    else if (pctCap >= 0.2)  unusualBadge = mk('🟠', '#3d2000', '#ff8c00', `${verb}ใหญ่ มีนัยยะ`);
    else if (pctCap >= 0.05) unusualBadge = mk('🟡', '#2d2a00', '#e6cc00', 'ควรสังเกต');
  }

  // weighted avg price ของฝั่งที่เด่น — ฝั่งซื้อใช้ buyValue/buyValuedQty,
  // ฝั่งขายใช้ sellValue/sellValuedQty (เดิมมีเฉพาะราคาเฉลี่ยฝั่งซื้อ)
  const avgPrice = isBuySide
    ? (r.buyValuedQty  > 0 ? r.buyValue  / r.buyValuedQty  : null)
    : (r.sellValuedQty > 0 ? r.sellValue / r.sellValuedQty : null);
  let pricePart = '';
  if (avgPrice) {
    const lbl = isBuySide ? 'avg ซื้อ' : 'avg ขาย';
    const avgStr = `฿${avgPrice.toFixed(2)}`;
    if (curPrice) {
      const diff = (curPrice - avgPrice) / avgPrice * 100;
      const diffCol = diff >= 0 ? '#3ab464' : '#dc503c';
      const diffStr = (diff >= 0 ? '+' : '') + diff.toFixed(2) + '%';
      pricePart = `<span title="ราคาปัจจุบันเทียบราคาเฉลี่ยที่ insider ${isBuySide ? 'ซื้อ' : 'ขาย'}" style="font-size:10px;color:var(--muted);cursor:help">${lbl}&nbsp;<span style="color:#c8d0dc">${avgStr}</span>&nbsp;<span style="color:${diffCol}">${diffStr}</span></span>`;
    } else {
      pricePart = `<span style="font-size:10px;color:var(--muted)">${lbl} <span style="color:#c8d0dc">${avgStr}</span></span>`;
    }
  }

  return `
    <div onclick="openChartModal('${_escJsAttr(r.sym)}')"
         style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;
                cursor:pointer;margin-bottom:3px;transition:background .15s;flex-wrap:wrap"
         onmouseover="this.style.background='rgba(255,255,255,0.04)'"
         onmouseout="this.style.background=''">
      <span style="font-weight:700;font-size:13px;color:#5ab4ff;min-width:50px">${_insEsc(r.sym)}${tvLink(r.sym)}</span>
      ${clusterBadge}
      ${unusualBadge}
      <span style="font-size:10px;color:var(--muted);flex:1;min-width:60px">${sector}</span>
      <span style="font-size:10px;color:var(--muted)">${r.buys}ซื้อ/${r.sells}ขาย · ${qty}หุ้น</span>
      ${netValuePart}
      ${pricePart}
      <span style="font-weight:700;font-size:13px;color:${netCol};min-width:28px;text-align:right">${netStr}</span>
      <span style="font-size:10px;color:var(--muted);min-width:70px;text-align:right">${lastDate||'—'}</span>
    </div>`;
}

// ══════════════════════════════════════════════════════════
// SHORT PAGE
// ══════════════════════════════════════════════════════════
let _shortSort = 'pos';   // column key
let _shortSortDir = -1;   // -1=desc, 1=asc
let _shortMinPct  = 0;    // filter: แสดงเฉพาะหุ้นที่ short_pos_pct >= ค่านี้

function setShortSortCol(col) {
  if (_shortSort === col) _shortSortDir *= -1;
  else { _shortSort = col; _shortSortDir = -1; }
  // sync top buttons
  document.getElementById('short-sort-pos').classList.toggle('active', col === 'pos');
  document.getElementById('short-sort-val').classList.toggle('active', col === 'val');
  renderShortTable();
}

function setShortSort(s, btn) {
  _shortSort = s; _shortSortDir = -1;
  document.querySelectorAll('[id^="short-sort-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  // Squeeze Radar มี sort คงที่ของตัวเอง (short_pos_pct มาก→น้อย) ไม่อิง _shortSort
  // จึงไม่ต้อง re-render ตอนเปลี่ยนการเรียงตาราง
  renderShortTable();
}

let _shortPageLoading = false;

// พิมพ์ค้นหาในตาราง Short — debounce กันรื้อ #short-table-wrap ทั้งก้อน + วาด sparkline
// canvas ทุกแถวใหม่ทุก keystroke (หลายร้อยแถว = jank เห็นชัดบน iPad)
let _shortSearchTimer = null;
function _shortSearchDebounced() {
  clearTimeout(_shortSearchTimer);
  _shortSearchTimer = setTimeout(renderShortTable, 180);
}

async function loadShortPage() {
  // กันเรียกซ้อน: showPage('short') + _startJob onDone ยิงพร้อมกันได้ (nav double-tap /
  // Quick Update เสร็จตอนเพิ่งเข้าหน้า) เดิมต่างคนต่าง fetch + render เต็มรอบ
  if (_shortPageLoading) return;
  _shortPageLoading = true;
  try {
    // แฟลช "กำลังโหลด..." เฉพาะรอบแรกที่ยังไม่มีข้อมูล — กลับเข้าหน้าเดิมที่ warm แล้ว
    // ไม่ต้องกระพริบ spinner (pattern เดียวกับ loadInsiderPage)
    if (!_shortData) {
      document.getElementById('short-table-wrap').innerHTML =
        '<div style="padding:20px;color:var(--muted);font-size:13px;text-align:center">กำลังโหลด...</div>';
    }
    const data = await loadShortData();
    if (!data) {
      document.getElementById('short-table-wrap').innerHTML =
        '<div style="padding:20px;color:var(--red);font-size:13px">ไม่พบข้อมูล — กรุณารัน import_short_sales.py ก่อน</div>';
      return;
    }
    try {
      const upd  = data.last_api_update ? `อัพเดท API ${data.last_api_update}` : 'ยังไม่มี daily update';
      const shortStatusEl = document.getElementById('short-status');
      const rangeStr = (data.period_from && data.period_to)
        ? `${data.period_from} ถึง ${data.period_to}` : 'ช่วงสะสมล่าสุด';
      shortStatusEl.textContent = `ข้อมูล ${rangeStr} · ${upd}`;
      const shortStaleBadge = _staleTradeDateBadge(data.last_api_update);
      if (shortStaleBadge) shortStatusEl.appendChild(shortStaleBadge);
      // ปุ่มเรียงเป็น HTML คงที่ — เขียนป้ายช่วงจริงทับ (ที่เหลือ render จาก JS อยู่แล้ว)
      const valSortBtn = document.getElementById('short-sort-val');
      if (valSortBtn) {
        valSortBtn.textContent = `% Vol ${_shortPeriodTag()}`;
        valSortBtn.title = `เรียงตาม % Short ต่อมูลค่าซื้อขายรวม ช่วง ${_shortPeriodRange()}`;
      }
      // Squeeze Radar ต้องใช้ _insAccum (insider) + _nvdrData ด้วย — เดิมต้องเข้าหน้า
      // Insider/NVDR ก่อนถึงจะมีข้อมูล (แถว NVDR% ในการ์ด squeeze หายเงียบๆ)
      // โหลดให้อัตโนมัติตรงนี้เลย ไม่ต้องพึ่งลำดับที่ผู้ใช้กดหน้าไหนก่อน
      if (!_insData) await fetchInsiderData();
      if (!_nvdrData) await loadNvdrData();
      renderShortSummary();
      renderShortSqueeze();
      renderShortTable();
    } catch (e) {
      // กัน render พังแล้วค้าง "กำลังโหลด..." ถาวรแบบไม่มี error โชว์เลย — แอปนี้ไม่มี
      // window.onunhandledrejection ดักจับ promise ที่ throw ไว้เลย (ต่างจาก fetchInsiderData/
      // loadFlowPage ที่มี try/catch ห่ออยู่แล้ว หน้านี้เคยไม่มี)
      console.error('loadShortPage render error:', e);
      document.getElementById('short-table-wrap').innerHTML =
        `<div style="padding:20px;color:var(--red);font-size:13px">เกิดข้อผิดพลาดขณะแสดงผล: ${e.message}</div>`;
    }
  } finally {
    _shortPageLoading = false;
  }
}

function filterShortByPct(minPct) {
  _shortMinPct = (_shortMinPct === minPct) ? 0 : minPct;  // toggle
  renderShortSummary();
  renderShortTable();
  if (_shortMinPct > 0) {
    const tbl = document.getElementById('short-table-wrap');
    if (tbl) tbl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

function renderShortSummary() {
  const el = document.getElementById('short-summary');
  if (!el || !_shortData) return;
  const stocks = Object.values(_shortData.stocks);
  const hasPos = stocks.filter(v => v.short_pos > 0).length;
  const over05 = stocks.filter(v => v.short_pos_pct >= 0.5).length;
  const over1  = stocks.filter(v => v.short_pos_pct >= 1).length;
  const over2  = stocks.filter(v => v.short_pos_pct >= 2).length;

  const card = (label, val, sub, col, minPct, tip) => {
    const active = _shortMinPct === minPct && minPct > 0;
    const clickable = minPct > 0;
    return `
    <div class="card" onclick="${clickable ? `filterShortByPct(${minPct})` : ''}"
         title="${tip}"
         style="padding:12px 16px;min-width:140px;flex:1;
                ${clickable ? 'cursor:pointer;' : ''}
                ${active ? `border:1px solid ${col};background:rgba(255,255,255,0.07)` : ''}
                transition:background .15s"
         ${clickable ? `onmouseover="this.style.background='rgba(255,255,255,0.06)'"
                        onmouseout="this.style.background='${active ? 'rgba(255,255,255,0.07)' : ''}'"`  : ''}>
      <div style="font-size:11px;color:var(--muted);margin-bottom:4px">${label}</div>
      <div style="font-size:20px;font-weight:700;color:${col}">${val}</div>
      <div style="display:flex;align-items:center;justify-content:space-between;margin-top:3px">
        <div style="font-size:10px;color:var(--muted)">${sub}</div>
        ${clickable ? `<div style="font-size:10px;color:${active ? col : 'var(--muted)'}">
          ${active ? '✕ ล้าง filter' : '→ กรองตาราง'}</div>` : ''}
      </div>
    </div>`;
  };

  el.innerHTML = [
    card('หุ้นที่มี Short Position', hasPos + ' หุ้น',
         `จากทั้งหมด ${stocks.length} หุ้น`, '#c8d0dc', 0,
         'จำนวนหุ้นทั้งหมดที่มี Short Position > 0 ในช่วงที่โหลดข้อมูล'),
    card('Short Pos > 0.5%', over05 + ' หุ้น',
         'เริ่มมีนัยยะสำหรับตลาดไทย', '#b09030', 0.5,
         'Short Position > 0.5% ของ Paid-up Capital — เริ่มมีนัยยะสำคัญสำหรับตลาด SET\nกดเพื่อกรองตารางด้านล่าง'),
    card('Short Pos > 1%', over1 + ' หุ้น',
         'สูง — short seller มั่นใจ bearish', '#d07030', 1,
         'Short Position > 1% — ระดับสูง บ่งชี้ short seller มีความมั่นใจขาลง\nกดเพื่อกรองตารางด้านล่าง'),
    card('Short Pos > 2%', over2 + ' หุ้น',
         'สูงมาก — squeeze potential สูง', '#e05252', 2,
         'Short Position > 2% — ระดับสูงมาก มี Squeeze Potential สูง\nถ้าราคาขึ้น short seller ต้องรีบซื้อคืน → ดันราคาขึ้นต่อ\nกดเพื่อกรองตารางด้านล่าง'),
  ].join('');
}

function renderShortSqueeze() {
  const el = document.getElementById('short-squeeze-wrap');
  if (!el || !_shortData) return;

  // หุ้นที่ short สูง (>1%) + insider ซื้อสุทธิ — ฝั่ง insider ตัดสินด้วยมูลค่าบาทสุทธิ
  // (_insDominant) ไม่ใช่การนับครั้ง เดิมใช้ ins.net > 0 ทำให้หุ้นที่ซื้อจิ๋วหลายครั้ง
  // แต่ขายก้อนใหญ่ครั้งเดียวยังติด radar เป็น "Insider ซื้อสะสม" อยู่
  const candidates = [];
  Object.entries(_shortData.stocks).forEach(([sym, v]) => {
    if (v.short_pos_pct < 1) return;
    const ins = _insAccum[sym];
    if (_insDominant(ins) <= 0) return;
    const nvdr = _nvdrData?.stocks?.[sym];
    // short_pos_pct: 0 กัน .toFixed() พังถ้าไฟล์สะสมมีค่า null (ดู renderShortTable)
    candidates.push({ sym, ...v, short_pos_pct: v.short_pos_pct ?? 0,
      ins, insNet: ins.buyValue - ins.sellValue, nvdr });
  });
  candidates.sort((a, b) => b.short_pos_pct - a.short_pos_pct);

  if (!candidates.length) {
    el.innerHTML = `
      <div class="card" style="padding:12px 16px;margin-bottom:14px">
        <div style="font-size:13px;font-weight:600;color:#c8d0dc;margin-bottom:6px">
          🎯 Squeeze Radar — Short สูง + Insider ซื้อ
        </div>
        <div style="font-size:12px;color:var(--muted)">
          ไม่พบหุ้นที่ short pos > 1% + insider ซื้อสะสมในช่วง ${_insDays} วันขณะนี้
        </div>
      </div>`;
    return;
  }

  el.innerHTML = `
    <div class="card" style="padding:14px;margin-bottom:14px">
      <div style="font-size:13px;font-weight:600;color:#c8d0dc;margin-bottom:12px">
        <span title="Squeeze = ราคาขึ้น ทำให้ short seller ต้องซื้อคืน (cover) → ดันราคาขึ้นต่อ · เงื่อนไข: Short Pos > 1% AND Insider ซื้อสุทธิ (วัดด้วยมูลค่าบาท ไม่ใช่จำนวนครั้ง)">🎯 Squeeze Radar</span>
        <span style="font-size:11px;font-weight:400;color:var(--muted);margin-left:8px">
          Short Pos > 1% + Insider ซื้อสะสมใน ${_insDays} วัน · ${candidates.length} หุ้น
        </span>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:8px">
        ${candidates.map(r => {
          const isCluster = r.ins.people.size >= 2;
          const stock = _stockBySym(r.sym);
          const posCol = r.short_pos_pct >= 2 ? '#e05252' : '#d07030';
          // มูลค่าสุทธิคือเกณฑ์ที่ใช้คัดเข้า radar — โชว์ไปเลย ไม่ใช่โชว์แค่จำนวนครั้ง
          const netPart = (r.ins.buyValue > 0 || r.ins.sellValue > 0)
            ? `<div style="display:flex;justify-content:space-between;margin-bottom:3px" title="มูลค่าซื้อ−ขายสุทธิของ insider (เฉพาะรายการที่มีราคา) — เกณฑ์ที่ใช้คัดเข้า Squeeze Radar">
                 <span style="font-size:11px;color:var(--muted)">ซื้อสุทธิ</span>
                 <span style="font-size:11px;font-weight:600;color:#3ab464">+${_insFmtBaht(r.insNet).slice(1)}</span>
               </div>` : '';
          return `
            <div onclick="openChartModal('${r.sym}')"
                 style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);
                        border-radius:8px;padding:10px 14px;cursor:pointer;min-width:160px;flex:1;
                        transition:background .15s"
                 onmouseover="this.style.background='rgba(255,255,255,0.08)'"
                 onmouseout="this.style.background='rgba(255,255,255,0.04)'">
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">
                <span style="font-weight:700;font-size:14px;color:#5ab4ff">${r.sym}${tvLink(r.sym)}</span>
                ${isCluster ? `<span title="Cluster = มี Insider ≥2 คนซื้อพร้อมกัน — สัญญาณแข็งแกร่งกว่า 1 คนซื้อ" style="font-size:9px;background:#1a3060;color:#5ab4ff;border-radius:3px;padding:1px 5px;cursor:help">Cluster</span>` : ''}
              </div>
              <div style="font-size:11px;color:var(--muted);margin-bottom:6px">${stock?.sector||''}</div>
              <div style="display:flex;justify-content:space-between;margin-bottom:3px">
                <span style="font-size:11px;color:var(--muted)">Short Pos</span>
                <span style="font-size:11px;font-weight:700;color:${posCol}">${r.short_pos_pct.toFixed(2)}%</span>
              </div>
              <div style="display:flex;justify-content:space-between;margin-bottom:3px">
                <span style="font-size:11px;color:var(--muted)">Insider ซื้อ</span>
                <span style="font-size:11px;font-weight:600;color:#3ab464">${r.ins.buys}x (${r.ins.people.size} คน)</span>
              </div>
              ${netPart}
              <div style="display:flex;justify-content:space-between;margin-bottom:3px">
                <span style="font-size:11px;color:var(--muted)">ราคา</span>
                <span style="font-size:11px;color:#c8d0dc">${stock?.price?.toFixed(2)||'—'}</span>
              </div>
              ${r.nvdr ? `<div style="display:flex;justify-content:space-between" title="NVDR% = ต่างชาติถือผ่าน NVDR">
                <span style="font-size:11px;color:var(--muted)">NVDR%</span>
                <span style="font-size:11px;color:#5ab4ff">${(r.nvdr.nvdr_pct ?? 0).toFixed(2)}%</span>
              </div>` : ''}
            </div>`;
        }).join('')}
      </div>
    </div>`;
}

function renderShortTable() {
  const el = document.getElementById('short-table-wrap');
  if (!el || !_shortData) return;

  const sortFn = {
    pos:    (a,b) => (b.short_pos_pct   - a.short_pos_pct)   * _shortSortDir * -1,
    pos_m:  (a,b) => (b.short_pos       - a.short_pos)       * _shortSortDir * -1,
    val:    (a,b) => (b.period_pct_value - a.period_pct_value)* _shortSortDir * -1,
    vol:    (a,b) => (b.period_vol       - a.period_vol)      * _shortSortDir * -1,
    price:  (a,b) => ((_stockBySym(b.sym)?.price||0) - (_stockBySym(a.sym)?.price||0)) * _shortSortDir * -1,
    ret1d:  (a,b) => ((_stockBySym(b.sym)?.ret_1d||0) - (_stockBySym(a.sym)?.ret_1d||0)) * _shortSortDir * -1,
    // คูณ -1 เหมือนคอลัมน์อื่น — เดิมไม่คูณ ทำให้คลิกแรกได้ Z→A ทั้งที่ tooltip บอก A→Z
    sym:    (a,b) => a.sym.localeCompare(b.sym) * _shortSortDir * -1,
    // อิงมูลค่าบาทสุทธิเหมือนคอลัมน์ Insider ที่แสดง (ดู _insDominant)
    ins:    (a,b) => (_insDominant(_insAccum[b.sym]) - _insDominant(_insAccum[a.sym])) * _shortSortDir * -1,
  };

  const _searchQ = (document.getElementById('short-search')?.value || '').trim().toUpperCase();
  const rows = Object.entries(_shortData.stocks)
    .filter(([sym, v]) => {
      if (_searchQ && !sym.toUpperCase().includes(_searchQ)) return false;
      // default: รวม short_pos > 0 ด้วย — บางตัว (DR/ไม่มี paid-up) pct เป็น 0
      // แต่มี position จริง เดิมโดนซ่อนจากตารางทั้งที่การ์ดสรุปนับรวม
      return _shortMinPct > 0
        ? v.short_pos_pct >= _shortMinPct
        : (v.short_pos_pct > 0 || v.short_pos > 0 || v.period_pct_value > 0);
    })
    // กัน .toFixed()/เปรียบเทียบพังทั้งตารางถ้าไฟล์ short_sales_data.json มีค่า null
    // (เขียนไม่สมบูรณ์/แก้มือ) — normalize เป็น 0 ที่จุดเดียวตรงนี้ ให้ทุกจุดที่ใช้ r.* ด้านล่างปลอดภัย
    .map(([sym, v]) => ({ sym, ...v,
      short_pos_pct: v.short_pos_pct ?? 0, period_pct_value: v.period_pct_value ?? 0,
      short_pos: v.short_pos ?? 0, period_vol: v.period_vol ?? 0 }))
    .sort(sortFn[_shortSort] || sortFn.pos);

  const filterBadge = _shortMinPct > 0
    ? `<span onclick="filterShortByPct(${_shortMinPct})" title="กดเพื่อล้าง filter"
            style="font-size:11px;background:rgba(208,112,48,0.2);color:#d07030;border:1px solid #d07030;
                   border-radius:4px;padding:2px 8px;margin-left:8px;cursor:pointer">
         Short Pos ≥ ${_shortMinPct}% · ${rows.length} หุ้น &nbsp;✕
       </span>` : '';

  if (!rows.length) {
    el.innerHTML = `<div style="padding:20px;color:var(--muted)">ไม่มีข้อมูลที่ตรงกับเงื่อนไข ${filterBadge}</div>`;
    return;
  }

  const posBar = (pct) => {
    const w = Math.min(pct / 4 * 100, 100);  // 4% = 100%
    const col = pct >= 2 ? '#e05252' : pct >= 1 ? '#d07030' : pct >= 0.5 ? '#b09030' : '#607080';
    return `<div style="display:inline-block;width:${w.toFixed(0)}%;height:4px;background:${col};border-radius:2px;vertical-align:middle;margin-left:4px"></div>`;
  };

  // คอลัมน์ตัวอักษร (sym) กลับด้าน: dir=-1 คือ A→Z (น้อยไปมาก) ตรงข้ามคอลัมน์ตัวเลข
  // ที่ dir=-1 คือมาก→น้อย — ถ้าใช้เกณฑ์เดียวกันหมด ลูกศรจะชี้สวนกับลำดับที่เห็นจริง
  const arr = (col) => {
    if (_shortSort !== col) return '⇅';
    const asc = col === 'sym' ? _shortSortDir === -1 : _shortSortDir === 1;
    return asc ? '▲' : '▼';
  };
  const th = (col, label, tip, right=true) =>
    `<th class="${right?'r':''}" style="cursor:pointer;user-select:none;white-space:nowrap"
         title="${tip}" onclick="setShortSortCol('${col}')">
       ${label} <span style="font-size:9px;color:${_shortSort===col?'#5ab4ff':'#506070'}">${arr(col)}</span>
     </th>`;

  el.innerHTML = `
    ${filterBadge ? `<div style="padding:6px 0 10px">${filterBadge}</div>` : ''}
    <table class="tbl" style="width:100%">
      <thead><tr>
        <th class="r" style="width:36px">#</th>
        ${th('sym','Symbol','เรียงตามชื่อหุ้น A→Z',false)}
        <th>ชื่อ</th>
        <th>Sector</th>
        ${th('pos','Pos%','Short Position ค้างอยู่ % ของหุ้นชำระแล้ว — ยิ่งสูงยิ่ง bearish')}
        ${th('pos_m','Position (M)','จำนวนหุ้น short ที่ยังค้างอยู่ (ยังไม่ได้ซื้อคืน)')}
        ${th('val',`%Val ${_shortPeriodTag()}`,`% Short ต่อมูลค่าซื้อขายรวม ช่วง ${_shortPeriodRange()} — ยิ่งสูง = short seller สนใจมาก`)}
        ${th('vol',`Vol ${_shortPeriodTag()} (M)`,`ปริมาณหุ้น short รวมช่วง ${_shortPeriodRange()}`)}
        ${th('price','ราคา','เรียงตามราคา')}
        ${th('ret1d','1D%','เรียงตาม % เปลี่ยนแปลงวันนี้')}
        ${th('ins','Insider','สถานะ Insider — net buy/sell ใน ' + _insDays + ' วัน',false)}
        <th style="width:70px" title="เทรนด์ Short Position ล่าสุด (สูงสุด 21 snapshots) — เขียว=ลด(cover, bullish) แดง=เพิ่ม(bearish)">เทรนด์</th>
      </tr></thead>
      <tbody id="short-tbl-body">
        ${rows.map((r, i) => {
          const stock = _stockBySym(r.sym);
          const ins   = _insAccum[r.sym];
          // ฝั่งอิงมูลค่าบาทสุทธิ (ดู _insDominant) ไม่ใช่นับครั้ง — ให้ตรงกับจุดสีข้าง
          // ชื่อหุ้นและตารางสะสม Insider
          const insDom = _insDominant(ins);
          const insHtml = insDom
            ? insDom > 0
              ? `<span style="color:#3ab464;font-size:11px">▲ ซื้อ ${ins.buys}x</span>`
              : `<span style="color:#e05252;font-size:11px">▼ ขาย ${ins.sells}x</span>`
            : '—';
          const posCol = r.short_pos_pct >= 2 ? '#e05252' : r.short_pos_pct >= 1 ? '#d07030' : r.short_pos_pct >= 0.5 ? '#b09030' : '#8090a0';
          return `<tr style="cursor:pointer" data-sym="${r.sym}" onclick="showShortDetail('${r.sym}',this)">
            <td class="r" style="color:var(--muted);font-size:11px">${i+1}</td>
            <td><strong class="sym-link" style="color:#5ab4ff" onclick="event.stopPropagation();openChartModal('${r.sym}')">${r.sym}</strong>${tvLink(r.sym)}${insiderBadge(r.sym)}</td>
            <td style="font-size:11px;color:var(--text2);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${stock?.name||'—'}</td>
            <td style="font-size:11px;color:var(--muted)">${stock?.sector||'—'}</td>
            <td class="r" style="font-weight:700;color:${posCol}">
              ${r.short_pos_pct.toFixed(3)}%${posBar(r.short_pos_pct)}
            </td>
            <td class="r" style="font-size:11px">${(r.short_pos/1e6).toFixed(2)}M</td>
            <td class="r" style="font-size:11px;color:${r.period_pct_value>=5?'#e05252':r.period_pct_value>=3?'#d07030':'#8090a0'}">${r.period_pct_value.toFixed(2)}%</td>
            <td class="r" style="font-size:11px">${(r.period_vol/1e6).toFixed(1)}M</td>
            <td class="r" style="font-size:11px">${stock?.price?.toFixed(2)||'—'}</td>
            <td class="r">${stock ? pct(stock.ret_1d) : '—'}</td>
            <td style="font-size:11px">${insHtml}</td>
            <td><canvas class="short-spark-canvas" style="width:60px;height:22px;display:block"></canvas></td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>`;

  _renderShortSparklines(rows);
}

// วาด sparkline เทรนด์ short position ต่อแถว — ใช้ daily_tail ที่ /api/short-sales
// ส่งมาแล้ว (ไม่ต้อง fetch เพิ่มต่อหุ้น) เขียว=short ลด(cover,bullish) แดง=เพิ่ม(bearish)
// กลับสีจาก drawSparkline เดิม (ที่ถือว่าค่าขึ้น=บวก) เพราะ short เพิ่ม=ลบ
function _renderShortSparklines(rows) {
  requestAnimationFrame(() => {
    document.querySelectorAll('#short-tbl-body tr[data-sym]').forEach(row => {
      const sym = row.dataset.sym;
      const v = _shortData?.stocks?.[sym];
      const tail = v?.daily_tail;
      if (!tail || tail.length < 2) return;
      const canvas = row.querySelector('.short-spark-canvas');
      if (!canvas) return;
      const prices = tail.map(t => [t[0], t[1] ?? 0]);   // [date, short_pos] — กัน null จากไฟล์สะสมเพี้ยน
      const trend = prices[prices.length-1][1] - prices[0][1];
      drawSparkline(canvas, prices, -trend);   // กลับเครื่องหมาย: short ลด = เขียว
    });
  });
}

let _shortDetailSym = null;
let _shortDetailSeq = 0;   // กด row รัวๆ -> response ที่ช้ากว่ามาทีหลังทับ panel ของ row ล่าสุด

async function showShortDetail(sym, rowEl) {
  const seq = ++_shortDetailSeq;
  // highlight row
  document.querySelectorAll('#short-table-wrap tr.selected-row')
    .forEach(r => { r.classList.remove('selected-row'); r.style.background = ''; });
  if (rowEl) { rowEl.classList.add('selected-row'); rowEl.style.background = 'rgba(90,180,255,0.08)'; }

  const panel = document.getElementById('short-detail-panel');
  panel.style.display = 'block';
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

  _shortDetailSym = sym;
  const stock = _stockBySym(sym);
  document.getElementById('short-detail-title').textContent = sym + (stock ? '  ' + stock.name : '');

  // ดึง daily snapshots จาก API — เวอร์ชันเว็บไม่มี endpoint รายตัว (404)
  // ใช้ daily_tail จาก summary ที่โหลดไว้แล้วแทน (เดิมไม่เช็ค d.error เลย
  // ทำให้ panel โชว์ undefined%/NaN บนเว็บ)
  try {
    const r = await _fetchTimeout(`/api/short-sales/${encodeURIComponent(sym)}`, 15000, 'หมดเวลารอข้อมูล Short Sale รายตัว (เกิน 15 วิ) — ลองใหม่อีกครั้ง');
    if (seq !== _shortDetailSeq) return;   // มี row ใหม่กว่าถูกกดระหว่างรอ — ทิ้งผลนี้
    let d = await r.json();
    if (seq !== _shortDetailSeq) return;
    let capped = false;   // true = เวอร์ชันเว็บ ใช้ daily_tail ที่ตัดไว้ 21 วัน
    if (d.error) {
      const v = _shortData?.stocks?.[sym];
      if (!v) throw new Error(d.error);
      capped = (v.daily_count || 0) > (v.daily_tail || []).length;
      d = { ...v, daily: (v.daily_tail || []).map(t => ({ date: t[0], short_pos: t[1], short_pos_pct: t[2] })) };
    }
    const daily = d.daily || [];
    // เวอร์ชันเว็บส่ง daily_tail แค่ 21 วัน — โชว์ count จริงจาก daily_count ไม่ใช่ความยาว tail
    const snapCount = (capped && d.daily_count) ? d.daily_count : daily.length;

    document.getElementById('short-detail-sub').textContent =
      daily.length > 0
        ? `${snapCount} snapshots${capped ? ' (แสดง 21 ล่าสุด)' : ''} (${daily[0].date} → ${daily[daily.length-1].date})`
        : 'ยังไม่มี daily snapshots — กด Quick Update เพื่อเริ่มเก็บข้อมูล';

    // stats
    const ins = _insAccum[sym];
    const insDom = _insDominant(ins);   // อิงมูลค่าบาทสุทธิ ไม่ใช่นับครั้ง
    const insHtml = insDom
      ? insDom > 0
        ? `<span style="color:#3ab464">▲ Insider ซื้อ ${ins.buys}x (${ins.people.size} คน)</span>`
        : `<span style="color:#e05252">▼ Insider ขาย ${ins.sells}x (${ins.sellPeople.size} คน)</span>`
      : '<span style="color:var(--muted)">ไม่มีข้อมูล Insider</span>';

    document.getElementById('short-detail-stats').innerHTML = [
      `<div title="Short Position ค้างอยู่ % ของหุ้นชำระแล้ว — ยิ่งสูงยิ่ง bearish · >1% = สูงสำหรับไทย · >2% = สูงมาก"><div style="font-size:10px;color:var(--muted);cursor:help">Short Pos %</div><div style="font-size:14px;font-weight:700;color:${d.short_pos_pct>=2?'#e05252':d.short_pos_pct>=1?'#d07030':'#c8d0dc'}">${d.short_pos_pct?.toFixed(3)}%</div></div>`,
      `<div title="จำนวนหุ้น short ที่ยังค้างอยู่ (ยังไม่ได้ซื้อคืน) — ถ้าราคาขึ้น คนเหล่านี้ต้องซื้อคืน = Short Squeeze"><div style="font-size:10px;color:var(--muted);cursor:help">Outstanding</div><div style="font-size:14px;font-weight:700;color:#c8d0dc">${((d.short_pos ?? 0)/1e6).toFixed(2)}M</div></div>`,
      `<div title="% Short ต่อมูลค่าซื้อขายรวม ช่วง ${_shortPeriodRange()} — ยิ่งสูง = short seller สนใจหุ้นนี้มาก"><div style="font-size:10px;color:var(--muted);cursor:help">%Val ${_shortPeriodTag()}</div><div style="font-size:14px;font-weight:700;color:#c8d0dc">${d.period_pct_value?.toFixed(2)}%</div></div>`,
      `<div><div style="font-size:10px;color:var(--muted)">ราคา</div><div style="font-size:14px;font-weight:700;color:#c8d0dc">${stock?.price?.toFixed(2)||'—'}</div></div>`,
      `<div title="สถานะ Insider ใน ${_insDays} วัน จากหน้า Insider (ต้องโหลดก่อน)"><div style="font-size:10px;color:var(--muted);cursor:help">Insider (${_insDays}ว)</div><div style="font-size:13px;font-weight:600">${insHtml}</div></div>`,
    ].join('');

    drawShortTrendChart(daily);
  } catch(e) {
    document.getElementById('short-detail-sub').textContent = 'โหลดไม่สำเร็จ: ' + e.message;
  }
}

// วาดเฉพาะ snapshot ที่มีจริงใน daily — เดิมเติมจุด "วันนี้" ด้วยค่า short_pos ปัจจุบัน
// ซึ่ง (ก) ซ้ำกับ daily[-1] เสมออยู่แล้ว เพราะ backend เขียนทั้งสองที่จาก snap ก้อนเดียวกัน
// และ (ข) ถ้าเปิดดูวันเสาร์-อาทิตย์/วันหยุด จะได้จุดวันที่ไม่ใช่วันทำการโผล่ท้ายกราฟ
function drawShortTrendChart(daily) {
  const canvas = document.getElementById('short-trend-canvas');
  if (!canvas) return;
  const W = canvas.offsetWidth || 600;
  const H = 140;
  canvas.width  = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);

  if (!daily || daily.length === 0) {
    // ยังไม่มีข้อมูล — แสดง placeholder
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.beginPath();
    // roundRect ไม่มีบน Safari < 16 (iPad รุ่นเก่า) — เช็คก่อนเหมือน call site อื่นทั้งหมด
    if (ctx.roundRect) ctx.roundRect(0, 0, W, H, 8);
    else ctx.rect(0, 0, W, H);
    ctx.fill();
    ctx.fillStyle = '#607080';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('ยังไม่มีข้อมูล trend — กด Quick Update เพื่อเริ่มเก็บ daily snapshots', W/2, H/2 - 8);
    ctx.font = '11px sans-serif';
    ctx.fillStyle = '#405060';
    ctx.fillText('Short Position จะถูกบันทึกทุกครั้งที่กด Quick Update', W/2, H/2 + 12);
    return;
  }

  const points = daily.map(d => ({ date: d.date, val: d.short_pos ?? 0 }));
  if (points.length < 2) {
    ctx.fillStyle = '#607080';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('ต้องการอย่างน้อย 2 snapshots เพื่อแสดง trend', W/2, H/2);
    return;
  }

  const PAD = { top: 16, bottom: 28, left: 52, right: 16 };
  const PW = W - PAD.left - PAD.right;
  const PH = H - PAD.top - PAD.bottom;

  const vals = points.map(p => p.val);
  const minV = Math.min(...vals);
  const maxV = Math.max(...vals);
  const range = maxV - minV || 1;
  const toX = i => PAD.left + (i / (points.length - 1)) * PW;
  const toY = v => PAD.top + PH - ((v - minV) / range) * PH;

  // grid lines
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  [0, 0.25, 0.5, 0.75, 1].forEach(f => {
    const y = PAD.top + PH * (1 - f);
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + PW, y); ctx.stroke();
    const label = ((minV + range * f) / 1e6).toFixed(1) + 'M';
    ctx.fillStyle = '#506070';
    ctx.font = '9px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(label, PAD.left - 4, y + 3);
  });

  // gradient fill
  const grad = ctx.createLinearGradient(0, PAD.top, 0, PAD.top + PH);
  grad.addColorStop(0, 'rgba(224,82,82,0.25)');
  grad.addColorStop(1, 'rgba(224,82,82,0.02)');
  ctx.beginPath();
  ctx.moveTo(toX(0), toY(points[0].val));
  points.forEach((p, i) => ctx.lineTo(toX(i), toY(p.val)));
  ctx.lineTo(toX(points.length-1), PAD.top + PH);
  ctx.lineTo(toX(0), PAD.top + PH);
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();

  // line
  ctx.beginPath();
  ctx.moveTo(toX(0), toY(points[0].val));
  points.forEach((p, i) => ctx.lineTo(toX(i), toY(p.val)));
  ctx.strokeStyle = '#e05252';
  ctx.lineWidth = 2;
  ctx.lineJoin = 'round';
  ctx.stroke();

  // dots
  points.forEach((p, i) => {
    const x = toX(i), y = toY(p.val);
    ctx.beginPath();
    ctx.arc(x, y, i === points.length-1 ? 4 : 2.5, 0, Math.PI*2);
    ctx.fillStyle = i === points.length-1 ? '#ff8080' : '#e05252';
    ctx.fill();
  });

  // date labels (แสดงทุก N จุด) — บังคับให้จุดสุดท้ายโชว์เสมอ แต่ถ้า label
  // ก่อนหน้าอยู่ใกล้กันเกินไป (ระยะพิกเซลน้อยกว่า minGapPx) ให้ตัดอันก่อนหน้าทิ้ง
  // กันข้อความทับกัน (เจอกับ dataset ยาว เช่น 115 snapshots)
  const step = Math.max(1, Math.floor(points.length / 8));
  const labelIdx = [];
  for (let i = 0; i < points.length; i += step) labelIdx.push(i);
  if (labelIdx[labelIdx.length - 1] !== points.length - 1) labelIdx.push(points.length - 1);

  const minGapPx = 34;
  const shownIdx = [];
  labelIdx.forEach((i, idx) => {
    const x = toX(i);
    const isLast = idx === labelIdx.length - 1;
    if (shownIdx.length === 0) { shownIdx.push(i); return; }
    const prevX = toX(shownIdx[shownIdx.length - 1]);
    if (x - prevX < minGapPx) {
      if (isLast) shownIdx.pop(); // ให้จุดสุดท้ายชนะ ตัดอันก่อนหน้าที่ชนกันทิ้ง
      else return;
    }
    shownIdx.push(i);
  });

  shownIdx.forEach(i => {
    const x = toX(i);
    ctx.fillStyle = '#607080';
    ctx.font = '9px sans-serif';
    ctx.textAlign = i === 0 ? 'left' : i === points.length-1 ? 'right' : 'center';
    ctx.fillText(points[i].date.slice(5), x, H - 6); // MM-DD
  });

  // trend arrow (เพิ่ม/ลด) — ลด = ดี (short cover), เพิ่ม = ระวัง
  const first = points[0].val, last = points[points.length-1].val;
  // กัน Infinity%/NaN% ตอน snapshot แรกสุดเป็น 0 หุ้น (เพิ่งเริ่มมี short position) —
  // ไม่มีฐานให้คิดเป็น % เปลี่ยนแปลงได้ โชว์ "n/a" แทน
  const chgPct = first ? ((last - first) / first * 100).toFixed(1) : null;
  const chgCol = last < first ? '#3ab464' : last > first ? '#e05252' : '#8090a0';
  const arrow  = last < first ? '▼' : last > first ? '▲' : '–';
  ctx.font = 'bold 11px sans-serif';
  ctx.fillStyle = chgCol;
  ctx.textAlign = 'right';
  ctx.fillText(chgPct == null ? `${arrow} n/a` : `${arrow} ${Math.abs(parseFloat(chgPct))}%`, W - PAD.right, PAD.top - 3);
}

// ══════════════════════════════════════════════════════════
// INSIDER PAGE
// ══════════════════════════════════════════════════════════
let _insDays   = 30;
let _insFilter = 'all';   // 'all' | 'buy' | 'sell'
let _insSrc    = {r59: true, r246: true};
let _insData   = null;   // {r59:[...], r246:[...]}
let _insReqSeq = 0;      // กัน race: กดปุ่มช่วงเวลารัวๆ (7→90) แล้ว response ช้ากว่ามาทีหลังทับผลใหม่

async function loadInsiderPage() {
  // ต้องเช็คว่ามีรายการจริงด้วย — ถ้ารอบก่อน SEC ล่ม/ยัง sync ไม่เสร็จ endpoint ตอบ
  // 200 {records:[]} ทำให้ _insData = {r59:[],r246:[],...} ซึ่ง truthy แล้ว return
  // ทันทีทุกครั้งที่กลับมาหน้านี้ ไม่ยอม refetch ทั้ง session (pattern เดียวกับ loadDRPage)
  if (_insData && (_insData.r59.length || _insData.r246.length)) {
    renderInsAccumTable();
    renderInsiderSummary();
    renderInsiderTable();
    return;
  }
  document.getElementById('ins-status').textContent = 'กำลังโหลด...';
  await fetchInsiderData();
}

async function fetchInsiderData() {
  const seq = ++_insReqSeq;
  document.getElementById('ins-table-wrap').innerHTML =
    '<div style="padding:20px;color:var(--muted);font-size:13px;text-align:center">กำลังโหลดข้อมูลจาก SEC...</div>';
  try {
    // เว็บมือถือ/ไอแพด (IS_STATIC): endpoint นี้ถูก STATIC_MAP เปลี่ยนเป็นดึงไฟล์ static
    // ล้วนๆ ไม่มี live sync ให้รอ — ถ้าค้างคือเน็ตมือถือหลุด/ช้าจริง ต้อง timeout สั้น
    // ไม่งั้นค้าง "กำลังโหลด" นานถึง 200 วิเหมือนโดนแฮงก์ (ดู feedback ผู้ใช้ที่รอแล้วไม่ขึ้น)
    // เวอร์ชันรันบนเครื่อง (Flask) ยังต้องรอนานได้จริงตอน sync SEC ครั้งแรก (~2-3 นาที)
    const timeoutMs = IS_STATIC ? 20000 : 200000;
    const syncMsg = IS_STATIC
      ? 'หมดเวลารอข้อมูล — เช็คสัญญาณอินเทอร์เน็ตแล้วลองโหลดหน้านี้ใหม่'
      : 'หมดเวลารอข้อมูล — ถ้าเป็นการเปิดหน้านี้ครั้งแรก backend ต้อง sync ข้อมูลจาก SEC ' +
        'ย้อนหลัง 180 วัน (ใช้เวลา ~2-3 นาที) ลองรออีกสักครู่แล้วโหลดหน้านี้ใหม่';
    const [r59res, r246res] = await Promise.all([
      _fetchTimeout(`/api/insider-trades?days=${_insDays}`, timeoutMs, syncMsg).then(r => r.json()),
      _fetchTimeout(`/api/major-changes?days=${_insDays}`, timeoutMs, syncMsg).then(r => r.json()),
    ]);
    // กดปุ่มช่วงเวลาอื่นระหว่างรอ response นี้ -> มี request ใหม่กว่าแล้ว ทิ้งผลนี้ไป
    // ไม่งั้น response ที่ช้ากว่าจะมาเขียนทับ _insData ของ request ที่ผู้ใช้เลือกล่าสุด
    if (seq !== _insReqSeq) return false;
    // เวอร์ชันเว็บ (static) เก็บข้อมูลไว้ที่ 180 วันคงที่ ไม่สนใจ query string
    // days= ที่ส่งไป -> กรองซ้ำฝั่ง client ด้วยวันที่จริง กันปุ่ม 7/30/90 วัน
    // แสดงข้อมูล 180 วันผิดๆ บนเวอร์ชันเว็บ (เดสก์ท็อป/Flask กรองมาแล้วพอดี ไม่กระทบ)
    // ใช้วันที่ตามเขตเวลาเครื่อง (ไม่ใช่ toISOString ที่เป็น UTC) — trade_date จาก SEC
    // เป็นวันที่ไทย ถ้าเทียบกับ UTC date จะคลาดได้ 1 วันช่วงเช้า (บน static viewer
    // client filter นี้เป็นตัวกรองเดียว จึงเห็นผลจริง)
    const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - _insDays);
    const cutoffStr = `${cutoff.getFullYear()}-${String(cutoff.getMonth() + 1).padStart(2, '0')}-${String(cutoff.getDate()).padStart(2, '0')}`;
    const withinDays = x => !x.trade_date || x.trade_date >= cutoffStr;
    _insData = {
      r59:   (r59res.records  || []).filter(withinDays),
      r246:  (r246res.records || []).filter(withinDays),
      fetched_at: r59res.fetched_at || '',
    };
    document.getElementById('ins-status').textContent =
      `อัพเดท ${_insData.fetched_at} · SEC ย้อนหลัง ${_insDays} วัน`;
    buildInsAccum();
    renderInsAccumTable();
    renderInsiderSummary();
    renderInsiderTable();
    // refresh badges in main stocks table only if currently visible
    if (window._currentStockList && document.getElementById('page-stocks')?.classList.contains('active')) {
      renderStocksTable(true);
    }
    return true;
  } catch(e) {
    if (seq !== _insReqSeq) return false;
    document.getElementById('ins-table-wrap').innerHTML =
      `<div style="padding:20px;color:var(--red);font-size:13px">เกิดข้อผิดพลาด: ${e.message}</div>`;
    document.getElementById('ins-status').textContent = '✗ โหลดข้อมูลไม่สำเร็จ';
    return false;
  }
}

// ปุ่ม manual sync บนหน้า Insider — เรียก /api/insider-sync (เดิม endpoint นี้มีอยู่
// แล้วแต่ไม่มีปุ่มเรียกใช้จาก UI เลย ต้องรอ Quick Update ประจำวันเท่านั้นถึงจะ sync)
async function syncInsiderData() {
  const btn = document.getElementById('ins-sync-btn');
  const status = document.getElementById('ins-status');
  btn.disabled = true;
  btn.textContent = '⟳ กำลัง sync...';
  try {
    const r = await _fetchTimeout('/api/insider-sync', 200000, 'หมดเวลารอ sync ข้อมูล SEC', { method: 'POST' }).then(r => r.json());
    if (!r.ok) throw new Error(r.error || 'sync ไม่สำเร็จ');
    _insData = null;
    _insStockCache = null;   // การ์ด insider ใน Tearsheet/popup หุ้นใช้ cache แยก — ล้างด้วย
    // ต่อท้ายผลสรุป sync เฉพาะตอน refetch สำเร็จจริง — ไม่งั้น ins-status จะกลายเป็น
    // "✗ โหลดข้อมูลไม่สำเร็จ · ✓ sync ดึงใหม่..." ที่ขัดกันเอง
    const okRefetch = await fetchInsiderData();
    status.textContent = okRefetch
      ? status.textContent + ` · ✓ sync ดึงใหม่: ผู้บริหาร +${r.insider_fetched} รายการ · ผู้ถือหุ้นใหญ่ +${r.major_fetched} รายการ`
      : `✓ sync สำเร็จ (ผู้บริหาร +${r.insider_fetched} · ผู้ถือหุ้นใหญ่ +${r.major_fetched}) — แต่โหลดข้อมูลใหม่ไม่สำเร็จ ลองโหลดหน้านี้ใหม่`;
  } catch (e) {
    status.textContent = '✗ sync ไม่สำเร็จ: ' + e.message;
  } finally {
    btn.disabled = false;
    btn.textContent = '⟳ Sync ข้อมูล SEC';
  }
}

function setInsDays(d, btn) {
  _insDays = d; _insData = null;
  document.querySelectorAll('[id^="ins-days-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  fetchInsiderData();
}

function setInsFilter(f, btn) {
  _insFilter = f;
  document.querySelectorAll('[id^="ins-filter-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderInsiderTable();
}

function setInsSrc(s, btn) {
  const other = s === 'r59' ? 'r246' : 'r59';
  if (_insSrc[s] && !_insSrc[other]) return; // ต้องมีอย่างน้อย 1 แหล่งข้อมูล
  _insSrc[s] = !_insSrc[s];
  btn.classList.toggle('active', _insSrc[s]);
  // เดิม re-render แค่ตารางล่าง — กล่องสรุป 4 ใบกับกล่องสะสมยังโชว์ตัวเลขของ
  // แหล่งที่ถูกปิดอยู่ ทำให้บน-ล่างขัดกัน ต้อง re-render ทุก section พร้อมกัน
  renderInsiderSummary();
  renderInsAccumTable();
  renderInsiderTable();
}

function renderInsiderSummary() {
  if (!_insData) return;
  const r59  = _insData.r59;
  const r246 = _insData.r246;

  const r59buy  = r59.filter(x => x.action === 'buy');
  const r59sell = r59.filter(x => x.action === 'sell');
  const r246buy  = r246.filter(x => x.action === 'buy');
  const r246sell = r246.filter(x => x.action === 'sell');

  const totBuyQty = r59buy.reduce((s,x) => s + (x.qty||0), 0);
  const totSellQty = r59sell.reduce((s,x) => s + (x.qty||0), 0);
  const uniqBuyStocks  = new Set(r59buy.map(x=>x.symbol)).size;
  const uniqSellStocks = new Set(r59sell.map(x=>x.symbol)).size;

  // โชว์การ์ดเฉพาะแหล่งข้อมูลที่เปิดอยู่ — ให้สอดคล้องกับตารางล่างที่กรองตาม _insSrc
  const cards = [
    ..._insSrc.r59 ? [
      { label:'ผู้บริหารซื้อ', value: r59buy.length + ' รายการ', sub: `${uniqBuyStocks} หุ้น · ${(totBuyQty/1e6).toFixed(1)}M หุ้น`, color:'#3ab464' },
      { label:'ผู้บริหารขาย', value: r59sell.length + ' รายการ', sub: `${uniqSellStocks} หุ้น`, color:'#dc503c' },
    ] : [],
    ..._insSrc.r246 ? [
      { label:'ผู้ถือหุ้นใหญ่เพิ่ม', value: r246buy.length + ' รายการ', sub: r246buy.map(x=>x.symbol).join(', ').slice(0,40)||'-', color:'#3ab464' },
      { label:'ผู้ถือหุ้นใหญ่ลด', value: r246sell.length + ' รายการ', sub: r246sell.map(x=>x.symbol).join(', ').slice(0,40)||'-', color:'#dc503c' },
    ] : [],
  ];
  document.getElementById('ins-summary').innerHTML = cards.map(c => `
    <div class="card" style="padding:12px 16px;min-width:160px;flex:1">
      <div style="font-size:11px;color:var(--muted);margin-bottom:4px">${c.label}</div>
      <div style="font-size:18px;font-weight:700;color:${c.color}">${c.value}</div>
      <div style="font-size:10px;color:var(--muted);margin-top:2px">${c.sub}</div>
    </div>`).join('');
}

// ผู้ใช้คลิกหัวคอลัมน์เพื่อจัดเรียงเอง — null = default (วันที่ desc)
let _insiderSort = null;   // { key, dir: 1=มาก→น้อย, -1=น้อย→มาก }
const _INSIDER_SORT_GETTERS = {
  trade_date: r => r.trade_date || '',
  symbol: r => r.symbol || '',
  src: r => r.src || '',
  who: r => r.src === 'r59' ? (r.name||'') : (r.holder||''),
  action: r => r.action || '',
  detail: r => r.src === 'r59' ? (r.qty ?? -Infinity) : (r.pct_change ?? -Infinity),
  price: r => r.src === 'r59' && r.price != null ? r.price : -Infinity,
};
const _INSIDER_SORT_STR = new Set(['trade_date','symbol','src','who','action']);
function insiderSortBy(key) {
  if (_insiderSort && _insiderSort.key === key) _insiderSort.dir *= -1;
  else _insiderSort = { key, dir: 1 };
  renderInsiderTable();
}
function _insiderSortArrow(key) {
  if (!_insiderSort || _insiderSort.key !== key) return '';
  return _insiderSort.dir === 1 ? ' ▼' : ' ▲';
}

// escape ก่อนใส่ innerHTML — ชื่อผู้บริหาร/ผู้ถือหุ้นใหญ่ (row.name/row.holder) มาจาก SEC
// scraping ดิบๆ (pandas.read_html อ่าน text content ของ <td> มา) ไม่ผ่าน sanitize เลย
// ถ้าหลุดอักขระ <, >, " มาในชื่อ จะทำให้ตาราง/popup insider ทั้งก้อนเพี้ยน (เหมือนปัญหา
// ที่หน้า Hedge Holdings เจอมาก่อนจนต้องมี _hedgeEsc — หน้า Insider ไม่เคยมีมาก่อน)
// ใช้ตัว escape กลาง (_escHtml — จัดการ ' ด้วย) ไม่ทำสำเนา regex ที่ 4 ในไฟล์
function _insEsc(s) { return _escHtml(s); }

function renderInsiderTable() {
  if (!_insData) return;
  const q = (document.getElementById('ins-search')?.value || '').toUpperCase();

  // merge r59 + r246 into unified rows
  let rows = [];

  if (_insSrc.r59) {
    _insData.r59.forEach(x => {
      if (_insFilter !== 'all' && x.action !== _insFilter) return;
      // (x.name || '') กัน crash ทั้งตาราง — บางรายการจาก SEC ไม่มีชื่อผู้บริหารครบ
      if (q && !x.symbol.includes(q) && !(x.name || '').includes(q)) return;
      rows.push({ ...x, src: 'r59' });
    });
  }
  if (_insSrc.r246) {
    _insData.r246.forEach(x => {
      if (_insFilter !== 'all' && x.action !== _insFilter) return;
      // ค้นชื่อผู้ถือหุ้นใหญ่ (holder) ด้วย — เดิมค้นได้แค่ symbol ทั้งที่ตาราง
      // แสดงชื่อผู้ถือหุ้นใหญ่ในคอลัมน์เดียวกับฝั่ง r59
      if (q && !x.symbol.includes(q) && !(x.holder || '').includes(q)) return;
      rows.push({ ...x, src: 'r246' });
    });
  }

  // sort by date desc (default) — หรือคอลัมน์ที่ผู้ใช้คลิกเลือก
  if (_insiderSort && _INSIDER_SORT_GETTERS[_insiderSort.key]) {
    const get = _INSIDER_SORT_GETTERS[_insiderSort.key];
    const dir = _insiderSort.dir;
    const isStr = _INSIDER_SORT_STR.has(_insiderSort.key);
    rows.sort((a, b) => {
      const va = get(a), vb = get(b);
      if (isStr) return dir === 1 ? String(vb).localeCompare(String(va)) : String(va).localeCompare(String(vb));
      // เทียบแบบไม่พึ่งการลบ — va-vb เป็น NaN เมื่อทั้งคู่เป็น -Infinity (r246 ที่ pct_change
      // ว่าง) ทำให้ลำดับของกลุ่มนั้นสุ่มไม่แน่นอน
      const d = va === vb ? 0 : (va < vb ? -1 : 1);
      return dir === 1 ? -d : d;
    });
  } else {
    rows.sort((a,b) => (b.trade_date||'').localeCompare(a.trade_date||''));
  }

  if (!rows.length) {
    document.getElementById('ins-table-wrap').innerHTML =
      '<div style="padding:20px;color:var(--muted);font-size:13px;text-align:center">ไม่พบรายการ</div>';
    return;
  }

  const actColor = a => a==='buy' ? '#3ab464' : a==='sell' ? '#dc503c' : '#8090a0';
  const actLabel = a => a==='buy' ? '🟢 ซื้อ' : a==='sell' ? '🔴 ขาย' : '— อื่นๆ';

  document.getElementById('ins-table-wrap').innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:12px">
      <thead>
        <tr style="background:var(--bg-card2);position:sticky;top:0;z-index:1">
          <th style="padding:8px 10px;text-align:left;color:var(--muted);font-weight:600;cursor:pointer" onclick="insiderSortBy('trade_date')">วันที่${_insiderSortArrow('trade_date')}</th>
          <th style="padding:8px 10px;text-align:left;color:var(--muted);cursor:pointer" onclick="insiderSortBy('symbol')">หุ้น${_insiderSortArrow('symbol')}</th>
          <th style="padding:8px 10px;text-align:left;color:var(--muted);cursor:pointer" onclick="insiderSortBy('src')">ประเภท${_insiderSortArrow('src')}</th>
          <th style="padding:8px 10px;text-align:left;color:var(--muted);cursor:pointer" onclick="insiderSortBy('who')">ชื่อ${_insiderSortArrow('who')}</th>
          <th style="padding:8px 10px;text-align:right;color:var(--muted);cursor:pointer" onclick="insiderSortBy('action')">ซื้อ/ขาย${_insiderSortArrow('action')}</th>
          <th style="padding:8px 10px;text-align:right;color:var(--muted);cursor:pointer" onclick="insiderSortBy('detail')">จำนวน / %${_insiderSortArrow('detail')}</th>
          <th style="padding:8px 10px;text-align:right;color:var(--muted);cursor:pointer" onclick="insiderSortBy('price')">ราคา${_insiderSortArrow('price')}</th>
        </tr>
      </thead>
      <tbody>
        ${rows.map(row => {
          const isR59  = row.src === 'r59';
          // pct_before/pct_after อาจเป็น null (SEC ไม่ได้กรอกช่อง "ก่อน") ทั้งที่ pct_change มี
          // -> โชว์วงเล็บช่วง before→after เฉพาะตอนมีครบทั้งคู่ ไม่งั้นได้สตริง "undefined"
          const detail = isR59
            ? `${(row.qty||0).toLocaleString()} หุ้น`
            : row.pct_change != null
              ? `${row.pct_change.toFixed(2)}%` + (row.pct_before != null && row.pct_after != null
                  ? ` (${row.pct_before.toFixed(2)}→${row.pct_after.toFixed(2)}%)` : '')
              : '—';
          const price = isR59 && row.price ? `฿${row.price.toFixed(2)}` : '—';
          const srcBadge = isR59
            ? '<span style="font-size:9px;background:#1a3060;color:#5ab4ff;border-radius:3px;padding:1px 4px">ผู้บริหาร</span>'
            : '<span style="font-size:9px;background:#2a1a40;color:#c06bff;border-radius:3px;padding:1px 4px">ผู้ถือหุ้นใหญ่</span>';
          const who = _insEsc(isR59 ? (row.name||'') : (row.holder||''));
          return `<tr style="border-bottom:1px solid rgba(255,255,255,0.04);cursor:pointer"
                      onclick="openChartModal('${_escJsAttr(row.symbol)}')"
                      onmouseover="this.style.background='rgba(255,255,255,0.03)'"
                      onmouseout="this.style.background=''">
            <td style="padding:7px 10px;color:var(--muted)">${_insEsc(row.trade_date||'—')}</td>
            <td style="padding:7px 10px">
              <strong style="color:#5ab4ff">${_insEsc(row.symbol)}</strong>${tvLink(row.symbol)}
            </td>
            <td style="padding:7px 10px">${srcBadge}</td>
            <td style="padding:7px 10px;color:#c8d0dc;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"
                title="${who}">${who}</td>
            <td style="padding:7px 10px;text-align:right;color:${actColor(row.action)};font-weight:600">${actLabel(row.action)}</td>
            <td style="padding:7px 10px;text-align:right;color:#c8d0dc">${detail}</td>
            <td style="padding:7px 10px;text-align:right;color:#c8d0dc">${price}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
    <div style="padding:8px 12px;color:var(--muted);font-size:10px;border-top:1px solid var(--border)">
      แหล่งข้อมูล: SEC Thailand (r59 + r246) · ${rows.length} รายการ
    </div>`;
}

// ── Section ใน stock popup ──────────────────────────────────
async function loadInsiderForStock(symbol) {
  const el = document.getElementById('popup-insider-section');
  if (!el) return;
  el.innerHTML = '<div style="color:var(--muted);font-size:11px;padding:4px 0">กำลังโหลด insider...</div>';

  try {
    const data = await _loadInsiderStockData();
    const sym = symbol.toUpperCase();
    const r59  = data.r59.filter(x => x.symbol === sym);
    const r246 = data.r246.filter(x => x.symbol === sym);
    const all  = [...r59.map(x=>({...x,src:'r59'})), ...r246.map(x=>({...x,src:'r246'}))]
                   .sort((a,b) => (b.trade_date||'').localeCompare(a.trade_date||''));

    if (!all.length) {
      el.innerHTML = '<div style="color:var(--muted);font-size:11px;padding:4px 0">ไม่มีรายการ insider 180 วัน</div>';
      return;
    }

    const actColor = a => a==='buy' ? '#3ab464' : a==='sell' ? '#dc503c' : '#8090a0';
    el.innerHTML = `
      <div style="font-size:11px;font-weight:600;color:#c8d0dc;margin-bottom:6px">
        Insider Activity 180 วัน (${all.length} รายการ)
      </div>
      ${all.map(row => {
        const isR59 = row.src === 'r59';
        const detail = isR59
          ? `${(row.qty||0).toLocaleString()} หุ้น${row.price ? ' @ ฿'+row.price.toFixed(2) : ''}`
          : row.pct_change != null
            ? `${row.pct_change.toFixed(2)}%` + (row.pct_before != null && row.pct_after != null
                ? ` (${row.pct_before.toFixed(2)}%→${row.pct_after.toFixed(2)}%)` : '')
            : '';
        const who = _insEsc(isR59 ? (row.name||'') : (row.holder||''));
        const badge = isR59
          ? '<span style="font-size:9px;background:#1a3060;color:#5ab4ff;border-radius:3px;padding:1px 4px">บริหาร</span>'
          : '<span style="font-size:9px;background:#2a1a40;color:#c06bff;border-radius:3px;padding:1px 4px">ถือหุ้นใหญ่</span>';
        return `<div style="display:flex;align-items:center;gap:8px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
          <span style="color:var(--muted);font-size:10px;min-width:75px">${row.trade_date||'—'}</span>
          ${badge}
          <span style="color:${actColor(row.action)};font-weight:600;font-size:11px">${row.action==='buy'?'ซื้อ':row.action==='sell'?'ขาย':'อื่น'}</span>
          <span style="color:#c8d0dc;font-size:11px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${who}">${who}</span>
          <span style="color:var(--muted);font-size:10px;white-space:nowrap">${detail}</span>
        </div>`;
      }).join('')}`;
  } catch(e) {
    el.innerHTML = `<div style="color:var(--muted);font-size:11px">ไม่สามารถโหลด insider: ${e.message}</div>`;
  }
}

// โหลด background data — อยู่ใน block เดียวกับที่ define functions เหล่านี้
loadShortData().then(() => { if (window._reRenderStockBadges) window._reRenderStockBadges(); });
loadNvdrData().then(()  => { if (window._reRenderStockBadges) window._reRenderStockBadges(); });


/* ═════════ inline block boundary ═════════ */


/* ============================================================
   WATCHLIST ALERT MODAL
   ============================================================ */
let _wlAlertSym = null;

function openWlAlertModal(sym) {
  _wlAlertSym = sym;
  const { isDR, isUS, isHK, under } = _alertSymMeta(sym);
  const label = isDR ? `DR: ${under} (USD)` : isUS ? `US: ${under} (USD)` : isHK ? `HK: ${under} (HKD)` : sym;
  document.getElementById("wl-alert-modal-title").textContent = `🔔 แจ้งเตือนราคา — ${label}`;
  const priceLabel = _currentPriceLabel(sym);
  document.getElementById("wl-al-price").placeholder = priceLabel || "0.00";
  document.getElementById("wl-al-price").value = "";
  document.getElementById("wl-al-cond").value = "below";
  document.getElementById("wl-al-note").value = "";
  _renderWlExistingAlerts(sym);
  document.getElementById("wl-alert-modal").classList.add("open");
  document.getElementById("wl-al-price").focus();
}

function closeWlAlertModal() {
  document.getElementById("wl-alert-modal").classList.remove("open");
  _wlAlertSym = null;
}

function saveWlAlert() {
  if (!_wlAlertSym) return;
  const cond = document.getElementById("wl-al-cond").value;
  const price = parseFloat(document.getElementById("wl-al-price").value);
  const note = document.getElementById("wl-al-note").value.trim();
  // Number.isFinite กัน Infinity (เช่นพิมพ์ "1e400") ที่ !price||price<=0 หลุดผ่านไม่ทัน —
  // Infinity ผ่าน JSON.stringify กลายเป็น null แล้วโดน _valid_price_alert ฝั่ง server reject
  // ทั้ง array ทำให้ alert อื่นที่ถูกต้องอยู่แล้วใน batch เดียวกัน sync ข้ามเครื่องไม่ขึ้นไปด้วย
  if (!Number.isFinite(price) || price <= 0) { document.getElementById("wl-al-price").focus(); return; }

  const alerts = _loadAlerts();
  alerts.unshift({
    id: Date.now().toString(),
    symbol: _wlAlertSym,
    condition: cond,
    targetPrice: price,
    note: note || "",
    createdAt: new Date().toISOString(),
    triggered: false,
    triggeredAt: null,
    triggeredPrice: null,
  });
  _saveAlerts(alerts);
  _updateBellBadge();
  _renderWlExistingAlerts(_wlAlertSym);
  document.getElementById("wl-al-price").value = "";
  document.getElementById("wl-al-note").value = "";
  renderWatchlist();
}

function deleteWlAlert(id) {
  _saveAlerts(_loadAlerts().filter(a => a.id !== id));
  _updateBellBadge();
  if (_wlAlertSym) _renderWlExistingAlerts(_wlAlertSym);
  renderWatchlist();
}

function _renderWlExistingAlerts(sym) {
  const alerts = _loadAlerts().filter(a => a.symbol === sym);
  const sec = document.getElementById("wl-alert-existing");
  const list = document.getElementById("wl-alert-existing-list");
  if (alerts.length === 0) { sec.style.display = "none"; return; }
  sec.style.display = "";
  list.innerHTML = alerts.map(a => {
    const condTh = a.condition === "above" ? "≥" : "≤";
    const statusBadge = a.triggered
      ? `<span style="color:var(--yellow);font-size:10px">✓ triggered @ ${a.triggeredPrice?.toFixed(2)??""}</span>`
      : `<span style="color:var(--green);font-size:10px">● active</span>`;
    return `<div class="wl-alert-ex-item">
      <div style="flex:1">
        <span style="font-weight:600">ราคา ${condTh} ${_fmtAlertPrice(a.targetPrice)} บาท</span>
        ${a.note ? `<span style="color:var(--text2)"> · ${a.note}</span>` : ""}
        <br>${statusBadge}
      </div>
      <button class="wl-alert-ex-del" onclick="deleteWlAlert('${a.id}')">×</button>
    </div>`;
  }).join("");
}

/* ============================================================
   PRICE ALERT SYSTEM
   - localStorage key: "set_price_alerts"
   - alert obj: { id, symbol, condition:'above'|'below', targetPrice, note, createdAt, triggered, triggeredAt, triggeredPrice }
   ============================================================ */

const ALERT_STORAGE_KEY = "set_price_alerts";
let _alertPanelOpen = false;
let _alertCheckTimer = null;

function _loadAlerts() {
  try { return JSON.parse(localStorage.getItem(ALERT_STORAGE_KEY) || "[]"); }
  catch { return []; }
}
// targetPrice ควรเป็นตัวเลขเสมอ แต่ record เก่า/sync ข้ามเครื่องอาจเพี้ยนได้ (undefined/string) —
// ใช้ตัวนี้แทน a.targetPrice.toFixed() ตรงๆ ทุกจุด กัน exception ทำให้ panel/popup ทั้งก้อนพัง
function _fmtAlertPrice(v, dp = 2) {
  const n = Number(v);
  return Number.isFinite(n) ? n.toFixed(dp) : "?";
}
function _saveAlerts(arr) {
  localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(arr));
  _alertsPush(arr);
}
// Watchlist legacy-migrate (bare symbol → prefixed เช่น "AAPL"→"DR:AAPL") เปลี่ยน key ใน
// watchlist array แต่ alert เดิมยังผูกกับ symbol เก่า — ไม่ rename ตาม alert จะมองไม่เห็น/
// จัดการไม่ได้จาก _wlAlertCell(newSym) อีกเลย (a.symbol==='AAPL' ไม่ตรง 'DR:AAPL')
function _alertsRenameSymbol(oldSym, newSym) {
  const alerts = _loadAlerts();
  let changed = false;
  alerts.forEach(a => { if (a.symbol === oldSym) { a.symbol = newSym; changed = true; } });
  if (changed) _saveAlerts(alerts);
}

// ============================================================
// PRICE ALERT SYNC ข้ามเครื่อง — เก็บเป็นไฟล์ data/price_alerts.json ให้ git push/pull
// พาไปเครื่องอื่นได้เหมือน watchlist (ดู /api/price-alerts ใน app.py) merge แบบ union ด้วย
// "id" เท่านั้น ไม่มีการลบข้ามเครื่องอัตโนมัติ (เหมือน watchlist — ดู _wlSyncFromServer)
// ยกเว้นสถานะ triggered ที่ทำเป็น ratchet ทางเดียว (ใครทริกก่อนถือว่าทริกแล้วทุกเครื่อง)
// กันเด้ง popup ซ้ำตอน sync กลับมาหาเครื่องที่ยังไม่เห็นว่าทริกไปแล้ว
// ============================================================

// union เข้า `local` (แก้ในที่) ด้วยรายการจาก `serverList`: alert ใหม่ push เข้า, alert ที่
// serverList บอกว่า triggered แล้วแต่ local ยังไม่เห็น จะ ratchet ไปข้างหน้าทางเดียว — ใช้ร่วมกัน
// ทั้งตอน sync ตอนโหลดหน้า (_alertsSyncFromServer) และก่อน POST ทุกครั้ง (_alertsPush) กันเคส
// เครื่อง B save alert ของตัวเองทับไฟล์ด้วย local array เก่าที่ยังไม่เห็นว่าเครื่อง A ทริกไปแล้ว
// (ย้อน triggered กลับเป็น false ทำให้ popup เด้งซ้ำ — พบจากรีวิวโค้ด 2026-08-24)
function _mergeAlertRatchet(local, serverList) {
  const byId = new Map(local.map(a => [a.id, a]));
  let changed = false;
  serverList.forEach(remote => {
    if (!remote || typeof remote.id !== 'string') return;
    const cur = byId.get(remote.id);
    if (!cur) { local.push(remote); byId.set(remote.id, remote); changed = true; return; }
    if (remote.triggered && !cur.triggered) {
      cur.triggered = true;
      cur.triggeredAt = remote.triggeredAt;
      cur.triggeredPrice = remote.triggeredPrice;
      changed = true;
    }
  });
  return changed;
}

function _alertsPush(arr) {
  fetch('/api/price-alerts').then(r => r.ok ? r.json() : Promise.reject())
    .then(serverList => {
      if (Array.isArray(serverList) && _mergeAlertRatchet(arr, serverList)) {
        localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(arr));
        _updateBellBadge();
        if (_alertPanelOpen) renderAlertPanel();
      }
    })
    .catch(() => {})
    .then(() => _alertsPost(arr));
}

function _alertsPost(arr) {
  fetch('/api/price-alerts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ alerts: arr }),
  }).then(r => {
    const note = document.getElementById('al-sync-note');
    if (!note) return;
    if (r.ok) { note.textContent = ''; return; }
    // เกิน 500 ตัว (limit ฝั่ง backend — ดู save_price_alerts ใน app.py) หรือ payload ผิดรูป —
    // localStorage เครื่องนี้ยังบันทึกได้ปกติ แต่ sync ข้ามเครื่องหยุดทำงานเงียบๆ ถ้าไม่แจ้ง
    // (เดิม .catch() เช็คแค่ network fail ไม่เช็ค r.ok เลย ตอบ 400 ก็เงียบเหมือนสำเร็จ —
    // พบจาก code review 2026-08-10 เหมือน _wlSave ที่เคยแก้ปัญหานี้ไปแล้ว)
    note.textContent = arr.length > 500
      ? `⚠ แจ้งเตือนเกิน 500 รายการ (มี ${arr.length}) — เกินลิมิต sync ข้ามเครื่อง บันทึกได้แค่ในเครื่องนี้`
      : '⚠ บันทึกแจ้งเตือนไปเซิร์ฟเวอร์ไม่สำเร็จ — sync ข้ามเครื่องอาจไม่ทำงาน';
  }).catch(() => {
    const note = document.getElementById('al-sync-note');
    if (note) note.textContent = '⚠ ติดต่อเซิร์ฟเวอร์ไม่ได้ — บันทึกแจ้งเตือนได้แค่ในเครื่องนี้ (localStorage)';
  });
}

(function _alertsSyncFromServer() {
  fetch('/api/price-alerts').then(r => r.ok ? r.json() : Promise.reject()).then(serverList => {
    if (!Array.isArray(serverList)) return;
    const local = _loadAlerts();
    const changed = _mergeAlertRatchet(local, serverList);
    if (changed) {
      localStorage.setItem(ALERT_STORAGE_KEY, JSON.stringify(local));
      _updateBellBadge();
      if (_alertPanelOpen) renderAlertPanel();
    }
    // เผื่อเครื่องนี้มี alert ใหม่ที่อีกเครื่องยังไม่มี ก็ sync กลับขึ้นไฟล์ด้วย
    if (local.length && (changed || local.length !== serverList.length)) _alertsPost(local);
  }).catch(() => {});
})();

function toggleAlertPanel() {
  _alertPanelOpen = !_alertPanelOpen;
  document.getElementById("alert-panel").classList.toggle("open", _alertPanelOpen);
  if (_alertPanelOpen) {
    _populateAlertSymList();
    renderAlertPanel();
  }
}

function _populateAlertSymList() {
  const dl = document.getElementById("al-sym-list");
  if (!dl) return;
  const setSyms = (DATA?.stocks || []).map(s => s.symbol).filter(Boolean).sort();
  const drSyms  = (_drData || []).map(s => "DR:" + s.sym).sort();
  const usSyms  = (_usData?.stocks || []).map(s => "US:" + s.symbol).sort();
  const hkSyms  = (_hkData?.stocks || []).map(s => "HK:" + s.symbol).sort();
  // rebuild เสมอ เพราะ SET/DR/US/HK โหลดคนละเวลา
  dl.innerHTML = [...setSyms, ...drSyms, ...usSyms, ...hkSyms].map(s => `<option value="${s}">`).join("");
}

function _isDRSym(sym) { return sym.startsWith("DR:"); }
function _isUsSym(sym) { return sym.startsWith("US:"); }
function _isHkSym(sym) { return sym.startsWith("HK:"); }

// ตลาด/สกุลเงิน/label/ทศนิยม ของ alert symbol (prefix DR:/US:/HK: หรือ SET เปล่า) — จุดเดียว
// ที่ map ข้อมูลนี้ ใช้ร่วมกันทุกจุดที่ต้องโชว์ currency/label ของ alert (เดิมกระจาย logic
// เดียวกันแยกกัน 5 จุด: openWlAlertModal/_currentPriceLabel/renderAlertPanel/
// _showNextAlertPopup/_showBrowserNotification — พบจากรีวิวโค้ด 2026-09-02)
function _alertSymMeta(sym) {
  const isDR = _isDRSym(sym), isUS = _isUsSym(sym), isHK = _isHkSym(sym);
  const under = _wlBaseSym(sym);
  const curr = isHK ? "HKD" : (isDR || isUS) ? "USD" : "บาท";
  const label = isDR ? `DR: ${under}` : isUS ? `US: ${under}` : isHK ? `HK: ${under}` : sym;
  return { isDR, isUS, isHK, under, curr, label, dp: isDR ? 4 : 2 };
}

function _currentPriceLabel(sym) {
  const { isDR, isUS, isHK, under } = _alertSymMeta(sym);
  if (isDR) {
    const dr = (_drData || []).find(x => x.sym === under);
    const curr = dr?.region === "TH" ? "THB" : (under.includes(".") ? "" : "USD");
    return dr ? `ราคาปัจจุบัน: ${dr.price?.toFixed(2)} ${curr}` : null;
  }
  if (isUS) {
    const u = (_usData?.stocks || []).find(x => x.symbol === under);
    return u ? `ราคาปัจจุบัน: ${u.price?.toFixed(2)} USD` : null;
  }
  if (isHK) {
    const h = (_hkData?.stocks || []).find(x => x.symbol === under);
    return h ? `ราคาปัจจุบัน: ${h.price?.toFixed(2)} HKD` : null;
  }
  const s = DATA?.stocks?.find(x => x.symbol === sym);
  return s ? `ราคาปัจจุบัน: ${s.price?.toFixed(2)} บาท` : null;
}

function addAlert() {
  let sym = document.getElementById("al-sym").value.trim().toUpperCase();
  const cond = document.getElementById("al-cond").value;
  const price = parseFloat(document.getElementById("al-price").value);
  const note = document.getElementById("al-note").value.trim();

  if (!sym) { alert("กรุณากรอกชื่อหุ้น"); return; }
  if (!price || price <= 0) { alert("กรุณากรอกราคาเป้าหมาย"); return; }

  // auto-detect DR/US/HK เหมือน Watchlist (addToWatchlist) — เดิมมีแค่ DR ทำให้พิมพ์ symbol
  // US/HK เปล่าๆ (เช่น "ZS") ไม่ถูกเติม prefix ให้เลยทั้งที่ comment ข้างบนอ้างว่าทำเหมือนกัน
  // (พบจากรีวิวโค้ด 2026-09-02)
  if (!sym.startsWith("DR:") && !sym.startsWith("US:") && !sym.startsWith("HK:")) {
    const matchesSET = (DATA?.stocks || []).some(s => s.symbol === sym);
    const matchesDR  = (_drData || []).some(s => s.sym === sym);
    const matchesUS  = (_usData?.stocks || []).some(s => s.symbol === sym);
    const matchesHK  = (_hkData?.stocks || []).some(s => s.symbol === sym);
    if (!matchesSET && matchesDR) sym = "DR:" + sym;
    else if (!matchesSET && !matchesDR && matchesUS) sym = "US:" + sym;
    else if (!matchesSET && !matchesDR && !matchesUS && matchesHK) sym = "HK:" + sym;
  }

  const alerts = _loadAlerts();
  alerts.unshift({
    id: Date.now().toString(),
    symbol: sym,
    condition: cond,
    targetPrice: price,
    note: note || "",
    createdAt: new Date().toISOString(),
    triggered: false,
    triggeredAt: null,
    triggeredPrice: null,
  });
  _saveAlerts(alerts);

  document.getElementById("al-sym").value = "";
  document.getElementById("al-price").value = "";
  document.getElementById("al-note").value = "";
  renderAlertPanel();
  _updateBellBadge();
}

function deleteAlert(id) {
  _saveAlerts(_loadAlerts().filter(a => a.id !== id));
  renderAlertPanel();
  _updateBellBadge();
}

function clearTriggeredAlerts() {
  _saveAlerts(_loadAlerts().filter(a => !a.triggered));
  renderAlertPanel();
  _updateBellBadge();
}

function renderAlertPanel() {
  const alerts = _loadAlerts();
  const active = alerts.filter(a => !a.triggered);
  const triggered = alerts.filter(a => a.triggered);

  // แสดงสกุลเงิน/label ให้ตรงตลาด — DR/US = USD, HK = HKD, ที่เหลือ (SET) = บาท
  // (ใช้ _alertSymMeta กลางตัวเดียวกับ openWlAlertModal/_showNextAlertPopup/_showBrowserNotification)
  //
  // label/note/id ต้อง escape ก่อนแทรก — backend (_valid_price_alert) เช็คแค่ type ไม่กรอง
  // ตัวอักษร ถ้ามาจาก sync ข้ามเครื่อง/แก้ไฟล์มือ/POST ตรงๆ อาจมี HTML/quote ปนมาได้ (เหมือน
  // เหตุผลที่ _wlAlertCell ใช้ _escHtml/_escJsAttr กับ sym อยู่แล้ว — พบจากรีวิวโค้ด 2026-09-02)
  const activeEl = document.getElementById("al-active-list");
  activeEl.innerHTML = active.length === 0
    ? `<div class="alert-empty">ยังไม่มีแจ้งเตือน — เพิ่มได้ด้านบน</div>`
    : active.map(a => {
        const condTh = a.condition === "above" ? "≥" : "≤";
        const { curr, label, dp } = _alertSymMeta(a.symbol);
        return `<div class="alert-item">
          <div class="alert-item-body">
            <div class="alert-sym">${_escHtml(label)}</div>
            <div class="alert-cond">ราคา ${condTh} <strong>${_fmtAlertPrice(a.targetPrice, dp)}</strong> ${curr}</div>
            ${a.note ? `<div class="alert-note">${_escHtml(a.note)}</div>` : ""}
          </div>
          <button class="alert-del-btn" onclick="deleteAlert('${_escJsAttr(a.id)}')" title="ลบ">×</button>
        </div>`;
      }).join("");

  const triggeredSec = document.getElementById("al-triggered-section");
  const triggeredEl = document.getElementById("al-triggered-list");
  triggeredSec.style.display = triggered.length > 0 ? "" : "none";
  triggeredEl.innerHTML = triggered.map(a => {
    const condTh = a.condition === "above" ? "≥" : "≤";
    const when = a.triggeredAt ? new Date(a.triggeredAt).toLocaleString("th-TH", { hour12: false }) : "";
    const { curr, label, dp } = _alertSymMeta(a.symbol);
    return `<div class="alert-item triggered">
      <div class="alert-item-body">
        <div class="alert-sym">${_escHtml(label)} <span style="font-size:10px;color:var(--yellow)">✓ triggered</span></div>
        <div class="alert-cond">ราคา ${condTh} ${_fmtAlertPrice(a.targetPrice, dp)} → ราคาจริง <strong>${a.triggeredPrice?.toFixed(dp) ?? "—"}</strong> ${curr}</div>
        ${when ? `<div class="alert-note">${when}</div>` : ""}
        ${a.note ? `<div class="alert-note">${_escHtml(a.note)}</div>` : ""}
      </div>
      <button class="alert-del-btn" onclick="deleteAlert('${_escJsAttr(a.id)}')" title="ลบ">×</button>
    </div>`;
  }).join("") + (triggered.length > 0 ? `<div style="padding:0 12px 12px"><button onclick="clearTriggeredAlerts()" style="width:100%;padding:5px;background:transparent;border:1px solid var(--border);border-radius:5px;color:var(--text2);cursor:pointer;font-size:11px">ล้างทั้งหมด</button></div>` : "");
}

function _updateBellBadge() {
  const alerts = _loadAlerts();
  const activeCount = alerts.filter(a => !a.triggered).length;
  const badge = document.getElementById("alert-badge");
  if (activeCount > 0) {
    badge.textContent = activeCount > 9 ? "9+" : activeCount;
    badge.style.display = "block";
  } else {
    badge.style.display = "none";
  }
}

/* ---------- PRICE CHECK ---------- */
// เทียบ alert ที่ยังไม่ triggered กับ price map {symbol: price} ที่ส่งมา — แยกออกจาก checkAlerts()
// ให้เรียกซ้ำได้จากแหล่งราคาอื่น เช่น wlRefreshLivePrices() (ปุ่ม "⚡ ราคาล่าสุด" ในหน้า Watchlist)
// ที่มีราคาสดกว่า /api/prices (เป็นราคาปิด/แคชแบบ batch รีเช็คทุก 5 นาที) คืนจำนวน alert ที่เพิ่ง trigger
function _applyAlertPrices(prices) {
  const alerts = _loadAlerts();
  let changed = 0;
  const now = new Date().toISOString();

  for (const a of alerts) {
    if (a.triggered) continue;
    const price = prices[a.symbol];
    if (price == null) continue;
    const hit = (a.condition === "above" && price >= a.targetPrice)
             || (a.condition === "below" && price <= a.targetPrice);
    if (hit) {
      a.triggered = true;
      a.triggeredAt = now;
      a.triggeredPrice = price;
      changed++;
      _showAlertToast(a, price);
      _showBrowserNotification(a, price);
    }
  }

  if (changed) {
    _saveAlerts(alerts);
    _updateBellBadge();
    if (_alertPanelOpen) renderAlertPanel();
  }
  return changed;
}

async function checkAlerts() {
  const alerts = _loadAlerts();
  const active = alerts.filter(a => !a.triggered);
  if (active.length === 0) return;

  try {
    const r = await fetch("/api/prices?t=" + Date.now());
    const d = await r.json();
    if (d.error) return;
    _applyAlertPrices(d.prices);   // { symbol: price }

    const checkEl = document.getElementById("al-last-check");
    if (checkEl) {
      const t = new Date().toLocaleTimeString("th-TH", { hour12: false });
      checkEl.textContent = `เช็คล่าสุด: ${t}`;
    }
  } catch(e) {
    console.warn("alert check failed:", e);
  }
}

let _alertPopupQueue = [];
let _alertPopupShowing = false;

function _showAlertToast(alert, price) {
  _alertPopupQueue.push({ type: "price", alert, price });
  if (!_alertPopupShowing) _showNextAlertPopup();
}

function _showNextAlertPopup() {
  if (_alertPopupQueue.length === 0) { _alertPopupShowing = false; return; }
  _alertPopupShowing = true;
  const item = _alertPopupQueue[0];
  const box = document.getElementById("alert-popup-box");
  const remaining = _alertPopupQueue.length - 1;
  document.getElementById("alert-popup-queue").textContent = remaining > 0 ? `และอีก ${remaining} รายการ` : "";

  if (item.type === "confluence") {
    const { sym, row } = item;
    const isUp = row.score > 0;
    box.className = isUp ? "up" : "down";
    document.getElementById("alert-popup-icon").textContent = isUp ? "🎯" : "⚠️";
    document.getElementById("alert-popup-sym").textContent = sym;
    document.getElementById("alert-popup-msg").innerHTML =
      `สัญญาณเงินทุนรวม <strong style="font-size:18px;color:${isUp ? "var(--green)" : "var(--red)"}">${row.score > 0 ? "+" : ""}${row.score}</strong>
       ${row.n_signals === 3 ? " ⭐ครบ 3 สัญญาณ" : ""}<br>
       <span style="font-size:12px;color:var(--text2)">Insider ${_dirIcon(row.insider?.dir)} · Short ${_dirIcon(row.short?.dir)} · NVDR ${_dirIcon(row.nvdr?.dir)}</span>`;
    document.getElementById("alert-popup-note").textContent = "หุ้นใน Watchlist — ดูรายละเอียดที่เมนู 🎯 สัญญาณรวม";
  } else {
    const { alert, price } = item;
    const condTh = alert.condition === "above" ? "≥" : "≤";
    const isUp = alert.condition === "above";
    box.className = isUp ? "up" : "down";
    document.getElementById("alert-popup-icon").textContent = isUp ? "🔼" : "🔽";
    const { curr, label: symLabel, dp } = _alertSymMeta(alert.symbol);
    document.getElementById("alert-popup-sym").textContent = symLabel;
    document.getElementById("alert-popup-msg").innerHTML =
      `ราคา <strong style="font-size:18px;color:${isUp ? "var(--green)" : "var(--red)"}">${price.toFixed(dp)}</strong> ${curr}<br>
       <span style="font-size:12px;color:var(--text2)">เป้าหมาย ${condTh} ${_fmtAlertPrice(alert.targetPrice, dp)} ${curr}</span>`;
    document.getElementById("alert-popup-note").textContent = alert.note || "";
  }
  document.getElementById("alert-popup").classList.add("open");
  // force re-animation
  box.style.animation = "none";
  requestAnimationFrame(() => { box.style.animation = ""; });
}

function dismissAlertPopup() {
  _alertPopupQueue.shift();
  document.getElementById("alert-popup").classList.remove("open");
  if (_alertPopupQueue.length > 0) {
    setTimeout(_showNextAlertPopup, 200);
  } else {
    _alertPopupShowing = false;
    renderWatchlist();
  }
}

function _showBrowserNotification(alert, price) {
  if (!("Notification" in window)) return;
  if (Notification.permission !== "granted") return;
  const condTh = alert.condition === "above" ? "≥" : "≤";
  const { curr, label: symLabel, dp } = _alertSymMeta(alert.symbol);
  new Notification(`🔔 ${symLabel} ถึงราคาเป้า!`, {
    body: `ราคา ${price.toFixed(dp)} ${curr} (เป้า ${condTh} ${_fmtAlertPrice(alert.targetPrice, dp)})${alert.note ? "\n" + alert.note : ""}`,
    icon: "/favicon.ico",
  });
}

function _requestNotificationPermission() {
  if ("Notification" in window && Notification.permission === "default") {
    Notification.requestPermission();
  }
}

/* ---------- WATCHLIST CONFLUENCE ALERT ----------
   แจ้งเตือนเมื่อหุ้นใน Watchlist ได้ score confluence ±3 (insider+short+NVDR
   ตรงกันหมด) — เช็คทุกครั้งที่ข้อมูลรีเฟรช/ทุก 5 นาทีเหมือน price alert
   จำ "ค่า score" ล่าสุดที่แจ้งไปแล้วต่อหุ้นไว้ใน localStorage กันแจ้งซ้ำ — เดิมจำ
   generated_at ของชุดข้อมูลแทน ทำให้ทุกครั้งที่ Quick Update/auto-update รันแล้ว
   invalidate cache /api/flow-signals (เกิดหลายรอบ/วัน) generated_at เปลี่ยนใหม่
   แต่ score หุ้นตัวเดิมไม่ได้เปลี่ยนเลย ก็ยังเด้ง popup ซ้ำทุกรอบ (พบจากผู้ใช้แจ้งว่า
   เตือนถี่เกินไป 2026-08-26) — เปลี่ยนมาเทียบค่า score ตรงๆ แจ้งใหม่เฉพาะตอน score
   เปลี่ยนค่าจริง หรือหลุดออกจากเกณฑ์ ±3 แล้วกลับเข้ามาใหม่ (นับเป็นสัญญาณใหม่) */
const CONFLUENCE_SEEN_KEY = "set_confluence_alert_seen";

function _loadConfluenceSeen() {
  try { return JSON.parse(localStorage.getItem(CONFLUENCE_SEEN_KEY) || "{}"); }
  catch { return {}; }
}
function _saveConfluenceSeen(obj) {
  localStorage.setItem(CONFLUENCE_SEEN_KEY, JSON.stringify(obj));
}

async function checkWatchlistConfluence() {
  if (!watchlist || !watchlist.length) return;
  const d = await loadFlowSignals();
  if (!d || !d.stocks) return;
  const seen = _loadConfluenceSeen();
  let changed = false;

  for (const rawSym of watchlist) {
    if (_isDRSym(rawSym) || _isUsSym(rawSym) || _isHkSym(rawSym)) continue;   // สัญญาณคำนวณเฉพาะหุ้นไทย SET ไม่ครอบคลุม DR/US/HK
    const row = d.stocks.find(r => r.symbol === rawSym);
    if (!row || Math.abs(row.score) < 3) {
      if (seen[rawSym] !== undefined) { delete seen[rawSym]; changed = true; }   // หลุดเกณฑ์แล้ว รอบหน้าถ้ากลับมาแตะ ±3 ใหม่ถือเป็นสัญญาณใหม่
      continue;
    }
    if (seen[rawSym] === row.score) continue;   // score เดิม ยังไม่ใช่สัญญาณใหม่ แค่ data รีเฟรชแต่ค่าไม่เปลี่ยน
    seen[rawSym] = row.score;
    changed = true;
    _alertPopupQueue.push({ type: "confluence", sym: rawSym, row });
  }

  if (changed) {
    _saveConfluenceSeen(seen);
    if (!_alertPopupShowing) _showNextAlertPopup();
  }
}

/* ---------- INIT & POLLING ---------- */
let _alertSystemInited = false;
function initAlertSystem() {
  _updateBellBadge();
  _requestNotificationPermission();
  // เช็คทันทีหลังโหลดข้อมูล (ทุกครั้งที่ data refresh)
  setTimeout(checkAlerts, 2000);
  setTimeout(checkWatchlistConfluence, 2500);
  // สร้าง interval เพียงครั้งเดียว
  if (!_alertSystemInited) {
    _alertSystemInited = true;
    setInterval(checkAlerts, 5 * 60 * 1000);
    setInterval(checkWatchlistConfluence, 5 * 60 * 1000);
  }
}

