// ============================================================
// NVDR RANKING (section ในหน้า Capital Flow)
// ============================================================
let _nvdrDeltaMode = 1;   // จำนวน snapshots ย้อนหลังที่ใช้คิด Δ (1 = ล่าสุด, 5, 20)

function _nvdrDeltaOf(v, n) {
  // คืน {dPct, dShr} จาก daily_tail โดยเทียบ snapshot ล่าสุดกับ n ครั้งก่อน
  // ต้องมีครบ n+1 snapshots — ไม่ครบคืน null (ไม่เดา ไม่ใช้ช่วงสั้นกว่าแทน)
  const t = v.daily_tail;
  if (!t || t.length < n + 1) return { dPct: null, dShr: null };
  const last = t[t.length - 1], base = t[t.length - 1 - n];
  return { dPct: (last[1] ?? 0) - (base[1] ?? 0),
           dShr: (last[2] ?? 0) - (base[2] ?? 0) };
}

function setNvdrDeltaMode(n, btn) {
  _nvdrDeltaMode = n;
  document.querySelectorAll('[id^="nvdr-d-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderNvdrRanking();
}

async function renderNvdrRanking() {
  const elHold = document.getElementById('nvdr-top-hold');
  const elIn   = document.getElementById('nvdr-top-in');
  const elOut  = document.getElementById('nvdr-top-out');
  if (!elHold) return;
  const d = await loadNvdrData();
  if (!d || !d.stocks) {
    elHold.innerHTML = '<tr><td style="color:var(--muted);padding:10px">ไม่มีข้อมูล NVDR</td></tr>';
    elIn.innerHTML = elOut.innerHTML = '';
    return;
  }

  const n = _nvdrDeltaMode;
  const rows = Object.entries(d.stocks).map(([sym, v]) => {
    const { dPct, dShr } = _nvdrDeltaOf(v, n);
    return { sym, pct: v.nvdr_pct ?? 0, shares: v.nvdr_shares ?? 0, dPct, dShr,
             snaps: v.daily_count ?? 0 };
  });

  const symTd = r =>
    `<td><strong class="sym-link" onclick="openChartModal('${r.sym}')">${r.sym}</strong>${tvLink(r.sym)}</td>`;
  const dHtml = r => {
    if (r.dPct == null) return '<span class="text2">—</span>';
    const c = r.dPct > 0 ? 'green' : r.dPct < 0 ? 'red' : 'text2';
    return `<span class="${c}">${r.dPct >= 0 ? '+' : ''}${r.dPct.toFixed(3)}%</span>`;
  };
  const shrHtml = v => v == null ? '' :
    `<span style="font-size:10px;color:var(--text2)">${v >= 0 ? '+' : ''}${(v/1e6).toFixed(1)}M</span>`;

  // 1) ถือครองสูงสุด
  elHold.innerHTML = [...rows].sort((a, b) => b.pct - a.pct).slice(0, 30).map((r, i) => `
    <tr><td class="r" style="color:var(--text2);width:22px">${i+1}</td>${symTd(r)}
        <td class="r" style="font-weight:700;color:${r.pct >= 20 ? '#5ab4ff' : r.pct >= 10 ? '#7090d0' : 'var(--text)'}">${r.pct.toFixed(2)}%</td>
        <td class="r">${dHtml(r)}</td></tr>`).join('');

  // 2)/3) เข้าเพิ่ม / ขายออก — เฉพาะตัวที่มี delta และขยับจริง (>0.005%)
  const withD = rows.filter(r => r.dPct != null && Math.abs(r.dPct) > 0.005);
  const mk = list => list.map((r, i) => `
    <tr><td class="r" style="color:var(--text2);width:22px">${i+1}</td>${symTd(r)}
        <td class="r">${dHtml(r)} ${shrHtml(r.dShr)}</td>
        <td class="r" style="color:var(--text2)">${r.pct.toFixed(2)}%</td></tr>`).join('');
  const inn = withD.filter(r => r.dPct > 0).sort((a, b) => b.dPct - a.dPct).slice(0, 30);
  const out = withD.filter(r => r.dPct < 0).sort((a, b) => a.dPct - b.dPct).slice(0, 30);
  const empty = `<tr><td style="color:var(--muted);padding:10px;font-size:11px">ยังไม่มีข้อมูลพอสำหรับ Δ ${n === 1 ? 'ล่าสุด' : n + ' วัน'} — ต้องมี snapshot อย่างน้อย ${n + 1} ครั้ง (เก็บเพิ่มทุกครั้งที่กด Quick Update วันทำการใหม่)</td></tr>`;
  elIn.innerHTML  = inn.length ? mk(inn) : empty;
  elOut.innerHTML = out.length ? mk(out) : empty;

  const st = document.getElementById('nvdr-rank-status');
  if (st) {
    const modeLbl = n === 1 ? 'Δ ล่าสุด' : `Δ สะสม ${n} snapshots`;
    st.textContent = `อัพเดท: ${d.updated_at || '—'}`;
    const nvdrStaleBadge = _staleTradeDateBadge(d.updated_at);
    if (nvdrStaleBadge) st.appendChild(nvdrStaleBadge);
    st.appendChild(document.createTextNode(` · ${modeLbl} · ${withD.length} หุ้นมีการเปลี่ยนแปลง`));
  }
}

function exportNvdrCSV() {
  // ข้อ 4: ดูครบทุกตัวไม่จำกัดอันดับ — export ทุกหุ้นพร้อม Δ ทุกช่วง
  if (!_nvdrData || !_nvdrData.stocks) { alert('ยังไม่ได้โหลดข้อมูล NVDR'); return; }
  const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const header = ['Symbol', 'NVDR %', 'NVDR Shares (M)',
                  'D1 %', 'D1 Shares (M)', 'D5 %', 'D5 Shares (M)',
                  'D20 %', 'D20 Shares (M)', 'Snapshots', 'Last Date'].map(esc).join(',');
  const lines = Object.entries(_nvdrData.stocks).map(([sym, v]) => {
    const d1 = _nvdrDeltaOf(v, 1), d5 = _nvdrDeltaOf(v, 5), d20 = _nvdrDeltaOf(v, 20);
    const t = v.daily_tail;
    const f = (x, dg = 4) => x == null ? '' : x.toFixed(dg);
    const m = x => x == null ? '' : (x / 1e6).toFixed(2);
    return [sym, (v.nvdr_pct ?? 0).toFixed(4), ((v.nvdr_shares ?? 0) / 1e6).toFixed(2),
            f(d1.dPct), m(d1.dShr), f(d5.dPct), m(d5.dShr), f(d20.dPct), m(d20.dShr),
            v.daily_count ?? 0, t && t.length ? t[t.length - 1][0] : ''].map(esc).join(',');
  });
  const csv = '﻿' + header + '\n' + lines.join('\n');
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })),
    download: `NVDR_${new Date().toISOString().slice(0, 10)}.csv`,
  });
  a.click(); URL.revokeObjectURL(a.href);
}

const _flowFetchInFlight = {};   // { set: Promise, s50: Promise, bond: Promise } — กันยิง fetch
// ซ้ำตอน loadFlowPage()/loadFlowSummaryCards() เรียก market เดียวกันเกือบพร้อมกันตอนเปิดหน้า
// (ตัวแรกยังไม่ resolve ตัวสอง cache ใน _flowDataByMarket จึงยังว่าง เห็นเป็น cache miss ทั้งคู่)

async function _fetchFlowMarket(market) {
  if (_flowDataByMarket[market]) return _flowDataByMarket[market];
  if (_flowFetchInFlight[market]) return _flowFetchInFlight[market];
  const cfg = FLOW_MARKETS[market];
  const p = (async () => {
    // endpoint นี้มี fallback ดึงสดจาก siamchart/SET API/TFEX/ThaiBMA เมื่อ cache
    // หมดอายุ (retry 3 ครั้ง x 20s ของ siamchart รวมแล้วอาจถึง ~70s) — ต้องมี
    // timeout กันหน้าค้าง "กำลังโหลด..." ไม่มีกำหนดเมื่อแหล่งต้นทางช้า/ล่ม
    const res = await _fetchTimeout(cfg.endpoint + '?t=' + Date.now(), 90000,
      `หมดเวลารอข้อมูล Capital Flow (${cfg.label}) — แหล่งข้อมูลต้นทางอาจช้าหรือล่มอยู่ ลองใหม่อีกครั้ง`);
    if (!res.ok) {
      // เดิม throw HTTP-status เฉยๆ ก่อนอ่าน body เลย ทำให้ error message ละเอียดที่ backend
      // ส่งมาจริง (เช่น "ไม่มีข้อมูล Capital Flow จากทุกแหล่ง") ไม่เคยไปถึงผู้ใช้ — ลองอ่าน
      // {error} จาก body ก่อน ถ้าอ่านไม่ได้ค่อย fallback เป็น HTTP status
      let msg = `โหลดข้อมูลไม่สำเร็จ (HTTP ${res.status})`;
      try {
        const errBody = await res.json();
        if (errBody && errBody.error) msg = errBody.error;
      } catch {}
      throw new Error(msg);
    }
    const d = await res.json();
    if (d.error) throw new Error(d.error);
    if (!d.rows) throw new Error('ข้อมูลที่ได้ไม่มี rows');
    _flowDataByMarket[market] = d;
    return d;
  })();
  _flowFetchInFlight[market] = p;
  try {
    return await p;
  } finally {
    delete _flowFetchInFlight[market];
  }
}

async function loadFlowPage() {
  // จำ market ที่ขอไว้ตอนเริ่มฟังก์ชัน — ถ้าผู้ใช้สลับตลาด (setFlowMarket) ก่อน fetch นี้จะ
  // เสร็จ ผลลัพธ์เก่านี้ต้องถูกทิ้ง ไม่งั้นสถานะ/แหล่งข้อมูลของตลาดเก่าจะไปทับของตลาดใหม่
  // ที่กำลังโชว์อยู่ (race condition: fetch ช้าของตลาดที่สลับออกไปแล้วเข้ามาทีหลัง)
  const requestedMarket = _flowMarket;
  renderNvdrRanking();   // section NVDR โหลดคู่ขนาน ไม่ block ตาราง flow
  loadFlowSummaryCards();
  const marketTipEl = document.getElementById('flow-market-tip');
  if (marketTipEl && !marketTipEl.innerHTML) marketTipEl.innerHTML = _tipIconHtml(FLOW_MARKETS[_flowMarket].tip);
  document.getElementById('flow-tbody').innerHTML =
    '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--muted)">กำลังโหลด...</td></tr>';
  try {
    const d = await _fetchFlowMarket(requestedMarket);
    if (_flowMarket !== requestedMarket) return;   // สลับตลาดไปแล้วระหว่างรอ — ทิ้งผลลัพธ์เก่า
    // โชว์ว่ารอบนี้ดึงข้อมูลใหม่ได้จากแหล่งไหนบ้าง (siamchart/tfex/thaibma ล่มบ่อย มี fallback
    // เป็น SET API หรือไฟล์สะสม) — เดิมมีข้อมูลนี้จาก backend อยู่แล้วแต่ UI ไม่โชว์เลย
    // ผู้ใช้จึงไม่รู้ว่ากำลังดูข้อมูล fallback/ไฟล์เก่าอยู่หรือเปล่า
    const srcLabel = { 'siamchart': 'siamchart.com', 'set.or.th': 'SET API', 'tfex.co.th': 'TFEX',
                       'thaibma.or.th': 'ThaiBMA' };
    const srcTxt = (d.sources || []).map(s => srcLabel[s] || s).join(', ');
    const srcHtml = srcTxt
      ? ` · แหล่ง: ${srcTxt}`
      : '';
    const flowStatusEl = document.getElementById('flow-status');
    flowStatusEl.textContent = 'อัพเดท: ' + (d.fetched_at || '') + srcHtml;
    // fetched_at เป็นเวลา "ตอนนี้" เสมอแม้ทุกแหล่งดึงสดจะล้มหมดและใช้ไฟล์สะสมเก่า — เช็คความ
    // ค้างจริงจาก latest_date (วันที่ของแถวข้อมูลล่าสุดจริง) แทน กันผู้ใช้เข้าใจผิดว่าข้อมูลสดใหม่
    const flowStaleBadge = _staleTradeDateBadge(d.latest_date);
    if (flowStaleBadge) flowStatusEl.appendChild(flowStaleBadge);
    renderFlowPage();
  } catch(e) {
    if (_flowMarket !== requestedMarket) return;   // สลับตลาดไปแล้วระหว่างรอ — ทิ้ง error เก่า
    document.getElementById('flow-tbody').innerHTML =
      `<tr><td colspan="6" style="padding:20px;color:var(--red)">โหลดไม่ได้: ${e.message}</td></tr>`;
  }
}

function setFlowMarket(market, btn) {
  _flowMarket = market;
  document.querySelectorAll('[id^="flow-m-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');

  const cfg = FLOW_MARKETS[market];
  document.getElementById('flow-th-fund').innerHTML    = cfg.thFund    ? `${cfg.thFund}<br><span style="font-size:10px;font-weight:400">(${cfg.unit})</span>` : '';
  document.getElementById('flow-th-foreign').innerHTML = cfg.thForeign ? `${cfg.thForeign}<br><span style="font-size:10px;font-weight:400">(${cfg.unit})</span>` : '';
  document.getElementById('flow-th-retail').innerHTML  = cfg.thRetail  ? `${cfg.thRetail}<br><span style="font-size:10px;font-weight:400">(${cfg.unit})</span>` : '';
  // Bond ไม่มีกองทุน+โบรก/รายย่อยแยก (มีแค่ต่างชาติ) — ซ่อนหัวคอลัมน์ทิ้งไปเลย เหมือนที่ทำกับ
  // SET/Chg ด้านล่าง กันคอลัมน์ว่างไม่มีชื่อค้างอยู่กลางตาราง
  document.getElementById('flow-th-fund').style.display   = cfg.thFund   ? '' : 'none';
  document.getElementById('flow-th-retail').style.display = cfg.thRetail ? '' : 'none';
  // S50/Bond ไม่มีดัชนี SET/Chg คู่กัน — ซ่อนหัวคอลัมน์ทิ้งไปเลย กันหัวลอยไม่มีข้อมูลใต้
  document.getElementById('flow-th-set').style.display = cfg.hasIndex ? '' : 'none';
  document.getElementById('flow-th-chg').style.display = cfg.hasIndex ? '' : 'none';
  document.getElementById('flow-source-note').textContent = cfg.source;
  document.getElementById('flow-market-tip').innerHTML = _tipIconHtml(cfg.tip);

  loadFlowPage();
}

function setFlowPeriod(m, btn) {
  _flowPeriod = m;
  document.querySelectorAll('[id^="flow-p-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderFlowPage();
}

function setFlowView(v, btn) {
  _flowView = v;
  document.querySelectorAll('[id^="flow-v-"]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderFlowPage();
}

// ตารางแรกๆ (NVDR) มี export CSV อยู่แล้ว — Capital Flow ไม่มี ทั้งที่ก็อปจากตาราง HTML
// ลำบาก (คอลัมน์เว้นไม่ตรงกันหลายเดือน) — export ตามช่วงเวลา (period) ที่เลือกอยู่ตอนนี้
function exportFlowCSV() {
  const d = _flowDataByMarket[_flowMarket];
  if (!d || !d.rows.length) { alert('ยังไม่ได้โหลดข้อมูล Capital Flow'); return; }
  const cutoff = new Date();
  // ตั้งวันที่เป็น 1 ก่อน setMonth() เสมอ — กัน rollover เดือนเมื่อวันที่ปัจจุบัน (เช่น 31)
  // เกินจำนวนวันของเดือนเป้าหมาย (เช่น ก.พ. 28 วัน) ซึ่ง JS จะปัดเลื่อนไปเดือนถัดไปเงียบๆ
  cutoff.setDate(1);
  cutoff.setMonth(cutoff.getMonth() - _flowPeriod);
  const cutStr = `${cutoff.getFullYear()}-${String(cutoff.getMonth() + 1).padStart(2, '0')}-${String(cutoff.getDate()).padStart(2, '0')}`;
  const rows = d.rows.filter(r => r.date >= cutStr).slice().sort((a, b) => a.date.localeCompare(b.date));
  const cfg = FLOW_MARKETS[_flowMarket];
  const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const header = ['Date', cfg.thFund, cfg.thForeign, cfg.thRetail, cfg.hasIndex ? 'SET' : null, cfg.hasIndex ? 'Chg' : null]
    .filter(Boolean).map(esc).join(',');
  const lines = rows.map(r => {
    const cells = [r.date];
    if (cfg.thFund)    cells.push(r.fund ?? '');
    if (cfg.thForeign) cells.push(r.foreign ?? '');
    if (cfg.thRetail)  cells.push(r.retail ?? '');
    if (cfg.hasIndex)  { cells.push(r.set ?? ''); cells.push(r.chg ?? ''); }
    return cells.map(esc).join(',');
  });
  const csv = '﻿' + header + '\n' + lines.join('\n');
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })),
    download: `CapitalFlow_${_flowMarket}_${new Date().toISOString().slice(0, 10)}.csv`,
  });
  a.click(); URL.revokeObjectURL(a.href);
}

function renderFlowPage() {
  const d = _flowDataByMarket[_flowMarket];
  if (!d) return;
  const cutoff = new Date();
  // ตั้งวันที่เป็น 1 ก่อน setMonth() เสมอ — กัน rollover เดือนเมื่อวันที่ปัจจุบัน (เช่น 31)
  // เกินจำนวนวันของเดือนเป้าหมาย (เช่น ก.พ. 28 วัน) ซึ่ง JS จะปัดเลื่อนไปเดือนถัดไปเงียบๆ
  cutoff.setDate(1);
  cutoff.setMonth(cutoff.getMonth() - _flowPeriod);
  // ใช้ local date components ไม่ใช่ toISOString() (แปลงเป็น UTC ก่อน) — ผู้ใช้ในโซนเวลา
  // ที่ UTC+ ล่วงหน้า (เช่น ไทย +7) จะได้ cutoff คลาดไป 1 วันตอนใกล้เที่ยงคืน
  const cutStr = `${cutoff.getFullYear()}-${String(cutoff.getMonth() + 1).padStart(2, '0')}-${String(cutoff.getDate()).padStart(2, '0')}`;
  // sort ตามวันที่ตรงๆ ไม่พึ่งลำดับจาก API (เดิม .reverse() เดาว่า API ส่ง
  // oldest-first แต่จริงๆ ส่ง newest-first มา ทำให้ตาราง/กราฟกลับหัว)
  const rows = d.rows.filter(r => r.date >= cutStr)
    .slice().sort((a, b) => b.date.localeCompare(a.date));   // newest first สำหรับตาราง

  const cfg = FLOW_MARKETS[_flowMarket];
  _renderFlowTable(rows, cfg);
  _renderFlowChart(rows.slice().reverse(), cfg); // oldest first สำหรับกราฟ
}

function _renderFlowTable(rows, cfg) {
  const fmt = v => {
    if (v == null) return '<span style="color:var(--muted)">—</span>';
    const col = v > 0 ? 'var(--green)' : v < 0 ? 'var(--red)' : 'var(--text2)';
    return `<span style="color:${col}">${v > 0 ? '+' : ''}${v.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2})}</span>`;
  };
  const fmtSet = v => v != null ? v.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2}) : '—';

  // Total row
  const totFund    = cfg.thFund    ? rows.reduce((s, r) => s + (r.fund    || 0), 0) : null;
  const totForeign = cfg.thForeign ? rows.reduce((s, r) => s + (r.foreign || 0), 0) : null;
  const totRetail  = cfg.thRetail  ? rows.reduce((s, r) => s + (r.retail  || 0), 0) : null;

  const totalRow = `<tr style="background:var(--bg3);font-weight:700;position:sticky;top:41px;z-index:1">
    <td style="padding:6px 10px">ยอดรวม</td>
    <td style="padding:6px 10px;text-align:right">${totFund    != null ? fmt(Math.round(totFund))    : ''}</td>
    <td style="padding:6px 10px;text-align:right">${totForeign != null ? fmt(Math.round(totForeign)) : ''}</td>
    <td style="padding:6px 10px;text-align:right">${totRetail  != null ? fmt(Math.round(totRetail))  : ''}</td>
    <td style="padding:6px 10px;text-align:right"></td>
    <td style="padding:6px 10px;text-align:right"></td>
  </tr>`;

  const dataRows = rows.map(r => {
    const chgHtml = r.chg != null
      ? `<span style="color:${r.chg > 0 ? 'var(--green)' : r.chg < 0 ? 'var(--red)' : 'var(--text2)'}">
           ${r.chg > 0 ? '+' : ''}${r.chg.toFixed(2)}</span>`
      : '—';
    return `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:5px 10px;white-space:nowrap;color:var(--text2)">${r.date.slice(2)}</td>
      <td style="padding:5px 10px;text-align:right">${cfg.thFund    ? fmt(r.fund)    : ''}</td>
      <td style="padding:5px 10px;text-align:right">${cfg.thForeign ? fmt(r.foreign) : ''}</td>
      <td style="padding:5px 10px;text-align:right">${cfg.thRetail  ? fmt(r.retail)  : ''}</td>
      <td style="padding:5px 10px;text-align:right;color:var(--fg)">${cfg.hasIndex ? fmtSet(r.set) : ''}</td>
      <td style="padding:5px 10px;text-align:right">${cfg.hasIndex ? chgHtml : ''}</td>
    </tr>`;
  }).join('');

  document.getElementById('flow-tbody').innerHTML = totalRow + dataRows;
}

function _renderFlowChart(rows, cfg, canvasId) {  // rows = oldest first
  const cv = document.getElementById(canvasId || 'flow-chart');
  if (!cv || !rows.length) return;
  const dpr = window.devicePixelRatio || 1;
  const W = cv.offsetWidth || 800, H = canvasId ? (cv.offsetHeight || 70) : 180;
  cv.width = W * dpr; cv.height = H * dpr;
  cv.style.width = W + 'px'; cv.style.height = H + 'px';
  const ctx = cv.getContext('2d');
  ctx.scale(dpr, dpr);

  const mini = !!canvasId;
  const PAD = mini ? { t: 4, b: 4, l: 4, r: 4 } : { t: 10, b: 30, l: 50, r: 10 };
  const PW = W - PAD.l - PAD.r;
  const PH = H - PAD.t - PAD.b;
  const view = mini ? 'cum' : _flowView;   // การ์ดสรุปเป็นสะสม 20 วันเสมอ ไม่ผูกกับปุ่ม Net/Cumulative ของกราฟหลัก

  // Compute series (เฉพาะ key ที่ market นี้มี — cfg.keys)
  const cum = {};
  cfg.keys.forEach(k => cum[k] = 0);
  const series = rows.map(r => {
    const out = { date: r.date, set: r.set };
    cfg.keys.forEach(k => {
      if (view === 'cum') { cum[k] += (r[k] || 0); out[k] = cum[k]; }
      else out[k] = r[k] || 0;
    });
    return out;
  });

  const allVals = series.flatMap(r => cfg.keys.map(k => r[k]));
  const minV = Math.min(...allVals, 0);
  const maxV = Math.max(...allVals, 0);
  const range = maxV - minV || 1;

  const toX = i => PAD.l + (i / (series.length - 1 || 1)) * PW;
  const toY = v => PAD.t + PH - ((v - minV) / range) * PH;

  ctx.clearRect(0, 0, W, H);

  // Zero line
  const zeroY = toY(0);
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
  ctx.beginPath(); ctx.moveTo(PAD.l, zeroY); ctx.lineTo(W - PAD.r, zeroY); ctx.stroke();
  ctx.setLineDash([]);

  // Draw lines
  cfg.legend.forEach(({ key, color }) => {
    ctx.beginPath();
    ctx.strokeStyle = color; ctx.lineWidth = mini ? 1.3 : 1.5;
    series.forEach((r, i) => {
      const x = toX(i), y = toY(r[key]);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.stroke();
  });

  if (mini) return;   // sparkline card: ไม่ต้องมีแกน/label/legend ในตัวกราฟ (ไม่ต้องมี tooltip ด้วย)

  // เก็บ state ล่าสุดไว้ให้ tooltip ใช้ (canvas element เดิมถูก redraw ซ้ำทุกครั้งที่เปลี่ยน
  // ตลาด/ช่วง/มุมมอง — เก็บบน element เอง กัน closure เก่าค้าง)
  cv._flowTip = { series, cfg, toX, PAD, PW, W };
  _bindFlowChartTooltip(cv);

  // SET index on right axis
  if (cfg.hasIndex) {
    const setVals = series.map(r => r.set).filter(v => v != null);
    if (setVals.length > 1) {
      const minS = Math.min(...setVals), maxS = Math.max(...setVals);
      const rangeS = maxS - minS || 1;
      const toYS = v => PAD.t + PH - ((v - minS) / rangeS) * PH;
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(200,200,220,0.6)'; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
      series.forEach((r, i) => {
        if (r.set == null) return;
        const x = toX(i), y = toYS(r.set);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      });
      ctx.stroke(); ctx.setLineDash([]);
    }
  }

  // X-axis labels (show ~6 dates)
  ctx.font = '10px sans-serif'; ctx.textAlign = 'center';
  const step = Math.max(1, Math.floor(series.length / 6));
  for (let i = 0; i < series.length; i += step) {
    ctx.fillStyle = '#8b949e';
    ctx.fillText(series[i].date.slice(2), toX(i), H - PAD.b + 14);
  }

  // Y-axis label — format ตามขนาดค่าจริง ไม่ใช่หาร 1000 (=K) ตายตัว เพราะ S50 (หน่วยสัญญา)
  // ช่วงข้อมูลยังสั้น ค่าสะสมน้อย จะเห็น "0K" ทั้งบนล่างถ้าหารพันเสมอ
  const fmtAxis = v => {
    const abs = Math.abs(v);
    if (abs >= 1e6) return (v / 1e6).toFixed(1) + 'M';
    if (abs >= 1e3) return (v / 1e3).toFixed(abs >= 1e4 ? 0 : 1) + 'K';
    return Math.round(v).toString();
  };
  ctx.textAlign = 'right'; ctx.fillStyle = '#8b949e';
  ctx.fillText(fmtAxis(maxV), PAD.l - 4, PAD.t + 10);
  ctx.fillText(fmtAxis(minV), PAD.l - 4, PAD.t + PH);

  // Legend
  const leg = cfg.legend.slice();
  if (cfg.hasIndex) leg.push({ label: 'SET', color: 'rgba(200,200,220,0.7)' });
  ctx.textAlign = 'left'; ctx.font = '10px sans-serif';
  let lx = PAD.l;
  leg.forEach(({ label, color }) => {
    ctx.fillStyle = color;
    ctx.fillRect(lx, PAD.t - 2, 10, 8);
    ctx.fillStyle = '#8b949e';
    ctx.fillText(label, lx + 13, PAD.t + 6);
    lx += ctx.measureText(label).width + 30;
  });
}

// Tooltip บนกราฟหลักของ Capital Flow — ชี้เมาส์ดูค่าของวันนั้นได้เลยไม่ต้องเลื่อนลงไปดูตาราง
// bind แค่ครั้งเดียวต่อ canvas element (ผูก flag ไว้กับ element เอง กัน listener ซ้อนตอน
// _renderFlowChart ถูกเรียกซ้ำทุกครั้งที่เปลี่ยนตลาด/ช่วง/มุมมอง) อ่าน state ล่าสุดจาก cv._flowTip
function _bindFlowChartTooltip(cv) {
  if (cv._flowTipBound) return;
  cv._flowTipBound = true;
  let tip = document.getElementById('flow-chart-tip');
  if (!tip) {
    tip = document.createElement('div');
    tip.id = 'flow-chart-tip';
    tip.style.cssText = 'position:fixed;pointer-events:none;z-index:9999;display:none;'
      + 'background:var(--card2);border:1px solid var(--border);border-radius:6px;'
      + 'padding:8px 10px;font-size:11px;line-height:1.6;box-shadow:0 4px 12px rgba(0,0,0,.3);'
      + 'white-space:nowrap;color:var(--text)';
    document.body.appendChild(tip);
  }
  const fmt = v => v == null ? '—' : (v > 0 ? '+' : '') + Math.round(v).toLocaleString();
  cv.addEventListener('mousemove', (e) => {
    const t = cv._flowTip;
    if (!t) return;
    const rect = cv.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const { series, cfg, toX } = t;
    let idx = 0, best = Infinity;
    series.forEach((r, i) => {
      const d = Math.abs(toX(i) - x);
      if (d < best) { best = d; idx = i; }
    });
    const r = series[idx];
    const rows = cfg.legend.map(({ key, label, color }) =>
      `<div style="display:flex;justify-content:space-between;gap:10px"><span style="color:${color}">${label}</span><b>${fmt(r[key])}</b></div>`
    ).join('');
    const setRow = cfg.hasIndex && r.set != null
      ? `<div style="display:flex;justify-content:space-between;gap:10px;color:var(--text2)"><span>SET</span><b>${r.set.toFixed(2)}</b></div>`
      : '';
    tip.innerHTML = `<div style="font-weight:600;margin-bottom:3px">${r.date}</div>${rows}${setRow}`;
    tip.style.display = 'block';
    const tw = tip.offsetWidth || 120;
    const left = (e.clientX + tw + 20 > window.innerWidth) ? e.clientX - tw - 14 : e.clientX + 14;
    tip.style.left = left + 'px';
    tip.style.top = (e.clientY + 14) + 'px';
  });
  cv.addEventListener('mouseleave', () => { tip.style.display = 'none'; });
}

// ── Summary cards (SET / S50 Futures / Thai Bond) — สะสม 20 วันล่าสุด + sparkline ──
async function loadFlowSummaryCards() {
  const ids = { set: 'fsum-set', s50: 'fsum-s50', bond: 'fsum-bond' };
  Object.entries(ids).forEach(async ([market, prefix]) => {
    const cfg = FLOW_MARKETS[market];
    const tipEl = document.getElementById(`${prefix}-tip`);
    if (tipEl && !tipEl.innerHTML) tipEl.innerHTML = _tipIconHtml(cfg.tip);
    try {
      const d = await _fetchFlowMarket(market);
      const rows = d.rows.slice().sort((a, b) => a.date.localeCompare(b.date)).slice(-20);
      if (!rows.length) return;

      document.getElementById(`${prefix}-date`).textContent = rows[rows.length - 1].date;

      const legendEl = document.getElementById(`${prefix}-legend`);
      legendEl.innerHTML = cfg.legend.map(({ key, label, color }) => {
        const tot = rows.reduce((s, r) => s + (r[key] || 0), 0);
        const col = tot > 0 ? 'var(--green)' : tot < 0 ? 'var(--red)' : 'var(--text2)';
        return `<span><span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:${color};margin-right:4px"></span>${label}
                <b style="color:${col}">${tot > 0 ? '+' : ''}${Math.round(tot).toLocaleString()}</b></span>`;
      }).join('');

      _renderFlowChart(rows, cfg, `${prefix}-spark`);
    } catch (e) {
      const legendEl = document.getElementById(`${prefix}-legend`);
      if (legendEl) legendEl.innerHTML = `<span style="color:var(--red)">โหลดไม่ได้: ${e.message}</span>`;
    }
  });
}

// ============================================================
// FILINGS — 📑 รายงานทางการ: ลิงก์เอกสารต้นทางรายหุ้น (ไทย/US/HK)
// ไม่มี backend — ทุกลิงก์ build จาก ticker ฝั่ง JS ล้วนๆ
// US ใช้ EDGAR browse-edgar ซึ่งรับ ticker ในช่อง CIK ได้เลย (ไม่ต้อง map CIK)
// ============================================================
let _filTab = 'TH';                       // TH | US | HK
const FIL_RECENT_KEY = 'fil_recent_v1';

function initFilingsPage() {
  initFinPage();          // ให้ fin-set-datalist / fin-dr-datalist ถูก populate ก่อน แล้วค่อยโคลนมาใช้
  _filBuildDatalist();
  _filRecentRender();
}

// TH โคลนจาก fin-set-datalist ได้ตรงๆ แต่ US/HK ต้องสร้างเองจาก _finDrMirrorSyms ซึ่งแยก
// ตลาดไว้ชัดเจน ({US:['A',...], HK:['0001',...], JP:[...]}) — เดิมโคลน fin-dr-datalist แล้ว
// แยกตลาดด้วย suffix ".HK" ซึ่งไม่มีอยู่จริงในข้อมูล (mirror เก็บ HK เป็นรหัส 4 หลักเปล่าๆ)
// ผลคือแท็บ HK ได้ 0 ตัวเลือก ส่วนแท็บ US มีรหัส HK/JP ปนมาทั้งหมด (รีวิว 2026-08-02)
function _filBuildDatalist() {
  const dl = document.getElementById('fil-datalist');
  if (!dl) return;

  if (_filTab === 'TH') {
    const src = document.getElementById('fin-set-datalist');
    if (!src || !src.childElementCount) return;
    const key = 'TH:' + src.childElementCount;
    if (dl.dataset.key === key) return;
    dl.innerHTML = '';
    const frag = document.createDocumentFragment();
    [...src.children].forEach(o => frag.appendChild(o.cloneNode(true)));
    dl.appendChild(frag);
    dl.dataset.key = key;
    return;
  }

  const mir = (typeof _finDrMirrorSyms === 'object' && _finDrMirrorSyms) ? _finDrMirrorSyms : {};
  // HK: รหัสตัวเลขจาก mirror → เติม .HK ให้พร้อมใช้ทันที (_filLinksHK ต้องการตัวเลข ถ้าเจอ
  // ตัวอักษรล้วนอย่าง "BABA" จะได้ code เป็น NaN — ดู guard ใน searchFilings)
  // US: ticker จาก mirror + underlying ของ DR ที่ region=US (BRK.B ฯลฯ ที่ไม่อยู่ใน mirror)
  let syms;
  if (_filTab === 'HK') {
    syms = (mir.HK || []).map(s => [String(s).padStart(4, '0') + '.HK', _finMirName('HK', s)]);
  } else {
    const drUs = (typeof _drData !== 'undefined' && _drData ? _drData : [])
      .filter(s => s.region === 'US' && s.sym).map(s => [s.sym, s.name]);
    const seen = new Set(drUs.map(([s]) => s));
    syms = drUs.concat((mir.US || []).filter(s => !seen.has(s)).map(s => [s, _finMirName('US', s)]));
  }
  // key รวมจำนวนชื่อบริษัทที่โหลดมาแล้วด้วย — /api/mirror-names มาเป็น request แยกทีหลัง
  // ตอน syms.length ยังเท่าเดิม ถ้า key เป็น count อย่างเดียว guard จะ return ก่อน ทำให้
  // ป้ายชื่อบริษัทไม่เคยถูกเติมลง datalist (autocomplete โชว์แต่ ticker เปล่า)
  const nameCnt = (_finMirNames && _finMirNames[_filTab]) ? Object.keys(_finMirNames[_filTab]).length : 0;
  const key = _filTab + ':' + syms.length + ':' + nameCnt;
  if (!syms.length || dl.dataset.key === key) return;
  dl.innerHTML = '';
  const frag = document.createDocumentFragment();
  syms.forEach(([sym, name]) => {
    const o = document.createElement('option');
    o.value = sym;
    if (name) o.label = name;
    frag.appendChild(o);
  });
  dl.appendChild(frag);
  dl.dataset.key = key;
}

function setFilTab(tab, btn) {
  _filTab = tab;
  document.querySelectorAll('#fil-tab-th,#fil-tab-us,#fil-tab-hk').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const inp = document.getElementById('fil-sym');
  if (inp) inp.placeholder = tab === 'TH' ? 'เช่น PTT, AOT, CPALL' : tab === 'US' ? 'เช่น NVDA, AAPL, MSFT' : 'เช่น 0700.HK, 9988.HK';
  // คนละ tab = คนละตลาด — ล้างผลของหุ้นตัวก่อนไม่ให้ลิงก์ผิดตลาดค้างจอ (แบบเดียวกับ setNewsTab/setFinTab)
  const out = document.getElementById('fil-result');
  if (out) out.innerHTML = '';
  const hint = document.getElementById('fil-hint');
  if (hint) hint.textContent = '';
  _filBuildDatalist();
}

// ---------- ชิป "เพิ่งดู" (localStorage แบบเดียวกับหน้าข่าว) ----------
function _filRecentRender() {
  const box = document.getElementById('fil-recent');
  if (!box) return;
  let list = [];
  try { list = JSON.parse(localStorage.getItem(FIL_RECENT_KEY)); } catch {}
  if (!Array.isArray(list)) list = [];
  if (!list.length) { box.style.display = 'none'; return; }
  box.style.display = 'flex';
  box.style.flexWrap = 'wrap';
  box.style.gap = '6px';
  box.style.alignItems = 'center';
  const flag = { TH: '🇹🇭', US: '🇺🇸', HK: '🇭🇰' };
  // sym มาจาก localStorage — กรองเป็น [A-Z0-9.-] ก่อนยัดลง onclick (กันอักขระพิเศษแตก HTML)
  const safe = s => String(s || '').replace(/[^A-Z0-9.\-]/gi, '');
  box.innerHTML = '<span style="color:var(--text2)">🕓 เพิ่งดู:</span>' +
    list.filter(r => r && safe(r.sym) && ['TH', 'US', 'HK'].includes(r.tab))
      .map(r => `<button class="filter-btn" style="font-size:11px;padding:3px 10px"
      onclick="_filRecentPick('${safe(r.sym)}','${r.tab}')">${flag[r.tab]} ${safe(r.sym)}</button>`).join('');
}

function _filRecentAdd(sym, tab) {
  let list = [];
  try { list = JSON.parse(localStorage.getItem(FIL_RECENT_KEY)); } catch {}
  if (!Array.isArray(list)) list = [];
  list = [{ sym, tab }, ...list.filter(r => r && !(r.sym === sym && r.tab === tab))].slice(0, 10);
  try { localStorage.setItem(FIL_RECENT_KEY, JSON.stringify(list)); } catch {}
  _filRecentRender();
}

function _filRecentPick(sym, tab) {
  if (_filTab !== tab) setFilTab(tab, document.getElementById('fil-tab-' + tab.toLowerCase()));
  document.getElementById('fil-sym').value = sym;
  searchFilings();
}

// ---------- ตัว build ลิงก์ต่อตลาด ----------
// คืน [{group, links:[{label, url, tip}]}]
function toggleFilGuide() {
  const box = document.getElementById('fil-guide-box');
  const btn = document.getElementById('fil-guide-btn');
  if (!box || !btn) return;
  const open = box.style.display === 'none';
  box.style.display = open ? '' : 'none';
  btn.style.background = open ? '#1f6feb44' : '#1f6feb22';
}

